/**
 * CLOUDINARY MIGRATION SCRIPT (v4 - Concurrency Optimized)
 * ------------------------------------------------------
 * Uploads assets from 'cloudinary_backup/' to a NEW Cloudinary account.
 * Uses parallel processing for significantly faster migration.
 */

// --- CONFIGURATION ---
const CONCURRENCY_LIMIT = 10; // Number of parallel uploads
const SKIP_EXISTENCE_CHECK = false; 
// ---------------------

if (!process.env.CLOUDINARY_CLOUD_NAME || !process.env.CLOUDINARY_API_KEY || !process.env.CLOUDINARY_API_SECRET) {
  console.error("❌ Error: Cloudinary credentials missing in .env.local");
  process.exit(1);
}

cloudinary.config({
  cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
  api_key: process.env.CLOUDINARY_API_KEY,
  api_secret: process.env.CLOUDINARY_API_SECRET,
  secure: true,
});

const BACKUP_DIR = path.join(__dirname, 'cloudinary_backup');

/**
 * Throttler helper to limit concurrency
 */
async function throttledAll(limit, tasks) {
  const results = [];
  const executing = [];
  for (const task of tasks) {
    const p = Promise.resolve().then(() => task());
    results.push(p);
    if (limit <= tasks.length) {
      const e = p.then(() => executing.splice(executing.indexOf(e), 1));
      executing.push(e);
      if (executing.length >= limit) {
        await Promise.race(executing);
      }
    }
  }
  return Promise.all(results);
}

function getAllFiles(dirPath, arrayOfFiles) {
  if (!fs.existsSync(dirPath)) return [];
  const files = fs.readdirSync(dirPath);
  arrayOfFiles = arrayOfFiles || [];
  files.forEach(function(file) {
    const fullPath = path.join(dirPath, file);
    if (fs.statSync(fullPath).isDirectory()) {
      arrayOfFiles = getAllFiles(fullPath, arrayOfFiles);
    } else {
      arrayOfFiles.push(fullPath);
    }
  });
  return arrayOfFiles;
}

async function migrate() {
  const startTime = Date.now();
  const allFiles = getAllFiles(BACKUP_DIR);
  console.info(`🚀 INITIALIZING FAST MIGRATION: ${allFiles.length} files in queue.`);
  console.info(`🎯 Target Cloud: ${process.env.CLOUDINARY_CLOUD_NAME}`);
  console.info(`⚡ Concurrency: ${CONCURRENCY_LIMIT}\n`);

  let stats = { uploaded: 0, skipped: 0, errors: 0 };

  const tasks = allFiles.map(filePath => async () => {
    const relativePath = path.relative(BACKUP_DIR, filePath).replace(/\/g, '/');
    const ext = path.extname(relativePath);
    const publicId = relativePath.slice(0, -ext.length);
    
    let resourceType = 'image';
    const lowExt = ext.toLowerCase();
    if (['.mp3', '.wav', '.ogg', '.mp4', '.webm', '.mov', '.m4a'].includes(lowExt)) {
      resourceType = 'video';
    } else if (['.pdf', '.docx', '.xlsx', '.csv', '.txt'].includes(lowExt)) {
      resourceType = 'raw';
    }

    try {
      if (!SKIP_EXISTENCE_CHECK) {
        try {
          await cloudinary.api.resource(publicId, { resource_type: resourceType });
          console.info(`⏩ Skipping: ${publicId} (Exists)`);
          stats.skipped++;
          return;
        } catch (e) {
          const code = e.http_code || e.error?.http_code;
          const isNotFound = code === 404 || (e.message && e.message.includes('not found'));
          if (!isNotFound) {
            throw new Error(`Check Failed: ${e.message || "Unknown"}`);
          }
        }
      }

      console.info(`📤 Uploading: ${publicId}${ext} ...`);
      const options = {
        public_id: publicId,
        resource_type: resourceType,
        overwrite: true,
        invalidate: true
      };
      if (resourceType === 'raw') options.use_filename = true;

      await cloudinary.uploader.upload(filePath, options);
      stats.uploaded++;
      
    } catch (err) {
      console.error(`❌ Failed: ${publicId} -> ${err.message || "Unknown"}`);
      stats.errors++;
    }
  });

  await throttledAll(CONCURRENCY_LIMIT, tasks);

  const duration = ((Date.now() - startTime) / 1000).toFixed(1);

  console.info(`\n===========================`);
  console.info(`✨ MIGRATION COMPLETE`);
  console.info(`✅ Newly Uploaded:  ${stats.uploaded}`);
  console.info(`⏩ Already Present: ${stats.skipped}`);
  console.info(`❌ Errors:          ${stats.errors}`);
  console.info(`📦 Total Processed: ${stats.uploaded + stats.skipped + stats.errors}`);
  console.info(`⏱️ Duration:       ${duration}s`);
  console.info(`===========================`);
}

migrate();

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import toast from 'react-hot-toast';

export default function AuditLogsPage() {
  const [logs, setLogs] = useState([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [offset, setOffset] = useState(0);
  const [limit] = useState(50);
  const [filters, setFilters] = useState({
    action: '',
    userType: '',
    targetId: ''
  });
  const [expandedLog, setExpandedLog] = useState(null);

  const fetchLogs = useCallback(async () => {
    setLoading(true);
    try {
      const queryParams = new URLSearchParams({
        limit: String(limit),
        offset: String(offset),
        ...Object.fromEntries(Object.entries(filters).filter(([, v]) => v !== ''))
      });

      const res = await fetch(`/api/admin/audit-logs?${queryParams}`);
      if (!res.ok) throw new Error('Failed to fetch audit logs');
      const data = await res.json();
      setLogs(data.logs);
      setTotal(data.total);
    } catch (error) {
      console.error(error);
      toast.error('Could not load audit logs');
    } finally {
      setLoading(false);
    }
  }, [limit, offset, filters]);

  useEffect(() => {
    const id = setTimeout(() => {
      fetchLogs();
    }, 0);
    return () => clearTimeout(id);
  }, [fetchLogs]);

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
    setOffset(0); // Reset to first page on filter change
  };

  const formatPayload = (payload) => {
    if (!payload) return 'N/A';
    try {
      const parsed = typeof payload === 'string' ? JSON.parse(payload) : payload;
      return JSON.stringify(parsed, null, 2);
    } catch (e) {
      return String(payload);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-200 pb-6">
        <div>
          <h1 className="text-2xl font-black text-[#0b3578] tracking-tight">AUDIT TRAILS</h1>
          <p className="text-slate-500 text-sm font-medium">Monitor system activities and data modifications</p>
        </div>
        <div className="text-right">
          <div className="text-2xl font-bold text-slate-900">{total.toLocaleString()}</div>
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-wider text-right">Total Logs</p>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 border border-slate-200 shadow-sm space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black text-slate-400 uppercase">Action</label>
            <input
              type="text"
              name="action"
              value={filters.action}
              onChange={handleFilterChange}
              placeholder="e.g. UPDATE_MARKS"
              className="w-full px-3 py-2 border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#0b3578]/20 transition-all"
            />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black text-slate-400 uppercase">User Type</label>
            <select
              name="userType"
              value={filters.userType}
              onChange={handleFilterChange}
              className="w-full px-3 py-2 border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#0b3578]/20 transition-all"
            >
              <option value="">All Types</option>
              <option value="admin">Admin</option>
              <option value="clerk">Clerk</option>
              <option value="student">Student</option>
              <option value="system">System</option>
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black text-slate-400 uppercase">Target ID</label>
            <input
              type="text"
              name="targetId"
              value={filters.targetId}
              onChange={handleFilterChange}
              placeholder="Search by Target ID"
              className="w-full px-3 py-2 border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#0b3578]/20 transition-all"
            />
          </div>
          <div className="flex items-end">
            <button 
              onClick={() => {
                setFilters({ action: '', userType: '', targetId: '' });
                setOffset(0);
              }}
              className="w-full px-4 py-2 text-xs font-bold text-slate-500 hover:text-slate-700 bg-slate-50 hover:bg-slate-100 border border-slate-200 transition-all uppercase tracking-wider"
            >
              Clear Filters
            </button>
          </div>
        </div>
      </div>

      {/* Logs Table */}
      <div className="bg-white border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-4 py-3 text-[10px] font-black text-slate-400 uppercase tracking-wider w-40">Timestamp</th>
                <th className="px-4 py-3 text-[10px] font-black text-slate-400 uppercase tracking-wider w-32">User Type</th>
                <th className="px-4 py-3 text-[10px] font-black text-slate-400 uppercase tracking-wider w-48">Action</th>
                <th className="px-4 py-3 text-[10px] font-black text-slate-400 uppercase tracking-wider">Target</th>
                <th className="px-4 py-3 text-[10px] font-black text-slate-400 uppercase tracking-wider w-32 text-right">Details</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan="5" className="px-4 py-12 text-center text-slate-400 italic text-sm">
                    Loading audit trails...
                  </td>
                </tr>
              ) : logs.length === 0 ? (
                <tr>
                  <td colSpan="5" className="px-4 py-12 text-center text-slate-400 italic text-sm">
                    No audit logs found matching your criteria.
                  </td>
                </tr>
              ) : (
                logs.map((log) => (
                  <React.Fragment key={log.id}>
                    <tr className={`hover:bg-slate-50 transition-colors ${expandedLog === log.id ? 'bg-slate-50' : ''}`}>
                      <td className="px-4 py-3 text-xs font-medium text-slate-600 whitespace-nowrap">
                        {new Date(log.created_at).toLocaleString()}
                      </td>
                      <td className="px-4 py-3">
                        <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider ${
                          log.user_type === 'admin' ? 'bg-purple-100 text-purple-700' :
                          log.user_type === 'clerk' ? 'bg-blue-100 text-blue-700' :
                          log.user_type === 'student' ? 'bg-emerald-100 text-emerald-700' :
                          'bg-slate-100 text-slate-700'
                        }`}>
                          {log.user_type}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <span className="text-xs font-bold text-slate-900 font-mono">
                          {log.action}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex flex-col">
                          <span className="text-xs text-slate-600 font-medium">
                            {log.target_type || 'N/A'}: <span className="text-slate-900 font-bold">{log.target_id || 'N/A'}</span>
                          </span>
                          <span className="text-[10px] text-slate-400 font-medium italic">
                            IP: {log.ip_address}
                          </span>
                        </div>
                      </td>
                      <td className="px-4 py-3 text-right">
                        <button 
                          onClick={() => setExpandedLog(expandedLog === log.id ? null : log.id)}
                          className="text-[#0b3578] hover:underline text-[10px] font-bold uppercase tracking-widest"
                        >
                          {expandedLog === log.id ? 'Hide' : 'View Data'}
                        </button>
                      </td>
                    </tr>
                    {expandedLog === log.id && (
                      <tr className="bg-slate-50">
                        <td colSpan="5" className="px-4 py-4 border-t border-slate-200">
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="space-y-2">
                              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Before Change</h4>
                              <pre className="p-3 bg-white border border-slate-200 rounded text-[10px] font-mono overflow-auto max-h-60 text-slate-600">
                                {formatPayload(log.payload_before)}
                              </pre>
                            </div>
                            <div className="space-y-2">
                              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-wider text-[#0b3578]">After Change</h4>
                              <pre className="p-3 bg-white border border-slate-200 rounded text-[10px] font-mono overflow-auto max-h-60 text-slate-900 font-bold">
                                {formatPayload(log.payload_after)}
                              </pre>
                            </div>
                          </div>
                          <div className="mt-4 pt-4 border-t border-slate-200/50">
                            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-wider">User Agent</h4>
                            <p className="text-[10px] text-slate-500 italic mt-1">{log.user_agent}</p>
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="px-4 py-3 bg-slate-50 border-t border-slate-200 flex items-center justify-between">
          <div className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">
            Showing {offset + 1} to {Math.min(offset + limit, total)} of {total}
          </div>
          <div className="flex gap-2">
            <button 
              disabled={offset === 0}
              onClick={() => setOffset(Math.max(0, offset - limit))}
              className="px-3 py-1 text-[10px] font-black uppercase tracking-widest border border-slate-200 bg-white hover:bg-slate-50 disabled:opacity-50 disabled:hover:bg-white transition-all rounded shadow-xs"
            >
              Prev
            </button>
            <button 
              disabled={offset + limit >= total}
              onClick={() => setOffset(offset + limit)}
              className="px-3 py-1 text-[10px] font-black uppercase tracking-widest border border-slate-200 bg-white hover:bg-slate-50 disabled:opacity-50 disabled:hover:bg-white transition-all rounded shadow-xs"
            >
              Next
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import StudentProfileCard from '@/components/StudentProfileCard';
import { useRef, useEffect, useState } from 'react';
import { useAdmin } from '@/context/AdminContext';
import CollegeInfoEditor from '@/components/admin/CollegeInfoEditor';
import { validateRollNo } from '@/lib/rollNumber';
import { COLLEGE_CONFIG } from '@/lib/college-config';
import FacultyInterestsManager from '@/components/admin/FacultyInterestsManager';
import { getNowSync } from '@/lib/clock';

const BRANCHES = COLLEGE_CONFIG.branches;

const currentYear = getNowSync().getFullYear();
const YEARS = Array.from({ length: 4 }, (_, i) => (currentYear - i).toString()).reverse();

export default function AdminDashboardPage() {
  const { clerks, studentStats, loading: contextLoading } = useAdmin();
  const [searchRoll, setSearchRoll] = useState('');
  const [searchedStudent, setSearchedStudent] = useState(null);
  const [searchError, setSearchError] = useState('');
  const [allStudents, setAllStudents] = useState([]);
  const [loadingAll, setLoadingAll] = useState(false);
  const [allError, setAllError] = useState('');
  const [selectedBranch, setSelectedBranch] = useState('CSE');
  const [selectedStudyingYear, setSelectedStudyingYear] = useState('1'); 
  const [activeTab, setActiveTab] = useState('stats'); // 'stats', 'faculty'

  const totalClerks = Array.isArray(clerks) ? clerks.length : 0;
  const activeClerks = Array.isArray(clerks) ? clerks.filter(c => c.is_active).length : 0;

  const handleSearch = async (e) => {
    e.preventDefault();
    setSearchError('');
    setSearchedStudent(null);
    if (!searchRoll.trim()) {
      setSearchError('Please enter a roll number.');
      return;
    }
    const { isValid } = validateRollNo(searchRoll.trim());
    if (!isValid) {
      setSearchError('Invalid Roll Number format.');
      return;
    }
    try {
      const res = await fetch(`/api/admin/students/${encodeURIComponent(searchRoll.trim())}`);
      if (res.ok) {
        const data = await res.json();
        if (data && data.student) {
          setSearchedStudent(data.student);
        } else {
          setSearchError('No student found for this roll number.');
        }
      } else {
        setSearchError('No student found for this roll number.');
      }
    } catch {
      setSearchError('Error searching for student.');
    }
  };

  const handleFetchAllStudents = async () => {
    setLoadingAll(true);
    setAllError('');
    setAllStudents([]);
    try {
      const res = await fetch(`/api/admin/students?studyingYear=${selectedStudyingYear}&branch=${selectedBranch}`);
      if (res.ok) {
        const data = await res.json();
        if (Array.isArray(data.students) && data.students.length > 0) {
          setAllStudents(data.students);
        } else {
          setAllError('No students found.');
        }
      } else {
        setAllError('No students found.');
      }
    } catch {
      setAllError('Error fetching students.');
    }
    setLoadingAll(false);
  };
  
  const studyYears = [1, 2, 3, 4];

  // Calculate total students in college
  const totalStudentsInCollege = studentStats 
    ? Object.values(studentStats).reduce((sum, branchStats) => sum + branchStats.total, 0)
    : 0;

  return (
    <div className="flex flex-col items-center justify-center p-2 sm:p-4">
      <div className="w-full max-w-6xl mx-auto bg-white border border-slate-200 shadow-sm p-4 sm:p-6 lg:p-8 flex flex-col items-center">
        <h1 className="text-xl sm:text-2xl font-bold text-[#0b3578] mb-6 tracking-tight uppercase">Admin Dashboard</h1>
        <form onSubmit={handleSearch} className="w-full flex flex-col sm:flex-row gap-2 mb-6">
          <input
            type="text"
            placeholder="Search by Roll No."
