import { db } from '@/db';
import { auditLogs, clerks, principal } from '@/db/schema';
import { eq, and, desc, like, sql, or } from 'drizzle-orm';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';
import logger from '@/lib/logger';

export async function GET(req) {
  try {
    const user = await getAuthUser('admin');
    if (!user) return apiError('Unauthorized', 401);

    const { searchParams } = new URL(req.url);
    const action = searchParams.get('action');
    const userType = searchParams.get('userType');
    const targetId = searchParams.get('targetId');
    const limitParam = parseInt(searchParams.get('limit') || '50');
    const limit = Number.isNaN(limitParam) ? 50 : Math.max(1, Math.min(limitParam, 100));
    const lastSeenIdParam = searchParams.get('last_seen_id') ? parseInt(searchParams.get('last_seen_id')) : null;
    const lastSeenId = Number.isNaN(lastSeenIdParam) ? null : lastSeenIdParam;

    // Build filters
    const baseFilters = [];
    if (action) baseFilters.push(eq(auditLogs.action, action));
    if (userType) baseFilters.push(eq(auditLogs.user_type, userType));
    if (targetId) baseFilters.push(eq(auditLogs.target_id, targetId));

    const dataFilters = [...baseFilters];
    if (lastSeenId) dataFilters.push(sql`${auditLogs.id} < ${lastSeenId}`);

    // Fetch logs with basic user info join
    // Note: Since user_id can refer to different tables based on user_type, 
    // we'll fetch raw logs first and then decorate if needed, or just return raw for now.
    const logs = await db.select()
      .from(auditLogs)
      .where(dataFilters.length > 0 ? and(...dataFilters) : undefined)
      .orderBy(desc(auditLogs.id))
      .limit(limit);

    // Get total count for pagination
    const [countResult] = await db.select({ count: sql`count(*)` })
      .from(auditLogs)
      .where(baseFilters.length > 0 ? and(...baseFilters) : undefined);

    return apiResponse({ 
      logs, 
      total: parseInt(countResult.count),
      limit,
      last_seen_id: logs.length > 0 ? logs[logs.length - 1].id : null
    });

  } catch (error) {
    logger.error(error, 'Failed to fetch audit logs');
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { clerks } from '@/db/schema';
import { eq, and, ne, sql } from 'drizzle-orm';
import { apiError, apiResponse, getAuthUser, logAudit } from '@/lib/api-utils';
import { clerkSchema } from '@/lib/validations/staff';
import { z } from 'zod';

export async function DELETE(req, context) {
  const user = await getAuthUser('admin');
  if (!user) return apiError('Unauthorized', 401);

  try {
    const params = await context.params;
    const idNum = parseInt(params.id);

    const clerkBefore = await db.query.clerks.findFirst({
      where: eq(clerks.id, idNum)
    });

    if (!clerkBefore) {
      return apiError('Clerk not found', 404);
    }

    const [result] = await db.update(clerks).set({ is_active: false }).where(eq(clerks.id, idNum));

    if (result.affectedRows === 0) {
      return apiError('Failed to delete clerk', 500);
    }

    // Audit Log
    await logAudit(req, {
      userId: user.id,
      userType: 'admin',
      action: 'DELETE_CLERK',
      targetId: idNum,
      targetType: 'clerk',
      before: clerkBefore
    });

    return apiResponse({ message: 'Clerk deleted successfully' });
  } catch (error) {
    logger.error('Error deleting clerk:', error);
    return apiError('Internal Server Error', 500);
  }
}

export async function PUT(req, context) {
  const user = await getAuthUser('admin');
  if (!user) return apiError('Unauthorized', 401);

  try {
    const params = await context.params;
    const idNum = parseInt(params.id);
    const json = await req.json();

    // Validate with Zod
    const updateSchema = clerkSchema.extend({
      is_active: z.boolean().default(true),
      employee_id: z.string().trim().min(1).max(50)
    }).partial();

    const validatedData = updateSchema.parse(json);
    const { name, email, employee_id, role, is_hod, branch, is_active } = validatedData;

    const clerkBefore = await db.query.clerks.findFirst({
      where: eq(clerks.id, idNum)
    });

    if (!clerkBefore) {
      return apiError('Clerk not found', 404);
    }

    // STRICT VALIDATION: Only one HOD per branch
    if (is_hod && branch && is_active !== false) {
      const existingHOD = await db.select({ id: clerks.id, name: clerks.name })
        .from(clerks)
        .where(and(
          eq(clerks.branch, branch),
          eq(clerks.is_hod, true),
          eq(clerks.is_active, true),
          ne(clerks.id, idNum)
        ))
        .limit(1);

      if (existingHOD.length > 0) {
        return apiError(
          `Conflict: ${existingHOD[0].name} is already the HOD for ${branch}. Please demote them first.`,
          400
        );
      }
    }

    const updatePayload = { /* empty */ };
    if (name !== undefined) updatePayload.name = name;
    if (email !== undefined) updatePayload.email = email.toLowerCase();
    if (employee_id !== undefined) updatePayload.employee_id = employee_id;
    if (role !== undefined) updatePayload.role = role;
    if (is_hod !== undefined) updatePayload.is_hod = !!is_hod;
    if (branch !== undefined) updatePayload.branch = branch || null;
    if (is_active !== undefined) updatePayload.is_active = !!is_active;

    const [result] = await db.update(clerks)
      .set(updatePayload)
      .where(eq(clerks.id, idNum));

    if (result.affectedRows === 0) {
      return apiError('Failed to update clerk', 500);
    }

    // Audit Log
    await logAudit(req, {
      userId: user.id,
      userType: 'admin',
      action: 'UPDATE_CLERK',
      targetId: idNum,
      targetType: 'clerk',
      before: clerkBefore,
      after: updatePayload
    });

    return apiResponse({ message: 'Clerk updated successfully' });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return apiError(error.errors?.[0]?.message || 'Invalid input data', 400);
    }
    logger.error('Error updating clerk:', error);
    if (error && error.code === 'ER_DUP_ENTRY') {
      return apiError('Email or Employee ID already exists', 409);
    }
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { clerks } from '@/db/schema';
import { eq } from 'drizzle-orm';
import bcrypt from 'bcrypt';
import { sendInstitutionalEmail } from '@/lib/email';
import { apiError, apiResponse, getAuthUser } from '@/lib/api-utils';
import { clerkSchema } from '@/lib/validations/staff';
import { z } from 'zod';

export async function POST(req) {
  const user = await getAuthUser('admin');
  if (!user) return apiError('Unauthorized', 401);

  try {
    const json = await req.json();
    
    // Validate with Zod
    const validationSchema = clerkSchema.extend({
      password: z.string().min(8, "Password must be at least 8 characters"),
      employee_id: z.string().trim().min(1, "Employee ID is required").max(50)
    });

    const validatedData = validationSchema.parse(json);
    const { name, email, password, employee_id, role, branch, is_hod } = validatedData;

    const saltRounds = 10;
    const passwordHash = await bcrypt.hash(password, saltRounds);

    const [result] = await db.insert(clerks).values({
      name,
      email: email.toLowerCase(),
      password_hash: passwordHash,
      employee_id,
      role,
      branch: branch || null,
      is_hod: !!is_hod
    });

    const subject = `Your KUCET CMS ${role} Account Credentials`;
    const title = 'Account Activation';
    const bodyHtml = `
      <p>Dear ${name},</p>
      <p>Your account for the KUCET College Management System has been created.</p>
      <p>Please find your account details below. Keep these credentials confidential and change your password after first login.</p>
    `;

    const emailResult = await sendInstitutionalEmail({
      to: email,
      subject,
      title,
      bodyHtml,
      infoRows: [
        { label: 'Name', value: name },
        { label: 'Email', value: email },
        { label: 'Employee ID', value: employee_id },
        { label: 'Role', value: role },
        { label: 'Temporary Password', value: password }
      ]
    });

    if (!emailResult.success) {
      logger.error(`Failed to send welcome email to ${email}: ${emailResult.message}`);
    }

    return apiResponse({ success: true, clerkId: result.insertId }, 201);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return apiError(error.errors?.[0]?.message || 'Invalid input data', 400);
    }
    logger.error('Error creating clerk:', error);
    if (error.code === 'ER_DUP_ENTRY') {
      return apiError('Email or Employee ID already exists', 409);
    }
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { 
  facultySubjectInterests, 
  clerks, 
  collegeInfo as collegeInfoTable, 
  facultySubjectAssignments 
} from '@/db/schema';
import { eq, and, desc, sql, or } from 'drizzle-orm';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';
import { getCollegeAcademicYear } from '@/lib/academic-utils';

export async function GET(request) {
  try {
    const user = await getAuthUser('admin');
    if (!user) return apiError('Unauthorized', 401);

    const collegeRows = await db.select().from(collegeInfoTable).where(eq(collegeInfoTable.id, 1)).limit(1);
    const collegeInfo = collegeRows[0] || null;
    const currentAcademicYear = await getCollegeAcademicYear(collegeInfo);

    const allocatedSubquery = db.select({
      names: sql`GROUP_CONCAT(${clerks.name} SEPARATOR ', ')`.as('names'),
      subject_code: facultySubjectAssignments.subject_code,
      branch: facultySubjectAssignments.branch,
      course_semester: facultySubjectAssignments.course_semester,
      academic_year: facultySubjectAssignments.academic_year
    })
    .from(facultySubjectAssignments)
    .innerJoin(clerks, eq(facultySubjectAssignments.faculty_id, clerks.id))
    .groupBy(
      facultySubjectAssignments.subject_code,
      facultySubjectAssignments.branch,
      facultySubjectAssignments.course_semester,
      facultySubjectAssignments.academic_year
    )
    .as('asgn');

    const interests = await db.select({
      id: facultySubjectInterests.id,
      faculty_id: facultySubjectInterests.faculty_id,
      subject_code: facultySubjectInterests.subject_code,
      subject_name: facultySubjectInterests.subject_name,
      branch: facultySubjectInterests.branch,
      semester: facultySubjectInterests.semester,
      academic_year: facultySubjectInterests.academic_year,
      status: facultySubjectInterests.status,
      created_at: facultySubjectInterests.created_at,
      updated_at: facultySubjectInterests.updated_at,
      faculty_name: clerks.name,
      employee_id: clerks.employee_id,
      allocated_faculty_name: allocatedSubquery.names
    })
    .from(facultySubjectInterests)
    .innerJoin(clerks, eq(facultySubjectInterests.faculty_id, clerks.id))
    .leftJoin(allocatedSubquery, and(
      eq(facultySubjectInterests.subject_code, allocatedSubquery.subject_code),
      eq(facultySubjectInterests.branch, allocatedSubquery.branch),
      eq(facultySubjectInterests.semester, allocatedSubquery.course_semester),
      eq(facultySubjectInterests.academic_year, allocatedSubquery.academic_year)
    ))
    .where(or(
      eq(facultySubjectInterests.academic_year, currentAcademicYear),
      eq(facultySubjectInterests.status, 'PENDING')
    ))
    .orderBy(desc(sql`${facultySubjectInterests.status} = 'PENDING'`), desc(facultySubjectInterests.created_at));

    return apiResponse({ data: interests });
  } catch (error) {
    logger.error('Admin Interests Fetch Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { getAuthUser, apiError, apiResponse } from '@/lib/api-utils';
import { v2 as cloudinary } from 'cloudinary';
import { spawn } from 'child_process';
import fs from 'fs';
import path from 'path';
import os from 'os';

// Configure Cloudinary
cloudinary.config({
  cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
  api_key: process.env.CLOUDINARY_API_KEY,
  api_secret: process.env.CLOUDINARY_API_SECRET,
  secure: true,
});

export async function POST(req) {
  try {
    const user = await getAuthUser('admin');
    if (!user) return apiError('Unauthorized', 401);

    const { filename } = await req.json();
    if (!filename) return apiError('Filename is required.', 400);

    // Validate filename: allow only alphanumerics, dots, dashes, underscores, .sql extension
    if (!/^[A-Za-z0-9._-]+\.sql$/.test(filename)) {
      return apiError('Invalid filename.', 400);
    }

    // SECURITY: We could verify password again here if we had it hashed, 
    // but the getAuthUser already verified the session.
    // For now, we trust the Super Admin session but log it heavily.
    logger.warn(`[CRITICAL_ACTION] Super Admin ${user.email} initiated DATABASE RESTORE using ${filename}`);

    const publicId = `kucet/backups/${filename}`;
    const tempFilePath = path.join(os.tmpdir(), `restore_${new Date().getTime()}.sql`);

    // 1. Download the backup file
    const downloadUrl = cloudinary.utils.private_download_url(publicId, 'sql', {
      resource_type: 'raw'
    });

    const response = await fetch(downloadUrl);
    if (!response.ok) throw new Error('Failed to download backup file from cloud.');
    
    const buffer = await response.arrayBuffer();
    fs.writeFileSync(tempFilePath, Buffer.from(buffer));

    // 2. Perform Restore using mysql CLI
    // Note: This requires mysql client to be installed on the system/container.
    return new Promise((resolve) => {
      const mysqlArgs = [
        `--host=${process.env.DB_HOST}`,
        `--user=${process.env.DB_USER}`,
        `--port=${process.env.DB_PORT || 3306}`,
        process.env.DB_DATABASE
      ];

      // Pass password via environment variable instead of command line
      const mysqlEnv = { ...process.env, MYSQL_PWD: process.env.DB_PASSWORD };

      // Handle SSL for TiDB Cloud if needed
      if (process.env.DB_SSL === 'true' || process.env.DB_HOST.includes('tidbcloud.com')) {
        mysqlArgs.push('--ssl-mode=REQUIRED');
      }

      // We use spawn and pipe the file into stdin
      const mysqlProcess = spawn('mysql', mysqlArgs, {
        stdio: ['pipe', 'pipe', 'pipe'],
        env: mysqlEnv
      });

      mysqlProcess.on('error', (err) => {
        logger.error(`Failed to start mysql restore process: ${err.message}`);
        // Clean up on error
        if (fs.existsSync(tempFilePath)) {
          try { fs.unlinkSync(tempFilePath); } catch (e) { /* empty */ }
        }
        resolve(apiError('Failed to initiate mysql restoration.', 500));
      });

      const fileStream = fs.createReadStream(tempFilePath);
      fileStream.pipe(mysqlProcess.stdin);

      let errorOutput = '';
      mysqlProcess.stderr.on('data', (data) => {
        errorOutput += data.toString();
      });

      mysqlProcess.on('close', (code) => {
        // Cleanup
        if (fs.existsSync(tempFilePath)) {
          try { fs.unlinkSync(tempFilePath); } catch (e) { /* empty */ }
        }
        fileStream.destroy();

        if (code === 0) {
          logger.info(`[RESTORE_SUCCESS] Database successfully restored from ${filename}`);
          resolve(apiResponse({ success: true, message: 'Database restoration successful.' }));
        } else {
          logger.error(`[RESTORE_FAILED] Database restore failed with code ${code}. Error: ${errorOutput}`);
          resolve(apiError('Database restoration failed.', 500));
        }
      });
    });

  } catch (error) {
    logger.error(error, 'Error during database restore');
    return apiError('Internal Server Error', 500);
  }
}

