export async function POST(req) {
  try {
    const user = await getAuthUser('admin');
    if (!user) return apiError('Unauthorized', 401);

    logger.info(`[ADMIN] ${user.email} triggered manual database backup.`);

    // Trigger the backup script using tsx
    // We'll run it as a detached process or wait for it? 
    // Since it's an admin action, we'll wait and give feedback.
    
    return new Promise((resolve) => {
      const scriptPath = path.join(process.cwd(), 'src', 'db', 'backup.js');
      const child = spawn('npx', ['tsx', scriptPath], { shell: true });

      let output = '';
      child.stdout.on('data', (data) => { output += data.toString(); });
      child.stderr.on('data', (data) => { output += data.toString(); });

      child.on('error', (err) => {
        logger.error(`Failed to start backup process: ${err.message}`);
        resolve(apiError('Failed to initiate backup process.', 500, err.message));
      });

      child.on('close', (code) => {
        if (code === 0) {
          resolve(apiResponse({ success: true, message: 'Backup completed successfully.' }));
        } else {
          logger.error(`Backup process failed with code ${code}. Output: ${output}`);
          resolve(apiError('Backup execution failed.', 500, output));
        }
      });
    });

  } catch (error) {
    logger.error(error, 'Error triggering backup');
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { collegeInfo } from '@/db/schema';
import { getAuthUser, apiError, apiResponse } from '@/lib/api-utils';
import { eq } from 'drizzle-orm';
import { ValidationService } from '@/services/ValidationService';

export async function GET(req) {
  try {
    const user = await getAuthUser('admin');
    if (!user) return apiError('Unauthorized', 401);

    const config = await db.query.collegeInfo.findFirst();
    return apiResponse({ config });
  } catch (error) {
    logger.error(error, 'Error fetching institutional config');
    return apiError('Internal Server Error', 500);
  }
}

export async function PATCH(req) {
  try {
    const user = await getAuthUser('admin');
    if (!user) return apiError('Unauthorized', 401);

    const updates = await req.json();
    
    const existing = await db.query.collegeInfo.findFirst();
    
    // Logic-level Dependency Check for Branch Removal
    if (existing && updates.branches) {
      const oldBranches = existing.branches || [];
      const newBranches = updates.branches || [];
      
      // Find removed branches
      const removedBranches = oldBranches.filter(b => !newBranches.includes(b));
      
      for (const branch of removedBranches) {
        const { canDelete, reason } = await ValidationService.checkBranchDependencies(branch);
        if (!canDelete) {
          return apiError(reason, 400);
        }
      }
    }

    if (!existing) {
      await db.insert(collegeInfo).values(updates);
    } else {
      // Don't allow updating ID
      delete updates.id;
      delete updates.updated_at;
      
      await db.update(collegeInfo).set(updates).where(eq(collegeInfo.id, existing.id));
    }

    logger.warn(`[CONFIG_UPDATE] Admin ${user.email} updated institutional configuration.`);

    return apiResponse({ success: true, message: 'Configuration updated successfully.' });
  } catch (error) {
    if (error.status === 400) throw error; // Re-throw validation errors
    logger.error(error, 'Error updating institutional config');
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { getAuthUser, apiError, apiResponse } from '@/lib/api-utils';
import { v2 as cloudinary } from 'cloudinary';
import fs from 'fs';
import path from 'path';

// Configure Cloudinary
cloudinary.config({
  cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
  api_key: process.env.CLOUDINARY_API_KEY,
  api_secret: process.env.CLOUDINARY_API_SECRET,
  secure: true,
});

/**
 * Recursively list files in a local directory
 */
function getAllFiles(dirPath, arrayOfFiles = []) {
  const files = fs.readdirSync(dirPath);

  files.forEach((file) => {
    if (fs.statSync(dirPath + "/" + file).isDirectory()) {
      arrayOfFiles = getAllFiles(dirPath + "/" + file, arrayOfFiles);
    } else {
      arrayOfFiles.push(path.join(dirPath, "/", file));
    }
  });

  return arrayOfFiles;
}

export async function GET(req) {
  try {
    const user = await getAuthUser('admin');
    if (!user) return apiError('Unauthorized', 401);

    const storageType = process.env.NEXT_PUBLIC_STORAGE_TYPE || 'cloudinary';
    let files = [];

    if (storageType === 'local') {
      const STORAGE_PATH = process.env.LOCAL_STORAGE_PATH || '/var/www/kucet-storage/uploads';
      if (fs.existsSync(STORAGE_PATH)) {
        const localFiles = getAllFiles(STORAGE_PATH);
        files = localFiles.map(f => {
          const stats = fs.statSync(f);
          return {
            name: path.relative(STORAGE_PATH, f).replace(/\/g, '/'),
            size: stats.size,
            created_at: stats.birthtime,
            type: 'local'
          };
        });
      }
    } else {
      // List from Cloudinary (kucet/ folder)
      // Note: resources_by_asset_folder only returns 1 level. 
      // To get EVERYTHING, we use the Search API.
      const result = await cloudinary.search
        .expression('folder:kucet/*')
        .sort_by('public_id', 'desc')
        .max_results(500)
        .execute();

      files = result.resources.map(r => ({
        name: r.public_id.replace(/^kucet//, ''),
        size: r.bytes,
        created_at: r.created_at,
        type: 'cloudinary',
        secure_url: r.secure_url,
        format: r.format
      }));
    }

    return apiResponse({ files, storageType });
  } catch (error) {
    logger.error(error, 'Error exploring storage');
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { getAuthUser, apiError } from '@/lib/api-utils';
import { v2 as cloudinary } from 'cloudinary';
import { NextResponse } from 'next/server';

// Configure Cloudinary
cloudinary.config({
  cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
  api_key: process.env.CLOUDINARY_API_KEY,
  api_secret: process.env.CLOUDINARY_API_SECRET,
