});

export async function GET(req) {
  try {
    const user = await getAuthUser('admin');
    if (!user) return apiError('Unauthorized', 401);

    const storageType = process.env.NEXT_PUBLIC_STORAGE_TYPE || 'cloudinary';

    if (storageType === 'cloudinary') {
      // Cloudinary has a built-in on-the-fly zip generator via signed URLs.
      // This bypasses the synchronous create_archive limits (10MB) and doesn't create persistent files.
      // We target the 'kucet' folder prefix.
      const zipUrl = cloudinary.utils.download_zip_url({
        prefixes: 'kucet/',
        resource_type: 'image',
        flatten_folders: false,
        use_original_filename: true,
        target_public_id: `kucet_full_export_${new Date().getTime()}`
      });

      if (!zipUrl) {
        throw new Error('Failed to generate signed download URL');
      }

      // Redirect the admin's browser directly to the Cloudinary zip generator
      return NextResponse.redirect(zipUrl);
    } else {
      // Local storage zipping 
      // This would require a library like archiver or adm-zip.
      // For now, we'll return an error if the library is missing or suggest manual VPS access.
      return apiError('Local storage zipping requires server-side compression utilities. Please contact system admin for direct VPS access.', 501);
    }

  } catch (error) {
    logger.error(error, 'Error generating storage zip');
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { students as studentsTable, collegeInfo as collegeInfoTable } from '@/db/schema';
import { eq } from 'drizzle-orm';
import { getBranchFromRoll, getCurrentStudyingYear, branchCodes } from '@/lib/rollNumber';
import { apiError, apiResponse, getAuthUser } from '@/lib/api-utils';
import { getNow } from '@/lib/clock';

export async function GET(req) {
  const user = await getAuthUser('admin');
  if (!user) return apiError('Unauthorized', 401);

  try {
    const now = await getNow();
    const collegeRows = await db.select().from(collegeInfoTable).where(eq(collegeInfoTable.id, 1)).limit(1);
    const collegeInfo = collegeRows[0] || null;

    const students = await db.select({ roll_no: studentsTable.roll_no }).from(studentsTable);

    const stats = { /* empty */ };
    const allBranchNames = Object.values(branchCodes);
    allBranchNames.forEach(name => {
      stats[name] = { 1: 0, 2: 0, 3: 0, 4: 0, total: 0 };
    });

    for (const student of students) {
      const { roll_no } = student;
      const branch = getBranchFromRoll(roll_no);
      const year = getCurrentStudyingYear(roll_no, collegeInfo, now);

      if (branch && year && stats[branch]) {
        if (stats[branch][year] !== undefined) {
          stats[branch][year]++;
        }
        stats[branch].total++;
      }
    }

    return apiResponse({ data: stats });
  } catch (error) {
    logger.error('Error fetching student stats:', error);
    return apiError('Internal Server Error', 500);
  }
}

import { db } from '@/db';
import { certificateVerifications, studentRequests, students } from '@/db/schema';
import { eq, sql, desc } from 'drizzle-orm';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';
import logger from '@/lib/logger';

export async function GET(request) {
    try {
        const user = await getAuthUser('admin');
        if (!user) {
            return apiError("Unauthorized", 401);
        }

        // 1. Get location-based aggregation for heatmap
        const locationStats = await db.select({
            location: certificateVerifications.location_name,
            count: sql`count(*)`,
            latitude: certificateVerifications.latitude,
            longitude: certificateVerifications.longitude
        })
        .from(certificateVerifications)
        .groupBy(certificateVerifications.location_name, certificateVerifications.latitude, certificateVerifications.longitude)
        .orderBy(desc(sql`count(*)`))
        .limit(50);

        // 2. Get most verified certificates (potential suspicious activity)
        const topVerifiedCerts = await db.select({
            request_id: certificateVerifications.request_id,
            cert_id: studentRequests.generated_certificate_id,
            student_name: students.name,
            roll_no: students.roll_no,
            count: sql`count(*)`
        })
        .from(certificateVerifications)
        .innerJoin(studentRequests, eq(certificateVerifications.request_id, studentRequests.request_id))
        .innerJoin(students, eq(studentRequests.student_id, students.id))
        .groupBy(certificateVerifications.request_id, studentRequests.generated_certificate_id, students.name, students.roll_no)
        .orderBy(desc(sql`count(*)`))
        .limit(20);

        // 3. Recent verification list
        const recentVerifications = await db.select({
            id: certificateVerifications.id,
            cert_id: studentRequests.generated_certificate_id,
            student_name: students.name,
            verification_date: certificateVerifications.verification_date,
            location: certificateVerifications.location_name,
            ip: certificateVerifications.ip_address,
            device: certificateVerifications.device_name
        })
        .from(certificateVerifications)
        .innerJoin(studentRequests, eq(certificateVerifications.request_id, studentRequests.request_id))
        .innerJoin(students, eq(studentRequests.student_id, students.id))
        .orderBy(desc(certificateVerifications.verification_date))
        .limit(100);

        return apiResponse({
            locationStats,
            topVerifiedCerts,
            recentVerifications
        });

    } catch (error) {
        logger.error({ err: error }, "[VERIFY_STATS_ERROR]");
        return apiError("Internal Server Error", 500);
    }
}

import logger from '@/lib/logger';
import NextAuth from "next-auth"
import GoogleProvider from "next-auth/providers/google";
import { db } from "@/db";
import { clerks } from "@/db/schema";
import { eq } from "drizzle-orm";
import { isDeveloper } from '@/lib/developers';

const publicBaseUrlRaw = process.env.NEXT_PUBLIC_BASE_URL;
if (process.env.NODE_ENV === 'production' && publicBaseUrlRaw) {
  const publicBaseUrl = /^https?:///i.test(publicBaseUrlRaw)
    ? publicBaseUrlRaw
    : `https://${publicBaseUrlRaw}`;
  process.env.NEXTAUTH_URL = publicBaseUrl;
  process.env.NEXTAUTH_URL_INTERNAL = publicBaseUrl;
}

export const authOptions = {
  trustHost: true,
  providers: [
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    }),
  ],
  callbacks: {
    async signIn({ account, profile }) {
      try {
        if (account.provider === "google") {
          if (!profile.email_verified) {
            return false; // Do not allow login if email is not verified
          }

          // Allow developer emails even if not in clerks table
          if (isDeveloper(profile.email)) {
            return true;
          }

          // Check if a clerk with this email exists
          const clerk = await db.query.clerks.findFirst({
            where: eq(clerks.email, profile.email),
            columns: {
                id: true,
                name: true,
                email: true,
                role: true,
                is_active: true
            }
          });
          logger.info('Google Sign-in: Profile Email:', profile.email);

          if (clerk) {
            logger.info('Google Sign-in: Clerk Found:', clerk.email, 'Role:', clerk.role, 'Active:', clerk.is_active);
            // If the clerk exists and is active, allow sign-in
            return clerk.is_active ? true : '/api/auth/error?error=ClerkInactive'; // Return redirect URL with error
          } else {
            // If the clerk does not exist, do not allow sign-in
            return '/api/auth/error?error=ClerkNotFound'; // Return redirect URL with error
          }
        }
        return '/api/auth/error?error=GoogleAuthError'; // General error for other providers or unexpected issues
      } catch (error) {
        logger.error('SignIn Callback Error:', error);
        return '/api/auth/error?error=SignInError';
      }
    },
    async jwt({ token, user, account, profile }) {
      // This is called after a successful sign-in
      try {
        if (account?.provider === "google" && profile) {
          const clerk = await db.query.clerks.findFirst({
            where: eq(clerks.email, profile.email),
            columns: {
                id: true,
                name: true,
                role: true
            }
          });
          if (clerk) {
            token.id = clerk.id;
            token.name = clerk.name;
            token.role = clerk.role;
          }
        }
      } catch (error) {
        logger.error('JWT Callback Error:', error);
      }
      return token;
    },
    async session({ session, token }) {
      // Add custom properties to the session object
      try {
        if (token?.id) {
          session.user.id = token.id;
        }
        if (token?.role) {
          session.user.role = token.role;
        }
      } catch (error) {
        logger.error('Session Callback Error:', error);
      }
      return session;
    },
    async redirect({ url, baseUrl }) {
      if (!globalThis.__nextauth_redirect_logged) {
        globalThis.__nextauth_redirect_logged = true;
        logger.info('[NEXTAUTH_REDIRECT]', {
          url,
          baseUrl,
          NEXTAUTH_URL: process.env.NEXTAUTH_URL,
          NEXTAUTH_URL_INTERNAL: process.env.NEXTAUTH_URL_INTERNAL,
          NEXT_PUBLIC_BASE_URL: process.env.NEXT_PUBLIC_BASE_URL,
          NODE_ENV: process.env.NODE_ENV,
        });
      }
      const preferredBase = process.env.NEXT_PUBLIC_BASE_URL || baseUrl;
      const normalizedBase = preferredBase.replace(/\/$/, '');
      if (url.startsWith('/')) {
        return `${normalizedBase}${url}`;
      }
      if (url.startsWith(normalizedBase)) {
        return url;
      }
      return normalizedBase;
    }
  },
  secret: process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || process.env.JWT_SECRET,
  session: {
    strategy: "jwt",
  },
  pages: {
    signIn: '/', // Redirect users to homepage for error
    error: '/', // Redirect users to homepage on error
  },
};

const handler = NextAuth(authOptions);

export { handler as GET, handler as POST };

import logger from '@/lib/logger';
import { NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { SignJWT } from 'jose';
import { authOptions } from '@/app/api/auth/[...nextauth]/route';
import { db } from '@/db';
import { clerks } from '@/db/schema';
import { eq } from 'drizzle-orm';
import { isDeveloper } from '@/lib/developers';

function resolveBaseRedirect(request) {
  const forwardedHost = request.headers.get('x-forwarded-host');
  if (forwardedHost) {
    const forwardedProto = request.headers.get('x-forwarded-proto') || 'https';
    return new URL(`${forwardedProto}://${forwardedHost}/`);
  }

  if (process.env.NEXT_PUBLIC_BASE_URL) {
    return new URL(process.env.NEXT_PUBLIC_BASE_URL);
  }

  return new URL('/', request.url);
}

async function buildClerkAuthToken(clerk) {
  const secret = new TextEncoder().encode(process.env.JWT_SECRET);
  return new SignJWT({
    id: clerk.id,
    clerkId: clerk.id,
    email: clerk.email,
    role: clerk.role,
    is_hod: !!clerk.is_hod,
    branch: clerk.branch,
  })
    .setProtectedHeader({ alg: 'HS256' })
    .setIssuedAt()
    .setExpirationTime('1h')
    .sign(secret);
}

export async function GET(request) {
  const session = await getServerSession(authOptions);
  const baseRedirect = resolveBaseRedirect(request);
  if (!globalThis.__google_complete_redirect_logged) {
    globalThis.__google_complete_redirect_logged = true;
    logger.info('[GOOGLE_COMPLETE_REDIRECT]', {
      requestUrl: request.url,
      forwardedHost: request.headers.get('x-forwarded-host'),
      forwardedProto: request.headers.get('x-forwarded-proto'),
      resolvedBase: baseRedirect.toString(),
      NEXT_PUBLIC_BASE_URL: process.env.NEXT_PUBLIC_BASE_URL,
    });
  }

  if (!session?.user?.email) {
    return NextResponse.redirect(new URL('/?error=NoEmail', baseRedirect), 303);
  }

  // Developer login: redirect to developers page without app auth cookies
  if (isDeveloper(session.user.email)) {
    return NextResponse.redirect(new URL('/developers', baseRedirect), 303);
  }

  const clerk = await db.query.clerks.findFirst({
    where: eq(clerks.email, session.user.email),
    columns: {
      id: true,
      email: true,
      role: true,
      is_active: true,
      is_hod: true,
      branch: true
    }
  });

  if (!clerk || !clerk.is_active) {
    return NextResponse.redirect(baseRedirect, 303);
  }

  const response = NextResponse.redirect(baseRedirect, 303);

  // Clear other auth cookies
  response.cookies.delete('admin_auth');
  response.cookies.delete('student_auth');

  // Use the standard utility to issue 30-day cookies for Google Login
  const { issueClerkAuthCookie } = await import('@/lib/auth-utils');
  await issueClerkAuthCookie(response, clerk, true);

  return response;
}

import { apiResponse } from '@/lib/api-utils';

export async function GET(request) {
  const response = apiResponse({ success: true, message: 'Logged out' });
  
  // Clear all potential auth cookies
  const cookiesToClear = [
    'admin_auth', 'admin_logged_in', 'admin_refresh_token', 'admin_session_id',
    'clerk_auth', 'clerk_logged_in', 'clerk_refresh_token', 'clerk_role', 'clerk_session_id',
    'student_auth', 'student_logged_in', 'student_refresh_token', 'student_session_id',
    'session_id'
  ];

  cookiesToClear.forEach(name => {
    response.cookies.delete(name);
  });

  const { searchParams } = new URL(request.url);
  const revoked = searchParams.get('revoked');
  
  if (revoked === 'true') {
    return Response.redirect(new URL('/?revoked=true', request.url));
  }

  return Response.redirect(new URL('/', request.url));
}

export async function POST(request) {
  const response = apiResponse({ success: true, message: 'Logged out' });
  
  const cookiesToClear = [
    'admin_auth', 'admin_logged_in', 'admin_refresh_token', 'admin_session_id',
    'clerk_auth', 'clerk_logged_in', 'clerk_refresh_token', 'clerk_role', 'clerk_session_id',
    'student_auth', 'student_logged_in', 'student_refresh_token', 'student_session_id',
    'session_id'
  ];

  cookiesToClear.forEach(name => {
    response.cookies.delete(name);
  });

  return response;
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { refreshTokens, students, clerks, principal, userSessions } from '@/db/schema';
import { eq, and, isNull } from 'drizzle-orm';
import { apiResponse, apiError } from '@/lib/api-utils';
import crypto from 'crypto';
import { 
  issueStudentAuthCookie, 
  issueClerkAuthCookie, 
  issueAdminAuthCookie 
} from '@/lib/auth-utils';
import { cookies } from 'next/headers';

export async function POST(req) {
  try {
    const { type } = await req.json(); // 'student', 'clerk', or 'admin'
    if (!['student', 'clerk', 'admin'].includes(type)) {
      return apiError('Invalid user type', 400);
    }

    const cookieStore = await cookies();
    const refreshToken = cookieStore.get(`${type}_refresh_token`)?.value;

    if (!refreshToken) {
      return apiError('Refresh token missing', 401);
    }

    const tokenHash = crypto.createHash('sha256').update(refreshToken).digest('hex');

    // 1. Find the token in DB
    const tokenRecord = await db.query.refreshTokens.findFirst({
      where: and(
        eq(refreshTokens.token_hash, tokenHash),
        eq(refreshTokens.user_type, type)
      )
    });

    if (!tokenRecord) {
      return apiError('Invalid refresh token', 401);
    }

    // 2. Check if the specific session is revoked in user_sessions (Security Enhancement)
    const sessionRecord = await db.query.userSessions.findFirst({
      where: and(
        eq(userSessions.session_token_hash, tokenHash),
        eq(userSessions.is_revoked, true)
      )
    });

    if (sessionRecord) {
      return apiError('Your session has been revoked. Please login again.', 401);
    }

    // 3. Check if revoked in refreshTokens
    if (tokenRecord.revoked_at) {
      // SECURITY: Potential theft if a revoked token is reused. 
      // Revoke all tokens for this user as a precaution.
      const now = (await import('@/lib/clock')).getNow();
      await db.update(refreshTokens)
        .set({ revoked_at: now })
        .where(and(
            eq(refreshTokens.user_id, tokenRecord.user_id),
            eq(refreshTokens.user_type, type)
        ));
      return apiError('Token revoked. Please login again.', 401);
    }

    // 4. Check if expired
    const now = (await import('@/lib/clock')).getNow();
    if (new Date(tokenRecord.expires_at) < now) {
      return apiError('Refresh token expired', 401);
    }

    // 5. Revoke old token
    await db.update(refreshTokens)
      .set({ revoked_at: now })
      .where(eq(refreshTokens.id, tokenRecord.id));

    // 6. Fetch user and issue new tokens
    const response = apiResponse({ success: true, message: 'Token refreshed' });
    const ip = req.headers.get('x-forwarded-for')?.split(',')[0] || 'anonymous';
    const userAgent = req.headers.get('user-agent') || 'Unknown';

    if (type === 'student') {
      const user = await db.query.students.findFirst({ where: eq(students.roll_no, tokenRecord.user_id) });
      if (!user) return apiError('User not found', 401);
      await issueStudentAuthCookie(response, user, true, ip, userAgent);
    } else if (type === 'clerk') {
      const user = await db.query.clerks.findFirst({ where: eq(clerks.email, tokenRecord.user_id) });
      if (!user || !user.is_active) return apiError('User not found or inactive', 401);
      await issueClerkAuthCookie(response, user, true, ip, userAgent);
    } else if (type === 'admin') {
      const user = await db.query.principal.findFirst({ where: eq(principal.email, tokenRecord.user_id) });
      if (!user) return apiError('User not found', 401);
      await issueAdminAuthCookie(response, user, true, ip, userAgent);
    }

    return response;

  } catch (error) {
    logger.error('[AUTH_REFRESH_ERROR]', error);
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { passwordResetTokens, students, clerks, principal } from '@/db/schema';
import { eq, and, isNull, sql } from 'drizzle-orm';
import { apiResponse, apiError } from '@/lib/api-utils';
import bcrypt from 'bcrypt';
import crypto from 'crypto';

export async function GET(req, { params }) {
  try {
    const resolved = params ? await params : { /* empty */ };
    const { token } = resolved || { /* empty */ };
    if (!token) return apiError('INVALID', 400);

    const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
    const tokenData = await db.query.passwordResetTokens.findFirst({
      where: eq(passwordResetTokens.token_hash, tokenHash)
    });

    if (!tokenData) return apiError('INVALID', 400);
    if (tokenData.used_at) return apiError('USED', 409);
    const { getNow } = await import('@/lib/clock');
    if (getNow() > new Date(tokenData.expires_at)) return apiError('EXPIRED', 410);

    return apiResponse({ status: 'VALID' });
  } catch (err) {
    logger.error('RESET TOKEN VALIDATION ERROR:', err);
    return apiError('INVALID', 400);
  }
}

export async function POST(req, { params }) {
  try {
    const resolved = params ? await params : { /* empty */ };
    const { token } = resolved || { /* empty */ };
    const { password } = await req.json();

    if (!token || !password) return apiError('Missing token or password', 400);

    const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
    const tokenData = await db.query.passwordResetTokens.findFirst({
      where: eq(passwordResetTokens.token_hash, tokenHash)
    });

    if (!tokenData) return apiError('INVALID', 400);
    if (tokenData.used_at) return apiError('USED', 409);
    const { getNow } = await import('@/lib/clock');
    if (getNow() > new Date(tokenData.expires_at)) return apiError('EXPIRED', 410);

    const saltRounds = 10;
    const hashedPassword = await bcrypt.hash(password, saltRounds);

    await db.transaction(async (tx) => {
      // 1. Update the appropriate user table
      if (tokenData.user_type === 'student') {
        await tx.update(students).set({ password_hash: hashedPassword }).where(eq(students.roll_no, tokenData.user_id));
      } else if (tokenData.user_type === 'clerk') {
        await tx.update(clerks).set({ password_hash: hashedPassword }).where(eq(clerks.email, tokenData.user_id));
      } else if (tokenData.user_type === 'admin') {
        await tx.update(principal).set({ password_hash: hashedPassword }).where(eq(principal.email, tokenData.user_id));
      } else {
        throw new Error('INVALID_USER_TYPE');
      }

      // 2. Mark token as used
      const [res] = await tx.update(passwordResetTokens)
        .set({ used_at: getNow() })
        .where(and(eq(passwordResetTokens.token_hash, tokenHash), isNull(passwordResetTokens.used_at)));
      
      // Check for concurrent usage
      if (res.affectedRows === 0) {
        throw new Error('TOKEN_ALREADY_USED');
      }
    });

    return apiResponse({ message: 'Password reset successful' });
  } catch (err) {
    if (err.message === 'TOKEN_ALREADY_USED') return apiError('USED', 409);
    logger.error('RESET PASSWORD ERROR:', err);
    return apiError('Internal server error', 500);
  }
}

import { db } from '@/db';
import { securityEvents } from '@/db/schema';
import { eq, and, desc } from 'drizzle-orm';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';
import logger from '@/lib/logger';

export async function GET(req) {
  try {
    // Check if student
    let user = await getAuthUser('student');
    let userType = 'STUDENT';
    
    if (!user) {
      // Check if clerk
      user = await getAuthUser('clerk');
      userType = 'CLERK';
    }

    if (!user) {
      return apiError('Unauthorized', 401);
    }

    // We need the database ID. getAuthUser might return different things based on role.
    // For student it usually returns { roll_no, ... }
    // For clerk it usually returns { email, ... }
    
    let dbId;
    if (userType === 'STUDENT') {
      const student = await db.query.students.findFirst({
        where: (students, { eq }) => eq(students.roll_no, user.roll_no),
        columns: { id: true }
      });
      dbId = student?.id;
    } else {
      const clerk = await db.query.clerks.findFirst({
        where: (clerks, { eq }) => eq(clerks.email, user.email),
        columns: { id: true }
      });
      dbId = clerk?.id;
    }

    if (!dbId) {
      return apiError('User not found', 404);
    }

    const events = await db.select()
      .from(securityEvents)
      .where(
        and(
          eq(securityEvents.user_id, dbId),
          eq(securityEvents.user_type, userType)
        )
      )
      .orderBy(desc(securityEvents.created_at))
      .limit(10);

    return apiResponse({ events });
  } catch (error) {
    logger.error('Error fetching security events:', error);
    return apiError('Internal server error', 500);
  }
}

