        where: (clerks, { eq }) => eq(clerks.email, user.email),
        columns: { id: true }
      });
      dbId = clerk?.id;
    }

    if (markAll) {
      await db
        .update(securityNotifications)
        .set({ is_read: true })
        .where(and(
          eq(securityNotifications.user_id, dbId),
          eq(securityNotifications.user_type, userType)
        ));
