        where: (clerks, { eq }) => eq(clerks.email, user.email),
        columns: { id: true }
      });
      dbId = clerk?.id;
    }

    const success = await SecurityService.revokeSession(userType, dbId, sessionId);
    if (!success) return apiError('Failed to revoke session', 500);

    return apiResponse({ success: true, message: 'Session revoked' });
  } catch (error) {
    logger.error('Error revoking session:', error);
    return apiError('Internal server error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { bugReports } from '@/db/schema';
import { desc, eq, or, like, and } from 'drizzle-orm';
import { apiError, apiResponse, getAuthUser } from '@/lib/api-utils';
import { storage } from '@/lib/providers';
import { checkRateLimit, getTieredKey } from '@/lib/rate-limit';
import crypto from 'crypto';

export async function GET(req) {
  try {
    const { searchParams } = new URL(req.url);
    const typeFilter = searchParams.get('type');
    const statusFilter = searchParams.get('status');
    const severityFilter = searchParams.get('severity');
    const searchQuery = searchParams.get('q');

    let conditions = [];

    if (typeFilter && ['BUG', 'FEATURE_REQUEST'].includes(typeFilter)) {
      conditions.push(eq(bugReports.type, typeFilter));
    }
    if (statusFilter && ['OPEN', 'RESOLVED', 'CLOSED'].includes(statusFilter)) {
      conditions.push(eq(bugReports.status, statusFilter));
    }
    if (severityFilter && ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW'].includes(severityFilter)) {
      conditions.push(eq(bugReports.severity, severityFilter));
    }
    if (searchQuery && searchQuery.trim()) {
      conditions.push(
        or(
          like(bugReports.description, `%${searchQuery.trim()}%`),
          like(bugReports.submitted_by, `%${searchQuery.trim()}%`),
          like(bugReports.affected_page, `%${searchQuery.trim()}%`)
        )
      );
    }

    const reports = await db.query.bugReports.findMany({
      where: conditions.length > 0 ? (and(...conditions)) : undefined,
      orderBy: [desc(bugReports.created_at)]
    });

    return apiResponse(reports);
  } catch (error) {
    logger.error(error, 'Error fetching bug reports');
    return apiError('Failed to fetch bug reports', 500);
  }
}

export async function POST(req) {
  try {
    let clientIp = 'unknown';
    if (req.ip) {
      clientIp = req.ip;
    } else {
      const xForwardedFor = req.headers.get('x-forwarded-for');
      if (xForwardedFor) {
        const ips = xForwardedFor.split(',').map(ip => ip.trim());
        const firstIp = ips[0];
        if (firstIp && firstIp.length > 0) {
          clientIp = firstIp;
        } else {
          clientIp = `req-${crypto.randomBytes(8).toString('hex')}`;
        }
      }
    }

    const rateCheck = await checkRateLimit(getTieredKey(req, 'bugs'), 5, 3600);
    if (!rateCheck.success) {
      return apiError('Too many reports. Please try again later.', 429);
    }

    const user = await getAuthUser();
    if (!user) {
      return apiError('Unauthorized', 401);
    }

    const body = await req.json();
    const { description, screenshot, severity, affected_page, type } = body;

    if (!description) {
      return apiError('Description is required', 400);
    }

    const validTypes = ['BUG', 'FEATURE_REQUEST'];
    const reportType = type && validTypes.includes(type) ? type : 'BUG';

    const validSeverities = ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW'];
    const bugSeverity = severity && validSeverities.includes(severity) ? severity : 'MEDIUM';

    let screenshotUrl = null;
    if (screenshot) {
      try {
        screenshotUrl = await storage.upload(screenshot, 'bug_reports');
      } catch (uploadError) {
        logger.error(uploadError, 'Error uploading bug screenshot');
        return apiError('Failed to upload screenshot', 500);
      }
    }

    let userType = 'student';
    let userIdentifier = user.roll_no || user.email;

    if (user.role) {
      userType = user.role === 'admin' ? 'admin' : 'clerk';
    }

    const browserInfo = req.headers.get('user-agent') || 'Unknown';

    try {
      const [result] = await db.insert(bugReports).values({
        description,
        screenshot_url: screenshotUrl,
        type: reportType,
        status: 'OPEN',
        severity: bugSeverity,
        submitted_by: userIdentifier,
        user_type: userType,
        affected_page: affected_page || null,
        browser_info: browserInfo
      });

      return apiResponse({ success: true, id: result.insertId });
    } catch (insertError) {
      if (screenshotUrl) {
        await storage.delete(screenshotUrl).catch(e => logger.error(e, 'Failed to cleanup orphaned bug screenshot'));
      }
      throw insertError;
    }
  } catch (error) {
    logger.error(error, 'Error creating report');
    return apiError('Failed to submit report', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { academicCalendar, semesters } from '@/db/schema';
import { eq, and, between, sql, notInArray, min, max } from 'drizzle-orm';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';

export async function POST(request) {
  try {
    const user = await getAuthUser('clerk');
    if (!user) return apiError('Unauthorized', 401);
    
    const body = await request.json();
    const { academic_year, semester, start_date, end_date, day_type, holiday_name } = body;

    if (!academic_year || !semester || !start_date || !end_date || !day_type) {
      return apiError('Missing required fields', 400);
    }

    const validDayTypes = ['WORKING', 'HOLIDAY', 'EXAM', 'INTERNAL', 'EVENT'];
    if (!validDayTypes.includes(day_type)) return apiError('Invalid day_type', 400);
    if (day_type === 'HOLIDAY' && !holiday_name) return apiError('Holiday name is required for day_type HOLIDAY', 400);
    
    const startDateObj = new Date(start_date);
    const endDateObj = new Date(end_date);
    if (startDateObj > endDateObj) return apiError('Start date cannot be after end date.', 400);

    const semNum = parseInt(semester);

    const result = await db.transaction(async (tx) => {
      const semesterRange = await tx.select({
        min_date: min(academicCalendar.date),
        max_date: max(academicCalendar.date)
      })
      .from(academicCalendar)
      .where(and(
        eq(academicCalendar.academic_year, academic_year),
        eq(academicCalendar.semester, semNum)
      ));
      
      if (semesterRange.length === 0 || !semesterRange[0].min_date) {
        throw new Error('CALENDAR_NOT_FOUND');
      }

      const minDate = new Date(semesterRange[0].min_date);
      const maxDate = new Date(semesterRange[0].max_date);
      if (startDateObj < minDate || endDateObj > maxDate) {
        throw new Error('OUT_OF_RANGE');
      }

      const finalHolidayName = day_type === 'HOLIDAY' ? holiday_name : null;
      
      let conditions = [
        between(academicCalendar.date, start_date, end_date),
        eq(academicCalendar.academic_year, academic_year),
        eq(academicCalendar.semester, semNum)
      ];

      // Smart Update: If setting days to WORKING, do NOT overwrite that semester's defined weekends.
      if (day_type === 'WORKING') {
        const semData = await tx.query.semesters.findFirst({
          where: and(eq(semesters.academic_year, academic_year), eq(semesters.semester, semNum))
        });

        if (semData && semData.weekend_pattern) {
          const weekendPattern = Array.isArray(semData.weekend_pattern) 
            ? semData.weekend_pattern 
            : JSON.parse(semData.weekend_pattern || '[]');

          if (weekendPattern.length > 0) {
            const dayMap = { 'SUNDAY': 1, 'MONDAY': 2, 'TUESDAY': 3, 'WEDNESDAY': 4, 'THURSDAY': 5, 'FRIDAY': 6, 'SATURDAY': 7 };
            const weekendDayIndexes = weekendPattern.map(day => dayMap[day.toUpperCase()]).filter(d => d);
            if (weekendDayIndexes.length > 0) {
              conditions.push(sql`DAYOFWEEK(${academicCalendar.date}) NOT IN (${sql.join(weekendDayIndexes, sql`, `)})`);
            }
          }
        }
      }

      await tx.update(academicCalendar)
        .set({ day_type, holiday_name: finalHolidayName })
        .where(and(...conditions));
      
      return { success: true };
    });

    return apiResponse({ message: 'Bulk update successful' });

  } catch (error) {
    if (error.message === 'CALENDAR_NOT_FOUND') return apiError('Calendar not generated for this semester.', 404);
    if (error.message === 'OUT_OF_RANGE') return apiError('Bulk update range cannot be outside the generated semester range.', 400);
    logger.error('API_BULK_UPDATE_CALENDAR_ERROR:', error);
    return apiError('Internal Server Error', 500);
  }
}

import { db } from '@/db';
import { 
  students as studentsTable, 
  studentPersonalDetails, 
  studentAcademicBackground,
  studentImportLogs
} from '@/db/schema';
import { eq, inArray } from 'drizzle-orm';
import * as XLSX from 'xlsx-js-style';
import { toMySQLDate, parseDate } from '@/lib/date';
import { apiError, wrapHandler } from '@/lib/api-utils';
import { encrypt, hashForIndex } from '@/lib/encryption';
import { StudentService } from '@/services/StudentService';

// Header normalization: lowercase, trim, spaces & hyphens to _, remove non-word chars
const normalizeHeader = (h) => {
  const s = String(h || '').toLowerCase().trim();
  return s
    .replace(/[\s-]+/g, '_')
    .replace(/[^a-z0-9_]/g, '');
};

const VALID_CATEGORIES = new Set(['OC', 'BC-A', 'BC-B', 'BC-C', 'BC-D', 'BC-E', 'SC', 'ST', 'EWS', 'OC-EWS']);

const ALIASES = {
  students: {
    roll_no: ['roll_no', 'rollnumber', 'roll_number', 'registration_no', 'reg_no', 'regnumber', 'hall_ticket_no', 'studentid', 'ht_no', 'hall_ticket_number'],
    name: ['name', 'candidate_name', 'student_name', 'fullname', 'name_of_this_student', 'name_of_the_candidate'],
    gender: ['gender', 'sex'],
    date_of_birth: ['dob', 'date_of_birth', 'birth_date', 'dateofbirth'],
    mobile: ['mobile', 'phone', 'phone_number', 'mobile_number', 'contact_number', 'mobile_no', 'student_number', 'number'],
    email: ['email', 'mail_id', 'email_id'],
    fee_reimbursement: ['fee_reimbursement', 'fee_reimb', 'reimbursement', 'scholarship'],
  },
  student_personal_details: {
    father_name: ['father_name', 'fathers_name', 'parent_name'],
    blood_group: ['blood_group', 'bloodgroup', 'bg'],
    category: ['category', 'caste_category', 'caste', 'category_cast'],
    permanent_address: ['permanent_address', 'permanentaddress', 'address', 'residential_address', 'aadhar_card_address'],
    contact_address: ['contact_address', 'contactaddress', 'current_address', 'currentaddress', 'present_address', 'presentaddress'],
    mother_name: ['mother_name', 'mothers_name'],
    nationality: ['nationality', 'native_country'],
    religion: ['religion'],
    sub_caste: ['sub_caste', 'subcaste'],
    area_status: ['area_status', 'areastatus', 'area_statu', 'local__non_local'],
    aadhaar_no: ['aadhaar_no', 'aadhaar', 'aadhar', 'aadhar_no', 'uid', 'aadhar_card_number'],
    place_of_birth: ['place_of_birth'],
    father_occupation: ['father_occupation', 'father_work'],
    annual_income: ['annual_income', 'income'],
    identification_marks: ['identification_mark', 'identify_marks'],
    guardian_mobile: ['guardian_mobile', 'parent_mobile', 'emergency_contact']
  },
  student_academic_background: {
    qualifying_exam: ['qualifying_exam', 'qualifyingexam'],
    previous_college_details: ['previous_college_details', 'previouscollege', 'previous_college'],
    medium_of_instruction: ['medium_of_instruction', 'medium', 'medium_of_education', 'language_of_education', 'education_medium'],
    ranks: ['rank', 'intermediate_rank'],
  },
};

function buildHeaderMapping(originalHeaders) {
  const normalized = originalHeaders.map(normalizeHeader);
  const mapping = { /* empty */ };
  normalized.forEach((hdr, idx) => {
    if (!hdr) return;
    let found = false;
    for (const table of Object.keys(ALIASES)) {
      for (const canonical of Object.keys(ALIASES[table])) {
        if (ALIASES[table][canonical].includes(hdr)) {
          mapping[idx] = { field: canonical, table };
          found = true;
          break;
        }
      }
      if (found) break;
    }
  });
  const requiredCanon = ['roll_no', 'name', 'gender', 'date_of_birth', 'father_name', 'category', 'permanent_address'];
  const present = new Set(Object.values(mapping).map((m) => m.field));
  const missing = requiredCanon.filter((f) => !present.has(f));
  return { mapping, normalizedHeaders: normalized, missingRequired: missing };
}

function normalizeGender(value) {
  const v = String(value || '').trim().toLowerCase();
  if (!v) return null;
  if (['male', 'm', 'boy'].includes(v)) return 'Male';
  if (['female', 'f', 'girl'].includes(v)) return 'Female';
  if (['other', 'o', 'others'].includes(v)) return 'Other';
  return null;
}

function normalizeDateToMySQL(value) {
  if (!value && value !== 0) return null;
  if (value instanceof Date && !isNaN(value.getTime())) {
    return value.toISOString().slice(0, 10);
  }
  if (typeof value === 'number') {
    const parsed = XLSX.SSF.parse_date_code(value);
    if (parsed) return `${parsed.y}-${String(parsed.m).padStart(2, '0')}-${String(parsed.d).padStart(2, '0')}`;
    const dt = new Date(Math.round((value - 25569) * 86400 * 1000));
    if (!isNaN(dt.getTime())) return dt.toISOString().slice(0, 10);
    return null;
  }
  const s = String(value);
  const parsedStrDate = parseDate(s);
  if (parsedStrDate) return parsedStrDate.toISOString().slice(0, 10);
  const mysql = toMySQLDate(s);
  if (mysql && /^\d{4}-\d{2}-\d{2}$/.test(mysql)) return mysql;
  return null;
}

export const POST = wrapHandler({
  auth: 'clerk',
  handler: async (req, { user, ip }) => {
    if (user.role !== 'admission') return apiError('Forbidden', 403);

    const clerkId = user.clerkId || user.id;
    const contentType = req.headers.get('content-type') || '';
    let totalRows = 0;
    const errors = [];
    const prepared = [];
    const seenRolls = new Map();
    let importFileName = null;

    let records = [];
    let isJsonInput = false;

    if (contentType.includes('application/json')) {
      const body = await req.json();
      records = body.students || [];
      isJsonInput = true;
    } else {
      const formData = await req.formData();
      const file = formData.get('file');
      if (!file) return apiError('No file uploaded.', 400);
      importFileName = file.name || null;
      const bytes = await file.arrayBuffer();
      const workbook = XLSX.read(bytes, { type: 'array', cellDates: true });
      const worksheet = workbook.Sheets[workbook.SheetNames[0]];
      const sheetRows = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '' });
      if (!sheetRows || sheetRows.length < 2) return apiError('Data empty.', 400);
      
      const headers = sheetRows[0];
      const dataRows = sheetRows.slice(1);
      const { mapping, missingRequired } = buildHeaderMapping(headers);
      if (missingRequired.length > 0) return apiError('Missing required columns', 400);

      records = dataRows.map((rowArray) => {
        const rowObject = { /* empty */ };
        headers.forEach((header, index) => {
          const map = mapping[index];
          if (map) rowObject[map.field] = rowArray[index];
        });
        return rowObject;
      });
    }

    totalRows = records.length;

    for (let i = 0; i < records.length; i++) {
      const record = records[i];
      const rowNumber = i + (isJsonInput ? 1 : 2);
      const student = { /* empty */ };
      const personal = { /* empty */ };
      const academic = { /* empty */ };

      Object.keys(record).forEach(key => {
        if (key.startsWith('_')) return;
        if (ALIASES.students[key]) {
            let val = record[key];
            if (key === 'mobile' && val) {
              const cleanMobile = String(val).replace(/\D/g, '');
              if (cleanMobile.length === 10) {
                student['mobile'] = encrypt(cleanMobile);
                student['mobile_hash'] = hashForIndex(cleanMobile);
              }
            } else {
              student[key] = val;
            }
        }
        else if (ALIASES.student_personal_details[key]) {
            let val = record[key];
            if (key === 'aadhaar_no' && val) {
              const cleanAadhaar = String(val).replace(/\D/g, '');
              if (cleanAadhaar.length === 12) {
                personal['aadhaar_no'] = encrypt(cleanAadhaar);
                personal['aadhaar_hash'] = hashForIndex(cleanAadhaar);
              }
            } else if (key === 'guardian_mobile' && val) {
              const cleanGMobile = String(val).replace(/\D/g, '');
              if (cleanGMobile.length === 10) {
                personal['guardian_mobile'] = encrypt(cleanGMobile);
              }
            } else {
              personal[key] = val;
            }
        }
        else if (ALIASES.student_academic_background[key]) academic[key] = record[key];
      });

      const roll = String(student.roll_no || '').trim();
      if (!roll) { errors.push({ row: rowNumber, roll_no: null, reason: 'Roll number missing' }); continue; }
      if (seenRolls.has(roll)) { errors.push({ row: rowNumber, roll_no: roll, reason: 'Duplicate in file' }); continue; }
      seenRolls.set(roll, rowNumber);

      // Simple Inline Validation
      const gender = normalizeGender(student.gender);
      const dob = normalizeDateToMySQL(student.date_of_birth);
      const name = String(student.name || '').trim();
      const fatherName = String(personal.father_name || '').trim();
      const category = String(personal.category || '').trim().replace(/\s*-\s*/g, '-');
      const permanent_address = String(personal.permanent_address || personal.address || '').trim();
      const contact_address = String(personal.contact_address || '').trim() || permanent_address;

      if (!name || !gender || !dob || !fatherName || !category || !permanent_address || !VALID_CATEGORIES.has(category)) {
        errors.push({ row: rowNumber, roll_no: roll, reason: 'Validation failed (missing or invalid fields)' });
        continue;
      }

      prepared.push({
        student: { ...student, roll_no: roll, name, gender, date_of_birth: dob },
        personal: { ...personal, father_name: fatherName, category, permanent_address, contact_address },
        academic,
        rowNumber
      });
    }

    if (prepared.length === 0) return { totalRows, inserted: 0, updated: 0, skipped: totalRows, errors };

    // Offload to background queue (Upstash QStash)
    const { Queue } = await import('@/lib/queue');
    const CHUNK_SIZE = 50; // Process 50 records per webhook invocation to prevent Vercel timeouts
    
    let queuedChunks = 0;
    const chunkPromises = [];
    for (let i = 0; i < prepared.length; i += CHUNK_SIZE) {
      const chunk = prepared.slice(i, i + CHUNK_SIZE);
      chunkPromises.push(Queue.enqueueBulkImportChunk(chunk, clerkId, importFileName));
    }
    
    try {
      const results = await Promise.all(chunkPromises);
      if (results.some(r => !r || r.success === false)) {
        throw new Error("One or more chunks failed to queue (QStash not configured or error)");
      }
      queuedChunks = chunkPromises.length;
    } catch (enqueueError) {
      return apiError('Failed to queue bulk import tasks: ' + enqueueError.message, 500);
    }

    return {
      message: `Bulk import queued. ${prepared.length} records are being processed in the background across ${queuedChunks} chunks.`,
      totalRows,
      queuedChunks,
      inserted: 0, // Client should check logs later for actual inserted count
      updated: 0,
      skipped: 0,
      errors // Return inline validation errors immediately
    };
  }
});

import logger from '@/lib/logger';
import { db } from '@/db';
import { 
  studentAdmissionDrafts 
} from '@/db/schema';
import { eq } from 'drizzle-orm';
import { apiError, apiResponse, wrapHandler } from '@/lib/api-utils';
import { validateRollNo } from '@/lib/rollNumber';
import { getNow } from '@/lib/clock';
import { z } from 'zod';
import { decrypt } from '@/lib/encryption';

import IdempotencyService from '@/services/IdempotencyService';
import { StudentService } from '@/services/StudentService';

export const POST = wrapHandler({
  auth: 'clerk',
  handler: async (req, { user, context }) => {
    if (user.role !== 'admission') return apiError('Forbidden', 403);

    const idempotencyKey = req.headers.get('idempotency-key');
    let idempotencyStarted = false;

    try {
      const params = await context.params;
      const id = parseInt(params.id);
      const json = await req.json();

      if (idempotencyKey) {
        const { isDuplicate, response, code } = await IdempotencyService.start(idempotencyKey);
        if (isDuplicate) return apiResponse(response, code || 201);
        idempotencyStarted = true;
      }

      // Validate with Zod
      const finalizeSchema = z.object({
        roll_no: z.string().trim().toUpperCase().min(10),
        admission_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional().or(z.literal(''))
      });

      const validatedData = finalizeSchema.parse(json);
      const rollNo = validatedData.roll_no;
      const admissionDateInput = validatedData.admission_date;

      const parsed = validateRollNo(rollNo);
      if (!parsed.isValid) return apiError('Invalid roll number format', 400);

      const result = await db.transaction(async (tx) => {
        // 1. Fetch the full draft data with lock
        const draftRows = await tx.select()
          .from(studentAdmissionDrafts)
          .where(eq(studentAdmissionDrafts.id, id))
          .for('update');

        if (draftRows.length === 0) throw new Error('DRAFT_NOT_FOUND');
        const draft = draftRows[0];
        if (draft.status !== 'PROCESSED') throw new Error('DRAFT_NOT_VERIFIED');

        // Enforce branch + admission type consistency with the draft
        if (String(parsed.branch).toUpperCase() !== String(draft.branch).toUpperCase()) throw new Error('ROLL_BRANCH_MISMATCH');
        const expectedType = String(draft.entrance_exam).toUpperCase() === 'TG ECET' ? 'Lateral' : 'Regular';
        if (String(parsed.admissionType) !== expectedType) throw new Error('ROLL_TYPE_MISMATCH');

        const { getPermanentAddressFromDetails, getContactAddressFromDetails } = require('@/lib/address-utils');

        // 2. Map draft fields to upsert data structure
        const studentData = {
          ...draft,
          roll_no: rollNo,
          date_of_birth: draft.dob,
          admission_date: admissionDateInput || draft.admission_date,
          mobile: decrypt(draft.student_mobile),
          guardian_mobile: draft.guardian_mobile ? decrypt(draft.guardian_mobile) : null,
          aadhaar_no: draft.aadhaar_no ? decrypt(draft.aadhaar_no) : null,
          permanent_address: getPermanentAddressFromDetails(draft),
          contact_address: getContactAddressFromDetails(draft),
          identification_marks: `${draft.identification_mark_1 || ''}\n${draft.identification_mark_2 || ''}`.trim(),
          qualifying_exam: draft.entrance_exam,
          inter_marks: draft.inter_diploma_marks,
          ranks: draft.exam_rank
        };

        // 3. Perform Upsert via Service
        const studentId = await StudentService.upsertStudent(studentData, user.clerkId || user.id, tx);
        if (!studentId) throw new Error('UPSERT_FAILED');

        // 4. Mark draft as FINALIZED and cleanup large strings
        await tx.update(studentAdmissionDrafts)
          .set({ 
            status: "FINALIZED",
            pfp: null,
            signature: null,
            updated_at: getNow()
          })
          .where(eq(studentAdmissionDrafts.id, id));

        return { studentId };
      });

      const responseData = { success: true, studentId: result.studentId, message: 'Student successfully admitted and record created.' };

      if (idempotencyStarted) {
        await IdempotencyService.complete(idempotencyKey, 201, responseData);
      }

      return responseData;

    } catch (error) {
      if (idempotencyStarted) await IdempotencyService.fail(idempotencyKey);
      
      if (error instanceof z.ZodError) return apiError(error.errors?.[0]?.message || 'Invalid input data', 400);
      if (error.message === 'DRAFT_NOT_FOUND') return apiError('Draft not found', 404);
      if (error.message === 'DRAFT_NOT_VERIFIED') return apiError('Only verified drafts can be finalized', 400);
      if (error.message === 'STUDENT_EXISTS') return apiError('A student with this Roll No or Email already exists.', 409);
      if (error.message === 'ROLL_BRANCH_MISMATCH') return apiError('Roll number branch does not match the draft branch.', 400);
      if (error.message === 'ROLL_TYPE_MISMATCH') return apiError('Roll number admission type does not match the draft entrance exam.', 400);
      if (error.message === 'UPSERT_FAILED') return apiError('Student record creation failed.', 500);
      
      logger.error(error, 'Finalization error');
      throw error; // Let wrapHandler handle standard 500
    }
  },
  audit: {
    action: 'FINALIZE_ADMISSION',
    getTargetId: (data, result) => result.studentId,
    getAfter: (data, result) => ({ roll_no: data.roll_no })
  }
});

import logger from '@/lib/logger';
import { db } from '@/db';
import { 
  studentProfileRequests, 
  students as studentsTable, 
  studentPersonalDetails, 
  studentAcademicBackground, 
  studentSignatures, 
  studentImages 
} from '@/db/schema';
import { eq, and, desc, sql } from 'drizzle-orm';
import { apiError, apiResponse, getAuthUser } from '@/lib/api-utils';
import { storage } from '@/lib/providers';
import { decrypt, hashForIndex } from '@/lib/encryption';

export async function GET(req) {
  const user = await getAuthUser('clerk');
  if (!user) return apiError('Unauthorized', 401);

  try {
    const rows = await db.select({
      id: studentProfileRequests.id,
      student_id: studentProfileRequests.student_id,
      roll_no: studentsTable.roll_no,
      name: studentsTable.name,
      new_signature: studentProfileRequests.new_signature,
      new_pfp: studentProfileRequests.new_pfp,
      new_data: studentProfileRequests.new_data,
      proof_url: studentProfileRequests.proof_url,
      old_signature: studentSignatures.signature,
      old_pfp: studentImages.pfp,
      current_email: studentsTable.email,
      current_mobile: studentsTable.mobile,
      current_father_name: studentPersonalDetails.father_name,
      current_mother_name: studentPersonalDetails.mother_name,
      current_nationality: studentPersonalDetails.nationality,
      current_religion: studentPersonalDetails.religion,
      current_category: studentPersonalDetails.category,
      current_sub_caste: studentPersonalDetails.sub_caste,
      current_area_status: studentPersonalDetails.area_status,
      current_mother_tongue: studentPersonalDetails.mother_tongue,
      current_place_of_birth: studentPersonalDetails.place_of_birth,
      current_father_occupation: studentPersonalDetails.father_occupation,
      current_guardian_mobile: studentPersonalDetails.guardian_mobile,
      current_annual_income: studentPersonalDetails.annual_income,
      current_aadhaar_no: studentPersonalDetails.aadhaar_no,
      current_perm_house_no: studentPersonalDetails.perm_house_no,
      current_perm_street: studentPersonalDetails.perm_street,
      current_perm_apartment: studentPersonalDetails.perm_apartment,
      current_perm_city: studentPersonalDetails.perm_city,
      current_perm_state: studentPersonalDetails.perm_state,
      current_perm_pincode: studentPersonalDetails.perm_pincode,
      current_perm_country: studentPersonalDetails.perm_country,
      current_curr_house_no: studentPersonalDetails.curr_house_no,
      current_curr_street: studentPersonalDetails.curr_street,
      current_curr_apartment: studentPersonalDetails.curr_apartment,
      current_curr_city: studentPersonalDetails.curr_city,
      current_curr_state: studentPersonalDetails.curr_state,
      current_curr_pincode: studentPersonalDetails.curr_pincode,
      current_curr_country: studentPersonalDetails.curr_country,
      current_seat_allotted_category: studentPersonalDetails.seat_allotted_category,
      current_identification_marks: studentPersonalDetails.identification_marks,
      current_blood_group: studentPersonalDetails.blood_group,
      current_qualifying_exam: studentAcademicBackground.qualifying_exam,
      current_previous_college_details: studentAcademicBackground.previous_college_details,
      current_medium_of_instruction: studentAcademicBackground.medium_of_instruction,
      current_ranks: studentAcademicBackground.ranks,
      current_ssc_marks: studentAcademicBackground.ssc_marks,
      current_inter_marks: studentAcademicBackground.inter_marks,
      created_at: studentProfileRequests.created_at
    })
    .from(studentProfileRequests)
    .innerJoin(studentsTable, eq(studentProfileRequests.student_id, studentsTable.id))
    .leftJoin(studentPersonalDetails, eq(studentProfileRequests.student_id, studentPersonalDetails.student_id))
    .leftJoin(studentAcademicBackground, eq(studentProfileRequests.student_id, studentAcademicBackground.student_id))
    .leftJoin(studentSignatures, eq(studentProfileRequests.student_id, studentSignatures.student_id))
    .leftJoin(studentImages, eq(studentProfileRequests.student_id, studentImages.student_id))
    .where(eq(studentProfileRequests.status, 'pending'))
    .orderBy(desc(studentProfileRequests.created_at));

    // Deduplicate rows by request ID to prevent duplicates from left joins
    const uniqueRowsMap = new Map();
    for (const row of rows) {
      if (!uniqueRowsMap.has(row.id)) {
        uniqueRowsMap.set(row.id, row);
      }
    }
    const uniqueRows = Array.from(uniqueRowsMap.values());

    const imageHelper = (val) => {
      if (!val) return null;
      if (typeof val === 'string' && (val.startsWith('http') || val.startsWith('data:'))) return val;
      if (Buffer.isBuffer(val)) return `data:image/png;base64,${val.toString('base64')}`;
      return val;
    };

    const data = uniqueRows.map(row => {
      const currentValues = { /* empty */ };
      Object.keys(row).forEach(key => {
        if (key.startsWith('current_')) {
          let val = row[key];
          // Decrypt current values
          if (val && (key === 'current_mobile' || key === 'current_guardian_mobile' || key === 'current_aadhaar_no')) {
              val = decrypt(val);
          }
          currentValues[key.replace('current_', '')] = val;
        }
      });

      const { getPermanentAddressFromDetails, getContactAddressFromDetails } = require('@/lib/address-utils');
      const detailsObj = { /* empty */ };
      Object.keys(row).forEach(key => {
        if (key.startsWith('current_')) {
          detailsObj[key.replace('current_', '')] = row[key];
        }
      });
      currentValues['permanent_address'] = getPermanentAddressFromDetails(detailsObj);
      currentValues['contact_address'] = getContactAddressFromDetails(detailsObj);

      // Decrypt new_data values
      let newData = row.new_data;
      if (newData) {
          const parsed = typeof newData === 'string' ? JSON.parse(newData) : newData;
          if (parsed.mobile) parsed.mobile = decrypt(parsed.mobile);
          if (parsed.guardian_mobile) parsed.guardian_mobile = decrypt(parsed.guardian_mobile);
          if (parsed.aadhaar_no) parsed.aadhaar_no = decrypt(parsed.aadhaar_no);
          newData = parsed;
      }

      return {
        id: row.id,
        student_id: row.student_id,
        roll_no: row.roll_no,
        name: row.name,
        new_signature: imageHelper(row.new_signature),
        new_pfp: imageHelper(row.new_pfp),
        new_data: newData,
        proof_url: imageHelper(row.proof_url),
        old_signature: imageHelper(row.old_signature),
        old_pfp: imageHelper(row.old_pfp),
        current_values: currentValues,
        created_at: row.created_at
      };
    });

    return apiResponse({ data });
  } catch (err) {
    logger.error(err, 'Clerk profile request fetch error');
    return apiError('Server error', 500, err.message);
  }
}

export async function PUT(req) {
  const user = await getAuthUser('clerk');
  if (!user) return apiError('Unauthorized', 401);

  try {
    const body = await req.json();
    const { requestId, action, rejectionReason } = body; 
    if (!requestId || !action) return apiError('Missing parameters', 400);

    const request = await db.query.studentProfileRequests.findFirst({
      where: and(eq(studentProfileRequests.id, requestId), eq(studentProfileRequests.status, 'pending'))
    });

    if (!request) return apiError('Request not found or already processed', 404);

    const { student_id, new_signature, new_pfp, new_data, proof_url } = request;

    if (action === 'approve') {
      await db.transaction(async (tx) => {
        // 1. Update Signature
        if (new_signature) {
          const oldSig = await tx.query.studentSignatures.findFirst({ where: eq(studentSignatures.student_id, student_id) });
          if (oldSig?.signature) await storage.delete(oldSig.signature);
          await tx.insert(studentSignatures)
            .values({ student_id, signature: new_signature })
            .onDuplicateKeyUpdate({ set: { signature: new_signature } });
        }
        
        // 2. Update PFP
        if (new_pfp) {
          const oldPfp = await tx.query.studentImages.findFirst({ where: eq(studentImages.student_id, student_id) });
          if (oldPfp?.pfp) await storage.delete(oldPfp.pfp);
          await tx.insert(studentImages)
            .values({ student_id, pfp: new_pfp })
            .onDuplicateKeyUpdate({ set: { pfp: new_pfp } });
        }

        // 3. Update Text Data
        if (new_data) {
          const data = typeof new_data === 'string' ? JSON.parse(new_data) : new_data;
          
          // Core Student Table Updates
          const studentSets = { /* empty */ };
          if (data.mobile) {
              studentSets.mobile = data.mobile; // Already encrypted in DB
              const plainMobile = decrypt(data.mobile);
              studentSets.mobile_hash = hashForIndex(plainMobile);
          }
          if (data.email) studentSets.email = data.email;
          if (data.name) studentSets.name = data.name;
          if (data.dob) studentSets.date_of_birth = new Date(data.dob);

          if (Object.keys(studentSets).length > 0) {
            await tx.update(studentsTable).set(studentSets).where(eq(studentsTable.id, student_id));
          }

          // Personal Details Updates
          const spd_fields = ['father_name','mother_name','nationality','religion','category','sub_caste','area_status','mother_tongue','place_of_birth','father_occupation','guardian_mobile','annual_income','aadhaar_no','seat_allotted_category','identification_marks','blood_group'];
          const spd_data = { /* empty */ };
          spd_fields.forEach(f => { 
              if (Object.prototype.hasOwnProperty.call(data, f)) {
                  spd_data[f] = data[f];
                  if (f === 'aadhaar_no' && data[f]) {
                      const plainAadhaar = decrypt(data[f]);
                      spd_data['aadhaar_hash'] = hashForIndex(plainAadhaar);
                  }
              }
          });

          if (Object.prototype.hasOwnProperty.call(data, 'contact_address') || Object.prototype.hasOwnProperty.call(data, 'permanent_address')) {
              const existingSPD = await tx.query.studentPersonalDetails.findFirst({ where: eq(studentPersonalDetails.student_id, student_id) });
              const { getPermanentAddressFromDetails, getContactAddressFromDetails, mapAddressStringsToFields } = await import('@/lib/address-utils');
              
              const existingPerm = getPermanentAddressFromDetails(existingSPD);
              const existingContact = getContactAddressFromDetails(existingSPD);

              const finalPerm = Object.prototype.hasOwnProperty.call(data, 'permanent_address') ? data.permanent_address : existingPerm;
              const finalContact = Object.prototype.hasOwnProperty.call(data, 'contact_address') ? data.contact_address : existingContact;

              const addressFields = mapAddressStringsToFields(finalContact, finalPerm);
              Object.assign(spd_data, addressFields);
          }
          
          if (Object.keys(spd_data).length > 0) {
            const existingSPD = await tx.query.studentPersonalDetails.findFirst({ where: eq(studentPersonalDetails.student_id, student_id) });
            if (existingSPD) {
                await tx.update(studentPersonalDetails).set(spd_data).where(eq(studentPersonalDetails.student_id, student_id));
            } else {
                await tx.insert(studentPersonalDetails).values({ student_id, ...spd_data });
            }
          }

          // Academic Background Updates
          const sab_fields = ['qualifying_exam','previous_college_details','medium_of_instruction','ranks','ssc_marks','inter_marks'];
          const sab_data = { /* empty */ };
          sab_fields.forEach(f => { if (Object.prototype.hasOwnProperty.call(data, f)) sab_data[f] = data[f]; });
          
          if (Object.keys(sab_data).length > 0) {
            const existingSAB = await tx.query.studentAcademicBackground.findFirst({ where: eq(studentAcademicBackground.student_id, student_id) });
            if (existingSAB) {
                await tx.update(studentAcademicBackground).set(sab_data).where(eq(studentAcademicBackground.student_id, student_id));
            } else {
                await tx.insert(studentAcademicBackground).values({ student_id, ...sab_data });
            }
          }
        }

        // 4. Update Request Status
        await tx.update(studentProfileRequests)
          .set({ status: "approved", rejection_reason: null, updated_at: new Date() })
          .where(eq(studentProfileRequests.id, requestId));
      });
    } else {
      if (new_pfp) await storage.delete(new_pfp);
      if (new_signature) await storage.delete(new_signature);
      if (proof_url) await storage.delete(proof_url);
      await db.update(studentProfileRequests)
        .set({ status: "rejected", rejection_reason: rejectionReason || 'No reason provided', updated_at: new Date() })
        .where(eq(studentProfileRequests.id, requestId));
    }

    // REAL-TIME
    try {
      const { broadcastUpdate } = await import('@/lib/sse');
      broadcastUpdate('REQUEST_UPDATED', {
        student_id: student_id,
        status: action === 'approve' ? 'APPROVED' : 'REJECTED',
        request_id: requestId,
        certificate_type: 'Profile Update'
      });
    } catch (e) { /* empty */ }

    return apiResponse({ success: true });
  } catch (err) {
    logger.error(err, 'Clerk profile request process error');
    return apiError('Server error', 500, err.message);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { 
  students as studentsTable, 
  studentPersonalDetails, 
  studentAcademicBackground,
  studentImages,
  studentSignatures
} from '@/db/schema';
import { eq, sql } from 'drizzle-orm';
import { toMySQLDate } from '@/lib/date';
import { apiError, apiResponse, getAuthUser } from '@/lib/api-utils';
import { COLLEGE_CONFIG } from '@/lib/college-config';
import { storage } from '@/lib/providers';
import { encrypt, hashForIndex } from '@/lib/encryption';
import { StudentService } from '@/services/StudentService';

const toNull = (value) => (value === undefined || value === '' ? null : value);

/**
 * GET /api/clerk/admission/students/[rollno]
 * Fetch full student profile for admission clerk
 */
export async function GET(req, context) {
  const user = await getAuthUser('clerk');
  if (!user || user.role !== 'admission') {
    return apiError('Forbidden: Only admission clerks can access this data', 403);
  }

  try {
    const params = await context.params;
    let { rollno } = params;
    if (!rollno) return apiError('Missing rollno parameter', 400);

    const profile = await StudentService.getStudentProfile(rollno);
    if (!profile) return apiError('Student not found', 404);

    return apiResponse(profile);
  } catch (error) {
    logger.error(error, 'Error fetching student profile for admission clerk');
    return apiError('Failed to fetch student details', 500, error.message);
  }
}

/**
 * PUT /api/clerk/admission/students/[rollno]
 * Update student details by admission clerk
 */
export async function PUT(req, context) {
  const user = await getAuthUser('clerk');
  if (!user || user.role !== 'admission') {
    return apiError('Forbidden: Only admission clerks can update student details', 403);
  }

  const clerkId = user?.clerkId || user.id || null;
  if (!clerkId) return apiError('Unauthorized: clerk id missing in token', 401);

  try {
    const params = await context.params;
    let { rollno } = params;
    if (!rollno) return apiError('Missing rollno parameter', 400);

    // Normalize Roll Number
    rollno = StudentService.normalizeRollNo(rollno);

    const updatedData = await req.json();

    // Validations
    if (updatedData.blood_group !== undefined) {
      const bg = updatedData.blood_group == null ? null : String(updatedData.blood_group).trim();
      if (bg && !COLLEGE_CONFIG.bloodGroups.includes(bg)) return apiError('Invalid blood group value', 400);
    }
    if (updatedData.fee_reimbursement !== undefined) {
      const fr = updatedData.fee_reimbursement == null ? null : String(updatedData.fee_reimbursement).trim().toUpperCase();
      if (fr && !['YES', 'NO', 'GOV'].includes(fr)) return apiError('Invalid fee_reimbursement value', 400);
    }

    const studentRows = await db.select({ id: studentsTable.id })
      .from(studentsTable)
      .where(eq(studentsTable.roll_no, rollno))
      .limit(1);
    if (studentRows.length === 0) return apiError('Student not found', 404);
    const studentId = studentRows[0].id;

    await db.transaction(async (tx) => {
      // 1. Update Core Students
      const studentUpdate = { /* empty */ };
      if (updatedData.name !== undefined) studentUpdate.name = toNull(updatedData.name);
      if (updatedData.admission_no !== undefined) studentUpdate.admission_no = toNull(updatedData.admission_no);
      if (updatedData.admission_date !== undefined) studentUpdate.admission_date = toMySQLDate(updatedData.admission_date) ? new Date(toMySQLDate(updatedData.admission_date)) : null;
      if (updatedData.academic_status !== undefined) studentUpdate.academic_status = toNull(String(updatedData.academic_status).trim().toUpperCase());
      if (updatedData.academic_offset_years !== undefined) studentUpdate.academic_offset_years = parseInt(updatedData.academic_offset_years) || 0;
      if (updatedData.fee_reimbursement !== undefined) studentUpdate.fee_reimbursement = toNull(String(updatedData.fee_reimbursement).trim().toUpperCase());
      if (updatedData.date_of_birth !== undefined) studentUpdate.date_of_birth = toMySQLDate(updatedData.date_of_birth) ? new Date(toMySQLDate(updatedData.date_of_birth)) : null;
      if (updatedData.gender !== undefined) studentUpdate.gender = toNull(updatedData.gender);
      
      if (updatedData.mobile !== undefined) {
          const val = toNull(updatedData.mobile);
          const normalizedMobile = val ? String(val).replace(/\D/g, '') : null;
          studentUpdate.mobile = normalizedMobile ? encrypt(normalizedMobile) : null;
          studentUpdate.mobile_hash = normalizedMobile ? hashForIndex(normalizedMobile) : null;
      }
      
      if (updatedData.email !== undefined) studentUpdate.email = toNull(updatedData.email);

      if (Object.keys(studentUpdate).length > 0) {
        await tx.update(studentsTable)
          .set({ ...studentUpdate, updated_at: new Date(), updated_by_clerk_id: clerkId })
          .where(eq(studentsTable.id, studentId));
      } else {
        // Just audit update if other tables change
        await tx.update(studentsTable)
          .set({ updated_at: new Date(), updated_by_clerk_id: clerkId })
          .where(eq(studentsTable.id, studentId));
      }

      // 2. Update Personal Details
      const personalFields = [
        'father_name', 'mother_name', 'nationality', 'religion', 'category', 'sub_caste', 'area_status', 'mother_tongue', 'place_of_birth', 'father_occupation', 'annual_income', 'guardian_mobile', 'aadhaar_no', 'seat_allotted_category', 'identification_marks', 'blood_group',
        'perm_house_no', 'perm_street', 'perm_apartment', 'perm_city', 'perm_state', 'perm_pincode', 'perm_country',
        'curr_house_no', 'curr_street', 'curr_apartment', 'curr_city', 'curr_state', 'curr_pincode', 'curr_country',
        'is_current_same_as_permanent'
      ];
      const personalUpdate = { /* empty */ };
      personalFields.forEach(col => {
        if (updatedData[col] !== undefined) {
          let val = toNull(updatedData[col]);
          
          if (col === 'aadhaar_no' && val !== null) {
            val = String(val).replace(/\D/g, '');
            personalUpdate.aadhaar_no = encrypt(val);
            personalUpdate.aadhaar_hash = hashForIndex(val);
          } else if (col === 'guardian_mobile' && val !== null) {
            personalUpdate.guardian_mobile = encrypt(val);
          } else if (col === 'is_current_same_as_permanent') {
            personalUpdate.is_current_same_as_permanent = val === null ? null : !!val;
          } else {
            personalUpdate[col] = val;
          }
        }
      });

      // Handle address mapping
      if (updatedData.contact_address !== undefined || updatedData.permanent_address !== undefined || updatedData.address !== undefined) {
        const existingSPD = await tx.query.studentPersonalDetails.findFirst({ where: eq(studentPersonalDetails.student_id, studentId) });
        const { getPermanentAddressFromDetails, getContactAddressFromDetails, mapAddressStringsToFields } = require('@/lib/address-utils');
        
        const existingPerm = getPermanentAddressFromDetails(existingSPD);
        const existingContact = getContactAddressFromDetails(existingSPD);

        const finalPerm = updatedData.permanent_address !== undefined ? updatedData.permanent_address : (updatedData.address !== undefined ? updatedData.address : existingPerm);
        const finalContact = updatedData.contact_address !== undefined ? updatedData.contact_address : existingContact;

        const addressFields = mapAddressStringsToFields(finalContact, finalPerm);
        Object.assign(personalUpdate, addressFields);
      }

      if (Object.keys(personalUpdate).length > 0) {
        const existing = await tx.select({ id: studentPersonalDetails.id })
          .from(studentPersonalDetails)
          .where(eq(studentPersonalDetails.student_id, studentId))
          .limit(1);

        if (existing.length > 0) {
          await tx.update(studentPersonalDetails)
            .set(personalUpdate)
            .where(eq(studentPersonalDetails.student_id, studentId));
        } else {
          await tx.insert(studentPersonalDetails)
            .values({ student_id: studentId, ...personalUpdate });
        }
      }

      // 3. Update Academic Background
      const academicFields = ['qualifying_exam', 'previous_college_details', 'medium_of_instruction', 'ranks', 'ssc_marks', 'inter_marks'];
      const academicUpdate = { /* empty */ };
      academicFields.forEach(col => {
        if (updatedData[col] !== undefined) academicUpdate[col] = toNull(updatedData[col]);
      });

      if (Object.keys(academicUpdate).length > 0) {
        const existing = await tx.select({ id: studentAcademicBackground.id })
          .from(studentAcademicBackground)
          .where(eq(studentAcademicBackground.student_id, studentId))
          .limit(1);

        if (existing.length > 0) {
          await tx.update(studentAcademicBackground)
            .set(academicUpdate)
            .where(eq(studentAcademicBackground.student_id, studentId));
        } else {
          await tx.insert(studentAcademicBackground)
            .values({ student_id: studentId, ...academicUpdate });
        }
      }

      // 4. Update Images
      if (updatedData.pfp) {
        const pfpUrl = await storage.upload(updatedData.pfp, 'students/pfp');
        await tx.insert(studentImages)
          .values({ student_id: studentId, pfp: pfpUrl })
          .onDuplicateKeyUpdate({ set: { pfp: pfpUrl } });
      }
      if (updatedData.signature) {
        const sigUrl = await storage.upload(updatedData.signature, 'students/signatures');
        await tx.insert(studentSignatures)
          .values({ student_id: studentId, signature: sigUrl })
          .onDuplicateKeyUpdate({ set: { signature: sigUrl } });
      }
    });

    return apiResponse({ success: true, message: 'Student details updated successfully' });
  } catch (error) {
    logger.error(error, 'Error updating student details for clerk');
    return apiError('Failed to update student details', 500, error.message);
  }
}

import { apiError, apiResponse, wrapHandler } from '@/lib/api-utils';
import { StudentService } from '@/services/StudentService';
