import logger from '@/lib/logger';
import { db } from '@/db';
import { facultySubjectAssignments, collegeInfo as collegeInfoTable } from '@/db/schema';
import { eq, and, desc, asc, sql } from 'drizzle-orm';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';
import { isSemesterActive } from '@/lib/academic-utils';

export async function GET(request) {
  try {
    const user = await getAuthUser('clerk');
    if (!user || user.role !== 'faculty') {
      return apiError('Unauthorized', 401);
    }

    const assignments = await db.select({
      id: facultySubjectAssignments.id,
      faculty_id: facultySubjectAssignments.faculty_id,
      subject_code: facultySubjectAssignments.subject_code,
      subject_name: facultySubjectAssignments.subject_name,
      branch: facultySubjectAssignments.branch,
      course_semester: facultySubjectAssignments.course_semester,
      semester: facultySubjectAssignments.course_semester,
      academic_term: facultySubjectAssignments.academic_term,
      academic_year: facultySubjectAssignments.academic_year,
      created_at: facultySubjectAssignments.created_at,
      is_active: facultySubjectAssignments.is_active,
      mid_max: facultySubjectAssignments.mid_max
    })
    .from(facultySubjectAssignments)
    .where(eq(facultySubjectAssignments.faculty_id, user.id))
    .orderBy(desc(facultySubjectAssignments.academic_year), asc(facultySubjectAssignments.course_semester));

    // Get college info for activity check
    const collegeRows = await db.select().from(collegeInfoTable).where(eq(collegeInfoTable.id, 1)).limit(1);
    const collegeInfo = collegeRows[0] || null;

    const assignmentsWithActivity = await Promise.all(assignments.map(async (asgn) => ({
      ...asgn,
      is_active: await isSemesterActive(asgn.course_semester, asgn.academic_year, collegeInfo)
    })));

    return apiResponse({ data: assignmentsWithActivity });
  } catch (error) {
    logger.error('Assignments Fetch Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { 
  attendanceSessions, 
  facultySubjectAssignments,
  facultySubstitutions
} from '@/db/schema';
import { eq, and, gt, sql } from 'drizzle-orm';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';
import crypto from 'crypto';

/**
 * GET /api/clerk/faculty/attendance/session?assignment_id=X
 * Check if there is an active session for the assignment
 */
export async function GET(request) {
  try {
    const user = await getAuthUser('clerk');
    if (!user || user.role !== 'faculty') {
      return apiError('Unauthorized', 401);
    }

    const { searchParams } = new URL(request.url);
    const assignment_id = searchParams.get('assignment_id') ? parseInt(searchParams.get('assignment_id')) : null;

    if (!assignment_id) {
      return apiError('Missing assignment_id', 400);
    }

    const { getNow } = await import('@/lib/clock');
    const sessions = await db.select({
      id: attendanceSessions.id,
      session_pin: attendanceSessions.session_pin,
      session_token: attendanceSessions.session_token,
      expires_at: attendanceSessions.expires_at,
      session_number: attendanceSessions.session_number,
      faculty_id: attendanceSessions.faculty_id
    })
    .from(attendanceSessions)
    .where(and(
      eq(attendanceSessions.assignment_id, assignment_id),
      eq(attendanceSessions.is_active, true),
      gt(attendanceSessions.expires_at, getNow())
    ))
    .limit(1);

    if (sessions.length === 0) {
      return apiResponse({ active: false });
    }

    // A session is active, check if the current user is the one who started it OR is authorized
    return apiResponse({ active: true, session: sessions[0] });
  } catch (error) {
    logger.error('Fetch Session Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

/**
 * POST /api/clerk/faculty/attendance/session
 * Create a new attendance session
 */
export async function POST(request) {
  try {
    const user = await getAuthUser('clerk');
    if (!user || user.role !== 'faculty') {
      return apiError('Unauthorized', 401);
    }

    const body = await request.json();
    const { assignment_id, latitude, longitude, accuracy, attendance_date, session_number } = body;

    if (!assignment_id || !attendance_date) {
      return apiError('Missing assignment_id or attendance_date', 400);
    }

    // 1. Verify assignment existence and get details
    const assignments = await db.select({
      id: facultySubjectAssignments.id,
      branch: facultySubjectAssignments.branch,
      subject_code: facultySubjectAssignments.subject_code,
      faculty_id: facultySubjectAssignments.faculty_id
    })
    .from(facultySubjectAssignments)
    .where(eq(facultySubjectAssignments.id, assignment_id))
    .limit(1);

    if (assignments.length === 0) {
      return apiError('Assignment not found', 404);
    }

    const targetAssignment = assignments[0];

    // 2. Authorization logic (Primary Faculty, HOD, or Substitute)
    let isAuthorized = false;
    let authType = 'PRIMARY';

    if (targetAssignment.faculty_id === user.id) {
      isAuthorized = true;
    } else if (user.is_hod && user.branch === targetAssignment.branch) {
      isAuthorized = true;
      authType = 'HOD_OVERRIDE';
    } else {
      // Check for active substitution on this date
      const substitution = await db.select()
        .from(facultySubstitutions)
        .where(and(
          eq(facultySubstitutions.original_assignment_id, assignment_id),
          eq(facultySubstitutions.substitute_faculty_id, user.id),
          eq(facultySubstitutions.substitution_date, attendance_date)
        ))
        .limit(1);
      
      if (substitution.length > 0) {
        isAuthorized = true;
        authType = 'SUBSTITUTE';
      }
    }

    if (!isAuthorized) {
      return apiError('You are not authorized to start a session for this assignment (Not primary, HOD, or substitute)', 403);
    }

    // 3. Deactivate any existing sessions for this assignment
    await db.update(attendanceSessions)
      .set({ is_active: false })
      .where(eq(attendanceSessions.assignment_id, assignment_id));

    // 4. Generate PIN and Token
    const sessionPin = crypto.randomInt(1000, 9999).toString();
    const sessionToken = crypto.randomBytes(32).toString('hex');
    
    // Session valid for 10 minutes by default
    const { getNow } = await import('@/lib/clock');
    const now = getNow();
    const expiresAt = new Date(now.getTime() + 10 * 60 * 1000);

    // 5. Create new session
    const [result] = await db.insert(attendanceSessions).values({
      assignment_id: assignment_id,
      faculty_id: user.id,
      session_pin: sessionPin,
      session_token: sessionToken,
      latitude: latitude ? String(latitude) : null,
      longitude: longitude ? String(longitude) : null,
      accuracy: accuracy ? parseFloat(accuracy) : null,
      attendance_date: attendance_date,
      session_number: session_number || 1,
      expires_at: expiresAt,
      is_active: true
    });

    // --- REAL-TIME: Notify Students/HOD ---
    try {
      const { broadcastUpdate } = await import('@/lib/sse');
      broadcastUpdate('SESSION_STARTED', { 
        assignment_id, 
        faculty_id: user.id, 
        branch: targetAssignment.branch,
        subject_code: targetAssignment.subject_code,
        sessionId: result.insertId,
        session_number: session_number || 1,
        auth_type: authType
      });
    } catch (sseErr) {
      console.warn('[SSE] Broadcast failed:', sseErr);
    }

    return apiResponse({
      message: `Session created successfully (${authType})`,
      session: {
        id: result.insertId,
        session_pin: sessionPin,
        session_token: sessionToken,
        expires_at: expiresAt,
        session_number: session_number || 1
      }
    });
  } catch (error) {
    logger.error('Create Session Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

/**
 * DELETE /api/clerk/faculty/attendance/session
 * Manually end a session
 */
export async function DELETE(request) {
  try {
    const user = await getAuthUser('clerk');
    if (!user || user.role !== 'faculty') {
      return apiError('Unauthorized', 401);
    }

    const { searchParams } = new URL(request.url);
    const assignment_id = searchParams.get('assignment_id') ? parseInt(searchParams.get('assignment_id')) : null;

    if (!assignment_id) {
      return apiError('Missing assignment_id', 400);
    }

    await db.update(attendanceSessions)
      .set({ is_active: false })
      .where(and(
        eq(attendanceSessions.assignment_id, assignment_id),
        eq(attendanceSessions.faculty_id, user.id),
        eq(attendanceSessions.is_active, true)
      ));

    // --- REAL-TIME: Notify Students/HOD ---
    try {
      const asgnRows = await db.select({ branch: facultySubjectAssignments.branch })
        .from(facultySubjectAssignments)
        .where(eq(facultySubjectAssignments.id, assignment_id))
        .limit(1);
        
      const { broadcastUpdate } = await import('@/lib/sse');
      broadcastUpdate('SESSION_ENDED', { 
        assignment_id, 
        faculty_id: user.id, 
        branch: asgnRows[0]?.branch || user.branch 
      });
    } catch (sseErr) {
      console.warn('[SSE] Broadcast failed:', sseErr);
    }

    return apiResponse({ message: 'Session ended successfully' });
  } catch (error) {
    logger.error('End Session Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { 
  facultySubjectAssignments, 
  studentAttendance, 
  attendanceSessionLogs, 
  attendanceSessions 
} from '@/db/schema';
import { eq, and, asc, sql } from 'drizzle-orm';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';

export async function GET(request) {
  try {
    const user = await getAuthUser('clerk');
    if (!user || user.role !== 'faculty') {
      return apiError('Unauthorized', 401);
    }

    const { searchParams } = new URL(request.url);
    const assignment_id = searchParams.get('assignment_id') ? parseInt(searchParams.get('assignment_id')) : null;
    const date = searchParams.get('date');
    const session = searchParams.get('session') ? parseInt(searchParams.get('session')) : 1;

    if (!assignment_id || !date) {
      return apiError('assignment_id and date are required', 400);
    }

    // Verify assignment belongs to faculty
    const assignments = await db.select({
      id: facultySubjectAssignments.id,
      subject_code: facultySubjectAssignments.subject_code,
      branch: facultySubjectAssignments.branch,
      course_semester: facultySubjectAssignments.course_semester,
      academic_year: facultySubjectAssignments.academic_year
    })
    .from(facultySubjectAssignments)
    .where(and(
      eq(facultySubjectAssignments.id, assignment_id),
      eq(facultySubjectAssignments.faculty_id, user.id)
    ))
    .limit(1);

    if (assignments.length === 0) {
      return apiError('Assignment not found or unauthorized', 404);
    }

    const assignment = assignments[0];
    const { subject_code, branch, course_semester, academic_year } = assignment;

    // --- SHARED DATA LOGIC: Canonical ID ---
    const canonicalRows = await db.select({ id: facultySubjectAssignments.id })
      .from(facultySubjectAssignments)
      .where(and(
        eq(facultySubjectAssignments.subject_code, subject_code),
        eq(facultySubjectAssignments.branch, branch),
        eq(facultySubjectAssignments.course_semester, course_semester),
        eq(facultySubjectAssignments.academic_year, academic_year)
      ))
      .orderBy(asc(facultySubjectAssignments.created_at))
      .limit(1);
    
    const targetAssignmentId = canonicalRows[0]?.id || assignment_id;

    // Lightweight fetch of attendance statuses for the specific date+session
    const rows = await db.select({
      student_id: studentAttendance.student_id,
      status: studentAttendance.status
    })
    .from(studentAttendance)
    .where(and(
      eq(studentAttendance.assignment_id, targetAssignmentId),
      eq(studentAttendance.date, date),
      eq(studentAttendance.session, session)
    ));

    // Also return which sessions have records for this date
    const sessRows = await db.select({ session: studentAttendance.session })
      .from(studentAttendance)
      .where(and(
        eq(studentAttendance.assignment_id, targetAssignmentId),
        eq(studentAttendance.date, date)
      ))
      .groupBy(studentAttendance.session)
      .orderBy(asc(studentAttendance.session));

    const sessions = sessRows.map(r => r.session);

    // --- FETCH SELF-VERIFIED STUDENTS ---
    const logRows = await db.select({ student_id: attendanceSessionLogs.student_id })
      .from(attendanceSessionLogs)
      .innerJoin(attendanceSessions, eq(attendanceSessionLogs.session_id, attendanceSessions.id))
      .where(and(
        eq(attendanceSessions.assignment_id, assignment_id),
        eq(attendanceSessions.attendance_date, date),
        eq(attendanceSessions.is_active, true),
        eq(attendanceSessionLogs.status, 'SUCCESS')
      ));

    const verified_ids = logRows.map(r => r.student_id);

    return apiResponse({ data: rows, sessions, verified_ids });
  } catch (error) {
    logger.error('Attendance Status Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { branchTimetable, syllabusSubjects, semesters } from '@/db/schema';
import { eq, and, desc, sql, like, or } from 'drizzle-orm';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';
import { getNow } from '@/lib/clock';

export async function GET(req) {
  try {
    const user = await getAuthUser('clerk');
    if (!user || user.role !== 'faculty') return apiError('Unauthorized', 401);

    const now = await getNow();
    const days = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
    const day = days[now.getDay()]; 
    const time = now.getHours() * 100 + now.getMinutes(); 

    let period = null;
    if (time >= 930 && time < 1020) period = 1;
    else if (time >= 1020 && time < 1110) period = 2;
    else if (time >= 1120 && time < 1210) period = 3;
    else if (time >= 1210 && time < 1300) period = 4;
    else if (time >= 1400 && time < 1450) period = 5;
    else if (time >= 1450 && time < 1540) period = 6;
    else if (time >= 1540 && time < 1630) period = 7;

    if (!period || day === 'SUN') {
      return apiResponse({ active: false, message: 'Outside college hours or Weekend' });
    }

    const clerkId = user.id || user.clerkId;
    const semRows = await db.select({ academic_year: semesters.academic_year })
      .from(semesters)
      .orderBy(desc(semesters.id))
      .limit(1);
    const systemYear = semRows[0]?.academic_year || '2025-26';
    const yearPattern = `%${systemYear.substring(0, 4)}%`;

    const rows = await db.select({
      branch: branchTimetable.branch,
      semester: branchTimetable.semester,
      room_no: branchTimetable.room_no,
      subject_name: sql`COALESCE(${syllabusSubjects.subject_name}, ${branchTimetable.subject_code})`,
      subject_code: branchTimetable.subject_code
    })
    .from(branchTimetable)
    .leftJoin(syllabusSubjects, eq(branchTimetable.subject_code, syllabusSubjects.subject_code))
    .where(and(
      eq(branchTimetable.faculty_id, clerkId),
      eq(branchTimetable.day_of_week, day),
      eq(branchTimetable.period_number, period),
      or(
        like(branchTimetable.academic_year, yearPattern),
        eq(branchTimetable.academic_year, '2025-26')
      )
    ))
    .limit(1);

    if (rows.length === 0) {
      return apiResponse({ active: false, message: 'Free period' });
    }

    return apiResponse({ active: true, period, activity: rows[0] });
  } catch (error) {
    logger.error('Current Activity API Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

