export async function POST(req) {
  try {
    const user = await getAuthUser('clerk');
    if (!user || user.role !== 'faculty' || !user.is_hod) {
      return apiError('Unauthorized', 401);
    }

    const json = await req.json();

    // Validate with Zod
    const validationSchema = timetableSlotSchema.extend({
      id: z.number().int().positive().optional(),
      version: z.number().int().min(0).optional(),
      section: z.string().trim().max(1).toUpperCase().default('A'),
      academic_year: z.string().regex(/^\d{4}-\d{2}$/, "Format: YYYY-YY").default('2025-26'),
      semester: z.number().int().min(1).max(8),
      faculty_id: z.preprocess(
        (v) => (v === '' || v === undefined || v === null) ? null : Number(v),
        z.number().int().positive().nullable()
      )
    });

    const validatedData = validationSchema.parse(json);
    const { 
      id, version, semester, section, day_of_week, period_number, 
      subject_code, faculty_id, academic_year, room_no 
    } = validatedData;

    if (faculty_id) {
      const yearPrefix = academic_year.substring(0, 7);
      const isEvenSem = semester % 2 === 0;
      
      const conflictRows = await db.select({
        branch: branchTimetable.branch,
        semester: branchTimetable.semester,
        section: branchTimetable.section,
        subject_code: branchTimetable.subject_code,
        subject_name: syllabusSubjects.subject_name
      })
      .from(branchTimetable)
      .leftJoin(syllabusSubjects, eq(branchTimetable.subject_code, syllabusSubjects.subject_code))
      .where(and(
        eq(branchTimetable.faculty_id, faculty_id),
        eq(branchTimetable.day_of_week, day_of_week),
        eq(branchTimetable.period_number, period_number),
        or(
          like(branchTimetable.academic_year, `%${yearPrefix}%`),
          eq(branchTimetable.academic_year, academic_year)
        ),
        // Term Parity Check: Only conflict if both are Odd or both are Even
        sql`(${branchTimetable.semester} % 2 = 0) = ${isEvenSem}`,
        // Don't conflict with itself
        id ? ne(branchTimetable.id, id) : sql`NOT (${eq(branchTimetable.branch, user.branch)} AND ${eq(branchTimetable.semester, semester)} AND ${eq(branchTimetable.section, section)})`
      ))
      .limit(1);

      if (conflictRows.length > 0) {
        const c = conflictRows[0];
        return apiError(`Faculty Conflict: This instructor is already assigned to ${c.subject_name || c.subject_code} in ${c.branch} Sem ${c.semester} (Sec ${c.section}) during this period.`, 400);
      }
    }

    const slotData = {
      branch: user.branch,
      semester: semester,
      section: section,
      day_of_week: day_of_week,
      period_number: period_number,
      subject_code: subject_code,
      faculty_id: faculty_id,
      academic_year: academic_year,
      room_no: room_no
    };

    if (id) {
      // Optimistic Locking Update
      const success = await FacultyService.updateTimetableAtomic(id, slotData, version || 0);
      if (!success) {
        return apiError('Concurrency Conflict: This timetable slot was modified by another user. Please refresh.', 409);
      }
    } else {
      // New Slot or Coordinate-based upsert if ID is missing but slot exists
      await db.insert(branchTimetable).values(slotData)
      .onDuplicateKeyUpdate({
        set: {
          subject_code: sql`VALUES(subject_code)`,
          faculty_id: sql`VALUES(faculty_id)`,
          room_no: sql`VALUES(room_no)`,
          version: sql`version + 1`
        }
      });
    }

    // REAL-TIME
    try {
      const { broadcastUpdate } = await import('@/lib/sse');
      broadcastUpdate('TIMETABLE_CHANGED', { branch: user.branch, semester });
    } catch (e) { /* empty */ }

    return apiResponse({ success: true, message: 'Slot updated successfully' });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return apiError(error.errors?.[0]?.message || 'Invalid input data', 400);
    }
    logger.error('Timetable Save Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

export async function DELETE(req) {
  try {
    const user = await getAuthUser('clerk');
    if (!user || user.role !== 'faculty' || !user.is_hod) {
      return apiError('Unauthorized', 401);
    }

    const { searchParams } = new URL(req.url);
    const action = searchParams.get('action'); // 'clearSemester' or 'clearAll'
    const semester = searchParams.get('semester');
    const section = searchParams.get('section') || 'A';
    const day_of_week = searchParams.get('day_of_week');
    const period_number = searchParams.get('period_number');

    if (action === 'clearSemester') {
      if (!semester) return apiError('Missing semester', 400);
      await db.delete(branchTimetable)
        .where(and(
          eq(branchTimetable.branch, user.branch),
          eq(branchTimetable.semester, parseInt(semester)),
          eq(branchTimetable.section, section)
        ));
    } 
    else if (action === 'clearAll') {
      await db.delete(branchTimetable)
        .where(eq(branchTimetable.branch, user.branch));
    }
    else {
      // Single slot deletion
      if (!semester || !day_of_week || !period_number) {
        return apiError('Missing required parameters', 400);
      }

      await db.delete(branchTimetable)
        .where(and(
          eq(branchTimetable.branch, user.branch),
          eq(branchTimetable.semester, parseInt(semester)),
          eq(branchTimetable.section, section),
          eq(branchTimetable.day_of_week, day_of_week),
          eq(branchTimetable.period_number, parseInt(period_number))
        ));
    }

    // REAL-TIME
    try {
      const { broadcastUpdate } = await import('@/lib/sse');
      broadcastUpdate('TIMETABLE_CHANGED', { branch: user.branch, semester: semester ? parseInt(semester) : 'ALL' });
    } catch (e) { /* empty */ }

    return apiResponse({ success: true, message: 'Timetable data updated successfully' });
  } catch (error) {
    logger.error('Timetable Delete Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { studentRequests, students, clerks } from '@/db/schema';
import { eq, and, sql } from 'drizzle-orm';
import { apiResponse, apiError, getAuthUser, logAudit } from '@/lib/api-utils';
import { getNow } from '@/lib/clock';
import crypto from 'crypto';

const clerkToTypes = {
    admission: [
        'Bonafide Certificate', 'No Objection Certificate', 'Course Completion Certificate',
        'Transfer Certificate (TC)', 'Migration Certificate', 'Study Conduct Certificate',
    ],
    scholarship: ['Income Tax (IT) Certificate', 'Custodian Certificate'],
};

export async function PUT(request, { params }) {
    const clerk = await getAuthUser('clerk');
    if (!clerk) return apiError('Unauthorized', 401);
    if (!clerk.id) return apiError('Clerk identity missing. Approval blocked.', 500);

    const resolvedParams = await params;
    const { request_id } = resolvedParams;
    const requestIdNum = parseInt(request_id);

    const body = await request.json();
    let { status } = body;
    const reject_reason = body.reject_reason;
    if (!status) return apiError('Status is required', 400);
    
    status = String(status).toUpperCase();
    if (!['APPROVED', 'REJECTED'].includes(status)) return apiError('Invalid status', 400);

    try {
        const rows = await db.select({
            certificate_type: studentRequests.certificate_type,
            generated_certificate_id: studentRequests.generated_certificate_id,
            student_id: studentRequests.student_id,
            roll_no: students.roll_no,
            status: studentRequests.status
        })
        .from(studentRequests)
        .innerJoin(students, eq(studentRequests.student_id, students.id))
        .where(eq(studentRequests.request_id, requestIdNum))
        .limit(1);

        if (rows.length === 0) return apiError('Request not found', 404);
        const requestToUpdate = rows[0];
        if (requestToUpdate.status !== 'PENDING') {
            return apiError('This request has already been processed', 409);
        }

        const allowedTypes = clerkToTypes[clerk.role] || [];
        if (!allowedTypes.includes(requestToUpdate.certificate_type)) return apiError('Forbidden', 403);

        let generatedCertId = requestToUpdate.generated_certificate_id;
        if (status === 'APPROVED' && !generatedCertId) {
            const SECRET_SALT = process.env.CERTIFICATE_SECRET || 'fallback_salt';
            const hash = crypto.createHmac('sha256', SECRET_SALT)
                               .update(`${requestToUpdate.roll_no}-${requestToUpdate.certificate_type}-${requestIdNum}`)
                               .digest('hex');
            generatedCertId = `KUCET-${hash.substring(0, 8).toUpperCase()}`;
        }

        const now = getNow();
        const updateData = { status, updated_at: now };

        if (status === 'REJECTED') {
            if (!reject_reason || String(reject_reason).trim().length === 0) return apiError('Rejection reason is required', 400);
            updateData.reject_reason = String(reject_reason).trim();
            updateData.completed_at = now;
            updateData.action_by_clerk_id = clerk.id;
            updateData.action_by_role = clerk.role;
        } else if (status === 'APPROVED') {
            updateData.reject_reason = null;
            updateData.completed_at = now;
            updateData.action_by_clerk_id = clerk.id;
            updateData.action_by_role = clerk.role;
            updateData.generated_certificate_id = generatedCertId;
        }

        const [result] = await db.update(studentRequests)
            .set(updateData)
            .where(and(
                eq(studentRequests.request_id, requestIdNum),
                eq(studentRequests.status, 'PENDING')
            ));

        if (result.affectedRows === 1) {
            // Audit Log
            await logAudit(request, {
                userId: clerk.id,
                userType: 'clerk',
                action: status === 'APPROVED' ? 'APPROVE_CERTIFICATE' : 'REJECT_CERTIFICATE',
                targetId: requestIdNum,
                targetType: 'certificate_request',
                before: { status: requestToUpdate.status },
                after: { status: status, reject_reason: updateData.reject_reason, cert_id: updateData.generated_certificate_id }
            });

            // REAL-TIME
            try {
                const { broadcastUpdate } = await import('@/lib/sse');
                broadcastUpdate('REQUEST_UPDATED', {
                    student_id: requestToUpdate.student_id,
                    status,
                    request_id: requestIdNum,
                    certificate_type: requestToUpdate.certificate_type
                });
            } catch (e) { /* empty */ }
            return apiResponse({ success: true });
        } else {
            return apiError('This request has already been processed', 409);
        }
    } catch (error) {
        logger.error("Error updating request:", error);
        return apiError('An error occurred while updating the request', 500, error.message);
    }
}

export async function GET(request, { params }) {
    const clerk = await getAuthUser('clerk');
    if (!clerk) return apiError('Unauthorized', 401);

    const resolvedParams = await params;
    const { request_id } = resolvedParams;
    const requestIdNum = parseInt(request_id);

    try {
        const rows = await db.select({
            request_id: studentRequests.request_id,
            roll_number: students.roll_no,
            student_name: students.name,
            certificate_type: studentRequests.certificate_type,
            status: studentRequests.status,
            payment_amount: studentRequests.payment_amount,
            transaction_id: studentRequests.transaction_id,
            payment_screenshot: studentRequests.payment_screenshot,
            purpose: studentRequests.purpose,
            academic_year: studentRequests.academic_year,
            created_at: studentRequests.created_at,
            updated_at: studentRequests.updated_at,
            completed_at: studentRequests.completed_at,
            reject_reason: studentRequests.reject_reason,
            action_by_clerk_id: studentRequests.action_by_clerk_id,
            action_by_role: studentRequests.action_by_role,
            action_by_clerk_name: clerks.name
        })
        .from(studentRequests)
        .innerJoin(students, eq(studentRequests.student_id, students.id))
        .leftJoin(clerks, eq(studentRequests.action_by_clerk_id, clerks.id))
        .where(eq(studentRequests.request_id, requestIdNum))
        .limit(1);

        if (rows.length === 0) return apiError('Request not found', 404);
        
        const allowedTypes = clerkToTypes[clerk.role] || [];
        if (!allowedTypes.includes(rows[0].certificate_type)) return apiError('Forbidden', 403);

        return apiResponse(rows[0]);
    } catch (error) {
        logger.error('Error fetching request details:', error);
        return apiError('Failed to fetch request details', 500);
    }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { 
  students as studentsTable, 
  studentImages, 
  scholarshipSanctions, 
  studentFeePayments 
} from '@/db/schema';
import { eq, and, asc, sql, or, like } from 'drizzle-orm';
import { 
  getBranchFromRoll, 
  getAcademicYear, 
  getResolvedCurrentAcademicYear,
  getAdmissionTypeFromRoll,
  getAcademicYearForStudyYear
} from '@/lib/rollNumber';
import { apiError, apiResponse, getAuthUser } from '@/lib/api-utils';
import { getNow } from '@/lib/clock';
import { decrypt } from '@/lib/encryption';

export async function GET(req, ctx) {
  const user = await getAuthUser('clerk');
  if (!user) return apiError('Unauthorized', 401);

  try {
    const params = await ctx.params;
    const { application_no } = params;
    if (!application_no) return apiError('Missing application_no parameter', 400);

    // Validation: Must be numeric
    if (!/^\d+$/.test(application_no)) {
      return apiError('application_no must be numeric', 400);
    }

    // Find sanction rows that match the application number
    const sanctionRows = await db.select({ 
      student_id: scholarshipSanctions.student_id, 
      academic_year: scholarshipSanctions.academic_year 
    })
    .from(scholarshipSanctions)
    .where(eq(scholarshipSanctions.application_no, application_no));

    if (sanctionRows.length === 0) {
      return apiError('Application not found', 404);
    }

    // Pick the first student (application_no should map to one student)
    const studentId = sanctionRows[0].student_id;

    const studentRows = await db.select({
      id: studentsTable.id,
      roll_no: studentsTable.roll_no,
      name: studentsTable.name,
      fee_reimbursement: studentsTable.fee_reimbursement,
      email: studentsTable.email,
      mobile: studentsTable.mobile,
      has_pfp: sql`CASE WHEN ${studentImages.pfp} IS NOT NULL THEN 1 ELSE 0 END`
    })
    .from(studentsTable)
    .leftJoin(studentImages, eq(studentsTable.id, studentImages.student_id))
    .where(eq(studentsTable.id, studentId))
    .limit(1);

    if (studentRows.length === 0) return apiError('Student not found', 404);
    const student = studentRows[0];

    const now = await getNow();
    const course = getBranchFromRoll(student.roll_no);
    const admission_year = getAcademicYear(student.roll_no);
    const current_year = getResolvedCurrentAcademicYear(student.roll_no, null, now);
    const admissionType = getAdmissionTypeFromRoll(student.roll_no);

    // For each academic_year belonging to this application, build a summary
    const allYears = Array.from(new Set(sanctionRows.map(r => r.academic_year))).filter(Boolean).sort();
    const year_records = { /* empty */ };

    for (const year of allYears) {
      // sanctions for this student/year
      const sanctions = await db.query.scholarshipSanctions.findMany({
        where: and(
          eq(scholarshipSanctions.student_id, studentId),
          eq(scholarshipSanctions.academic_year, year)
        ),
        orderBy: [asc(scholarshipSanctions.sanction_date)]
      });

      const scholarship_proceedings = sanctions.map(r => ({ 
        id: r.id, 
        proceeding_no: r.proceeding_no, 
        amount: Number(r.sanctioned_amount) || 0, 
        date: r.sanction_date 
      }));
      const application_for_year = sanctions.map(r => r.application_no).find(v => v && String(v).trim() !== '') || null;

      // payments for this student/year
      const payments = await db.query.studentFeePayments.findMany({
        where: and(
          eq(studentFeePayments.student_id, studentId),
          eq(studentFeePayments.academic_year, year)
        ),
        orderBy: [asc(studentFeePayments.transaction_date)]
      });

      const student_payments = payments.map(r => ({ 
        id: r.id, 
        transaction_ref: r.transaction_ref_no, 
        amount: Number(r.amount) || 0, 
        date: r.transaction_date 
      }));

      // derive fee summary
      const SFC_COURSES = new Set(['CSD', 'IT', 'CIVIL']);
      const fee_category = SFC_COURSES.has(String(course).toUpperCase()) ? 'SFC' : 'NON-SFC';
      const total_fee = fee_category === 'SFC' ? 70000 : 35000;
      const govt_paid = scholarship_proceedings.reduce((sum, p) => sum + p.amount, 0);
      const student_paid = student_payments.reduce((sum, p) => sum + p.amount, 0);
      const pending_fee = Math.max(0, Number(total_fee) - (Number(govt_paid) + Number(student_paid)));
      const status = pending_fee === 0 ? 'COMPLETED' : 'PENDING';

      year_records[year] = {
        academic_year: year,
        scholarship_proceedings,
        application_no: application_for_year,
        student_payments,
        fee_summary: {
          total_fee,
          govt_paid,
          student_paid,
          pending_fee,
          status,
        },
      };
    }

    const response = {
      student: {
        id: student.id,
        roll_no: student.roll_no,
        name: student.name,
        fee_reimbursement: student.fee_reimbursement,
        fee_category: new Set(['CSD', 'IT', 'CIVIL']).has(String(course).toUpperCase()) ? 'SFC' : 'NON-SFC',
        course,
        email: student.email ?? null,
        mobile: decrypt(student.mobile) ?? null,
        pfp: student.has_pfp ? `/api/student/image/${student.roll_no}` : null,
        admission_year,
        current_year,
      },
      year_records,
    };

    return apiResponse({ data: response });
  } catch (error) {
    logger.error('Error fetching application data:', error);
    return apiError('Internal Server Error', 500);
  }
}

