import { createClient } from '@supabase/supabase-js';
import { NextResponse } from 'next/server';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

export async function GET() {
  if (!supabaseUrl || !supabaseKey) {
    return NextResponse.json({ error: 'Missing keys' }, { status: 500 });
  }

  try {
    const supabase = createClient(supabaseUrl, supabaseKey);
    
    // Perform a minimal "ping" to Supabase Realtime/Rest
    // This counts as activity to prevent project pausing
    const { data, error } = await supabase.from('_dummy_ping').select('*').limit(1).maybeSingle();
    
    // Note: _dummy_ping doesn't need to exist. We just need to hit the API.
    
    return NextResponse.json({ 
      status: 'active', 
      timestamp: new Date().toISOString(),
      supabase: error?.code === 'PGRST116' || !error ? 'reachable' : 'error' 
    });
  } catch (err) {
    return NextResponse.json({ status: 'error', message: err.message }, { status: 500 });
  }
}

import { apiResponse, apiError } from "@/lib/api-utils";
import logger from "@/lib/logger";
import { getNow } from "@/lib/clock";
import { HealthService } from "@/services/HealthService";

/**
 * Deployment Health Check API
 * Verifies critical infrastructure connections: Database, Redis, and Email Config.
 */
export async function GET(request) {
  const dbCheck = await HealthService.checkDatabase();
  const redisCheck = await HealthService.checkRedis();
  const emailCheck = HealthService.checkEmailConfig();

  const hasCriticalError = HealthService.isCriticalError(dbCheck.status, emailCheck.status);
  const overallStatus = HealthService.determineStatus(dbCheck.status, redisCheck.status, emailCheck.status);

  const status = {
    status: overallStatus,
    database: dbCheck.status,
    redis: redisCheck.status,
    email_service: emailCheck.status,
    timestamp: getNow().toISOString()
  };

  // Respond with 503 if any critical service (DB, email) is down
  if (hasCriticalError) {
    return apiError("System Unhealthy", 503, status);
  }

  return apiResponse(status);
}

import logger from '@/lib/logger';
import { apiResponse, apiError } from "@/lib/api-utils";
import { v2 as cloudinary } from "cloudinary";
import { sendInstitutionalEmail } from "@/lib/email";
import { DEVELOPER_EMAILS } from "@/lib/developers";

cloudinary.config({
  cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
  api_key: process.env.CLOUDINARY_API_KEY,
  api_secret: process.env.CLOUDINARY_API_SECRET,
  secure: true,
});

/**
 * GET /api/public/system/storage-alert
 * Automated check for Cloudinary storage limits.
 */
export async function GET(request) {
  // Developer emails from shared config
  const developerEmails = DEVELOPER_EMAILS;

  const ALERT_THRESHOLD_GB = 20;

  try {
    // Fetch Cloudinary Usage
    const usageData = await cloudinary.api.usage();
    const storage = usageData.storage || { /* empty */ };
    
    const usageBytes = storage.usage || 0;
    const limitBytes = storage.limit || (25 * 1024 * 1024 * 1024);
    
    const usageGB = usageBytes / (1024 * 1024 * 1024);
    const limitGB = limitBytes / (1024 * 1024 * 1024);
    const percent = (usageBytes / limitBytes) * 100;

    logger.info(`[STORAGE_CHECK] Current Usage: ${usageGB.toFixed(2)} GB (${percent.toFixed(1)}%)`);

    // Trigger Alert if threshold reached (20GB)
    if (usageGB >= ALERT_THRESHOLD_GB) {
      // Send email to each developer
      const emailPromises = developerEmails.map(email => 
        sendInstitutionalEmail({
          to: email,
          subject: "⚠️ URGENT: Cloudinary Storage Limit Warning",
          title: "Storage Threshold Reached",
          bodyHtml: `
            <p>This is an automated system alert for your Cloudinary storage.</p>
            <p style="color: #b91c1c; font-weight: bold;">Your Cloudinary storage usage has exceeded the ${ALERT_THRESHOLD_GB}GB threshold.</p>
            <p>Current usage is <strong>${usageGB.toFixed(2)} GB</strong> which is <strong>${percent.toFixed(1)}%</strong> of your total limit.</p>
            <p>Please log in to your Cloudinary dashboard to manage your assets or consider upgrading your plan to prevent service interruption.</p>
          `,
          infoRows: [
            { label: "Current Usage", value: `${usageGB.toFixed(2)} GB` },
            { label: "Total Limit", value: `${limitGB.toFixed(2)} GB` },
            { label: "Alert Threshold", value: `${ALERT_THRESHOLD_GB}.00 GB` }
          ],
          action: {
            label: "View Cloudinary Dashboard",
            url: "https://cloudinary.com/console"
          }
        })
      );

      await Promise.all(emailPromises);

      return apiResponse({ 
        alert_sent: true, 
        usage: `${usageGB.toFixed(2)} GB`,
        message: `Storage threshold exceeded. Alert email sent to ${developerEmails.length} developers.`
      });
    }

    return apiResponse({ 
      alert_sent: false, 
      usage: `${usageGB.toFixed(2)} GB`,
      message: `Storage usage is within safe limits (Threshold: ${ALERT_THRESHOLD_GB}GB).` 
    });

  } catch (error) {
    logger.error("[STORAGE_CHECK_ERROR]", error);
    return apiError("Internal Server Error", 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { 
  students, 
  studentPersonalDetails, 
  studentAcademicBackground, 
  studentImages, 
  studentSignatures, 
  scholarshipSanctions, 
  studentFeePayments 
} from '@/db/schema';
import { eq, asc, desc } from 'drizzle-orm';
import { getBranchFromRoll, getAdmissionTypeFromRoll, getAcademicYear as computeAcademicYear } from '@/lib/rollNumber';
import { apiError, apiResponse, getAuthUser } from '@/lib/api-utils';
import { decrypt } from '@/lib/encryption';

export async function GET(req, context) {
  // Check any valid auth
  const user = await getAuthUser();

  if (!user) {
    return apiError('Unauthorized', 401);
  }

  try {
    const params = await context.params;
    let { rollno } = params;

    // Invisible Normalization Hook
    rollno = String(rollno || '').trim().toUpperCase();

    // SECURITY GUARD: A student can ONLY access their own profile.
    // Staff (clerk/admin) can access any profile.
    const isStudent = !!user.roll_no;
    if (isStudent && user.roll_no !== rollno) {
      logger.warn(`[SECURITY_ALERT] Student ${user.roll_no} tried to access profile ${rollno}`);
      return apiError('Forbidden: Access denied to this profile', 403);
    }

    // 1. Fetch student with joined personal and academic data
    const studentResult = await db.select()
      .from(students)
      .leftJoin(studentPersonalDetails, eq(students.id, studentPersonalDetails.student_id))
      .leftJoin(studentAcademicBackground, eq(students.id, studentAcademicBackground.student_id))
      .where(eq(students.roll_no, rollno));

    if (studentResult.length === 0) {
      return apiError('Student not found', 404);
    }

    const row = studentResult[0];
    const studentData = row.students;
    const studentId = studentData.id;

    // Nest the data as expected by the frontend
    const student = { 
      ...studentData,
      mobile: decrypt(studentData.mobile) // Decrypt student mobile
    };
    
    student.personal_details = row.student_personal_details ? {
      ...row.student_personal_details,
      guardian_mobile: decrypt(row.student_personal_details.guardian_mobile), // Decrypt guardian mobile
      aadhaar_no: decrypt(row.student_personal_details.aadhaar_no) // Decrypt Aadhaar
    } : { /* empty */ };
    
    const academics = row.student_academic_background ? [row.student_academic_background] : [];
    
    student.course = getBranchFromRoll(student.roll_no);
    student.branch = student.course;
    student.admission_type = getAdmissionTypeFromRoll(student.roll_no);

    // Helper to handle both URLs and legacy Buffer data
    const imageHelper = (val) => {
      if (!val) return null;
      if (typeof val === 'string' && (val.startsWith('http') || val.startsWith('data:'))) return val;
      if (Buffer.isBuffer(val)) return `data:image/png;base64,${val.toString('base64')}`;
      return val;
    };

    // 2. Fetch pfp and signature separately
    const pfpRow = await db.query.studentImages.findFirst({
      columns: { student_id: true },
      where: eq(studentImages.student_id, studentId)
    });
    student.pfp = pfpRow ? `/api/student/image/${student.roll_no}` : null;

    const sigRow = await db.query.studentSignatures.findFirst({
      where: eq(studentSignatures.student_id, studentId)
    });
    student.signature = sigRow ? imageHelper(sigRow.signature) : null;

    // 3. Fetch one-to-many relationships
    const scholarshipRows = await db.query.scholarshipSanctions.findMany({
      where: eq(scholarshipSanctions.student_id, studentId),
      orderBy: [asc(scholarshipSanctions.sanction_date)]
    });

    const scholarship = scholarshipRows.map(s => {
      const academic_year = s.academic_year || (s.year ? computeAcademicYear(student.roll_no, s.year) : null);
      return {
        ...s,
        academic_year,
        application_no: s.application_no,
        proceeding_no: s.proceeding_no,
        sanctioned_amount: s.sanctioned_amount,
        sanction_date: s.sanction_date,
      };
    });

    const feesRows = await db.query.studentFeePayments.findMany({
      where: eq(studentFeePayments.student_id, studentId),
      orderBy: [asc(studentFeePayments.academic_year), asc(studentFeePayments.transaction_date)]
    });

    const fees = feesRows.map(f => ({
      ...f,
      transaction_ref: f.transaction_ref_no,
      date: f.transaction_date,
    }));

    return apiResponse({ student, scholarship, fees, academics });
  } catch (error) {
    logger.error(error, 'Error fetching student profile data');
    return apiError('Failed to fetch student profile data', 500, error.message);
  }
}

import logger from '@/lib/logger';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';
import { fetchWithSWR } from '@/lib/cache';
import { db } from '@/db';
import { 
  students as studentsTable,
  collegeInfo as collegeInfoTable, 
  syllabusStructure, 
  syllabusSubjects, 
  studentMarks, 
  facultySubjectAssignments, 
  clerks, 
  studentAttendance 
} from '@/db/schema';
import { eq, and, min, sql, countDistinct, or } from 'drizzle-orm';
import { calculateYearAndSemesterAsync, getCollegeAcademicYear } from '@/lib/academic-utils';
import { getBranchFromRoll } from '@/lib/rollNumber';

export async function GET(request) {
  try {
    const user = await getAuthUser('student');
    if (!user) {
      return apiError('Unauthorized', 401);
    }

    const collegeRows = await db.select().from(collegeInfoTable).where(eq(collegeInfoTable.id, 1));
    const collegeInfo = collegeRows[0] || null;

    const { semester } = await calculateYearAndSemesterAsync(user.roll_no, collegeInfo, user.academic_offset_years || 0);
    const academicYear = await getCollegeAcademicYear(collegeInfo);
    const branch = getBranchFromRoll(user.roll_no);
    const studentId = user.student_id;

    if (!studentId || !branch || !semester || !academicYear) {
      return apiError('Unable to determine student academic context', 400);
    }

    const cacheKey = `academic_info:${studentId}:${branch}:${semester}:${academicYear}`;
    
    const cachedResponse = await fetchWithSWR(cacheKey, async () => {
      // --- OPTIMIZED AGGREGATED DATA QUERY USING DRIZZLE ---
      
      // 1. Define the CTE for Canonical Assignments
      const canonicalAssignments = db.$with('CanonicalAssignments').as(
        db.select({
          subject_code: facultySubjectAssignments.subject_code,
          canonical_id: min(facultySubjectAssignments.id).as('canonical_id')
        })
        .from(facultySubjectAssignments)
        .where(and(
          eq(facultySubjectAssignments.branch, branch),
          eq(facultySubjectAssignments.course_semester, semester),
          eq(facultySubjectAssignments.academic_year, academicYear)
        ))
        .groupBy(facultySubjectAssignments.subject_code)
      );

      // 2. Main query with joins and aggregations
      const subjects = await db.with(canonicalAssignments)
        .select({
          subject_code: syllabusStructure.subject_code,
          subject_name: syllabusSubjects.subject_name,
          subject_type: syllabusSubjects.subject_type,
          assignment_id: canonicalAssignments.canonical_id,
          mid_max: sql`MAX(${facultySubjectAssignments.mid_max})`,
          faculty_name: sql`GROUP_CONCAT(DISTINCT ${clerks.name} SEPARATOR ' & ')`,
          
          // Marks
          mid1_marks: studentMarks.mid1_marks,
          mid2_marks: studentMarks.mid2_marks,
          assignment_marks: studentMarks.assignment_marks,
          lab_theory_marks: studentMarks.lab_theory_marks,
          lab_execution_marks: studentMarks.lab_execution_marks,
          lab_record_marks: studentMarks.lab_record_marks,

          // Used only for backend-side dedupe
          _marks_row_id: studentMarks.id,
          _marks_created_at: studentMarks.created_at,
          _marks_updated_at: studentMarks.updated_at,

          // Attendance (Filtering by Admission Date to avoid Spot Admission penalty)
          total_classes: sql`COUNT(DISTINCT CASE WHEN ${studentAttendance.date} >= COALESCE(${studentsTable.admission_date}, '1900-01-01') THEN ${studentAttendance.id} END)`,
          attended_classes: sql`COUNT(DISTINCT CASE WHEN ${studentAttendance.status} IN ('PRESENT', 'NCC', 'MEDICAL') AND ${studentAttendance.date} >= COALESCE(${studentsTable.admission_date}, '1900-01-01') THEN ${studentAttendance.id} END)`
        })
        .from(syllabusStructure)
        .innerJoin(syllabusSubjects, eq(syllabusStructure.subject_code, syllabusSubjects.subject_code))
        .leftJoin(canonicalAssignments, eq(canonicalAssignments.subject_code, syllabusStructure.subject_code))
        .innerJoin(studentsTable, eq(studentsTable.id, studentId)) // Join students to get admission_date
        .leftJoin(studentMarks, and(
          eq(studentMarks.student_id, studentId),
          eq(studentMarks.assignment_id, canonicalAssignments.canonical_id),
          eq(studentMarks.is_published, true)
        ))
        .leftJoin(facultySubjectAssignments, and(
          eq(facultySubjectAssignments.subject_code, syllabusStructure.subject_code),
          eq(facultySubjectAssignments.branch, syllabusStructure.branch),
          eq(facultySubjectAssignments.course_semester, syllabusStructure.semester),
          eq(facultySubjectAssignments.academic_year, academicYear)
        ))
        .leftJoin(clerks, eq(facultySubjectAssignments.faculty_id, clerks.id))
        .leftJoin(studentAttendance, and(
          eq(studentAttendance.student_id, studentId),
          eq(studentAttendance.assignment_id, facultySubjectAssignments.id)
        ))
        .where(and(
          eq(syllabusStructure.branch, branch),
          eq(syllabusStructure.semester, semester),
          eq(syllabusStructure.is_group, false)
        ))
        .groupBy(
          syllabusStructure.subject_code, 
          syllabusSubjects.subject_name, 
          syllabusSubjects.subject_type, 
          canonicalAssignments.canonical_id,
          studentMarks.id,
          studentsTable.admission_date // Add to group by
        );

      // If student_marks already contains duplicates, the JOIN can yield repeated subject rows.
      // Deduplicate by subject_code, keeping the newest marks row (and preferring rows with marks).
      const pickBetter = (a, b) => {
        const countMarks = (row) => {
          const fields = [
            row.mid1_marks,
            row.mid2_marks,
            row.assignment_marks,
            row.lab_theory_marks,
            row.lab_execution_marks,
            row.lab_record_marks,
          ];
          return fields.reduce((acc, v) => acc + (v === null || v === undefined ? 0 : 1), 0);
        };

        const aMarks = countMarks(a);
        const bMarks = countMarks(b);
        if (aMarks !== bMarks) return bMarks > aMarks ? b : a;

        const aTime = a._marks_updated_at || a._marks_created_at || null;
        const bTime = b._marks_updated_at || b._marks_created_at || null;
        const aMs = aTime ? new Date(aTime).getTime() : 0;
        const bMs = bTime ? new Date(bTime).getTime() : 0;
        if (aMs !== bMs) return bMs > aMs ? b : a;

        const aId = a._marks_row_id || 0;
        const bId = b._marks_row_id || 0;
        return bId > aId ? b : a;
      };

      const dedupedBySubject = new Map();
      for (const row of subjects) {
        const key = row.subject_code;
        const existing = dedupedBySubject.get(key);
        dedupedBySubject.set(key, existing ? pickBetter(existing, row) : row);
      }

      const cleaned = Array.from(dedupedBySubject.values()).map(s => {
        const { _marks_row_id, _marks_created_at, _marks_updated_at, ...rest } = s;
        return { ...rest, mid_max: rest.mid_max || 20 };
      });

      return { 
        data: cleaned,
        semester,
        academicYear
      };
    }, 60, 3600); // 60s stale, 1h max cache

    return apiResponse(cachedResponse);
  } catch (error) {
    logger.error('Student Academic Info Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { 
  students, 
  collegeInfo as collegeInfoTable, 
  scholarshipWindows, 
  scholarshipSanctions 
} from '@/db/schema';
import { eq, desc, and } from 'drizzle-orm';
import { toMySQLDate } from '@/lib/date';
import { apiError, apiResponse, getAuthUser } from '@/lib/api-utils';
import { getCurrentAcademicYear } from '@/lib/rollNumber';

export async function GET(request) {
  try {
    const user = await getAuthUser('student');
    if (!user) return apiError('Unauthorized', 401);

    const studentRoll = user.roll_no;
    if (!studentRoll) return apiError('Student roll number not found in session', 400);

    // Resolve student id
    const student = await db.query.students.findFirst({
      columns: { id: true },
      where: eq(students.roll_no, studentRoll)
    });

    if (!student) {
      return apiResponse({
        scholarshipThumbUpdate: { active: false },
        scholarshipHardcopyPending: { active: false },
      });
    }
    const studentId = student.id;

    // STEP 1 — Determine current academic year for this student using helper
    const collegeRows = await db.select().from(collegeInfoTable).where(eq(collegeInfoTable.id, 1));
    const collegeInfo = collegeRows[0] || null;

    let currentAcademicYear = null;
    try {
      currentAcademicYear = getCurrentAcademicYear(studentRoll, collegeInfo) || null;
    } catch {
      currentAcademicYear = null;
    }

    if (!currentAcademicYear) {
      return apiResponse({
        scholarshipThumbUpdate: { active: false },
        scholarshipHardcopyPending: { active: false },
        scholarshipApplicationReceived: { active: false },
        scholarshipApplicationsOpen: { active: false },
      });
    }

    // STEP 2 — Fetch latest scholarship window
    const win = await db.query.scholarshipWindows.findFirst({
      orderBy: [desc(scholarshipWindows.id)]
    });

    let windowOpen = false;
    let windowStart = null;
    let windowEnd = null;

    if (win && win.start_date && win.end_date) {
      const today = new Date();
      const start = new Date(win.start_date);
      const end = new Date(win.end_date);
      if (today >= start && today <= end) {
        windowOpen = true;
        windowStart = toMySQLDate(win.start_date);
        windowEnd = toMySQLDate(win.end_date);
      }
    }

    // STEP 3 — Fetch scholarship record for CURRENT academic year only
    const rec = await db.query.scholarshipSanctions.findFirst({
      where: and(
        eq(scholarshipSanctions.student_id, studentId),
        eq(scholarshipSanctions.academic_year, currentAcademicYear)
      ),
      orderBy: [desc(scholarshipSanctions.id)]
    });

    const applicationNo = rec && rec.application_no ? String(rec.application_no).trim() : null;
    const hardcopySubmitted = rec ? Number(rec.hardcopy_submitted) === 1 : false;
    const thumbAvailable = rec ? Number(rec.thumb_update_available) === 1 : false;
    const thumbPending = thumbAvailable && String(rec.thumb_status || '').trim().toUpperCase() === 'PENDING';

    // STEP 4 — Build lifecycle activities based on current academic year

    // Activity 1 — Scholarship Applications Open
    const scholarshipApplicationsOpen = windowOpen && !applicationNo
      ? {
          active: true,
          startDate: windowStart,
          endDate: windowEnd,
          academic_year: currentAcademicYear,
        }
      : { active: false };

    // Activity 2 — Submit Hard Copies
    const scholarshipHardcopyPending = applicationNo && !hardcopySubmitted
      ? {
          active: true,
          application_no: applicationNo,
          academic_year: currentAcademicYear,
        }
      : { active: false };

    // Activity 3 — Application Received
    const scholarshipApplicationReceived = hardcopySubmitted && !thumbAvailable
      ? {
          active: true,
          academic_year: currentAcademicYear,
        }
      : { active: false };

    // Activity 4 — Thumb Verification Required
    const scholarshipThumbUpdate = thumbPending
      ? {
          active: true,
          application_no: applicationNo,
          academic_year: currentAcademicYear,
        }
      : { active: false };

    return apiResponse({
      scholarshipThumbUpdate,
      scholarshipHardcopyPending,
      scholarshipApplicationReceived,
      scholarshipApplicationsOpen,
    });
  } catch (error) {
    logger.error('Failed to fetch student activity', error);
    return apiError('Internal Server Error', 500);
  }
}

