import logger from '@/lib/logger';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';
import { db } from '@/db';
import { 
  facultySubjectAssignments, 
  attendanceSessions, 
  clerks, 
  attendanceSessionLogs 
} from '@/db/schema';
import { eq, and, inArray, isNull, sql, gt } from 'drizzle-orm';

/**
 * GET /api/student/attendance/active-sessions?ids=1,2,3
 * Returns active attendance sessions for the provided assignment IDs
 */
export async function GET(request) {
  try {
    const user = await getAuthUser('student');
    if (!user) {
      return apiError('Unauthorized', 401);
    }

    const { searchParams } = new URL(request.url);
    const ids = searchParams.get('ids');

    if (!ids) {
      return apiResponse({ data: [] });
    }

    const assignmentIds = ids.split(',').map(id => parseInt(id)).filter(id => !isNaN(id));
    if (assignmentIds.length === 0) {
      return apiResponse({ data: [] });
    }

    // 1. First, find the subject codes, branch, and semester for the provided assignment IDs
    const contextRows = await db.select({
      subject_code: facultySubjectAssignments.subject_code,
      branch: facultySubjectAssignments.branch,
      course_semester: facultySubjectAssignments.course_semester,
      academic_year: facultySubjectAssignments.academic_year
    })
    .from(facultySubjectAssignments)
    .where(inArray(facultySubjectAssignments.id, assignmentIds));

    if (contextRows.length === 0) {
      return apiResponse({ data: [] });
    }

    const subjectCodes = Array.from(new Set(contextRows.map(r => r.subject_code)));
    const branch = contextRows[0].branch;
    const semester = contextRows[0].course_semester;
    const academicYear = contextRows[0].academic_year;

    // 2. Fetch ALL active sessions for these subjects in this branch/sem/year
    // AND check if this student has already verified.
    const { getNow } = await import('@/lib/clock');
    const sessions = await db.select({
      session_id: attendanceSessions.id,
      assignment_id: attendanceSessions.assignment_id,
      attendance_date: attendanceSessions.attendance_date,
      subject_name: facultySubjectAssignments.subject_name,
      subject_code: facultySubjectAssignments.subject_code,
      faculty_name: clerks.name
    })
    .from(attendanceSessions)
    .innerJoin(facultySubjectAssignments, eq(attendanceSessions.assignment_id, facultySubjectAssignments.id))
    .innerJoin(clerks, eq(attendanceSessions.faculty_id, clerks.id))
    .leftJoin(attendanceSessionLogs, and(
      eq(attendanceSessions.id, attendanceSessionLogs.session_id),
      eq(attendanceSessionLogs.student_id, user.student_id),
      eq(attendanceSessionLogs.status, 'SUCCESS')
    ))
    .where(and(
      inArray(facultySubjectAssignments.subject_code, subjectCodes),
      eq(facultySubjectAssignments.branch, branch),
      eq(facultySubjectAssignments.course_semester, semester),
      eq(facultySubjectAssignments.academic_year, academicYear),
      eq(attendanceSessions.is_active, true),
      gt(attendanceSessions.expires_at, getNow()),
      isNull(attendanceSessionLogs.id)
    ));

    return apiResponse({ data: sessions });
  } catch (error) {
    logger.error('Fetch Active Sessions Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';
import { db } from '@/db';
import { 
  attendanceSessions, 
  attendanceSessionLogs, 
  students, 
  studentAttendance 
} from '@/db/schema';
import { eq, and, gt, sql } from 'drizzle-orm';
import { isWithinRange } from '@/lib/geo-utils';
import { getNow } from '@/lib/clock';
import crypto from 'crypto';

/**
 * POST /api/student/attendance/verify
 * Students use this to verify their attendance via PIN or QR
 */
export async function POST(request) {
  try {
    const user = await getAuthUser('student');
    if (!user) {
      return apiError('Unauthorized', 401);
    }

    const body = await request.json();
    const { assignment_id, session_id, pin, token, latitude, longitude, accuracy, device_id } = body;

    if ((!assignment_id && !session_id) || (!pin && !token) || latitude === undefined || longitude === undefined) {
      return apiError('Location and Verification Data (PIN/QR) are required.', 400);
    }

    const now = await getNow();
    
    // 1. Fetch the active session
    const session = await db.query.attendanceSessions.findFirst({
      where: and(
        session_id ? eq(attendanceSessions.id, session_id) : eq(attendanceSessions.assignment_id, assignment_id),
        eq(attendanceSessions.is_active, true),
        gt(attendanceSessions.expires_at, now)
      )
    });

    if (!session) {
      return apiError('No active attendance session found or session expired.', 404);
    }

    const sessionNum = session.session_number || 1;

    // --- GPS RADIUS & ACCURACY CHECK ---
    const maxAccuracy = 100; // 100 meters
    if (accuracy && accuracy > maxAccuracy) {
      return apiError(`GPS accuracy too low (${Math.round(accuracy)}m). Please move to a clearer area and try again.`, 400);
    }

    if (session.latitude && session.longitude) {
      const isNearby = isWithinRange(
        Number(session.latitude), 
        Number(session.longitude), 
        latitude, 
        longitude, 
        50 // 50m radius
      );

      if (!isNearby) {
        // Record failure
        await db.insert(attendanceSessionLogs)
          .values({
            session_id: session.id,
            student_id: user.student_id,
            status: 'FAILED_LOCATION',
            ip_address: request.headers.get('x-forwarded-for')?.split(',')[0] || '127.0.0.1',
            created_at: now
          });

        return apiError('You are not within the allowed radius (50m) of the classroom.', 403);
      }
    }
    const userAgent = request.headers.get('user-agent') || '';
    const ipAddress = request.headers.get('x-forwarded-for')?.split(',')[0] || 
                      request.headers.get('x-real-ip') || 
                      '127.0.0.1';
    
    const uaHash = crypto.createHash('md5').update(userAgent).digest('hex');
    const finalDeviceId = device_id || crypto.createHash('sha256').update(userAgent + ipAddress).digest('hex');

    // --- PIN / TOKEN VALIDATION ---
    if (pin) {
      // 1. Check existing failures/lockout
      const existingLogs = await db.select({ 
        failed_count: sql`COUNT(CASE WHEN status = 'FAILED_PIN' THEN 1 END)`,
        is_locked: sql`COUNT(CASE WHEN status = 'LOCKED' THEN 1 END)`
      })
        .from(attendanceSessionLogs)
        .where(and(
          eq(attendanceSessionLogs.session_id, session.id),
          eq(attendanceSessionLogs.student_id, user.student_id)
        ));
      
      const { failed_count, is_locked } = existingLogs[0];
      if (Number(is_locked) > 0) {
        return apiError('You have been locked out of this session due to multiple failed PIN attempts. Please contact the faculty.', 403);
      }

      if (String(pin) !== String(session.session_pin)) {
        const newFailedCount = Number(failed_count) + 1;
        const status = newFailedCount >= 3 ? 'LOCKED' : 'FAILED_PIN';
        
        // Record failure
        await db.insert(attendanceSessionLogs)
          .values({
            session_id: session.id,
            student_id: user.student_id,
            status: status,
            ip_address: ipAddress,
            ua_hash: uaHash,
            device_hash: finalDeviceId
          });

        if (newFailedCount >= 3) {
          // Notify Faculty
          try {
            const { broadcastUpdate } = await import('@/lib/sse');
            broadcastUpdate('STUDENT_LOCKED', { 
              assignment_id: session.assignment_id,
              session_number: sessionNum,
              roll_no: user.roll_no,
              reason: '3 failed PIN attempts'
            });
          } catch (sseErr) { /* empty */ }
          return apiError('3 failed PIN attempts. You are now locked out of this session.', 403);
        }

        return apiError(`Invalid PIN. ${3 - newFailedCount} attempts remaining.`, 403);
      }
    } else if (token) {
      if (token !== session.session_token) {
        return apiError('Invalid verification token or QR code.', 403);
      }
    }

    // --- PROXY DETECTION: DEVICE FINGERPRINTING ---
    const idLogs = await db.select({
      student_id: attendanceSessionLogs.student_id,
      roll_no: students.roll_no
    })
    .from(attendanceSessionLogs)
    .innerJoin(students, eq(attendanceSessionLogs.student_id, students.id))
    .where(and(
      eq(attendanceSessionLogs.session_id, session.id),
      eq(attendanceSessionLogs.device_hash, finalDeviceId),
      eq(attendanceSessionLogs.status, 'SUCCESS')
    ));

    if (idLogs.length > 0 && idLogs[0].student_id !== user.student_id) {
      const originalStudent = idLogs[0];
      
      // PROXY DETECTED: Mark BOTH students as ABSENT
      await db.transaction(async (tx) => {
        // Original student
        await tx.insert(studentAttendance)
          .values({
            assignment_id: session.assignment_id,
            student_id: originalStudent.student_id,
            date: session.attendance_date,
            session: sessionNum,
            status: 'ABSENT'
          })
          .onDuplicateKeyUpdate({ set: { status: 'ABSENT' } });

        // Attempting student (user)
        await tx.insert(studentAttendance)
          .values({
            assignment_id: session.assignment_id,
            student_id: user.student_id,
            date: session.attendance_date,
            session: sessionNum,
            status: 'ABSENT'
          })
          .onDuplicateKeyUpdate({ set: { status: 'ABSENT' } });
      });

      // Notify Faculty
      try {
        const { broadcastUpdate } = await import('@/lib/sse');
        broadcastUpdate('PROXY_ATTEMPTED', { 
          assignment_id: session.assignment_id,
          session_number: sessionNum,
          attempting_roll_no: user.roll_no,
          original_roll_no: originalStudent.roll_no,
          original_student_id: originalStudent.student_id
        });
      } catch (sseErr) { /* empty */ }

      return apiError(`Proxy blocked: Student ${originalStudent.roll_no} attempted to proxy for you using their device/session. Both records have been flagged as ABSENT.`, 403);
    }

    // 2. Check if this specific IP + User-Agent combination has already been used
    const proxyLogs = await db.select({
      student_id: attendanceSessionLogs.student_id,
      roll_no: students.roll_no
    })
    .from(attendanceSessionLogs)
    .innerJoin(students, eq(attendanceSessionLogs.student_id, students.id))
    .where(and(
      eq(attendanceSessionLogs.session_id, session.id),
      eq(attendanceSessionLogs.ip_address, ipAddress),
      eq(attendanceSessionLogs.ua_hash, uaHash),
      eq(attendanceSessionLogs.status, 'SUCCESS')
    ));

    if (proxyLogs.length > 0 && proxyLogs[0].student_id !== user.student_id) {
      const originalStudent = proxyLogs[0];

      // PROXY DETECTED: Mark BOTH students as ABSENT
      await db.transaction(async (tx) => {
        // Original student
        await tx.insert(studentAttendance)
          .values({
            assignment_id: session.assignment_id,
            student_id: originalStudent.student_id,
            date: session.attendance_date,
            session: sessionNum,
            status: 'ABSENT'
          })
          .onDuplicateKeyUpdate({ set: { status: 'ABSENT' } });

        // Attempting student (user)
        await tx.insert(studentAttendance)
          .values({
            assignment_id: session.assignment_id,
            student_id: user.student_id,
            date: session.attendance_date,
            session: sessionNum,
            status: 'ABSENT'
          })
          .onDuplicateKeyUpdate({ set: { status: 'ABSENT' } });
      });

      // Notify Faculty
      try {
        const { broadcastUpdate } = await import('@/lib/sse');
        broadcastUpdate('PROXY_ATTEMPTED', { 
          assignment_id: session.assignment_id,
          session_number: sessionNum,
          attempting_roll_no: user.roll_no,
          original_roll_no: originalStudent.roll_no,
          original_student_id: originalStudent.student_id
        });
      } catch (sseErr) { /* empty */ }

      return apiError(`Proxy blocked: This network signature has already been used by student ${originalStudent.roll_no} to verify their attendance. Both records have been flagged as ABSENT.`, 403);
    }

    // 5. Record the log with all fingerprinting markers
    await db.insert(attendanceSessionLogs)
      .values({
        session_id: session.id,
        student_id: user.student_id,
        device_hash: finalDeviceId,
        ip_address: ipAddress,
        ua_hash: uaHash,
        status: 'SUCCESS'
      })
      .onDuplicateKeyUpdate({
        set: {
          status: 'SUCCESS',
          device_hash: finalDeviceId,
          ip_address: ipAddress,
          ua_hash: uaHash
        }
      });

    // --- REAL-TIME: Notify Faculty ---
    try {
      const { broadcastUpdate } = await import('@/lib/sse');
      broadcastUpdate('STUDENT_VERIFIED', { 
        assignment_id: session.assignment_id, 
        student_id: user.student_id,
        roll_no: user.roll_no
      });
    } catch (sseErr) {
      console.warn('[SSE] Broadcast failed:', sseErr);
    }

    return apiResponse({ 
      success: true, 
      message: 'Attendance verified successfully. The faculty will finalize the records.' 
    });

  } catch (error) {
    logger.error('Attendance Verification Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { 
  collegeInfo as collegeInfoTable, 
  semesters, 
  branchTimetable, 
  syllabusSubjects, 
  clerks 
} from '@/db/schema';
import { eq, and, desc, like, or } from 'drizzle-orm';
import { apiResponse, apiError, getAuthUser } from '@/lib/api-utils';
import { getNow } from '@/lib/clock';
import { getCurrentSemester, getBranchFromRoll } from '@/lib/rollNumber';

export async function GET(req) {
  try {
    const user = await getAuthUser('student');
    if (!user) return apiError('Unauthorized', 401);

    const rollNo = user.roll_no || user.rollNo;
    if (!rollNo) return apiError('Roll number missing.', 400);

    const now = await getNow();
    const days = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
    const day = days[now.getDay()];
    const time = now.getHours() * 100 + now.getMinutes();

    // Map time to period
    let period = null;
    if (time >= 930 && time < 1020) period = 1;
    else if (time >= 1020 && time < 1110) period = 2;
    else if (time >= 1120 && time < 1210) period = 3;
    else if (time >= 1210 && time < 1300) period = 4;
    else if (time >= 1400 && time < 1450) period = 5;
    else if (time >= 1450 && time < 1540) period = 6;
    else if (time >= 1540 && time < 1630) period = 7;

    if (!period || day === 'SUN') {
      return apiResponse({ active: false, message: 'Outside college hours' });
    }

    // Resolve context
    const collegeRows = await db.select().from(collegeInfoTable).limit(1);
    const collegeInfo = collegeRows[0] || null;
    const semester = getCurrentSemester(rollNo, collegeInfo);
    const branch = getBranchFromRoll(rollNo);

    if (!semester || !branch) {
      return apiResponse({ active: false, message: 'Context resolution failed' });
    }

    const semRow = await db.query.semesters.findFirst({
      orderBy: [desc(semesters.id)]
    });
    const systemYear = semRow?.academic_year || '2025-26';

    const timetableRows = await db.select({
      room_no: branchTimetable.room_no,
      subject_name: syllabusSubjects.subject_name,
      faculty_name: clerks.name,
      subject_code: branchTimetable.subject_code
    })
    .from(branchTimetable)
    .leftJoin(syllabusSubjects, eq(branchTimetable.subject_code, syllabusSubjects.subject_code))
    .leftJoin(clerks, eq(branchTimetable.faculty_id, clerks.id))
    .where(and(
      eq(branchTimetable.branch, branch),
      eq(branchTimetable.semester, semester),
      eq(branchTimetable.day_of_week, day),
      eq(branchTimetable.period_number, period),
      or(
        like(branchTimetable.academic_year, `%${systemYear.substring(0, 4)}%`),
        eq(branchTimetable.academic_year, '2025-26')
      )
    ))
    .limit(1);

    if (timetableRows.length === 0) {
      return apiResponse({ active: false, message: 'No lecture scheduled' });
    }

    const activity = {
      ...timetableRows[0],
      subject_name: timetableRows[0].subject_name || timetableRows[0].subject_code
    };

    return apiResponse({ 
      active: true, 
      period,
      activity 
    });
  } catch (error) {
    logger.error('Student Current Activity API Error:', error);
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import crypto from 'crypto'; 
import QRCode from 'qrcode';
import React from 'react';
import { pdf } from '@react-pdf/renderer';
import { NextResponse } from 'next/server';
import { db } from '@/db';
import { students, studentPersonalDetails, studentRequests, collegeInfo as collegeInfoTable } from '@/db/schema';
import { eq, and } from 'drizzle-orm';
import { apiError, getAuthUser } from '@/lib/api-utils';
import { getAssetUrl } from '@/lib/assets';
import path from 'path';
import fs from 'fs';
import { getBranchFromRoll } from '@/lib/rollNumber';
import { calculateYearAndSemesterAsync } from '@/lib/academic-utils';
import { getNow } from '@/lib/clock';
import { getResolvedCurrentAcademicYear } from '@/lib/rollNumber';
import { decrypt } from '@/lib/encryption';
import { studentImages } from '@/db/schema';

// React-PDF templates
import BonafideCertificatePDF from '@/pdf/templates/BonafideCertificatePDF';
import CustodianCertificatePDF from '@/pdf/templates/CustodianCertificatePDF';
import StudyConductCertificatePDF from '@/pdf/templates/StudyConductCertificatePDF';
import MigrationCertificatePDF from '@/pdf/templates/MigrationCertificatePDF';
import CourseCompletionCertificatePDF from '@/pdf/templates/CourseCompletionCertificatePDF';
import IncomeTaxCertificatePDF from '@/pdf/templates/IncomeTaxCertificatePDF';
import TransferCertificatePDF from '@/pdf/templates/TransferCertificatePDF';
import NoObjectionCertificatePDF from '@/pdf/templates/NoObjectionCertificatePDF';

const certificateComponents = {
    'Bonafide Certificate': BonafideCertificatePDF,
    'Custodian Certificate': CustodianCertificatePDF,
    'Study Conduct Certificate': StudyConductCertificatePDF,
    'Migration Certificate': MigrationCertificatePDF,
    'Course Completion Certificate': CourseCompletionCertificatePDF,
    'Income Tax (IT) Certificate': IncomeTaxCertificatePDF,
    'Transfer Certificate (TC)': TransferCertificatePDF,
    'No Objection Certificate': NoObjectionCertificatePDF,
};

export async function GET(request, context) {
    const auth = await getAuthUser('student');
    if (!auth || !auth.student_id) return apiError('Unauthorized', 401);

    try {
        const params = await context.params;
        const { request_id } = params;
        const requestIdNum = parseInt(request_id);

        const studentUser = await db.query.students.findFirst({
            columns: { email: true, is_email_verified: true, password_hash: true },
            where: eq(students.id, auth.student_id)
        });

        if (!studentUser || !studentUser.email || !studentUser.is_email_verified || !studentUser.password_hash) {
            return apiError('Verification required', 403);
        }

        // 1. Verify this request belongs to the logged-in student
        const certRequest = await db.query.studentRequests.findFirst({
            where: and(
                eq(studentRequests.request_id, requestIdNum),
                eq(studentRequests.student_id, auth.student_id)
            )
        });

        if (!certRequest) {
            return apiError('Request not found or not authorized', 404);
        }

        const Template = certificateComponents[certRequest.certificate_type];
        if (!Template || certRequest.status !== 'APPROVED') {
            return apiError('Certificate not available for download', 403);
        }

        // 2. Fetch student details
        const studentInfo = await db.select({
            name: students.name,
            roll_no: students.roll_no,
            mobile: students.mobile,
            father_name: studentPersonalDetails.father_name,
            date_of_birth: students.date_of_birth,
            perm_house_no: studentPersonalDetails.perm_house_no,
            perm_street: studentPersonalDetails.perm_street,
            perm_apartment: studentPersonalDetails.perm_apartment,
            perm_city: studentPersonalDetails.perm_city,
            perm_state: studentPersonalDetails.perm_state,
            perm_pincode: studentPersonalDetails.perm_pincode,
            perm_country: studentPersonalDetails.perm_country,
        })
        .from(students)
        .leftJoin(studentPersonalDetails, eq(students.id, studentPersonalDetails.student_id))
        .where(eq(students.id, auth.student_id))
        .limit(1);
        
        if (studentInfo.length === 0) {
            return apiError('Student details not found', 404);
        }
        const student = studentInfo[0];
        const mobile = decrypt(student.mobile) || 'N/A';
        
        const { getPermanentAddressFromDetails } = require('@/lib/address-utils');
        const address = getPermanentAddressFromDetails(student) || 'N/A';

        // Fetch college info
        const collegeRows = await db.select().from(collegeInfoTable).where(eq(collegeInfoTable.id, 1));
        const collegeInfo = collegeRows[0] || { /* empty */ };

        const { yearOfStudy, semester: currentSemester } = await calculateYearAndSemesterAsync(student.roll_no, collegeInfo);
        
        const rollNo = student.roll_no;
        const isLateral = rollNo.toUpperCase().endsWith('L');
        const admissionYearShort = parseInt(rollNo.substring(0, 2));
        const admissionYear = 2000 + admissionYearShort;
        const batchStart = isLateral ? admissionYear - 1 : admissionYear;
        const batchEnd = batchStart + 4; 
        const batchString = `${batchStart}-${batchEnd}`;
        
        const today = await getNow();
        const yearWords = ["I (FIRST)", "II (SECOND)", "III (THIRD)", "IV (FOURTH)"];
        const semesterWords = ["I (FIRST)", "II (SECOND)", "III (THIRD)", "IV (FOURTH)", "V (FIFTH)", "VI (SIXTH)", "VII (SEVENTH)", "VIII (EIGHTH)"];

        // 4. SECURITY: Generate Certificate ID & QR URL
        const SECRET_SALT = process.env.CERTIFICATE_SECRET || "fallback_salt";
        let certId = certRequest.generated_certificate_id;
        if (!certId) {
            const hash = crypto.createHmac('sha256', SECRET_SALT)
                               .update(`${student.roll_no}-${certRequest.certificate_type}-${requestIdNum}`)
                               .digest('hex');
            certId = `KUCET-${hash.substring(0, 8).toUpperCase()}`;
            await db.update(studentRequests)
                .set({ generated_certificate_id: certId })
                .where(eq(studentRequests.request_id, requestIdNum));
        }

        const isBonafide = certRequest.certificate_type === 'Bonafide Certificate';
        let attendanceValue = isBonafide ? certRequest.generated_attendance : null;

        const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || `http://localhost:${process.env.PORT || 3000}`;
        const verificationUrl = `${baseUrl}/verify?id=${certId?.trim()}&roll=${rollNo?.trim()}`;
        const qrBase64 = await QRCode.toDataURL(verificationUrl, { margin: 1, width: 150 });

        const formattedDate = `${today.getDate()}/${today.getMonth() + 1}/${today.getFullYear()}`;
        const dob = new Date(student.date_of_birth);
        const formattedDob = `${dob.getDate()}-${dob.getMonth() + 1}-${dob.getFullYear()}`;
        const course = String(getBranchFromRoll(student.roll_no) || '');

        const getBase64Image = async (imagePath) => {
            try {
                let imageBuffer;
                if (imagePath.startsWith('data:') || imagePath.startsWith('http')) {
                    const response = await fetch(imagePath);
                    if (!response.ok) return null;
                    const arrayBuffer = await response.arrayBuffer();
                    imageBuffer = Buffer.from(arrayBuffer);
                } else {
                    const cleanPath = imagePath.startsWith('/') ? imagePath.substring(1) : imagePath;
                    const fullPath = path.join(process.cwd(), 'public', cleanPath);
                    if (!fs.existsSync(fullPath)) return null;
                    imageBuffer = fs.readFileSync(fullPath);
                }
                if (!imageBuffer || imageBuffer.length < 4) return null;

                let mimeType = 'image/png';
                if (imageBuffer[0] === 0xFF && imageBuffer[1] === 0xD8) mimeType = 'image/jpeg';
                else if (imageBuffer[0] === 0x89 && imageBuffer[1] === 0x50) mimeType = 'image/png';
                else if (imageBuffer.slice(0,4).toString('ascii') === 'GIF8') mimeType = 'image/gif';
                else if (imageBuffer.slice(0,4).toString('ascii') === 'RIFF') mimeType = 'image/webp';

                return `data:${mimeType};base64,${imageBuffer.toString('base64')}`;
            } catch (err) {
                return null;
            }
        };

        const logoUrl = await getBase64Image(getAssetUrl('/assets/ku-logo.png'));
        const collegeLogoUrl = await getBase64Image(getAssetUrl('/assets/ku-college-logo.png')) || logoUrl;
        const signatureUrl = await getBase64Image(getAssetUrl('/assets/principal-sign.png'));
        const stampUrl = await getBase64Image(getAssetUrl('/assets/ku-college-seal.png'));
        const stampSign = await getBase64Image(getAssetUrl('/assets/principal-sign-stamp.png')) || signatureUrl;

        const formatDate = (d) => {
            if (!d) return '';
            const dt = new Date(d);
            if (Number.isNaN(dt.getTime())) return '';
            return `${String(dt.getDate()).padStart(2, '0')}/${String(dt.getMonth() + 1).padStart(2, '0')}/${dt.getFullYear()}`;
        };

        const commonData = {
            certId, date: formattedDate, studentName: student.name,
            fatherName: student.father_name || 'N/A', admissionNo: student.roll_no,
            course, dob: formattedDob,
            academicYear: getResolvedCurrentAcademicYear(student.roll_no, collegeInfo) || certRequest.academic_year || '',
            logoUrl, signatureUrl, stampSign, stampUrl, qrUrl: qrBase64, batch: batchString
        };

        let data = { ...commonData };
        switch (certRequest.certificate_type) {
            case 'Bonafide Certificate':
                data.year = yearWords[yearOfStudy - 1] || 'N/A';
                data.semester = semesterWords[currentSemester - 1] || 'N/A';
                data.attendancePercentage = attendanceValue || '';
                break;
            case 'Course Completion Certificate':
                data.aggCgpa = 'N/A';
                data.completionYear = today.getFullYear();
                break;
            case 'Income Tax (IT) Certificate':
                data.year = yearWords[yearOfStudy - 1] || 'N/A';
                data.semester = semesterWords[currentSemester - 1] || 'N/A';
                data.feeAmount = '35,000/- (Rupees Thirty-five Thousand only)';
                data.purpose = certRequest.purpose || '';
                break;
            case 'Transfer Certificate (TC)':
                data.conduct = 'Good';
                data.reason = 'Completion of Course';
                break;
            case 'Migration Certificate':
                data.reason = 'N/A';
                break;
            case 'Study Conduct Certificate':
                data.conduct = 'Satisfactory';
                break;
            case 'Custodian Certificate':
                data.year = yearWords[yearOfStudy - 1] || 'N/A';
                data.semester = semesterWords[currentSemester - 1] || 'N/A';
                data.hallTicket = student.roll_no;
                break;
            case 'No Objection Certificate':
                data.year = yearWords[yearOfStudy - 1] || 'N/A';
                data.semester = semesterWords[currentSemester - 1] || 'N/A';
                data.purpose = certRequest.purpose || '';
                data.fromDate = formatDate(certRequest.from_date);
                data.toDate = formatDate(certRequest.to_date);
                break;
        }

        const pdfBuffer = await pdf(<Template {...data} />).toBuffer();
        const headers = new Headers();
        headers.set('Content-Type', 'application/pdf');
        const filename = `${certRequest.certificate_type.replace(/ /g, '_')}_${student.roll_no}.pdf`;
        headers.set('Content-Disposition', `attachment; filename*=UTF-8''${encodeURIComponent(filename)}`);

        return new NextResponse(pdfBuffer, { status: 200, headers });

    } catch (error) {
        logger.error("Error generating certificate:", error);
        return apiError('An error occurred while generating the certificate.', 500, error.message);
    }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { studentProfileRequests } from '@/db/schema';
import { eq, desc } from 'drizzle-orm';
import { apiError, apiResponse, getAuthUser } from '@/lib/api-utils';

export async function GET(req) {
  const user = await getAuthUser('student');
  if (!user) return apiError('Unauthorized', 401);

  try {
    const rows = await db.query.studentProfileRequests.findMany({
      where: eq(studentProfileRequests.student_id, user.student_id),
      orderBy: [desc(studentProfileRequests.created_at)]
    });

    const imageHelper = (val) => {
      if (!val) return null;
      if (typeof val === 'string' && (val.startsWith('http') || val.startsWith('data:'))) return val;
      if (Buffer.isBuffer(val)) return `data:image/png;base64,${val.toString('base64')}`;
      return val;
    };

    const requests = rows.map(row => ({
      ...row,
      new_signature: imageHelper(row.new_signature),
      new_pfp: imageHelper(row.new_pfp)
    }));

    return apiResponse({ data: requests });
  } catch (err) {
    logger.error('Profile requests fetch error:', err);
    return apiError('Server error', 500, err.message);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { students, otpCodes } from '@/db/schema';
import { eq, and, ne } from 'drizzle-orm';
import { sendInstitutionalEmail } from '@/lib/email';
import crypto from 'crypto';
import { apiError, apiResponse, getAuthUser } from '@/lib/api-utils';
import { checkRateLimit, getTieredKey } from '@/lib/rate-limit';

export async function POST(req) {
  try {
    const ip = req.headers.get('x-forwarded-for')?.split(',')[0] || 'anonymous';
    const rateCheck = await checkRateLimit(getTieredKey(req, 'otp_send'), 5, 900); // 5 attempts per 15 min
    
    if (!rateCheck.success) {
      return apiError('Please try again after 15 minutes.', 429);
    }

    const user = await getAuthUser('student');
    if (!user) return apiError('Unauthorized', 401);

    try {
      const body = await req.json();
      const rollno = body.rollno;
      const rawEmail = body.email ? String(body.email) : '';
      const email = rawEmail.trim().replace(/\s+/g, '').replace(/[^a-zA-Z0-9@.\-_]/g, '');

      if (!rollno || !email) {
        return apiError('Missing roll number or email', 400);
      }

      // Server-side email uniqueness check
      const existingEmailRows = await db.select({ roll_no: students.roll_no })
        .from(students)
        .where(and(
          eq(students.email, email),
          ne(students.roll_no, rollno)
        ))
        .limit(1);

      if (existingEmailRows.length > 0) {
        return apiError('This email is already registered to another student.', 409);
      }
      
      const otp = crypto.randomInt(100000, 999999).toString();
      const { getNow } = await import('@/lib/clock');
      const now = getNow();
      const expiresAt = new Date(now.getTime() + 10 * 60 * 1000);

      try {
        await db.delete(otpCodes).where(eq(otpCodes.identifier, rollno));
        await db.insert(otpCodes).values({
          identifier: rollno,
          otp_code: otp,
          expires_at: expiresAt
        });
      } catch (dbError) {
        logger.error('[DATABASE ERROR] OTP management failed:', dbError);
        return apiError('Please try again after 15 minutes.', 500);
      }

      const isActivating = !user.is_email_verified;
      const subject = isActivating ? 'Activate Your KUCET Student Account' : 'Verify Your Email Address';
      const studentName = user.name || 'Student';
      const actionText = isActivating ? 'activate your student account' : 'verify your email address for your student portal account';
      
      const bodyHtml = `
        <p style="margin:0 0 12px 0;font-size:15px;color:#111827;">Hello <strong>${studentName}</strong>,</p>
        <p style="margin:0 0 18px 0;font-size:14px;color:#374151;">Use the secure One-Time Password (OTP) below to ${actionText}.</p>
        <div style="text-align:center;margin:18px 0;">
          <div style="display:inline-block;padding:16px 26px;border-radius:8px;background:linear-gradient(180deg,#ffffff,#f7f9fb);border:1px solid #e6e9ee;">
            <div style="font-size:26px;letter-spacing:4px;font-weight:700;color:#0b5ed7;">${otp}</div>
          </div>
        </div>
        <p style="margin:0 0 8px 0;font-size:13px;color:#6b7280;">This OTP will expire in <strong>10 minutes</strong>. For your security, do not share this code with anyone.</p>
        <p style="margin:8px 0 0 0;font-size:12px;color:#9ca3af;">If you did not request this, please ignore this email.</p>
      `;

      let emailResponse;
      try {
        emailResponse = await sendInstitutionalEmail({
          to: email,
          subject,
          title: isActivating ? 'Account Activation' : 'Email Verification',
          bodyHtml: bodyHtml,
        });
      } catch (mailError) {
        logger.error('[MAIL EXCEPTION] Failed during sendEmail:', mailError);
        return apiError('Please try again after 15 minutes.', 500);
      }

      if (emailResponse.success) {
        return apiResponse({ message: 'OTP sent to your new email address.' });
      } else {
        logger.error('[MAIL FAILURE] sendEmail returned false:', emailResponse.message);
        return apiError('Please try again after 15 minutes.', 500);
      }
    } catch (error) {
      logger.error('[GENERAL ERROR] send-update-email-otp:', error);
      return apiError('An internal server error occurred.', 500);
    }
  } catch (outerError) {
    logger.error('[CRITICAL ERROR] send-update-email-otp rate limit check:', outerError);
    return apiError('Internal Server Error', 500);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { 
  studentSignatures, 
  studentImages, 
  studentProfileRequests, 
  studentPersonalDetails, 
  studentAcademicBackground, 
  students 
} from '@/db/schema';
import { eq, desc, and } from 'drizzle-orm';
import { apiError, apiResponse, getAuthUser } from '@/lib/api-utils';
import { storage } from '@/lib/providers';
import { encrypt, decrypt, hashForIndex } from '@/lib/encryption';
import { getPermanentAddressFromDetails, getContactAddressFromDetails } from '@/lib/address-utils';

export async function GET(req) {
  const user = await getAuthUser('student');
  if (!user) return apiError('Unauthorized', 401);

  try {
    // Helper to handle both URLs and legacy Buffer data
    const imageHelper = (val) => {
      if (!val) return null;
      if (typeof val === 'string' && (val.startsWith('http') || val.startsWith('data:'))) return val;
      if (Buffer.isBuffer(val)) return `data:image/png;base64,${val.toString('base64')}`;
      return val;
    };
    
    // 1. Fetch current signature
    const sigRow = await db.query.studentSignatures.findFirst({
      where: eq(studentSignatures.student_id, user.student_id)
    });

    // 2. Fetch current image (PFP)
    const pfpRow = await db.query.studentImages.findFirst({
      where: eq(studentImages.student_id, user.student_id)
    });

    // 3. Fetch latest request (pending or rejected)
    const latestReqRow = await db.query.studentProfileRequests.findFirst({
      where: eq(studentProfileRequests.student_id, user.student_id),
      orderBy: [desc(studentProfileRequests.created_at)]
    });

    let latestRequest = null;
    if (latestReqRow) {
      let newData = latestReqRow.new_data;
      if (newData) {
          const data = typeof newData === 'string' ? JSON.parse(newData) : newData;
          // Decrypt sensitive fields in the request data
          if (data.mobile) data.mobile = decrypt(data.mobile);
          if (data.guardian_mobile) data.guardian_mobile = decrypt(data.guardian_mobile);
          if (data.aadhaar_no) data.aadhaar_no = decrypt(data.aadhaar_no);
          newData = data;
      }

      latestRequest = {
        ...latestReqRow,
        new_data: newData,
        new_signature: imageHelper(latestReqRow.new_signature),
        new_pfp: imageHelper(latestReqRow.new_pfp),
        proof_url: imageHelper(latestReqRow.proof_url)
      };
    }

    const currentSignature = sigRow ? imageHelper(sigRow.signature) : null;
    const currentPfp = pfpRow ? imageHelper(pfpRow.pfp) : null;

    // 4. Fetch full student details for comparison
    const personalRow = await db.query.studentPersonalDetails.findFirst({
      where: eq(studentPersonalDetails.student_id, user.student_id)
    });
    const academicRow = await db.query.studentAcademicBackground.findFirst({
      where: eq(studentAcademicBackground.student_id, user.student_id)
    });
    const studentRow = await db.query.students.findFirst({
      columns: {
        roll_no: true,
        name: true,
        mobile: true,
        email: true
      },
      where: eq(students.id, user.student_id)
    });

    // Decrypt current sensitive fields
    if (studentRow) studentRow.mobile = decrypt(studentRow.mobile);
    if (personalRow) {
        personalRow.guardian_mobile = decrypt(personalRow.guardian_mobile);
        personalRow.aadhaar_no = decrypt(personalRow.aadhaar_no);
        personalRow.contact_address = getContactAddressFromDetails(personalRow);
        personalRow.permanent_address = getPermanentAddressFromDetails(personalRow);
    }

    return apiResponse({
      signature: currentSignature,
      pfp: currentPfp,
      latestRequest: latestRequest,
      details: {
        student: studentRow || { /* empty */ },
        personal: personalRow || { /* empty */ },
        academic: academicRow || { /* empty */ }
      }
    });
  } catch (err) {
    logger.error(err, 'Profile fetch error');
    return apiError('Server error', 500, err.message);
  }
}

// Handle profile/signature update requests
export async function POST(req) {
  const user = await getAuthUser('student');
  if (!user) return apiError('Unauthorized', 401);

  try {
    const { checkRateLimit } = require('@/lib/rate-limit');
    const rateCheck = await checkRateLimit(`profile_req:${user.student_id}`, 5, 86400); // 5 per day
    if (!rateCheck.success) {
      return apiError('You can only submit 5 update requests per day.', 429);
    }

    const body = await req.json();
    const { signature, pfp, data, proof } = body;
    
    // If updating text data, proof is mandatory
    if (data && !proof) {
      return apiError('Verification proof (image) is required for updating profile details.', 400);
    }

    if (!signature && !pfp && !data) {
      return apiError('No changes provided to request an update.', 400);
    }

    // Encrypt sensitive fields in the data payload before storing
    const encryptedData = data ? { ...data } : null;
    if (encryptedData) {
        if (encryptedData.mobile) encryptedData.mobile = encrypt(encryptedData.mobile);
        if (encryptedData.guardian_mobile) encryptedData.guardian_mobile = encrypt(encryptedData.guardian_mobile);
        if (encryptedData.aadhaar_no) encryptedData.aadhaar_no = encrypt(encryptedData.aadhaar_no);
    }
    
    // Upload images to Cloudinary if provided
    let signatureUrl = null;
    let pfpUrl = null;
    let proofUrl = null;

    try {
      if (signature) signatureUrl = await storage.upload(signature, 'requests/signatures');
      if (pfp) pfpUrl = await storage.upload(pfp, 'requests/pfp');
      if (proof) proofUrl = await storage.upload(proof, 'requests/proofs');
    } catch (uploadError) {
      if (signatureUrl) await storage.delete(signatureUrl).catch(e => logger.error(e, 'Rollback signature failed'));
      if (pfpUrl) await storage.delete(pfpUrl).catch(e => logger.error(e, 'Rollback pfp failed'));
      if (proofUrl) await storage.delete(proofUrl).catch(e => logger.error(e, 'Rollback proof failed'));
      throw new Error(`Upload failed: ${uploadError.message}`);
    }

    try {
      // Check if there's already a pending request
      const pending = await db.query.studentProfileRequests.findFirst({
        where: and(
          eq(studentProfileRequests.student_id, user.student_id),
          eq(studentProfileRequests.status, 'pending')
        )
      });

      if (pending) {
        // --- ACTIVE REQUEST GUARD ---
        const existingData = pending.new_data ? (typeof pending.new_data === 'string' ? JSON.parse(pending.new_data) : pending.new_data) : { /* empty */ };
        const newFields = data ? Object.keys(data) : [];
        const existingFields = Object.keys(existingData);
        
        const overlaps = newFields.filter(f => existingFields.includes(f));
        
        if (overlaps.length > 0) {
          return apiError(`You already have a pending request for: ${overlaps.map(f => f.replace(/_/g, ' ')).join(', ')}. Please wait for clerk approval before submitting new changes for these fields.`, 400);
        }

        if (signature && pending.new_signature) {
          return apiError('You already have a pending signature update request.', 400);
        }
        if (pfp && pending.new_pfp) {
          return apiError('You already have a pending profile photo update request.', 400);
        }

        // Merge data for non-overlapping fields
        const mergedData = { ...existingData, ...(encryptedData || { /* empty */ }) };

        // Update existing pending request
        const updateData = { /* empty */ };
        if (signatureUrl) updateData.new_signature = signatureUrl;
        if (pfpUrl) updateData.new_pfp = pfpUrl;
        if (Object.keys(mergedData).length > 0) updateData.new_data = mergedData;
        if (proofUrl) updateData.proof_url = proofUrl; // Latest proof replaces old one
        
        await db.update(studentProfileRequests)
          .set(updateData)
          .where(eq(studentProfileRequests.id, pending.id));
      } else {
        // Create a new request (status defaults to 'pending')
        await db.insert(studentProfileRequests).values({
          student_id: user.student_id,
          new_signature: signatureUrl,
          new_pfp: pfpUrl,
          new_data: encryptedData || null,
          proof_url: proofUrl
        });
      }
    } catch (dbError) {
      if (signatureUrl) await storage.delete(signatureUrl).catch(e => logger.error(e, 'Rollback signature failed'));
      if (pfpUrl) await storage.delete(pfpUrl).catch(e => logger.error(e, 'Rollback pfp failed'));
      if (proofUrl) await storage.delete(proofUrl).catch(e => logger.error(e, 'Rollback proof failed'));
      throw dbError;
    }

    // REAL-TIME: Broadcast to admission clerks
    try {
      const { broadcastUpdate } = await import('@/lib/sse');
      broadcastUpdate('PROFILE_UPDATE_REQUESTED', {
        student_id: user.student_id,
        roll_no: user.roll_no
      });
    } catch (e) {
      logger.error(e, 'SSE Broadcast error');
    }

    return apiResponse({ success: true, message: 'Profile update request submitted for clerk approval.' });
  } catch (err) {
    logger.error(err, 'Profile request error');
    return apiError('Server error', 500, err.message);
  }
}

import logger from '@/lib/logger';
import { db } from '@/db';
import { studentRequests, students, certificateVerifications } from '@/db/schema';
import { eq, and, asc } from 'drizzle-orm';
import { apiError, apiResponse } from '@/lib/api-utils';
import { checkRateLimit } from '@/lib/rate-limit';

export async function POST(request) {
    try {
        const ip = request.headers.get('x-forwarded-for')?.split(',')[0] || '127.0.0.1';
        
        // 0. RATE LIMITING (5 requests per minute per IP)
        const rl = await checkRateLimit(`verify_cert_${ip}`, 5, 60);
        if (!rl.success) {
            logger.warn(`[VERIFY_BLOCKED] Rate limit exceeded for IP: ${ip}`);
            return apiResponse({ valid: false, message: "Too many attempts. Please try again later." }, 429);
        }

        const body = await request.json();
        
        // Normalize inputs
        const certId = body.certId?.trim()?.toUpperCase() || null;
        const rollNo = body.rollNo?.trim()?.toUpperCase() || null;

        if (!certId || !rollNo) {
            return apiResponse({ valid: false, message: "Missing params" }, 400);
        }

        // 1. Check for the certificate by ID only first to be more robust
        const results = await db.select({
            request_id: studentRequests.request_id,
            generated_certificate_id: studentRequests.generated_certificate_id,
            certificate_type: studentRequests.certificate_type,
            name: students.name,
            roll_no: students.roll_no,
            status: studentRequests.status,
            completed_at: studentRequests.completed_at
        })
        .from(studentRequests)
        .innerJoin(students, eq(studentRequests.student_id, students.id))
        .where(eq(studentRequests.generated_certificate_id, certId))
        .orderBy(asc(studentRequests.status));

        // 2. Find the exact match manually to handle potential DB-level spacing/casing
        const certData = results.find(r => 
            r.roll_no?.trim()?.toUpperCase() === rollNo
        );

        if (!certData) {
            logger.info(`[VERIFY_FAIL] No matching Roll No for Cert ID: "${certId}". Input Roll: "${rollNo}"`);
            return apiResponse({ valid: false });
        }
        
        if (certData.status !== 'APPROVED') {
            logger.info(`[VERIFY_FAIL] Record found but status is ${certData.status}. ID: "${certId}"`);
            return apiResponse({ valid: false });
        }

        // 3. LOG THE VERIFICATION 
        const userAgent = request.headers.get('user-agent') || 'Unknown Device';
        const deviceName = body.deviceName || null;
        const latitude = body.latitude || null;
        const longitude = body.longitude || null;

        // IP-based Location Lookup (Multi-tier Fail-over)
        let locationName = 'Unknown Location';
        let finalLat = latitude ? String(latitude) : null;
        let finalLon = longitude ? String(longitude) : null;

        /**
         * Multi-tier Geolocation Strategy:
         * 1. Primary: ipapi.co (HTTPS, 1000/day limit)
         * 2. Fallback: ip-api.com (HTTP, 45/min limit)
         * 3. Silence: If all fail, use 'Unknown Location' and don't crash.
         */
        const fetchGeoData = async (clientIp) => {
            if (!clientIp || clientIp === '127.0.0.1' || clientIp === '::1') return null;

            try {
                // Tier 1: Primary (HTTPS)
                const res = await fetch(`https://ipapi.co/${clientIp}/json/`, { timeout: 3000 });
                const data = await res.json();
                if (!data.error) return {
                    location: `${data.city}, ${data.region}`,
                    lat: String(data.latitude),
                    lon: String(data.longitude)
                };
            } catch (e1) {
                logger.warn(`[GEOLOCATION_T1_FAIL] ${clientIp}: ${e1.message}`);
                try {
                    // Tier 2: Fallback (HTTP)
                    const res2 = await fetch(`http://ip-api.com/json/${clientIp}?fields=status,city,regionName,lat,lon`, { timeout: 3000 });
                    const data2 = await res2.json();
                    if (data2.status === 'success') return {
                        location: `${data2.city}, ${data2.regionName}`,
                        lat: String(data2.lat),
                        lon: String(data2.lon)
                    };
                } catch (e2) {
                    logger.warn(`[GEOLOCATION_T2_FAIL] ${clientIp}: ${e2.message}`);
                }
            }
            return null;
        };

        try {
            const geo = await fetchGeoData(ip);
            if (geo) {
                locationName = geo.location;
                if (!finalLat) finalLat = geo.lat;
                if (!finalLon) finalLon = geo.lon;
            }
        } catch (globalGeoErr) {
            // Absolute silence on geolocation crash to prevent app failure
            logger.error("[GEOLOCATION_CRITICAL_ERROR]", globalGeoErr.message);
        }

        try {
            await db.insert(certificateVerifications).values({
                request_id: certData.request_id,
                ip_address: ip,
                user_agent: userAgent,
                device_name: deviceName,
                location_name: locationName,
                latitude: finalLat,
                longitude: finalLon
            });
            logger.info(`[VERIFY] Logged scan for Request ID: ${certData.request_id}`);
        } catch (dbErr) {
            logger.error("[VERIFY] Logging to table failed:", dbErr.message);
        }

        // 4. Return success details to the frontend
        return apiResponse({
            valid: true,
            details: {
                name: certData.name,
                roll_no: certData.roll_no,
                cert_id: certData.generated_certificate_id,
                issue_date: (certData.completed_at && !isNaN(new Date(certData.completed_at).getTime())) 
                    ? new Date(certData.completed_at).toLocaleDateString('en-GB') 
                    : 'N/A',
                cert_type: certData.certificate_type,
                type: certData.certificate_type
            }
        });

    } catch (error) {
        logger.error("Critical Verification Error:", error);
        return apiError("Internal Server Error", 500, { valid: false });
    }
}

import { db } from '@/db';
import { 
  students as studentsTable, 
  studentPersonalDetails, 
  studentAcademicBackground,
  studentImportLogs
} from '@/db/schema';
import { eq, inArray } from 'drizzle-orm';
import { StudentService } from '@/services/StudentService';
import { verifySignatureAppRouter } from "@upstash/qstash/nextjs";
import { NextResponse } from 'next/server';

async function handler(req) {
  try {
    const body = await req.json();
    const { chunk, clerkId, importFileName } = body;

    if (!chunk || !chunk.length) {
      return NextResponse.json({ success: true, message: 'Empty chunk' });
    }

    const incomingRolls = chunk.map(p => p.student.roll_no);
    const incomingEmails = chunk.map(p => p.student.email).filter(Boolean);

    // Fetch existing students by Roll No
    const existingByRoll = await db.select({
      id: studentsTable.id,
      roll_no: studentsTable.roll_no,
      email: studentsTable.email
    })
    .from(studentsTable)
    .where(inArray(studentsTable.roll_no, incomingRolls));

    // Fetch existing students by Email (to prevent cross-collisions)
    const existingByEmail = incomingEmails.length > 0 ? await db.select({
      id: studentsTable.id,
      roll_no: studentsTable.roll_no,
      email: studentsTable.email
    })
    .from(studentsTable)
    .where(inArray(studentsTable.email, incomingEmails)) : [];

    const rollMap = new Map(existingByRoll.map(s => [s.roll_no, s]));
    const emailMap = new Map(existingByEmail.map(s => [s.email, s]));

    let insertedCount = 0;
    let updatedCount = 0;
    const errors = [];
    const processedEmails = new Set();

    await db.transaction(async (tx) => {
      for (const rec of chunk) {
        const { student, personal, academic } = rec;
        
        // Collision Check: If email exists but belongs to a DIFFERENT roll number
        if (student.email) {
          const emailCollision = emailMap.get(student.email);
          if (emailCollision && emailCollision.roll_no !== student.roll_no) {
            errors.push({ 
              row: rec.rowNumber, 
              roll_no: student.roll_no, 
              reason: `Email (${student.email}) is already assigned to student ${emailCollision.roll_no}` 
            });
            continue; 
          }
          if (processedEmails.has(student.email)) {
            errors.push({ 
              row: rec.rowNumber, 
              roll_no: student.roll_no, 
              reason: `Email (${student.email}) is duplicated within the import file` 
            });
            continue;
          }
        }

        const isUpdate = rollMap.has(student.roll_no);

        // Perform Upsert via StudentService
        await StudentService.upsertStudent({
          ...student,
          ...personal,
          ...academic
        }, clerkId, tx);

        if (student.email) processedEmails.add(student.email);

        if (isUpdate) updatedCount++;
        else insertedCount++;
      }

      if (insertedCount > 0 || updatedCount > 0) {
        await tx.insert(studentImportLogs).values({ 
          clerk_id: clerkId, 
          total_records: insertedCount + updatedCount, 
          file_name: importFileName 
        });
      }
    });

    return NextResponse.json({ success: true, insertedCount, updatedCount, errors });
  } catch (err) {
    console.error('Bulk Import Webhook Error:', err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

// Verify QStash Signature to ensure only Upstash can call this
export const POST = process.env.QSTASH_TOKEN ? verifySignatureAppRouter(handler) : handler;

'use client';
import { useEffect, useState, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import toast from 'react-hot-toast';
import { useClerk } from '@/context/ClerkContext';
import AttendanceSheet from '@/components/clerk/faculty/AttendanceSheet';
import MobileAttendanceSheet from '@/components/clerk/faculty/MobileAttendanceSheet';
import { FacultyAttendanceProvider } from '@/context/FacultyAttendanceContext';

function AttendanceContent() {
  const searchParams = useSearchParams();
  const assignmentId = searchParams.get('id');
  const { clerkData: clerk, loading: isLoading } = useClerk();
  const [assignments, setAssignments] = useState([]);
  const [loadingAssignments, setLoadingAssignments] = useState(true);
  const [selectedAssignment, setSelectedAssignment] = useState(null);

  useEffect(() => {
    const fetchAssignments = async () => {
      setLoadingAssignments(true);
      try {
        const res = await fetch('/api/clerk/faculty/assignments');
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Failed to fetch assignments');
        
        const assignmentsList = data.data || [];
        // Sort assignments: Active first, History last
        const sortedAssignments = [...assignmentsList].sort((a, b) => {
          if (a.is_active === b.is_active) return 0;
          return a.is_active ? -1 : 1;
        });
        
        setAssignments(sortedAssignments);

        // Pre-select if ID is in URL
        if (assignmentId) {
          const preSelected = assignmentsList.find(a => String(a.id) === String(assignmentId));
          if (preSelected) setSelectedAssignment(preSelected);
        }
      } catch (e) {
        toast.error(e.message);
      } finally {
        setLoadingAssignments(false);
      }
    };
    fetchAssignments();
  }, [assignmentId]);

  const resetSelection = () => {
    setSelectedAssignment(null);
  };

  const SubjectCard = ({ assignment, onSelect }) => {
    const isActive = assignment.is_active;
    
    return (
      <div
        onClick={() => onSelect(assignment)}
        className={`border-2 rounded-2xl p-5 transition-all duration-300 relative group overflow-hidden cursor-pointer ${
          isActive 
            ? 'bg-white border-indigo-50 hover:shadow-xl hover:border-indigo-200' 
            : 'bg-gray-50 border-gray-100 opacity-80 grayscale-[0.5] hover:grayscale-0 hover:opacity-100'
        }`}
      >
        <div className={`absolute -right-4 -top-4 w-16 h-16 rounded-full opacity-50 group-hover:scale-150 transition-transform duration-500 ${
          isActive ? 'bg-indigo-50' : 'bg-gray-200'
        }`}></div>

        <div className="relative">
            <div className="flex justify-between items-start mb-2">
            <div className="flex-1 min-w-0">
              <div className={`font-black text-xl leading-tight mb-1 break-words ${
                isActive ? 'text-indigo-900' : 'text-gray-600'
              }`}>
                {assignment.subject_name}
              </div>
              <div className={`text-xs font-mono font-bold mb-2 uppercase tracking-widest ${
                isActive ? 'text-indigo-500' : 'text-gray-400'
              }`}>
                {assignment.subject_code}
              </div>
            </div>
            <div className="ml-3 flex-shrink-0">
              <span className={`text-xs font-bold px-3 py-1 rounded-full ${
                isActive ? 'text-emerald-600 bg-emerald-50' : 'text-gray-500 bg-gray-200'
              }`}>
                {isActive ? 'Active' : 'History'}
              </span>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4 mb-2">
            <div className="bg-white/50 p-2 rounded-xl border border-gray-100">
              <div className="text-[10px] text-gray-400 font-bold uppercase">Branch</div>
              <div className="text-xs font-bold text-gray-700 truncate">{assignment.branch}</div>
            </div>
            <div className="bg-white/50 p-2 rounded-xl border border-gray-100">
              <div className="text-[10px] text-gray-400 font-bold uppercase">Semester</div>
              <div className="text-xs font-bold text-gray-700"> {assignment.semester}</div>
            </div>
          </div>

          <div className="text-[10px] text-gray-400 font-bold uppercase mt-2">Academic Year</div>
          <div className="text-xs font-bold text-gray-700">{assignment.academic_year}</div>
        </div>
      </div>
    );
  };

  const activeAssignments = assignments.filter(a => a.is_active);
  const historyAssignments = assignments.filter(a => !a.is_active);

  return (
    <>
      <div className="mb-6">
        <h1 className="text-2xl md:text-3xl font-bold">Attendance</h1>
        <p className="text-gray-600">
          {selectedAssignment ? `Managing attendance for ${selectedAssignment.subject_name}` : 'Select a subject to manage attendance.'}
        </p>
      </div>

      {!selectedAssignment ? (
        loadingAssignments ? (
          <div className="text-center py-6">Loading assignments...</div>
        ) : assignments.length > 0 ? (
          <div className="space-y-12">
            {/* Active Subjects */}
            {activeAssignments.length > 0 && (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {activeAssignments.map(assignment => (
                  <SubjectCard key={assignment.id} assignment={assignment} onSelect={setSelectedAssignment} />
                ))}
              </div>
            )}

            {/* Inactive/History Subjects */}
            {historyAssignments.length > 0 && (
              <section className="pt-8 border-t border-gray-200">
                <div className="flex items-center gap-2 mb-6 text-gray-500">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  <h2 className="text-lg font-bold uppercase tracking-wider">Subject History</h2>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
