import StudentAcademicSummaryCard from '@/components/clerk/scholarship/StudentAcademicSummaryCard';
import YearRecordsList from '@/components/clerk/scholarship/YearRecordsList';
import AddEditRecordModal from '@/components/clerk/scholarship/AddEditRecordModal';
import AddEditRecordInstitutionalModal from '@/components/clerk/scholarship/AddEditRecordInstitutionalModal';
import ScholarshipMetricsCards from '@/components/clerk/scholarship/ScholarshipMetricsCards';
import ScholarshipSearchCard from '@/components/clerk/scholarship/ScholarshipSearchCard';
import ScholarshipWindowCard from '@/components/clerk/scholarship/ScholarshipWindowCard';
import { useScholarshipDashboard } from '@/context/ScholarshipDashboardContext';
import toast from 'react-hot-toast';
import { validateRollNo } from '@/lib/rollNumber';
import { formatDate, toMySQLDate } from '@/lib/date';
import LoadingSpinner from '@/components/ui/LoadingSpinner';
import { smoothScrollToId } from '@/lib/scroll-utils';
import { logoutScholarshipDashboard } from '@/lib/logout';


function ScholarshipDashboardContent() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const { clerkData: clerk, loading: isClerkLoading } = useClerk();
  const { state, setField, resetStudent, setState } = useScholarshipDashboard();
  const {
    roll,
    searchMode,
    applicationNoInput,
    nameInput,
    nameResults,
    rollError,
    student,
    feeSummary,
    yearList,
    summariesByYear,
    expandedByYear,
  } = state;
  const setRoll = (v) => setField('roll', v);
  const setSearchMode = (v) => setField('searchMode', v);
  const setApplicationNoInput = (v) => setField('applicationNoInput', v);
  const setNameInput = (v) => setField('nameInput', v);
  const setNameResults = (v) => setField('nameResults', v);
  const setRollError = (v) => setField('rollError', v);
  const setExpandedByYear = (updater) => {
    setState((prev) => ({
      ...prev,
      expandedByYear:
        typeof updater === 'function'
          ? updater(prev.expandedByYear || { /* empty */ })
          : updater,
    }));
  };
  const MAX_ROLL = 10;
  const [loading, setLoading] = useState(false); // For fetching student data
  const [scholarshipProceedings, setScholarshipProceedings] = useState([]);
  const [studentPayments, setStudentPayments] = useState([]);
  const [imagePreviewOpen, setImagePreviewOpen] = useState(false);
  const [imagePreviewSrc, setImagePreviewSrc] = useState(null);
  const [view, setView] = useState('dashboard');

  const firstName = clerk?.name?.split(' ')[0] || 'Clerk';
  const employeeId = clerk?.employee_id || (clerk?.role ? String(clerk.role).toUpperCase() : 'SCHOLARSHIP');
  const roleLabel = 'Scholarship Clerk';

  const openProfile = () => {
    try {
      router.push('/clerk/scholarship/profile');
    } catch {
      // ignore
    }
  };

  const backToDashboard = () => {
    setView('dashboard');
    try {
      router.push('/clerk/scholarship/dashboard');
    } catch {
      // ignore
    }
  };

  // URL Parameter Handling: switch view and auto-scroll
  useEffect(() => {
    const v = searchParams.get('view');
    const scroll = searchParams.get('scroll');

    let viewTimer;
    let scrollTimer;

    if (v === 'requests' || v === 'certificates' || v === 'verification') {
      viewTimer = setTimeout(() => {
        setView('certificates');
      }, 0);

      if (scroll === '1') {
        scrollTimer = setTimeout(() => {
          smoothScrollToId('certificate-section', { behavior: 'smooth', block: 'start' });
        }, 800);
      }
    }

    return () => {
      if (viewTimer) clearTimeout(viewTimer);
      if (scrollTimer) clearTimeout(scrollTimer);
    };
  }, [searchParams]);

  const [metricsRefreshToken, setMetricsRefreshToken] = useState(0);
  const [modalOpen, setModalOpen] = useState(false);
  const [modalYear, setModalYear] = useState('');
  // Modal form state
  const [schAppNo, setSchAppNo] = useState('');
  const [schProceedingNo, setSchProceedingNo] = useState('');
  const [schAmount, setSchAmount] = useState('');
  const [schDate, setSchDate] = useState(''); // This was being used for sanction_date in some places, let's normalize
  const [schSanctionDate, setSchSanctionDate] = useState('');
  const [releasedAmount, setReleasedAmount] = useState('');
  const [releasedDate, setReleasedDate] = useState('');
  const [schStatus, setSchStatus] = useState('SANCTIONED');
  const [payAmount, setPayAmount] = useState('');
  const [payRef, setPayRef] = useState('');
  const [payDate, setPayDate] = useState('');
  const [payMode, setPayMode] = useState('UPI');
  const [bankName, setBankName] = useState('');
  const [saving, setSaving] = useState(false);
  const [appEditing, setAppEditing] = useState(false);
  const [thumbUpdateAvailable, setThumbUpdateAvailable] = useState(false);
  const [thumbStatus, setThumbStatus] = useState('Pending');
  const [hardcopySubmitted, setHardcopySubmitted] = useState(false);
  const [selectedProceeding, setSelectedProceeding] = useState(null); // For edit mode

  // Helper to set form state from modal-like callers
  const setFormState = (k, v) => {
    const setters = {
      schAppNo: setSchAppNo,
      schProceedingNo: setSchProceedingNo,
      schAmount: setSchAmount,
      schSanctionDate: setSchSanctionDate,
      releasedAmount: setReleasedAmount,
      releasedDate: setReleasedDate,
      payAmount: setPayAmount,
      payRef: setPayRef,
      payDate: setPayDate,
      payMode: setPayMode,
      bankName: setBankName,
      appEditing: setAppEditing,
      thumbUpdateAvailable: setThumbUpdateAvailable,
      thumbStatus: setThumbStatus,
      hardcopySubmitted: setHardcopySubmitted,
      schStatus: setSchStatus,
    };
    const fn = setters[k] || (() => { /* empty */ });
    fn(v);
  };

  const handleClearDashboard = () => {
    // Clear search inputs
    setRoll('');
    setApplicationNoInput('');
    setNameInput('');
    setNameResults([]);
    setRollError('');
    setSearchMode('roll');

    // Clear loaded student/session data
    localResetStudent();

    // Reset modal-related local state
    setModalOpen(false);
    setModalYear('');
    setSchAppNo('');
    setSchProceedingNo('');
    setSchAmount('');
    setSchSanctionDate('');
    setReleasedAmount('');
    setReleasedDate('');
    setSchStatus('SANCTIONED');
    setPayAmount('');
    setPayRef('');
    setPayDate('');
    setPayMode('UPI');
    setBankName('');
    setSaving(false);
    setAppEditing(false);
    setThumbUpdateAvailable(false);
    setThumbStatus('Pending');
    setHardcopySubmitted(false);
    setSelectedProceeding(null);

    // Scroll back to the top of the dashboard for clarity
    smoothScrollToId('scholarship-dashboard-top', { behavior: 'smooth', block: 'start' });
  };

  


  useEffect(() => {
    if (!isClerkLoading && clerk && clerk.role !== 'scholarship') {
      toast.error('Access Denied');
    }
  }, [clerk, isClerkLoading]);

  // Date formatting helper (UI only)
  const toDmy = (val) => formatDate(val) || '-';

  // UI must not parse roll number; rely only on backend fields

  const handleLogout = () => {
    logoutScholarshipDashboard();
  };

  const localResetStudent = () => {
    resetStudent();
    setScholarshipProceedings([]);
    setStudentPayments([]);
  };

  const handleSelectStudentFromName = async (rollNo) => {
    if (!rollNo) return;
    setRoll(String(rollNo));
    setSearchMode('roll');
    setNameResults([]);
    // Reuse existing roll search flow
    try {
      await fetchStudent();
    } catch {
      // fetchStudent already reports errors via toast
    }
  };

  const fetchStudent = async (e) => {
    if (e && e.preventDefault) e.preventDefault();

    // Name search: only fetch list of candidates; selection will refetch by roll
    if (searchMode === 'name') {
      const term = String(nameInput || '').trim();
      if (term.length < 2) {
        toast.error('Enter at least 2 characters for name search');
        return;
      }
      setLoading(true);
      setNameResults([]);
      const id = toast.loading('Searching students by name...');
      try {
        const url = `/api/clerk/scholarship/search-by-name?name=${encodeURIComponent(term)}`;
        const res = await fetch(url);
        const data = await res.json();
        if (!res.ok) throw new Error(data?.error || 'Failed to search students');
        const list = Array.isArray(data?.students) ? data.students : [];
        if (list.length === 0) {
          toast.error('No students found for given name', { id });
        } else {
          toast.success(`Found ${list.length} student(s)`, { id });
        }
        setNameResults(list);
      } catch (err) {
        toast.error(err.message || 'Failed to search students', { id });
      } finally {
        setLoading(false);
      }
      return;
    }

    if (searchMode === 'roll') {
      if (!roll) return;
      // Enforce same client-side constraints as LoginPanel / Admission clerk
      if (String(roll).length !== MAX_ROLL) {
        toast.error(`Roll Number must be ${MAX_ROLL} characters long`);
        return;
      }
      try {
        const { isValid } = validateRollNo(String(roll));
        if (!isValid) {
          toast.error('Invalid Roll Number format');
          return;
        }
      } catch (err) {
        toast.error('Invalid Roll Number format');
        return;
      }
    } else {
      if (!applicationNoInput) return;
    }
    setLoading(true);
    localResetStudent();
    const id = toast.loading('Fetching student...');
    try {
      let res, data, payload;
      if (searchMode === 'roll') {
        res = await fetch(`/api/clerk/scholarship/summary/${encodeURIComponent(roll)}`);
        data = await res.json();
        if (!res.ok) throw new Error((data && data.error) || 'Student not found');
        payload = (data && data.data) ? data.data : data;
        setField('student', payload.student || null);
        setField('feeSummary', payload.fee_summary || null);
        setScholarshipProceedings(Array.isArray(payload.scholarship_proceedings) ? payload.scholarship_proceedings : []);
        setStudentPayments(Array.isArray(payload.student_payments) ? payload.student_payments : []);

        // Build 4-year list from admission academic year period (e.g., 2023-2027)
        const list = deriveYearsFromAdmission(String(payload?.student?.admission_year || ''));
        setField('yearList', list);
        // Fetch summaries for each year in parallel; store by year
        const urls = list.map(y => `/api/clerk/scholarship/summary/${encodeURIComponent(roll)}?year=${encodeURIComponent(y)}`);
        const results = await Promise.allSettled(urls.map(u => fetch(u).then(r => r.ok ? r.json() : null).catch(() => null)));
        const byYear = { /* empty */ };
        results.forEach((res, idx) => {
          const y = list[idx];
          const raw = (res.status === 'fulfilled' ? res.value : null) || null;
          byYear[y] = raw && raw.data ? raw.data : raw;
        });
        setField('summariesByYear', byYear);
        // Default collapsed view for all cards
        setField('expandedByYear', list.reduce((acc, y) => { acc[y] = false; return acc; }, { /* empty */ }));
      } else {
        // Application number search — expects { student, year_records }
        res = await fetch(`/api/clerk/scholarship/application/${encodeURIComponent(applicationNoInput)}`);
        data = await res.json();
        if (!res.ok) throw new Error((data && data.error) || 'Student not found');
        payload = (data && data.data) ? data.data : data;
        setField('student', payload.student || null);
        // If backend provided per-year records, use them directly
        if (payload.year_records && typeof payload.year_records === 'object') {
          const years = Object.keys(payload.year_records || { /* empty */ });
          setField('yearList', years);
          setField('summariesByYear', payload.year_records);
          setField('expandedByYear', years.reduce((acc, y) => { acc[y] = false; return acc; }, { /* empty */ }));
        } else {
          // Fallback to derive from student
          const list = deriveYearsFromAdmission(String(payload?.student?.admission_year || ''));
          setField('yearList', list);
          setField('expandedByYear', list.reduce((acc, y) => { acc[y] = false; return acc; }, { /* empty */ }));
        }
      }

      toast.success('Student loaded', { id });
    } catch (err) {
      toast.error(err.message || 'Failed to fetch student', { id });
    } finally {
      setLoading(false);
    }
  };

  // Derive 4 academic years (YYYY-YY) from an admission period like "2023-2027"
  function deriveYearsFromAdmission(period) {
    const m = String(period).match(/^(\d{4})-(\d{4})$/);
    if (!m) return [];
    const start = parseInt(m[1], 10);
    // Generate Year 1..4 as YYYY-YY
    return [0,1,2,3].map(offset => {
      const s = start + offset;
      const e = s + 1;
      return `${s}-${String(e).slice(-2)}`;
    });
  }

  // Determine canonical record state for a year from backend summary or fallbacks.
  // Returns 'NO_RECORD' | 'PENDING' | 'COMPLETED'
  function computeRecordState(summary, globalFeeSummary) {
    // If no summary object at all, there are no DB rows for this year
    if (!summary) return 'NO_RECORD';

    const hasScholar = Array.isArray(summary.scholarship_proceedings) && summary.scholarship_proceedings.length > 0;
    const hasPayments = Array.isArray(summary.student_payments) && summary.student_payments.length > 0;
    const hasApplication = !!(summary.application_no && String(summary.application_no).trim() !== '');

    if (!hasScholar && !hasPayments && !hasApplication) return 'NO_RECORD';

    // Prefer explicit record_state from backend if provided
    if (summary.record_state && ['NO_RECORD', 'PENDING', 'COMPLETED'].includes(summary.record_state)) return summary.record_state;

    // Try to derive from fee_summary.pending_fee (if present)
    const fs = summary.fee_summary || { /* empty */ };
    let pending = fs.pending_fee;

    // If pending not available, use globalFeeSummary total_fee as fallback and assume nothing paid
    if (pending == null) {
      const total = fs.total_fee ?? globalFeeSummary?.total_fee ?? null;
      if (total == null) {
        // We have records but no fee numbers -> treat as PENDING to force clerk attention
        return 'PENDING';
      }
      // No payments recorded: pending equals total
      pending = total;
    }

    const pendingNum = Number(pending);
    if (!isNaN(pendingNum) && pendingNum === 0) return 'COMPLETED';
    return 'PENDING';
  }

  function openAddModal(year) {
    setModalYear(year);
    setModalOpen(true);
    // Reset fields
    try {
      const existingApp = (summariesByYear[year]?.application_no) || '';
      setSchAppNo(existingApp);
      setAppEditing(false);
    } catch { setSchAppNo(''); setAppEditing(false); }
    // Clear proceeding entry fields (Institutional workflow: new entry per row)
    setSchProceedingNo('');
    setSchAmount('');
    setSchSanctionDate('');
    setReleasedAmount('');
    setReleasedDate('');
    setSchStatus('SANCTIONED');
    setPayAmount('');
    setPayRef('');
    setPayDate('');
    setPayMode('UPI');
    setBankName('');
    setSelectedProceeding(null);
    // Thumb fields - hydrate from stored summary and normalize values
    try {
      const summaryData = summariesByYear[year] || { /* empty */ };
      const thumbAvailable = summaryData?.thumb_update_available === 1 || summaryData?.thumb_update_available === true;
      const thumbStatusRaw = summaryData?.thumb_status ?? 'PENDING';
      const ts = String(thumbStatusRaw).toLowerCase();
      const completeValues = ['complete', '1', 'true', 'success', 'done'];
      const thumbStatusNorm = completeValues.includes(ts) ? 'Complete' : 'Pending';
      // initialize via setFormState so modal setter API is used
      setFormState('thumbUpdateAvailable', thumbAvailable);
      setFormState('thumbStatus', thumbStatusNorm);
    } catch {
      setFormState('thumbUpdateAvailable', false);
      setFormState('thumbStatus', 'Pending');
    }
    // Hardcopy submission flag
    try {
      const summaryData = summariesByYear[year] || { /* empty */ };
      const hardcopy = summaryData?.hardcopy_submitted === 1 || summaryData?.hardcopy_submitted === true;
      setFormState('hardcopySubmitted', hardcopy);
    } catch {
      setFormState('hardcopySubmitted', false);
    }
  }

  async function refetchYearSummary(rollNo, year) {
    try {
      const res = await fetch(`/api/clerk/scholarship/summary/${encodeURIComponent(rollNo)}?year=${encodeURIComponent(year)}`);
      const data = res.ok ? await res.json() : null;
      const payload = data && data.data ? data.data : data;
      setField('summariesByYear', {
        ...summariesByYear,
        [year]: payload,
      });
    } catch { /* empty */ }
  }

  async function handleProceedingSave() {
    if (!student || !modalYear) return;
    setSaving(true);
    try {
      if (!schAppNo) throw new Error('Application Number is required');
      const hasAmount = Number(schAmount) > 0;
      if (hasAmount && !String(schProceedingNo || '').trim()) {
        throw new Error('Proceeding Number is required to enter sanctioned amount');
      }
      if (hasAmount && !schSanctionDate) {
        throw new Error('Sanction Date is required for entered amount');
      }
      const hasRelAmount = Number(releasedAmount) > 0;
      if (hasRelAmount && !releasedDate) {
        throw new Error('Released Date is required for entered amount');
      }

      const amt = hasAmount ? Number(schAmount) : null;
      const sanctionBody = {
        roll_no: student.roll_no,
        academic_year: modalYear,
        application_no: schAppNo || null,
        proceeding_no: schProceedingNo || null,
        sanctioned_amount: amt,
        sanction_date: schSanctionDate || null,
        released_amount: hasRelAmount ? Number(releasedAmount) : null,
        released_date: releasedDate || null,
        status: schStatus || 'SANCTIONED',
        thumb_update_available: !!thumbUpdateAvailable,
        thumb_status: thumbStatus || 'Pending',
        hardcopy_submitted: hardcopySubmitted ? 1 : 0,
      };

      if (process.env.NODE_ENV === 'development') {
        console.info('[DEBUG] Proceeding Save Payload:', sanctionBody);
      }

      const res = await fetch('/api/clerk/scholarship/sanctions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(sanctionBody)
      });
      const data = await res.json();
      
      if (process.env.NODE_ENV === 'development') {
        console.info('[DEBUG] Proceeding Save Response:', { status: res.status, data });
      }

      if (!res.ok) throw new Error(data.error || 'Failed to save sanction');
      
      toast.success('Proceeding recorded');
      setSchProceedingNo('');
      setSchAmount('');
      setSchSanctionDate('');
      setReleasedAmount('');
      setReleasedDate('');
      setSelectedProceeding(null);
      await refetchYearSummary(student.roll_no, modalYear);
    } catch (err) {
      toast.error(err.message || 'Failed to save proceeding');
    } finally {
      setSaving(false);
    }
  }

  async function handlePaymentSave() {
    if (!student || !modalYear) return;
    setSaving(true);
    try {
      const pAmt = Number(payAmount);
      if (!(pAmt > 0)) throw new Error('Student Paid Amount must be > 0');
      if (!payRef) throw new Error('Transaction Ref is required');
      if (!payDate) throw new Error('Transaction Date is required');

      const paymentBody = {
        roll_no: student.roll_no,
        academic_year: modalYear,
        transaction_ref: payRef,
        amount: pAmt,
        transaction_date: payDate,
        payment_mode: payMode || 'UPI',
        bank_name: bankName || null,
      };

      if (process.env.NODE_ENV === 'development') {
        console.info('[DEBUG] Payment Save Payload:', paymentBody);
      }

      const res = await fetch('/api/clerk/scholarship/payments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(paymentBody)
      });
      const data = await res.json();

      if (process.env.NODE_ENV === 'development') {
        console.info('[DEBUG] Payment Save Response:', { status: res.status, data });
      }

      if (!res.ok) throw new Error(data.error || 'Failed to save payment');

      toast.success('Payment recorded');
      setPayAmount('');
      setPayRef('');
      setPayDate('');
      setPayMode('UPI');
      setBankName('');
      await refetchYearSummary(student.roll_no, modalYear);
    } catch (err) {
      toast.error(err.message || 'Failed to save payment');
    } finally {
      setSaving(false);
    }
  }

  async function handleFinalUpdate() {
    if (!student || !modalYear) return;
    setSaving(true);
    try {
      const updateBody = {
        roll_no: student.roll_no,
        academic_year: modalYear,
        application_no: schAppNo || null,
        hardcopy_submitted: hardcopySubmitted ? 1 : 0,
        thumb_update_available: !!thumbUpdateAvailable,
        thumb_status: thumbStatus || 'Pending'
      };

      if (process.env.NODE_ENV === 'development') {
        console.info('[DEBUG] Final Update Payload:', updateBody);
      }

      const res = await fetch('/api/clerk/scholarship/sanctions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updateBody)
      });
      const data = await res.json();

      if (process.env.NODE_ENV === 'development') {
        console.info('[DEBUG] Final Update Response:', { status: res.status, data });
      }

      if (!res.ok) throw new Error(data.error || 'Failed to update registry');

      toast.success('Registry record updated');
      setModalOpen(false);
      await refetchYearSummary(student.roll_no, modalYear);
    } catch (err) {
      toast.error(err.message || 'Failed to save record');
    } finally {
      setSaving(false);
    }
  }

  async function deleteScholarship(id) {
    if (!id) return;
    if (!confirm('Delete this scholarship proceeding?')) return;
    try {
      const res = await fetch(`/api/clerk/scholarship/sanctions/${id}`, { method: 'DELETE' });
      if (!res.ok) {
        const e = await res.json().catch(() => ({ /* empty */ }));
        throw new Error(e.error || 'Failed to delete proceeding');
      }
      toast.success('Proceeding deleted');
      await refetchYearSummary(student.roll_no, modalYear);
    } catch (err) {
      toast.error(err.message || 'Failed to delete proceeding');
    }
  }

  async function deletePayment(id) {
    if (!id) return;
    if (!confirm('Delete this payment?')) return;
    try {
      const res = await fetch(`/api/clerk/scholarship/payments/${id}`, { method: 'DELETE' });
      if (!res.ok) {
        const e = await res.json().catch(() => ({ /* empty */ }));
        throw new Error(e.error || 'Failed to delete payment');
      }
      toast.success('Payment deleted');
      await refetchYearSummary(student.roll_no, modalYear);
    } catch (err) {
      toast.error(err.message || 'Failed to delete payment');
    }
  }


  if (isClerkLoading && !clerk) {
    return <LoadingSpinner label="Loading Dashboard" />;
  }

  if (!clerk) return null;

  return (
    <div className="max-w-7xl mx-auto space-y-12 pb-20 px-4 animate-fadeIn font-sans antialiased text-slate-600">
      <header id="scholarship-dashboard-top" className="flex flex-col md:flex-row md:items-end justify-between border-b border-slate-100 gap-5">
        <div className="space-y-1">
          <p className="text-[#0b3578] text-[10px] font-bold uppercase tracking-[0.22em] opacity-90">Scholarship Operations</p>
          <h1 className="text-3xl font-bold tracking-tight text-slate-800">Welcome, {firstName}</h1>
          <div className="flex items-center gap-3 mt-2 text-slate-600">
            <span className="text-[12px] font-semibold bg-slate-50 border border-slate-100 px-2 py-0.5 rounded uppercase tracking-wider">{employeeId}</span>
            <span className="text-slate-200">|</span>
            <span className="text-xs font-medium uppercase tracking-tight">{roleLabel}</span>
          </div>
        </div>

        {view === 'certificates' ? (
          <button
            type="button"
            onClick={backToDashboard}
            className="px-6 py-2.5 bg-white text-slate-700 text-[12px] font-black uppercase tracking-widest rounded-md border border-slate-200 shadow-sm hover:shadow-md hover:-translate-y-0.5 transition-all"
          >
            Back to Dashboard
          </button>
        ) : (
          <button
            type="button"
            onClick={openProfile}
            className="px-6 py-2.5 bg-[#0b3578] text-white text-[12px] font-black uppercase tracking-widest rounded-md shadow-lg shadow-[#0b3578]/20 hover:shadow-xl hover:-translate-y-0.5 transition-all"
          >
            Open Profile
          </button>
        )}
      </header>

      {view === 'certificates' ? (
        <section id="certificate-section" className="space-y-6">
          <div className="flex items-center justify-between px-1">
            <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em]">Certificate Queue</h2>
            <span className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider">Operational module</span>
          </div>
          <div className="bg-white rounded-2xl border border-slate-200 shadow-[0_2px_10px_rgba(0,0,0,0.02)] p-3 sm:p-6">
            <CertificateDashboard clerkType="scholarship" />
          </div>
        </section>
      ) : (
        <>
          <section className="space-y-6">
            <div className="flex items-center justify-between px-1">
              <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em]">Queue Pulse</h2>
              <span className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider">Live status</span>
            </div>
            <ScholarshipMetricsCards refreshToken={metricsRefreshToken} />
          </section>

          <section className="space-y-6">
            <div className="flex items-center justify-between px-1">
              <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em]">Primary Operations</h2>
              <span className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider">Search • window • queue</span>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
              <div className="lg:col-span-7">
                <ScholarshipSearchCard
                  searchMode={searchMode}
                  setSearchMode={setSearchMode}
                  roll={roll}
                  setRoll={setRoll}
                  applicationNoInput={applicationNoInput}
                  setApplicationNoInput={setApplicationNoInput}
                  nameInput={nameInput}
                  setNameInput={setNameInput}
                  rollError={rollError}
                  setRollError={setRollError}
                  MAX_ROLL={MAX_ROLL}
                  loading={loading}
                  onSubmit={fetchStudent}
                  nameResults={nameResults}
                  onSelectStudentFromName={handleSelectStudentFromName}
                />
              </div>

              <div className="lg:col-span-5 space-y-6">
                <ScholarshipWindowCard
                  onWindowUpdated={() => {
                    setMetricsRefreshToken((t) => t + 1);
                    smoothScrollToId('scholarship-dashboard-top', { behavior: 'smooth', block: 'start' });
                  }}
                />
              </div>
            </div>
          </section>

          {student && (
            <section className="space-y-6">
              <div className="flex flex-col sm:flex-row sm:items-end sm:justify-between gap-4 px-1">
                <div className="space-y-1">
                  <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em]">Student Workspace</h2>
                  <p className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider">Active student loaded • {student.roll_no}</p>
                </div>
                <button
                  type="button"
                  onClick={handleClearDashboard}
                  className="px-4 py-2 bg-white text-slate-700 text-[11px] font-bold uppercase tracking-widest rounded-md border border-slate-200 shadow-sm hover:shadow-md hover:-translate-y-0.5 transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#0b3578]"
                >
                  Clear Workspace
                </button>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                <div className="lg:col-span-5 space-y-6">
                  <StudentInfoCard
                    student={student}
                    onImageClick={(src) => {
                      setImagePreviewSrc(src);
                      setImagePreviewOpen(true);
                    }}
                  />
                  <StudentAcademicSummaryCard student={student} />
                </div>

                <div className="lg:col-span-7 space-y-4">
                  <div className="flex items-center justify-between px-1">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em]">Year Timeline Records</h3>
                    <span className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider">Expand for fee & proceedings</span>
                  </div>
                  <YearRecordsList
                    yearList={yearList}
                    summariesByYear={summariesByYear}
                    expandedByYear={expandedByYear}
                    onToggleExpand={(yy) =>
                      setExpandedByYear((prev) => ({ ...prev, [yy]: !prev[yy] }))
                    }
                    onOpenModal={(yy) => openAddModal(yy)}
                    computeRecordState={computeRecordState}
                    feeSummary={feeSummary}
                    student={student}
                    toDmy={toDmy}
                  />
                </div>
              </div>

              <AddEditRecordInstitutionalModal
                open={modalOpen}
                year={modalYear}
                student={student}
                summary={summariesByYear[modalYear] || null}
                formState={{
                  schAppNo,
                  schProceedingNo,
                  schAmount,
                  schSanctionDate,
                  releasedAmount,
                  releasedDate,
                  payAmount,
                  payRef,
                  payDate,
                  payMode,
                  bankName,
                  appEditing,
                  thumbUpdateAvailable,
                  thumbStatus,
                  hardcopySubmitted,
                  selectedProceeding,
                }}
                setFormState={(k, v) => {
                  const setters = {
                    schAppNo: setSchAppNo,
                    schProceedingNo: setSchProceedingNo,
                    schAmount: setSchAmount,
                    schSanctionDate: setSchSanctionDate,
                    releasedAmount: setReleasedAmount,
                    releasedDate: setReleasedDate,
                    payAmount: setPayAmount,
                    payRef: setPayRef,
                    payDate: setPayDate,
                    payMode: setPayMode,
                    bankName: setBankName,
                    appEditing: setAppEditing,
                    thumbUpdateAvailable: setThumbUpdateAvailable,
                    thumbStatus: setThumbStatus,
                    hardcopySubmitted: setHardcopySubmitted,
                  };
                  (setters[k] || (() => { /* empty */ }))(v);
                }}
                saving={saving}
                onProceedingSave={handleProceedingSave}
                onPaymentSave={handlePaymentSave}
                onFinalUpdate={handleFinalUpdate}
                onClose={() => setModalOpen(false)}
                onDeletePayment={deletePayment}
                onDeleteScholarship={deleteScholarship}
                onSelectProceeding={(p) => {
                   setSelectedProceeding(p);
                   setSchProceedingNo(p.proceeding_no || '');
                   setSchAmount(p.amount || '');
                   setSchSanctionDate(toMySQLDate(p.date) || '');
                   setReleasedAmount(p.released_amount || '');
                   setReleasedDate(toMySQLDate(p.released_date) || '');
                   setSchStatus(p.status || 'SANCTIONED');
                }}
                onCancelEdit={() => {
                   setSelectedProceeding(null);
                   setSchProceedingNo('');
                   setSchAmount('');
                   setSchSanctionDate('');
                   setReleasedAmount('');
                   setReleasedDate('');
                   setSchStatus('SANCTIONED');
                }}
                toDmy={toDmy}
              />
            </section>
          )}
        </>
      )}
      <ImagePreviewModal src={imagePreviewSrc} alt="Profile preview" open={imagePreviewOpen} onClose={() => setImagePreviewOpen(false)} />
    </div>
  );
}

export default function ScholarshipDashboard() {
  return (
    <Suspense fallback={<LoadingSpinner label="Loading Scholarship Dashboard..." />}>
      <ScholarshipDashboardContent />
    </Suspense>
  );
}

'use client';

import { useEffect, useState, useRef } from 'react';
import { useClerk } from '@/context/ClerkContext';
import { useRouter } from 'next/navigation';
import Image from 'next/image';
import toast from 'react-hot-toast';
import LoadingSpinner from '@/components/ui/LoadingSpinner';
import { getAssetUrl } from '@/lib/assets';

export default function ClerkEditProfilePage() {
  const router = useRouter();
  const { clerkData: clerk, refreshClerkData } = useClerk();
  
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    mobile: '',
    employee_id: '',
    role: '',
    branch: '',
    address: ''
  });
  
  const [originalData, setOriginalData] = useState(null);
  const [saving, setSaving] = useState(false);
  const [pfpDataUrl, setPfpDataUrl] = useState(null);
  const [signatureDataUrl, setSignatureDataUrl] = useState(null);
  const [loading, setLoading] = useState(true);

  // Email Verification Workflow States
  const [isEditingEmail, setIsEditingEmail] = useState(false);
  const [emailVerified, setEmailVerified] = useState(false);
  const [showOtpInput, setShowOtpInput] = useState(false);
  const [otpCode, setOtpCode] = useState('');
  const [sendingOtp, setSendingOtp] = useState(false);
  const [verifyingOtp, setVerifyingOtp] = useState(false);

  const fileInputRef = useRef(null);
  const signatureInputRef = useRef(null);

  useEffect(() => {
    if (clerk) {
      const data = {
        name: clerk.name || '',
        email: clerk.email || '',
        mobile: clerk.mobile || '',
        employee_id: clerk.employee_id || '',
        role: clerk.role || '',
        branch: clerk.branch || '',
        address: clerk.address || ''
      };
      const id = setTimeout(() => {
        setFormData(data);
        setOriginalData(JSON.parse(JSON.stringify(data)));
        setLoading(false);
      }, 0);
      return () => clearTimeout(id);
    }
    return undefined;
  }, [clerk]);

  const onFileSelect = async (file, type) => {
    if (file) {
      if (!['image/jpeg', 'image/png', 'image/jpg', 'image/webp'].includes(file.type)) {
        toast.error('File format rejected. Use JPG/PNG/WEBP.');
        return;
      }

      let processedFile = file;
      try {
        const { compressImage } = await import('@/lib/image-compressor');
        processedFile = await compressImage(file, 1200, 1200, 0.6);
      } catch (err) {
        console.error('Image compression failed:', err);
      }

      if (processedFile.size >= 1 * 1024 * 1024) {
        toast.error('File exceeds 1MB limit.');
        return;
      }
      const reader = new FileReader();
      reader.onload = () => {
        if (type === 'pfp') setPfpDataUrl(reader.result);
        else if (type === 'sig') setSignatureDataUrl(reader.result);
      };
      reader.readAsDataURL(processedFile);
    }
  };

  const handleRequestEmailChange = async () => {
    if (!formData.email || !formData.email.includes('@')) {
      toast.error('Please enter a valid institutional email.');
      return;
    }
    if (formData.email === originalData.email) {
      toast.error('This is already your registered email.');
      return;
    }

    setSendingOtp(true);
    try {
      const res = await fetch('/api/auth/send-otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          email: formData.email,
          purpose: 'Verification for New Email'
        })
      });
      const data = await res.json();
      if (res.ok) {
        toast.success(`OTP sent to ${formData.email}`);
        setShowOtpInput(true);
      } else {
        toast.error(data.error || 'Failed to send OTP');
      }
    } catch (e) {
      toast.error('Network error occurred.');
    } finally {
      setSendingOtp(false);
    }
  };

  const handleVerifyOtp = async () => {
    if (otpCode.length !== 6) {
      toast.error('Enter a valid 6-digit OTP');
      return;
    }
    setVerifyingOtp(true);
    try {
      const res = await fetch('/api/auth/verify-otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          email: formData.email,
          submittedOtp: otpCode
        })
      });
      const data = await res.json();
      if (res.ok) {
        toast.success('New email verified successfully.');
        setEmailVerified(true);
        setShowOtpInput(false);
        setIsEditingEmail(false);
      } else {
        toast.error(data.error || 'Invalid OTP');
      }
    } catch (e) {
      toast.error('Verification failed.');
    } finally {
      setVerifyingOtp(false);
    }
  };

  const hasChanges = () => {
    if (!originalData) return false;
    if (pfpDataUrl || signatureDataUrl) return true;
    
    const emailChanged = formData.email !== originalData.email;
    
    return (
      formData.name !== originalData.name ||
      (emailVerified && emailChanged) ||
      formData.mobile !== originalData.mobile ||
      formData.address !== originalData.address
    );
  };

  const onSave = async () => {
    if (!hasChanges()) {
      // If email is changed but not verified, show a specific error
      if (formData.email !== originalData.email && !emailVerified) {
        toast.error('Please verify your new email address before saving.');
        return;
      }
      toast.error('No modifications detected.');
      return;
    }

    // Additional check for unverified email change if other changes exist
    if (formData.email !== originalData.email && !emailVerified) {
      toast.error('Please verify your new email address or revert it.');
      return;
    }

    // Input Validations
    if (formData.name.trim().length < 3) {
      toast.error('Name must be at least 3 characters long.');
      return;
    }
    if (formData.name.length > 50) {
      toast.error('Name cannot exceed 50 characters.');
      return;
    }
    if (!/^[a-zA-Z\s]*$/.test(formData.name)) {
      toast.error('Name can only contain letters and spaces.');
      return;
    }

    if (formData.mobile.length !== 10) {
      toast.error('Mobile number must be exactly 10 digits.');
      return;
    }

    if (formData.address.length > 255) {
      toast.error('Address cannot exceed 255 characters.');
      return;
    }

    setSaving(true);
    const toastId = toast.loading('Updating institutional records...');

    try {
      const payload = { /* empty */ };
      if (formData.name !== originalData.name) payload.name = formData.name;
      if (emailVerified && formData.email !== originalData.email) payload.email = formData.email;
      if (formData.mobile !== originalData.mobile) payload.mobile = formData.mobile;
      if (formData.address !== originalData.address) payload.address = formData.address;
      if (pfpDataUrl) payload.pfp = pfpDataUrl;
      if (signatureDataUrl) payload.signature = signatureDataUrl;

      const res = await fetch('/api/clerk/update-profile', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      
      const resData = await res.json();
      if (!res.ok) throw new Error(resData.error || 'Update failed');
      
      toast.success('Profile updated successfully.', { id: toastId });
      setPfpDataUrl(null);
      setSignatureDataUrl(null);
      setEmailVerified(false); // Reset after save
      setIsEditingEmail(false);
      await refreshClerkData();
    } catch (e) {
      toast.error(e.message || 'System error occurred.', { id: toastId });
    } finally {
      setSaving(false);
    }
  };

  if (loading && !clerk) {
    return <LoadingSpinner label="Loading Records" />;
  }

  return (
    <div className="w-full max-w-5xl mx-auto space-y-6">
      <div className="bg-white border border-slate-200 shadow-sm rounded-sm overflow-hidden">
        
        {/* Header */}
        <div className="bg-[#0b3578] px-6 py-5 border-b border-blue-900 flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-white uppercase tracking-tight">Staff Profile Settings</h1>
            <p className="text-blue-100 text-xs mt-1">Institutional Employee Information Management</p>
          </div>
          <div className="px-3 py-1 bg-blue-900/50 border border-blue-400 text-[10px] font-black text-white uppercase tracking-widest">
            {String(clerk?.role || 'Staff').toUpperCase()} Portal
          </div>
        </div>

        <div className="p-6 md:p-10">
          <div className="grid grid-cols-1 lg:grid-cols-[240px_1fr] gap-12">
            
            {/* Left: Avatar & Signature */}
            <aside className="space-y-10">
              <div className="text-center">
                <span className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Official Portrait</span>
                <div className="relative inline-block group">
                  <div className={`w-44 h-44 rounded-full border-4 ${pfpDataUrl ? 'border-[#0b3578]' : 'border-slate-100'} bg-slate-50 overflow-hidden flex items-center justify-center shadow-inner`}>
                    {(pfpDataUrl || clerk?.pfp) ? (
                      <Image 
                        src={pfpDataUrl || getAssetUrl(clerk?.pfp)} 
                        alt="Profile" 
                        width={176} 
                        height={176} 
                        unoptimized 
                        className="object-cover w-full h-full" 
                      />
                    ) : (
                      <div className="text-slate-300 flex flex-col items-center">
                        <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                        </svg>
                        <span className="text-[9px] font-bold uppercase mt-2">No Image</span>
                      </div>
                    )}
                  </div>
                  <button 
                    onClick={() => fileInputRef.current.click()}
                    className="absolute bottom-1 right-1 w-10 h-10 bg-[#0b3578] text-white rounded-full shadow-lg flex items-center justify-center hover:bg-blue-900 transition-all border-2 border-white"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  </button>
                  <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={(e) => onFileSelect(e.target.files[0], 'pfp')} />
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Verification Signature</label>
                <div className={`w-full h-24 border-2 ${signatureDataUrl ? 'border-[#0b3578] bg-blue-50/20' : 'border-dashed border-slate-200 bg-slate-50'} flex items-center justify-center relative group overflow-hidden rounded-sm`}>
                  {(signatureDataUrl || clerk?.signature) ? (
                    <Image 
                      src={signatureDataUrl || getAssetUrl(clerk?.signature)} 
                      alt="Signature" 
                      width={200} 
                      height={96} 
                      unoptimized 
                      className="object-contain w-full h-full p-3" 
                    />
                  ) : (
                    <span className="text-[9px] font-bold text-slate-300 uppercase tracking-widest">Unrecorded</span>
                  )}
                  <button 
                    onClick={() => signatureInputRef.current.click()} 
                    className="absolute inset-0 bg-[#0b3578]/90 text-white opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-[10px] font-black uppercase tracking-widest"
                  >
                    Upload Signature
                  </button>
                </div>
                <input ref={signatureInputRef} type="file" accept="image/*" className="hidden" onChange={(e) => onFileSelect(e.target.files[0], 'sig')} />
              </div>
            </aside>

            {/* Right: Form */}
            <div className="space-y-10">
              
              <section>
                <h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest border-b border-slate-100 pb-2 mb-6 flex items-center gap-2">
                  <span className="w-1.5 h-4 bg-[#0b3578] block"></span>
                  Personal Particulars
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Full Name</label>
                    <input 
                      value={formData.name} 
                      onChange={(e) => setFormData({...formData, name: e.target.value})}
                      maxLength={50}
                      className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.name !== originalData?.name ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200 hover:border-slate-300'}`}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Employee Contact Number</label>
                    <input 
                      value={formData.mobile} 
                      onChange={(e) => {
                        const val = e.target.value.replace(/\D/g, '').slice(0, 10);
                        setFormData({...formData, mobile: val});
                      }}
                      maxLength={10}
                      className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.mobile !== originalData?.mobile ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200 hover:border-slate-300'}`}
                      placeholder="10-digit mobile number"
                    />
                  </div>
                  <div className="space-y-1.5 md:col-span-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Institutional Email</label>
                    <div className="flex flex-col md:flex-row gap-3">
                      <div className="flex-1 relative">
                        <input 
                          value={formData.email} 
                          disabled={!isEditingEmail && !emailVerified}
                          onChange={(e) => {
                            setFormData({...formData, email: e.target.value});
                            if (emailVerified) setEmailVerified(false);
                          }}
                          className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${
                            emailVerified 
                              ? 'border-green-400 bg-green-50/10' 
                              : (isEditingEmail ? 'border-amber-400 bg-amber-50/30' : 'bg-slate-50 border-slate-200 text-slate-500 cursor-not-allowed')
                          }`}
                        />
                        {emailVerified && (
                          <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1.5">
                            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                            <span className="text-[8px] font-black text-green-600 uppercase tracking-tighter">Verified</span>
                          </div>
                        )}
                      </div>

                      {!isEditingEmail && !emailVerified && (
                        <button 
                          onClick={() => setIsEditingEmail(true)}
                          className="px-6 py-3 bg-slate-800 text-white text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all"
                        >
                          Change Email
                        </button>
                      )}

                      {isEditingEmail && !showOtpInput && (
                        <div className="flex gap-2">
                          <button 
                            onClick={handleRequestEmailChange}
                            disabled={sendingOtp || formData.email === originalData?.email}
                            className="px-6 py-3 bg-[#0b3578] text-white text-[10px] font-black uppercase tracking-widest hover:bg-blue-900 transition-all disabled:opacity-50"
                          >
                            {sendingOtp ? 'Sending...' : 'Verify New Email'}
                          </button>
                          <button 
                            onClick={() => {
                              setIsEditingEmail(false);
                              setFormData({...formData, email: originalData.email});
                            }}
                            className="px-4 py-3 bg-slate-100 text-slate-500 text-[10px] font-black uppercase tracking-widest hover:bg-slate-200 transition-all"
                          >
                            Cancel
                          </button>
                        </div>
                      )}

                      {showOtpInput && (
                        <div className="flex gap-2">
                          <input 
                            value={otpCode}
                            onChange={(e) => setOtpCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                            placeholder="6-DIGIT OTP"
                            className="w-32 border-2 border-[#0b3578] px-4 py-2 text-center text-sm font-black tracking-[0.2em] outline-none"
                          />
                          <button 
                            onClick={handleVerifyOtp}
                            disabled={verifyingOtp}
                            className="px-6 py-3 bg-[#0b3578] text-white text-[10px] font-black uppercase tracking-widest hover:bg-blue-900 transition-all"
                          >
                            {verifyingOtp ? '...' : 'Verify'}
                          </button>
                          <button 
                            onClick={() => { setShowOtpInput(false); setOtpCode(''); }}
                            className="px-4 py-3 text-slate-400 hover:text-rose-600 transition-all"
                          >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                          </button>
                        </div>
                      )}
                    </div>
                    <p className="mt-2 text-[9px] text-slate-400 font-medium italic">
                      {emailVerified 
                        ? "* New email address has been verified and is ready to be recorded."
                        : (isEditingEmail 
                            ? "* Please enter your new institutional email and verify it via OTP."
                            : "* Changing your institutional email requires verification of the new address.")}
                    </p>
                  </div>
                  <div className="space-y-1.5 md:col-span-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Permanent Address</label>
                    <textarea 
                      value={formData.address} 
                      onChange={(e) => setFormData({...formData, address: e.target.value})}
                      rows={3}
                      maxLength={255}
                      className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.address !== originalData?.address ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200 hover:border-slate-300'}`}
                      placeholder="Enter permanent residential address"
                    />
                  </div>
                </div>
              </section>

              <section>
                <h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest border-b border-slate-100 pb-2 mb-6 flex items-center gap-2">
                  <span className="w-1.5 h-4 bg-[#0b3578] block"></span>
                  Institutional Appointment
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Employee ID</label>
                    <input value={formData.employee_id} disabled className="w-full bg-slate-50 border border-slate-200 px-4 py-3 text-sm font-bold text-slate-400 cursor-not-allowed uppercase" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Designated Role</label>
                    <input value={formData.role.toUpperCase()} disabled className="w-full bg-slate-50 border border-slate-200 px-4 py-3 text-sm font-bold text-slate-400 cursor-not-allowed uppercase" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Department/Branch</label>
                    <input value={formData.branch || 'INSTITUTIONAL'} disabled className="w-full bg-slate-50 border border-slate-200 px-4 py-3 text-sm font-bold text-slate-400 cursor-not-allowed uppercase" />
                  </div>
                </div>
                <p className="mt-4 text-[10px] text-slate-400 font-medium italic">
                  * Appointment details are fixed by the administrative office. Contact Super Admin for role modifications.
                </p>
              </section>

              {/* Actions */}
              <div className="pt-8 flex items-center justify-end gap-4 border-t border-slate-100">
                <button 
                  type="button"
                  onClick={() => router.back()} 
                  className="px-8 py-3 bg-slate-50 text-slate-500 font-bold uppercase tracking-widest hover:bg-slate-100 transition-all text-[10px]"
                >
                  Cancel
                </button>
                <button 
                  disabled={saving || !hasChanges()} 
                  onClick={onSave}
                  className="px-10 py-3 bg-[#0b3578] text-white font-bold uppercase tracking-widest hover:bg-blue-900 disabled:opacity-30 disabled:grayscale transition-all text-[10px] shadow-sm"
                >
                  {saving ? 'Processing...' : 'Apply Modifications'}
                </button>
              </div>

            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import Footer from '@/components/Footer';
import Image from 'next/image';
import { useAssets } from '@/context/AssetContext';
import { useRef, useEffect, useMemo, useState, useCallback } from 'react';
import Header from '@/components/Header';
import HeaderMobileView from '@/components/Header-MobileView';
import Link from 'next/link';
import toast from 'react-hot-toast';

export default function DevelopersPage() {
  const { getAsset } = useAssets();
  const audiosRef = useRef({ /* empty */ });
  const [bugDescription, setBugDescription] = useState('');
  const [bugSeverity, setBugSeverity] = useState('MEDIUM');
  const [affectedPage, setAffectedPage] = useState('');
  const [screenshot, setScreenshot] = useState(null);
  const [screenshotPreview, setScreenshotPreview] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [bugReports, setBugReports] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [reportType, setReportType] = useState('BUG');
  const [isDeveloper, setIsDeveloper] = useState(false);
  const [activeTab, setActiveTab] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isLoginPromptOpen, setIsLoginPromptOpen] = useState(false);
  const fetchRef = useRef();

  // On mount, check for pending submission from before login
  useEffect(() => {
    try {
      const pending = sessionStorage.getItem('pendingBugReport');
      if (pending) {
        sessionStorage.removeItem('pendingBugReport');
        const data = JSON.parse(pending);
        if (data.description) {
          const doSubmit = async () => {
            const toastId = toast.loading('Completing your submission...');
            try {
              let screenshotPayload = null;
              if (data.screenshotPreview) {
                screenshotPayload = data.screenshotPreview;
              }
              const res = await fetch('/api/bugs', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                  description: data.description,
                  screenshot: screenshotPayload,
                  severity: data.severity,
                  type: data.type,
                  affected_page: data.affected_page || null,
                }),
              });
              if (res.ok) {
                toast.success(`${data.type === 'FEATURE_REQUEST' ? 'Suggestion' : 'Bug report'} submitted successfully!`, { id: toastId });
                if (fetchRef.current) fetchRef.current();
              } else if (res.status === 401) {
                toast.error('Please log in to submit', { id: toastId });
                sessionStorage.setItem('pendingBugReport', pending);
              } else {
                const err = await res.json();
                toast.error(err.message || 'Submission failed', { id: toastId });
              }
            } catch {
              toast.error('Submission failed. Please try again.', { id: toastId });
            }
          };
          doSubmit();
        }
      }
    } catch {
      // sessionStorage might not be available
    }
  }, []);

  const fetchBugReports = useCallback(async () => {
    try {
      const params = new URLSearchParams();
      if (activeTab === 'bugs') params.append('type', 'BUG');
      else if (activeTab === 'features') params.append('type', 'FEATURE_REQUEST');
      else if (activeTab === 'fixed') params.append('status', 'RESOLVED');
      if (searchQuery.trim()) params.append('q', searchQuery.trim());

      const res = await fetch(`/api/bugs?${params.toString()}`);
      if (res.ok) {
        const data = await res.json();
        setBugReports(data);
      }
    } catch (error) {
      console.error('Failed to fetch reports:', error);
    }
  }, [activeTab, searchQuery]);

  useEffect(() => {
    fetchRef.current = fetchBugReports;
    // Inline fetch to avoid set-state-in-effect lint
    const params = new URLSearchParams();
    if (activeTab === 'bugs') params.append('type', 'BUG');
    else if (activeTab === 'features') params.append('type', 'FEATURE_REQUEST');
    else if (activeTab === 'fixed') params.append('status', 'RESOLVED');
    if (searchQuery.trim()) params.append('q', searchQuery.trim());
    fetch(`/api/bugs?${params.toString()}`)
      .then(r => r.json())
      .then(data => setBugReports(data))
      .catch(() => { /* empty */ });
    fetch('/api/bugs/developer-check')
      .then(r => r.json())
      .then(data => setIsDeveloper(data.isDeveloper))
      .catch(() => { /* empty */ });
  }, [fetchBugReports, activeTab, searchQuery]);

  const handleFileChange = async (e) => {
    const file = e.target.files[0];
    if (file) {
      if (!['image/jpeg', 'image/png', 'image/jpg', 'image/webp'].includes(file.type)) {
        toast.error('File format rejected. Use JPG/PNG/WEBP.');
        return;
      }
      let processedFile = file;
      try {
        const { compressImage } = await import('@/lib/image-compressor');
        processedFile = await compressImage(file, 1200, 1200, 0.6);
      } catch (err) {
        console.error('Image compression failed:', err);
      }

      if (processedFile.size >= 1 * 1024 * 1024) {
        toast.error('File size should be less than 1MB');
        return;
      }
      setScreenshot(processedFile);
      const reader = new FileReader();
      reader.onloadend = () => {
        setScreenshotPreview(reader.result);
      };
      reader.readAsDataURL(processedFile);
    }
  };

  const handleSubmitReport = async (e) => {
    e.preventDefault();
    if (!bugDescription.trim()) {
      toast.error('Please provide a description');
      return;
    }

    setIsSubmitting(true);
    const loadingToast = toast.loading('Submitting...');

    try {
      let base64Screenshot = null;
      if (screenshotPreview) {
        base64Screenshot = screenshotPreview;
      }

      const label = reportType === 'BUG' ? 'bug report' : 'feature suggestion';

      const res = await fetch('/api/bugs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          description: bugDescription,
          screenshot: base64Screenshot,
          severity: bugSeverity,
          type: reportType,
          affected_page: affectedPage || null,
        }),
      });

      if (res.ok) {
        toast.success(`${label} submitted successfully!`, { id: loadingToast });
        setBugDescription('');
        setBugSeverity('MEDIUM');
        setAffectedPage('');
        setScreenshot(null);
        setScreenshotPreview(null);
        setIsModalOpen(false);
        fetchBugReports();
      } else if (res.status === 401) {
        toast.error('Please log in to submit', { id: loadingToast });
        sessionStorage.setItem('pendingBugReport', JSON.stringify({
          description: bugDescription,
          type: reportType,
          severity: bugSeverity,
          affected_page: affectedPage,
          screenshotPreview: base64Screenshot,
        }));
        setIsModalOpen(false);
        setIsLoginPromptOpen(true);
      } else {
        const errorData = await res.json();
        toast.error(errorData.message || `Failed to submit ${label}`, { id: loadingToast });
      }
    } catch (error) {
      console.error('Submit error:', error);
      toast.error('An error occurred. Please try again.', { id: loadingToast });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleMarkFixed = async (id) => {
    const loadingToast = toast.loading('Marking as fixed...');
    try {
      const res = await fetch(`/api/bugs/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'resolve' }),
      });
      if (res.ok) {
        toast.success('Marked as fixed!', { id: loadingToast });
        fetchBugReports();
      } else {
        const err = await res.json();
        toast.error(err.message || 'Failed to mark as fixed', { id: loadingToast });
      }
    } catch {
      toast.error('An error occurred', { id: loadingToast });
    }
  };

  const handleReopen = async (id) => {
    const loadingToast = toast.loading('Reopening...');
    try {
      const res = await fetch(`/api/bugs/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'reopen' }),
      });
      if (res.ok) {
        toast.success('Reopened!', { id: loadingToast });
        fetchBugReports();
      } else {
        const err = await res.json();
        toast.error(err.message || 'Failed to reopen', { id: loadingToast });
      }
    } catch {
      toast.error('An error occurred', { id: loadingToast });
    }
  };

  const developers = useMemo(() => [
    {
      name: 'Masna Goutham',
      role: 'Frontend & UI/UX Developer',
      image: getAsset('/assets/DevPics/Dev1.png'),
      delay: '0s',
      audio: getAsset('/assets/DevPics/Dev1.mp4'),
      portfolio: ''
    },
    {
      name: 'P.Sannith',
      role: 'Backend & Database Administrator',
      image: getAsset('/assets/DevPics/Dev2.jpg'),
      delay: '0.2s',
      audio: getAsset('/assets/DevPics/Dev2.mp3'),
      portfolio: 'https://sannith-hack.github.io/Portfolio/'
    },
    {
      name: 'Uzair',
      role: 'System Interface and API designer',
      image: getAsset('/assets/DevPics/Dev3.jpeg'),
      audio: getAsset('/assets/DevPics/Dev3.mp3'),
      delay: '0.4s',
    },
  ], [getAsset]);

  useEffect(() => {
    developers.forEach(dev => {
      if (dev.audio && !audiosRef.current[dev.audio]) {
        const audio = new Audio(dev.audio);
        audio.volume = 0.5;
        audio.preload = 'auto';
        audiosRef.current[dev.audio] = audio;
      }
    });

    const audios = audiosRef.current;
    return () => {
      Object.values(audios).forEach(audio => {
        audio.pause();
        audio.src = '';
      });
    };
  }, [developers]);

  const handleMouseEnter = (dev) => {
    if (dev.audio && audiosRef.current[dev.audio]) {
      const audio = audiosRef.current[dev.audio];
      Object.values(audiosRef.current).forEach(a => {
        if (a !== audio) { a.pause(); a.currentTime = 0; }
      });
      audio.currentTime = 0;
      const playPromise = audio.play();
      if (playPromise !== undefined) {
        playPromise.catch(() => { /* empty */ });
      }
    }
  };

  const handleMouseLeave = (dev) => {
    if (dev.audio && audiosRef.current[dev.audio]) {
      const audio = audiosRef.current[dev.audio];
      audio.pause();
      audio.currentTime = 0;
    }
  };

  const tabs = [
    { key: 'all', label: 'All', icon: '📋' },
    { key: 'bugs', label: 'Bugs', icon: '🐛' },
    { key: 'features', label: 'Feature Requests', icon: '💡' },
    { key: 'fixed', label: 'Fixed \u2705', icon: '' },
  ];

  return (
    <div className="min-h-screen bg-gray-50 font-sans relative">
      <HeaderMobileView />
      <Header />

      <div id="main-content" className="flex flex-col min-h-screen relative overflow-x-hidden transition-all duration-300">
        <main className="flex-grow container mx-auto px-4 py-12">
          <div className="text-center mb-16">
            <h1 className="text-4xl font-extrabold text-[#0b3578] mb-4 animate-fade-in-down">
              Meet Team &quot;Homeless Soon&quot;
            </h1>
            <p className="text-lg text-gray-600 max-w-2xl mx-auto animate-fade-in-up">
              The talented individuals behind the KUCET College Management System, dedicated to building a robust and user-friendly platform.
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 max-w-6xl mx-auto mb-20">
            {developers.map((dev, index) => (
              <div
                key={index}
                className="group bg-white rounded-2xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 overflow-hidden border border-gray-100 flex flex-col items-center p-8 text-center animate-fade-in-up"
                style={{ animationDelay: dev.delay, animationFillMode: 'both' }}
                onMouseEnter={() => handleMouseEnter(dev)}
                onMouseLeave={() => handleMouseLeave(dev)}
              >
                <div className="relative w-40 h-40 mb-6">
                  <div className="absolute inset-0 bg-blue-100 rounded-full scale-0 group-hover:scale-110 transition-transform duration-500 ease-out"></div>
                  <div className="relative w-full h-full rounded-full overflow-hidden border-4 border-white shadow-md group-hover:border-blue-50 transition-colors duration-300">
                    <Image src={dev.image} alt={dev.name} fill className="object-cover" />
                  </div>
                </div>
                <h3 className="text-2xl font-bold text-gray-800 mb-2 group-hover:text-[#0b3578] transition-colors duration-300">
                  {dev.name}
                </h3>
                <div className="h-1 w-12 bg-blue-500 rounded-full mb-4 group-hover:w-24 transition-all duration-300"></div>
                <p className="text-gray-600 font-medium bg-blue-50 px-4 py-1.5 rounded-full text-sm">
                  {dev.role}
                </p>
                {dev.portfolio && (
                  <a
                    href={dev.portfolio}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="mt-4 text-blue-600 hover:text-blue-700 text-sm font-semibold flex items-center gap-1 hover:underline decoration-2 underline-offset-4"
                  >
                    View more details
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M10.293 3.293a1 1 0 011.414 0l6 6a1 1 0 010 1.414l-6 6a1 1 0 01-1.414-1.414L14.586 11H3a1 1 0 110-2h11.586l-4.293-4.293a1 1 0 010-1.414z" clipRule="evenodd" />
                    </svg>
                  </a>
                )}
              </div>
            ))}
          </div>

          <div className="max-w-5xl mx-auto text-center animate-fade-in-up" style={{ animationDelay: '0.6s', animationFillMode: 'both' }}>
            <h2 className="text-3xl font-bold text-[#0b3578] mb-8">Team &quot;Homeless Soon&quot;</h2>
            <div className="relative w-full rounded-2xl overflow-hidden shadow-xl border-4 border-white group">
               <Image
                  src={getAsset('/assets/DevPics/Group.jpg')}
                  alt="Team Group Photo"
                  width={3096}
                  height={2477}
                  className="w-full h-auto object-contain transition-transform duration-500 group-hover:scale-105"
               />
            </div>
            <p className="mt-6 text-gray-600 italic">
              &quot;Coming together is a beginning, keeping together is progress, working together is success.&quot;
            </p>
          </div>

          <div className="max-w-5xl mx-auto mt-24 mb-16 animate-fade-in-up" style={{ animationDelay: '0.8s', animationFillMode: 'both' }}>
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-6">
              <div>
                <h2 className="text-3xl font-bold text-[#0b3578]">Community Board</h2>
                <p className="text-gray-600 mt-2">Report bugs, suggest features, and track progress — all in the open.</p>
              </div>
              <div className="flex gap-3">
                <button
                  onClick={() => { setReportType('BUG'); setIsModalOpen(true); }}
                  className="bg-red-600 hover:bg-red-700 text-white font-bold py-3 px-6 rounded-xl shadow-lg hover:shadow-xl transition-all flex items-center gap-2 transform hover:scale-105 active:scale-95"
                >
                  <span>🐛</span> Report Bug
                </button>
                <button
                  onClick={() => { setReportType('FEATURE_REQUEST'); setIsModalOpen(true); }}
                  className="bg-purple-600 hover:bg-purple-700 text-white font-bold py-3 px-6 rounded-xl shadow-lg hover:shadow-xl transition-all flex items-center gap-2 transform hover:scale-105 active:scale-95"
                >
                  <span>💡</span> Suggest Feature
                </button>
              </div>
            </div>

            {/* Search */}
            <div className="mb-6">
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search reports, features, or reporters..."
                className="w-full px-5 py-3 rounded-xl border-2 border-gray-100 focus:border-[#0b3578] focus:outline-none transition-colors"
              />
            </div>

            {/* Tabs */}
            <div className="flex gap-2 mb-8 border-b border-gray-200 pb-2">
              {tabs.map((tab) => (
                <button
                  key={tab.key}
                  onClick={() => setActiveTab(tab.key)}
                  className={`px-5 py-2.5 rounded-lg font-semibold text-sm transition-all ${
                    activeTab === tab.key
                      ? 'bg-[#0b3578] text-white shadow-md'
                      : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                  }`}
                >
                  {tab.icon && <span className="mr-1.5">{tab.icon}</span>}
                  {tab.label}
                </button>
              ))}
            </div>

            {/* Reports Grid */}
            {bugReports.length === 0 ? (
              <div className="bg-white rounded-2xl p-12 text-center border-2 border-dashed border-gray-200">
                <div className="text-gray-400 mb-4 flex justify-center">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                </div>
                <h3 className="text-xl font-semibold text-gray-700">Nothing here yet!</h3>
                <p className="text-gray-500 mt-1">Be the first to report a bug or suggest a feature.</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {bugReports.map((report) => {
                  const isFeature = report.type === 'FEATURE_REQUEST';
                  return (
                    <div key={report.id} className={`bg-white rounded-2xl shadow-md border overflow-hidden hover:shadow-lg transition-shadow ${
                      report.status === 'RESOLVED' ? 'border-green-200' : isFeature ? 'border-purple-100' : 'border-gray-100'
                    }`}>
                      <div className="p-6">
                        <div className="flex justify-between items-start mb-4 gap-2">
                          <div className="flex gap-2 flex-wrap">
                            <span className={`px-3 py-1 rounded-full text-xs font-bold whitespace-nowrap ${
                              isFeature
                                ? 'bg-purple-100 text-purple-700'
                                : 'bg-red-100 text-red-600'
                            }`}>
                              {isFeature ? 'FEATURE' : 'BUG'}
                            </span>
                            <span className={`px-3 py-1 rounded-full text-xs font-bold whitespace-nowrap ${
                              report.status === 'OPEN' ? 'bg-yellow-100 text-yellow-700' :
                              report.status === 'RESOLVED' ? 'bg-green-100 text-green-700' :
                              'bg-gray-100 text-gray-600'
                            }`}>
                              {report.status === 'RESOLVED' ? 'FIXED' : report.status}
                            </span>
                            {!isFeature && (
                              <span className={`px-3 py-1 rounded-full text-xs font-bold whitespace-nowrap ${
                                report.severity === 'CRITICAL' ? 'bg-red-200 text-red-700' :
                                report.severity === 'HIGH' ? 'bg-orange-100 text-orange-600' :
                                report.severity === 'MEDIUM' ? 'bg-yellow-100 text-yellow-600' :
                                'bg-blue-100 text-blue-600'
                              }`}>
                                {report.severity}
                              </span>
                            )}
                          </div>
                          <span className="text-xs text-gray-400 whitespace-nowrap">
                            {new Date(report.created_at).toLocaleDateString()}
                          </span>
                        </div>

                        <div className="mb-3">
                          <p className="text-xs text-gray-500">
                            <strong>By:</strong> {report.submitted_by} ({report.user_type})
                          </p>
                          {report.affected_page && (
                            <p className="text-xs text-gray-500">
                              <strong>Page:</strong> {report.affected_page}
                            </p>
                          )}
                          {report.fixed_by && (
                            <p className="text-xs text-green-600 font-semibold">
                              <strong>Fixed by:</strong> {report.fixed_by}
                              {report.fixed_at && (
                                <span className="font-normal text-gray-500">
                                  {' '}on {new Date(report.fixed_at).toLocaleDateString()}
                                </span>
                              )}
                            </p>
                          )}
                        </div>

                        <p className={`text-gray-800 font-medium mb-4 ${report.status === 'RESOLVED' ? 'line-through opacity-60' : ''}`}>
                          {report.description}
                        </p>

                        {report.screenshot_url && (
                          <div className="relative h-40 w-full rounded-lg overflow-hidden bg-gray-100 cursor-pointer group mb-3" onClick={() => window.open(getAsset(report.screenshot_url), '_blank')}>
                            <Image src={getAsset(report.screenshot_url)} alt="Screenshot" fill className="object-cover group-hover:scale-110 transition-transform duration-500" />
                            <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                              <span className="text-white text-sm font-bold bg-black/40 px-3 py-1 rounded-lg">View Full Image</span>
                            </div>
                          </div>
                        )}

                        {report.browser_info && !report.fixed_by && (
                          <p className="text-xs text-gray-400 truncate">
                            <strong>Browser:</strong> {report.browser_info}
                          </p>
                        )}

                        {/* Admin Actions */}
                        {report.status === 'OPEN' && isDeveloper && (
                          <button
                            onClick={() => handleMarkFixed(report.id)}
                            className="mt-4 w-full bg-green-600 hover:bg-green-700 text-white font-bold py-2.5 px-4 rounded-xl transition-all flex items-center justify-center gap-2"
                          >
                            <span>✓</span> Mark as Fixed
                          </button>
                        )}
                        {report.status === 'RESOLVED' && isDeveloper && (
                          <button
                            onClick={() => handleReopen(report.id)}
                            className="mt-4 w-full bg-yellow-500 hover:bg-yellow-600 text-white font-bold py-2.5 px-4 rounded-xl transition-all flex items-center justify-center gap-2"
                          >
                            Reopen
                          </button>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </main>

        {/* Modal */}
        {isModalOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-white rounded-3xl w-full max-w-xl shadow-2xl overflow-hidden animate-scale-in">
              <div className={`p-6 text-white flex justify-between items-center ${reportType === 'FEATURE_REQUEST' ? 'bg-purple-700' : 'bg-[#0b3578]'}`}>
                <h2 className="text-xl font-bold flex items-center gap-2">
                  {reportType === 'FEATURE_REQUEST' ? (
                    <><span>💡</span> Suggest a Feature</>
                  ) : (
                    <><span>🐛</span> Report a Bug</>
                  )}
                </h2>
                <button
                  onClick={() => setIsModalOpen(false)}
                  className="p-1 hover:bg-white/10 rounded-full transition-colors"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>

              <div className="p-4 bg-gray-50 border-b border-gray-100 flex gap-2">
                <button
                  onClick={() => setReportType('BUG')}
                  className={`flex-1 py-2.5 rounded-lg font-bold text-sm transition-all ${reportType === 'BUG' ? 'bg-red-600 text-white shadow-md' : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'}`}
                >
                  🐛 Report Bug
                </button>
                <button
                  onClick={() => setReportType('FEATURE_REQUEST')}
                  className={`flex-1 py-2.5 rounded-lg font-bold text-sm transition-all ${reportType === 'FEATURE_REQUEST' ? 'bg-purple-600 text-white shadow-md' : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'}`}
                >
                  💡 Suggest Feature
                </button>
              </div>

              <form onSubmit={handleSubmitReport} className="p-8">
                <div className="mb-6">
                  <label className="block text-gray-700 font-bold mb-2">
                    {reportType === 'FEATURE_REQUEST' ? 'Feature Description' : 'Problem Description'}
                  </label>
                  <textarea
                    value={bugDescription}
                    onChange={(e) => setBugDescription(e.target.value)}
                    placeholder={reportType === 'FEATURE_REQUEST'
                      ? 'Describe the feature you\'d like to see. What problem would it solve?'
                      : 'Please describe the issue in detail. What were you doing? What went wrong?'}
                    className="w-full h-32 px-4 py-3 rounded-xl border-2 border-gray-100 focus:border-[#0b3578] focus:outline-none transition-colors resize-none"
                    required
                  />
                </div>

                <div className="grid grid-cols-2 gap-4 mb-6">
                  {reportType === 'BUG' && (
                    <div>
                      <label className="block text-gray-700 font-bold mb-2">Severity</label>
                      <select
                        value={bugSeverity}
                        onChange={(e) => setBugSeverity(e.target.value)}
                        className="w-full px-4 py-3 rounded-xl border-2 border-gray-100 focus:border-[#0b3578] focus:outline-none transition-colors"
                      >
                        <option value="LOW">Low</option>
                        <option value="MEDIUM">Medium</option>
                        <option value="HIGH">High</option>
                        <option value="CRITICAL">Critical</option>
                      </select>
                    </div>
                  )}
                  <div className={reportType === 'BUG' ? '' : 'col-span-2'}>
                    <label className="block text-gray-700 font-bold mb-2">Affected Page (Optional)</label>
                    <input
                      type="text"
                      value={affectedPage}
                      onChange={(e) => setAffectedPage(e.target.value)}
                      placeholder={reportType === 'FEATURE_REQUEST' ? 'e.g., Student Dashboard' : 'e.g., /student/profile'}
                      className="w-full px-4 py-3 rounded-xl border-2 border-gray-100 focus:border-[#0b3578] focus:outline-none transition-colors"
                    />
                  </div>
                </div>

                <div className="mb-8">
                  <label className="block text-gray-700 font-bold mb-2">Screenshot (Optional)</label>
                  {!screenshotPreview ? (
                    <div className="relative h-40 border-2 border-dashed border-gray-200 rounded-xl flex flex-col items-center justify-center hover:border-blue-400 hover:bg-blue-50 transition-all cursor-pointer group">
                      <input type="file" accept="image/*" onChange={handleFileChange} className="absolute inset-0 opacity-0 cursor-pointer" />
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-gray-400 group-hover:text-blue-500 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                      </svg>
                      <span className="text-gray-500 group-hover:text-blue-600 font-medium">Click to upload screenshot</span>
                      <span className="text-xs text-gray-400 mt-1">PNG, JPG up to 1MB</span>
                    </div>
                  ) : (
                    <div className="relative h-48 rounded-xl overflow-hidden shadow-md">
                      <Image src={screenshotPreview} alt="Preview" fill className="object-cover" />
                      <button type="button" onClick={() => { setScreenshot(null); setScreenshotPreview(null); }}
                        className="absolute top-2 right-2 bg-red-600 text-white p-2 rounded-full shadow-lg hover:bg-red-700 transition-colors">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                      </button>
                    </div>
                  )}
                </div>

                <div className="flex gap-4">
                  <button type="button" onClick={() => setIsModalOpen(false)}
                    className="flex-1 px-6 py-3 border-2 border-gray-100 text-gray-600 font-bold rounded-xl hover:bg-gray-50 transition-colors">
                    Cancel
                  </button>
                  <button type="submit" disabled={isSubmitting}
                    className={`flex-[2] text-white font-bold py-3 rounded-xl shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed ${reportType === 'FEATURE_REQUEST' ? 'bg-purple-700 hover:bg-purple-800' : 'bg-[#0b3578] hover:bg-[#082a61]'}`}>
                    {isSubmitting ? 'Submitting...' : reportType === 'FEATURE_REQUEST' ? 'Submit Suggestion' : 'Submit Bug Report'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Login Prompt Modal */}
        {isLoginPromptOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden animate-scale-in">
              <div className="bg-[#0b3578] p-6 text-white text-center">
                <div className="text-5xl mb-4">🔐</div>
                <h2 className="text-xl font-bold">Login Required</h2>
                <p className="text-white/80 mt-2">Please log in to submit your report or suggestion.</p>
              </div>
              <div className="p-8 text-center">
                <p className="text-gray-600 mb-2">Your draft has been saved.</p>
                <p className="text-sm text-gray-500 mb-4">After logging in, visit this page again and your submission will be completed automatically.</p>
                <p className="text-xs text-gray-400 mb-6">Developers: Sign in with <strong>Google</strong> using your registered email.</p>
                <div className="flex gap-4">
                  <button
                    onClick={() => setIsLoginPromptOpen(false)}
                    className="flex-1 px-6 py-3 border-2 border-gray-100 text-gray-600 font-bold rounded-xl hover:bg-gray-50 transition-colors"
                  >
                    Cancel
                  </button>
                  <Link
                    href="/?login=true"
                    className="flex-[2] bg-[#0b3578] hover:bg-[#082a61] text-white font-bold py-3 rounded-xl shadow-lg text-center transition-all inline-block"
                  >
                    Go to Login
                  </Link>
                </div>
              </div>
            </div>
          </div>
        )}

        <Footer />
      </div>
    </div>
  );
}

"use client";
import { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import toast from "react-hot-toast";
import Link from "next/link";
import Footer from "@/components/Footer";
import Header from "@/components/Header";
import HeaderMobileView from "@/components/Header-MobileView";
import ClientShell from "@/components/ClientShell.client";

export default function ResetPassword() {
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [passwordVisible, setPasswordVisible] = useState(false);
  const [confirmVisible, setConfirmVisible] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [redirecting, setRedirecting] = useState(false);
  const [passwordValid, setPasswordValid] = useState(false);
  const [passwordStrengthLabel, setPasswordStrengthLabel] = useState('');
  const [tokenStatus, setTokenStatus] = useState('loading'); // 'loading' | 'VALID' | 'EXPIRED' | 'USED' | 'INVALID'
  const [tokenMessage, setTokenMessage] = useState('');

  const params = useParams();
  const router = useRouter();
  const token = params?.token;

  useEffect(() => {
    let cancelled = false;
    async function validateToken() {
      if (!token) {
        setTokenStatus('INVALID');
        setTokenMessage('Invalid reset link');
        return;
      }

      setTokenStatus('loading');
      try {
        const res = await fetch(`/api/auth/reset-password/${encodeURIComponent(token)}`);
        const data = await res.json().catch(() => ({ /* empty */ }));

        let status = data.status;
        if (!status) {
          if (res.status === 200) status = 'VALID';
          else if (res.status === 410) status = 'EXPIRED';
          else if (res.status === 409) status = 'USED';
          else status = 'INVALID';
        }

        if (!cancelled) {
          setTokenStatus(status);
          setTokenMessage(data.message || '');
        }
      } catch (err) {
        if (!cancelled) {
          setTokenStatus('INVALID');
          setTokenMessage('Invalid reset link');
        }
      }
    }

    validateToken();
    return () => {
      cancelled = true;
    };
  }, [token]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setMessage("");
    setError("");

    if (password !== confirmPassword) {
      toast.error("Passwords do not match");
      setIsLoading(false);
      return;
    }

    try {
      const response = await fetch(`/api/auth/reset-password/${token}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password }),
      });

      const data = await response.json().catch(() => ({ /* empty */ }));

      if (response.ok) {
        toast.success(data.message || "Password reset successful");
        setMessage(data.message || "Password reset successful");
        setRedirecting(true);
        setIsLoading(false);
        setTimeout(() => router.push("/"), 2000);
      } else {
        const msg = data.error || "An error occurred";
        toast.error(msg);
        setError(msg);
      }
    } catch (err) {
      toast.error("An error occurred");
      setError("An error occurred");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans relative">
      <HeaderMobileView />
      <Header />
      <ClientShell />

      <div id="main-content" className="flex-1 flex flex-col min-h-screen relative overflow-x-hidden transition-all duration-300">
        <main className="flex-1 bg-gray-100 flex items-center justify-center p-4">
          <div className="max-w-md w-full">
            <div className="bg-white border border-gray-200 rounded-xl shadow-sm p-8">
              <div className="text-center mb-8">
                <h1 className="text-2xl font-bold text-[#0b3578] uppercase tracking-tight">Reset Password</h1>
                <p className="text-xs text-slate-400 mt-2 uppercase tracking-widest font-bold">Credential Recovery</p>
              </div>

              {tokenStatus === 'loading' && (
                <div className="py-12 text-center">
                  <div className="w-8 h-8 border-4 border-[#0b3578] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Validating reset link...</p>
                </div>
              )}

              {tokenStatus === 'VALID' && (
                <form onSubmit={handleSubmit} className="space-y-5">
                  <div className="space-y-1.5">
                    <label htmlFor="password" uncomfortable className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                      New Password
                    </label>
                    <div className="relative">
                      <input
                        id="password"
                        type={passwordVisible ? 'text' : 'password'}
                        value={password}
                        onChange={(e) => {
                          const v = e.target.value;
                          setPassword(v);
                          const score = v.length >= 12 ? 3 : v.length >= 10 ? 2 : v.length >= 8 ? 1 : 0;
                          const hasLower = /[a-z]/.test(v);
                          const hasUpper = /[A-Z]/.test(v);
                          const hasNum = /\d/.test(v);
                          const hasSpec = /[!@#$%^&*()_+\-=[\]{ /* empty */ };':"\\|,.<>/?]/.test(v);
                          const passed = v.length >= 8 && hasLower && hasUpper && hasNum && hasSpec;
                          setPasswordValid(passed);
                          if (!v) setPasswordStrengthLabel('');
                          else if (!passed) setPasswordStrengthLabel('Weak');
                          else if (score >= 3) setPasswordStrengthLabel('Strong');
                          else if (score === 2) setPasswordStrengthLabel('Good');
                          else setPasswordStrengthLabel('Fair');
                        }}
                        className="w-full border border-gray-200 rounded px-3 py-2 text-xs focus:outline-none focus:ring-1 focus:ring-[#0b3578]"
                        required
                      />
                      <button
                        type="button"
                        onClick={() => setPasswordVisible((v) => !v)}
                        className="absolute right-2 top-1/2 -translate-y-1/2 text-[10px] font-bold text-slate-400 hover:text-[#0b3578] uppercase"
                      >
                        {passwordVisible ? 'Hide' : 'Show'}
                      </button>
                    </div>
                    {passwordStrengthLabel && (
                      <p className={`text-[9px] font-black uppercase tracking-widest ${passwordValid ? 'text-green-600' : 'text-yellow-600'}`}>Strength: {passwordStrengthLabel}</p>
                    )}
                  </div>

                  <div className="space-y-1.5">
                    <label htmlFor="confirmPassword" className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                      Confirm Password
                    </label>
                    <div className="relative">
                      <input
                        id="confirmPassword"
                        type={confirmVisible ? 'text' : 'password'}
                        value={confirmPassword}
                        onChange={(e) => setConfirmPassword(e.target.value)}
                        className="w-full border border-gray-200 rounded px-3 py-2 text-xs focus:outline-none focus:ring-1 focus:ring-[#0b3578]"
                        required
                      />
                      <button
                        type="button"
                        onClick={() => setConfirmVisible((v) => !v)}
                        className="absolute right-2 top-1/2 -translate-y-1/2 text-[10px] font-bold text-slate-400 hover:text-[#0b3578] uppercase"
                      >
                        {confirmVisible ? 'Hide' : 'Show'}
                      </button>
                    </div>
                    {confirmPassword && password !== confirmPassword && (
                      <p className="text-red-600 text-[9px] font-black uppercase tracking-widest mt-1">Passwords do not match</p>
                    )}
                  </div>

                  <div className="pt-2">
                    <button
                      type="submit"
                      className="w-full bg-[#0b3578] text-white font-bold py-2 rounded text-xs uppercase tracking-widest hover:bg-[#0a2d66] transition-all disabled:opacity-50"
                      disabled={isLoading || redirecting || !password || !confirmPassword || password !== confirmPassword}
                    >
                      {redirecting ? 'Redirecting...' : (isLoading ? 'Processing...' : 'Reset Password')}
                    </button>
                  </div>

                  <div className="text-center">
                    <Link href="/" className="text-[10px] font-black text-[#0b3578] hover:underline uppercase tracking-widest">
                      Back to Login
                    </Link>
                  </div>
                </form>
              )}

              {tokenStatus !== 'loading' && tokenStatus !== 'VALID' && (
                <div className="text-center">
                  <h2 className="text-lg font-bold text-red-600 uppercase tracking-tight">
                    {tokenStatus === 'EXPIRED' ? 'Link Expired' : tokenStatus === 'USED' ? 'Link Used' : 'Invalid Link'}
                  </h2>
                  <p className="mt-2 text-xs text-slate-500">{tokenMessage || 'Please request a new reset link.'}</p>
                  <div className="mt-6">
                    <Link href="/" className="inline-block bg-[#0b3578] text-white px-6 py-2 rounded text-xs font-bold uppercase tracking-widest hover:bg-[#0a2d66] transition-all">Go to Home</Link>
                  </div>
                </div>
              )}
            </div>
          </div>
        </main>

        <Footer />
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { useStudent } from '@/context/StudentContext';
import { getSyllabusUrl } from '@/lib/getSyllabusUrl';
import { getBranchFromRoll, getCurrentStudyingYear, getCurrentSemester } from '@/lib/rollNumber';
import { AcademicsProvider, useAcademicsCache } from '@/context/AcademicsContext';
import toast from 'react-hot-toast';

// Utility: derive subject metadata (kept isolated for future DB migration)
function getSubjectMeta(subjectName) {
  // Placeholder logic: always return Core, 3 credits.
  return { type: 'Core', credits: 3 };
}

// Utility: derive short name code from subject name (e.g., "Introduction to Data Analysis" -> "IDAV")
function deriveShortName(subjectName) {
  if (!subjectName) return '';
  const words = subjectName.split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) return '';
  // Take first letter of up to 4 significant words
  const initials = words.slice(0, 4).map(w => w.replace(/[^A-Za-z]/g, '')[0] || '').join('');
  return initials.toUpperCase();
}

export default function AcademicsPage() {
  const { studentData, collegeInfo } = useStudent();
  if (!studentData) return null;

  return (
    <AcademicsProvider roll={studentData.student.roll_no}>
      <AcademicsInner studentData={studentData} collegeInfo={collegeInfo} />
    </AcademicsProvider>
  );
}

function AcademicsInner({ studentData, collegeInfo }) {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [historySubject, setHistorySubject] = useState(null);
  const [historyData, setHistoryData] = useState([]);
  const [loadingHistory, setLoadingHistory] = useState(false);
  const [activeTab, setActiveTab] = useState('subjects');
  const [currentSem, setCurrentSem] = useState(null);
  const [currentYear, setCurrentYear] = useState(null);

  const { cache, saveCache, isReload } = useAcademicsCache() || { /* empty */ };
  
  // BREAK THE LOOP: Use a ref to access the latest cache without making it a dependency of the fetch function.
  // Since fetchAcademicInfo updates the cache, having cache as a dependency creates a cycle.
  const cacheRef = React.useRef(cache);
  const hasFetchedRef = React.useRef(false);

  useEffect(() => {
    cacheRef.current = cache;
  }, [cache]);

  const fetchAcademicInfo = React.useCallback(async (forceRefresh = false) => {
    setLoading(true);
    try {
      // Access current cache via ref to stay independent of re-renders
      const cached = cacheRef.current?.payload;
      
      if (!forceRefresh && cached && !isReload) {
        setData(cached.data || []);
        setCurrentSem(cached.semester);
        setCurrentYear(cached.academicYear);
        setLoading(false);
        return;
      }

      const res = await fetch('/api/student/academic-info');
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to fetch academic info');
      const subjects = json.data || [];
      setData(subjects);
      setCurrentSem(json.semester);
      setCurrentYear(json.academicYear);
      // Save payload to session cache - this triggers a re-render but NOT a re-fetch
      try { saveCache({ data: subjects, semester: json.semester, academicYear: json.academicYear }); } catch { /* empty */ }
    } catch (error) {
      toast.error(error.message);
    } finally {
      setLoading(false);
    }
  }, [saveCache, isReload]);

  const fetchHistory = async (subject) => {
    setHistorySubject(subject);
    setLoadingHistory(true);
    try {
      const res = await fetch(`/api/student/attendance/history?assignment_id=${subject.assignment_id}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to fetch attendance history');
      setHistoryData(json.data || []);
    } catch (error) {
      toast.error(error.message);
    } finally {
      setLoadingHistory(false);
    }
  };

  useEffect(() => {
    // Prevent double-firing in StrictMode or due to parent re-renders
    if (hasFetchedRef.current) return;
    hasFetchedRef.current = true;

    fetchAcademicInfo(false);
  }, [fetchAcademicInfo]);

  // removed unused helpers: getPercentageColor, overallAttendance
  // resolve syllabus URL via helper that uses rollNumber utilities
  function resolveSyllabusUrl(studentData, collegeInfo) {
    try {
      const roll = studentData?.student?.roll_no;
      if (!roll) return null;
      const branch = getBranchFromRoll(roll);
      const yearOfStudy = getCurrentStudyingYear(roll, collegeInfo);
      const semester = getCurrentSemester(roll, collegeInfo);
      if (!branch && yearOfStudy !== 1) return null; // branch required except maybe first year
      if (!yearOfStudy || !semester) return null;
      return getSyllabusUrl({ course: branch, year: yearOfStudy, semester });
    } catch (e) {
      return null;
    }
  }

  const syllabusUrl = resolveSyllabusUrl(studentData, collegeInfo);

  return (
    <div className="w-full max-w-6xl mx-auto space-y-6 text-sm">
      <header className="mb-4">
        <h1 className="text-2xl font-semibold text-gray-800">Academic Subjects and Performance</h1>
        <p className="text-sm text-gray-600 mt-1">Overview of your current semester subjects, attendance, and internal assessment results.</p>
      </header>

          <div className="flex items-center gap-2 mb-3">
            <button onClick={() => setActiveTab('subjects')} className={`px-3 py-2 rounded-md text-sm ${activeTab === 'subjects' ? 'bg-[#0b3578] text-white' : 'bg-white border'}`}>Subjects</button>
            <button onClick={() => setActiveTab('attendance')} className={`px-3 py-2 rounded-md text-sm ${activeTab === 'attendance' ? 'bg-[#0b3578] text-white' : 'bg-white border'}`}>Attendance</button>
            <button onClick={() => setActiveTab('internals')} className={`px-3 py-2 rounded-md text-sm ${activeTab === 'internals' ? 'bg-[#0b3578] text-white' : 'bg-white border'}`}>Internals</button>
            <div className="ml-auto text-xs text-gray-500"></div>
          </div>

          {/* Section 1: Subjects Offered */}
          {activeTab === 'subjects' && (
            <section className="border border-gray-300 rounded-md bg-white p-4">
            <div className="mb-3">
              <h2 className="text-sm font-semibold text-gray-800">
                Subjects Offered {currentSem ? `– Semester ${currentSem}` : ''}
              </h2>
              <p className="text-sm text-gray-600">
                Academic Year {currentYear || '—'}
              </p>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full min-w-0 table-auto">
                <thead className="bg-gray-100 text-sm font-medium text-gray-700">
                  <tr>
                    <th className="text-left py-2.5 px-2 text-[11px] sm:text-sm whitespace-normal wrap-break-word">Code</th>
                    <th className="text-left py-2.5 px-2 text-[11px] sm:text-sm whitespace-normal wrap-break-word">Subject Name</th>
