                            const m2 = sub.mid2_marks !== null ? parseFloat(sub.mid2_marks) : null;
                            const assgn = sub.assignment_marks !== null ? parseFloat(sub.assignment_marks) : null;
                            let total = null;
                            if (m1 !== null || m2 !== null || assgn !== null) {
                              const bestMid = Math.max(m1 ?? 0, m2 ?? 0);
                              total = bestMid + (assgn ?? 0);
                            }
                            const short = deriveShortName(sub.subject_name) || sub.subject_code || '—';
                            return (
                              <tr key={`theory-${sub.subject_code}`} className="border-b">
                                <td className="py-2 px-2 text-xs sm:text-sm text-gray-800 whitespace-normal wrap-break-word">{short}</td>
                                <td className="py-2 px-2 text-xs sm:text-sm text-gray-700 text-right whitespace-normal wrap-break-word">{m1 !== null ? m1 : '--'}</td>
                                <td className="py-2 px-2 text-xs sm:text-sm text-gray-700 text-right whitespace-normal wrap-break-word">{m2 !== null ? m2 : '--'}</td>
                                <td className="py-2 px-2 text-xs sm:text-sm text-gray-700 text-right whitespace-normal wrap-break-word">{assgn !== null ? assgn : '--'}</td>
                                <td className="py-2 px-2 text-xs sm:text-sm text-gray-700 text-right whitespace-normal wrap-break-word">{total !== null ? total.toFixed(1) : '--'}</td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  </div>
                );
              })()}

              {/* Lab subjects */}
              {(() => {
                const labSubjects = data.filter((sub) => sub.subject_type === 'lab');   
                if (!labSubjects.length) return null;
                return (
                  <div className="border border-gray-300 rounded-md bg-white p-4">      
                    <div className="mb-3">
                      <h2 className="text-sm font-semibold text-gray-800">Lab Evaluation</h2>
                      <p className="text-sm text-gray-600">Execution, writing, and record/observation marks for lab subjects.</p>
                    </div>
                    <div className="overflow-x-auto">
                      <table className="w-full min-w-0 table-auto text-sm">
                        <thead className="bg-gray-100 font-medium text-gray-700">       
                          <tr>
                            <th className="text-left py-2 px-2 text-xs sm:text-sm whitespace-normal wrap-break-word">Subject</th>
                            <th className="text-right py-2 px-2 w-24 text-xs sm:text-sm whitespace-normal wrap-break-word">Execution</th>
                            <th className="text-right py-2 px-2 w-24 text-xs sm:text-sm whitespace-normal wrap-break-word">Writing</th>
                            <th className="text-right py-2 px-2 w-24 text-xs sm:text-sm whitespace-normal wrap-break-word">Record/Obs</th>
                            <th className="text-right py-2 px-2 w-20 text-xs sm:text-sm whitespace-normal wrap-break-word">Total</th>
                          </tr>
                        </thead>
                        <tbody>
                          {labSubjects.map((sub) => {
                            const th = sub.lab_theory_marks !== null ? parseFloat(sub.lab_theory_marks) : null;
                            const ex = sub.lab_execution_marks !== null ? parseFloat(sub.lab_execution_marks) : null;
                            const rec = sub.lab_record_marks !== null ? parseFloat(sub.lab_record_marks) : null;
                            let total = null;
                            if (th !== null || ex !== null || rec !== null) {
                              total = (th ?? 0) + (ex ?? 0) + (rec ?? 0);
                            }
                            const short = deriveShortName(sub.subject_name) || sub.subject_code || '—';
                            return (
                              <tr key={`lab-${sub.subject_code}`} className="border-b">
                                <td className="py-2 px-2 text-xs sm:text-sm text-gray-800 whitespace-normal wrap-break-word">{short}</td>
                                <td className="py-2 px-2 text-xs sm:text-sm text-gray-700 text-right whitespace-normal wrap-break-word">{ex !== null ? ex : '--'}</td>
                                <td className="py-2 px-2 text-xs sm:text-sm text-gray-700 text-right whitespace-normal wrap-break-word">{th !== null ? th : '--'}</td>
                                <td className="py-2 px-2 text-xs sm:text-sm text-gray-700 text-right whitespace-normal wrap-break-word">{rec !== null ? rec : '--'}</td>
                                <td className="py-2 px-2 text-xs sm:text-sm text-gray-700 text-right whitespace-normal wrap-break-word">{total !== null ? total.toFixed(1) : '--'}</td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  </div>
                );
              })()}            </section>
          )}
        </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useStudent } from '@/context/StudentContext';
import { getBranchFromRoll, getResolvedCurrentAcademicYear, getBatchFromRoll } from '@/lib/rollNumber';
import { calculateYearAndSemester } from '@/lib/academic-utils';
import ProfileHeaderCard from '@/components/student/ProfileHeaderCard';
import ProfileStatusBar from '@/components/student/ProfileStatusBar';
import ProfileTabs from '@/components/student/ProfileTabs';
import PersonalInfoTab from '@/components/student/PersonalInfoTab';
import SetPasswordGate from '@/components/student/SetPasswordGate';
import ProfileActivityBar from '@/components/student/ProfileActivityBar';
import ProfileWarningBar from '@/components/student/ProfileWarningBar';
import useProfileEdit from '@/hooks/student/useProfileEdit';
import useEmailVerification from '@/hooks/student/useEmailVerification';
import usePasswordSetup from '@/hooks/student/usePasswordSetup';
import useProfileActivity from '@/hooks/student/useProfileActivity';
import Loading from './loading';

export default function StudentProfileNew() {
  const { studentData, collegeInfo, loading: contextLoading, refreshData } = useStudent();
  const [activeTab, setActiveTab] = useState('personal');

  const activity = useProfileActivity();
  
  // Feature hooks (call unconditionally to preserve hook order)
  const password = usePasswordSetup(studentData?.student?.roll_no);
  const profileEdit = useProfileEdit(studentData, refreshData);
  const emailVerify = useEmailVerification({
    rollno: studentData?.student?.roll_no,
    newEmail: profileEdit.email,
    setEmail: profileEdit.setEmail,
    originalEmail: profileEdit.originalEmail,
    isPasswordSet: password.isPasswordSet,
    openSetPasswordModal: password.setShowSetPasswordModal,
    refreshData,
  });

  if (!studentData && contextLoading) return <Loading />;
  if (!studentData) return null;

  const { student } = studentData;

  const branch = getBranchFromRoll(student.roll_no);
  const courseLabel = branch ? `B. Tech (${branch})` : 'B. Tech';
  const { yearOfStudy, semester, semesterLabel } = calculateYearAndSemester(student.roll_no, collegeInfo, student.academic_offset_years || 0);
  const currentAcademicYearLabel = (() => { try { return getResolvedCurrentAcademicYear(student.roll_no, collegeInfo); } catch { return null; } })();
  const batchString = (() => { try { return getBatchFromRoll(student.roll_no); } catch { return null; } })();

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-fadeIn">
      <SetPasswordGate show={password.showSetPasswordModal} rollno={student.roll_no} email={profileEdit.email} onPasswordSet={() => { password.setShowSetPasswordModal(false); refreshData(); }} />

      <ProfileActivityBar activity={activity} student={student} />
      <ProfileWarningBar student={student} />

      <div className="flex items-start justify-center">
        <div className="w-full bg-white shadow-xl rounded-lg p-6 overflow-hidden border border-slate-100">
          <div className="grid grid-cols-1 md:grid-cols-[280px_1fr] gap-8">
            <ProfileHeaderCard student={student} />
            <div className="flex flex-col justify-start">
              <ProfileStatusBar courseLabel={courseLabel} yearOfStudy={yearOfStudy} semesterLabel={semesterLabel} currentAcademicYearLabel={currentAcademicYearLabel} batchString={batchString} />
              <ProfileTabs
                activeTab={activeTab}
                setActiveTab={setActiveTab}
                personalPanel={<PersonalInfoTab student={student} />}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";
import { useEffect, useRef } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import { smoothScrollToElement } from '@/lib/scroll-utils';

export default function ScrollHandler() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const hasScrolled = useRef(false);

  useEffect(() => {
    if (!searchParams) return;
    const scrollTarget = searchParams.get('scroll');
    if (scrollTarget !== 'history') return;
    if (hasScrolled.current) return;

    let intervalId = null;

    const tryScroll = () => {
      if (typeof document === 'undefined') return false;
      const el = document.getElementById('request-history-section');
      if (el) {
        smoothScrollToElement(el, { behavior: 'smooth', block: 'start' });
        el.classList.add('bg-indigo-50', 'transition-colors', 'duration-1000', 'rounded-lg');
        setTimeout(() => el.classList.remove('bg-indigo-50', 'transition-colors', 'duration-1000', 'rounded-lg'), 1000);
        hasScrolled.current = true;
        return true;
      }
      return false;
    };

    // Try immediately, then poll every 100ms until the element exists
    const didScroll = tryScroll();
    if (!didScroll) {
      intervalId = setInterval(() => {
        const ok = tryScroll();
        if (ok && intervalId) {
          clearInterval(intervalId);
          intervalId = null;
          // clean URL param without triggering navigation
          try {
            router.replace('/student/requests/certificates', { scroll: false });
          } catch (e) {
            // ignore
          }
        }
      }, 100);
    } else {
      try {
        router.replace('/student/requests/certificates', { scroll: false });
      } catch (e) { /* empty */ }
    }

    return () => {
      if (intervalId) clearInterval(intervalId);
    };
  }, [searchParams, router]);

  return null;
}

"use client";
export const dynamic = "force-dynamic";
import { useState, useEffect, Suspense, useCallback } from 'react';
import { useStudent } from '@/context/StudentContext';
import { useRouter } from 'next/navigation';
import ScrollHandler from './ScrollHandler';
import toast from 'react-hot-toast';
import CertificatePageLayout from '../../../../components/student/requests/CertificatePageLayout';
import CertificateRequestForm from '../../../../components/student/requests/CertificateRequestForm';
import RequestHistoryDesktop from '../../../../components/student/requests/RequestHistoryDesktop';
import RequestHistoryMobile from '../../../../components/student/requests/RequestHistoryMobile';
import RejectDetailsModal from '../../../../components/student/requests/RejectDetailsModal';
import { smoothScrollToId } from '@/lib/scroll-utils';

// Page-level UPI VPA (source of truth for UPI ID)
const UPI_VPA = 'kuengineeringcollege@sbi';

const certificateOptions = [
  { value: 'Bonafide Certificate', label: 'Bonafide Certificate', fee: 100, clerk: 'admission' },
  { value: 'No Objection Certificate', label: 'No Objection Certificate', fee: 0, clerk: 'admission'},
  { value: 'Course Completion Certificate', label: 'Course Completion Certificate', fee: 100, clerk: 'admission' },
  { value: 'Income Tax (IT) Certificate', label: 'Income Tax (IT) Certificate', fee: 0, clerk: 'scholarship' },
  { value: 'Custodian Certificate', label: 'Custodian Certificate', fee: 100, clerk: 'scholarship' },
  { value: 'Transfer Certificate (TC)', label: 'Transfer Certificate (TC)', fee: 150, clerk: 'admission' },
  { value: 'Migration Certificate', label: 'Migration Certificate', fee: 200, clerk: 'admission' },
  { value: 'Study Conduct Certificate', label: 'Study Conduct Certificate', fee: 100, clerk: 'admission' },
];

export default function CertificateRequestsPage() {
  const router = useRouter();
  const { studentData, loading: contextLoading, certificateRequests, setCertificateRequests, certificateRequestsLoaded, setCertificateRequestsLoaded, isLoadingRequests, setIsLoadingRequests } = useStudent();
  const [selectedCertificate, setSelectedCertificate] = useState(certificateOptions[0].value);
  const [downloadingId, setDownloadingId] = useState(null);
  const [downloadErrors, setDownloadErrors] = useState({ /* empty */ });
  const [isMobile, setIsMobile] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [rejectReq, setRejectReq] = useState(null);
  const [historyFlash, setHistoryFlash] = useState(false);

  const selectedOption = certificateOptions.find(o => o.value === selectedCertificate) || certificateOptions[0];
  
  // Calculate dynamic fee for Bonafide Certificate
  let fee = selectedOption.fee;
  if (selectedCertificate === 'Bonafide Certificate') {
    const hasApprovedBonafide = (certificateRequests || []).some(
      req => req.certificate_type === 'Bonafide Certificate' && req.status === 'APPROVED'
    );
    if (hasApprovedBonafide) {
      fee = 0;
    }
  }

  const fetchRequests = useCallback(async () => {
    try {
      setIsLoadingRequests(true);
      const response = await fetch('/api/student/requests', { method: 'GET', cache: 'no-store' });
      if (response.ok) {
        const data = await response.json();
        // API returns an object like { data: [...] } – store just the array
        const rows = Array.isArray(data) ? data : (data?.data || []);
        setCertificateRequests(rows);
        setCertificateRequestsLoaded(true);
      } else {
        toast.error('Failed to fetch requests.');
      }
    } catch (error) {
      toast.error('An error occurred while fetching requests.');
    } finally {
      setIsLoadingRequests(false);
    }
  }, [setCertificateRequests, setCertificateRequestsLoaded, setIsLoadingRequests]);

  useEffect(() => {
    if (!studentData) return;
    const s = studentData.student;
    const verified = !!(s?.email) && !!(s?.is_email_verified) && !!(s?.password_hash);
    if (!verified) {
      router.replace('/student/requests/verification-required');
      return;
    }
    if (!certificateRequestsLoaded) {
      fetchRequests();
    }
  }, [studentData, certificateRequestsLoaded, fetchRequests, router]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const mq = window.matchMedia('(max-width: 767px)');
    
    // Initial sync - deferred to avoid synchronous setState in effect
    const timeoutId = setTimeout(() => {
      setIsMobile(mq.matches);
    }, 0);

    const handler = (e) => setIsMobile(e.matches);
    
    if (mq.addEventListener) {
      mq.addEventListener('change', handler);
      return () => {
        clearTimeout(timeoutId);
        mq.removeEventListener('change', handler);
      };
    } else {
      mq.addListener(handler);
      return () => {
        clearTimeout(timeoutId);
        mq.removeListener(handler);
      };
    }
  }, []);

  const handleDownload = async (req) => {
    if (downloadingId) return;
    setDownloadErrors(prev => ({ ...prev, [req.request_id]: null }));
    setDownloadingId(req.request_id);
    try {
      const res = await fetch(`/api/student/requests/download/${req.request_id}`, { method: 'GET', credentials: 'same-origin', cache: 'no-store' });
      if (!res.ok) {
        const err = await res.json().catch(() => ({ /* empty */ }));
        throw new Error(err.error || 'Failed to generate certificate');
      }
      const blob = await res.blob();
      
      const contentDisp = res.headers.get('Content-Disposition') || res.headers.get('content-disposition');
      let filename = `Certificate_${req.roll_number || 'certificate'}.pdf`;
      if (contentDisp) {
        const filenameStarMatch = contentDisp.match(/filename\*\s*=\s*([^;]+)/i);
        if (filenameStarMatch) {
          let val = filenameStarMatch[1].trim();
          val = val.replace(/^"/, '').replace(/"$/, '');
          const parts = val.split("''");
          if (parts.length === 2) {
            try { filename = decodeURIComponent(parts[1]); } catch (e) { filename = parts[1]; }
          } else {
            try { filename = decodeURIComponent(val); } catch (e) { filename = val; }
          }
        } else {
          const filenameMatch = contentDisp.match(/filename\s*=\s*"?(.*?)"?(?:;|$)/i);
          if (filenameMatch) filename = filenameMatch[1];
        }
      }

      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename || `Certificate_${req.roll_number || 'certificate'}.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Download error', error);
      setDownloadErrors(prev => ({ ...prev, [req.request_id]: 'Failed to generate certificate. Try again.' }));
    } finally {
      setDownloadingId(null);
    }
  };

  const openRejectModal = (req) => {
    setRejectReq(req);
    setShowRejectModal(true);
  };

  const closeRejectModal = () => {
    setShowRejectModal(false);
    setRejectReq(null);
  };

  const handleReapply = (req) => {
    // Prefill form to allow re-apply
    if (!req) return;
    setSelectedCertificate(req.certificate_type);
    closeRejectModal();
    // Scroll to form
    smoothScrollToId('certificate-type', { behavior: 'smooth', block: 'center' });
  };

  const handleSubmit = async ({ transactionId, paymentScreenshot, finalPurpose, fromDate, toDate }) => {
    setIsLoading(true);
    const formData = new FormData();
    formData.append('certificateType', selectedCertificate);
    formData.append('clerkType', selectedOption.clerk);
    formData.append('paymentAmount', fee);
    formData.append('purpose', finalPurpose);
    if (fromDate) formData.append('fromDate', fromDate);
    if (toDate) formData.append('toDate', toDate);
    // append transaction and screenshot only when provided (avoid sending null)
    if (transactionId) formData.append('transactionId', transactionId);
    if (paymentScreenshot) formData.append('paymentScreenshot', paymentScreenshot);

    try {
      const response = await fetch('/api/student/requests', {
        method: 'POST',
        body: formData,
        cache: 'no-store'
      });
      if (response.ok) {
        // refresh request history from server to avoid optimistic / placeholder rows
        await fetchRequests();
        toast.success('Request submitted successfully!');
        setSelectedCertificate(certificateOptions[0].value);
      } else {
        const errorData = await response.json();
        toast.error(errorData.error || 'Failed to submit request.');
      }
    } catch (error) {
      toast.error('An error occurred while submitting the request.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      <Suspense fallback={null}>
        <ScrollHandler />
      </Suspense>

      <CertificatePageLayout
        title="Certificate Requests"
        left={
          <CertificateRequestForm
            key={selectedCertificate}
            certificateOptions={certificateOptions}
            selectedCertificate={selectedCertificate}
            setSelectedCertificate={setSelectedCertificate}
            fee={fee}
            onSubmit={handleSubmit}
            upiVPA={UPI_VPA}
            isLoading={isLoading}
          />
        }
        bottom={
          isMobile ? (
            <RequestHistoryMobile
              requests={certificateRequests || []}
              downloadingId={downloadingId}
              downloadErrors={downloadErrors}
              onDownload={handleDownload}
              onOpenRejectModal={openRejectModal}
              isLoadingRequests={isLoadingRequests}
            />
          ) : (
            <RequestHistoryDesktop
              requests={certificateRequests || []}
              downloadingId={downloadingId}
              downloadErrors={downloadErrors}
              onDownload={handleDownload}
              onOpenRejectModal={openRejectModal}
              isLoadingRequests={isLoadingRequests}
            />
          )
        }
      />

      <RejectDetailsModal isOpen={showRejectModal} request={rejectReq} onClose={closeRejectModal} onReapply={handleReapply} />
    </>
  );
}

"use client";

import { useStudent } from '@/context/StudentContext';
// No client-side routing for auth; server handles redirects

export default function VerificationRequiredPage() {
  const { studentData, loading } = useStudent();
  const s = studentData?.student || { /* empty */ };
  const studentStatus = {
    email: s.email || null,
    is_email_verified: !!s.is_email_verified,
    password_hash: s.password_hash || null,
  };

  const emailStatus = studentStatus.email && studentStatus.is_email_verified ? 'Verified' : 'Not Verified';
  const passwordStatus = studentStatus.password_hash ? 'Set' : 'Not Set';

  return (
    <div className="max-w-5xl mx-auto py-10">
      <div className="border border-gray-300 p-6 rounded-sm bg-white">
        <h1 className="text-2xl sm:text-3xl font-bold text-gray-900">Verification Required</h1>
        <p className="mt-2 text-gray-800">You must verify your email and set a password before requesting certificates.</p>

        <div className="mt-6">
          <table className="w-full border border-gray-300 text-sm">
            <tbody>
              <tr className="border-t">
                <td className="px-4 py-2 font-medium text-gray-700">Email Status</td>
                <td className="px-4 py-2 text-gray-900">{emailStatus}</td>
              </tr>
              <tr className="border-t">
                <td className="px-4 py-2 font-medium text-gray-700">Password Status</td>
                <td className="px-4 py-2 text-gray-900">{passwordStatus}</td>
              </tr>
            </tbody>
          </table>
        </div>

        <div className="mt-8 flex flex-col sm:flex-row gap-3">
          <a href="/student/settings/security" className="inline-flex items-center justify-center px-5 py-2.5 rounded-sm bg-blue-700 text-white font-medium hover:bg-blue-800">Go to Security & Privacy</a>
          <a href="/student/profile" className="inline-flex items-center justify-center px-5 py-2.5 rounded-sm bg-gray-200 text-gray-900 font-medium hover:bg-gray-300">Back to Profile</a>
        </div>
      </div>
    </div>
  );
}

// src/app/student/settings/edit-profile/page.js
'use client';

import { useEffect, useState, useCallback, useRef } from 'react';
import { useStudent } from '@/context/StudentContext';
import { useRouter } from 'next/navigation';
import Image from 'next/image';
import toast from 'react-hot-toast';
import { COLLEGE_CONFIG } from '@/lib/college-config';
import { getAssetUrl } from '@/lib/assets';

export default function EditProfilePage() {
  const router = useRouter();
  const { studentData, loading: contextLoading, refreshData } = useStudent();
  
  const [formData, setFormData] = useState({
    student: { /* empty */ },
    personal: { /* empty */ },
    academic: { /* empty */ }
  });
  const [originalData, setOriginalData] = useState(null);
  
  const [saving, setSaving] = useState(false);
  const [photoMenuOpen, setPhotoMenuOpen] = useState(false);
  const [profileDataLoaded, setProfileDataLoaded] = useState(false);
  
  // OTP State
  const [showOtpModal, setShowOtpModal] = useState(false);
  const [otpEmail, setOtpEmail] = useState('');
  const [otp, setOtp] = useState('');
  const [verifying, setVerifying] = useState(false);
  const [emailVerified, setEmailVerified] = useState(false);

  const [pfpDataUrl, setPfpDataUrl] = useState(null);
  const [currentPfp, setCurrentPfp] = useState(null);
  const [signatureDataUrl, setSignatureDataUrl] = useState(null);
  const [currentSignature, setCurrentSignature] = useState(null);
  const [proofDataUrl, setProofDataUrl] = useState(null);
  const [latestRequest, setLatestRequest] = useState(null);

  const fileInputRef = useRef(null);
  const signatureInputRef = useRef(null);
  const proofInputRef = useRef(null);
  const menuRef = useRef(null);
  const editBtnRef = useRef(null);

  const displayedPhoto = pfpDataUrl || getAssetUrl(currentPfp) || null;
  const displayedSignature = signatureDataUrl || getAssetUrl(currentSignature);

  useEffect(() => {
    fetchProfileData();
  }, []);

  async function fetchProfileData() {
    try {
      const res = await fetch('/api/student/signature');
      if (res.ok) {
        const data = await res.json();
        setCurrentSignature(data.signature);
        setCurrentPfp(data.pfp);
        setLatestRequest(data.latestRequest);
        
        if (data.details) {
          setFormData(data.details);
          setOriginalData(JSON.parse(JSON.stringify(data.details)));
          setEmailVerified(false); // Reset verified state on fresh fetch
        }
      }
    } catch (err) {
      console.error('Failed to fetch profile data:', err);
    } finally {
      setProfileDataLoaded(true);
    }
  }

  // Close photo menu when clicking outside
  useEffect(() => {
    const handleOutside = (e) => {
      if (!photoMenuOpen) return;
      const t = e.target;
      if (menuRef.current && menuRef.current.contains(t)) return;
      if (editBtnRef.current && editBtnRef.current.contains(t)) return;
      setPhotoMenuOpen(false);
    };
    document.addEventListener('mousedown', handleOutside);
    return () => document.removeEventListener('mousedown', handleOutside);
  }, [photoMenuOpen]);

  // OTP Functions
  const sendOtp = async () => {
    const newEmail = formData.student.email;
    if (!newEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(newEmail)) {
        toast.error('Enter a valid email address first.');
        return;
    }
    
    setVerifying(true);
    const tid = toast.loading('Transmitting OTP to new address...');
    try {
        const res = await fetch('/api/student/send-update-email-otp', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email: newEmail })
        });
        const d = await res.json();
        if (!res.ok) throw new Error(d.error || 'Failed to send OTP');
        
        setOtpEmail(newEmail);
        setShowOtpModal(true);
        toast.success('Verification code dispatched.', { id: tid });
    } catch (e) {
        toast.error(e.message, { id: tid });
    } finally {
        setVerifying(false);
    }
  };

  const verifyOtp = async () => {
    if (otp.length !== 6) {
        toast.error('Verification code must be 6 digits.');
        return;
    }
    setVerifying(true);
    const tid = toast.loading('Validating credentials...');
    try {
        const res = await fetch('/api/student/verify-update-email-otp', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email: otpEmail, otp })
        });
        const d = await res.json();
        if (!res.ok) throw new Error(d.error || 'Invalid code');

        setEmailVerified(true);
        setShowOtpModal(false);
        setOtp('');
        toast.success('Institutional email verified successfully.', { id: tid });
        
        // Note: Do NOT update originalData here - only update it after successful save
        // Keep verified email in transient state for validation
    } catch (e) {
        toast.error(e.message, { id: tid });
    } finally {
        setVerifying(false);
    }
  };

  const getChangedData = () => {
    if (!originalData) return null;
    const changes = { /* empty */ };
    
    ['mobile', 'email'].forEach(field => {
        if (formData.student[field] !== originalData.student[field]) {
            changes[field] = formData.student[field];
        }
    });

    const spd_fields = [
      'father_name','mother_name','nationality','religion','category','sub_caste','area_status','mother_tongue','place_of_birth','father_occupation','guardian_mobile','annual_income','aadhaar_no',
      'curr_house_no', 'curr_street', 'curr_apartment', 'curr_city', 'curr_state', 'curr_pincode', 'curr_country',
      'perm_house_no', 'perm_street', 'perm_apartment', 'perm_city', 'perm_state', 'perm_pincode', 'perm_country',
      'is_current_same_as_permanent',
      'seat_allotted_category','identification_marks','blood_group'
    ];
    spd_fields.forEach(field => {
        if (formData.personal[field] !== originalData.personal[field]) {
            changes[field] = formData.personal[field];
        }
    });

    const sab_fields = ['qualifying_exam','previous_college_details','medium_of_instruction','ranks','ssc_marks','inter_marks'];
    sab_fields.forEach(field => {
        if (formData.academic[field] !== originalData.academic[field]) {
            changes[field] = formData.academic[field];
        }
    });

    return Object.keys(changes).length > 0 ? changes : null;
  };

  const onSave = async () => {
    if (latestRequest && latestRequest.status === 'pending') {
        toast.error('A pending request is already under review.');
        return;
    }

    const changedData = getChangedData();
    if (!changedData && !pfpDataUrl && !signatureDataUrl) {
        toast.error('No modifications detected.');
        return;
    }

    // Input Validations
    if (changedData) {
        // Email Verification Check
        if (changedData.email && !emailVerified) {
            toast.error('Please verify your new email address via OTP first.');
            return;
        }

        // Mobile & Email
        if (changedData.mobile && !/^\d{10}$/.test(changedData.mobile)) {
            toast.error('Mobile number must be exactly 10 digits.');
            return;
        }

        // Personal Details
        const nameRegex = /^[a-zA-Z\s]*$/;
        if (changedData.father_name) {
            if (!nameRegex.test(changedData.father_name)) { toast.error('Father name can only contain letters.'); return; }
            if (changedData.father_name.length > 50) { toast.error('Father name too long.'); return; }
        }
        if (changedData.mother_name) {
            if (!nameRegex.test(changedData.mother_name)) { toast.error('Mother name can only contain letters.'); return; }
            if (changedData.mother_name.length > 50) { toast.error('Mother name too long.'); return; }
        }
        if (changedData.aadhaar_no && !/^\d{12}$/.test(changedData.aadhaar_no)) {
            toast.error('Aadhaar number must be exactly 12 digits.');
            return;
        }
        if (changedData.guardian_mobile && !/^\d{10}$/.test(changedData.guardian_mobile)) {
            toast.error('Guardian mobile must be 10 digits.');
            return;
        }
        const addressFields = [
            'curr_house_no', 'curr_street', 'curr_apartment', 'curr_city', 'curr_state', 'curr_pincode', 'curr_country',
            'perm_house_no', 'perm_street', 'perm_apartment', 'perm_city', 'perm_state', 'perm_pincode', 'perm_country'
        ];
        for (const f of addressFields) {
            if (changedData[f] && changedData[f].length > 255) {
                toast.error(`Address field too long (max 255 chars).`);
                return;
            }
        }
        if (changedData.identification_marks && changedData.identification_marks.length > 200) {
            toast.error('Identification marks too long (max 200 chars).');
            return;
        }

        // Academic Details
        const marksRegex = /^\d{1,3}(\.\d{1,2})?$/;
        if (changedData.ssc_marks && (!marksRegex.test(changedData.ssc_marks) || parseFloat(changedData.ssc_marks) > 100)) {
            toast.error('Invalid SSC Score (max 100%).');
            return;
        }
        if (changedData.inter_marks && (!marksRegex.test(changedData.inter_marks) || parseFloat(changedData.inter_marks) > 100)) {
            toast.error('Invalid Inter Score (max 100%).');
            return;
        }
    }

    // Determine if proof is needed
    // Email and Mobile are exempt from document proof requirement
    let needsProof = false;
    if (changedData) {
        const sensitiveFields = Object.keys(changedData).filter(k => k !== 'email' && k !== 'mobile');
        if (sensitiveFields.length > 0) needsProof = true;
    }

    if (needsProof && !proofDataUrl) {
        toast.error('Verification proof is mandatory for these data updates.');
        return;
    }

    setSaving(true);
    const toastId = toast.loading('Transmitting request to administrative office...');

    try {
        const res = await fetch('/api/student/signature', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            signature: signatureDataUrl || null,
            pfp: pfpDataUrl || null,
            data: changedData,
            proof: proofDataUrl || null
          })
        });
        
        const resData = await res.json();
        if (!res.ok) throw new Error(resData.error || 'Submission failed');
        
        setPfpDataUrl(null);
        setSignatureDataUrl(null);
        setProofDataUrl(null);
        toast.success('Official update request submitted successfully.', { id: toastId });
        await fetchProfileData();
    } catch (e) {
      toast.error(e.message || 'System error occurred.', { id: toastId });
    } finally {
      setSaving(false);
    }
  };

  const onFileSelect = async (file, type) => {
    if (latestRequest && latestRequest.status === 'pending') {
      toast.error('Pending request exists. System locked.');
      return;
    }

    if (file) {
      if (!['image/jpeg', 'image/png', 'image/jpg', 'image/webp'].includes(file.type)) {
        toast.error('File format rejected. Use JPG/PNG/WEBP.');
        return;
      }

      let processedFile = file;
      try {
        const { compressImage } = await import('@/lib/image-compressor');
        processedFile = await compressImage(file, 1200, 1200, 0.6);
      } catch (err) {
        console.error('Image compression failed:', err);
      }

      if (processedFile.size > 1 * 1024 * 1024) {
        toast.error('File exceeds 1MB limit.');
        return;
      }
      const reader = new FileReader();
      reader.onload = () => {
        if (type === 'pfp') setPfpDataUrl(reader.result);
        else if (type === 'sig') setSignatureDataUrl(reader.result);
        else if (type === 'proof') setProofDataUrl(reader.result);
      };
      reader.readAsDataURL(processedFile);
    }
    if (type === 'pfp') setPhotoMenuOpen(false);
  };

  const updateField = (section, field, value) => {
    setFormData(prev => ({
        ...prev,
        [section]: {
            ...prev[section],
            [field]: value
        }
    }));
  };

  const handleCheckboxChange = (checked) => {
    setFormData(prev => {
      const personal = { 
        ...prev.personal, 
        is_current_same_as_permanent: checked 
      };
      if (checked) {
        personal.perm_house_no = prev.personal.curr_house_no || '';
        personal.perm_street = prev.personal.curr_street || '';
        personal.perm_apartment = prev.personal.curr_apartment || '';
        personal.perm_city = prev.personal.curr_city || '';
        personal.perm_state = prev.personal.curr_state || '';
        personal.perm_pincode = prev.personal.curr_pincode || '';
        personal.perm_country = prev.personal.curr_country || 'India';
      }
      return { ...prev, personal };
    });
  };

  const handleAddressChange = (field, value) => {
    setFormData(prev => {
      const personal = { 
        ...prev.personal, 
        [field]: value 
      };
      if (prev.personal.is_current_same_as_permanent && field.startsWith('curr_')) {
        const permField = field.replace('curr_', 'perm_');
        personal[permField] = value;
      }
      return { ...prev, personal };
    });
  };

  if (!studentData && contextLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 text-slate-500 font-bold uppercase tracking-widest text-xs">
        Loading Institutional Records...
      </div>
    );
  }

  const changedData = getChangedData();

  // Determine if proof is needed
  // Email and Mobile are exempt from document proof requirement
  let needsProof = false;
  if (changedData) {
      const sensitiveFields = Object.keys(changedData).filter(k => k !== 'email' && k !== 'mobile');
      if (sensitiveFields.length > 0) needsProof = true;
  }

  return (
    <div className="w-full max-w-6xl mx-auto">
      <div className="bg-white border border-slate-300 shadow-md rounded-sm overflow-hidden">
        
        {/* Header Bar */}
        <div className="bg-[#0b3578] px-6 py-4 border-b border-blue-900 flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div>
            <h1 className="text-xl md:text-2xl font-bold text-white uppercase tracking-tight">Record Modification Portal</h1>
            <p className="text-blue-100 text-sm mt-1">Official Student Data Management System</p>
          </div>
          {latestRequest && (
            <div className={`px-4 py-1.5 border rounded-sm text-[10px] font-black uppercase tracking-widest ${
              latestRequest.status === 'pending' ? 'bg-blue-900/50 text-white border-blue-400 animate-pulse' : 
              latestRequest.status === 'rejected' ? 'bg-rose-900/50 text-white border-rose-400' : 'hidden'
            }`}>
              {latestRequest.status === 'pending' ? '● Application Under Review' : '● Modification Rejected'}
            </div>
          )}
        </div>

        <div className="p-6 md:p-8">
          <div className="grid grid-cols-1 lg:grid-cols-[260px_1fr] gap-12">
            
            {/* Identity Assets Sidebar */}
            <aside className="space-y-10">
              <div className="text-center">
                <span className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Identification Photo</span>
                <div className="relative inline-block">
                  <div className={`w-48 h-48 border-2 ${pfpDataUrl ? 'border-[#0b3578]' : 'border-slate-200'} bg-slate-50 overflow-hidden flex items-center justify-center`}>
                    {displayedPhoto ? (
                      <Image src={displayedPhoto} alt="Profile" width={192} height={192} unoptimized className="object-cover w-full h-full" />
                    ) : (
                      <span className="text-slate-300 font-bold uppercase text-[9px]">No Record Found</span>
                    )}
                  </div>
                  <button 
                    ref={editBtnRef}
                    onClick={() => setPhotoMenuOpen(!photoMenuOpen)}
                    className="absolute -bottom-2 -right-2 w-10 h-10 bg-[#0b3578] text-white rounded-full shadow-lg flex items-center justify-center hover:bg-blue-900 transition-all z-20 border-2 border-white"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  </button>
                  {photoMenuOpen && (
                    <div ref={menuRef} className="absolute left-1/2 -translate-x-1/2 top-full mt-2 bg-white shadow-xl border border-slate-200 w-44 z-30 py-1 rounded-sm">
                      <button onClick={() => fileInputRef.current.click()} className="w-full text-left px-4 py-2 hover:bg-slate-50 text-[11px] font-bold uppercase tracking-wide">
                        Upload New Image
                      </button>
                    </div>
                  )}
                  <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={(e) => onFileSelect(e.target.files[0], 'pfp')} />
                </div>
                {pfpDataUrl && <span className="block text-[9px] font-black text-[#0b3578] uppercase mt-2">New Image Staged</span>}
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Digital Signature Record</label>
                <div className={`w-full h-20 border-2 ${signatureDataUrl ? 'border-[#0b3578] bg-blue-50/20' : 'border-dashed border-slate-200 bg-slate-50'} flex items-center justify-center relative group overflow-hidden`}>
                  {displayedSignature ? (
                    <Image src={displayedSignature} alt="Signature" width={200} height={80} unoptimized className="object-contain w-full h-full p-2" />
                  ) : <span className="text-[9px] font-bold text-slate-300 uppercase tracking-widest">Unrecorded</span>}
                  <button onClick={() => signatureInputRef.current.click()} className="absolute inset-0 bg-[#0b3578]/90 text-white opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-[10px] font-bold uppercase tracking-widest">Update Signature</button>
                </div>
                {signatureDataUrl && <span className="block text-[9px] font-black text-[#0b3578] uppercase text-center italic">New Signature Staged</span>}
                <input ref={signatureInputRef} type="file" accept="image/*" className="hidden" onChange={(e) => onFileSelect(e.target.files[0], 'sig')} />
              </div>

              {latestRequest && latestRequest.status === 'rejected' && (
                <div className="p-4 bg-rose-50 border border-rose-200 rounded-sm">
                  <h3 className="text-[10px] font-black text-rose-700 uppercase tracking-widest mb-2">Rejection Analysis</h3>
                  <p className="text-[11px] text-rose-800 leading-relaxed italic font-medium">&quot;{latestRequest.rejection_reason}&quot;</p>
                </div>
              )}
            </aside>

            {/* Modification Form */}
            <div className="space-y-12">
              
              {/* 1. System Identity */}
              <section>
                <h2 className="text-sm font-bold text-slate-500 uppercase tracking-widest border-b border-slate-200 pb-2 mb-6">Core Identification</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Permanent Roll No</label>
                    <input value={formData.student.roll_no || ''} disabled className="w-full bg-slate-50 border border-slate-200 px-4 py-3 text-sm font-bold text-slate-400 cursor-not-allowed uppercase" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Official Registered Name</label>
                    <input value={formData.student.name || ''} disabled className="w-full bg-slate-50 border border-slate-200 px-4 py-3 text-sm font-bold text-slate-400 cursor-not-allowed uppercase" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Registered Mobile (Direct Update)</label>
                    <input 
                      value={formData.student.mobile || ''} 
                      onChange={(e) => updateField('student', 'mobile', e.target.value)}
                      maxLength={10}
                      placeholder="ENTER 10 DIGIT MOBILE"
                      className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.student.mobile !== originalData?.student.mobile ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`}
                    />
                    {formData.student.mobile !== originalData?.student.mobile && (
                      <span className="text-[9px] font-bold text-amber-600 uppercase tracking-tighter italic">Proof not required for mobile update</span>
                    )}
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Primary Email Address</label>
                    <div className="relative group">
                      <input 
                        value={formData.student.email || ''} 
                        onChange={(e) => {
                            updateField('student', 'email', e.target.value);
                            setEmailVerified(false);
                        }}
                        maxLength={100}
                        disabled={emailVerified}
                        placeholder="ENTER INSTITUTIONAL EMAIL"
                        className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all pr-24 ${emailVerified ? 'bg-emerald-50 border-emerald-500 text-emerald-700' : formData.student.email !== originalData?.student.email ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`}
                      />
                      {formData.student.email !== originalData?.student.email && !emailVerified && (
                        <button 
                          onClick={sendOtp}
                          disabled={verifying}
                          className="absolute right-2 top-1.5 bottom-1.5 px-3 bg-[#0b3578] text-white text-[9px] font-black uppercase tracking-widest hover:bg-blue-900 transition-colors disabled:opacity-50"
                        >
                          {verifying ? '...' : 'Verify Email'}
                        </button>
                      )}
                      {emailVerified && (
                        <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-1.5">
                          <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Verified</span>
                          <span className="text-emerald-500 text-xs">✓</span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </section>

              {/* 2. Personal Records */}
              <section>
                <h2 className="text-sm font-bold text-slate-500 uppercase tracking-widest border-b border-slate-200 pb-2 mb-6">Personal Demographic Records</h2>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {[
                    { label: 'Father Name', field: 'father_name', maxLength: 50 },
                    { label: 'Mother Name', field: 'mother_name', maxLength: 50 },
                    { label: 'Nationality', field: 'nationality', maxLength: 30 },
                    { label: 'Religion', field: 'religion', type: 'select', options: COLLEGE_CONFIG.religions },
                    { label: 'Category', field: 'category', type: 'select', options: COLLEGE_CONFIG.categories },
                    { label: 'Sub Caste', field: 'sub_caste', maxLength: 50 },
                    { label: 'Area Status', field: 'area_status', type: 'select', options: ['Local', 'Non-Local'] },
                    { label: 'Mother Tongue', field: 'mother_tongue', maxLength: 30 },
                    { label: 'Place of Birth', field: 'place_of_birth', maxLength: 100 },
                    { label: 'Father Occupation', field: 'father_occupation', maxLength: 100 },
                    { label: 'Guardian Mobile', field: 'guardian_mobile', maxLength: 10 },
                    { label: 'Annual Income', field: 'annual_income', type: 'select', options: COLLEGE_CONFIG.incomeRanges },
                    { label: 'Aadhaar Card No', field: 'aadhaar_no', maxLength: 12 },
                    { label: 'Allotted Category', field: 'seat_allotted_category' },
                    { label: 'Blood Group', field: 'blood_group', type: 'select', options: COLLEGE_CONFIG.bloodGroups }
                  ].map((item) => (
                    <div key={item.field} className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{item.label}</label>
                      {item.type === 'select' ? (
                        <select 
                          value={formData.personal[item.field] || ''}
                          onChange={(e) => updateField('personal', item.field, e.target.value)}
                          className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal[item.field] !== originalData?.personal[item.field] ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`}
                        >
                          <option value="">SELECT {item.label.toUpperCase()}</option>
                          {item.options.map(opt => <option key={opt} value={opt}>{opt.toUpperCase()}</option>)}
                        </select>
                      ) : (
                        <input 
                          value={formData.personal[item.field] || ''}
                          onChange={(e) => updateField('personal', item.field, e.target.value)}
                          maxLength={item.maxLength}
                          className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal[item.field] !== originalData?.personal[item.field] ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`}
                        />
                      )}
                    </div>
                  ))}
                  {/* Current Address */}
                  <div className="md:col-span-3 border-t border-slate-100 pt-4 mt-2">
                    <h4 className="text-sm font-bold text-indigo-900 mb-2 uppercase tracking-wider">Current Address</h4>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">House No</label>
                        <input placeholder="House No*" value={formData.personal.curr_house_no || ''} onChange={e => handleAddressChange('curr_house_no', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.curr_house_no !== originalData?.personal?.curr_house_no ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Apartment / Landmark</label>
                        <input placeholder="Apartment / Landmark" value={formData.personal.curr_apartment || ''} onChange={e => handleAddressChange('curr_apartment', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.curr_apartment !== originalData?.personal?.curr_apartment ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Street</label>
                        <input placeholder="Street*" value={formData.personal.curr_street || ''} onChange={e => handleAddressChange('curr_street', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.curr_street !== originalData?.personal?.curr_street ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">City</label>
                        <input placeholder="City*" value={formData.personal.curr_city || ''} onChange={e => handleAddressChange('curr_city', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.curr_city !== originalData?.personal?.curr_city ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">State</label>
                        <input placeholder="State*" value={formData.personal.curr_state || ''} onChange={e => handleAddressChange('curr_state', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.curr_state !== originalData?.personal?.curr_state ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">PIN Code</label>
                        <input placeholder="PIN Code*" value={formData.personal.curr_pincode || ''} onChange={e => handleAddressChange('curr_pincode', e.target.value.replace(/\D/g, ''))} maxLength={6} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.curr_pincode !== originalData?.personal?.curr_pincode ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                      </div>
                      <div className="md:col-span-3 space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Country</label>
                        <input placeholder="Country*" value={formData.personal.curr_country || ''} onChange={e => handleAddressChange('curr_country', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.curr_country !== originalData?.personal?.curr_country ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                      </div>
                    </div>
                  </div>

                  {/* Sync Checkbox */}
                  <div className="md:col-span-3 flex items-center gap-2 py-2">
                    <input 
                      type="checkbox" 
                      id="student_is_current_same_as_permanent" 
                      checked={!!formData.personal.is_current_same_as_permanent} 
                      onChange={e => handleCheckboxChange(e.target.checked)} 
                      className="h-4 w-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500 cursor-pointer" 
                    />
                    <label htmlFor="student_is_current_same_as_permanent" className="text-sm font-bold text-gray-700 select-none cursor-pointer">
                      Mark as permanent address
                    </label>
                  </div>

                  {/* Permanent Address */}
                  <div className="md:col-span-3 border-t border-slate-100 pt-4">
                    <h4 className="text-sm font-bold text-indigo-900 mb-2 uppercase tracking-wider">Permanent Address</h4>
                    {!formData.personal.is_current_same_as_permanent ? (
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">House No</label>
                          <input placeholder="House No*" value={formData.personal.perm_house_no || ''} onChange={e => updateField('personal', 'perm_house_no', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.perm_house_no !== originalData?.personal?.perm_house_no ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                        </div>
                        <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Apartment / Landmark</label>
                          <input placeholder="Apartment / Landmark" value={formData.personal.perm_apartment || ''} onChange={e => updateField('personal', 'perm_apartment', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.perm_apartment !== originalData?.personal?.perm_apartment ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                        </div>
                        <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Street</label>
                          <input placeholder="Street*" value={formData.personal.perm_street || ''} onChange={e => updateField('personal', 'perm_street', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.perm_street !== originalData?.personal?.perm_street ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                        </div>
                        <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">City</label>
                          <input placeholder="City*" value={formData.personal.perm_city || ''} onChange={e => updateField('personal', 'perm_city', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.perm_city !== originalData?.personal?.perm_city ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                        </div>
                        <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">State</label>
                          <input placeholder="State*" value={formData.personal.perm_state || ''} onChange={e => updateField('personal', 'perm_state', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.perm_state !== originalData?.personal?.perm_state ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                        </div>
                        <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">PIN Code</label>
                          <input placeholder="PIN Code*" value={formData.personal.perm_pincode || ''} onChange={e => updateField('personal', 'perm_pincode', e.target.value.replace(/\D/g, ''))} maxLength={6} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.perm_pincode !== originalData?.personal?.perm_pincode ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                        </div>
                        <div className="md:col-span-3 space-y-1">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Country</label>
                          <input placeholder="Country*" value={formData.personal.perm_country || ''} onChange={e => updateField('personal', 'perm_country', e.target.value)} className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.perm_country !== originalData?.personal?.perm_country ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`} />
                        </div>
                      </div>
                    ) : (
                      <div className="text-xs font-semibold text-gray-500 bg-gray-50 border border-gray-100 p-3 rounded uppercase tracking-wide">
                        Permanent address is synchronized with current address.
                      </div>
                    )}
                  </div>
                  <div className="md:col-span-3 space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Physical Identification Marks</label>
                    <textarea 
                      value={formData.personal.identification_marks || ''}
                      onChange={(e) => updateField('personal', 'identification_marks', e.target.value)}
                      rows={2}
                      maxLength={200}
                      className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.personal.identification_marks !== originalData?.personal.identification_marks ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`}
                    />
                  </div>
                </div>
              </section>

              {/* 3. Academic Background */}
              <section>
                <h2 className="text-sm font-bold text-slate-500 uppercase tracking-widest border-b border-slate-200 pb-2 mb-6">Prior Academic Background</h2>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {[
                    { label: 'Qualifying Exam', field: 'qualifying_exam', maxLength: 50 },
                    { label: 'Medium of Instruction', field: 'medium_of_instruction', maxLength: 30 },
                    { label: 'State/National Rank', field: 'ranks', maxLength: 20 },
                    { label: 'SSC Score (%)', field: 'ssc_marks', maxLength: 5 },
                    { label: 'Inter/Diploma Score (%)', field: 'inter_marks', maxLength: 5 }
                  ].map((item) => (
                    <div key={item.field} className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{item.label}</label>
                      <input 
                        value={formData.academic[item.field] || ''}
                        onChange={(e) => updateField('academic', item.field, e.target.value)}
                        maxLength={item.maxLength}
                        className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.academic[item.field] !== originalData?.academic[item.field] ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`}
                      />
                    </div>
                  ))}
                  <div className="md:col-span-3 space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Previous Educational Institution</label>
                    <textarea 
                      value={formData.academic.previous_college_details || ''}
                      onChange={(e) => updateField('academic', 'previous_college_details', e.target.value)}
                      rows={2}
                      className={`w-full border px-4 py-3 text-sm font-bold outline-none transition-all ${formData.academic.previous_college_details !== originalData?.academic.previous_college_details ? 'border-amber-400 bg-amber-50/30' : 'border-slate-200'}`}
                    />
                  </div>
                </div>
              </section>

              {/* Verification Evidence */}
              <section className="bg-slate-50 border border-slate-200 p-6 space-y-6">
                <div className="flex items-center gap-3">
                  <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest">Verification Evidence Submission</h2>
                </div>
                <p className="text-[10px] text-slate-500 font-medium leading-relaxed italic uppercase tracking-wider">
                  Provide a high-resolution scan of your Aadhaar card or Government ID to validate the modification requests initiated above.
                </p>
                <div className="flex flex-col md:flex-row items-start gap-8">
                  <div className={`w-full md:w-80 aspect-video border-2 ${proofDataUrl ? 'border-[#0b3578] bg-white' : 'border-dashed border-slate-300 bg-white'} flex items-center justify-center relative group overflow-hidden`}>
                    {proofDataUrl ? (
                      <Image src={proofDataUrl} alt="Proof" width={320} height={180} unoptimized className="object-contain w-full h-full p-1" />
                    ) : (
                      <div className="flex flex-col items-center gap-2">
                        <span className="text-2xl opacity-20">📄</span>
                        <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Pending Upload</span>
                      </div>
                    )}
                    <button onClick={() => proofInputRef.current.click()} className="absolute inset-0 bg-[#0b3578]/90 text-white opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-[10px] font-black uppercase tracking-widest">Select Evidence File</button>
                  </div>
                  <input ref={proofInputRef} type="file" accept="image/*" className="hidden" onChange={(e) => onFileSelect(e.target.files[0], 'proof')} />
                  
                  <div className="flex-1 space-y-4">
                    {needsProof && !proofDataUrl && (
                      <div className="px-4 py-2 bg-rose-100 border border-rose-200 text-rose-700 text-[9px] font-black uppercase tracking-widest leading-none">
                        Error: Substantiating evidence is required for data modifications.
                      </div>
                    )}
                    {!needsProof && changedData && (
                      <div className="px-4 py-2 bg-emerald-100 border border-emerald-200 text-emerald-700 text-[9px] font-black uppercase tracking-widest leading-none">
                        Note: Document proof is not required for email or mobile updates.
                      </div>
                    )}
                    <p className="text-[10px] text-slate-400 font-medium leading-relaxed">
                      SYSTEM SPECIFICATIONS: MAX FILE SIZE 1MB. AUTHORIZED FORMATS: JPG, PNG. ENSURE LEGIBILITY FOR AUDIT PURPOSES.
                    </p>
                  </div>
                </div>
              </section>

              {/* Form Actions */}
              <div className="pt-8 flex flex-col-reverse md:flex-row items-center justify-end gap-4 border-t border-slate-200">
                <button 
                  onClick={() => router.back()} 
                  className="w-full md:w-auto px-8 py-3 bg-slate-100 text-slate-600 font-bold uppercase tracking-widest hover:bg-slate-200 transition-all text-[10px]"
                >
                  Dismiss Changes
                </button>
                <button 
                  disabled={saving || (!changedData && !pfpDataUrl && !signatureDataUrl)} 
                  onClick={onSave}
                  className="w-full md:w-auto px-10 py-3 bg-[#0b3578] text-white font-bold uppercase tracking-widest hover:bg-blue-900 disabled:opacity-30 disabled:grayscale transition-all text-[10px] shadow-md"
                >
                  {saving ? 'Processing Application...' : 'Authenticate & Submit Modification Request'}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* OTP Modal */}
      {showOtpModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-sm shadow-2xl border border-slate-300 w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="bg-[#0b3578] p-4 text-white">
              <h3 className="text-xs font-black uppercase tracking-widest">Institutional Email Verification</h3>
            </div>
            <div className="p-6 space-y-4">
              <div className="bg-blue-50 border border-blue-100 p-4">
                <p className="text-[10px] text-blue-800 leading-relaxed font-bold uppercase tracking-wide">
                  A 6-digit verification code has been dispatched to:
                </p>
                <p className="text-sm font-black text-[#0b3578] mt-1 break-all">{otpEmail}</p>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Enter One-Time Password (OTP)</label>
                <input 
                  type="text"
                  maxLength={6}
                  value={otp}
                  onChange={(e) => setOtp(e.target.value.replace(/\D/g, ''))}
                  className="w-full border-2 border-slate-200 px-4 py-4 text-2xl font-black text-center tracking-[1em] outline-none focus:border-[#0b3578] transition-colors"
                  placeholder="000000"
                />
              </div>
              <p className="text-[10px] text-slate-500 italic">Please check your inbox (and spam folder) for the code. Valid for 10 minutes.</p>
              <div className="flex gap-3 pt-2">
                <button 
                  onClick={() => setShowOtpModal(false)}
                  className="flex-1 px-4 py-3 border border-slate-300 text-slate-600 text-[10px] font-black uppercase tracking-widest hover:bg-slate-50"
                >
                  Cancel
                </button>
                <button 
                  disabled={otp.length !== 6 || verifying}
                  onClick={verifyOtp}
                  className="flex-1 px-4 py-3 bg-emerald-600 text-white text-[10px] font-black uppercase tracking-widest hover:bg-emerald-700 disabled:opacity-50"
                >
                  {verifying ? 'Validating...' : 'Verify & Continue'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import Footer from '@/components/Footer';
import Header from '@/components/Header';
import HeaderMobileView from '@/components/Header-MobileView';
import ClientShell from '@/components/ClientShell.client';
import { useSearchParams } from 'next/navigation';
import { useEffect, useState, Suspense } from 'react';

function VerifyContent() {
  const searchParams = useSearchParams();
  const certId = searchParams.get('id')?.trim();
  const rollNo = searchParams.get('roll')?.trim();
  
  const missingParams = !certId || !rollNo;

  const [status, setStatus] = useState('loading');
  const [data, setData] = useState(null);

  useEffect(() => {
    if (missingParams) {
      return;
    }

    const verify = async (locationData = { /* empty */ }) => {
      // Get device info from UA
      let deviceName = 'Unknown Device';
      try {
        const ua = navigator.userAgent;
        if (ua.includes('iPhone')) deviceName = 'iPhone';
        else if (ua.includes('iPad')) deviceName = 'iPad';
        else if (ua.includes('Android')) {
          const match = ua.match(/Android\s+([^\s;]+|[^;)]+)/);
          deviceName = match ? `Android Device (${match[1]})` : 'Android Device';
        } else if (ua.includes('Windows')) deviceName = 'Windows PC';
        else if (ua.includes('Macintosh')) deviceName = 'MacBook/iMac';
      } catch (e) { /* empty */ }

      fetch('/api/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          certId, 
          rollNo,
          deviceName,
          latitude: locationData.latitude,
          longitude: locationData.longitude
        }),
      })
      .then(res => res.json())
      .then(result => {
        if (result.valid) {
          setData(result.details);
          setStatus('success');
        } else {
          setStatus('failed');
        }
      })
      .catch(() => setStatus('error'));
    };

    // Try to get location
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          verify({
            latitude: pos.coords.latitude,
            longitude: pos.coords.longitude
          });
        },
        () => {
          // If denied or error, verify without location
          verify();
        },
        { timeout: 5000 }
      );
    } else {
      verify();
    }
  }, [certId, rollNo, missingParams]);

  const showInvalidUI = missingParams || status === 'failed' || status === 'error';
  const showLoadingUI = !missingParams && status === 'loading';
  const showSuccessUI = !missingParams && status === 'success' && data;

  return (
   <div className="min-h-screen bg-gray-50 flex flex-col font-sans relative">
      <HeaderMobileView />
      <Header />
      <ClientShell />

      {/* Main Content Area */}
      <div id="main-content" className="flex-1 flex flex-col min-h-screen relative overflow-x-hidden transition-all duration-300">
        <div className="flex-1 bg-slate-50 flex items-start sm:items-center justify-center p-5">
          <div className="bg-white shadow-2xl rounded-2xl max-w-md w-full overflow-hidden border border-slate-200">
            {/* Header Section */}
            <div className="bg-[#0b3578] p-6 text-center">
              <p className="text-white text-xl font-semibold tracking-tight uppercase">Document Verification</p>
            </div>

            <div className="p-8">
              {showLoadingUI && (
                <div className="flex flex-col items-center py-10">
                  <div className="w-12 h-12 border-4 border-[#0b3578] border-t-transparent rounded-full animate-spin"></div>
                  <p className="mt-4 text-slate-600 font-medium uppercase text-xs tracking-widest">Verifying Document...</p>
                </div>
              )}

              {showSuccessUI && (
                <div className="animate-in fade-in duration-700">
                  <div className="bg-green-50 border border-green-200 rounded-xl p-4 mb-6 flex items-center justify-center gap-3">
                    <span className="text-green-600 text-2xl">✓</span>
                    <span className="text-green-800 font-bold uppercase text-sm tracking-widest">Verified Record</span>
                  </div>
                  
                  <div className="space-y-4">
                    <div className="flex flex-col border-b border-slate-100 pb-2">
                      <span className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Student Name</span>
                      <span className="text-slate-900 font-bold text-lg">{data.name}</span>
                    </div>
                    <div className="flex flex-col border-b border-slate-100 pb-2">
                      <span className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Hall Ticket Number</span>
                      <span className="text-slate-900 font-bold text-lg">{data.roll_no}</span>
                    </div>
                    <div className="flex flex-col border-b border-slate-100 pb-2">
                      <span className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Certificate Type</span>
                      <span className="text-slate-900 font-bold text-lg">{data.cert_type}</span>
                    </div>
                    <div className="flex flex-col border-b border-slate-100 pb-2">
                      <span className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Certificate ID</span>
                      <span className="text-slate-900 font-bold text-lg">{data.cert_id}</span>
                    </div>
                    <div className="flex flex-col border-b border-slate-100 pb-2">
                      <span className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Issue Date</span>
                      <span className="text-slate-900 font-bold text-lg">{data.issue_date}</span>
                    </div>
                  </div>

                  <p className="mt-8 text-[10px] text-slate-400 text-center leading-relaxed uppercase tracking-tighter">
                    This verification result is retrieved directly from our institutional database.
                  </p>
                </div>
              )}

              {showInvalidUI && (
                <div className="text-center py-6 animate-in zoom-in duration-300">
                  <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4 text-3xl font-bold">!</div>
                  <h2 className="text-xl font-bold text-slate-800 uppercase tracking-tight">Invalid Certificate</h2>
                  <p className="text-slate-500 mt-2 text-xs leading-relaxed">
                    The certificate details provided do not match our records. 
                    Please ensure you have scanned a genuine QR code.
                  </p>
                  <button 
                    onClick={() => window.location.reload()}
                    className="mt-6 px-6 py-2 bg-[#0b3578] text-white rounded text-xs font-bold uppercase tracking-widest hover:bg-[#0a2d66] transition-all"
                  >
                    Try Again
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
        <Footer/>
      </div>
    </div>
  );
}

export default function VerifyPage() {
  return (
    <Suspense fallback={null}>
      <VerifyContent />
    </Suspense>
  );
}

"use client";
import { useState, useRef } from 'react';
import toast from 'react-hot-toast';
import readXlsxFile from 'read-excel-file'; // Corrected import path
import { parseDate } from '@/lib/date';
import { validateRollNo, branchCodes } from '@/lib/rollNumber';
import { COLLEGE_CONFIG } from '@/lib/college-config';

// --- Constants for Client-Side Validation ---
const HEADERS_MAP = {
  // Required Fields
  roll_no: { display: 'Roll Number', aliases: ['roll no', 'rollnumber', 'registration no', 'admission no', 'hall ticket no', 'studentid', 'h.t no', 'hall ticket number'], required: true },
  name: { display: 'Candidate Name', aliases: ['student name', 'name of the candidate', 'candidate name', 'name of this student'], required: true },
  gender: { display: 'Gender', aliases: ['sex'], required: true },
  date_of_birth: { display: 'Date of Birth', aliases: ['dob'], required: true },
  father_name: { display: 'Father Name', aliases: [], required: true },
  category: { display: 'Category', aliases: ['cast'], required: true },
  permanent_address: { display: 'Permanent Address', aliases: ['permanent address', 'address', 'aadhar card address'], required: true },
  contact_address: { display: 'Contact Address', aliases: ['contact address', 'current address', 'present address'], required: false },

  // Optional Fields (students table)
  mobile: { display: 'Mobile', aliases: ['mobile number', 'phone', 'phone number', 'contact number', 'student number'], required: false },
  email: { display: 'Email', aliases: ['email id'], required: false },

  // Optional Fields (student_personal_details table)
  mother_name: { display: 'Mother Name', aliases: [], required: false },
  aadhaar_no: { display: 'Aadhaar No', aliases: ['aadhaar number', 'aadhaar', 'uid', 'aadhar card number'], required: false },
  nationality: { display: 'Nationality', aliases: ['native country'], required: false },
  religion: { display: 'Religion', aliases: [], required: false },
  sub_caste: { display: 'Sub Caste', aliases: [], required: false },
  area_status: { display: 'Area Status', aliases: ['area statu', 'local /non local'], required: false },
  place_of_birth: { display: 'Place of Birth', aliases: [], required: false },
  father_occupation: { display: 'Father Occupation', aliases: ['father work'], required: false },
  annual_income: { display: 'Annual Income', aliases: ['income'], required: false },
  identification_marks: { display: 'Identification Marks', aliases: ['identify marks'], required: false },

  // Optional Fields (student_academic_background table)
  medium_of_instruction: { display: 'Medium of Instruction', aliases: ['medium', 'medium of education', 'language of education', 'education medium'], required: false },
  ranks: { display: 'Ranks', aliases: ['intermediate rank', 'rank'], required: false },
  qualifying_exam: { display: 'Qualifying Exam', aliases: [], required: false },
  previous_college_details: { display: 'Previous College', aliases: [], required: false },

};

const CATEGORIES = COLLEGE_CONFIG.categories;
const GENDERS = [...COLLEGE_CONFIG.genders, 'Other'];
const AREA_STATUSES = ['Local', 'Non-Local'];

// Mobile number regex: 10 digits only or +91 followed by 10 digits
const MOBILE_REGEX = /^(\+91)?\d{10}$/;
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const NUMBER_REGEX = /^\d+$/;
const DECIMAL_REGEX = /^\d+(\.\d+)?$/;

// --- Utility Functions ---
const normalizeHeader = (header) => {
  if (!header) return '';
  return header.toString().trim().toLowerCase().replace(/[\s-]+/g, '_');
};

const validateRow = (rowData, excelRowNumber) => {
  const rowErrors = { /* empty */ };
  const rowWarnings = { /* empty */ };
  const validationErrors = [];

  // --- REQUIRED FIELDS ---
  // 1. Roll Number
  const rollNo = String(rowData['roll_no'] || '').trim();
  const { isValid: isRollNoValid } = validateRollNo(rollNo);
  if (!rollNo || !isRollNoValid) {
    rowErrors['roll_no'] = 'Invalid Roll Number format.';
    validationErrors.push({ row: excelRowNumber, field: 'Roll Number', message: `Invalid Roll Number format: ${rollNo}` });
  }

  // 2. Candidate Name
  const candidateName = String(rowData['name'] || '').trim();
  if (!candidateName) {
    rowErrors['name'] = 'Candidate Name is required.';
    validationErrors.push({ row: excelRowNumber, field: 'Candidate Name', message: 'Candidate Name is required.' });
  }

  // 3. Gender
  let gender = String(rowData['gender'] || '').trim();
  if (gender) {
    const lowerGender = gender.toLowerCase();
    if (lowerGender === 'm') gender = 'Male';
    if (lowerGender === 'f') gender = 'Female';
  }
  if (!gender || !GENDERS.includes(gender)) {
    rowErrors['gender'] = `Invalid Gender. Must be one of ${GENDERS.join(', ')}.`;
    validationErrors.push({ row: excelRowNumber, field: 'Gender', message: `Invalid Gender: ${gender}` });
  }

  // 4. Date of Birth
  const dobValue = rowData['date_of_birth'];
  if (!dobValue || !parseDate(dobValue)) {
    rowErrors['date_of_birth'] = 'Invalid Date of Birth format.';
    validationErrors.push({ row: excelRowNumber, field: 'Date of Birth', message: `Invalid Date of Birth: ${dobValue}.` });
  }

  // 5. Father Name
  const fatherName = String(rowData['father_name'] || '').trim();
  if (!fatherName) {
    rowErrors['father_name'] = 'Father Name is required.';
    validationErrors.push({ row: excelRowNumber, field: 'Father Name', message: 'Father Name is required.' });
  }

  // 6. Category
  const category = String(rowData['category'] || '').trim().replace(/\s*-\s*/g, '-');
  if (!category || !CATEGORIES.includes(category)) {
    rowErrors['category'] = `Invalid Category. Must be one of ${CATEGORIES.join(', ')}.`;
    validationErrors.push({ row: excelRowNumber, field: 'Category', message: `Invalid Category: ${category}` });
  }
  
  // 7. Permanent Address
  const permanentAddress = String(rowData['permanent_address'] || rowData['address'] || '').trim();
  if (!permanentAddress) {
    rowErrors['permanent_address'] = 'Permanent Address is required.';
    validationErrors.push({ row: excelRowNumber, field: 'Permanent Address', message: 'Permanent Address is required.' });
  }

  // 8. Contact Address (Warning if empty)
  const contactAddress = String(rowData['contact_address'] || '').trim();
  if (!contactAddress) {
    rowWarnings['contact_address'] = 'Contact Address is empty, will default to Permanent Address.';
    validationErrors.push({ row: excelRowNumber, field: 'Contact Address', message: 'Contact Address is empty.', isWarning: true });
  }

  // --- OPTIONAL FIELDS ---
  // 8. Mobile Number (Warning for empty, error for invalid)
  const mobile = String(rowData['mobile'] || '').trim();
  if (!mobile) {
    rowWarnings['mobile'] = 'Mobile Number is empty.';
    validationErrors.push({ row: excelRowNumber, field: 'Mobile', message: 'Mobile Number is empty.', isWarning: true });
  } else if (!MOBILE_REGEX.test(mobile)) {
    rowErrors['mobile'] = 'Invalid Mobile Number format (10 digits or +91XXXXXXXXXX).';
    validationErrors.push({ row: excelRowNumber, field: 'Mobile', message: `Invalid Mobile: ${mobile}` });
  }
  
  // 9. Email (Warning for invalid)
  const email = String(rowData['email'] || '').trim();
  if (email && !EMAIL_REGEX.test(email)) {
    rowWarnings['email'] = 'Invalid Email format.';
    validationErrors.push({ row: excelRowNumber, field: 'Email', message: `Invalid Email: ${email}`, isWarning: true });
  }
  
  // 10. Aadhaar (Warning for invalid)
  const aadhaar = String(rowData['aadhaar_no'] || '').replace(/\s/g, '');
  if (aadhaar && !/^\d{12}$/.test(aadhaar)) {
    rowWarnings['aadhaar_no'] = 'Aadhaar should be 12 digits.';
    validationErrors.push({ row: excelRowNumber, field: 'Aadhaar No', message: `Invalid Aadhaar: ${aadhaar}`, isWarning: true });
  }

  // 11. Area Status (Warning for invalid)
  let areaStatus = String(rowData['area_status'] || '').trim();
  if (areaStatus) {
    const lowerArea = areaStatus.toLowerCase();
    if(lowerArea.includes('non')) areaStatus = 'Non-Local';
    else if(lowerArea.includes('local')) areaStatus = 'Local';
  }
  if (areaStatus && !AREA_STATUSES.includes(areaStatus)) {
    rowWarnings['area_status'] = `Invalid Area Status. Must be 'Local' or 'Non-Local'.`;
    validationErrors.push({ row: excelRowNumber, field: 'Area Status', message: `Invalid Area Status: ${areaStatus}`, isWarning: true });
  }

  // 12. Annual Income (Warning for invalid)
  const annualIncome = String(rowData['annual_income'] || '').trim();
  const incomeRanges = Array.isArray(COLLEGE_CONFIG.incomeRanges) ? COLLEGE_CONFIG.incomeRanges : [];
  
  if (annualIncome && incomeRanges.length > 0) {
    // Normalize both sides to strings for comparison
    const normalizedIncomeRanges = incomeRanges.map(r => String(r).trim());
    if (!normalizedIncomeRanges.includes(annualIncome)) {
      rowWarnings['annual_income'] = `Invalid Income Range. Should be one of ${incomeRanges.join(', ') || 'N/A'}.`;
      validationErrors.push({ row: excelRowNumber, field: 'Annual Income', message: `Invalid Annual Income Range: ${annualIncome}`, isWarning: true });
    }
  }
  
  // 13. Rank (Warning for invalid)
  const rank = String(rowData['intermediate_rank'] || '').trim();
  if (rank && !NUMBER_REGEX.test(rank)) {
    rowWarnings['intermediate_rank'] = 'Rank should be a number.';
    validationErrors.push({ row: excelRowNumber, field: 'Rank', message: `Invalid Rank: ${rank}`, isWarning: true });
  }

  // Other optional fields (mother_name, nationality, etc.) are treated as free text, so no specific validation is added for them.

  return { rowErrors, rowWarnings, validationErrors };
};


// --- Main Component ---
export default function BulkImportStudents({ onImportSuccess, onReset }) {
  const [file, setFile] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef(null);

  // New state for displaying results from API
  const [showSummary, setShowSummary] = useState(false);
  const [summaryData, setSummaryData] = useState(null);
  const [errorDetails, setErrorDetails] = useState([]);
  // Import stage management
  const [importStage, setImportStage] = useState('idle'); // idle | header_error | client_preview | importing | success
  const [headerError, setHeaderError] = useState(null); // { missing: [], missingDisplay: [], aliasHints: { /* empty */ }, detectedHeaders: [] }

  // New states for client-side preview and validation
  const [previewData, setPreviewData] = useState(null); // Array of objects (rows)
  const [previewHeaders, setPreviewHeaders] = useState([]); // Array of string (headers)
  const [clientValidationErrors, setClientValidationErrors] = useState([]); // [{ row: 1, message: '...' }]
  const [hasClientValidationErrors, setHasClientValidationErrors] = useState(false); // Only for critical errors
  const [isClientValidated, setIsClientValidated] = useState(false);
  const [isDataEdited, setIsDataEdited] = useState(false);
  const [detectedHeaderMap, setDetectedHeaderMap] = useState({ /* empty */ });

  const handleCellEdit = (rowIndex, cellKey, value) => {
    const updatedPreviewData = [...previewData];
    updatedPreviewData[rowIndex][cellKey] = value;
    
    const excelRowNumber = rowIndex + 2;
    const { rowErrors, rowWarnings, validationErrors } = validateRow(updatedPreviewData[rowIndex], excelRowNumber);
    
    updatedPreviewData[rowIndex]._errors = rowErrors;
    updatedPreviewData[rowIndex]._warnings = rowWarnings;

    setPreviewData(updatedPreviewData);
    
    // Update the overall validation errors
    const otherRowsErrors = clientValidationErrors.filter(err => err.row !== excelRowNumber);
    const newValidationErrors = [...otherRowsErrors, ...validationErrors];
    setClientValidationErrors(newValidationErrors);
    
    const criticalErrors = newValidationErrors.filter(err => !err.isWarning);
    setHasClientValidationErrors(criticalErrors.length > 0);
    setIsDataEdited(true);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false); // Reset dragging state on drop
    const dt = e.dataTransfer;
    if (dt && dt.files && dt.files.length) {
      // Create a synthetic event object for handleFileChange
      const syntheticEvent = {
        target: {
          files: dt.files
        }
      };
      handleFileChange(syntheticEvent); // Reuse the same logic
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragEnter = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleFileChange = async (e) => {
    const selectedFile = e.target.files[0];
    // Reset all states
    try { toast.dismiss(); } catch { /* empty */ }
    setFile(null);
    setIsLoading(false);
    setShowSummary(false);
    setSummaryData(null);
    setErrorDetails([]);
    setImportStage('idle');
    setHeaderError(null);
    // Reset client-side preview states
    setPreviewData(null);
    setPreviewHeaders([]);
    setClientValidationErrors([]);
    setHasClientValidationErrors(false);
    setIsClientValidated(false);
    setIsDataEdited(false);

    if (selectedFile) {
      const validTypes = [
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'application/vnd.ms-excel',
      ];
      if (!validTypes.includes(selectedFile.type)) {
        toast.error("Invalid file type. Please upload an Excel file (.xlsx or .xls).");
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
      }
      setFile(selectedFile);
      if (onReset) { try { onReset(); } catch { /* empty */ } }

      const rows = await readXlsxFile(selectedFile);
      if (rows.length < 2) {
        toast.error("File is empty or contains only a header.");
        setImportStage('idle');
        return;
      }

      const rawHeaders = rows[0];
      const detectedHeaderMap = { /* empty */ }; // Maps normalized Excel header -> internal_key
      const missingRequired = [];
      const aliasHints = { /* empty */ };

      // Get a set of all required internal keys
      const requiredKeys = new Set(
        Object.keys(HEADERS_MAP).filter(key => HEADERS_MAP[key].required)
      );

      // Map detected headers to our canonical keys
      const mappedInternalKeys = new Set();
      rawHeaders.forEach(rawHeader => {
        const normalizedExcelHeader = normalizeHeader(rawHeader);
        for (const internalKey in HEADERS_MAP) {
          const headerConfig = HEADERS_MAP[internalKey];
          const allPossibleAliases = [
            internalKey, // e.g., 'roll_no'
            normalizeHeader(headerConfig.display), // e.g., 'roll_number'
            ...headerConfig.aliases.map(normalizeHeader) // e.g., 'hall_ticket_no'
          ];
          
          if (allPossibleAliases.includes(normalizedExcelHeader)) {
            if (!mappedInternalKeys.has(internalKey)) { // Avoid mapping multiple Excel columns to the same internal key
              detectedHeaderMap[normalizedExcelHeader] = internalKey;
              mappedInternalKeys.add(internalKey);
              break; 
            }
          }
        }
      });
      
      // Check for missing *required* headers
      requiredKeys.forEach(key => {
        if (!mappedInternalKeys.has(key)) {
          missingRequired.push(key);
        }
      });

      setDetectedHeaderMap(detectedHeaderMap);

      if (missingRequired.length > 0) {
        const missingDisplay = missingRequired.map(key => {
          const config = HEADERS_MAP[key];
          aliasHints[key] = [config.display, ...config.aliases];
          return { field: key, display: config.display };
        });

        setHeaderError({
          missing: missingRequired,
          missingDisplay,
          aliasHints,
          detectedHeaders: rawHeaders,
        });
        setImportStage('header_error');
        toast.error('Missing required headers. Please check the file.');
        return;
      }

      const dataRows = rows.slice(1);
      const allValidationErrors = [];
      const allPreviewData = [];

      for (let i = 0; i < dataRows.length; i++) {
        const row = dataRows[i];
        const rowData = { /* empty */ };
        rawHeaders.forEach((rawHeader, j) => {
            const normalizedExcelHeader = normalizeHeader(rawHeader);
            const internalKey = detectedHeaderMap[normalizedExcelHeader];
            if (internalKey) {
                rowData[internalKey] = row[j];
            }
        });

        const excelRowNumber = i + 2;
        const { rowErrors, rowWarnings, validationErrors } = validateRow(rowData, excelRowNumber);
        
        allPreviewData.push({ ...rowData, _errors: rowErrors, _warnings: rowWarnings });
        allValidationErrors.push(...validationErrors);
      }

      const criticalErrors = allValidationErrors.filter(err => !err.isWarning);
      const warnings = allValidationErrors.filter(err => err.isWarning);

      setPreviewHeaders(rawHeaders);
      setPreviewData(allPreviewData);
      setClientValidationErrors(allValidationErrors);
      setHasClientValidationErrors(criticalErrors.length > 0);
      setIsClientValidated(true);
      setImportStage('client_preview');

      if (criticalErrors.length > 0) {
        toast(`File has ${criticalErrors.length} critical error(s). Please fix before importing.`, { icon: '❌' });
      } else if (warnings.length > 0) {
        toast(`File has ${warnings.length} warning(s). Please review.`, { icon: '⚠️' });
      } else {
        toast.success('File ready for import. Review the preview.');
      }
    }
  };

  const handleUpload = async () => {
    if (!previewData) {
      toast.error('No data to import.');
      return;
    }
    // Prevent upload if there are critical client-side validation errors
    if (hasClientValidationErrors) {
      toast.error('Cannot import due to critical client-side validation errors. Please fix them first.');
      return;
    }

    try { toast.dismiss(); } catch { /* empty */ }
    setIsLoading(true);
    setImportStage('importing');

    try {
      const response = await fetch('/api/clerk/admission/bulk-import', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ students: previewData, headers: previewHeaders }),
      });
      const data = await response.json();

      if (response.ok) {
        setSummaryData({
          totalRows: data.totalRows ?? 0,
          inserted: data.inserted ?? 0,
          updated: data.updated ?? 0,
          skipped: data.skipped ?? 0,
        });
        const rowErrors = Array.isArray(data.errors) ? data.errors : [];
        setErrorDetails(rowErrors);
        setShowSummary(true);
        if (data.inserted > 0 && rowErrors.length === 0) {
          setImportStage('success');
          toast.success('Students imported successfully');
        } else {
          setImportStage('row_preview');
          toast('Import complete. Please review the results.', { icon: '⚠' });
        }
        if (onImportSuccess) {
          onImportSuccess(data);
        }
      } else {
        const errorMessage = data.error || 'Import failed due to a server issue.';
        toast.error(errorMessage);
        setImportStage('client_preview'); // Revert to preview stage on error
      }
    } catch (error) {
      console.error('Upload error:', error);
      toast.error('Import failed due to a network or server error.');
      setImportStage('client_preview');
    } finally {
      setIsLoading(false);
    }
  };

  const handleDismissResults = () => {
    setShowSummary(false);
    setSummaryData(null);
    setErrorDetails([]);
    setHeaderError(null);
    setImportStage('idle');
    // also clear client-side preview
    setFile(null);
    setPreviewData(null);
    setPreviewHeaders([]);
    setClientValidationErrors([]);
    setHasClientValidationErrors(false);
    setIsClientValidated(false);
    if(fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="bg-white p-6 rounded-lg shadow-md border border-gray-200 mt-8">
      <h3 className="text-xl font-semibold text-gray-800 mb-4">Bulk Import Students</h3>
      <input
        ref={fileInputRef}
        type="file"
        accept=".xlsx,.xls"
        onChange={handleFileChange}
        className="sr-only"
        disabled={isLoading}
      />

      {importStage === 'idle' && (
        <div
          role="button"
          tabIndex={0}
          onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); fileInputRef.current?.click(); } }}
          onClick={() => fileInputRef.current?.click()}
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragEnter={handleDragEnter}
          onDragLeave={handleDragLeave}
          className={`mx-auto max-w-2xl p-8 border-2 rounded-lg text-center transition cursor-pointer select-none
            ${isDragging ? 'border-blue-400 bg-blue-50' : 'border-dashed border-gray-300 hover:border-blue-300 hover:bg-gray-50'}`}
        >
          <div className="text-3xl mb-2">📄</div>
          <>
              <div className="text-gray-800 font-medium">Drag & drop Excel file here</div>
              <div className="text-gray-600">or click to browse</div>
              <div className="text-xs text-gray-500 mt-2">Accepted: .xlsx, .xls</div>
          </>
        </div>
      )}

      {importStage === 'client_preview' && previewData && (
        <div className="mt-6">
          <div className="p-4 bg-gray-50 rounded-lg border border-gray-200">
            <h4 className="text-lg font-semibold text-gray-800 mb-2">Data Preview & Validation</h4>
            {(hasClientValidationErrors || clientValidationErrors.some(err => err.isWarning)) && (
              <div className="mb-4 p-3 bg-red-50 rounded-md border border-red-200 text-sm">
                <p className="font-semibold text-red-800">
                  <span className="font-bold">
                    {clientValidationErrors.filter(err => !err.isWarning).length} critical error(s) and{' '}
                    {clientValidationErrors.filter(err => err.isWarning).length} warning(s) found.
                  </span>{' '}
                  Please review the highlighted rows before importing. Critical errors must be fixed, warnings are informational.
                </p>
              </div>
            )}
            {!hasClientValidationErrors && clientValidationErrors.some(err => err.isWarning) && (
                <div className="mb-4 p-3 bg-yellow-50 rounded-md border border-yellow-200 text-sm">
                    <p className="font-semibold text-yellow-800">
                        <span className="font-bold">{clientValidationErrors.filter(err => err.isWarning).length} warning(s) found.</span> Please review.
                    </p>
                </div>
            )}
            <div className="overflow-x-auto max-h-[50vh]">
              <table className="divide-y divide-gray-200">
                <thead className="bg-gray-100 sticky top-0">
                  <tr>
                    <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Row</th>
                    {previewHeaders.map((header, index) => (
                      <th key={index} className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        {header}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {previewData.map((row, rowIndex) => {
                    const hasRowErrors = Object.keys(row._errors).length > 0;
                    const hasRowWarnings = Object.keys(row._warnings).length > 0;
                    const rowStateClass = hasRowErrors ? 'bg-red-50' : hasRowWarnings ? 'bg-yellow-50' : '';

                    return (
                      <tr key={rowIndex} className={rowStateClass}>
                        <td className="px-4 py-2 whitespace-nowrap text-sm font-medium text-gray-900">{rowIndex + 2}</td>
                        {previewHeaders.map((header, colIndex) => {
                          const normalizedHeader = normalizeHeader(header);
                          const internalKey = detectedHeaderMap[normalizedHeader];

                          // If header is not mapped, render a disabled or empty cell
                          if (!internalKey) {
                            return (
                              <td key={colIndex} className="px-1 py-1 whitespace-nowrap text-sm">
                                <input
                                  type="text"
                                  value={""} // Or some indicator for unmapped data
                                  disabled
                                  className="w-full h-full bg-gray-100 border-none p-2 cursor-not-allowed"
                                  title={`Unmapped header: ${header}`}
                                />
                              </td>
                            );
                          }
                          
                          const cellError = row._errors[internalKey];
                          const cellWarning = row._warnings[internalKey];
                          const hasError = !!cellError;
                          const hasWarning = !!cellWarning;

                          return (
                            <td 
                              key={colIndex} 
                              className={`px-1 py-1 whitespace-nowrap text-sm text-gray-700 
                                ${hasError ? 'bg-red-100' : hasWarning ? 'bg-yellow-100' : ''}`}
                            >
                              <input
                                type="text"
                                value={String(row[internalKey] ?? '')}
                                onChange={(e) => handleCellEdit(rowIndex, internalKey, e.target.value)}
                                className={`w-full h-full bg-transparent border-none p-2 focus:ring-1 focus:ring-blue-500 rounded-sm ${
                                  hasError ? 'border-red-300' : hasWarning ? 'border-yellow-300' : ''
                                }`}
                                title={hasError ? cellError : hasWarning ? cellWarning : `Internal Field: ${internalKey}`}
                              />
                            </td>
                          );
                        })}
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
          <div className="mt-6 flex justify-end space-x-4">
            <button
              onClick={handleDismissResults}
              disabled={isLoading}
              className="px-5 py-2 bg-gray-200 text-gray-800 font-semibold rounded shadow hover:bg-gray-300 disabled:bg-gray-400"
            >
              Cancel
            </button>
            <button
              onClick={handleUpload}
              disabled={!file || isLoading}
              className="inline-flex items-center justify-center px-5 py-2 bg-blue-600 text-white font-semibold rounded shadow hover:bg-blue-700 disabled:bg-gray-400 disabled:cursor-not-allowed"
            >
              {isLoading ? 'Importing...' : 'Confirm & Import'}
            </button>
          </div>
        </div>
      )}

      {importStage === 'header_error' && headerError && (
        <div className="mt-8 p-4 bg-red-50 rounded-lg border border-red-200">
          <div className="flex justify-between items-center mb-3">
            <h4 className="text-lg font-semibold text-red-800">Import blocked due to missing required headers</h4>
            <button
              onClick={handleDismissResults}
              className="px-3 py-1 text-sm bg-red-200 hover:bg-red-300 rounded-md text-red-800"
            >
              Dismiss
            </button>
          </div>
          <div className="grid grid-cols-2 gap-6 text-sm">
            <div>
              <h5 className="font-semibold text-red-700 mb-2">Missing headers</h5>
              <ul className="list-disc list-inside space-y-1">
                {headerError.missingDisplay && headerError.missingDisplay.length > 0 ? (
                  headerError.missingDisplay.map((m, idx) => (
                    <li key={idx} className="text-gray-800">
                      <span className="font-medium">{m.display}</span>
                      {headerError.aliasHints && headerError.aliasHints[m.field] && headerError.aliasHints[m.field].length > 0 && (
                        <span className="text-gray-600"> {' '} (expected aliases: {headerError.aliasHints[m.field].join(', ')})</span>
                      )}
                    </li>
                  ))
                ) : (
                  headerError.missing.map((field, idx) => (
                    <li key={idx} className="text-gray-800">{field}</li>
                  ))
                )}
              </ul>
            </div>
            <div>
              <h5 className="font-semibold text-gray-700 mb-2">Detected headers</h5>
              <ul className="list-disc list-inside space-y-1">
                {headerError.detectedHeaders && headerError.detectedHeaders.length > 0 ? (
                  headerError.detectedHeaders.map((h, idx) => (
                    <li key={idx} className="text-gray-800">{h || '(empty)'}</li>
                  ))
                ) : (
                  <li className="text-gray-600">No headers detected.</li>
                )}
              </ul>
            </div>
          </div>
        </div>
      )}

      {showSummary && summaryData && (importStage === 'row_preview' || importStage === 'success') && (
        <div className="mt-8 p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex justify-between items-center mb-3">
            <h4 className="text-lg font-semibold text-gray-800">Import Results</h4>
            <button
              onClick={handleDismissResults}
              className="px-3 py-1 text-sm bg-gray-200 hover:bg-gray-300 rounded-md text-gray-700"
            >
              Dismiss
            </button>
          </div>
          <div className="grid grid-cols-3 gap-4 text-sm text-gray-700">
            <div>
              <span className="font-medium">Total Rows:</span> {summaryData.totalRows}
            </div>
            <div>
              <span className="font-medium">Inserted:</span> {summaryData.inserted}
            </div>
            <div>
              <span className="font-medium">Updated:</span> {summaryData.updated}
            </div>
            <div>
              <span className="font-medium">Skipped (due to errors):</span> {summaryData.skipped}
            </div>
          </div>

          {importStage === 'row_preview' && errorDetails.length > 0 && (
            <div className="mt-6">
              <h5 className="text-md font-semibold text-red-700 mb-3">
                <span className="text-red-500 mr-2">⚠</span> Row-level validation errors
              </h5>
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-100">
                    <tr>
                      <th scope="col" className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Excel Row
                      </th>
                      <th scope="col" className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Roll Number
                      </th>
                      <th scope="col" className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Reason
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {errorDetails.map((error, index) => (
                      <tr key={index} className="hover:bg-red-50">
                        <td className="px-4 py-2 whitespace-nowrap text-sm font-medium text-gray-900">
                          {error.row}
                        </td>
                        <td className="px-4 py-2 whitespace-nowrap text-sm text-gray-500">
                          {error.roll_no || 'N/A'}
                        </td>
                        <td className="px-4 py-2 text-sm text-gray-500">
                          {error.reason}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';
import { useState } from 'react';
import toast from 'react-hot-toast';

export default function ChangePasswordModal({ show, onClose, apiEndpoint }) {
  const [oldPassword, setOldPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    if (newPassword !== confirmPassword) {
      toast.error('New passwords do not match');
      setIsLoading(false);
      return;
    }

    try {
      const response = await fetch(apiEndpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ oldPassword, newPassword }),
      });

      const data = await response.json();

      if (response.ok) {
        toast.success(data.message);
        onClose();
      } else {
        toast.error(data.error || 'An error occurred');
      }
    } catch (error) {
      toast.error('An error occurred');
    } finally {
      setIsLoading(false);
    }
  };

  if (!show) {
    return null;
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white p-8 rounded-lg shadow-md w-full max-w-md">
        <h2 className="text-2xl font-bold mb-6">Change Password</h2>
        <form onSubmit={handleSubmit}>
          <div className="mb-4">
            <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="oldPassword">
              Old Password
            </label>
            <input
              type="password"
              id="oldPassword"
              value={oldPassword ?? ''}
              onChange={(e) => setOldPassword(e.target.value)}
              className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
              required
            />
          </div>
          <div className="mb-4">
            <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="newPassword">
              New Password
            </label>
            <input
              type="password"
              id="newPassword"
              value={newPassword ?? ''}
              onChange={(e) => setNewPassword(e.target.value)}
              className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
              required
            />
          </div>
          <div className="mb-6">
            <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="confirmPassword">
              Confirm New Password
            </label>
            <input
              type="password"
              id="confirmPassword"
              value={confirmPassword ?? ''}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
              required
            />
          </div>
          <div className="flex items-center justify-end gap-4">
            <button
              type="button"
              onClick={onClose}
              className="bg-gray-200 hover:bg-gray-300 text-gray-800 font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
              disabled={isLoading}
            >
              {isLoading ? 'Saving...' : 'Save'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

