  const [fpAttempted, setFpAttempted] = useState(false);
  const [fpRollnoValid, setFpRollnoValid] = useState(false);
  const [fpRollnoError, setFpRollnoError] = useState(''); // New state for specific roll number errors


  // Employee forgot-password states (used for clerk/admin)
  const [fpEmail, setFpEmail] = useState('');
  const [fpEmailLoading, setFpEmailLoading] = useState(false);
  const [fpEmailMessage, setFpEmailMessage] = useState('');
  const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const handleStudentSubmit = async (e) => {
    e.preventDefault();
    setStudentLoading(true);
    setStudentError('');
    const toastId = toast.loading('Logging in...');
    try {
      // convert DD-MM-YYYY -> YYYY-MM-DD for server
      let dobForServer = '';
      if (studentForm.dob) {
        const p = studentForm.dob.split('-');
        if (p.length === 3) {
          const dd = p[0].padStart(2, '0');
          const mm = p[1].padStart(2, '0');
          const yyyy = p[2];
          dobForServer = `${yyyy}-${mm}-${dd}`;
        } else {
          dobForServer = studentForm.dob;
        }
      }

      const res = await fetch('/api/student/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          rollno: studentForm.rollNumber, 
          dob: dobForServer,
          rememberMe: studentRememberMe 
        }),
      });
      const data = await res.json();
      if (res.ok && data.student) {
        toast.success('Login successful!', { id: toastId });
        // Trigger a hard reload to "/" so proxy.js runs and redirects server-side
        window.location.replace('/');
      } else {
        toast.error(data.error || 'Login failed', { id: toastId });
        setStudentError(data.error || 'Login failed');
      }
    } catch (err) {
      toast.error('Network error', { id: toastId });
      setStudentError('Network error');
    } finally {
      setStudentLoading(false);
    }
  };

  // --- Student forgot-password helpers (reused from src/app/forgot-password/student/page.js) ---
  const checkStudentStatus = useCallback(async (currentRollno) => {
    // This helper DOES NOT show any toasts. It only updates local UI state
    // and returns a structured result so the caller (the form) decides what
    // to show to the user. This prevents duplicate toasters.
    if (!currentRollno) {
      setFpIsEligibleForReset(false);
      setFpShowDOBLoginMessage(false);
      setFpDisplayMessage('');
      return { ok: false, status: null, data: null };
    }

    setFpIsCheckingStatus(true);
    let data = null;
    let status = null;
    try {
      const response = await fetch(`/api/auth/forgot-password/student?rollno=${currentRollno}`);
      status = response.status;
      data = await response.json().catch(() => null);

      if (response.ok) {
        if (data && data.is_email_verified && data.has_password_set) {
          setFpIsEligibleForReset(true);
          setFpShowDOBLoginMessage(false);
          setFpDisplayMessage('');
        } else {
          setFpIsEligibleForReset(false);
          setFpShowDOBLoginMessage(true);
          setFpDisplayMessage(
            "You haven't set a password and verified your email. Please login using your Date of Birth as password in (DD-MM-YYYY) format. If you need further assistance, contact support."
          );
        }
      } else {
        setFpIsEligibleForReset(false);
        setFpShowDOBLoginMessage(false);
        setFpDisplayMessage(data?.error || 'Unable to retrieve student status.');
      }
    } catch (error) {
      console.error('Error checking student status:', error);
      setFpIsEligibleForReset(false);
      setFpShowDOBLoginMessage(false);
      setFpDisplayMessage('Network error. Please try again.');
      return { ok: false, status: null, error: 'network' };
    } finally {
      setFpIsCheckingStatus(false);
    }

    return { ok: status >= 200 && status < 300, status, data };
  }, []);


  const handleForgotStudentSubmit = async (e) => {
    e.preventDefault();
    // Enforce client-side roll number validation: 10-11 alphanumeric characters
    const rn = (fpRollno || '').toString().trim();
    setFpAttempted(true);

    if (!fpRollnoValid || fpRollnoError) {
      // Error message is already set by onChange handler
      return;
    }

    setFpIsLoading(true);
    setFpDisplayMessage('');

    try {
      // First, check eligibility explicitly (GET)
      setFpIsCheckingStatus(true);
      const statusData = await checkStudentStatus(rn);

      // statusData is a structured result: { ok, status, data, error }
      if (statusData.error === 'network') {
        toast.error('Unable to verify student status');
        setFpDisplayMessage('Unable to verify student status.');
        return;
      }

      if (!statusData.ok) {
        // Handle expected business case: student not found
        const isNotFound = statusData.status === 404 || (statusData.data && typeof statusData.data.error === 'string' && /not\s*found/i.test(statusData.data.error));
        if (isNotFound) {
          // Single, specific toaster for this scenario
          toast.error('Student Not Found');
          setFpDisplayMessage('Student Not Found');
        } else {
          // Other failures: show a single local toaster
          toast.error(statusData.data?.error || 'Unable to verify student status');
          setFpDisplayMessage(statusData.data?.error || 'Unable to verify student status');
        }
        return;
      }

      if (statusData.data && statusData.data.is_email_verified && statusData.data.has_password_set) {
        // Eligible: send reset link (POST)
        const response = await fetch('/api/auth/forgot-password/student', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ rollno: rn }),
        });
        const data = await response.json();
        if (response.ok) {
          toast.success(data.message);
          setFpDisplayMessage(data.message);
        } else {
          toast.error(data.error || 'An error occurred');
          setFpDisplayMessage(data.error || 'An error occurred');
        }
      } else {
        // Not eligible: show helper message (DOB login info)
        setFpShowDOBLoginMessage(true);
        setFpDisplayMessage(
          "Password reset not available. Please login using your Date of Birth as password. If you need further assistance, contact support."
        );
      }
    } catch (error) {
      toast.error('An error occurred');
      setFpDisplayMessage('An error occurred');
    } finally {
      setFpIsLoading(false);
      setFpIsCheckingStatus(false);
    }
  };

  // --- Employee forgot-password handler (reused from clerk page) ---
  const handleForgotEmployeeSubmit = async (e) => {
    e.preventDefault();
    setFpEmailLoading(true);
    setFpEmailMessage('');

    try {
      const response = await fetch('/api/auth/forgot-password/clerk', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: fpEmail }),
      });

      const data = await response.json();

      if (response.ok) {
        toast.success(data.message);
        setFpEmailMessage(data.message);
      } else {
        toast.error(data.error || 'An error occurred');
      }
    } catch (error) {
      toast.error('An error occurred');
    } finally {
      setFpEmailLoading(false);
    }
  };

  const handleEmployeeSubmit = async (e) => {
    e.preventDefault();
    const isClerk = activePanel === 'clerk';
    const errorSetter = isClerk ? setClerkError : setAdminError;
    const formData = isClerk ? clerkForm : adminForm;
    const rememberMe = isClerk ? clerkRememberMe : adminRememberMe;

    errorSetter('');
    const toastId = toast.loading('Logging in...');
    try {
      const res = await fetch('/api/auth/employee-login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: formData.email,
          password: formData.password,
          rememberMe
        }),
      });

      const data = await res.json();

      if (res.ok) {
        toast.success('Login successful!', { id: toastId });
        window.location.replace('/');
      } else {
        toast.error(data.error || 'Login failed', { id: toastId });
        errorSetter(data.error || 'Login failed');
      }
    } catch (error) {
      toast.error('An unexpected error occurred', { id: toastId });
      errorSetter('An unexpected error occurred');
    }
  };

  if (!activePanel) return null;

  const isModal = variant === 'modal';
  const isEmbedded = !isModal;

  return (
    <div
      id={isModal ? 'login-panels' : undefined}
      className={isModal
        ? 'fixed top-0 left-0 w-full h-full z-100 flex items-center justify-center p-4 lg:p-8 overflow-y-auto bg-slate-900/60 animate-fadeIn'
        : 'w-full'}
      style={isModal ? { position: 'fixed', zIndex: 1000 } : undefined}
      onClick={isModal && dismissable ? (e) => {
        if (e.target.id === 'login-panels') onClose();
      } : undefined}
    >
      <div className={isModal ? 'w-full max-w-md relative animate-slideUp' : 'w-full'}>
        <div className={isModal
          ? 'bg-linear-to-b from-[#0b3578] to-[#1a4a8f] rounded-2xl shadow-2xl overflow-hidden border border-white/10'
          : 'bg-transparent border-0 shadow-none rounded-none'}>
          <div className={isModal ? 'py-8 lg:py-10 px-6 md:px-8' : 'p-0'}>
          
          {/* Student Login Panel */}
          <div 
            className={`transition-all duration-400 ease-out ${
              activePanel === 'student' 
                ? 'opacity-100 transform translate-y-0' 
                : 'opacity-0 transform -translate-y-4 absolute inset-0 pointer-events-none'
            }`}
          >
            {activePanel === 'student' && (
              <div className={isModal ? 'bg-white rounded-xl border shadow-sm p-6 md:p-8' : 'bg-white rounded-sm border border-slate-200 shadow-none p-4 sm:p-5'}>
                <div className={isModal ? 'flex items-start justify-between gap-4 mb-6' : 'flex items-start justify-between gap-3 mb-4'}>
                  <div>
                    <h2 className={isModal ? 'text-2xl font-semibold text-[#0b3578]' : 'text-lg font-bold tracking-wide text-slate-900 uppercase'}>
                      Student Login
                    </h2>
                    <p className={isModal ? 'text-gray-500 text-sm mt-1' : 'text-xs text-slate-600'}>
                      Enter roll number and password.
                    </p>
                  </div>
                  <div className={isModal ? 'inline-flex items-center justify-center w-12 h-12 bg-blue-50 rounded' : 'inline-flex items-center justify-center w-10 h-10 bg-blue-50 rounded-sm shrink-0'}>
                    <svg className={isModal ? 'w-6 h-6 text-[#0b3578]' : 'w-5 h-5 text-[#0b3578]'} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 14l9-5-9-5-9 5 9 5z" />
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 14l6.16-3.422a12.083 12.083 0 01.665 6.479A11.952 11.952 0 0012 20.055a11.952 11.952 0 00-6.824-2.998 12.078 12.078 0 01.665-6.479L12 14z" />
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 14l9-5-9-5-9 5 9 5zm0 0l6.16-3.422a12.083 12.083 0 01.665 6.479A11.952 11.952 0 0012 20.055a11.952 11.952 0 00-6.824-2.998 12.078 12.078 0 01.665-6.479L12 14zm-4 6v-7.5l4-2.222" />
                    </svg>
                  </div>
                </div>
                {mode === 'login' ? (
                <form onSubmit={handleStudentSubmit} className={isEmbedded ? 'space-y-4' : 'space-y-5'}>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Roll Number
                    </label>
                      <input
                      type="text"
                      value={studentForm.rollNumber ?? ''}
                      onChange={(e) => {
                        const v = String(e.target.value || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
                        setStudentForm({ ...studentForm, rollNumber: v });
                        if (v.length > 0 && v.length === MAX_ROLL) {
                          const { isValid } = validateRollNo(v);
                          if (!isValid) {
                            setStudentRollNoError('Invalid Roll Number format.');
                          } else {
                            setStudentRollNoError('');
                          }
                        } else if (v.length > 0 && v.length !== MAX_ROLL) {
                          setStudentRollNoError(`Roll Number must be ${MAX_ROLL} characters long.`);
                        }
                        else {
                          setStudentRollNoError('');
                        }
                      }}
                      placeholder="Enter your Roll Number"
                      className="w-full px-3 py-2.5 border border-gray-300 rounded-md focus:ring-2 focus:ring-[#0b3578] focus:border-transparent transition-all duration-150 text-gray-800 placeholder-gray-400 text-sm"
                      required
                      maxLength={MAX_ROLL}
                    />
                    {studentRollNoError && <div className="text-red-600 text-sm mt-1">{studentRollNoError}</div>}
                  </div>
                  
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Password
                      {isEmbedded ? (
                        <span className="block text-[11px] text-gray-500 font-normal mt-0.5">
                          First-time login: use DOB (DD-MM-YYYY)
                        </span>
                      ) : (
                        <span className="block text-xs text-gray-500 font-normal mt-0.5">
                          First time user ? Use your DOB in the format : DD-MM-YYYY(ex: &quot;31-12-2000&quot;) as password
                        </span>
                      )}
                    </label>
                    <div className="relative">
                      <input
                        type={studentPasswordVisible ? 'text' : 'password'}
                        value={studentForm.dob ?? ''}
                        onChange={(e) => setStudentForm({ ...studentForm, dob: e.target.value })}
                        placeholder="Enter Password"
                        className="w-full px-3 py-2.5 pr-10 border border-gray-300 rounded-md focus:ring-2 focus:ring-[#0b3578] focus:border-transparent transition-all duration-150 text-gray-800 text-sm"
                        required
                      />
                      <button
                        type="button"
                        onClick={() => setStudentPasswordVisible((v) => !v)}
                        aria-label={studentPasswordVisible ? 'Hide password' : 'Show password'}
                        className="absolute inset-y-0 right-2 flex items-center justify-center px-2 text-gray-500 hover:text-gray-700 focus:outline-none"
                      >
                        {studentPasswordVisible ? (
                          <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" viewBox="0 0 24 24" fill="none" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.477 0 8.268 2.943 9.542 7-1.274 4.057-5.065 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3l18 18" />
                          </svg>
                        ) : (
                          // eye icon
                          <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" viewBox="0 0 24 24" fill="none" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.477 0 8.268 2.943 9.542 7-1.274 4.057-5.065 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                          </svg>
                        )}
                      </button>
                    </div>
                    <div className={isEmbedded ? 'flex items-center justify-between mt-2' : 'flex items-center justify-between mt-2'}>
                        <div className="flex items-center">
                          <input
                            id="student-remember-me"
                            type="checkbox"
                            checked={studentRememberMe}
                            onChange={(e) => setStudentRememberMe(e.target.checked)}
                            className="h-4 w-4 text-[#0b3578] focus:ring-[#0b3578] border-gray-300 rounded"
                          />
                          <label htmlFor="student-remember-me" className="ml-2 block text-xs text-gray-700">
                            Remember Me
                          </label>
                        </div>
                        <button
                          type="button"
                          onClick={() => { if (activeRole === 'student') { setMode('forgot-password'); setFpRollno(studentForm.rollNumber ?? ''); } }}
                          className="text-xs text-blue-600 hover:text-blue-800"
                        >
                          Forgot Password?
                        </button>
                      </div>
                  </div>
                  
                  <button
                    type="submit"
                    className="w-full mt-2 bg-[#0b3578] text-white py-2.5 rounded-md font-medium hover:bg-[#0a2d66] transition-colors duration-150 text-sm"
                    disabled={studentLoading || !!studentRollNoError}
                  >
                    {studentLoading ? 'Logging in...' : 'Login'}
                  </button>

                  {studentError && (
                    <div className="text-red-600 text-sm mt-2 text-center">{studentError}</div>
                  )}
                </form>
                ) : (
                  <form onSubmit={handleForgotStudentSubmit} className="space-y-5">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">Roll Number</label>
                      <input
                        type="text"
                        value={fpRollno ?? ''}
                        onChange={(e) => {
                          const v = String(e.target.value || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
                          setFpRollno(v);
                          if (v.length === MAX_ROLL) {
                            const { isValid } = validateRollNo(v);
                            setFpRollnoValid(isValid);
                            if (!isValid) {
                              setFpRollnoError('Invalid Roll Number format.');
                            } else {
                              setFpRollnoError('');
                            }
                          } else {
                            setFpRollnoValid(false);
                            setFpRollnoError(`Roll Number must be exactly ${MAX_ROLL} characters long.`);
                          }
                        }}
                        placeholder="Enter your Roll Number"
                        className="w-full px-3 py-2.5 border border-gray-300 rounded-md focus:ring-2 focus:ring-[#0b3578] focus:border-transparent transition-all duration-150 text-gray-800 placeholder-gray-400 text-sm"
                        required
                        disabled={fpIsCheckingStatus || fpIsLoading}
                        maxLength={MAX_ROLL}
                      />
                      {fpRollnoError && <div className="text-red-600 text-sm mt-1">{fpRollnoError}</div>}
                      <div className="text-right mt-2">
                        <button
                          type="button"
                          onClick={() => { setMode('login'); setFpAttempted(false); setFpDisplayMessage(''); setFpShowDOBLoginMessage(false); }}
                          className="inline-block font-medium text-sm text-blue-500 hover:text-blue-800"
                        >
                          Back to Login
                        </button>
                      </div>
                    </div>

                    {(fpRollno.length < MIN_ROLL) ? (
                      <p className="text-sm text-gray-500 text-center mt-4"></p>
                    ) : fpShowDOBLoginMessage && fpAttempted ? (
                      <div className="bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 p-4 mb-4" role="alert">
                        <p className="font-bold">Information</p>
                        <p>{fpDisplayMessage}</p>
                      </div>
                    ) : (
                      <div className="flex items-center justify-center">
                        <button
                          type="submit"
                          className="bg-blue-600 hover:bg-blue-700 text-white font-medium py-2.5 px-4 rounded-md focus:outline-none text-sm"
                          disabled={fpIsLoading || !fpRollnoValid || !!fpRollnoError}
                        >
                          {fpIsLoading ? 'Sending...' : 'Send Reset Link'}
                        </button>
                      </div>
                    )}

                    {fpDisplayMessage && !fpShowDOBLoginMessage && <p className="text-green-500 text-xs italic mt-4">{fpDisplayMessage}</p>}
                  </form>
                )}

                <p className={isModal ? 'mt-6 text-center text-xs text-gray-600' : 'mt-4 text-center text-[11px] text-gray-600 hidden sm:block'}>
                  Note : Login by DOB will work only for the students who haven&apos;t set their password yet
                </p>
              </div>
            )}
          </div>

          {/* Unified Staff Login Panel (Clerk/Admin) */}
          <div 
            className={`transition-all duration-400 ease-out ${
              (activePanel === 'clerk' || activePanel === 'admin')
                ? 'opacity-100 transform translate-y-0' 
                : 'opacity-0 transform -translate-y-4 absolute inset-0 pointer-events-none'
            }`}
          >
            {(activePanel === 'clerk' || activePanel === 'admin') && (
              <div className={isModal ? 'bg-white rounded-xl border shadow-sm p-6 md:p-8' : 'bg-white rounded-sm border border-slate-200 shadow-none p-4 sm:p-5'}>
                <div className={isModal ? 'flex items-start justify-between gap-4 mb-6' : 'flex items-start justify-between gap-3 mb-4'}>
                  <div>
                    <h2 className={isModal ? 'text-2xl font-semibold text-[#0b3578]' : 'text-lg font-bold tracking-wide text-slate-900 uppercase'}>
                      Staff Login
                    </h2>
                    <p className={isModal ? 'text-gray-500 text-sm mt-1' : 'text-xs text-slate-600'}>
                      Sign in with Google or password.
                    </p>
                  </div>
                  <div className={isModal ? 'inline-flex items-center justify-center w-12 h-12 bg-green-50 rounded' : 'inline-flex items-center justify-center w-10 h-10 bg-green-50 rounded-sm shrink-0'}>
                    <svg className={isModal ? 'w-6 h-6 text-green-700' : 'w-5 h-5 text-green-700'} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                    </svg>
                  </div>
                </div>
                
                {mode === 'login' ? (
                <div>
                  <button
                    onClick={() => {
                      // Browser Google login
                      const base = (process.env.NEXT_PUBLIC_BASE_URL || '').replace(/\/$/, '');
                      const callbackUrl = base ? `${base}/api/auth/google-complete` : '/api/auth/google-complete';
                      return signIn('google', { callbackUrl });
                    }}
                    className={isModal
                      ? 'w-full flex items-center justify-center bg-white border border-gray-300 text-gray-700 py-2.5 rounded-md font-medium hover:bg-gray-50 transition-all duration-150 mb-4'
                      : 'w-full flex items-center justify-center bg-white border border-gray-300 text-gray-700 py-2 rounded-sm font-medium hover:bg-gray-50 transition-all duration-150 mb-3 text-sm'}
                  >
                    <svg className="w-4 h-4 mr-2" viewBox="0 0 48 48" aria-hidden>
                      <path fill="#FFC107" d="M43.611 20.083H42V20H24v8h11.303c-1.649 4.657-6.08 8-11.303 8c-6.627 0-12-5.373-12-12s5.373-12 12-12c3.059 0 5.842 1.154 7.961 3.039l5.657-5.657C34.046 6.053 29.268 4 24 4C12.955 4 4 12.955 4 24s8.955 20 20 20s20-8.955 20-20c0-1.341-.138-2.65-.389-3.917z" />
                      <path fill="#FF3D00" d="M6.306 14.691c-1.413 3.453-2.306 7.243-2.306 11.309C4 28.061 5.484 31.402 7.727 34.091l5.657-5.657C12.015 26.68 11.231 25.158 11.231 24s.784-2.68 2.14-3.64l-5.657-5.657z" />
                      <path fill="#4CAF50" d="M24 48c5.166 0 9.86-1.977 13.409-5.192l-6.19-5.238C29.211 40.776 26.753 42 24 42c-5.223 0-9.641-3.343-11.303-7.918l-5.657-5.657C10.237 43.945 16.598 48 24 48z" />
                      <path fill="#1976D2" d="M43.611 20.083L43.595 20L42 20H24v8h11.303c-.792 2.237-2.231 4.166-4.087 5.571l6.19 5.238C42.022 36.372 44 30.636 44 24c0-1.341-.138-2.65-.389-3.917z" />
                    </svg>
                    Sign in with Google
                  </button>

                  <div className={isModal ? 'relative my-4' : 'relative my-3'}>
                    <div className="absolute inset-0 flex items-center" aria-hidden="true">
                      <div className="w-full border-t border-gray-200"></div>
                    </div>
                    <div className="relative flex justify-center text-xs uppercase">
                      <span className="px-2 bg-white text-gray-500">Or</span>
                    </div>
                  </div>
                <form onSubmit={handleEmployeeSubmit} className={isEmbedded ? 'space-y-4' : 'space-y-5'}>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Email Address
                    </label>
                      <input
                      type="email"
                      value={activePanel === 'clerk' ? clerkForm.email : adminForm.email}
                      onChange={(e) => {
                        const val = e.target.value;
                        if (activePanel === 'clerk') setClerkForm({ ...clerkForm, email: val });
                        else setAdminForm({ ...adminForm, email: val });
                      }}
                      placeholder="Enter your email"
                      className="w-full px-3 py-2.5 border border-gray-300 rounded-md focus:ring-2 focus:ring-green-600 focus:border-transparent transition-all duration-150 text-gray-800 placeholder-gray-400 text-sm"
                      required
                    />
                  </div>
                  
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Password
                    </label>
                    <div className="relative">
                      <input
                        type={(activePanel === 'clerk' ? clerkPasswordVisible : adminPasswordVisible) ? 'text' : 'password'}
                        value={activePanel === 'clerk' ? clerkForm.password : adminForm.password}
                        onChange={(e) => {
                          const val = e.target.value;
                          if (activePanel === 'clerk') setClerkForm({ ...clerkForm, password: val });
                          else setAdminForm({ ...adminForm, password: val });
                        }}
                        placeholder="Enter your password"
                        className="w-full px-3 py-2.5 pr-10 border border-gray-300 rounded-md focus:ring-2 focus:ring-green-600 focus:border-transparent transition-all duration-150 text-gray-800 placeholder-gray-400 text-sm"
                        required
                      />
                      <button
                        type="button"
                        onClick={() => {
                          if (activePanel === 'clerk') setClerkPasswordVisible(v => !v);
                          else setAdminPasswordVisible(v => !v);
                        }}
                        aria-label="Toggle password visibility"
                        className="absolute inset-y-0 right-2 flex items-center justify-center px-2 text-gray-500 hover:text-gray-700 focus:outline-none"
                      >
                        {(activePanel === 'clerk' ? clerkPasswordVisible : adminPasswordVisible) ? (
                          <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" viewBox="0 0 24 24" fill="none" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.477 0 8.268 2.943 9.542 7-1.274 4.057-5.065 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3l18 18" />
                          </svg>
                        ) : (
                          <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" viewBox="0 0 24 24" fill="none" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.477 0 8.268 2.943 9.542 7-1.274 4.057-5.065 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                          </svg>
                        )}
                      </button>
                    </div>
                    <div className="flex items-center justify-between mt-2">
                      <div className="flex items-center">
                        <input
                          id="employee-remember-me"
                          type="checkbox"
                          checked={activePanel === 'clerk' ? clerkRememberMe : adminRememberMe}
                          onChange={(e) => {
                            const val = e.target.checked;
                            if (activePanel === 'clerk') setClerkRememberMe(val);
                            else setAdminRememberMe(val);
                          }}
                          className="h-4 w-4 text-green-600 focus:ring-green-500 border-gray-300 rounded"
                        />
                        <label htmlFor="employee-remember-me" className="ml-2 block text-xs text-gray-700">
                          Remember Me
                        </label>
                      </div>
                      <button
                        type="button"
                        onClick={() => { setMode('forgot-password'); setFpEmail(activePanel === 'clerk' ? clerkForm.email : adminForm.email); }}
                        className="text-xs text-blue-500 hover:text-blue-700"
                      >
                        Forgot Password?
                      </button>
                    </div>
                  </div>
                  
                  <button
                    type="submit"
                    className="w-full mt-2 bg-green-700 text-white py-2.5 rounded-md font-medium hover:bg-green-800 transition-colors duration-150 text-sm"
                  >
                    Login
                  </button>
                  {(activePanel === 'clerk' ? clerkError : adminError) && (
                    <div className="text-red-600 text-sm mt-2 text-center">{activePanel === 'clerk' ? clerkError : adminError}</div>
                  )}
                </form>
                </div>
                ) : (
                  <form onSubmit={handleForgotEmployeeSubmit} className="space-y-5">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">Email Address</label>
                      <input
                        type="email"
                        value={fpEmail ?? ''}
                        onChange={(e) => setFpEmail(e.target.value)}
                        placeholder="Enter your email address"
                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-600 focus:border-transparent transition-all duration-200 text-gray-800 placeholder-gray-400"
                        required
                        disabled={fpEmailLoading}
                      />
                    </div>
                    <div className="flex items-center justify-between">
                      {EMAIL_REGEX.test((fpEmail || '').trim()) ? (
                        <button
                          type="submit"
                          className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
                          disabled={fpEmailLoading}
                        >
                          {fpEmailLoading ? 'Sending...' : 'Send Reset Link'}
                        </button>
                      ) : (
                        <p className="text-sm text-gray-500">&nbsp;</p>
                      )}

                      <button
                        type="button"
                        onClick={() => setMode('login')}
                        className="inline-block align-baseline font-bold text-sm text-blue-500 hover:text-blue-800"
                      >
                        Back to Login
                      </button>
                    </div>
                    {fpEmailMessage && <p className="text-green-500 text-xs italic mt-4">{fpEmailMessage}</p>}
                  </form>
                )}

                <p className={isModal ? 'text-center text-xs text-gray-500 mt-4' : 'text-center text-[11px] text-gray-500 mt-3 hidden sm:block'}>
                  Authorized personnel only
                </p>
              </div>
            )}
          </div>

          </div>
        </div>
        
        {/* Close button (modal only) */}
        {isModal && dismissable && (
          <button 
            onClick={onClose}
            className="block mx-auto mt-6 text-white/80 hover:text-white text-sm transition-colors duration-200 group"
          >
            <span className="flex items-center gap-2">
              <svg className="w-4 h-4 group-hover:rotate-90 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
              </svg>
              Close Panel
            </span>
          </button>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useContext } from 'react';
import { useStudent, StudentContext } from '@/context/StudentContext';
import { useClerk, ClerkContext } from '@/context/ClerkContext';
import { useRouter, usePathname } from 'next/navigation';
import Link from 'next/link';
import ChangePasswordModal from './ChangePasswordModal';
import NotificationDropdown from './NotificationDropdown';
import ClerkNotificationDropdown from './clerk/ClerkNotificationDropdown';
import { NAV_MENU_CONFIG } from '@/lib/menu-config';
import { logoutByRole } from '@/lib/logout';

export default function Navbar({ activePanel, setActivePanel, role, studentProfileMode = false, onLogout, clerkMinimal = false, activeTab, setActiveTab, isSubPage = false, sticky = true, minimalNav = false, brandLabel = 'LOGIN PORTAL' }) {
  const router = useRouter();
  const pathname = usePathname();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [mobileExpanded, setMobileExpanded] = useState({ /* empty */ });
  const [showChangePasswordModal, setShowChangePasswordModal] = useState(false);

  // Use useContext directly to avoid throwing when Provider is missing (e.g. guest home)
  // Hooks must be called unconditionally at the top level
  const studentContext = useContext(StudentContext);
  const clerkContext = useContext(ClerkContext);

  const studentData = studentContext?.studentData;
  const clerkData = clerkContext?.clerkData;

  // Get student and clerk names for greeting
  let studentName = null;
  let clerkName = null;

  if (role === 'student' || studentProfileMode) {
    studentName = studentData?.student?.name || studentData?.name || null;
  }
  if (role === 'clerk' || role === 'clerkAdmission' || role === 'clerkScholarship') {
    clerkName = clerkData?.name || null;
  }
  // (menu definitions moved to top-level `NAV_MENU_CONFIG` for reuse)

  // Role selection: prefer explicit `role` prop. Fall back to studentProfileMode for backward compatibility.
  let effectiveRole = role || (studentProfileMode ? 'student' : 'guest');

  // Map specific clerk sub-roles to their distinct menu variants
  if (effectiveRole === 'admission') {
    effectiveRole = 'clerkAdmission';
  } else if (effectiveRole === 'scholarship') {
    effectiveRole = 'clerkScholarship';
  }

  // Determine if student is fully verified to control menu visibility
  let isStudentVerified = true;
  if (effectiveRole === 'student') {
    const s = studentData?.student;
    if (s) {
      isStudentVerified = !!(s.is_email_verified && s.password_hash);
    }
  }

  const menuItemsRaw = NAV_MENU_CONFIG[effectiveRole] || NAV_MENU_CONFIG['guest'] || [
    { label: 'STUDENT LOGIN', action: 'open-panel-student' },
    { label: 'STAFF LOGIN', action: 'open-panel-clerk' }
  ];

  // Filter student menu if unverified
  const menuItems = (effectiveRole === 'student' && !isStudentVerified)
    ? [
        { label: 'HOME', route: '/student' },
        { label: 'PROFILE', route: '/student/profile' },
        { label: 'MENU', children: [
            { label: 'Security & Privacy', route: '/student/settings/security' }
          ]
        }
      ]
    : menuItemsRaw;

  const handleNavClick = (panel) => {
    if (pathname !== '/' && pathname !== '/admission') {
      router.push('/');
      return;
    }
    if (activePanel === panel) {
      setActivePanel(null); // Close if clicking the same panel
    } else {
      setActivePanel(panel);
    }
    setMobileMenuOpen(false);
  };

  const isActive = (panel) => activePanel === panel;

  const performAction = async (action) => {
    if (action === 'logout') {
      await logoutByRole({ role: effectiveRole, onLogout });
      return;
    }
    if (action === 'change-password') {
      setShowChangePasswordModal(true);
    }
  };

  const handleMobileParentToggle = (idx) => {
    setMobileExpanded(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const handleMobileNavigate = (item) => {
    // Close menu first, then navigate or perform action
    setMobileMenuOpen(false);
    if (item.action === 'logout') {
      setTimeout(async () => {
        await performAction('logout');
      }, 260);
      return;
    }
    if (item.action === 'change-password') {
      setTimeout(() => performAction('change-password'), 260);
      return;
    }
    if (item.action && item.action.startsWith('open-panel-')) {
      const panel = item.action.split('open-panel-')[1];
      setTimeout(() => handleNavClick(panel), 260);
      return;
    }
    if (item.route) {
      setTimeout(() => router.push(item.route), 260);
    }
  };

  return (
    <>
      <nav className={`bg-[#0b3578] shadow-lg ${sticky ? 'sticky z-50' : 'relative z-20'} pt-[env(safe-area-inset-top)]`} style={sticky ? { top: 'var(--site-header-height, 72px)' } : undefined}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className={`flex items-center h-13 ${minimalNav ? 'justify-start' : 'justify-between'}`}>
            <div className={`flex items-center gap-4 ${minimalNav ? 'pl-2 sm:pl-4' : 'shrink-0'}`}>
              <span className="text-white text-lg font-bold tracking-wide uppercase">{brandLabel}</span>
            </div>

            {/* Desktop Menu */}
            {!minimalNav && (
            <div className="hidden md:flex items-center gap-6">
              <div className="flex items-center gap-4">
                {(menuItems || []).map((item, idx) => {
                  const hasChildren = Array.isArray(item.children) && item.children.length > 0;
                  if (hasChildren) {
                    return (
                      <div key={idx} className="relative group">
                        <button className="text-white px-3 py-2 text-sm tracking-wide uppercase relative flex items-center cursor-pointer">
                          <span>{item.label}</span>
                          <svg className="w-4 h-4 ml-2 transform transition-transform duration-200 ease-in-out group-hover:rotate-90" viewBox="0 0 20 20" fill="none" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 4l8 6-8 6" />
                          </svg>
                          <span className={`absolute bottom-0 left-0 h-0.5 bg-white transition-all duration-300 ease-in-out ${
                            // underline parent if any child matches current pathname
                            (Array.isArray(item.children) && item.children.some(c => c.route && pathname && pathname.startsWith(c.route))) ? 'w-full' : 'w-0 group-hover:w-full'
                          }`}></span>
                        </button>
                        <div className="absolute left-0 top-full w-56 bg-white rounded-b-md shadow-lg py-1 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 transform z-50">
                          {item.children.map((c, ci) => {
                              if (c.route && c.route !== '#') {
                              const childActive = pathname && pathname.startsWith(c.route);
                              return (
                                <Link key={ci} href={c.route} className={`block px-4 py-2 text-sm ${childActive ? 'text-[#0b3578] underline' : 'text-gray-700 hover:bg-[#0b3578] hover:text-white'} transition-colors`}>{c.label}</Link>
                              );
                            }
                            if (c.action) {
                              return (
                                <button key={ci} onClick={() => performAction(c.action)} className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-[#0b3578] hover:text-white transition-colors">{c.label}</button>
                              );
                            }
                            return (
                              <button key={ci} className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-[#0b3578] hover:text-white transition-colors" onClick={(e) => e.preventDefault()}>{c.label}</button>
                            );
                          })}
                        </div>
                      </div>
                    );
                  }
                  // action items
                  if (item.action) {
                    if (typeof item.action === 'string' && item.action.startsWith('open-panel-')) {
                      const panelName = item.action.split('open-panel-')[1];
                      return (
                        <button key={idx} onClick={() => handleNavClick(panelName)} className={`text-white px-3 py-2 text-sm tracking-wide uppercase relative group cursor-pointer`}>
                          {item.label}
                          <span className={`absolute bottom-0 left-0 h-0.5 bg-white transition-all duration-300 ease-in-out ${isActive(panelName) ? 'w-full' : 'w-0 group-hover:w-full'}`}></span>
                        </button>
                      );
                    }
                    return (
                      <button key={idx} onClick={() => performAction(item.action)} className="text-white px-3 py-2 text-sm tracking-wide uppercase relative group cursor-pointer">
                        {item.label}
                        <span className="absolute bottom-0 left-0 h-0.5 bg-white transition-all duration-300 ease-in-out w-0 group-hover:w-full"></span>
                      </button>
                    );
                  }
                  // Render a real link only when a valid route exists and is not a placeholder
                  if (item.route && item.route !== '#') {
                    // Exact match for root route to prevent multiple highlighting
                    const routeActive = item.route === '/' 
                      ? pathname === '/' 
                      : (pathname && pathname.startsWith(item.route));

                    return (
                      <Link key={idx} href={item.route} className="text-white px-3 py-2 text-sm tracking-wide uppercase relative group">
                        {item.label}
                        <span className={`absolute bottom-0 left-0 h-0.5 bg-white transition-all duration-300 ease-in-out ${routeActive ? 'w-full' : 'w-0 group-hover:w-full'}`}></span>
                      </Link>
                    );
                  }
                  // Otherwise render a non-navigating button (avoids showing '#' in status bar)
                  return (
                    <button key={idx} onClick={() => { /* empty */ }} className={`text-white px-3 py-2 text-sm tracking-wide uppercase relative group text-left`}>
                      {item.label}
                      <span className="absolute bottom-0 left-0 h-0.5 bg-white transition-all duration-300 ease-in-out w-0 group-hover:w-full"></span>
                    </button>
                  );
                })}
              </div>

              {/* Functional Notification Dropdown */}
              {effectiveRole === 'student' && (
                <div className="border-l border-white/10 pl-4">
                  <NotificationDropdown />
                </div>
              )}
              {(effectiveRole === 'clerkAdmission' || effectiveRole === 'clerkScholarship') && (
                <div className="border-l border-white/10 pl-4">
                  <ClerkNotificationDropdown />
                </div>
              )}
            </div>
            )}
            {/* Mobile Menu Button (single element morphing hamburger -> X) */}
            {!minimalNav && (
            <div className="md:hidden">
              <button
                onClick={() => setMobileMenuOpen(prev => !prev)}
                className="text-white focus:outline-none p-2"
                aria-label="Toggle menu"
              >
                <span className="relative w-6 h-6 inline-block">
                  <span
                    className={`absolute left-0 top-1/2 w-6 h-0.5 bg-white transform transition duration-200 ease-in-out origin-center ${mobileMenuOpen ? 'translate-y-0 rotate-45' : '-translate-y-2'}`}
                  />
                  <span
                    className={`absolute left-0 top-1/2 w-6 h-0.5 bg-white transform transition-opacity duration-200 ease-in-out ${mobileMenuOpen ? 'opacity-0' : 'opacity-100'}`}
                  />
                  <span
                    className={`absolute left-0 top-1/2 w-6 h-0.5 bg-white transform transition duration-200 ease-in-out origin-center ${mobileMenuOpen ? 'translate-y-0 -rotate-45' : 'translate-y-2'}`}
                  />
                </span>
              </button>
            </div>
            )}
          </div>
        </div>
        {/* Mobile Menu */}
        {!minimalNav && (
        <div
          className={`md:hidden bg-[#0a2d66] overflow-hidden shadow-sm ${mobileMenuOpen ? 'opacity-100' : 'opacity-0'}`}
          style={{
            transform: mobileMenuOpen ? 'translateY(0)' : 'translateY(-10px)',
            transitionProperty: 'transform, opacity, max-height',
            transitionTimingFunction: 'ease-in-out',
            transitionDuration: mobileMenuOpen ? '250ms' : '200ms',
            maxHeight: mobileMenuOpen ? '520px' : '0px'
          }}
        >
          <div className="px-4 pt-2 pb-3">
            {(menuItems || []).map((item, idx) => {
              const hasChildren = Array.isArray(item.children) && item.children.length > 0;
              const expanded = !!mobileExpanded[idx];
              const mobileRouteActive = pathname && item.route && item.route !== '#' && (item.route === '/' ? pathname === '/' : pathname.startsWith(item.route));
              return (
                <div key={idx} className="mb-0">
                  <div className={`flex items-center justify-between w-full ${hasChildren ? 'cursor-pointer' : ''}`}>
                    {hasChildren ? (
                      <button
                        onClick={() => handleMobileParentToggle(idx)}
                        className="w-full text-left px-3 py-3 text-white text-sm flex items-center justify-between"
                        aria-expanded={expanded}
                      >
                        <span className="truncate">{item.label}</span>
                        <svg className={`w-4 h-4 ml-2 transform transition-transform duration-200 ease-in-out ${expanded ? 'rotate-90' : 'rotate-0'}`} viewBox="0 0 20 20" fill="none" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 4l8 6-8 6" />
                        </svg>
                      </button>
                    ) : (
                      <button
                        onClick={() => handleMobileNavigate(item)}
                        className={`w-full text-left px-3 py-3 text-white text-sm ${mobileRouteActive ? 'bg-white/5 rounded' : ''}`}
                      >
                        {item.label}
                      </button>
                    )}
                  </div>
                  {/* Mobile children container: smooth ease-in expand with slight translate */}
                  {hasChildren && (
                    <div
                      className="pl-4 bg-white/5 overflow-hidden"
                      style={{
                        maxHeight: expanded ? `${item.children.length * 44}px` : '0px',
                        opacity: expanded ? 1 : 0,
                        transform: expanded ? 'translateY(0)' : 'translateY(-6px)',
                        transition: 'max-height 220ms ease-in, opacity 200ms ease-in, transform 220ms ease-in',
                        pointerEvents: expanded ? 'auto' : 'none'
                      }}
                    >
                      {(item.children || []).map((child, cidx) => {
                        const childActive = pathname && child.route && pathname.startsWith(child.route);
                        return (
                          <button
                            key={cidx}
                            onClick={() => handleMobileNavigate(child)}
                            className={`w-full text-left block px-3 py-2 text-sm ${childActive ? 'bg-white/5 rounded text-white' : 'text-white/95'}`}
                            style={{ transition: 'opacity 180ms ease-in-out', transitionDelay: `${(cidx + 1) * 40}ms` }}
                          >
                            {child.label}
                          </button>
                        );
                      })}
                    </div>
                  )}
                  <div className="border-t border-white/10" />
                </div>
              );
            })}
          </div>
        </div>
        )}
      </nav>
      <ChangePasswordModal 
        show={showChangePasswordModal} 
        onClose={() => setShowChangePasswordModal(false)}
        apiEndpoint={
            effectiveRole === 'student' ? '/api/auth/change-password/student' :
            effectiveRole.startsWith('clerk') ? '/api/auth/change-password/clerk' : ''
          }
      />
    </>
  );
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import Link from 'next/link';
import { useStudent } from '@/context/StudentContext';
import useProfileActivity from '@/hooks/student/useProfileActivity';

export default function NotificationDropdown({ onOpenChange }) {
  const { studentData } = useStudent();
  const activity = useProfileActivity();
  const { latestRequest, dismissCount, dismiss } = activity;
  const isProd = typeof process !== 'undefined' ? process.env.NODE_ENV === 'production' : true;
  
  const [localVisible, setLocalVisible] = useState(true);
  const [notifOpen, setNotifOpen] = useState(false);
  const dropdownRef = useRef(null);

  const showRequestNotif = !!latestRequest && localVisible && !(latestRequest && dismissCount >= 4 && isProd);

  useEffect(() => {
    onOpenChange?.(notifOpen);
  }, [notifOpen, onOpenChange]);

  useEffect(() => {
    function handleClickOutside(event) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setNotifOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const notifications = [];
  if (showRequestNotif) {
    const status = (latestRequest?.status || '').toUpperCase();
    const type = latestRequest?.certificate_type || latestRequest?.type || 'Certificate';
    notifications.push({
      id: latestRequest.request_id || latestRequest.id,
      title: `${type} Request ${status.charAt(0) + status.slice(1).toLowerCase()}`,
      desc: status === 'APPROVED' ? 'Your request has been processed and is ready.' : 
            status === 'REJECTED' ? 'Your request was declined.' : 
            'Your request is currently under review.',
      time: 'Update',
      link: `/student/requests/certificates?request_id=${latestRequest.request_id || ''}&scroll=history`,
      type: status === 'APPROVED' ? 'success' : status === 'REJECTED' ? 'error' : 'info'
    });
  }

  const handleDismiss = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setLocalVisible(false);
    if (typeof dismiss === 'function') dismiss();
  };

  return (
    <div className="relative" ref={dropdownRef}>
      <button 
        onClick={() => setNotifOpen(!notifOpen)}
        className={`p-2 transition-colors rounded-xl relative group ${
          notifOpen 
            ? 'text-white bg-white/10' 
            : 'text-blue-100/60 hover:text-white hover:bg-white/5'
        }`}
      >
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
