'use client';

import { useEffect, useRef, useContext, useCallback, useState } from 'react';
import { createClient } from '@supabase/supabase-js';
import { io } from 'socket.io-client';
import toast from 'react-hot-toast';
import { StudentContext } from '@/context/StudentContext';
import { ClerkContext } from '@/context/ClerkContext';

// Shared state for all instances of RealtimeListener
let sharedSupabaseClient = null;
let sharedSupabaseChannel = null;
let sharedSocket = null;
let sharedStatus = 'connecting';
let lastActivity = Date.now();
let heartbeatInterval = null;
const statusSubscribers = new Set();
const eventSubscribers = new Set();

function notifyStatus(status) {
  sharedStatus = status;
  statusSubscribers.forEach((subscriber) => {
    try {
      subscriber(status);
    } catch (error) {
      console.error('Realtime status subscriber error', error);
    }
  });
}

function notifyEvent(event) {
  eventSubscribers.forEach((subscriber) => {
    try {
      subscriber(event);
    } catch (error) {
      console.error('Realtime event subscriber error', error);
    }
  });
}

/**
 * Strategy A: VPS Mode (Socket.io)
 */
function ensureSocketConnection() {
  const socketUrl = process.env.NEXT_PUBLIC_SOCKET_URL;
  if (!socketUrl || sharedSocket || typeof window === 'undefined') return;

  const isLocal = socketUrl.includes('localhost') || socketUrl.includes('127.0.0.1');
  const isDev = process.env.NODE_ENV === 'development';

  if (!isLocal) {
    // console.info('🔌 [Socket.io] Connecting to', socketUrl);
  }
  
  sharedSocket = io(socketUrl, {
    transports: ['websocket'],
    reconnectionAttempts: isDev ? 1 : 5, // Minimal attempts in dev
    timeout: 3000,
    autoConnect: true
  });

  sharedSocket.on('connect', () => {
    // console.info('✅ [Socket.io] Connected');
    notifyStatus('connected');
  });

  sharedSocket.on('live-session-update', (data) => {
    notifyEvent({ type: data.type, payload: data });
  });

  sharedSocket.on('connect_error', (err) => {
    // Suppress logs for local failures to keep console clean
    if (!isLocal) {
      // console.warn('⚠️ [Realtime] Socket.io Error:', err.message);
    }
    notifyStatus('error');
  });

  sharedSocket.on('disconnect', () => {
    notifyStatus('disconnected');
  });
}

/**
 * Strategy B: Cloud Mode (Supabase)
 */
function getSharedSupabaseClient() {
  if (sharedSupabaseClient) return sharedSupabaseClient;

  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
  
  // Allow Supabase if Socket.io is not connected
  const isSocketActive = sharedSocket && sharedSocket.connected;
  if (!url || !key || typeof window === 'undefined' || isSocketActive) return null;

  sharedSupabaseClient = createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  return sharedSupabaseClient;
}

function startSupabaseHeartbeat() {
  if (heartbeatInterval) return;
  
  heartbeatInterval = setInterval(() => {
    if (!sharedSupabaseChannel) return;
    
    // 1. Send Ping to self and others to verify channel health
    sharedSupabaseChannel.send({
      type: 'broadcast',
      event: 'PING',
      payload: { timestamp: Date.now() }
    }).catch(() => { /* empty */ });
    
    // 2. Check for Zombie State (No activity for 35s)
    const silentPeriod = Date.now() - lastActivity;
    if (silentPeriod > 35000) {
      // console.warn(`🧟 [Realtime] Zombie connection detected (${Math.round(silentPeriod/1000)}s silence). Forcing recovery...`);
      recoverSupabaseConnection();
    }
  }, 30000);
}

function recoverSupabaseConnection() {
  if (sharedSupabaseChannel) {
    // console.info('🔄 [Realtime] Re-subscribing to Supabase channel...');
    sharedSupabaseChannel.unsubscribe();
    sharedSupabaseChannel = null;
  }
  ensureSupabaseChannel();
}

function ensureSupabaseChannel() {
  const supabase = getSharedSupabaseClient();
  const isSocketActive = sharedSocket && (sharedSocket.connected || sharedStatus === 'connected');
  
  if (!supabase || isSocketActive || sharedSupabaseChannel) return;

  sharedSupabaseChannel = supabase.channel('kucet-updates', {
    config: { broadcast: { self: true } }, // self: true allows us to see our own pings back
  });

  sharedSupabaseChannel
    .on('broadcast', { event: '*' }, ({ event, payload }) => {
      lastActivity = Date.now(); // Update on any activity
      
      // Ignore internal PINGs for UI updates
      if (event !== 'PING') {
        notifyEvent({ type: event, payload });
      }
    })
    .subscribe((status) => {
      // Only set status if socket isn't already taking precedence
      if (!sharedSocket || !sharedSocket.connected) {
        if (status === 'SUBSCRIBED') {
          lastActivity = Date.now();
          notifyStatus('connected');
          startSupabaseHeartbeat();
        } else {
          notifyStatus(status);
        }
      }
    });
}

export default function RealtimeListener({ onUpdate, enableNotifications = false }) {
  const { studentData } = useContext(StudentContext) || { /* empty */ };
  const { clerkData } = useContext(ClerkContext) || { /* empty */ };
  
  const studentDataRef = useRef(studentData);
  const clerkDataRef = useRef(clerkData);
  const [status, setStatus] = useState(sharedStatus);

  useEffect(() => {
    studentDataRef.current = studentData;
    clerkDataRef.current = clerkData;
  }, [studentData, clerkData]);

  const handleNotification = useCallback((event, payload) => {
    const sData = studentDataRef.current;
    const cData = clerkDataRef.current;

    // console.info('📡 [Realtime Event]', event, payload);

    if (event === 'TIMETABLE_CHANGED') {
      if (sData?.branch === payload.branch) {
        toast.success('Your timetable has been updated!', { id: 'timetable-update' });
      }
    }

    if (event === 'SESSION_STARTED') {
      if (sData?.branch === payload.branch) {
        toast('🚀 New Attendance Session Started!', { icon: '📝', duration: 10000, id: payload.sessionId });
      }
    }

    if (event === 'REQUEST_CREATED' || event === 'REQUEST_UPDATED') {
      if (cData && payload.clerkType === cData.role) {
         toast(`New request: ${payload.certificate_type}`, { icon: '🔔' });
      }
      if (sData && payload.student_id === sData.id) {
         toast(`Request status updated: ${payload.certificate_type}`, { icon: '📄' });
      }
    }
  }, []);

  useEffect(() => {
    const statusHandler = (nextStatus) => setStatus(nextStatus);
    const eventHandler = ({ type, payload }) => {
      if (typeof onUpdate === 'function') onUpdate({ type, payload });
      if (enableNotifications) handleNotification(type, payload || { /* empty */ });
    };

    statusSubscribers.add(statusHandler);
    eventSubscribers.add(eventHandler);
    
    // Initialize primary or secondary strategy
    const socketUrl = process.env.NEXT_PUBLIC_SOCKET_URL;
    const isLocal = socketUrl?.includes('localhost') || socketUrl?.includes('127.0.0.1');
    const isDev = process.env.NODE_ENV === 'development';

    // Strategy: Skip Socket.io on localhost in Dev if Supabase is available
    // to avoid persistent connection failure errors in the console.
    const hasSupabase = !!(process.env.NEXT_PUBLIC_SUPABASE_URL && process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY);
    const shouldSkipSocket = isDev && isLocal && hasSupabase;
    
    if (socketUrl && !shouldSkipSocket) {
      ensureSocketConnection();
      
      // Secondary fallback logic: if socket is still connecting after 5 seconds, 
      // check if we should enable Supabase as a backup.
      // But avoid dual connections.
      const fallbackTimer = setTimeout(() => {
        if (sharedStatus !== 'connected' && sharedStatus !== 'error') {
          // console.info('⚠️ [Realtime] Socket.io taking too long, checking Supabase availability...');
          ensureSupabaseChannel();
        }
      }, 5000);
      
      return () => {
        clearTimeout(fallbackTimer);
        statusSubscribers.delete(statusHandler);
        eventSubscribers.delete(eventHandler);
      };
    } else {
      // In Dev/Local or if no Socket URL, go straight to Supabase
      if (shouldSkipSocket) {
        // console.info('🚀 [Realtime] Dev Mode: Prioritizing Supabase over local Socket.io');
      }
      ensureSupabaseChannel();
      return () => {
        statusSubscribers.delete(statusHandler);
        eventSubscribers.delete(eventHandler);
      };
    }
  }, [enableNotifications, handleNotification, onUpdate]);

  return null;
}

'use client';
import { useEffect } from 'react';
import toast from 'react-hot-toast';

export default function SearchParamToast({ serverError }) {
  useEffect(() => {
    const error = serverError;
    if (!error) return;

    switch (error) {
      case 'ClerkNotFound':
        toast.error('This email is not registered as an employee.');
        break;
      case 'ClerkInactive':
        toast.error('Your employee account is inactive. Please contact support.');
        break;
      case 'GoogleAuthError':
        toast.error('Google authentication failed. Please try again.');
        break;
      default:
        toast.error('An unknown authentication error occurred.');
        break;
    }

    try {
      const url = new URL(window.location.href);
      url.searchParams.delete('error');
      window.history.replaceState({ /* empty */ }, document.title, url.pathname + url.search);
    } catch (e) {
      // ignore
    }
  }, [serverError]);

  return null;
}

import React, { useState } from 'react';
import { Lock, Shield, Check, X, AlertCircle, Wand2, Copy, Share2 } from 'lucide-react';
import toast from 'react-hot-toast';
import { generateStrongPassword } from '@/lib/security';

const SetPasswordModal = ({ rollno, email, onPasswordSet }) => {
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordSaving, setPasswordSaving] = useState(false);

  const handlePasswordSave = async () => {
    if (newPassword !== confirmPassword) {
      toast.error('Passwords do not match');
      return;
    }
    if (newPassword.length < 8) {
      toast.error('Password must be at least 8 characters long');
      return;
    }
    
    setPasswordSaving(true);
    try {
      const res = await fetch('/api/student/set-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rollno, password: newPassword }),
      });
      const data = await res.json();
      if (res.ok) {
        toast.success('Password set successfully!');
        if (onPasswordSet) onPasswordSet();
      } else {
        toast.error(data.error || 'Failed to set password');
      }
    } catch (e) {
      toast.error('Network error');
    } finally {
      setPasswordSaving(false);
    }
  };

  const handleGeneratePassword = () => {
    const pw = generateStrongPassword();
    setNewPassword(pw);
    setConfirmPassword(pw);
    toast.success('Strong password generated!');
  };

  const copyToClipboard = () => {
    if (!newPassword) return;
    navigator.clipboard.writeText(newPassword);
    toast.success('Password copied to clipboard!');
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden border border-slate-100">
        <div className="bg-[#0b3578] p-6 text-white text-center relative">
          <div className="absolute top-0 left-0 w-full h-full opacity-10" style={{ backgroundImage: 'radial-gradient(circle at 20% 20%, white 0%, transparent 40%)' }} />
          <Shield className="mx-auto mb-3 opacity-80" size={32} />
          <h2 className="text-xl font-bold tracking-tight uppercase">Secure Your Account</h2>
          <p className="text-blue-100 text-xs mt-1 uppercase tracking-widest font-medium">Create a personal password</p>
        </div>

        <div className="p-8 space-y-6">
          <div className="flex items-center justify-between">
            <div className="bg-blue-50 border border-blue-100 p-3 rounded-xl flex gap-3 flex-1">
              <AlertCircle className="text-blue-600 shrink-0" size={18} />
              <p className="text-[10px] text-blue-800 leading-relaxed font-medium">
                Set a strong personal password to replace your temporary DOB password.
              </p>
            </div>
            <button 
              onClick={handleGeneratePassword}
              className="ml-3 p-3 bg-slate-50 text-[#0b3578] rounded-xl border border-slate-200 hover:bg-slate-100 transition-all group"
              title="Generate Strong Password"
            >
              <Wand2 size={20} className="group-hover:rotate-12 transition-transform" />
            </button>
          </div>

          <div className="space-y-4">
            <div className="space-y-1">
              <div className="flex items-center justify-between px-1">
                <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest">New Password</label>
                {newPassword && (
                  <button onClick={copyToClipboard} className="text-[#0b3578] hover:underline text-[9px] font-bold uppercase flex items-center gap-1">
                    <Copy size={12} /> Copy
                  </button>
                )}
              </div>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"><Lock size={16} /></span>
                <input 
                  type="password"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  placeholder="••••••••"
                  className="w-full border border-slate-200 rounded-xl pl-10 pr-4 py-3 text-sm focus:ring-2 focus:ring-[#0b3578]/20 focus:border-[#0b3578] outline-none transition-all"
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest">Confirm Password</label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"><Check size={16} /></span>
                <input 
                  type="password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder="••••••••"
                  className="w-full border border-slate-200 rounded-xl pl-10 pr-4 py-3 text-sm focus:ring-2 focus:ring-[#0b3578]/20 focus:border-[#0b3578] outline-none transition-all"
                />
              </div>
            </div>
          </div>

          {newPassword && (
            <div className="p-3 bg-emerald-50 border border-emerald-100 rounded-xl flex gap-3 animate-slideDown">
              <Share2 className="text-emerald-600 shrink-0" size={18} />
              <p className="text-[10px] text-emerald-800 leading-relaxed font-medium">
                <strong className="uppercase">Save Password:</strong> Please copy and save this password in your <span className="font-bold">WhatsApp</span> or a safe place before saving.
              </p>
            </div>
          )}

          <div className="space-y-3 pt-2">
            <button
              onClick={handlePasswordSave}
              disabled={passwordSaving || !newPassword || newPassword !== confirmPassword || newPassword.length < 8}
              className="w-full py-3 bg-[#0b3578] text-white rounded-xl font-bold uppercase tracking-[0.15em] text-xs hover:bg-[#0a2d66] disabled:bg-slate-100 disabled:text-slate-400 transition-all shadow-lg shadow-blue-900/20"
            >
              {passwordSaving ? 'Saving Credentials...' : 'Set Password'}
            </button>
            <p className="text-[10px] text-center text-slate-400 uppercase font-medium tracking-tighter">
              Password must be at least 8 characters long.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

