'use client';

import { useContext, useState, useRef, useEffect } from 'react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { NAV_MENU_CONFIG } from '@/lib/menu-config';
import { ClerkContext } from '@/context/ClerkContext';
import { StudentContext } from '@/context/StudentContext';
import { Home, User, Book, Calendar, FileText, Settings, LogOut, Plus, Wallet, ChevronDown } from 'lucide-react';

const ICON_MAP = {
  'HOME': Home,
  'PROFILE': User,
  'ACADEMICS': Book,
  'FINANCES': Wallet,
  'TIME TABLE': Calendar,
  'REQUESTS': FileText,
  'DASHBOARD': Home,
  'DEPARTMENTS': FileText,
  'FACULTIES': User,
  'MENU': Settings,
  'ATTENDANCE': Book,
  'MARKS': FileText,
  'MATERIALS': Book,
};

export default function Sidebar({ role: initialRole = 'student', isMobileOpen = false, setIsMobileOpen = () => { /* empty */ }, onLogout }) {
  const pathname = usePathname();
  const router = useRouter();
  const clerkContext = useContext(ClerkContext);
  const studentContext = useContext(StudentContext);
  const clerkData = clerkContext?.clerkData;
  const studentData = studentContext?.studentData;
  const isClerkLoading = clerkContext?.loading;
  
  const [expanded, setExpanded] = useState(false);
  const [mobileExpanded, setMobileExpanded] = useState({ /* empty */ });
  const [desktopExpanded, setDesktopExpanded] = useState({ /* empty */ });

  // Determine effective role for menu mapping
  let role = initialRole;
  if (role === 'clerk' && clerkData?.role) {
    if (clerkData.role === 'admission') role = 'clerkAdmission';
    else if (clerkData.role === 'scholarship') role = 'clerkScholarship';
    else if (clerkData.role === 'faculty') role = 'faculty';
  }

  const menu = (role === 'clerk' && isClerkLoading) ? [] : (NAV_MENU_CONFIG[role] || NAV_MENU_CONFIG['student'] || []);

  // Estimate expanded width based on the longest visible label
  const computeMaxLabelLength = () => {
    let maxLen = 0;

    const register = (label) => {
      if (!label) return;
      const len = String(label).length;
      if (len > maxLen) maxLen = len;
    };

    menu.forEach((item) => {
      let baseLabel = item.label || '';
      if (role === 'student' && item.label === 'HOME') baseLabel = 'DASHBOARD';
      if (role === 'student' && item.label === 'MENU') baseLabel = 'SETTINGS';
      register(baseLabel);

      if (Array.isArray(item.children)) {
        item.children.forEach((child) => register(child.label));
      }
    });

    register('Logout');
    return maxLen || 0;
  };

  const maxLabelLength = computeMaxLabelLength();
  const estimatedLabelWidth = maxLabelLength * 7.5; // px estimate per character for 13px uppercase
  const BASE_EXPANDED_WIDTH = 208; // ~13rem, previous fixed w-52
  const TEXT_AREA_BASE = 144; // approximate space available for text at base width
  const extraWidth = Math.max(0, estimatedLabelWidth - TEXT_AREA_BASE);
  const expandedWidthPx = Math.min(260, BASE_EXPANDED_WIDTH + extraWidth);

  const isActiveRoute = (route) => {
    if (!route || !pathname) return false;
    // Root routes must match exactly to avoid over-highlighting
    if (route === '/') return pathname === '/';
    if (route === '/student') return pathname === '/student';
    return pathname.startsWith(route);
  };

  const performAction = async (action) => {
    if (!action) return;
    if (action === 'logout') {
      // Allow parent to override logout behaviour
      if (role === 'student' && typeof onLogout === 'function') {
        try { await onLogout(); return; } catch (e) { /* empty */ }
      }
      try {
        const endpoint = role === 'student' ? '/api/student/logout' : (role && String(role).startsWith('clerk') ? '/api/clerk/logout' : '/api/auth/logout');
        await fetch(endpoint, { method: 'POST' });
      } catch (e) { /* empty */ }
      try { localStorage.removeItem('logged_in_student'); } catch (e) { /* empty */ }
      try { sessionStorage.clear(); } catch (e) { /* empty */ }
      window.location.replace('/');
      return;
    }
    if (action === 'change-password') {
      if (role === 'student') { router.push('/student/settings/security'); return; }
      if (role && String(role).startsWith('clerk')) { router.push('/clerk/settings/security'); return; }
      router.push('/settings/security');
    }
  };

  // Desktop rail
  const headerVar = 'var(--site-header-height, 72px)';
  const [hasOverflow, setHasOverflow] = useState(false);
  const [atScrollBottom, setAtScrollBottom] = useState(false);
  const desktopScrollRef = useRef(null);

  useEffect(() => {
    const el = desktopScrollRef.current;
    if (!el) return;

    const handleScroll = () => {
      const has = el.scrollHeight > el.clientHeight + 1;
      setHasOverflow(has);
      const atBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - 1;
      setAtScrollBottom(atBottom);
    };

    handleScroll();
    el.addEventListener('scroll', handleScroll);
    return () => el.removeEventListener('scroll', handleScroll);
  }, [menu.length, expanded]);

  const DesktopNav = (
    <aside
      onMouseEnter={() => setExpanded(true)}
      onMouseLeave={() => setExpanded(false)}
      style={{
        top: `${headerVar}`,
        height: `calc(100vh - ${headerVar})`,
        left: 0,
        width: expanded ? `${expandedWidthPx}px` : '4rem',
        transition: 'width 250ms ease'
      }}
      className="hidden lg:flex fixed left-0 z-40 bg-[#0A3D91] backdrop-blur-md border border-[#0a2f6b]/70 rounded-r-2xl overflow-hidden"
      aria-hidden={false}
    >
      <div className="flex flex-col h-full text-slate-100">
        <div
          ref={desktopScrollRef}
          className="flex-1 overflow-y-auto overflow-x-hidden px-3 py-4 pr-2 pb-24 relative scrollbar-hide"
        >
          <div
            className={`px-2 pb-3 text-[10px] font-semibold uppercase tracking-[0.22em] text-slate-300 transition-opacity ${
              expanded ? 'opacity-100' : 'opacity-0 pointer-events-none'
            }`}
          >
            Overview
          </div>

          <nav className="space-y-1.5 pr-1">
        {menu.map((item, idx) => {
          const Icon = ICON_MAP[item.label] || FileText;
          const isStudentDashboard = role === 'student' && item.label === 'HOME';
          const isStudentSettings = role === 'student' && item.label === 'MENU';
          const displayLabel = isStudentDashboard ? 'DASHBOARD' : (isStudentSettings ? 'SETTINGS' : item.label);
          const selfActive = item.route && isActiveRoute(item.route);
          const childActive = Array.isArray(item.children) && item.children.some(c => c.route && isActiveRoute(c.route));
          const active = !!(selfActive || childActive);

          // fixed icon column to avoid any horizontal shift
          const IconBlock = (
            <div
              className="flex-shrink-0 flex items-center"
              style={{ width: 36, minWidth: 36 }}
            >
              <div
                className={`w-9 h-9 flex items-center justify-center rounded-xl transition-colors ${
                  active ? 'bg-white/20 text-white' : 'bg-white/10 text-slate-200 group-hover:bg-white/20 group-hover:text-white'
                }`}
              >
                <Icon size={16} />
              </div>
            </div>
          );

          const LabelBlock = (
            <div
              className={`ml-1 truncate text-[13px] font-semibold leading-tight tracking-tight transform transition-all duration-200 ${
                expanded ? 'max-w-[220px] opacity-100 translate-x-0' : 'max-w-0 opacity-0 -translate-x-2 pointer-events-none'
              } ${active ? 'text-white' : 'text-slate-200'} group-hover:text-white`}
            >
              {displayLabel}
            </div>
          );

          // Parent with children: show parent row; children expand only when arrow button/row is clicked
          if (item.children) {
            const open = !!desktopExpanded[idx];
            return (
              <div key={idx}>
                <button
                  type="button"
                  onClick={() => setDesktopExpanded(prev => ({ ...prev, [idx]: !prev[idx] }))}
                  className={`group w-full flex items-center gap-3 py-2 rounded-xl ${
                    expanded ? 'justify-between px-2' : 'justify-start px-2'
                  } ${
                    open || active ? 'bg-white/10' : 'hover:bg-white/5'
                  } transition-colors`}
                >
                  <div className="flex items-center gap-1.5">
                    {IconBlock}
                    {LabelBlock}
                  </div>
                  {expanded && (
                    <div
                      className="flex-shrink-0 flex items-center"
                      style={{ width: 36, minWidth: 36 }}
                    >
                      <div
                        className={`w-9 h-9 flex items-center justify-center rounded-xl transition-colors transform transition-transform duration-200 ${
                          open ? 'rotate-90' : 'rotate-0'
                        } ${
                          open || active
                            ? 'bg-white/20 text-white'
                            : 'bg-white/10 text-slate-200 group-hover:bg-white/20 group-hover:text-white'
                        }`}
                      >
                        <ChevronDown size={16} />
                      </div>
                    </div>
                  )}
                </button>
                {expanded && open && (
                  <div className="ml-9 mt-1.5 space-y-1 border-l border-white/10 pl-3">
                    {item.children.map((c, ci) => {
                      const childIsActive = c.route && isActiveRoute(c.route);
                      if (c.action) {
                        return (
                          <button
                            key={ci}
                            onClick={() => performAction(c.action)}
                            className={`w-full text-left px-2 py-1.5 text-[12px] font-medium rounded-lg transition-colors ${
                              childIsActive ? 'bg-white/10 text-white' : 'text-slate-200 hover:bg-white/5'
                            }`}
                          >
                            {c.label}
                          </button>
                        );
                      }
                      if (c.route) {
                        return (
                          <Link
                            key={ci}
                            href={c.route}
                            className={`block px-2 py-1.5 text-[12px] font-medium rounded-lg transition-colors ${
                              childIsActive ? 'bg-white/10 text-white' : 'text-slate-200 hover:bg-white/5'
                            }`}
                          >
                            {c.label}
                          </Link>
                        );
                      }
                      return (
                        <div key={ci} className="px-2 py-1.5 text-[12px] text-slate-400">
                          {c.label}
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          }

          // Action items (direct)
          if (item.action) {
            return (
              <button key={idx} onClick={() => performAction(item.action)} className="group w-full p-0 rounded-md">
                <div
                  className={`flex items-center gap-2 px-2 py-2 rounded-xl transition-colors ${
                    active ? 'bg-white/10' : 'hover:bg-white/5'
                  }`}
                >
                  {IconBlock}
                  {LabelBlock}
                </div>
              </button>
            );
          }

          // Normal route link
          return (
            <Link key={idx} href={item.route || '#'} className="group block p-0 rounded-md">
              <div
                className={`flex items-center gap-2 px-2 py-2 rounded-xl transition-colors ${
                  active ? 'bg-white/10' : 'hover:bg-white/5'
                }`}
              >
                  {IconBlock}
                  {LabelBlock}
                </div>
            </Link>
          );
        })}
          </nav>

          {!expanded && hasOverflow && (
            <div
              className={`pointer-events-none sticky bottom-1 flex justify-center transition-opacity duration-200 ${
                atScrollBottom ? 'opacity-0' : 'opacity-80'
              }`}
            >
              <div className="flex items-center justify-center w-6 h-6 rounded-full bg-white/20 text-white">
                <ChevronDown size={14} />
              </div>
            </div>
          )}
        </div>

        {/* Logout Button */}
        <div className={`absolute bottom-4 left-0 right-0 border-t border-white/15 ${expanded ? 'px-2 pt-4' : 'p-2'} flex items-center justify-center gap-2`}>
          <button
            type="button"
            onClick={() => performAction('logout')}
            title="Logout"
            className="group w-12 h-12 flex items-center justify-center rounded-full text-white bg-red-500 hover:bg-red-600 transition-all"
          >
            <LogOut size={30} />
          </button>
          {expanded && <span className="text-sm font-semibold text-white">Logout</span>}
        </div>
      </div>
    </aside>
  );


  const MobileNav = (
    <aside
      className={`lg:hidden fixed left-0 z-50 transform ${isMobileOpen ? 'translate-x-0' : '-translate-x-full'} transition-transform duration-300`}
      style={{ top: 0, height: '100vh' }}
    >
      <div className="w-72 h-full bg-white border-r border-slate-200">
        <div className="p-4 flex items-center justify-between">
          <div className="text-lg font-bold">Menu</div>
          <button onClick={() => setIsMobileOpen(false)} className="p-2">
            ✕
          </button>
        </div>
        <nav className="px-2 py-2">
          {menu.map((item, idx) => {
            const Icon = ICON_MAP[item.label] || FileText;
            const selfActive = item.route && isActiveRoute(item.route);
            const childActive = Array.isArray(item.children) && item.children.some(c => c.route && isActiveRoute(c.route));
            const active = !!(selfActive || childActive);

            if (item.children) {
              const open = !!mobileExpanded[idx];
              return (
                <div key={idx} className="my-1">
                  <button
                    onClick={() => setMobileExpanded(prev => ({ ...prev, [idx]: !prev[idx] }))}
                    className={`w-full flex items-center gap-3 p-2 rounded-md ${active ? 'bg-slate-100' : 'hover:bg-slate-50'}`}
                  >
                    <Icon size={18} />
                    <div className="text-sm text-slate-700 flex-1 text-left">{item.label}</div>
                    <svg className={`w-4 h-4 transform transition-transform ${open ? 'rotate-90' : 'rotate-0'}`} viewBox="0 0 20 20" fill="none" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 4l8 6-8 6" /></svg>
                  </button>
                  <div className={`pl-8 overflow-hidden transition-all ${open ? 'max-h-96 opacity-100' : 'max-h-0 opacity-0'} `}>
                    {item.children.map((c, ci) => {
                      const childIsActive = c.route && isActiveRoute(c.route);
                      if (c.action) {
                        return (
                          <button
                            key={ci}
                            onClick={() => { setIsMobileOpen(false); performAction(c.action); }}
                            className={`w-full text-left block px-2 py-2 rounded-md text-sm transition-colors ${childIsActive ? 'bg-blue-50 text-[#0b3578] font-semibold' : 'text-slate-600 hover:bg-slate-50'}`}
                          >
                            {c.label}
                          </button>
                        );
                      }
                      if (c.route) {
                        return (
                          <Link
                            key={ci}
                            href={c.route}
                            onClick={() => setIsMobileOpen(false)}
                            className={`block px-2 py-2 rounded-md text-sm transition-colors ${childIsActive ? 'bg-blue-50 text-[#0b3578] font-semibold' : 'text-slate-600 hover:bg-slate-50'}`}
                          >
                            {c.label}
                          </Link>
                        );
                      }
                      return (
                        <div key={ci} className="px-2 py-2 text-sm text-slate-600">
                          {c.label}
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            }

            if (item.action) {
              return (
                <button key={idx} onClick={() => { setIsMobileOpen(false); performAction(item.action); }} className={`w-full my-1 p-2 rounded-md text-left ${active ? 'bg-slate-100' : 'hover:bg-slate-50'}`}>
                  <div className="flex items-center gap-3">
                    <Icon size={18} />
                    <div className="text-sm text-slate-700">{item.label}</div>
                  </div>
                </button>
              );
            }

            return (
              <Link key={idx} href={item.route || '#'} onClick={() => setIsMobileOpen(false)} className={`block my-1 p-2 rounded-md ${active ? 'bg-slate-100' : 'hover:bg-slate-50'}`}>
                <div className="flex items-center gap-3">
                  <Icon size={18} />
                  <div className="text-sm text-slate-700">{item.label}</div>
                </div>
              </Link>
            );
          })}
        </nav>
      </div>
    </aside>
  );

  return (
    <>
      {DesktopNav}
      {MobileNav}
    </>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import { formatDate } from '@/lib/date';

export default function BackupManager() {
  const [backups, setBackups] = useState([]);
  const [loading, setLoading] = useState(true);
  const [triggering, setTriggering] = useState(false);
  const [restoreModal, setRestoreModal] = useState(null); // stores the backup to restore
  const [restoring, setRestoring] = useState(false);
  const [confirmString, setConfirmString] = useState('');

  const fetchBackups = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/admin/infrastructure/backups');
      const data = await res.json();
      if (res.ok) {
        setBackups(data.backups);
      } else {
        toast.error('Failed to load backups');
      }
    } catch (error) {
      toast.error('Connection error while fetching backups');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let isMounted = true;
    const load = async () => {
      if (isMounted) await fetchBackups();
    };
    load();
    return () => { isMounted = false; };
  }, []);

  const handleManualBackup = async () => {
    if (!confirm('This will generate a full database dump and upload it to Cloudinary. Proceed?')) return;
    
    setTriggering(true);
    const toastId = toast.loading('Generating system-wide backup...');
    try {
      const res = await fetch('/api/admin/infrastructure/backups', { method: 'POST' });
      const data = await res.json();
      if (res.ok) {
        toast.success('Manual backup successfully completed.', { id: toastId });
        fetchBackups();
      } else {
        toast.error(`Backup failed: ${data.message || 'Unknown error'}`, { id: toastId });
      }
    } catch (error) {
      toast.error('Failed to trigger backup execution.', { id: toastId });
    } finally {
      setTriggering(false);
    }
  };

  const handleRestore = async () => {
    if (!restoreModal) return;
    
    setRestoring(true);
    const toastId = toast.loading(`Restoring system to ${restoreModal.name}...`);
    try {
      const res = await fetch('/api/admin/infrastructure/backups/restore', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ filename: restoreModal.name })
      });
      const data = await res.json();
      if (res.ok) {
        toast.success('Database successfully restored. System re-initialized.', { id: toastId });
        setRestoreModal(null);
      } else {
        toast.error(`Restoration failed: ${data.message || 'Unknown error'}`, { id: toastId });
      }
    } catch (error) {
      toast.error('Critical error during restoration pipe.', { id: toastId });
    } finally {
      setRestoring(false);
    }
  };

  const formatBytes = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      
      {/* Action Bar */}
      <div className="flex justify-between items-center bg-white p-6 border border-slate-200 shadow-sm rounded-sm">
        <div>
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">Database Control</h3>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Manual system snapshots and disaster recovery.</p>
        </div>
        <button
          onClick={handleManualBackup}
          disabled={triggering || loading}
          className="px-6 h-12 bg-slate-800 text-white text-[11px] font-black uppercase tracking-[0.2em] rounded-sm hover:bg-slate-900 transition-all shadow-md disabled:bg-slate-300 disabled:cursor-not-allowed flex items-center gap-3"
        >
          {triggering ? (
            <>
              <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
              <span>Executing Dump...</span>
            </>
          ) : (
            <span>Run Backup Now</span>
          )}
        </button>
      </div>

      {/* Backups List */}
      <div className="bg-white border border-slate-200 shadow-sm rounded-sm overflow-hidden">
        <div className="bg-slate-50 px-8 py-4 border-b border-slate-200">
           <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Cloud Storage History (kucet/backups)</span>
        </div>
        
        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="border-b border-slate-100 bg-white">
                <th className="px-8 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Filename / ID</th>
                <th className="px-8 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Timestamp</th>
                <th className="px-8 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">File Size</th>
                <th className="px-8 py-4 text-right text-[9px] font-black text-slate-400 uppercase tracking-widest">Operations</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {loading ? (
                <tr>
                  <td colSpan="4" className="px-8 py-20 text-center">
                    <div className="flex flex-col items-center gap-4">
                      <div className="w-10 h-10 border-4 border-slate-100 border-t-blue-600 rounded-full animate-spin"></div>
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Scanning cloud registry...</span>
                    </div>
                  </td>
                </tr>
              ) : backups.length === 0 ? (
                <tr>
                  <td colSpan="4" className="px-8 py-20 text-center text-slate-400 text-xs font-bold uppercase tracking-widest">No previous backups detected.</td>
                </tr>
              ) : (
                backups.map((b) => (
                  <tr key={b.name} className="hover:bg-slate-50 transition-colors">
                    <td className="px-8 py-5">
                      <div className="flex flex-col">
                        <span className="text-xs font-black text-slate-700">{b.name}</span>
                        <span className="text-[9px] font-mono text-slate-400 mt-1 uppercase">MD5: {b.etag}</span>
                      </div>
                    </td>
                    <td className="px-8 py-5">
                       <span className="text-xs font-bold text-slate-600">{formatDate(b.created_at)}</span>
                    </td>
                    <td className="px-8 py-5">
                       <span className="text-xs font-bold text-slate-600">{formatBytes(b.size)}</span>
                    </td>
                    <td className="px-8 py-5 text-right">
                       <div className="flex items-center justify-end gap-3">
                          <a
                            href={`/api/admin/infrastructure/backups/download/${b.name}`}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="px-4 py-2 border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-white hover:shadow-sm transition-all rounded-sm"
                          >
                            Download
                          </a>
                          <button
                            onClick={() => setRestoreModal(b)}
                            className="px-4 py-2 bg-rose-50 text-rose-700 border border-rose-100 text-[10px] font-black uppercase tracking-widest hover:bg-rose-600 hover:text-white transition-all rounded-sm"
                          >
                            Restore
                          </button>
                       </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Restore Confirmation Modal */}
      {restoreModal && (
        <div className="fixed inset-0 z-100 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white max-w-lg w-full shadow-2xl rounded-sm overflow-hidden border border-rose-200 animate-slideUp">
            <div className="p-8 space-y-6">
              <div className="flex items-center gap-4 text-rose-600">
                <div className="w-12 h-12 bg-rose-50 rounded-full flex items-center justify-center">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                  </svg>
                </div>
                <h3 className="text-xl font-black uppercase tracking-tight">Critical Warning</h3>
              </div>

              <div className="space-y-4">
                <p className="text-sm font-bold text-slate-700 leading-relaxed">
                  You are about to restore the system to a previous state using:
                </p>
                <div className="bg-slate-50 p-4 border border-slate-200 rounded-sm">
                  <div className="text-xs font-black text-slate-800">{restoreModal.name}</div>
                  <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Generated: {formatDate(restoreModal.created_at)}</div>
                </div>

                <div className="space-y-2">
                   <label className="text-[10px] font-black text-rose-600 uppercase tracking-widest">Type &quot;RESTORE_DATABASE&quot; to confirm</label>
                   <input 
                     type="text" 
                     value={confirmString}
                     onChange={(e) => setConfirmString(e.target.value)}
                     className="w-full h-12 border-2 border-rose-100 rounded-sm px-4 text-sm font-bold outline-none focus:border-rose-500 transition-all uppercase"
                     placeholder="CONFIRMATION STRING"
                   />
                </div>

                <p className="text-xs font-medium text-slate-500 italic">
                  * This action will OVERWRITE all current database records. This cannot be undone.
                </p>
              </div>

              <div className="flex gap-4 pt-4 border-t border-slate-100">
                <button
                  disabled={restoring}
                  onClick={() => { setRestoreModal(null); setConfirmString(''); }}
                  className="flex-1 h-12 border border-slate-200 text-slate-600 text-[11px] font-black uppercase tracking-widest rounded-sm hover:bg-slate-50 transition-all disabled:opacity-50"
                >
                  Cancel
                </button>
                <button
                  disabled={restoring || confirmString !== 'RESTORE_DATABASE'}
                  onClick={handleRestore}
                  className="flex-2 h-12 bg-rose-600 text-white text-[11px] font-black uppercase tracking-[0.2em] rounded-sm hover:bg-rose-700 transition-all shadow-lg shadow-rose-600/20 flex items-center justify-center gap-3 disabled:bg-rose-300 disabled:shadow-none"
                >
                  {restoring ? (
                    <>
                      <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                      <span>Restoring...</span>
                    </>
                  ) : (
                    <span>Confirm Restore</span>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import toast from 'react-hot-toast';

export default function ConfigManager() {
  const [config, setConfig] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const fetchConfig = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/admin/infrastructure/config');
      const data = await res.json();
      if (res.ok) {
        setConfig(data.config);
      } else {
        toast.error('Failed to load institutional configuration');
      }
    } catch (error) {
      toast.error('Connection error while fetching settings');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let isMounted = true;
    (async () => {
      if (isMounted) await fetchConfig();
    })();
    return () => { isMounted = false; };
  }, []);

  const handleUpdate = async (e) => {
    e.preventDefault();
    setSaving(true);
    const toastId = toast.loading('Synchronizing institutional settings...');
    try {
      const res = await fetch('/api/admin/infrastructure/config', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(config)
      });
      if (res.ok) {
        toast.success('Institutional configuration updated successfully.', { id: toastId });
        fetchConfig();
      } else {
        toast.error('Failed to update configuration.', { id: toastId });
      }
    } catch (error) {
      toast.error('Critical error during synchronization.', { id: toastId });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-20 bg-white border border-slate-200 rounded-sm">
        <div className="w-10 h-10 border-4 border-slate-100 border-t-blue-600 rounded-full animate-spin"></div>
        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-4">Retrieving system registry...</span>
      </div>
    );
  }

  return (
    <form onSubmit={handleUpdate} className="space-y-8 animate-fadeIn">
      
      {/* 1. Core Identity */}
      <div className="bg-white border border-slate-200 shadow-sm rounded-sm overflow-hidden">
        <div className="bg-slate-50 px-8 py-4 border-b border-slate-200">
           <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Institutional Identity</span>
        </div>
        <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Full College Name</label>
            <input 
              type="text" 
              value={config.name || ''} 
              onChange={(e) => setConfig({...config, name: e.target.value})}
              className="w-full h-12 bg-slate-50 border border-slate-200 rounded-sm px-4 text-xs font-bold focus:border-blue-500 outline-none transition-all uppercase"
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Short Name / Abbreviation</label>
            <input 
              type="text" 
              value={config.short_name || ''} 
              onChange={(e) => setConfig({...config, short_name: e.target.value})}
              className="w-full h-12 bg-slate-50 border border-slate-200 rounded-sm px-4 text-xs font-bold focus:border-blue-500 outline-none transition-all uppercase"
            />
          </div>
          <div className="space-y-2 md:col-span-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Official Address</label>
            <textarea 
              rows="3"
              value={config.address || ''} 
              onChange={(e) => setConfig({...config, address: e.target.value})}
              className="w-full bg-slate-50 border border-slate-200 rounded-sm p-4 text-xs font-bold focus:border-blue-500 outline-none transition-all uppercase"
            />
          </div>
        </div>
      </div>

      {/* 2. Localization & Contact */}
      <div className="bg-white border border-slate-200 shadow-sm rounded-sm overflow-hidden">
        <div className="bg-slate-50 px-8 py-4 border-b border-slate-200">
           <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Localization & Reach</span>
        </div>
        <div className="p-8 grid grid-cols-1 md:grid-cols-3 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">City / Location</label>
            <input 
              type="text" 
              value={config.location || ''} 
              onChange={(e) => setConfig({...config, location: e.target.value})}
              className="w-full h-12 bg-slate-50 border border-slate-200 rounded-sm px-4 text-xs font-bold focus:border-blue-500 outline-none transition-all uppercase"
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Pincode</label>
            <input 
              type="text" 
              value={config.pincode || ''} 
              onChange={(e) => setConfig({...config, pincode: e.target.value})}
              className="w-full h-12 bg-slate-50 border border-slate-200 rounded-sm px-4 text-xs font-bold focus:border-blue-500 outline-none transition-all uppercase"
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Official Contact</label>
            <input 
              type="text" 
              value={config.contact || ''} 
              onChange={(e) => setConfig({...config, contact: e.target.value})}
              className="w-full h-12 bg-slate-50 border border-slate-200 rounded-sm px-4 text-xs font-bold focus:border-blue-500 outline-none transition-all uppercase"
            />
          </div>
        </div>
      </div>

      {/* 3. Entrance Codes (JSON) */}
      <div className="bg-white border border-slate-200 shadow-sm rounded-sm overflow-hidden">
        <div className="bg-slate-50 px-8 py-4 border-b border-slate-200">
           <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Institutional Entrance Codes</span>
        </div>
        <div className="p-8 grid grid-cols-1 md:grid-cols-3 gap-8">
           {['tgpgecet', 'tgeapcet', 'tgecet'].map(exam => (
             <div key={exam} className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{exam} Code</label>
                <input 
                  type="text" 
                  value={config.entrance_codes?.[exam] || ''} 
                  onChange={(e) => setConfig({
                    ...config, 
                    entrance_codes: { ...config.entrance_codes, [exam]: e.target.value }
                  })}
                  className="w-full h-12 bg-slate-50 border border-slate-200 rounded-sm px-4 text-xs font-bold focus:border-blue-500 outline-none transition-all uppercase"
                />
             </div>
           ))}
        </div>
      </div>

      {/* 4. Safety & Maintenance */}
      <div className="bg-rose-50 border border-rose-100 shadow-sm rounded-sm overflow-hidden">
        <div className="bg-rose-100 px-8 py-4 border-b border-rose-200 flex justify-between items-center">
           <span className="text-[10px] font-black text-rose-700 uppercase tracking-widest">System Governance</span>
           <span className="px-2 py-0.5 bg-rose-600 text-white text-[8px] font-black rounded-full uppercase tracking-tighter">High Privilege</span>
        </div>
        <div className="p-8 flex items-center justify-between">
           <div className="space-y-1">
             <p className="text-sm font-black text-slate-800 uppercase tracking-tight">Institutional Maintenance Mode</p>
             <p className="text-xs text-slate-500 font-medium">When active, the portal becomes read-only for students and staff. Only Super Admins can make modifications.</p>
           </div>
           <button
             type="button"
             onClick={() => setConfig({...config, maintenance_mode: !config.maintenance_mode})}
             className={`w-16 h-8 rounded-full p-1 transition-all duration-300 ${config.maintenance_mode ? 'bg-rose-600' : 'bg-slate-300'}`}
           >
             <div className={`w-6 h-6 bg-white rounded-full shadow-md transform transition-all duration-300 ${config.maintenance_mode ? 'translate-x-8' : 'translate-x-0'}`}></div>
           </button>
        </div>
      </div>

      {/* Save Button */}
      <div className="flex justify-end pt-4">
         <button
           type="submit"
           disabled={saving}
           className="px-10 h-14 bg-slate-800 text-white text-xs font-black uppercase tracking-[0.2em] rounded-sm hover:bg-slate-900 transition-all shadow-xl disabled:bg-slate-300 flex items-center gap-4"
         >
           {saving ? (
             <>
               <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
               <span>Updating System...</span>
             </>
           ) : (
             <span>Synchronize Configuration</span>
           )}
         </button>
      </div>
    </form>
  );
}

'use client';

import React, { useState, useEffect, useMemo } from 'react';
import toast from 'react-hot-toast';
import Image from 'next/image';
import { formatDate } from '@/lib/date';
import { getAssetUrl } from '@/lib/assets';

export default function StorageExplorer() {
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [storageType, setStorageType] = useState('cloudinary');
  const [zipping, setZipping] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPath, setCurrentPath] = useState(''); // Empty string is root

  const fetchFiles = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/admin/infrastructure/storage');
      const data = await res.json();
      if (res.ok) {
        setFiles(data.files);
        setStorageType(data.storageType);
      } else {
        toast.error('Failed to load storage files');
      }
    } catch (error) {
      toast.error('Connection error while exploring bucket');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let isMounted = true;
    const load = async () => {
      if (isMounted) await fetchFiles();
    };
    load();
    return () => { isMounted = false; };
  }, []);

  const handleZipDownload = () => {
    if (!confirm('This will generate a compressed archive of ALL institutional assets. This may take a moment depending on the bucket size. Proceed?')) return;
    
    setZipping(true);
    toast.loading('Generating storage archive...', { duration: 5000 });
    
    // Redirect to the zip API which will eventually redirect to the zip file
    window.location.href = '/api/admin/infrastructure/storage/zip';
    
    setTimeout(() => setZipping(false), 5000);
  };

  const formatBytes = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  /**
   * DERIVED DATA: Compute the current view (Folders vs Files)
   */
  const viewData = useMemo(() => {
    // If searching, show a flat list (Global Search mode)
    if (searchTerm) {
      return {
        isSearch: true,
        items: files.filter(f => f.name.toLowerCase().includes(searchTerm.toLowerCase())),
        folders: []
      };
    }

    const folders = new Set();
    const currentFiles = [];

    files.forEach(f => {
      const name = f.name;
      
      // If we're at root, and the path has segments
      if (currentPath === '') {
        if (name.includes('/')) {
          folders.add(name.split('/')[0]);
        } else {
          currentFiles.push(f);
        }
      } 
      // If we're in a folder (e.g., 'students')
      else if (name.startsWith(currentPath + '/')) {
        const relativePath = name.substring(currentPath.length + 1);
        if (relativePath.includes('/')) {
          folders.add(relativePath.split('/')[0]);
        } else {
          currentFiles.push(f);
        }
      }
    });

    return {
      isSearch: false,
      items: currentFiles,
      folders: Array.from(folders).sort()
    };
  }, [files, currentPath, searchTerm]);

  const breadcrumbs = useMemo(() => {
    if (!currentPath) return [];
    const segments = currentPath.split('/');
    return segments.map((s, i) => ({
      name: s,
      path: segments.slice(0, i + 1).join('/')
    }));
  }, [currentPath]);

  return (
    <div className="space-y-8 animate-fadeIn">
      
      {/* Action Bar */}
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 border border-slate-200 shadow-sm rounded-sm gap-4">
        <div className="w-full md:w-auto">
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
            Bucket Explorer
            <span className="px-2 py-0.5 bg-blue-50 text-blue-700 text-[8px] font-black rounded-full border border-blue-100 uppercase tracking-tighter">
              {storageType} mode
            </span>
          </h3>
          
          {/* Breadcrumbs */}
          <div className="flex items-center gap-2 mt-2 overflow-x-auto no-scrollbar">
            <button 
              onClick={() => { setCurrentPath(''); setSearchTerm(''); }}
              className={`text-[9px] font-black uppercase tracking-widest ${currentPath === '' ? 'text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Root
            </button>
            {breadcrumbs.map((b, i) => (
              <React.Fragment key={b.path}>
                <span className="text-slate-300 text-[10px]">/</span>
                <button 
                  onClick={() => { setCurrentPath(b.path); setSearchTerm(''); }}
                  className={`text-[9px] font-black uppercase tracking-widest whitespace-nowrap ${i === breadcrumbs.length - 1 ? 'text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}
                >
                  {b.name}
                </button>
              </React.Fragment>
            ))}
          </div>
        </div>
        
        <div className="flex items-center gap-4 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <input 
              type="text" 
              placeholder="Search all assets..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full h-11 bg-slate-50 border border-slate-200 px-4 text-[11px] font-bold outline-none focus:border-blue-500 transition-all uppercase tracking-wider shadow-inner rounded-sm"
            />
          </div>
          <button
            onClick={handleZipDownload}
            disabled={zipping || loading}
            className="px-6 h-11 bg-[#0b3578] text-white text-[10px] font-black uppercase tracking-[0.2em] rounded-sm hover:bg-blue-900 transition-all shadow-md disabled:bg-slate-300 disabled:cursor-not-allowed flex items-center gap-3 whitespace-nowrap"
          >
            {zipping ? (
              <>
                <div className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                <span>Compressing...</span>
              </>
            ) : (
              <>
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                </svg>
                <span>Full Export</span>
              </>
            )}
          </button>
        </div>
      </div>

      {/* Structured View Grid/Table */}
      <div className="bg-white border border-slate-200 shadow-sm rounded-sm overflow-hidden">
        <div className="bg-slate-50 px-8 py-4 border-b border-slate-200 flex justify-between items-center">
           <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">
             {viewData.isSearch ? 'Search Results' : (currentPath || 'Root Directory')}
             {!viewData.isSearch && <span className="ml-2 opacity-60">({viewData.folders.length} folders, {viewData.items.length} files)</span>}
           </span>
           <button onClick={fetchFiles} className="text-[10px] font-black text-blue-600 hover:underline uppercase tracking-widest">Refresh Sync</button>
        </div>
        
        <div className="overflow-x-auto min-h-[400px]">
          <table className="w-full border-collapse">
            <thead>
              <tr className="border-b border-slate-100 bg-white sticky top-0 z-10">
                <th className="px-8 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Type</th>
                <th className="px-8 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Asset Name</th>
                <th className="px-8 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Size</th>
                <th className="px-8 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Created At</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {loading ? (
                <tr>
                  <td colSpan="4" className="px-8 py-20 text-center">
                    <div className="flex flex-col items-center gap-4">
                      <div className="w-10 h-10 border-4 border-slate-100 border-t-blue-600 rounded-full animate-spin"></div>
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Synchronizing cloud files...</span>
                    </div>
                  </td>
                </tr>
              ) : (viewData.folders.length === 0 && viewData.items.length === 0) ? (
                <tr>
                  <td colSpan="4" className="px-8 py-20 text-center text-slate-400 text-xs font-bold uppercase tracking-widest italic">Directory is empty.</td>
                </tr>
              ) : (
                <>
                  {/* FOLDERS FIRST */}
                  {viewData.folders.map(folder => (
                    <tr 
                      key={folder} 
                      onClick={() => setCurrentPath(currentPath ? `${currentPath}/${folder}` : folder)}
                      className="group hover:bg-blue-50/50 cursor-pointer transition-colors"
                    >
                      <td className="px-8 py-4">
                         <div className="w-10 h-10 bg-amber-50 border border-amber-100 rounded-sm flex items-center justify-center text-amber-500 shadow-sm group-hover:bg-amber-100 transition-colors">
                            <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20">
                               <path d="M2 6a2 2 0 012-2h5l2 2h5a2 2 0 012 2v6a2 2 0 01-2 2H4a2 2 0 01-2-2V6z" />
                            </svg>
                         </div>
                      </td>
                      <td className="px-8 py-4">
                        <div className="flex flex-col">
                           <span className="text-xs font-black text-slate-700 uppercase tracking-widest group-hover:text-blue-700">{folder}</span>
                           <span className="text-[8px] font-bold text-slate-400 mt-0.5 uppercase tracking-tighter">Directory</span>
                        </div>
                      </td>
                      <td className="px-8 py-4 text-slate-400 text-[10px] font-black">—</td>
                      <td className="px-8 py-4 text-slate-400 text-[10px] font-black">—</td>
                    </tr>
                  ))}

                  {/* FILES SECOND */}
                  {viewData.items.map((f, i) => (
                    <tr key={f.name + i} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-8 py-3">
                         <div className="w-10 h-10 bg-white border border-slate-200 rounded-sm overflow-hidden flex items-center justify-center relative shadow-sm">
                            {f.secure_url || storageType === 'local' ? (
                              <Image 
                                src={f.secure_url || getAssetUrl(f.name)} 
                                alt="Asset" 
                                width={40} 
                                height={40} 
                                unoptimized
                                className="object-cover w-full h-full cursor-zoom-in hover:scale-110 transition-transform"
                                onClick={() => window.open(f.secure_url || getAssetUrl(f.name), '_blank')}
                              />
                            ) : (
                              <span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">BIN</span>
                            )}
                         </div>
                      </td>
                      <td className="px-8 py-3">
                        <div className="flex flex-col max-w-md">
                          <span className="text-xs font-black text-slate-700 truncate" title={f.name}>
                            {viewData.isSearch ? f.name : f.name.split('/').pop()}
                          </span>
                          <span className="text-[8px] font-mono text-slate-400 mt-1 uppercase">
                            {f.format || f.name.split('.').pop()} • {viewData.isSearch ? `Path: ${f.name}` : 'File'}
                          </span>
                        </div>
                      </td>
                      <td className="px-8 py-3">
                         <span className="text-xs font-bold text-slate-600">{formatBytes(f.size)}</span>
                      </td>
                      <td className="px-8 py-3">
                         <span className="text-xs font-bold text-slate-500 whitespace-nowrap">{formatDate(f.created_at)}</span>
                      </td>
                    </tr>
                  ))}
                </>
              )}
            </tbody>
          </table>
        </div>
      </div>
      
      {/* Storage Alert Note */}
      <div className="bg-blue-50 border-l-4 border-blue-400 p-6 shadow-sm rounded-sm">
         <div className="flex gap-4">
           <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center flex-shrink-0 text-blue-600">
             <svg className="h-6 w-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
             </svg>
           </div>
           <div className="space-y-1">
             <p className="text-[11px] font-black text-blue-800 uppercase tracking-widest">Institutional Asset Sovereignty</p>
             <p className="text-xs text-blue-700 leading-relaxed font-medium">
               The explorer provides a visual interface to your institutional {storageType} bucket. 
               The structure is derived from your database-standardized paths. 
               Use the global search for cross-directory auditing.
             </p>
           </div>
         </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { useClerk } from '@/context/ClerkContext';
import Image from 'next/image';
import Link from 'next/link';
import ClerkNotificationDropdown from './ClerkNotificationDropdown';

export default function ClerkTopBar({ onMenuClick }) {
  const { clerkData } = useClerk();
  
  const [profileMenuOpen, setProfileMenuOpen] = useState(false);
  const profileDropdownRef = useRef(null);

  // Close dropdowns on click outside
  useEffect(() => {
    function handleClickOutside(event) {
      if (profileDropdownRef.current && !profileDropdownRef.current.contains(event.target)) {
        setProfileMenuOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <header className="h-16 lg:h-20 flex items-center justify-between px-4 lg:px-8 bg-transparent relative">
      {/* Left: Mobile Menu Toggle & Search */}
      <div className="flex items-center gap-4 flex-1">
        <button 
          onClick={onMenuClick}
          className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-lg transition-colors"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
      </div>

      {/* Middle: Notification Hub for Mobile */}
      <div className="lg:hidden absolute left-1/2 -translate-x-1/2 flex items-center justify-center">
        {(clerkData?.role === 'admission' || clerkData?.role === 'scholarship') && (
           <div className="scale-110 sm:scale-125">
             <ClerkNotificationDropdown />
           </div>
        )}
      </div>

      {/* Right Side: Profile & Role */}
      <div className="flex items-center gap-3 lg:gap-5 flex-1 justify-end">
        {/* Desktop Notification Hub */}
        <div className="hidden lg:block border-r border-slate-200 pr-4">
          {(clerkData?.role === 'admission' || clerkData?.role === 'scholarship') && (
            <ClerkNotificationDropdown />
          )}
        </div>
        
        <div className="flex items-center gap-3 pl-1 lg:pl-4 relative" ref={profileDropdownRef}>
          <div className="text-right max-w-[100px] sm:max-w-none">
            <p className="text-[10px] sm:text-xs font-bold text-slate-700 leading-none truncate">{clerkData?.name || 'Loading...'}</p>
            <p className="text-[8px] sm:text-[10px] text-slate-400 mt-1 uppercase tracking-tighter truncate">
                {clerkData?.role} {clerkData?.is_hod ? '• HOD' : ''}
            </p>
          </div>
          <button 
            onClick={() => setProfileMenuOpen(!profileMenuOpen)}
            className="w-8 h-8 lg:w-9 lg:h-9 rounded-full overflow-hidden bg-[#0b3578] relative border border-slate-100 shadow-sm flex-shrink-0 hover:ring-2 hover:ring-[#0b3578]/20 transition-all focus:outline-none flex items-center justify-center text-white font-bold text-xs uppercase"
          >
            {clerkData?.name?.charAt(0) || 'E'}
          </button>

          {profileMenuOpen && (
            <div className="absolute right-0 top-full mt-3 w-48 bg-white rounded-xl shadow-2xl border border-slate-100 overflow-hidden z-[70] animate-fadeIn">
               <div className="p-2">
                  <Link 
                    href="/clerk/settings/edit-profile" 
                    onClick={() => setProfileMenuOpen(false)}
                    className="flex items-center gap-3 px-4 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-50 rounded-lg transition-colors group"
                  >
                    <svg className="w-4 h-4 text-slate-400 group-hover:text-[#0b3578]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                    </svg>
                    Edit Profile
                  </Link>
                  <Link 
                    href="/clerk/settings/security" 
                    onClick={() => setProfileMenuOpen(false)}
                    className="flex items-center gap-3 px-4 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-50 rounded-lg transition-colors group"
                  >
                    <svg className="w-4 h-4 text-slate-400 group-hover:text-[#0b3578]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                    </svg>
                    Security
                  </Link>
               </div>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

