"use client";

import { useEffect, useMemo, useState, useRef, useCallback } from "react";
import { usePathname } from 'next/navigation';
import { useClerk } from "@/context/ClerkContext";
// Filters moved into a contextual popover; removed full-width CertificateFilters component
import CertificateWorkspaceCard from "./CertificateWorkspaceCard";
// Date-based history removed — replaced with scope-based history UI
import CertificateRecordsView from "./CertificateRecordsView";
import CertificateActionPanel from "./CertificateActionPanel";
import FiltersPopover from "./FiltersPopover";
import FiltersButton from "./FiltersButton";
import { createPortal } from 'react-dom';

export default function CertificateDashboard({ clerkType }) {
  const { pendingCertificateRequests, isLoadingRequests, refreshCertificateRequests } = useClerk();
  const [workspaceMode, setWorkspaceMode] = useState("active"); // "active" | "history"
  const [selectedDate, setSelectedDate] = useState(null); // string | null
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [selectedRequestId, setSelectedRequestId] = useState(null);
  const [selectedRequestDetails, setSelectedRequestDetails] = useState(null);
  const [isDialogLoading, setIsDialogLoading] = useState(false);
  const [dialogError, setDialogError] = useState(null);
  const [records, setRecords] = useState([]);
  const [loadingRecords, setLoadingRecords] = useState(false);
  const [historyScope, setHistoryScope] = useState('my'); // 'my' | 'all'
  const [myHistoryCount, setMyHistoryCount] = useState(0);
  const [allHistoryCount, setAllHistoryCount] = useState(0);
  const [rejectReasonOpen, setRejectReasonOpen] = useState(false);
  const [rejectReason, setRejectReason] = useState("");
  // Filter UI state
  const [showFilters, setShowFilters] = useState(false);
  // Filters stored as arrays per spec but popover provides single-select values
  const [filters, setFilters] = useState({ certificateType: '', status: '' });
  const [appliedFilters, setAppliedFilters] = useState({ certificateType: [], status: [] });
  const filtersRef = useRef(null);
  const pathname = usePathname();

  const handleChangeMode = (next) => {
    setWorkspaceMode(next);
    if (next === "active") {
      setSelectedDate(null);
    }
  };

  // Derived records to avoid sync setState in effect
  const displayRecords = useMemo(() => {
    if (workspaceMode === 'active' && appliedFilters.certificateType.length === 0 && appliedFilters.status.length === 0) {
      return (pendingCertificateRequests || []).map(r => ({ 
        ...r, 
        date: r.created_at ? String(r.created_at).split('T')[0] : r.date 
      }));
    }
    return records;
  }, [workspaceMode, appliedFilters, pendingCertificateRequests, records]);

  // Fetch records whenever mode/date/clerkType changes
  const fetchRecords = useCallback(async () => {
    if (workspaceMode === 'active' && appliedFilters.certificateType.length === 0 && appliedFilters.status.length === 0) {
       return;
    }

    setLoadingRecords(true);
    if (workspaceMode === 'history') {
      setRecords([]); // clear old records while loading history
    }

    try {
      const params = new URLSearchParams();
      params.set('workspace', workspaceMode);
      if (workspaceMode === 'history') params.set('scope', historyScope);
      if (clerkType) params.set('clerkType', clerkType);
      
      if (Array.isArray(appliedFilters.certificateType) && appliedFilters.certificateType.length > 0) {
        appliedFilters.certificateType.forEach(v => params.append('certificateType', v));
      }
      if (Array.isArray(appliedFilters.status) && appliedFilters.status.length > 0) {
        appliedFilters.status.forEach(v => params.append('status', v));
      }
      const res = await fetch(`/api/clerk/requests?${params.toString()}`, { credentials: 'same-origin' });
      if (!res.ok) throw new Error('Failed to fetch requests');
      const data = await res.json();
      
      if (workspaceMode === 'history') {
        const recs = Array.isArray(data?.records) ? data.records : [];
        const normalized = recs.map(r => ({
          ...r,
          date: r.completed_at ? String(r.completed_at).split('T')[0] : (r.date ? String(r.date) : null),
        }));
        setRecords(normalized);
        setMyHistoryCount(Number(data?.myHistoryCount ?? 0));
        setAllHistoryCount(Number(data?.allHistoryCount ?? 0));
      } else {
        const recs = Array.isArray(data.records) ? data.records : (Array.isArray(data) ? data : []);
        const normalized = recs.map(r => ({ ...r, date: r.created_at ? String(r.created_at).split('T')[0] : r.date }));
        setRecords(normalized);
      }
    } catch (e) {
      setRecords([]);
    } finally {
      setLoadingRecords(false);
    }
  }, [workspaceMode, historyScope, clerkType, appliedFilters]);

  // Effects
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchRecords();
  }, [fetchRecords]);

  // Click-away and Escape handling for Filters popover
  useEffect(() => {
    const onPointerDown = (e) => {
      if (!showFilters) return;
      const el = filtersRef.current;
      if (!el) return;
      if (!el.contains(e.target)) setShowFilters(false);
    };
    const onKeyDown = (e) => {
      if (e.key === 'Escape' && showFilters) setShowFilters(false);
    };
    const onScroll = () => {
      // Close on scroll for small screens to avoid awkward overlays
      try {
        if (showFilters && typeof window !== 'undefined' && window.innerWidth < 640) setShowFilters(false);
      } catch { /* empty */ }
    };

    const onResize = () => {
      // If user resizes, ensure popover doesn't remain incorrectly placed
      if (showFilters && typeof window !== 'undefined' && window.innerWidth < 480) setShowFilters(false);
    };

    document.addEventListener('pointerdown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onResize);

    return () => {
      document.removeEventListener('pointerdown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onResize);
    };
  }, [showFilters]);

  // Close popover on route change
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (showFilters) setShowFilters(false);
  }, [pathname, showFilters]);

  const formatDateForDisplay = (val) => {
    if (!val) return val;
    try {
      const s = String(val);
      if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
        const [y, m, d] = s.split('-');
        return `${d}-${m}-${y}`;
      }
      // If it's already in another display-friendly format, return as-is
      return s;
    } catch {
      return String(val);
    }
  };

  const handleViewDetails = async (r) => {
    const id = r?.request_id;
    setSelectedRequestId(id || null);
    setIsDialogOpen(true);
    setIsDialogLoading(true);
    setDialogError(null);
    setSelectedRequestDetails(null);
    try {
      if (!id) throw new Error('Invalid request id');
      const res = await fetch(`/api/clerk/requests/${encodeURIComponent(id)}`, { credentials: 'same-origin' });
      if (!res.ok) throw new Error('Failed to load request details');
      const data = await res.json();
      const req = Array.isArray(data) ? data[0] : data;
      setSelectedRequestDetails(req || null);
    } catch (e) {
      setDialogError(e?.message || 'Unable to load details');
    } finally {
      setIsDialogLoading(false);
    }
  };

  const closeDialog = () => {
    setIsDialogOpen(false);
    setSelectedRequestId(null);
    setSelectedRequestDetails(null);
    setIsDialogLoading(false);
    setDialogError(null);
    setRejectReason('');
    setRejectReasonOpen(false);
  };

  return (
    <div className="w-full space-y-4" id="certificate-section">
      {/* Filters moved to contextual popover aligned with the main content card */}

      {/* Main: Single grid with stacked left cards */}
      <div className="grid grid-cols-1 gap-4 md:grid-cols-12">
        {/* Left column: stacked cards */}
        <div className="md:col-span-3 space-y-4">
          <CertificateWorkspaceCard mode={workspaceMode} onChange={handleChangeMode} />
          {workspaceMode === "history" && (
            <section className="bg-white border rounded-lg p-3 shadow-sm">
              <h4 className="text-sm font-semibold text-gray-800 mb-3">History Scope</h4>
              <div className="flex flex-col gap-2">
                <button
                  type="button"
                  onClick={() => setHistoryScope('my')}
                  className={
                    "px-3 py-2 text-sm rounded-md border text-left w-full " +
                    (historyScope === 'my' ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-gray-50 border-gray-200 text-gray-700')
                  }
                >
                  My History ({myHistoryCount})
                </button>
                <button
                  type="button"
                  onClick={() => setHistoryScope('all')}
                  className={
                    "px-3 py-2 text-sm rounded-md border text-left w-full " +
                    (historyScope === 'all' ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-gray-50 border-gray-200 text-gray-700')
                  }
                >
                  All History ({allHistoryCount})
                </button>
              </div>
            </section>
          )}
        </div>

        {/* Right column: main content — one area, conditional content */}
        <div className="md:col-span-9 space-y-4">
          {workspaceMode === "active" && (
            <>
              <section className="bg-white border rounded-lg p-4 shadow-sm relative">
                <div className="flex items-start justify-between">
                  <div>
                    <h3 className="text-lg font-semibold text-gray-800">Active Requests</h3>
                    <p className="text-sm text-gray-600">Placeholder list of currently active certificate requests.</p>
                  </div>
                    <div ref={filtersRef} className="ml-4 relative">
                    <FiltersButton
                      show={showFilters}
                      onToggle={() => setShowFilters((s) => !s)}
                      activeCount={(appliedFilters.certificateType?.length || 0) + (appliedFilters.status?.length || 0)}
                    />
                    {showFilters && (
                      <FiltersPopover
                        filters={filters}
                        setFilters={setFilters}
                        onApply={() => {
                          const certArr = filters.certificateType ? [filters.certificateType] : [];
                          const statusArr = filters.status ? [filters.status] : [];
                          setAppliedFilters({ certificateType: certArr, status: statusArr });
                          setShowFilters(false);
                        }}
                        onClear={() => { setFilters({ certificateType: '', status: '' }); setAppliedFilters({ certificateType: [], status: [] }); setShowFilters(false); }}
                      />
                    )}
                  </div>
                </div>
              </section>
              <CertificateRecordsView records={displayRecords} onViewDetails={handleViewDetails} loading={loadingRecords} />
            </>
          )}

          {workspaceMode === 'history' && (
            <>
              <section className="bg-white border rounded-lg p-4 shadow-sm relative">
                <div className="flex items-start justify-between">
                  <div>
                    <h3 className="text-lg font-semibold text-gray-800">History — {historyScope === 'my' ? 'My History' : 'All History'}</h3>
                    <p className="text-sm text-gray-600">Showing approved and rejected records grouped by completion date.</p>
                  </div>
                  <div className="ml-4 relative">
                    <FiltersButton
                      show={showFilters}
                      onToggle={() => setShowFilters((s) => !s)}
                      activeCount={(appliedFilters.certificateType?.length || 0) + (appliedFilters.status?.length || 0)}
                    />
                    {showFilters && (
                      <FiltersPopover
                        filters={filters}
                        setFilters={setFilters}
                        onApply={() => {
                          // Convert popover single-select values into arrays for appliedFilters
                          const certArr = filters.certificateType ? [filters.certificateType] : [];
                          const statusArr = filters.status ? [filters.status] : [];
                          setAppliedFilters({ certificateType: certArr, status: statusArr });
                          setShowFilters(false);
                        }}
                        onClear={() => { setFilters({ certificateType: '', status: '' }); setAppliedFilters({ certificateType: [], status: [] }); setShowFilters(false); }}
                      />
                    )}
                  </div>
                </div>
              </section>
              <CertificateRecordsView records={displayRecords} onViewDetails={handleViewDetails} groupByDate={true} loading={loadingRecords} />
            </>
          )}
        </div>
      </div>

      {/* Modal/Dialog for request details */}
      {isDialogOpen && typeof document !== 'undefined' && createPortal(
        (
          <div className="fixed inset-0 z-[9998] flex items-center justify-center p-4" style={{ backgroundColor: 'rgba(0,0,0,0.4)' }}>
            <div className="bg-white rounded-lg shadow-xl w-full max-w-3xl flex flex-col">
            <div className="p-4 border-b flex items-center justify-between">
              <h3 className="text-lg font-semibold text-gray-800">Request Details</h3>
              <button
                type="button"
                className="text-gray-600 hover:text-gray-900"
                onClick={closeDialog}
                aria-label="Close dialog"
              >
                ✕
              </button>
            </div>
            <div className="p-6 overflow-y-auto max-h-[60vh]">
              {isDialogLoading ? (
                <div className="text-sm text-gray-600">Loading request details…</div>
              ) : dialogError ? (
                <div className="text-sm text-red-600">{dialogError}</div>
              ) : (
                <CertificateActionPanel request={selectedRequestDetails} />
              )}
            </div>
            <div className="p-4 border-t bg-gray-50 flex items-center justify-end gap-2">
              {selectedRequestDetails?.status === 'PENDING' ? (
                <>
                  <button type="button" className="px-4 py-2 rounded-md bg-red-600 text-white cursor-pointer disabled:opacity-60" disabled={isDialogLoading || !!dialogError || !selectedRequestId} onClick={() => setRejectReasonOpen(true)}>Reject</button>
                  <button type="button" className="px-4 py-2 rounded-md bg-green-600 text-white cursor-pointer disabled:opacity-60" disabled={isDialogLoading || !!dialogError || !selectedRequestId} onClick={async () => {
                    try {
                      if (!selectedRequestId) return;
                      // Guard: only allow PUT when request is still pending
                      if (selectedRequestDetails?.status !== 'PENDING') return;
                      const res = await fetch(`/api/clerk/requests/${encodeURIComponent(selectedRequestId)}`, {
                        method: 'PUT', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'APPROVED' })
                      });
                      if (res.ok) {
                        closeDialog();
                        await refreshCertificateRequests(clerkType);
                        await fetchRecords();
                      }
                    } catch { /* empty */ }
                  }}>Approve</button>
                </>
              ) : null}

              <button
                type="button"
                onClick={closeDialog}
                className="px-4 py-2 rounded-md border cursor-pointer"
              >
                Close
              </button>
            </div>
          </div>
          </div>
        ),
        document.body
      )}

      {/* Reject reason dialog */}
      {rejectReasonOpen && typeof document !== 'undefined' && createPortal(
        (
          <div className="fixed inset-0 z-[9998] flex items-center justify-center p-4" style={{ backgroundColor: 'rgba(0,0,0,0.45)' }}>
            <div className="bg-white rounded-lg shadow-xl w-full max-w-md flex flex-col">
            <div className="p-4 border-b flex items-center justify-between">
              <h3 className="text-lg font-semibold text-gray-800">Reason for Rejection</h3>
              <button type="button" className="text-gray-600 hover:text-gray-900 cursor-pointer" onClick={() => setRejectReasonOpen(false)} aria-label="Close">✕</button>
            </div>
            <div className="p-4">
              <p className="text-sm text-gray-600 mb-3">Provide a clear reason so the student can re-apply if needed.</p>
              <textarea value={rejectReason} onChange={(e) => setRejectReason(e.target.value)} rows={6} className="w-full p-3 border border-gray-300 rounded-md resize-none text-sm" placeholder="Enter rejection reason" />
            </div>
            <div className="p-4 border-t bg-gray-50 flex items-center justify-end gap-2">
              <button type="button" className="px-4 py-2 rounded-md border cursor-pointer" onClick={() => setRejectReasonOpen(false)}>Cancel</button>
              <button type="button" className="px-4 py-2 rounded-md bg-red-600 text-white cursor-pointer" onClick={async () => {
                try {
                  if (!selectedRequestId) return;
                  // Do not allow rejection if already finalized
                  if (selectedRequestDetails?.status !== 'PENDING') return;
                  const reason = String(rejectReason || '').trim();
                  if (!reason) return;
                  const res = await fetch(`/api/clerk/requests/${encodeURIComponent(selectedRequestId)}`, {
                    method: 'PUT', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'REJECTED', reject_reason: reason })
                  });
                  if (res.ok) {
                    setRejectReasonOpen(false);
                    closeDialog();
                    await refreshCertificateRequests(clerkType);
                    await fetchRecords();
                  }
                } catch { /* empty */ }
              }}>Confirm Reject</button>
            </div>
          </div>
          </div>
        ),
        document.body
      )}
    </div>
  );
}

"use client";

export default function FiltersButton({ show, onToggle, activeCount = 0 }) {
  return (
    <div className="relative inline-block text-left">
      <button type="button" onClick={onToggle} className="inline-flex items-center gap-2 px-3 py-1.5 border rounded-md bg-white text-sm">
        <span>Filters</span>
        <svg className="w-3 h-3" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><path fillRule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 11.293l3.71-4.064a.75.75 0 111.08 1.04l-4.25 4.657a.75.75 0 01-1.08 0L5.21 8.27a.75.75 0 01.02-1.06z" clipRule="evenodd" /></svg>
        {activeCount ? <span className="ml-1 inline-flex items-center justify-center w-5 h-5 text-xs rounded-full bg-indigo-600 text-white">{activeCount}</span> : null}
      </button>
    </div>
  );
}

'use client';
import { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import FacultyAcademicCalendar from './FacultyAcademicCalendar';
import { useFacultyAttendance } from '@/context/FacultyAttendanceContext';

const formatDisplayDate = (dateStr) => {
  if (!dateStr) return '—';
  const parts = dateStr.split('-');
  if (parts.length !== 3) return dateStr;
  const [year, month, day] = parts;
  return `${day}-${month}-${year}`;
};

const SubjectIdentityPanel = () => {
  const { assignment } = useFacultyAttendance();
  return (
  <div className="bg-white border-2 border-gray-200 p-4 rounded-lg mb-6">
    <div className="flex justify-between items-center border-b-2 border-gray-200 pb-2 mb-4">
      <h2 className="text-xl font-bold text-gray-800">Attendance Register</h2>
      <span className={`text-sm font-bold px-3 py-1 rounded-full ${assignment.is_active ? 'bg-green-100 text-green-700' : 'bg-gray-200 text-gray-600'}`}>
        {assignment.is_active ? 'Active' : 'History'}
      </span>
    </div>
    <div className="grid grid-cols-2 md:grid-cols-4 gap-x-4 gap-y-2 text-sm">
      <div className="font-semibold text-gray-500">Subject:</div>
      <div className="font-mono text-gray-900 col-span-3">{assignment.subject_name}</div>

      <div className="font-semibold text-gray-500">Code:</div>
      <div className="font-mono text-gray-900">{assignment.subject_code}</div>

      <div className="font-semibold text-gray-500">Branch:</div>
      <div className="font-mono text-gray-900">{assignment.branch}</div>

      <div className="font-semibold text-gray-500">Semester:</div>
      <div className="font-mono text-gray-900">{assignment.semester}</div>

      <div className="font-semibold text-gray-500">Academic Year:</div>
      <div className="font-mono text-gray-900">{assignment.academic_year}</div>
    </div>
  </div>
  );
};

const SessionControlPanel = () => {
  const { 
    activeSession, 
    startSession, 
    endSession, 
    submitting, 
    verifiedStudentIds, 
    students, 
    setAttendanceStatus, 
    handleManualRefresh,
    selectedDate,
    dateValidation
  } = useFacultyAttendance();

  const verifiedList = (students || []).filter((s) => verifiedStudentIds?.has?.(s.id));

  const handleConfirmAll = () => {
    (students || []).forEach((s) => {
      if (verifiedStudentIds?.has?.(s.id)) {
        setAttendanceStatus(s.id, 'PRESENT');
      } else if (s.status === null) {
        setAttendanceStatus(s.id, 'ABSENT');
      }
    });
    toast.success('Marked verified students as PRESENT and others as ABSENT.');
  };

  return (
    <div className="bg-indigo-50 border-2 border-indigo-200 p-4 rounded-xl mb-6 shadow-sm">
      <div className="flex flex-col lg:flex-row justify-between gap-6">
        <div className="flex-1">
          <h3 className="text-indigo-900 font-bold flex items-center gap-2">
            <span className="relative flex h-3 w-3">
              <span className={`animate-ping absolute inline-flex h-full w-full rounded-full ${activeSession ? 'bg-green-400' : 'bg-gray-400'} opacity-75`}></span>
              <span className={`relative inline-flex rounded-full h-3 w-3 ${activeSession ? 'bg-green-500' : 'bg-gray-500'}`}></span>
            </span>
            SECURE ATTENDANCE (PIN + GPS)
          </h3>
          <p className="text-xs text-indigo-700 mt-1">
            {activeSession 
              ? 'Session is live! Students must enter the 4-digit PIN on their dashboard to verify.' 
              : 'Start a secure session to allow students to mark their own attendance via GPS verification.'}
          </p>

          {activeSession && (
            <div className="mt-4 p-3 bg-white rounded-lg border border-indigo-100 shadow-inner">
              <div className="flex justify-between items-center mb-2">
                <div className="flex items-center gap-2">
                  <span className="text-[10px] font-black text-indigo-400 uppercase">Live Verifications ({verifiedList.length})</span>
                  <button 
                    onClick={handleManualRefresh}
                    className="p-1 hover:bg-gray-100 rounded-full transition-colors group"
                    title="Manual Refresh"
                  >
                    <svg className="w-3.5 h-3.5 text-indigo-500 group-active:rotate-180 transition-transform duration-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                  </button>
                </div>
                {verifiedList.length > 0 && (
                  <button 
                    onClick={handleConfirmAll}
                    className="text-[10px] bg-indigo-600 text-white px-2 py-1 rounded font-bold hover:bg-indigo-700 active:scale-95 transition-all"
                  >
                    Confirm All
                  </button>
                )}
              </div>
              <div className="flex flex-wrap gap-2 max-h-24 overflow-y-auto pr-1">
                {verifiedList.length > 0 ? verifiedList.map(s => (
                  <div key={s.id} className="text-[10px] font-bold bg-green-50 text-green-700 px-2 py-1 rounded border border-green-100 animate-fadeIn">
                    {s.roll_no}
                  </div>
                )) : (
                  <p className="text-[10px] text-gray-400 italic">Waiting for students to enter PIN...</p>
                )}
              </div>
            </div>
          )}
        </div>

        {activeSession ? (
          <div className="flex items-center gap-8 bg-white p-4 rounded-lg border border-indigo-100 shadow-sm shrink-0">
            <div className="text-center px-4">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">ATTENDANCE PIN</p>
              <p className="text-5xl font-black text-indigo-600 tracking-tighter">{activeSession.session_pin}</p>
            </div>
            <button
              onClick={endSession}
              disabled={submitting}
              className="ml-4 px-6 py-2 bg-red-600 text-white text-xs font-bold rounded-lg hover:bg-red-700 transition-colors uppercase"
            >
              End Session
            </button>
          </div>
        ) : (
          <button
            onClick={startSession}
            disabled={submitting || !selectedDate || !dateValidation.isValid}
            className="px-6 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition-all shadow-md active:scale-95 flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:grayscale"
            title={!selectedDate ? "Please select a date first" : !dateValidation.isValid ? "Please select a valid working day" : "Start Secure Session"}
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 11c0 3.517-1.009 6.799-2.753 9.571m-3.44-2.04l.054-.09A10.003 10.003 0 0012 3c4.183 0 7.66 2.567 9.106 6H22.25m-9.448 10a10.003 10.003 0 01-1.106-2.04m0 0l.054-.09A10.003 10.003 0 0122.5 12"></path></svg>
            START SECURE SESSION
          </button>
        )}
      </div>
    </div>
  );
};

const SessionSelector = () => {
  const { assignment, selectedSession, setSelectedSession, existingSessionsForSelectedDate } = useFacultyAttendance();

  return (
    <div className="flex-1">
      <label className="block text-[11px] font-bold text-gray-500 uppercase mb-2">SESSIONS</label>
      <div className="flex gap-1 bg-gray-100 p-1 rounded-lg border-2">
        {[1, 2, 3, 4, 5].map((num) => {
          const isExisting = existingSessionsForSelectedDate.includes(num);
          const isAllowedSequential = num === 1 || existingSessionsForSelectedDate.includes(num - 1);
          const isDisabled = !assignment.is_active || !isAllowedSequential;
          const isSelected = selectedSession === num;

          return (
            <button
              key={num}
              type="button"
              onClick={() => !isDisabled && setSelectedSession(num)}
              disabled={isDisabled}
              className={`flex-1 h-9 rounded-md text-[11px] font-bold tracking-wide uppercase transition-colors border ${
                isSelected
                  ? 'bg-gray-900 text-white border-gray-900'
                  : isExisting
                  ? 'bg-gray-50 text-gray-900 border-gray-300'
                  : 'bg-white text-gray-600 border-gray-200'
              } ${isDisabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
              title={
                isDisabled && num !== 1
                  ? `Session S${num} will be available after S${num - 1} is recorded.`
                  : isExisting
                  ? `S${num} already has attendance records.`
                  : ''
              }
            >
              S{num}
            </button>
          );
        })}
      </div>
      <p className="mt-1 text-[11px] text-gray-500">Sessions unlock sequentially. S2 requires recorded attendance for S1, and so on.</p>
    </div>
  );
};

const SaveControls = () => {
  const { assignment, submitting, students, dateValidation, existingSessionsForSelectedDate, selectedSession, handleSaveAttendance, handleDeleteAttendance } =
    useFacultyAttendance();

  return (
    <div className="flex flex-col items-stretch md:items-end gap-2 min-w-[180px]">
      {assignment.is_active ? (
        <>
          <button
            type="button"
            onClick={handleSaveAttendance}
            disabled={submitting || !students.length || !dateValidation.isValid || !assignment.is_active}
            className="px-4 py-2 bg-gray-900 text-white text-xs font-bold uppercase tracking-wide border border-gray-900 disabled:opacity-60"
          >
            {submitting ? 'Saving…' : 'Save Attendance'}
          </button>
          <button
            type="button"
            onClick={handleDeleteAttendance}
            disabled={
              submitting ||
              !existingSessionsForSelectedDate.includes(selectedSession) ||
              !dateValidation.isValid ||
              !assignment.is_active
            }
            className="px-4 py-2 bg-white text-red-700 text-xs font-bold uppercase tracking-wide border border-red-300 disabled:opacity-50"
          >
            Delete Session
          </button>
        </>
      ) : (
        <div className="px-4 py-2 bg-gray-200 text-gray-600 text-[11px] font-bold uppercase tracking-[0.18em] border text-center">Semester Ended</div>
      )}
    </div>
  );
};

const FollowPreviousButton = () => {
  const { assignment, selectedSession, selectedDate, existingSessionsForSelectedDate, setAttendanceStatus, students } = useFacultyAttendance();
  const [loadingCopy, setLoadingCopy] = useState(false);

  if (!selectedDate) return null;
  if (selectedSession <= 1) return null;

  const prev = selectedSession - 1;
  if (!existingSessionsForSelectedDate.includes(prev)) return null;

  const handleFollow = async () => {
    if (!assignment?.id) return;
    setLoadingCopy(true);
    try {
      const url = `/api/clerk/faculty/attendance/status?assignment_id=${assignment.id}&date=${encodeURIComponent(
        selectedDate,
      )}&session=${encodeURIComponent(prev)}`;
      const res = await fetch(url);
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to fetch previous session');

      const statusMap = (data.data || []).reduce((acc, r) => {
        acc[r.student_id] = r.status;
        return acc;
      }, { /* empty */ });

      (students || []).forEach((s) => {
        setAttendanceStatus(s.id, statusMap[s.id] ?? null);
      });

      toast.success('Session attendance copied from previous session');
    } catch (err) {
      toast.error(err.message || 'Unable to copy previous session');
    } finally {
      setLoadingCopy(false);
    }
  };

  return (
    <div className="flex items-center md:justify-center w-full md:w-auto">
      <button
        type="button"
        onClick={handleFollow}
        disabled={loadingCopy}
        className="w-full md:w-auto inline-flex items-center justify-center gap-2 px-3 py-2 bg-white border border-gray-300 text-sm font-semibold text-gray-700 rounded-md hover:bg-gray-50 disabled:opacity-60"
        title="Copy attendance from previous session"
      >
        {loadingCopy ? 'Copying…' : 'Follow previous session'}
      </button>
    </div>
  );
};

const AttendanceGrid = () => {
  const { students, assignment, dateValidation, toggleAttendanceStatus, setAllAttendanceStatus, statusLoading, verifiedStudentIds } = useFacultyAttendance();

  return (
    <table className="min-w-full divide-y-2 divide-gray-200 border">
      <thead className="bg-gray-50">
        <tr>
          <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Roll No</th>
          <th className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Name</th>
          <th className="px-6 py-3 text-center text-xs font-bold text-gray-500 uppercase tracking-wider">
            <div className="flex flex-col items-center gap-2">
              <div className="inline-flex items-center justify-center gap-2">
                <span>Status</span>
                {statusLoading && (
                  <span className="inline-block h-3 w-3 border-2 border-gray-400 border-t-transparent rounded-full animate-spin" />
                )}
              </div>
              {/* Bulk Toggle Buttons */}
              <div className="flex gap-1">
                <button
                  type="button"
                  onClick={() => assignment.is_active && dateValidation.isValid && setAllAttendanceStatus('PRESENT')}
                  disabled={!assignment.is_active || !dateValidation.isValid || statusLoading}
                  className="px-2 py-1 bg-green-600 text-white text-[9px] font-black rounded hover:bg-green-700 disabled:opacity-50 transition-colors uppercase"
                  title="Mark All Present"
                >
                  All P
                </button>
                <button
                  type="button"
                  onClick={() => assignment.is_active && dateValidation.isValid && setAllAttendanceStatus('ABSENT')}
                  disabled={!assignment.is_active || !dateValidation.isValid || statusLoading}
                  className="px-2 py-1 bg-red-600 text-white text-[9px] font-black rounded hover:bg-red-700 disabled:opacity-50 transition-colors uppercase"
                  title="Mark All Absent"
                >
                  All A
                </button>
              </div>
            </div>
          </th>
        </tr>
      </thead>
      <tbody className="bg-white divide-y divide-gray-200">
        {students.map((student) => (
          <tr key={student.id} className="hover:bg-gray-50">
            <td className="px-6 py-4 whitespace-nowrap text-sm font-mono text-gray-800">
              <div className="flex items-center gap-2">
                {student.roll_no}
                {verifiedStudentIds.has(student.id) && (
                  <span className="flex h-2 w-2 rounded-full bg-green-500 animate-pulse" title="Self-Verified via QR/PIN"></span>
                )}
              </div>
            </td>
            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
              <div className="flex items-center gap-2">
                {student.name}
                {verifiedStudentIds.has(student.id) && (
                  <span className="text-[9px] font-black text-green-600 bg-green-50 px-1.5 py-0.5 rounded border border-green-100 uppercase">Verified</span>
                )}
              </div>
            </td>
            <td className="px-6 py-4 whitespace-nowrap text-center">
              {statusLoading ? (
                <div className="flex justify-center">
                  <span className="inline-block h-6 w-6 border-2 border-gray-300 border-t-transparent rounded-full animate-spin" />
                </div>
              ) : (
                <button
                  onClick={() => assignment.is_active && toggleAttendanceStatus(student.id)}
                  disabled={!assignment.is_active || !dateValidation.isValid}
                  className={`w-28 px-3 py-2 rounded text-sm font-bold uppercase ${
                    student.status === null
                      ? 'bg-gray-100 text-gray-700'
                      : student.status === 'PRESENT'
                      ? 'bg-green-100 text-green-800'
                      : student.status === 'ABSENT'
                      ? 'bg-red-100 text-red-800'
                      : student.status === 'NCC'
                      ? 'bg-blue-100 text-blue-800'
                      : student.status === 'MEDICAL'
                      ? 'bg-purple-100 text-purple-800'
                      : 'bg-gray-100 text-gray-700'
                  } ${!assignment.is_active || !dateValidation.isValid ? 'cursor-default opacity-50' : 'cursor-pointer'}`}
                >
                  {student.status === null ? 'NOT SET' : student.status}
                </button>
              )}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

const PendingSyncIndicator = () => {
  const { pendingSyncs, syncOfflineAttendance, submitting } = useFacultyAttendance();

  if (!pendingSyncs || pendingSyncs.length === 0) return null;

  return (
    <div className="bg-amber-50 border-2 border-amber-200 p-4 rounded-xl mb-6 shadow-sm animate-fadeIn">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div className="flex items-center gap-3">
          <div className="h-10 w-10 bg-amber-100 rounded-full flex items-center justify-center shrink-0">
            <svg className="w-6 h-6 text-amber-600 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
