function TimetableManager({ data, onEditSlot }) {
  const days = ['MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
  const periods = [1, 2, 3, 4, 5, 6, 7];
  
  const getSlot = (day, period) => data.find(s => s.day_of_week === day && s.period_number === period);

  return (
    <div className="animate-in fade-in duration-500">
      <div className="mb-4 flex justify-between items-center px-1">
        <h3 className="text-sm font-bold text-slate-800 tracking-wider uppercase">Active Master Matrix</h3>
        <div className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 text-emerald-700 border border-emerald-100 text-[8px] font-bold uppercase tracking-widest">
          System Registry Active
        </div>
      </div>

      <div className="overflow-x-auto border border-slate-200">
        <table className="w-full border-collapse text-xs min-w-[1000px]">
          <thead>
            <tr>
              <th className="border-b border-r border-slate-200 bg-slate-50 p-4 text-slate-400 font-bold uppercase tracking-widest w-24">Day</th>
              {periods.map(p => (
                <th key={p} className="border-b border-slate-200 bg-slate-50 p-4">
                  <div className="font-bold text-slate-700 uppercase tracking-widest mb-1 text-[10px]">Period {p}</div>
                  <div className="text-[8px] font-bold text-[#0b3578]/60 uppercase tracking-tighter">
                    {p === 1 && '09:30 - 10:20'}
                    {p === 2 && '10:20 - 11:10'}
                    {p === 3 && '11:20 - 12:10'}
                    {p === 4 && '12:10 - 01:00'}
                    {p === 5 && '02:00 - 02:50'}
                    {p === 6 && '02:50 - 03:40'}
                    {p === 7 && '03:40 - 04:30'}
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {days.map(day => (
              <tr key={day} className="hover:bg-slate-50 transition-colors">
                <td className="border-r border-b border-slate-200 bg-slate-50/50 font-bold text-center p-4 text-slate-600 text-[10px] uppercase">
                  {day}
                </td>
                {periods.map(p => {
                  const slot = getSlot(day, p);
                  const isActivity = slot && INSTITUTIONAL_ACTIVITIES.some(a => a.code === slot.subject_code);
                  return (
                    <td 
                      key={`${day}-${p}`} 
                      onClick={() => onEditSlot(day, p, slot)}
                      className={`border-b border-r border-slate-200 p-3 text-center transition-all cursor-pointer relative hover:bg-white hover:z-10 hover:shadow-xl group/cell ${slot ? (isActivity ? 'bg-amber-50/20' : 'bg-slate-50/30') : 'bg-slate-50/30'}`}
                    >
                      {slot ? (
                        <div className={`animate-in fade-in zoom-in-95 duration-300 border rounded-sm px-2.5 py-2 shadow-sm ${isActivity ? 'bg-amber-50 border-amber-200' : 'bg-white border-slate-200'}`}>
                          <div className={`font-bold text-[10px] mb-1 line-clamp-2 uppercase tracking-tight leading-tight ${isActivity ? 'text-amber-800' : 'text-[#0b3578]'}`}>
                            {isActivity ? INSTITUTIONAL_ACTIVITIES.find(a => a.code === slot.subject_code)?.name : (slot.subject_name || slot.subject_code)}
                          </div>
                          <div className="text-[9px] text-slate-500 font-bold mb-2 line-clamp-1 opacity-90">{slot.faculty_name || (isActivity ? 'N/A' : 'NOT ASSIGNED')}</div>
                          <div className="flex items-center justify-center gap-1.5">
                            <span className={`text-[8px] px-2 py-0.5 border font-bold uppercase tracking-widest ${isActivity ? 'bg-amber-50 text-amber-800 border-amber-200' : 'bg-slate-50 text-slate-600 border-slate-200'}`}>
                              {slot.room_no || 'TBD'}
                            </span>
                          </div>
                        </div>
                      ) : (
                        <div className="flex flex-col items-center justify-center gap-1.5 opacity-70 group-hover/cell:opacity-100 transition-all py-2">
                          <div className="text-[#0b3578] font-bold uppercase tracking-widest text-[7px]">Available</div>
                          <div className="w-6 h-6 border border-dashed border-[#0b3578] flex items-center justify-center text-[#0b3578] group-hover/cell:bg-[#0b3578] group-hover/cell:text-white">+</div>
                        </div>
                      )}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      
      <div className="mt-8 flex flex-wrap gap-8 items-center justify-center bg-slate-50 p-5 border border-slate-200">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-white border border-slate-200 flex items-center justify-center text-orange-500 font-bold text-sm">☕</div>
          <div>
            <div className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Instructional Break</div>
            <div className="text-[10px] font-bold text-slate-700 uppercase">11:10 AM - 11:20 AM</div>
          </div>
        </div>
        <div className="w-px h-8 bg-slate-200 hidden sm:block"></div>
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-white border border-slate-200 flex items-center justify-center text-emerald-500 font-bold text-sm">🍱</div>
          <div>
            <div className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Luncheon Break</div>
            <div className="text-[10px] font-bold text-slate-700 uppercase">01:00 PM - 02:00 PM</div>
          </div>
        </div>
      </div>
    </div>
  );
}

function SubjectAllocation({ subjects, faculty, assignments, refresh }) {
  const [selectedSub, setSelectedSub] = useState('');
  const [selectedFac, setSelectedFac] = useState('');
  const [selectedSem, setSelectedSem] = useState(6);
  const [isSaving, setIsSaving] = useState(false);

  const filteredAssignments = assignments.filter(a => a.course_semester === selectedSem);

  const handleAuthorize = async () => {
    if (!selectedSub || !selectedFac) return toast.error('Please select both subject and faculty');
    const subjectObj = subjects.find(s => s.subject_code === selectedSub);
    setIsSaving(true);
    try {
      const res = await fetch('/api/clerk/hod/subject-assignments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          faculty_id: selectedFac,
          subject_code: selectedSub,
          subject_name: subjectObj?.subject_name,
          semester: selectedSem
        })
      });
      if (res.ok) {
        toast.success('Authorization complete');
        refresh();
      } else {
        const data = await res.json();
        toast.error(data.error || 'Failed');
      }
    } catch (e) {
      toast.error('Network error');
    } finally {
      setIsSaving(false);
    }
  };

  const handleRevoke = async (id) => {
    if (!confirm('Revoke this faculty authorization?')) return;
    try {
      const res = await fetch(`/api/clerk/hod/subject-assignments?id=${id}`, { method: 'DELETE' });
      if (res.ok) {
        toast.success('Authorization revoked');
        refresh();
      }
    } catch (e) { toast.error('Failed'); }
  };

  return (
    <div className="animate-in fade-in slide-in-from-right-2 duration-500">
      <h3 className="text-sm font-bold text-slate-800 mb-6 uppercase tracking-wider">Faculty Authorization Registry</h3>
      
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Authorization Form */}
        <div className="bg-slate-50 border border-slate-200 p-6 h-fit sticky top-6">
          <h4 className="font-bold text-slate-700 mb-6 uppercase tracking-widest text-[13px] flex items-center gap-2">
            <span className="w-1.5 h-1.5 bg-[#0b3578] rounded-full"></span>
            New Personnel Authorization
          </h4>
          <div className="space-y-5">
             <div>
               <label className="text-[9.5px] font-bold text-slate-400 uppercase mb-1 block px-0.5 tracking-widest">Academic Semester</label>
               <select 
                 value={selectedSem}
                 onChange={(e) => setSelectedSem(parseInt(e.target.value))}
                 className="w-full bg-white border border-slate-200 p-3 text-xs font-bold text-slate-700 outline-none focus:border-[#0b3578] transition-all"
               >
                 {[1,2,3,4,5,6,7,8].map(s => <option key={s} value={s}>Semester {s}</option>)}
               </select>
             </div>
             <div>
               <label className="text-[9.5px] font-bold text-slate-400 uppercase mb-1 block px-0.5 tracking-widest">Target Subject Registry</label>
               <select 
                 value={selectedSub}
                 onChange={(e) => setSelectedSub(e.target.value)}
                 className="w-full bg-white border border-slate-200 p-3 text-xs font-bold text-slate-700 outline-none focus:border-[#0b3578] transition-all"
               >
                 <option value="">Select Subject</option>
                 {subjects.filter(s => s.semester === selectedSem).map(s => (
                   <option key={s.subject_code} value={s.subject_code}>{s.subject_code} - {s.subject_name}</option>
                 ))}
               </select>
             </div>
             <div>
               <label className="text-[9.5px] font-bold text-slate-400 uppercase mb-1 block px-0.5 tracking-widest">Registered Personnel</label>
               <select 
                 value={selectedFac}
                 onChange={(e) => setSelectedFac(e.target.value)}
                 className="w-full bg-white border border-slate-200 p-3 text-xs font-bold text-slate-700 outline-none focus:border-[#0b3578] transition-all"
               >
                 <option value="">Select Faculty Member</option>
                 {faculty.map(f => (
                   <option key={f.id} value={f.id}>{f.name} {f.home_branch ? `(${f.home_branch})` : ''}</option>
                 ))}
               </select>
             </div>
             <button 
               onClick={handleAuthorize}
               disabled={isSaving}
               className="w-full py-4 bg-[#0b3578] text-white font-bold uppercase tracking-widest text-[10.5px] hover:bg-blue-900 transition-all border border-[#0b3578] disabled:opacity-50 mt-4 shadow-sm"
             >
               {isSaving ? 'Synchronizing Authorization...' : 'Authorize Personnel Access'}
             </button>
          </div>
        </div>

        {/* Existing Assignments List */}
        <div className="lg:col-span-2 space-y-6">
           <div className="flex justify-between items-center px-1">
              <h4 className="font-bold text-slate-800 uppercase tracking-tight text-sm">Active Registry (Semester {selectedSem})</h4>
              <span className="text-[9px] font-bold text-[#0b3578] bg-blue-50 px-3 py-1 border border-blue-100 uppercase tracking-widest">{filteredAssignments.length} Official Records</span>
           </div>

           <div className="grid grid-cols-1 gap-3">
              {filteredAssignments.map(a => (
                <div key={a.id} className="bg-white border border-slate-200 p-5 flex justify-between items-center group hover:border-[#0b3578] transition-all shadow-sm">
                   <div className="flex items-center gap-5">
                      <div className="w-10 h-10 bg-slate-50 border border-slate-100 flex items-center justify-center text-sm group-hover:bg-blue-50 transition-colors">🎓</div>
                      <div>
                         <h5 className="font-bold text-slate-800 tracking-wider text-[11px] leading-tight mb-1 uppercase">{a.subject_name}</h5>
                         <div className="flex items-center gap-3">
                            <span className="text-[8px] font-bold text-[#0b3578] border border-[#0b3578]/20 bg-blue-50 px-2 py-0.5 uppercase tracking-widest">{a.subject_code}</span>
                            <span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Handler: <span className="text-slate-600 underline underline-offset-2 decoration-slate-300">{a.faculty_name}</span></span>
                         </div>
                      </div>
                   </div>
                   <button 
                     onClick={() => handleRevoke(a.id)}
                     className="p-2.5 text-slate-300 hover:bg-red-500 hover:text-white border border-transparent hover:border-red-600 transition-all opacity-0 group-hover:opacity-100"
                     title="Revoke Registry Authorization"
                   >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                   </button>
                </div>
              ))}

              {filteredAssignments.length === 0 && (
                <div className="bg-slate-50 border border-dashed border-slate-300 py-20 flex flex-col items-center justify-center text-center px-10">
                   <div className="text-3xl mb-4 opacity-20">🔐</div>
                   <p className="text-slate-400 font-bold uppercase tracking-widest text-[9px]">No Faculty Authorized for Semester {selectedSem} Registry</p>
                   <p className="text-[8px] text-slate-400 mt-2 max-w-xs uppercase tracking-tighter opacity-60">Authorized personnel will be granted system access to manage student academic records for this semester.</p>
                </div>
              )}
           </div>
        </div>
      </div>
    </div>
  );
}

function BranchConfig({ config, branch, refresh }) {
  const [isUpdating, setIsSaving] = useState(false);

  const updatePattern = async (mid, ass) => {
    setIsSaving(true);
    try {
      const res = await fetch('/api/clerk/hod/branch-config', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          branch,
          mid_max: mid,
          assignment_max: ass,
          academic_year: '2025-26',
          semester: 6
        })
      });
      if (res.ok) {
        toast.success('Pattern updated');
        refresh();
      }
    } catch (e) {
      toast.error('Update failed');
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="animate-in fade-in duration-500">
      <h3 className="text-sm font-bold text-slate-800 mb-8 uppercase tracking-wider px-1">Institutional Departmental Directives</h3>
      
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 px-1">
        <div className="bg-white border border-slate-200 p-6 shadow-sm">
          <div className="flex items-center gap-4 mb-8 pb-4 border-b border-slate-100">
            <div className="w-10 h-10 bg-slate-50 border border-slate-200 flex items-center justify-center text-xl">📊</div>
            <div>
              <h4 className="font-bold text-slate-800 text-xs uppercase tracking-wider">Internal Assessment Schema</h4>
              <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Mandatory pattern for departmental theory subjects</p>
            </div>
          </div>

          <div className="space-y-3">
            {[
              { mid: 20, ass: 10, label: 'University Standard (20+10)' },
              { mid: 25, ass: 5, label: 'Institutional Advanced (25+5)' }
            ].map(p => (
              <button 
                key={p.mid}
                onClick={() => updatePattern(p.mid, p.ass)}
                disabled={isUpdating}
                className={`w-full p-4 flex justify-between items-center transition-all border ${config?.mid_max === p.mid ? 'border-[#0b3578] bg-blue-50/20' : 'border-slate-100 hover:border-slate-300'}`}
              >
                <div className="text-left">
                  <div className="font-bold text-slate-800 text-[11px] uppercase tracking-wide">{p.label}</div>
                  <div className="text-[8px] font-bold text-[#0b3578] uppercase tracking-widest mt-1">MID: {p.mid} | ASSIGNMENT: {p.ass}</div>
                </div>
                {config?.mid_max === p.mid && <div className="w-5 h-5 bg-[#0b3578] flex items-center justify-center text-white text-[8px] font-bold">ACTIVE</div>}
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-6">
           <div className="bg-[#0b3578] p-8 text-white border border-[#0b3578]">
              <h4 className="font-bold text-[10px] mb-2 uppercase tracking-[0.3em] text-blue-300 opacity-80">University Affiliate Branch</h4>
              <div className="text-3xl font-bold mb-1 tracking-tight">{branch}</div>
              <div className="text-[9px] font-bold text-blue-200/60 uppercase tracking-widest mb-8 border-b border-white/10 pb-4">Engineering Department Control Unit</div>
              
              <div className="grid grid-cols-2 gap-4">
                <div className="bg-white/5 p-4 border border-white/10">
                  <div className="text-[8px] font-bold text-blue-300 uppercase mb-1 tracking-widest opacity-70">Academic Period</div>
                  <div className="font-bold text-xs">2025-2026</div>
                </div>
                <div className="bg-white/5 p-4 border border-white/10">
                  <div className="text-[8px] font-bold text-blue-300 uppercase mb-1 tracking-widest opacity-70">Active Session</div>
                  <div className="font-bold text-xs uppercase">VI (Even Semester)</div>
                </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
}

'use client';
import { useState, useEffect, useRef, useCallback } from 'react';
import toast from 'react-hot-toast';

export default function MarksEntrySheet({ assignment, onBack }) {
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [midMax, setMidMax] = useState(20);
  const [recommendedMidMax, setRecommendedMidMax] = useState(null);
  const [subjectType, setSubjectType] = useState('theory'); // 'theory' | 'lab'
  const [marksMode, setMarksMode] = useState('overview'); // 'overview' | 'mid1' | 'mid2' | 'assignment'
  const [isMobile, setIsMobile] = useState(false);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [rollColWidth, setRollColWidth] = useState(0);

  const scrollContainerRef = useRef(null);
  const rollHeaderRef = useRef(null);

  const fetchStudents = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`/api/clerk/faculty/marks?assignment_id=${assignment.id}`);
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to fetch students');
      
      const payload = data.data || [];
      const detectedType = data.subject_type || 'theory';
      const isLab = detectedType === 'lab';
      const studentsWithMarks = payload.map(s => ({
        ...s,
        is_published: Boolean(s.is_published),
        mid1_marks: isLab ? (s.lab_execution_marks ?? '') : (s.mid1_marks ?? ''),
        mid2_marks: isLab ? (s.lab_theory_marks ?? '') : (s.mid2_marks ?? ''),       
        assignment_marks: isLab ? (s.lab_record_marks ?? '') : (s.assignment_marks ?? ''),
      }));
      
      setStudents(studentsWithMarks);
      setDirty(false);
      if (data.mid_max) setMidMax(data.mid_max);
      if (data.recommended_mid_max) setRecommendedMidMax(data.recommended_mid_max);
      setSubjectType(detectedType);
    } catch (error) {
      toast.error(error.message);
    } finally {
      setLoading(false);
    }
  }, [assignment.id]);

  const hasAnyMarks = students.some(s => 
    (s.mid1_marks !== '' && s.mid1_marks !== null && s.mid1_marks !== undefined) || 
    (s.mid2_marks !== '' && s.mid2_marks !== null && s.mid2_marks !== undefined) || 
    (s.assignment_marks !== '' && s.assignment_marks !== null && s.assignment_marks !== undefined)
  );

  const isPublishedLocked = students.some(s => Boolean(s.is_published));

  useEffect(() => {
    const id = setTimeout(() => {
      fetchStudents();
    }, 0);
    return () => clearTimeout(id);
  }, [fetchStudents]);

  useEffect(() => {
    const updateIsMobile = () => {
      if (typeof window !== 'undefined') {
        setIsMobile(window.innerWidth < 768);
      }
    };
    const id = setTimeout(() => {
      updateIsMobile();
    }, 0);
    window.addEventListener('resize', updateIsMobile);
    return () => {
      clearTimeout(id);
      window.removeEventListener('resize', updateIsMobile);
    };
  }, []);

  useEffect(() => {
    const id = setTimeout(() => {
      if (rollHeaderRef.current) {
        setRollColWidth(rollHeaderRef.current.offsetWidth || 0);
      }
    }, 0);

    return () => clearTimeout(id);
  }, [students.length]);

  const handleScroll = (event) => {
    setScrollLeft(event.target.scrollLeft || 0);
  };

  const getFieldMax = (field) => {
    if (subjectType === 'lab') {
      if (field === 'mid1_marks') return 10;
      if (field === 'mid2_marks') return 10;
      return 5;
    }
    if (field === 'assignment_marks') return midMax === 25 ? 5 : 10;
    return midMax;
  };

  const toNumberOrNull = (value) => {
    if (value === '' || value === null || value === undefined) return null;
    const n = typeof value === 'number' ? value : parseFloat(String(value));
    return Number.isFinite(n) ? n : null;
  };

  const computeTotal = (student) => {
    const m1 = toNumberOrNull(student.mid1_marks);
    const m2 = toNumberOrNull(student.mid2_marks);
    const a = toNumberOrNull(student.assignment_marks);

    const hasAny = m1 !== null || m2 !== null || a !== null;
    if (!hasAny) return null;

    if (subjectType === 'lab') {
      return (m1 ?? 0) + (m2 ?? 0) + (a ?? 0);
    }

    const best = Math.max(m1 ?? 0, m2 ?? 0);
    return best + (a ?? 0);
  };

  const handleMarkChange = (studentId, field, value) => {
    if (value === '') {
      setDirty(true);
      setStudents((prev) => prev.map(s => 
        s.id === studentId ? { ...s, [field]: '' } : s
      ));
      return;
    }

    let numericValue = parseFloat(value);
    if (!Number.isFinite(numericValue)) return;

    // Prevent decimal abuse: allow up to 2 decimals.
    numericValue = Math.round(numericValue * 100) / 100;

    const max = getFieldMax(field);
    if (numericValue < 0) numericValue = 0;
    if (numericValue > max) numericValue = max;

    setDirty(true);
    setStudents((prev) => prev.map(s => 
      s.id === studentId ? { ...s, [field]: numericValue } : s
    ));
  };

  const handleSave = async (publish) => {
    if (!assignment.is_active) return;
    if (isPublishedLocked) {
      toast.error('Marks already published and locked.');
      return;
    }

    if (publish) {
      const ok = confirm('Publish marks now? This will lock editing for this subject.');
      if (!ok) return;
    }

    for (const s of students) {
      const m1 = toNumberOrNull(s.mid1_marks);
      const m2 = toNumberOrNull(s.mid2_marks);
      const a = toNumberOrNull(s.assignment_marks);

      const m1Max = getFieldMax('mid1_marks');
      const m2Max = getFieldMax('mid2_marks');
      const aMax = getFieldMax('assignment_marks');

      if ((m1 !== null && (m1 < 0 || m1 > m1Max)) || (m2 !== null && (m2 < 0 || m2 > m2Max)) || (a !== null && (a < 0 || a > aMax))) {
        toast.error(`Invalid marks detected for ${s.roll_no}. Please correct them.`);
        return;
      }
    }

    setSubmitting(true);
    try {
      const res = await fetch('/api/clerk/faculty/marks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          assignment_id: assignment.id,
          mid_max: midMax,
          publish,
          marks_data: students.map(s => {
            if (subjectType === 'lab') {
              return {
                student_id: s.id,
                lab_theory_marks: s.mid2_marks === '' ? null : s.mid2_marks,
                lab_execution_marks: s.mid1_marks === '' ? null : s.mid1_marks,
                lab_record_marks: s.assignment_marks === '' ? null : s.assignment_marks,
              };
            }
            return {
              student_id: s.id,
              mid1_marks: s.mid1_marks === '' ? null : s.mid1_marks,
              mid2_marks: s.mid2_marks === '' ? null : s.mid2_marks,
              assignment_marks: s.assignment_marks === '' ? null : s.assignment_marks,
            };
          })
        })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to save marks');

      toast.success(publish ? 'Marks published and locked.' : 'Draft saved successfully.');
      await fetchStudents();
    } catch (error) {
      toast.error(error.message);
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <div className="text-center py-10 text-sm text-gray-600">Loading students and departmental recommendations...</div>;

  const labels = subjectType === 'lab' 
    ? { m1: 'Execution', m2: 'Writing', a: 'Record', m1m: 10, m2m: 10, am: 5, total: 25 }
    : { m1: 'Mid-1', m2: 'Mid-2', a: 'Assignment', m1m: midMax, m2m: midMax, am: (midMax === 25 ? 5 : 10), total: 30 };

  const modeMeta = {
    overview: { label: 'Overview', field: 'all', max: labels.total },
    mid1: { label: labels.m1, field: 'mid1_marks', max: labels.m1m },
    mid2: { label: labels.m2, field: 'mid2_marks', max: labels.m2m },
    assignment: { label: labels.a, field: 'assignment_marks', max: labels.am },
  };

  const activeMode = modeMeta[marksMode] || modeMeta.overview;

  const handleBack = () => {
    if (dirty && !confirm('You have unsaved changes. Go back without saving?')) return;
    onBack();
  };

  return (
    <div className="border border-slate-300 rounded-sm bg-white p-3 mt-4 shadow-sm">
      {/* Compact Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 gap-4 border-b border-slate-100 pb-3">
        <div className="flex flex-col gap-1">
          <button onClick={handleBack} className="text-[10px] font-bold text-slate-500 uppercase tracking-wider hover:text-indigo-600 flex items-center gap-1">
            <span className="text-sm">←</span> BACK TO SUBJECTS
          </button>
          <div className="flex items-center gap-2">
            <h2 className="text-lg font-bold text-slate-800 leading-tight">{assignment.subject_name}</h2>
            <span className={`text-[9px] font-bold uppercase px-1.5 py-0.5 rounded-sm border ${subjectType === 'lab' ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-indigo-50 border-indigo-200 text-indigo-700'}`}>{subjectType === 'lab' ? 'LAB' : 'THEORY'}</span>
            {isPublishedLocked ? (
              <span className="text-[9px] font-bold uppercase px-1.5 py-0.5 rounded-sm border bg-rose-50 border-rose-200 text-rose-700">PUBLISHED</span>
            ) : hasAnyMarks ? (
              <span className="text-[9px] font-bold uppercase px-1.5 py-0.5 rounded-sm border bg-slate-50 border-slate-200 text-slate-500">DRAFT</span>
            ) : null}
          </div>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tight">
            {assignment.branch} • SEM {assignment.semester} • {assignment.academic_year}
          </p>
        </div>
        
        <div className="flex flex-wrap items-center gap-3">
          {/* Mode Switching (Government Style) */}
          <div className="flex border border-slate-200 rounded-sm overflow-hidden">
            {Object.keys(modeMeta).map((m) => (
              <button
                key={m}
                type="button"
                onClick={() => setMarksMode(m)}
                className={`px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider transition-colors border-r last:border-r-0 border-slate-200 ${marksMode === m ? 'bg-slate-800 text-white' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}
              >
                {modeMeta[m].label}
              </button>
            ))}
          </div>

          {/* Action Buttons (Compact Utility) */}
          {assignment.is_active ? (
            isPublishedLocked ? (
              <div className="bg-rose-50 text-rose-700 px-3 py-1.5 rounded-sm text-[9px] font-bold uppercase border border-rose-200">LOCKED</div>
            ) : (
              <div className="flex items-center gap-2">
                <button
                  onClick={() => handleSave(false)}
                  disabled={submitting}
                  className="bg-white text-slate-700 px-3 py-1.5 rounded-sm text-[10px] font-bold uppercase tracking-wider border border-slate-300 hover:bg-slate-50 disabled:opacity-50"
                >
                  {submitting ? '...' : 'SAVE DRAFT'}
                </button>
                <button
                  onClick={() => handleSave(true)}
                  disabled={submitting}
                  className="bg-indigo-600 text-white px-3 py-1.5 rounded-sm text-[10px] font-bold uppercase tracking-wider hover:bg-indigo-700 disabled:opacity-50"
                >
                  {submitting ? '...' : 'PUBLISH'}
                </button>
              </div>
            )
          ) : (
            <div className="bg-slate-100 text-slate-500 px-3 py-1.5 rounded-sm text-[9px] font-bold uppercase border border-slate-200">FINALIZED</div>
          )}
        </div>
      </div>

      <div ref={scrollContainerRef} onScroll={isMobile ? handleScroll : undefined} className="overflow-x-auto border border-slate-200">
        <table className="w-full text-xs border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th ref={rollHeaderRef} className={`px-2 py-2 text-center text-[10px] font-bold text-slate-500 uppercase tracking-wider border-r border-slate-200 ${isMobile ? 'sticky left-0 z-10 bg-slate-50' : ''}`}>Roll No</th>
              <th className="px-2 py-2 text-left text-[10px] font-bold text-slate-500 uppercase tracking-wider border-r border-slate-200">Student Name</th>
              
              {marksMode === 'overview' ? (
                <>
                  <th className="px-2 py-2 text-center text-[10px] font-bold text-slate-500 uppercase tracking-wider border-r border-slate-200 hidden md:table-cell">{labels.m1}</th>
                  <th className="px-2 py-2 text-center text-[10px] font-bold text-slate-500 uppercase tracking-wider border-r border-slate-200 hidden md:table-cell">{labels.m2}</th>
                  <th className="px-2 py-2 text-center text-[10px] font-bold text-slate-500 uppercase tracking-wider border-r border-slate-200 hidden md:table-cell">{labels.a}</th>
                  <th className="px-2 py-2 text-center text-[10px] font-bold text-indigo-700 uppercase tracking-wider bg-indigo-50/50 hidden md:table-cell">Total</th>
                  {/* Mobile Overview: Show only Total if in Overview? Prompt says: "MOBILE MUST SHOW ONLY: Roll Number, Student Name, Active Mode Marks." */}
                  {/* "OVERVIEW MODE | Roll No | Student | M1 | M2 | ASG | Total |" on Desktop */}
                  {/* On Mobile Overview, let's show Total as the "Active Marks" */}
                  <th className="px-2 py-2 text-center text-[10px] font-bold text-indigo-700 uppercase tracking-wider md:hidden">Total</th>
                </>
              ) : (
                <th className="px-2 py-2 text-center text-[10px] font-bold text-slate-500 uppercase tracking-wider">{activeMode.label} ({activeMode.max})</th>
              )}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {students.map((student) => {
              const internalTotal = computeTotal(student);
              const fullRoll = student.roll_no || '';
              const showCompact = isMobile && scrollLeft > rollColWidth;
              const shortRoll = fullRoll.endsWith('L') ? fullRoll.slice(-3) : fullRoll.slice(-2);
              const disabled = !assignment.is_active || isPublishedLocked;

              return (
                <tr key={student.id} className="hover:bg-slate-50 transition-colors group">
                  <td className={`px-2 py-1.5 font-mono font-bold text-center border-r border-slate-100 ${isMobile ? 'sticky left-0 z-10 bg-white group-hover:bg-slate-50' : ''}`}>
                    <span className={`inline-block transition-all ${isMobile && showCompact ? 'opacity-0 scale-50' : 'opacity-100 scale-100'}`}>{fullRoll}</span>
                    {isMobile && <span className={`absolute inset-0 flex items-center justify-center transition-all ${showCompact ? 'opacity-100 scale-100' : 'opacity-0 scale-50'}`}>{shortRoll}</span>}
                  </td>
                  <td className="px-2 py-1.5 border-r border-slate-100">
                    <div className="text-[11px] font-bold text-slate-700 uppercase whitespace-nowrap overflow-hidden text-ellipsis max-w-[150px] md:max-w-none" title={student.name}>
                      {student.name}
                    </div>
                  </td>
                  
                  {marksMode === 'overview' ? (
                    <>
                      <td className="px-2 py-1.5 text-center font-mono text-slate-600 border-r border-slate-100 hidden md:table-cell">{student.mid1_marks === '' ? '-' : student.mid1_marks}</td>
                      <td className="px-2 py-1.5 text-center font-mono text-slate-600 border-r border-slate-100 hidden md:table-cell">{student.mid2_marks === '' ? '-' : student.mid2_marks}</td>
                      <td className="px-2 py-1.5 text-center font-mono text-slate-600 border-r border-slate-100 hidden md:table-cell">{student.assignment_marks === '' ? '-' : student.assignment_marks}</td>
                      <td className="px-2 py-1.5 text-center font-mono font-bold text-indigo-700 bg-indigo-50/20 hidden md:table-cell">{internalTotal !== null ? internalTotal.toFixed(1) : '-'}</td>
                      <td className="px-2 py-1.5 text-center font-mono font-bold text-indigo-700 md:hidden">{internalTotal !== null ? internalTotal.toFixed(1) : '-'}</td>
                    </>
                  ) : (
                    <td className="px-2 py-1.5 text-center">
                      <input
                        type="number"
                        min="0"
                        max={activeMode.max}
                        step="0.5"
                        value={student[activeMode.field]}
                        onChange={(e) => handleMarkChange(student.id, activeMode.field, e.target.value)}
                        className="w-full max-w-[80px] px-1 py-1 bg-slate-50 border border-slate-200 rounded-sm text-center text-[11px] font-bold text-slate-800 focus:bg-white focus:border-indigo-500 outline-none disabled:opacity-50"
                        disabled={disabled}
                        inputMode="decimal"
                      />
                    </td>
                  )}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

'use client';
import { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import FacultyAcademicCalendar from './FacultyAcademicCalendar';
import { useFacultyAttendance } from '@/context/FacultyAttendanceContext';

const formatDisplayDate = (dateStr) => {
  if (!dateStr) return '—';
  const parts = dateStr.split('-');
  if (parts.length !== 3) return dateStr;
  const [year, month, day] = parts;
  return `${day}-${month}-${year}`;
};

const MobileSubjectIdentityPanel = () => {
  const { assignment } = useFacultyAttendance();
  return (
    <div className="bg-white border-b shadow-sm p-3 mb-4 sticky top-[52px] z-20">
      <div className="flex justify-between items-start gap-2">
        <div className="flex-1">
          <h2 className="text-sm font-black text-gray-900 uppercase leading-tight line-clamp-1">{assignment.subject_name}</h2>
          <div className="flex items-center gap-2 mt-1">
            <span className="text-[10px] font-bold bg-gray-100 px-1.5 py-0.5 rounded text-gray-600 uppercase">{assignment.subject_code}</span>
            <span className="text-[10px] font-bold text-indigo-600">{assignment.branch} • Sem {assignment.semester}</span>
          </div>
        </div>
        <div className={`text-[10px] font-black px-2 py-1 rounded-full shrink-0 ${assignment.is_active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}`}>
          {assignment.is_active ? 'ACTIVE' : 'HISTORY'}
        </div>
      </div>
    </div>
  );
};

const MobileSessionControlPanel = () => {
  const { 
    activeSession, 
    startSession, 
    endSession, 
    submitting, 
    selectedDate, 
    dateValidation,
    verifiedStudentIds,
    students,
    setAttendanceStatus,
    fetchAttendanceStatus
  } = useFacultyAttendance();

  const verifiedList = students.filter(s => verifiedStudentIds.has(s.id));

  const handleConfirmAll = () => {
    students.forEach(s => {
      if (verifiedStudentIds.has(s.id)) {
        setAttendanceStatus(s.id, 'PRESENT');
      } else if (s.status === null) {
        setAttendanceStatus(s.id, 'ABSENT');
      }
    });
    toast.success(`Marked verified students as PRESENT and others as ABSENT.`);
  };

  return (
    <div className="bg-indigo-50 border-2 border-indigo-200 p-4 rounded-xl mb-6 shadow-sm">
      <h3 className="text-indigo-900 font-bold flex items-center gap-2 text-sm mb-3">
        <span className="relative flex h-3 w-3">
          <span className={`animate-ping absolute inline-flex h-full w-full rounded-full ${activeSession ? 'bg-green-400' : 'bg-gray-400'} opacity-75`}></span>
          <span className={`relative inline-flex rounded-full h-3 w-3 ${activeSession ? 'bg-green-500' : 'bg-gray-500'}`}></span>
        </span>
        SECURE ATTENDANCE
      </h3>

      {activeSession ? (
        <div className="space-y-4">
          <div className="flex items-center justify-between gap-4">
            <div className="flex-1 bg-white p-3 rounded-lg border border-indigo-100 text-center">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-0.5">PIN</p>
              <p className="text-3xl font-black text-indigo-600 tracking-tight">{activeSession.session_pin}</p>
            </div>
            <button
              onClick={endSession}
              disabled={submitting}
              className="px-4 py-3 bg-red-600 text-white text-xs font-bold rounded-lg uppercase shadow-sm active:bg-red-700"
            >
              End
            </button>
          </div>

          {/* Live verification list for mobile */}
          <div className="bg-white p-3 rounded-lg border border-indigo-100 shadow-inner">
            <div className="flex justify-between items-center mb-2">
              <div className="flex items-center gap-2">
                <span className="text-[10px] font-black text-indigo-400 uppercase tracking-wider">Live Logs ({verifiedList.length})</span>
                <button 
                  onClick={() => {
                    fetchAttendanceStatus();
                    toast.success('List updated', { duration: 1000, id: 'mobile-refresh' });
                  }}
                  className="p-1 text-indigo-500 hover:bg-indigo-50 rounded-full transition-all group"
                >
                  <svg className="w-3.5 h-3.5 group-active:rotate-180 transition-transform duration-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                </button>
              </div>
              {verifiedList.length > 0 && (
                <button 
                  onClick={handleConfirmAll}
                  className="text-[9px] bg-indigo-600 text-white px-2 py-1 rounded-md font-bold uppercase active:scale-95 transition-all"
                >
                  Confirm All
                </button>
              )}
            </div>
            <div className="flex flex-wrap gap-1.5 max-h-20 overflow-y-auto pr-1">
              {verifiedList.length > 0 ? verifiedList.map(s => (
                <div key={s.id} className="text-[9px] font-bold bg-green-50 text-green-700 px-1.5 py-0.5 rounded border border-green-100">
                  {s.roll_no}
                </div>
              )) : (
                <p className="text-[9px] text-gray-400 italic">No one has entered PIN yet...</p>
              )}
            </div>
          </div>
        </div>
      ) : (
        <button
          onClick={startSession}
          disabled={submitting || !selectedDate || !dateValidation.isValid}
          className="w-full py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-md flex items-center justify-center gap-2 text-sm active:bg-indigo-700 disabled:opacity-50 disabled:grayscale"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 11c0 3.517-1.009 6.799-2.753 9.571m-3.44-2.04l.054-.09A10.003 10.003 0 0012 3c4.183 0 7.66 2.567 9.106 6H22.25m-9.448 10a10.003 10.003 0 01-1.106-2.04m0 0l.054-.09A10.003 10.003 0 0122.5 12"></path></svg>
          START SECURE SESSION
        </button>
      )}
    </div>
  );
};

const MobilePendingSyncIndicator = () => {
  const { pendingSyncs, syncOfflineAttendance, submitting } = useFacultyAttendance();

  if (!pendingSyncs || pendingSyncs.length === 0) return null;

  return (
    <div className="bg-amber-50 border-2 border-amber-200 p-3 rounded-xl mb-4 shadow-sm">
      <div className="flex justify-between items-start gap-3">
        <div className="flex-1">
          <h3 className="text-amber-900 font-black text-[10px] uppercase tracking-wider">Offline Sync Pending ({pendingSyncs.length})</h3>
          <p className="text-[10px] text-amber-700 mt-0.5 leading-tight">
            Recorded while offline. Click to sync with server.
          </p>
        </div>
        <button
          onClick={() => syncOfflineAttendance()}
          disabled={submitting}
          className="px-3 py-1.5 bg-amber-600 text-white text-[9px] font-black uppercase tracking-widest rounded-md shadow-sm active:scale-95 disabled:opacity-50"
        >
          {submitting ? '...' : 'Sync Now'}
        </button>
      </div>
      <div className="mt-2 flex gap-1 overflow-x-auto no-scrollbar">
        {pendingSyncs.map(p => (
          <div key={p.id} className="text-[8px] font-bold bg-white/60 text-amber-800 px-1.5 py-0.5 rounded border border-amber-100 whitespace-nowrap">
            {p.date} • S{p.session}
          </div>
        ))}
      </div>
    </div>
  );
};

export default function MobileAttendanceSheet({ onBack }) {
  const {
    assignment,
    students,
    loading,
    statusLoading,
    selectedDate,
    selectedSession,
    setSelectedSession,
    setAttendanceStatus,
    submitting,
    dateValidation,
    dayInfo,
    existingSessionsForSelectedDate,
    handleSaveAttendance,
    handleDeleteAttendance,
    handleCalendarSelect,
    toggleAttendanceStatus,
    setAllAttendanceStatus,
    verifiedStudentIds
  } = useFacultyAttendance();

  return (
    <div className="pb-24">
      {/* Back Button */}
      <button onClick={onBack} className="text-sm font-medium text-indigo-600 hover:text-indigo-800 mb-4 inline-flex items-center">
        <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7"></path></svg>
        Back to Subjects
      </button>

      {/* Pending Sync (Mobile) */}
      <MobilePendingSyncIndicator />

      {/* Subject Identity Panel */}
      <MobileSubjectIdentityPanel />

      {/* SECURE SESSION PANEL (MOBILE) */}
      {assignment.is_active && <MobileSessionControlPanel />}

      {/* FACULTY ACADEMIC CALENDAR (MOBILE) */}
      <FacultyAcademicCalendar
        assignment={assignment}
        selectedDate={selectedDate}
        onSelectDate={handleCalendarSelect}
        attendanceSectionId="mobile-faculty-attendance-section"
      />

      {/* ATTENDANCE ENTRY SECTION */}
      <section id="mobile-faculty-attendance-section" className="bg-white p-4 rounded-lg border-2 mb-6">
        <div className="mb-4 border-b pb-3 flex flex-col gap-2">
          <div>
            <p className="text-[11px] font-bold text-gray-500 tracking-[0.18em] uppercase">ATTENDANCE ENTRY</p>
            <p className="text-xs text-gray-600 mt-1">
              Select a WORKING day from the calendar to record attendance.
            </p>
          </div>
          <div className="flex justify-between text-[11px] text-gray-600">
            <div>
              <span className="font-semibold mr-2">DATE</span>
              <span className="font-mono text-gray-900">{selectedDate ? formatDisplayDate(selectedDate) : '—'}</span>
            </div>
            <div className="text-right">
              <span className="font-semibold mr-2">DAY TYPE</span>
              <span className="font-semibold text-gray-900">{dayInfo?.day_type || '—'}</span>
            </div>
          </div>
        </div>

        {!selectedDate && (
          <div className="text-xs text-gray-600 bg-gray-50 border border-dashed border-gray-300 rounded-md p-3 mb-2">
            Select a WORKING day in the academic calendar above to enable attendance entry.
          </div>
        )}

        {selectedDate && !dateValidation.isValid && (
          <div className="text-xs text-red-700 bg-red-50 border border-red-200 rounded-md p-3 mb-3 font-semibold">
            {dateValidation.message}
          </div>
        )}

        {selectedDate && dateValidation.isValid && (
          <>
            {/* Session Selector */}
            <div className="mb-4">
              <div className="flex items-center justify-between mb-2">
                <label className="text-[11px] font-bold text-gray-500 uppercase">Sessions</label>
                {verifiedStudentIds.size > 0 && (
                  <div className="flex items-center gap-1 bg-green-50 px-2 py-0.5 rounded border border-green-100">
                    <span className="flex h-1.5 w-1.5 rounded-full bg-green-500 animate-pulse"></span>
                    <span className="text-[9px] font-black text-green-700">{verifiedStudentIds.size} VERIFIED</span>
                  </div>
                )}
              </div>
              <div className="flex gap-1 overflow-x-auto pb-1 no-scrollbar">
                {[1, 2, 3, 4, 5].map(num => {
                  const isExisting = existingSessionsForSelectedDate.includes(num);
                  const isAllowedSequential = num === 1 || existingSessionsForSelectedDate.includes(num - 1);
                  const isDisabled = !assignment.is_active || !isAllowedSequential;
                  const isSelected = selectedSession === num;

                  return (
                    <button
                      key={num}
                      type="button"
                      onClick={() => !isDisabled && setSelectedSession(num)}
                      disabled={isDisabled}
                      className={`flex-1 h-10 rounded-lg text-[11px] font-black flex items-center justify-center min-w-[50px] border-2 transition-all ${
                        isSelected
                          ? 'bg-indigo-600 text-white border-indigo-600 shadow-sm'
                          : isExisting
                          ? 'bg-indigo-50 text-indigo-900 border-indigo-100'
                          : 'bg-white text-gray-400 border-gray-100'
                      } ${isDisabled ? 'opacity-30' : 'active:scale-95'}`}
                    >
                      S{num}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Action Buttons (Condensed) */}
            <div className="space-y-2 mb-6">
              {assignment.is_active && (
                <>
                  <div className="grid grid-cols-2 gap-2">
                    <button
                      type="button"
                      onClick={() => assignment.is_active && dateValidation.isValid && setAllAttendanceStatus('PRESENT')}
                      disabled={submitting || !students.length}
                      className="bg-green-50 text-green-700 py-2.5 rounded-xl font-bold text-[10px] uppercase border-2 border-green-100 active:bg-green-100"
                    >
                      All Present
                    </button>
                    <button
                      type="button"
                      onClick={() => assignment.is_active && dateValidation.isValid && setAllAttendanceStatus('ABSENT')}
                      disabled={submitting || !students.length}
                      className="bg-red-50 text-red-700 py-2.5 rounded-xl font-bold text-[10px] uppercase border-2 border-red-100 active:bg-red-100"
                    >
                      All Absent
                    </button>
                  </div>
                  
                  {selectedSession > 1 && existingSessionsForSelectedDate.includes(selectedSession - 1) && (
                    <FollowPreviousMobileButton
                      assignment={assignment}
                      prevSession={selectedSession - 1}
                      selectedDate={selectedDate}
                      students={students}
                      setAttendanceStatus={setAttendanceStatus}
                    />
                  )}
                </>
              )}
            </div>

            {/* Mobile Table */}
            <div className="mt-2">
              {loading && students.length === 0 ? (
                <div className="text-center py-4 text-gray-500 text-xs">Loading students...</div>
              ) : students.length > 0 ? (
                <table className="w-full table-fixed border-collapse">
                  <colgroup>
                    <col style={{ width: '28%' }} />
                    <col style={{ width: '52%' }} />
                    <col style={{ width: '20%' }} />
                  </colgroup>
                  <thead>
                    <tr className="bg-gray-50">
                      <th className="px-3 py-2 text-left font-semibold text-gray-600 text-[12px]">Roll No</th>
                      <th className="px-3 py-2 text-left font-semibold text-gray-600 text-[12px]">Name</th>
                      <th className="px-3 py-2 text-center font-semibold text-gray-600 text-[12px]">
                        <span className="inline-flex items-center justify-center gap-1">
                          <span>Status</span>
                          {statusLoading && (
                            <span className="inline-block h-3 w-3 border-2 border-gray-400 border-t-transparent rounded-full animate-spin" />
                          )}
                        </span>
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {students.map(student => (
                      <tr key={student.id} className="hover:bg-gray-50">
                        <td className="px-3 py-2 align-middle font-mono text-gray-800 text-[12px] font-semibold">
                          <div className="flex items-center gap-1">
                            {student.roll_no}
                            {verifiedStudentIds.has(student.id) && (
                              <span className="flex h-1.5 w-1.5 rounded-full bg-green-500 animate-pulse"></span>
                            )}
                          </div>
                        </td>
                        <td className="px-3 py-2 align-middle text-gray-800 text-[13px] font-medium break-words">
                          {student.name}
                          {verifiedStudentIds.has(student.id) && (
                            <div className="text-[8px] font-black text-green-600 uppercase">Verified</div>
                          )}
                        </td>
                        <td className="px-3 py-2 align-middle text-center">
                          {statusLoading ? (
                            <span className="inline-block h-6 w-6 border-2 border-gray-300 border-t-transparent rounded-full animate-spin" />
                          ) : (
                            <button
                              type="button"
                              onClick={() => assignment.is_active && dateValidation.isValid && toggleAttendanceStatus(student.id)}
                              disabled={!assignment.is_active || !dateValidation.isValid}
                              style={{ width: '56px', height: '32px', textAlign: 'center', fontWeight: 700, fontSize: '12px', borderRadius: '6px' }}
                              className={`${
                                student.status === null 
                                  ? 'bg-gray-100 text-gray-700' 
                                  : student.status === 'PRESENT' 
                                  ? 'bg-green-100 text-green-800' 
                                  : student.status === 'ABSENT' 
                                  ? 'bg-red-100 text-red-800'
                                  : student.status === 'NCC'
                                  ? 'bg-blue-100 text-blue-800'
                                  : student.status === 'MEDICAL'
                                  ? 'bg-purple-100 text-purple-800'
                                  : 'bg-gray-100 text-gray-700'
                              } ${(!assignment.is_active || !dateValidation.isValid) ? 'cursor-default opacity-50' : 'cursor-pointer'}`}
                            >
                              {student.status === null ? 'N/A' : 
                               student.status === 'PRESENT' ? 'P' : 
                               student.status === 'ABSENT' ? 'A' :
                               student.status === 'NCC' ? 'NCC' :
                               student.status === 'MEDICAL' ? 'M' : '?'}
                            </button>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <div className="text-center py-4 text-gray-500 text-xs">No students found.</div>
              )}
            </div>
          </>
        )}
      </section>

      {/* STICKY BOTTOM ACTION BAR */}
      {selectedDate && dateValidation.isValid && assignment.is_active && (
        <div className="fixed bottom-0 left-0 right-0 bg-white border-t p-4 flex gap-3 z-30 shadow-[0_-4px_10px_rgba(0,0,0,0.05)]">
          <button
            type="button"
            onClick={handleDeleteAttendance}
            disabled={submitting || !existingSessionsForSelectedDate.includes(selectedSession)}
            className="p-3 text-red-600 border-2 border-red-50 rounded-xl active:bg-red-50 disabled:opacity-30"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
          </button>
          <button
            type="button"
            onClick={handleSaveAttendance}
            disabled={submitting || !students.length}
            className="flex-1 bg-indigo-600 text-white font-black py-3 rounded-xl shadow-lg shadow-indigo-200 active:scale-[0.98] transition-all flex items-center justify-center gap-2 uppercase tracking-wider text-sm disabled:bg-gray-300 disabled:shadow-none"
          >
            {submitting ? (
              <span className="inline-block h-4 w-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
            ) : (
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
            )}
            Save Session S{selectedSession}
          </button>
        </div>
      )}
    </div>
  );
}

  {/* Follow Previous Mobile Button Component */}
  function FollowPreviousMobileButton({ assignment, prevSession, selectedDate, students, setAttendanceStatus }) {
    const [loading, setLoading] = useState(false);

    const handleFollow = async () => {
      if (!assignment?.id || !selectedDate) return;
      setLoading(true);
      try {
        const url = `/api/clerk/faculty/attendance/status?assignment_id=${assignment.id}&date=${encodeURIComponent(
          selectedDate,
        )}&session=${encodeURIComponent(prevSession)}`;
        const res = await fetch(url);
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Failed to fetch previous session');

        const statusMap = (data.data || []).reduce((acc, r) => {
          acc[r.student_id] = r.status;
          return acc;
        }, { /* empty */ });

        (students || []).forEach((s) => {
          setAttendanceStatus(s.id, statusMap[s.id] ?? null);
        });

        toast.success('Session attendance copied from previous session');
      } catch (err) {
        toast.error(err.message || 'Unable to copy previous session');
      } finally {
        setLoading(false);
      }
    };

    return (
      <button
        type="button"
        onClick={handleFollow}
        disabled={loading}
        className="w-full py-2 rounded-lg bg-white border border-gray-300 text-sm font-semibold text-gray-700 hover:bg-gray-50 disabled:opacity-60"
      >
        {loading ? 'Copying…' : 'Follow previous session'}
      </button>
    );
  }

'use client';

import { useState, useEffect, useCallback } from 'react';
import { toast } from 'react-hot-toast';
import RealtimeListener from '@/components/RealtimeListener';

const INSTITUTIONAL_ACTIVITIES = [
  { code: 'SPORTS', name: 'Sports & Athletics' },
  { code: 'MINI_PROJECT', name: 'Mini Projects' },
  { code: 'EXTRA_CURRICULAR', name: 'Extra Curricular Activities' },
  { code: 'SEMINAR', name: 'Seminars / Workshops' },
  { code: 'LIB', name: 'Library Period' }
];

export default function PersonalSchedule() {
  const [schedule, setSchedule] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchMySchedule = useCallback(async () => {
    try {
      const res = await fetch('/api/clerk/faculty/my-timetable');
      const data = await res.json();
      if (res.ok) {
        setSchedule(data.data || []);
      } else {
        setError(data.error || 'Failed to fetch schedule');
      }
    } catch (e) {
      setError('Network error - could not sync your schedule');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    const id = setTimeout(() => {
      fetchMySchedule();
    }, 0);
    return () => clearTimeout(id);
  }, [fetchMySchedule]);

  const handleRealtimeUpdate = (data) => {
    if (data.type === 'TIMETABLE_CHANGED') {
      console.info('[FacultySchedule] Server broadcast received, syncing...');
      fetchMySchedule();
    }
  };

  const days = ['MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
  const periods = [1, 2, 3, 4, 5, 6, 7];
  const getSlot = (day, p) => schedule.find(s => s.day_of_week === day && s.period_number === p);

  if (loading) return (
    <div className="bg-white p-12 border border-slate-200 flex flex-col items-center justify-center gap-4">
       <div className="w-8 h-8 border-2 border-[#0b3578] border-t-transparent animate-spin"></div>
       <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">Synchronizing Teaching Schedule...</p>
    </div>
  );

  if (error) return (
    <div className="bg-white p-12 border border-red-100 flex flex-col items-center justify-center text-center gap-4">
       <div className="text-3xl">⚠️</div>
       <div>
          <h3 className="text-sm font-bold text-slate-800 uppercase tracking-tight">Sync Failed</h3>
          <p className="text-xs text-slate-500 max-w-sm mx-auto mt-1 font-medium">{error}</p>
       </div>
       <button onClick={fetchMySchedule} className="mt-2 px-4 py-2 bg-[#0b3578] text-white font-bold text-[10px] uppercase tracking-widest hover:bg-blue-900 transition-all">Try Again</button>
    </div>
  );

  return (
    <>
      <RealtimeListener onUpdate={handleRealtimeUpdate} />
      <div className="bg-white border border-slate-200 shadow-sm overflow-hidden">
        <div className="bg-[#0b3578] px-6 py-4 text-white flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div>
            <h2 className="text-sm font-bold tracking-wider uppercase">Weekly Teaching Matrix</h2>
            <p className="text-blue-200 text-[9px] font-medium uppercase tracking-widest mt-0.5 opacity-80">Academic Year 2025-26 &bull; Official Registry</p>
          </div>
          <div className="bg-white/10 px-3 py-1 border border-white/20 text-[10px] font-bold uppercase tracking-tighter">
            {schedule.length} Periods Recorded
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse min-w-[800px]">
            <thead>
              <tr>
                <th className="p-3 bg-slate-50 border-b border-r border-slate-200 text-slate-500 text-[9px] font-bold uppercase tracking-widest w-20">Day</th>
                {periods.map(p => (
                  <th key={p} className="p-3 bg-slate-50 border-b border-slate-200">
                    <div className="text-slate-700 font-bold text-[9px] uppercase tracking-widest mb-0.5">Period {p}</div>
                    <div className="text-[8px] font-medium text-slate-400 uppercase tracking-tighter">
                      {p === 1 && '09:30 - 10:20'}
                      {p === 2 && '10:20 - 11:10'}
                      {p === 3 && '11:20 - 12:10'}
                      {p === 4 && '12:10 - 01:00'}
                      {p === 5 && '02:00 - 02:50'}
                      {p === 6 && '02:50 - 03:40'}
                      {p === 7 && '03:40 - 04:30'}
                    </div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {days.map(day => (
                <tr key={day}>
                  <td className="p-3 border-b border-r border-slate-200 bg-slate-50/50 font-bold text-slate-600 text-center text-[10px]">{day}</td>
                  {periods.map(p => {
                    const slot = getSlot(day, p);
                    const activity = slot ? INSTITUTIONAL_ACTIVITIES.find(a => a.code === slot.subject_code) : null;
                    const isActivity = !!activity;

                    return (
                      <td key={`${day}-${p}`} className={`p-3 border-b border-r border-slate-200 text-center transition-colors ${slot ? (isActivity ? 'bg-amber-50/20' : 'bg-slate-50/30') : 'bg-slate-50/30'}`}>
                        {slot ? (
                          <div className={`flex flex-col gap-1 border rounded-sm px-2.5 py-2 shadow-sm ${isActivity ? 'bg-amber-50 border-amber-200' : 'bg-white border-slate-200'}`}>
                            <div className={`font-bold text-[10px] uppercase leading-tight line-clamp-2 ${isActivity ? 'text-amber-800' : 'text-[#0b3578]'}`}>
                              {activity ? activity.name : (slot.display_name || slot.subject_code)}
                            </div>
                            <div className="flex flex-col gap-0.5">
                              <div className="text-[8px] font-bold text-slate-500 uppercase tracking-tighter">
                                {slot.branch} &bull; S{slot.semester}
                              </div>
                              {slot.room_no && (
                                <div className="text-[8px] font-bold text-emerald-700 tracking-widest uppercase">Room {slot.room_no}</div>
                              )}
                            </div>
                          </div>
                        ) : (
                          <span className="text-[8px] font-bold text-slate-300 uppercase tracking-widest italic opacity-70">Free</span>
                        )}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="p-4 bg-slate-50 border-t border-slate-200 flex flex-wrap gap-6 justify-center items-center">
           <div className="flex items-center gap-2">
              <span className="text-xs">☕</span>
              <div className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Short Break: 11:10 AM</div>
           </div>
           <div className="flex items-center gap-2">
              <span className="text-xs">🍱</span>
              <div className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Lunch Break: 01:00 PM</div>
           </div>
        </div>
      </div>
    </>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { toast } from 'react-hot-toast';

export default function SyllabusManager({ branch }) {
  const [syllabus, setSyllabus] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedSem, setSelectedSem] = useState(6);
  const [editingSubject, setEditingSubject] = useState(null);

  const fetchSyllabus = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`/api/clerk/hod/syllabus?semester=${selectedSem}`);
      const data = await res.json();
      if (res.ok) setSyllabus(data.data);
    } catch (e) {
      toast.error('Failed to load syllabus');
    } finally {
      setLoading(false);
    }
  }, [selectedSem]);

  useEffect(() => {
    const id = setTimeout(() => {
      fetchSyllabus();
    }, 0);
    return () => clearTimeout(id);
  }, [fetchSyllabus]);

  const handleDeleteSubject = async (code) => {
    if (!confirm('Are you sure you want to remove this subject from your branch syllabus?')) return;
    try {
      const res = await fetch('/api/clerk/hod/syllabus', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'DELETE_SUBJECT', subject: { subject_code: code } })
      });
      if (res.ok) {
        toast.success('Subject removed');
        fetchSyllabus();
      }
    } catch (e) {
      toast.error('Delete failed');
    }
  };

  const handleSaveSubject = async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    const payload = {
      action: 'ADD_SUBJECT',
      subject: {
        subject_code: formData.get('code'),
        subject_name: formData.get('name'),
        subject_type: formData.get('type'),
        semester: selectedSem
      }
    };
    try {
      const res = await fetch('/api/clerk/hod/syllabus', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      if (res.ok) {
        toast.success('Subject saved');
        setEditingSubject(null);
        fetchSyllabus();
      }
    } catch (e) {
      toast.error('Save failed');
    }
  };

  return (
    <div className="animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
          <h3 className="text-base font-bold text-slate-900 uppercase tracking-[0.22em] flex items-center gap-3">
            <span className="inline-flex h-9 w-9 items-center justify-center bg-blue-50 text-[#0b3578] border border-blue-100 rounded-sm text-sm">📖</span>
            Branch Syllabus
          </h3>
          <p className="text-[10px] text-slate-700 font-bold uppercase mt-1 tracking-[0.22em]">Branch: {branch}</p>
        </div>
        
        <div className="flex gap-1 bg-slate-50 border border-slate-300 p-1 rounded-sm shadow-sm">
          {[1,2,3,4,5,6,7,8].map(s => (
            <button 
              key={s} 
              onClick={() => setSelectedSem(s)}
              className={`w-10 h-10 rounded-sm font-bold text-[10px] uppercase tracking-widest transition-colors ${selectedSem === s ? 'bg-[#0b3578] text-white shadow-sm' : 'text-slate-700 hover:bg-white'}`}
            >
              S{s}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6">
        <button 
          onClick={() => setEditingSubject({ /* empty */ })}
          className="w-full py-3 border border-white/25 rounded-sm text-white font-bold uppercase tracking-[0.22em] text-[10px] bg-[#0b3578] hover:bg-blue-900 transition-colors group shadow-lg shadow-blue-100"
        >
          <span className="group-hover:scale-110 inline-block transition-transform mr-2">+</span> Add New Subject to Semester {selectedSem}
        </button>

        {loading ? (
          <div className="text-center py-16 text-slate-500 font-bold text-[10px] uppercase tracking-[0.2em] animate-pulse border border-slate-200 bg-white rounded-sm">
            Synchronizing Syllabus...
          </div>
        ) : (
          syllabus.map(sub => (
            <div key={sub.subject_code} className="bg-white border border-slate-300 rounded-sm overflow-hidden group hover:border-slate-400 transition-colors shadow-sm">
              <div className="p-5 flex justify-between items-start gap-4 bg-slate-50">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-[10px] font-bold bg-blue-100/70 text-[#0b3578] border border-[#0b3578]/20 px-2 py-0.5 rounded-sm uppercase tracking-widest">
                      {sub.subject_code}
                    </span>
                    <span className="text-[10px] font-bold bg-slate-200/70 text-slate-800 border border-slate-300 px-2 py-0.5 rounded-sm uppercase tracking-widest">
                      {sub.subject_type}
                    </span>
                  </div>
                  <h4 className="text-base font-bold text-slate-900 uppercase tracking-wide leading-snug">{sub.subject_name}</h4>
                </div>
                <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button onClick={() => setEditingSubject(sub)} className="px-3 py-2 bg-slate-50 border border-slate-200 text-slate-700 hover:text-[#0b3578] rounded-sm transition-colors text-[10px] font-bold uppercase tracking-widest">
                    Edit
                  </button>
                  <button onClick={() => handleDeleteSubject(sub.subject_code)} className="px-3 py-2 bg-red-50 border border-red-200 text-red-700 hover:bg-red-100 rounded-sm transition-colors text-[10px] font-bold uppercase tracking-widest">
                    Remove
                  </button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Subject Modal */}
      {editingSubject && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-sm z-[110] flex items-center justify-center px-4 py-10 overflow-y-auto">
          <div className="bg-white border border-slate-200 shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 rounded-sm">
            <div className="bg-[#0b3578] p-4 text-white flex justify-between items-center border-b border-white/10">
              <h3 className="font-bold text-sm uppercase tracking-widest">Subject Registry</h3>
              <button onClick={() => setEditingSubject(null)} className="text-white/70 hover:text-white font-bold text-[10px] uppercase tracking-[0.2em]">Close</button>
            </div>
            <form onSubmit={handleSaveSubject} className="p-6 sm:p-8 space-y-5 bg-white">
              <div>
                <label className="block text-[10px] font-bold text-slate-700 uppercase tracking-[0.2em] mb-1">Unique Subject Code</label>
                <input name="code" defaultValue={editingSubject.subject_code} required className="w-full bg-slate-50 border border-slate-200 rounded-sm p-3 text-sm font-semibold text-slate-900 outline-none focus:ring-2 focus:ring-[#0b3578]/30" placeholder="e.g. PC3203CS" />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-slate-700 uppercase tracking-[0.2em] mb-1">Full Course Name</label>
                <input name="name" defaultValue={editingSubject.subject_name} required className="w-full bg-slate-50 border border-slate-200 rounded-sm p-3 text-sm font-semibold text-slate-900 outline-none focus:ring-2 focus:ring-[#0b3578]/30" placeholder="e.g. Software Engineering" />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-slate-700 uppercase tracking-[0.2em] mb-1">Instruction Type</label>
                <select name="type" defaultValue={editingSubject.subject_type || 'theory'} className="w-full bg-slate-50 border border-slate-200 rounded-sm p-3 text-sm font-semibold text-slate-900 outline-none focus:ring-2 focus:ring-[#0b3578]/30">
                  <option value="theory">Theory Course</option>
                  <option value="lab">Laboratory / Practical</option>
                </select>
              </div>
              <button type="submit" className="w-full py-4 bg-[#0b3578] text-white rounded-sm font-bold uppercase tracking-[0.2em] text-[10px] hover:bg-[#0b3578]/90 transition-colors">
                Synchronize Course
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';
import React, { useCallback, useRef } from 'react';
import { createPortal } from 'react-dom';
import Image from 'next/image';
import { COLLEGE_CONFIG } from '@/lib/college-config';
import { getAssetUrl } from '@/lib/assets';

export const BLOOD_GROUP_OPTIONS = ['A+', 'A-', 'B+', 'B-', 'O+', 'O-', 'AB+', 'AB-'];

export const EditableField = React.memo(function EditableField({
    label,
    name,
    type = 'text',
    fullWidth = false,
    options = null,
    inputMode,
    maxLength,
    isEditing,
    value,
    onChange,
    min,
    max,
    step,
}) {
    const handleChange = useCallback(
        (e) => {
            onChange(name, e.target.value);
        },
        [name, onChange]
    );

    const baseClass = 'block w-full border px-3 py-2 text-xs font-bold transition-all rounded-sm';
    const activeClass = 'border-blue-400 bg-white focus:ring-2 focus:ring-blue-100 outline-none uppercase shadow-sm';
    const readOnlyClass = 'border-slate-200 bg-slate-50 text-slate-500 uppercase tracking-tight';

    return (
        <div className={`${fullWidth ? 'md:col-span-2 col-span-1' : ''}`}>
            <label className="block text-[10px] font-black text-slate-400 mb-1.5 uppercase tracking-widest">{label}</label>
            {options ? (
                <select
                    value={value || ''}
                    onChange={handleChange}
                    disabled={!isEditing}
                    className={`${baseClass} ${isEditing ? activeClass : readOnlyClass}`}
                >
                    <option value="">SELECT</option>
                    {options.map((o) => (
                        <option key={o} value={o}>
                            {o.toUpperCase()}
                        </option>
                    ))}
                </select>
            ) : type === 'textarea' ? (
                <textarea
                    value={value || ''}
                    onChange={handleChange}
                    disabled={!isEditing}
                    rows={3}
                    maxLength={maxLength}
                    className={`${baseClass} ${isEditing ? activeClass : readOnlyClass} resize-none`}
                />
            ) : (
                <input
                    type={type}
                    value={value || ''}
                    onChange={handleChange}
                    disabled={!isEditing}
                    inputMode={inputMode}
                    maxLength={maxLength}
                    min={min}
                    max={max}
                    step={step}
                    className={`${baseClass} ${isEditing ? activeClass : readOnlyClass}`}
                />
            )}
        </div>
    );
});

export function MediaSection({ detail, isEditing, onFieldChange }) {
    const handleFileChange = (e, name) => {
        const file = e.target.files[0];
        if (!file) return;

        if (file.size > 1 * 1024 * 1024) {
            alert('File size exceeds 1MB limit.');
            return;
        }

        const reader = new FileReader();
        reader.onloadend = () => {
            onFieldChange(name, reader.result);
        };
        reader.readAsDataURL(file);
    };

    return (
        <div className="space-y-6">
            <div className="border border-slate-200 bg-white p-4 shadow-sm rounded-sm">
                <div className="mb-3 flex items-center justify-between">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Identification Photo</span>
                    {isEditing && (
                        <label className="cursor-pointer bg-blue-50 text-blue-700 px-2 py-0.5 rounded-full text-[9px] font-black border border-blue-200 hover:bg-blue-100 transition-all uppercase tracking-widest">
                            Replace
                            <input 
                                type="file" 
                                className="hidden" 
                                accept="image/*"
                                onChange={(e) => handleFileChange(e, 'pfp')} 
                            />
                        </label>
                    )}
                </div>
                <div className="w-full bg-slate-50 border border-slate-200 flex items-center justify-center overflow-hidden" style={{ aspectRatio: '3 / 4' }}>
                    {detail.pfp ? (
                        <div className="w-full h-full relative">
                            <Image src={getAssetUrl(detail.pfp)} alt="Student Photo" fill className="object-cover" unoptimized />
                        </div>
                    ) : (
                        <span className="text-[9px] font-bold text-slate-300 uppercase tracking-widest">No Record Found</span>
                    )}
                </div>
            </div>
            <div className="border border-slate-200 bg-white p-4 shadow-sm rounded-sm">
                <div className="mb-3 flex items-center justify-between">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Specimen Signature</span>
                    {isEditing && (
                        <label className="cursor-pointer bg-blue-50 text-blue-700 px-2 py-0.5 rounded-full text-[9px] font-black border border-blue-200 hover:bg-blue-100 transition-all uppercase tracking-widest">
                            Replace
                            <input 
                                type="file" 
                                className="hidden" 
                                accept="image/*"
                                onChange={(e) => handleFileChange(e, 'signature')} 
                            />
                        </label>
                    )}
                </div>
                <div className="w-full h-24 bg-slate-50 border border-slate-200 flex items-center justify-center overflow-hidden">
                    {detail.signature ? (
                        <div className="w-full h-full relative p-2">
                            <Image src={getAssetUrl(detail.signature)} alt="Signature" fill className="object-contain" unoptimized />
                        </div>
                    ) : (
                        <span className="text-[9px] font-bold text-slate-300 uppercase tracking-widest">No Record Found</span>
                    )}
                </div>
            </div>
        </div>
    );
}

