'use client';
import { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { 
  X, 
  Info, 
  CreditCard, 
  History, 
  PlusCircle, 
  CheckCircle2, 
  AlertCircle,
  FileText,
  User,
  Calendar,
  IndianRupee,
  ShieldCheck,
  TrendingUp,
  Clock,
  ArrowRight,
  Edit2,
  Save
} from 'lucide-react';
import { getYearlyTotalFee } from '@/lib/financial-utils';

export default function AddEditRecordInstitutionalModal({
  open,
  year,
  student,
  summary,
  formState,
  setFormState,
  saving,
  onProceedingSave,
  onPaymentSave,
  onFinalUpdate,
  onClose,
  onDeletePayment,
  onDeleteScholarship,
  onSelectProceeding,
  onCancelEdit,
  toDmy,
}) {
  const [isDesktop, setIsDesktop] = useState(true);

  // 1. Core data derivation (needed for state and initial logic)
  const proceedings = Array.isArray(summary?.scholarship_proceedings) ? summary.scholarship_proceedings : [];
  const payments = Array.isArray(summary?.student_payments) ? summary.student_payments : [];

  const reimbursementStatus = String(student?.fee_reimbursement || 'NO').toUpperCase();
  const hasScholarshipData = (proceedings.length > 0) || (summary?.application_no && String(summary.application_no).trim() !== '');
  
  const [forceScholarWorkflow, setForceScholarWorkflow] = useState(false);
  const isScholar = reimbursementStatus === 'YES' || reimbursementStatus === 'GOV' || hasScholarshipData || forceScholarWorkflow;

  // 2. Lifecycle hooks
  useEffect(() => {
    const handleResize = () => setIsDesktop(window.innerWidth >= 1024);
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    if (!open) return;
    if (isScholar) {
      console.info('[Workflow Mode] Scholarship workflow enabled');
    } else {
      console.info('[Workflow Mode] Non-scholarship payment-only mode enabled');
    }
  }, [open, isScholar]);

  if (!open) return null;

  // 3. Advanced derived values
  const totalFee = getYearlyTotalFee(student?.course);
  const totalSanctioned = proceedings
    .filter(p => (p.status || 'SANCTIONED').toUpperCase() !== 'REJECTED')
    .reduce((sum, p) => sum + (Number(p.amount) || 0), 0);
  const totalReleased = proceedings
    .filter(p => (p.status || 'SANCTIONED').toUpperCase() !== 'REJECTED')
    .reduce((sum, p) => sum + (Number(p.released_amount) || 0), 0);
  const totalStudentPaid = payments.reduce((sum, p) => sum + (Number(p.amount) || 0), 0);

  // DYNAMIC GOVT CAP: SC/ST/Minority get full fee, others capped at 35k
  const category = String(student?.category || '').toUpperCase();
  const religion = String(student?.religion || '').toUpperCase();
  const isFullReimbursementCategory = ['SC', 'ST'].includes(category) || 
    ['MUSLIM', 'CHRISTIAN', 'SIKH', 'BUDDHIST', 'JAIN', 'PARSI'].includes(religion);
  
  const GOVT_CAP = (reimbursementStatus === 'GOV' || isFullReimbursementCategory) ? totalFee : 35000;
  const eligibleAmount = isScholar ? GOVT_CAP : 0;

  const allowedStudentPayableLimit = isScholar ? Math.max(0, totalFee - GOVT_CAP) : totalFee;
  const remainingStudentPayable = Math.max(0, allowedStudentPayableLimit - totalStudentPaid);
  const currentPayAmt = Number(formState.payAmount) || 0;
  const isPayOverflow = currentPayAmt > remainingStudentPayable;
  const isPayLimitReached = remainingStudentPayable <= 0;
  
  // Validation for UI
  const currentEntryAmt = Number(formState.schAmount) || 0;
  const currentRelAmt = Number(formState.releasedAmount) || 0;
  const currentStatus = (formState.schStatus || 'SANCTIONED').toUpperCase();
  
  const totalExcludingCurrent = proceedings
    .filter(p => (!formState.selectedProceeding || p.id !== formState.selectedProceeding.id) && (p.status || 'SANCTIONED').toUpperCase() !== 'REJECTED')
    .reduce((sum, p) => sum + (Number(p.amount) || 0), 0);

  const relExcludingCurrent = proceedings
    .filter(p => (!formState.selectedProceeding || p.id !== formState.selectedProceeding.id) && (p.status || 'SANCTIONED').toUpperCase() !== 'REJECTED')
    .reduce((sum, p) => sum + (Number(p.released_amount) || 0), 0);

  const isOverflow = currentStatus !== 'REJECTED' && (totalExcludingCurrent + currentEntryAmt) > GOVT_CAP;
  const isRelOverflow = currentStatus !== 'REJECTED' && (relExcludingCurrent + currentRelAmt) > GOVT_CAP;

  const remainingEligible = Math.max(0, GOVT_CAP - totalSanctioned);
  const balanceToRelease = Math.max(0, totalSanctioned - totalReleased);
  const pendingFromStudent = Math.max(0, totalFee - (totalSanctioned + totalStudentPaid));
  const pendingInstitutionalFee = Math.max(0, totalFee - totalStudentPaid);

  const setField = (k, v) => setFormState?.(k, v);

  // Status computation
  let status = 'Pending';
  let statusColor = 'bg-slate-100 text-slate-600';
  if (isScholar) {
    if (totalReleased >= totalFee && totalFee > 0) {
      status = 'Fully Released';
      statusColor = 'bg-emerald-100 text-emerald-700';
    } else if (totalReleased > 0) {
      status = 'Partially Released';
      statusColor = 'bg-blue-100 text-blue-700';
    } else if (totalSanctioned > 0) {
      status = 'Sanctioned';
      statusColor = 'bg-indigo-100 text-indigo-700';
    }
  } else {
    if (totalStudentPaid >= totalFee && totalFee > 0) {
      status = 'Paid';
      statusColor = 'bg-emerald-100 text-emerald-700';
    } else if (totalStudentPaid > 0) {
      status = 'Partially Paid';
      statusColor = 'bg-blue-100 text-blue-700';
    } else {
      status = 'Unpaid';
      statusColor = 'bg-slate-100 text-slate-600';
    }
  }

  // Application lock logic
  const hasExistingApp = !!(summary?.application_no && String(summary.application_no).trim() !== '');
  const isAppLocked = hasExistingApp && !formState.appEditing;

  // Debug wrappers
  const wrapSave = (fn, label) => async () => {
    if (process.env.NODE_ENV === 'development') {
        console.info(`[Scholarship Registry] Triggering ${label}...`);
        console.info(`[Scholarship Registry] Current Form State:`, formState);
    }
    try {
        await fn();
        if (process.env.NODE_ENV === 'development') console.info(`[Scholarship Registry] ${label} SUCCESS`);
    } catch (err) {
        if (process.env.NODE_ENV === 'development') console.error(`[Scholarship Registry] ${label} ERROR:`, err);
    }
  };

  const modalContent = (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-slate-900/60 p-4 overflow-hidden">
      {!isDesktop ? (
        <div className="bg-white rounded-xl shadow-2xl p-8 max-w-md w-full text-center space-y-4">
          <div className="mx-auto w-16 h-16 bg-amber-50 rounded-full flex items-center justify-center text-amber-600">
            <Info size={32} />
          </div>
          <h3 className="text-xl font-bold text-slate-800">Desktop Access Required</h3>
          <p className="text-slate-600 leading-relaxed">
            Scholarship financial processing is available only on desktop devices to ensure accuracy and compliance.
          </p>
          <button 
            onClick={onClose}
            className="w-full py-3 bg-slate-800 text-white rounded-lg font-semibold hover:bg-slate-700 transition-colors"
          >
            Close
          </button>
        </div>
      ) : (
        <div className="bg-slate-50 w-full max-w-[1200px] h-[90vh] flex flex-col rounded-lg shadow-xl border border-slate-200 overflow-hidden font-sans transform-gpu">
          {/* 1. STICKY MODAL HEADER */}
          <header className="bg-white border-b border-slate-200 px-5 py-3 flex items-center justify-between sticky top-0 z-20">
            <div className="min-w-0">
              <div className="flex items-center gap-2">
                <div className="p-1.5 bg-slate-50 border border-slate-200 rounded text-slate-700">
                  <ShieldCheck size={18} />
                </div>
                <h2 className="text-base font-semibold text-slate-900">
                  {isScholar ? 'Scholarship Financial Processing' : 'Institutional Fee Payments'}
                </h2>
                <span className="hidden sm:inline-flex px-2 py-0.5 text-[11px] font-medium text-slate-600 bg-slate-100 border border-slate-200 rounded">
                  {isScholar ? 'Registry' : 'Payments'}
                </span>
                {(!isScholar && reimbursementStatus === 'NO') && (
                  <button 
                    onClick={() => setForceScholarWorkflow(true)}
                    className="px-2 py-0.5 text-[10px] font-bold text-indigo-700 bg-indigo-50 border border-indigo-200 rounded hover:bg-indigo-100 transition-colors uppercase tracking-wider"
                  >
                    Enable Scholarship Workflow
                  </button>
                )}
              </div>
              <div className="mt-1 flex flex-wrap items-center gap-x-2 gap-y-1 text-[12px] text-slate-600">
                <span className="font-semibold text-slate-800">{year}</span>
                <span className="text-slate-300">|</span>
                <span className="font-semibold text-slate-900">{student?.roll_no}</span>
                <span className="text-slate-300">|</span>
                <span className="font-medium text-slate-800 truncate max-w-[280px]">{student?.name}</span>
                <span className="text-slate-300">|</span>
                <span className="font-medium text-indigo-700">{student?.course}</span>
              </div>
            </div>
            <div className="flex items-center gap-3 shrink-0">
              <div className={`px-2.5 py-1 rounded-full text-[11px] font-semibold border ${statusColor}`}>
                {status}
              </div>
              <button 
                onClick={onClose}
                className="p-2 hover:bg-slate-100 rounded text-slate-500 hover:text-slate-700 transition-colors"
              >
                <X size={18} />
              </button>
            </div>
          </header>

          <main className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar">
            
            {/* 3. FINANCIAL STATUS SUMMARY */}
            {isScholar ? (
              <section className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                <div className="grid grid-cols-4 divide-x divide-slate-200">
                  {[
                    {
                      label: 'Total Sanctioned',
                      value: totalSanctioned,
                      icon: FileText,
                      iconWrap: 'bg-indigo-50 text-indigo-700',
                    },
                    {
                      label: 'Total Released',
                      value: totalReleased,
                      icon: CheckCircle2,
                      iconWrap: 'bg-emerald-50 text-emerald-700',
                    },
                    {
                      label: 'Pending Release',
                      value: balanceToRelease,
                      icon: Clock,
                      iconWrap: 'bg-amber-50 text-amber-700',
                    },
                    {
                      label: 'Remaining Eligible',
                      value: remainingEligible,
                      icon: TrendingUp,
                      iconWrap: 'bg-slate-50 text-slate-700',
                    },
                  ].map((m) => (
                    <div key={m.label} className="px-4 py-3">
                      <div className="flex items-center justify-between">
                        <div className={`p-1.5 rounded border border-slate-200 ${m.iconWrap}`}>
                          <m.icon size={16} />
                        </div>
                        <div className="text-xl font-bold text-slate-900 tabular-nums">
                          ₹{m.value.toLocaleString()}
                        </div>
                      </div>
                      <div className="mt-1 text-xs font-medium text-slate-600">{m.label}</div>
                    </div>
                  ))}
                </div>
              </section>
            ) : (
              <section className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                <div className="grid grid-cols-3 divide-x divide-slate-200">
                  {[
                    {
                      label: 'Total Course Fee',
                      value: totalFee,
                      icon: FileText,
                      iconWrap: 'bg-slate-50 text-slate-700',
                    },
                    {
                      label: 'Total Paid',
                      value: totalStudentPaid,
                      icon: CheckCircle2,
                      iconWrap: 'bg-emerald-50 text-emerald-700',
                    },
                    {
                      label: 'Balance Due',
                      value: pendingInstitutionalFee,
                      icon: Clock,
                      iconWrap: 'bg-amber-50 text-amber-700',
                    },
                  ].map((m) => (
                    <div key={m.label} className="px-4 py-3">
                      <div className="flex items-center justify-between">
                        <div className={`p-1.5 rounded border border-slate-200 ${m.iconWrap}`}>
                          <m.icon size={16} />
                        </div>
                        <div className="text-xl font-bold text-slate-900 tabular-nums">
                          ₹{m.value.toLocaleString()}
                        </div>
                      </div>
                      <div className="mt-1 text-xs font-medium text-slate-600">{m.label}</div>
                    </div>
                  ))}
                </div>
              </section>
            )}

            <div className="grid grid-cols-12 gap-6">
              {/* Left Column - Scholarship Operations */}
              {isScholar && (
              <div className="col-span-7 space-y-6">
                
                {/* 4. SCHOLARSHIP DETAILS SECTION */}
                <section className="bg-white rounded-lg border border-slate-200 overflow-hidden">
                  <div className="bg-slate-50 px-4 py-2.5 border-b border-slate-200">
                    <h3 className="text-sm font-semibold text-slate-900 flex items-center gap-2">
                      <FileText size={16} className="text-indigo-700" />
                      Scholarship details
                    </h3>
                  </div>
                  <div className="p-4">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600 flex items-center justify-between">
                          Application number
                          {isAppLocked && (
                            <button 
                              onClick={() => setField('appEditing', true)}
                              className="text-indigo-700 hover:text-indigo-900 text-xs font-medium"
                            >
                              Unlock
                            </button>
                          )}
                        </label>
                        <input 
                          type="text"
                          value={formState.schAppNo || ''}
                          onChange={(e) => {
                            const val = e.target.value.replace(/\D/g, '').slice(0, 15);
                            setField('schAppNo', val);
                          }}
                          disabled={isAppLocked}
                          placeholder="Enter 6-15 digit Application No"
                          className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 transition disabled:bg-slate-50 disabled:text-slate-400"
                        />
                        {formState.appEditing && (
                          <div className="flex items-center gap-2 text-xs text-amber-700">
                            <AlertCircle size={14} />
                            Application numbers propagate across all years. Edit with caution.
                          </div>
                        )}
                      </div>

                      <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600">Compliance registry</label>
                        <div className="grid grid-cols-2 gap-2">
                          <label className="flex items-center gap-2 bg-white px-3 py-2 rounded-md border border-slate-200 cursor-pointer">
                            <input 
                              type="checkbox" 
                              id="hardcopy"
                              checked={!!formState.hardcopySubmitted}
                              onChange={(e) => setField('hardcopySubmitted', e.target.checked)}
                              className="w-4 h-4 text-indigo-600 rounded border-slate-300"
                            />
                            <span className="text-xs font-medium text-slate-700">Hardcopy</span>
                          </label>

                          <label className="flex items-center gap-2 bg-white px-3 py-2 rounded-md border border-slate-200 cursor-pointer">
                            <input 
                              type="checkbox" 
                              id="thumb"
                              checked={!!formState.thumbUpdateAvailable}
                              onChange={(e) => setField('thumbUpdateAvailable', e.target.checked)}
                              className="w-4 h-4 text-indigo-600 rounded border-slate-300"
                            />
                            <span className="text-xs font-medium text-slate-700">Thumb update</span>
                          </label>
                        </div>

                        {formState.thumbUpdateAvailable && (
                          <div className="mt-3 space-y-2 animate-fadeIn">
                            <label className="text-xs font-medium text-slate-600">Thumb verification status</label>
                            <select 
                              value={formState.thumbStatus || 'PENDING'}
                              onChange={(e) => setField('thumbStatus', e.target.value)}
                              className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 transition"
                            >
                              <option value="PENDING">PENDING</option>
                              <option value="COMPLETE">COMPLETE</option>
                            </select>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </section>

                {/* 5. NEW/EDIT PROCEEDING ENTRY SECTION */}
                <section className={`bg-white rounded-lg border overflow-hidden ${formState.selectedProceeding ? 'border-amber-200' : 'border-slate-200'}`}>
                  <div className={`bg-slate-50 px-4 py-2.5 border-b flex items-center justify-between ${formState.selectedProceeding ? 'border-amber-200' : 'border-slate-200'}`}>
                    <h3 className="text-sm font-semibold text-slate-900 flex items-center gap-2">
                      <span className={`inline-flex items-center justify-center w-7 h-7 rounded border ${formState.selectedProceeding ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-indigo-50 border-indigo-200 text-indigo-700'}`}>
                        {formState.selectedProceeding ? <Edit2 size={16} /> : <PlusCircle size={16} />}
                      </span>
                      {formState.selectedProceeding ? 'Update proceeding' : 'Register proceeding'}
                    </h3>
                    {formState.selectedProceeding && (
                      <button 
                        onClick={onCancelEdit}
                        className="px-2.5 py-1 text-xs font-medium text-slate-700 bg-white border border-slate-200 rounded hover:bg-slate-50 transition-colors"
                      >
                        Cancel edit
                      </button>
                    )}
                  </div>

                  <div className="p-4 space-y-4 bg-white">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600">Proceeding ID</label>
                        <input 
                          type="text"
                          value={formState.schProceedingNo || ''}
                          onChange={(e) => setField('schProceedingNo', e.target.value)}
                          placeholder="e.g. 152/S1/2023"
                          className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 transition"
                        />
                      </div>

                      <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600">Sanctioned amount</label>
                        <div className="relative">
                          <IndianRupee size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                          <input 
                            type="number"
                            value={formState.schAmount || ''}
                            onChange={(e) => setField('schAmount', e.target.value)}
                            placeholder="0.00"
                            className="w-full pl-9 pr-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 transition"
                          />
                        </div>
                      </div>

                      <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600">Sanction date</label>
                        <input 
                          type="date"
                          value={formState.schSanctionDate || ''}
                          onChange={(e) => setField('schSanctionDate', e.target.value)}
                          className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 transition"
                        />
                      </div>

                      <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600">Released amount</label>
                        <div className="relative">
                          <IndianRupee size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                          <input 
                            type="number"
                            value={formState.releasedAmount || ''}
                            onChange={(e) => setField('releasedAmount', e.target.value)}
                            placeholder="Actually disbursed"
                            className="w-full pl-9 pr-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-600 transition"
                          />
                        </div>
                      </div>

                      <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600">Released date</label>
                        <input 
                          type="date"
                          value={formState.releasedDate || ''}
                          onChange={(e) => setField('releasedDate', e.target.value)}
                          className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-600 transition"
                        />
                      </div>

                      <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600">Status</label>
                        <select 
                          value={formState.schStatus || 'SANCTIONED'}
                          onChange={(e) => setField('schStatus', e.target.value)}
                          className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 transition"
                        >
                          <option value="SANCTIONED">SANCTIONED</option>
                          <option value="RELEASED">RELEASED</option>
                          <option value="PENDING">PENDING</option>
                          <option value="REJECTED">REJECTED (voids dues credit)</option>
                        </select>
                      </div>
                    </div>
                    
                    {/* Inline Validation Warnings */}
                    {(Number(formState.schAmount) > remainingEligible && Number(formState.schAmount) > 0) && (
                      <div className="px-3 py-2 bg-amber-50 border border-amber-200 rounded-md flex items-start gap-2">
                        <AlertCircle size={16} className="text-amber-600 mt-0.5" />
                        <div>
                          <p className="text-xs font-semibold text-amber-900">Budget warning</p>
                          <p className="text-xs text-amber-700 mt-0.5">Total sanction exceeds remaining eligible cap. Check policy.</p>
                        </div>
                      </div>
                    )}

                    <div className="flex justify-end">
                      <button 
                        onClick={wrapSave(onProceedingSave, 'PROCEEDING')}
                        disabled={saving || !formState.schAppNo || !formState.schProceedingNo}
                        className="inline-flex items-center gap-2 px-4 py-2 bg-[#0b3578] border border-[#0b3578] text-white text-sm font-semibold rounded-md hover:bg-[#072a5f] transition-colors disabled:opacity-50"
                      >
                        {saving ? <Clock size={16} className="animate-spin" /> : (formState.selectedProceeding ? <Save size={16} /> : <PlusCircle size={16} />)}
                        {saving ? 'Processing...' : (formState.selectedProceeding ? 'Update registry entry' : 'Register proceeding entry')}
                      </button>
                    </div>
                  </div>
                </section>

                {/* 6. EXISTING PROCEEDINGS TABLE */}
                <section className="bg-white rounded-lg border border-slate-200 overflow-hidden">
                  <div className="bg-slate-50 px-4 py-2.5 border-b border-slate-200 flex items-center justify-between">
                    <h3 className="text-sm font-semibold text-slate-900 flex items-center gap-2">
                      <History size={16} className="text-slate-500" />
                      Scholarship proceedings
                    </h3>
                    <span className="text-xs text-slate-500">{proceedings.length} records</span>
                  </div>
                  <div className="overflow-x-auto max-h-[300px]">
                    <table className="w-full text-left border-collapse">
                      <thead className="bg-slate-50 sticky top-0 z-10 border-b border-slate-200">
                        <tr>
                          <th className="px-3 py-2 text-xs font-semibold text-slate-600">Proceeding</th>
                          <th className="px-3 py-2 text-xs font-semibold text-slate-600 text-right">Sanctioned</th>
                          <th className="px-3 py-2 text-xs font-semibold text-slate-600 text-center">Sanction date</th>
                          <th className="px-3 py-2 text-xs font-semibold text-slate-600 text-center">Status</th>
                          <th className="px-3 py-2 text-xs font-semibold text-slate-600 text-right">Released</th>
                          <th className="px-3 py-2 text-xs font-semibold text-slate-600 text-right">Actions</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {proceedings.length === 0 ? (
                          <tr>
                            <td colSpan="6" className="px-3 py-10 text-center text-slate-500 text-sm">No proceedings recorded for this year.</td>
                          </tr>
                        ) : (
                          proceedings.map((p) => (
                            <tr key={p.id} className={`hover:bg-slate-50 transition-colors group ${p.status === 'REJECTED' ? 'bg-red-50/30' : ''}`}>
                              <td className="px-3 py-2.5">
                                <p className="text-sm font-medium text-slate-900">{p.proceeding_no}</p>
                              </td>
                              <td className="px-3 py-2.5 text-right text-sm font-semibold text-slate-900 tabular-nums">₹{Number(p.amount).toLocaleString()}</td>
                              <td className="px-3 py-2.5 text-center text-xs text-slate-600">{toDmy(p.date)}</td>
                              <td className="px-3 py-2.5 text-center">
                                <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold border ${
                                  p.status === 'REJECTED' ? 'bg-red-100 text-red-700 border-red-200' :
                                  p.status === 'RELEASED' ? 'bg-emerald-100 text-emerald-700 border-emerald-200' :
                                  'bg-indigo-100 text-indigo-700 border-indigo-200'
                                }`}>
                                  {p.status || 'SANCTIONED'}
                                </span>
                              </td>
                              <td className="px-3 py-2.5 text-right">
                                {p.released_amount ? (
                                  <div className="space-y-0.5">
                                    <p className="text-sm font-semibold text-emerald-700 tabular-nums">₹{Number(p.released_amount).toLocaleString()}</p>
                                    <p className="text-xs text-emerald-700/80">{toDmy(p.released_date)}</p>
                                  </div>
                                ) : (
                                  <span className="text-xs text-slate-500">Pending</span>
                                )}
                              </td>
                              <td className="px-3 py-2.5 text-right">
                                <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                  <button 
                                    onClick={() => onSelectProceeding?.(p)}
                                    className="p-2 text-slate-500 hover:text-indigo-700 hover:bg-indigo-50 rounded transition-colors"
                                  >
                                    <Edit2 size={16} />
                                  </button>
                                  <button
                                    onClick={() => {
                                      if (window.confirm('Are you sure you want to permanently delete this scholarship proceeding record?')) {
                                        onDeleteScholarship?.(p.id);
                                      }
                                    }}
                                    className="p-2 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                                  >
                                    <X size={16} />
                                  </button>
                                </div>
                              </td>
                            </tr>
                          ))
                        )}
                      </tbody>
                    </table>
                  </div>
                </section>
              </div>
              )}

              {/* Right Column - Student Operations */}
              <div className={`${isScholar ? 'col-span-5' : 'col-span-12'} space-y-6`}>
                
                {/* 7. STUDENT PAYMENT SECTION */}
                <section className="bg-white rounded-lg border border-slate-200 overflow-hidden">
                  <div className="bg-slate-50 px-4 py-2.5 border-b border-slate-200">
                    <h3 className="text-sm font-semibold text-slate-900 flex items-center gap-2">
                      <CreditCard size={16} className="text-amber-700" />
                      Student fee payments
                    </h3>
                  </div>

                  <div className="p-4 bg-white space-y-3">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600">Amount paid</label>
                        <input 
                          type="number"
                          value={formState.payAmount || ''}
                          onChange={(e) => setField('payAmount', e.target.value)}
                          placeholder="₹0.00"
                          disabled={saving || isPayLimitReached}
                          className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-amber-500/20 focus:border-amber-600 transition"
                        />
                        <div className="text-xs text-slate-600">
                          <span>Allowed payable limit: </span>
                          <span className="font-semibold text-slate-900 tabular-nums">₹{allowedStudentPayableLimit.toLocaleString()}</span>
                          <span className="mx-1.5 text-slate-300">•</span>
                          <span>Remaining: </span>
                          <span className="font-bold text-slate-900 tabular-nums text-sm">₹{remainingStudentPayable.toLocaleString()}</span>
                        </div>
                        {isPayLimitReached && (
                          <div className="mt-2 px-3 py-2 bg-emerald-50 border border-emerald-200 rounded-md flex items-start gap-2">
                            <CheckCircle2 size={16} className="text-emerald-700 mt-0.5" />
                            <div>
                              <p className="text-xs font-semibold text-emerald-900">Payable limit reached</p>
                              <p className="text-xs text-emerald-800 mt-0.5">No more student payments can be recorded for this year.</p>
                            </div>
                          </div>
                        )}
                        {isPayOverflow && (
                          <div className="mt-1 px-3 py-2 bg-red-100 border border-red-300 rounded-md flex items-start gap-2 animate-shake">
                            <AlertCircle size={16} className="text-red-700 mt-0.5" />       
                            <div>
                              <p className="text-xs font-bold text-red-900 uppercase">Payment Not Possible</p>
                              <p className="text-xs text-red-800 mt-0.5 font-medium">
                                This amount exceeds the student&apos;s required payable limit. Reduce it to <span className="underline font-bold tabular-nums">₹{remainingStudentPayable.toLocaleString()}</span> or less to proceed.
                              </p>
                            </div>
                          </div>
                        )}
                        </div>
                        <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600">Payment date</label>
                        <input 
                          type="date"
                          value={formState.payDate || ''}
                          onChange={(e) => setField('payDate', e.target.value)}
                          disabled={saving || isPayLimitReached}
                          className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-amber-500/20 focus:border-amber-600 transition"
                        />
                        </div>
                        <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600">Payment mode</label>
                        <select 
                          value={formState.payMode || 'UPI'}
                          onChange={(e) => setField('payMode', e.target.value)}
                          disabled={saving || isPayLimitReached}
                          className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-amber-500/20 focus:border-amber-600 transition"
                        >
                          <option value="CASH">CASH</option>
                          <option value="UPI">UPI / QR</option>
                          <option value="BANK_TRANSFER">BANK TRANSFER</option>
                          <option value="DD">DEMAND DRAFT (DD)</option>
                          <option value="OTHER">OTHER</option>
                        </select>
                        </div>
                        <div className="space-y-2">
                        <label className="text-xs font-medium text-slate-600">Bank name</label>
                        <input 
                          type="text"
                          value={formState.bankName || ''}
                          onChange={(e) => setField('bankName', e.target.value)}
                          placeholder="Bank name"
                          disabled={saving || isPayLimitReached}
                          className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-amber-500/20 focus:border-amber-600 transition"
                        />
                        </div>
                        <div className="col-span-2 space-y-2">
                        <label className="text-xs font-medium text-slate-600">Reference (UTR/Ref No)</label>
                        <input 
                          type="text"
                          value={formState.payRef || ''}
                          onChange={(e) => setField('payRef', e.target.value)}
                          placeholder="e.g. DU15263748"
                          disabled={saving || isPayLimitReached}
                          className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md text-sm font-semibold focus:ring-2 focus:ring-amber-500/20 focus:border-amber-600 transition"
                        />
                        </div>
                        </div>
                        <button 
                        onClick={wrapSave(onPaymentSave, 'PAYMENT')}
                        disabled={saving || isPayLimitReached || !formState.payAmount || !formState.payRef || isPayOverflow}
                        className="w-full py-2 bg-[#0b3578] border border-[#0b3578] text-white text-sm font-semibold rounded-md hover:bg-[#072a5f] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                        {saving ? 'Processing...' : isPayOverflow ? 'Payment Limit Exceeded' : 'Register student payment'}
                        </button>
                  </div>

                  <div className="max-h-[250px] overflow-y-auto border-t border-slate-200">
                    <table className="w-full text-left">
                      <thead className="bg-slate-50 sticky top-0 z-10 border-b border-slate-200">
                        <tr>
                          <th className="px-3 py-2 text-xs font-semibold text-slate-600">Amount / date</th>
                          <th className="px-3 py-2 text-xs font-semibold text-slate-600">Mode / ref</th>
                          <th className="px-3 py-2 text-xs font-semibold text-slate-600 text-right">Actions</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {payments.length === 0 ? (
                          <tr>
                            <td colSpan="3" className="px-3 py-8 text-center text-slate-500 text-sm">No student payments recorded.</td>
                          </tr>
                        ) : (
                          payments.slice().reverse().map(p => (
                            <tr key={p.id} className="group hover:bg-slate-50 transition-colors">
                              <td className="px-3 py-2.5">
                                <p className="text-sm font-semibold text-slate-900 tabular-nums">₹{Number(p.amount).toLocaleString()}</p>
                                <p className="text-xs text-slate-600 mt-0.5">{toDmy(p.date)}</p>
                              </td>
                              <td className="px-3 py-2.5">
                                <p className="text-xs text-slate-700">{p.payment_mode || 'UPI'}</p>
                                <p className="text-xs text-slate-600 font-mono truncate max-w-[160px]">{p.transaction_ref}</p>
                              </td>
                              <td className="px-3 py-2.5 text-right">
                                <button 
                                  onClick={() => {
                                    if (window.confirm('Are you sure you want to permanently delete this student fee payment record?')) {
                                      onDeletePayment?.(p.id);
                                    }
                                  }}
                                  className="p-2 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded opacity-0 group-hover:opacity-100 transition-colors"
                                >
                                  <X size={16} />
                                </button>
                              </td>
                            </tr>
                          ))
                        )}
                      </tbody>
                    </table>
                  </div>
                </section>

                {/* 8. SCHOLARSHIP RELEASE STATUS */}
                {isScholar && (
                  <section className="bg-white rounded-lg border border-slate-200 overflow-hidden">
                    <div className="bg-slate-50 px-4 py-2.5 border-b border-slate-200">
                      <h3 className="text-sm font-semibold text-slate-900 flex items-center gap-2">
                        <TrendingUp size={16} className="text-emerald-700" />
                        Scholarship release status
                      </h3>
                    </div>
                    <div className="p-4 space-y-3">
                      <div className="grid grid-cols-2 gap-3">
                        <div className="rounded-md border border-slate-200 bg-slate-50 px-3 py-2">
                          <div className="text-[12px] text-slate-600">Sanctioned</div>
                          <div className="text-lg font-bold text-slate-900 tabular-nums">₹{totalSanctioned.toLocaleString()}</div>
                        </div>
                        <div className="rounded-md border border-slate-200 bg-slate-50 px-3 py-2">
                          <div className="text-[12px] text-slate-600">Released</div>
                          <div className="text-lg font-bold text-emerald-700 tabular-nums">₹{totalReleased.toLocaleString()}</div>
                        </div>
                        <div className="rounded-md border border-slate-200 bg-slate-50 px-3 py-2">
                          <div className="text-[12px] text-slate-600">Balance to release</div>
                          <div className="text-lg font-bold text-slate-900 tabular-nums">₹{balanceToRelease.toLocaleString()}</div>
                        </div>
                        <div className="rounded-md border border-slate-200 bg-slate-50 px-3 py-2">
                          <div className="text-[12px] text-slate-600">Release rate</div>
                          <div className="text-lg font-bold text-slate-900 tabular-nums">
                            {totalSanctioned > 0 ? Math.round((totalReleased / totalSanctioned) * 100) : 0}%
                          </div>
                        </div>
                      </div>
                      <div className="text-xs text-slate-600">
                        This is a summary of disbursement against recorded proceedings for the selected year.
                      </div>
                    </div>
                  </section>
                )}
              </div>
            </div>
          </main>

          {/* 10. STICKY FOOTER ACTIONS */}
          <footer className="bg-white border-t border-slate-200 px-6 py-3 flex items-center justify-between sticky bottom-0 z-20">
            {isScholar ? (
              <div className="flex items-center gap-6 text-[12px] text-slate-700">
                <div className="flex flex-col">
                  <span className="text-[11px] text-slate-500">Total value impact</span>
                  <span className="text-base font-bold text-slate-900 tabular-nums">₹{(totalSanctioned + totalStudentPaid).toLocaleString()}</span>
                </div>
                <div className="w-px h-8 bg-slate-200" />
                <div className="flex flex-col">
                  <span className="text-[11px] text-slate-500">Registry balance</span>
                  <span className={`text-base font-bold tabular-nums ${pendingFromStudent > 0 ? 'text-amber-700' : 'text-emerald-700'}`}>₹{pendingFromStudent.toLocaleString()}</span>
                </div>
              </div>
            ) : (
              <div className="flex items-center gap-6 text-[12px] text-slate-700">
                <div className="flex flex-col">
                  <span className="text-[11px] text-slate-500">Total paid</span>
                  <span className="text-base font-bold text-slate-900 tabular-nums">₹{totalStudentPaid.toLocaleString()}</span>
                </div>
                <div className="w-px h-8 bg-slate-200" />
                <div className="flex flex-col">
                  <span className="text-[11px] text-slate-500">Balance due</span>
                  <span className={`text-base font-bold tabular-nums ${pendingInstitutionalFee > 0 ? 'text-amber-700' : 'text-emerald-700'}`}>₹{pendingInstitutionalFee.toLocaleString()}</span>
                </div>
              </div>
            )}

            <div className="flex items-center gap-2">
              <button 
                onClick={onClose}
                className="px-3 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-300 rounded-md hover:bg-slate-50 transition-colors"
              >
                Discard
              </button>
              <button 
                onClick={wrapSave(onFinalUpdate, 'FINAL')}
                disabled={saving}
                className="px-4 py-2 bg-[#0b3578] border border-[#0b3578] text-white text-sm font-semibold rounded-md hover:bg-[#072a5f] transition-colors flex items-center gap-2 disabled:opacity-50"
              >
                {saving ? <Clock size={16} className="animate-spin" /> : <Save size={16} />}
                Save record
              </button>
            </div>
          </footer>
        </div>
      )}
    </div>
  );

  return createPortal(modalContent, document.body);
}

"use client";
import React, { useState, useEffect, forwardRef } from 'react';
import Image from 'next/image';
import toast from 'react-hot-toast';
import { formatDate, parseDate } from '@/lib/date';
import DatePicker from 'react-datepicker';
import "react-datepicker/dist/react-datepicker.css";
import { validateRollNo, getBranchFromRoll, getAdmissionTypeFromRoll, getEntranceExamQualified } from '@/lib/rollNumber';
import { COLLEGE_CONFIG } from '@/lib/college-config';
import { smoothScrollToTop } from '@/lib/scroll-utils';
import { formatIndianNumber } from '@/lib/financial-utils';

const DatePickerInput = forwardRef(({ value, onClick, ...props }, ref) => (
  <input
    onClick={onClick}
    ref={ref}
    value={value ?? ''}
    {...props}
  />
));
DatePickerInput.displayName = 'DatePickerInput';

export default function AddNewStudent() {
  const MAX_ROLL = 10;
  const MAX_MOBILE_LEN = 10;
  const MAX_ANNUAL_INCOME = 99999999; // adjust to DB limit if known

  const [basic, setBasic] = useState({ admission_no:'', roll_no:'', name:'', date_of_birth:'', gender:'Male', mobile:'', email:'' });
  const [mobileError, setMobileError] = useState('');
  const [incomeError, setIncomeError] = useState('');
  const [annualIncomeDisplay, setAnnualIncomeDisplay] = useState('');
  const [personal, setPersonal] = useState({ 
    father_name:'', mother_name:'', nationality:'', religion:'', category:'OC', sub_caste:'', area_status:'Local', 
    mother_tongue:'', place_of_birth:'', father_occupation:'', annual_income:'', aadhaar_no:'', 
    curr_house_no: '', curr_street: '', curr_apartment: '', curr_city: '', curr_state: '', curr_pincode: '', curr_country: 'India',
    perm_house_no: '', perm_street: '', perm_apartment: '', perm_city: '', perm_state: '', perm_pincode: '', perm_country: 'India',
    is_current_same_as_permanent: false,
    seat_allotted_category:'', identification_marks:'', blood_group: '', guardian_mobile: '' 
  });
  const [academic, setAcademic] = useState({ qualifying_exam:'TG EAPCET', previous_college_details:'', medium_of_instruction:'English', ranks:'', ssc_marks:'', inter_marks:'' });

  const handleCheckboxChange = (checked) => {
    setPersonal(prev => {
      const updated = { ...prev, is_current_same_as_permanent: checked };
      if (checked) {
        updated.perm_house_no = prev.curr_house_no;
        updated.perm_street = prev.curr_street;
        updated.perm_apartment = prev.curr_apartment;
        updated.perm_city = prev.curr_city;
        updated.perm_state = prev.curr_state;
        updated.perm_pincode = prev.curr_pincode;
        updated.perm_country = prev.curr_country;
      }
      return updated;
    });
  };

  const handleAddressChange = (field, value) => {
    setPersonal(prev => {
      const updated = { ...prev, [field]: value };
      if (prev.is_current_same_as_permanent && field.startsWith('curr_')) {
        const permField = field.replace('curr_', 'perm_');
        updated[permField] = value;
      }
      return updated;
    });
  };
  const [files, setFiles] = useState({ pfp: null, signature: null });
  const [addLoading, setAddLoading] = useState(false);
  const [savedRollLocked, setSavedRollLocked] = useState(false);
  const [showAddForm, setShowAddForm] = useState(true);
  const [rollNoError, setRollNoError] = useState('');
  const [isTotalMarksAutofilled, setIsTotalMarksAutofilled] = useState(false);

  useEffect(() => {
    const id = setTimeout(() => {
      if (basic.roll_no) {
        // Enforce roll length client-side
        const trimmed = String(basic.roll_no || '').toUpperCase().slice(0, MAX_ROLL);
        if (trimmed !== basic.roll_no) setBasic(prev => ({ ...prev, roll_no: trimmed }));
        const { isValid } = validateRollNo(basic.roll_no);
        if (basic.roll_no.length === MAX_ROLL && isValid) {
          setRollNoError('');
        } else if (basic.roll_no.length === MAX_ROLL && !isValid) {
          setRollNoError('Invalid Roll Number format.');
        } else {
          setRollNoError(`Roll Number must be exactly ${MAX_ROLL} characters long`);
        }
        const entranceExam = getEntranceExamQualified(basic.roll_no);
        const newQualifyingExam = entranceExam || 'TG EAPCET';

        setAcademic(prev => ({ ...prev, qualifying_exam: newQualifyingExam, ranks: '' })); // Initialize ranks to empty
        setIsTotalMarksAutofilled(false); // Ranks is not autofilled based on exam
      } else {
        setRollNoError('');
        setAcademic(prev => ({ ...prev, qualifying_exam: 'TG EAPCET', ranks: '' })); // Reset to default if rollNo is empty
        setIsTotalMarksAutofilled(false);
      }
    }, 0);

    return () => clearTimeout(id);
  }, [basic.roll_no]);

  const addRequiredFilled = () => {
    return basic.admission_no.trim() && basic.roll_no.trim() && !rollNoError && basic.name.trim() && basic.date_of_birth && basic.gender && (basic.mobile || '').length === MAX_MOBILE_LEN && basic.email.trim();
  };

  const formatAadhaar = (val) => {
    if (val == null) return '';
    const digits = String(val).replace(/\D/g, '').slice(0, 12);
    if (!digits) return '';
    return digits.replace(/(\d{4})(?=\d)/g, '$1 ').trim();
  };

  const handleFileChange = async (e, type) => {
    const file = e.target.files[0];
    if (!file) return;

    let processedFile = file;
    try {
      const { compressImage } = await import('@/lib/image-compressor');
      processedFile = await compressImage(file, 1200, 1200, 0.6);
    } catch (err) {
      console.error('Image compression failed:', err);
    }

    // 1MB limit
    if (processedFile.size > 1 * 1024 * 1024) {
      toast.error(`${type === 'pfp' ? 'Photo' : 'Signature'} file is too large. Max limit is 1MB.`);
      e.target.value = null;
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFiles(prev => ({ ...prev, [type]: reader.result }));
    };
    reader.readAsDataURL(processedFile);
  };

  const handleAddStudent = async (e) => {
    e.preventDefault();
    if (!addRequiredFilled()) return;
    setAddLoading(true);
    const toastId = toast.loading('Saving new student...');
    try{
      const payload = {
        admission_no: basic.admission_no || null,
        roll_no: basic.roll_no || null,
        name: basic.name || null,
        fee_reimbursement: basic.fee_reimbursement ? String(basic.fee_reimbursement).trim().toUpperCase() : null,
        father_name: personal.father_name || null,
        mother_name: personal.mother_name || null,
        date_of_birth: basic.date_of_birth || null,
        place_of_birth: personal.place_of_birth || null,
        gender: basic.gender || null,
        nationality: personal.nationality || null,
        religion: personal.religion || null,
        sub_caste: personal.sub_caste || null,
        category: personal.category || null,
        curr_house_no: personal.curr_house_no || null,
        curr_street: personal.curr_street || null,
        curr_apartment: personal.curr_apartment || null,
        curr_city: personal.curr_city || null,
        curr_state: personal.curr_state || null,
        curr_pincode: personal.curr_pincode || null,
        curr_country: personal.curr_country || 'India',
        perm_house_no: personal.perm_house_no || null,
        perm_street: personal.perm_street || null,
        perm_apartment: personal.perm_apartment || null,
        perm_city: personal.perm_city || null,
        perm_state: personal.perm_state || null,
        perm_pincode: personal.perm_pincode || null,
        perm_country: personal.perm_country || 'India',
        is_current_same_as_permanent: !!personal.is_current_same_as_permanent,
        mobile: basic.mobile || null,
        email: basic.email || null,
        qualifying_exam: academic.qualifying_exam || null,
        mother_tongue: personal.mother_tongue || null,
        father_occupation: personal.father_occupation || null,
        annual_income: personal.annual_income ? personal.annual_income.toString().replace(/,/g, '') : null,
        guardian_mobile: personal.guardian_mobile || null,
        aadhaar_no: personal.aadhaar_no || null,
        ranks: academic.ranks ? Number(academic.ranks) : null,
        ssc_marks: academic.ssc_marks || null,
        inter_marks: academic.inter_marks || null,
        previous_college_details: academic.previous_college_details || null,
        medium_of_instruction: academic.medium_of_instruction || null,
        area_status: personal.area_status || null,
        seat_allotted_category: personal.seat_allotted_category || null,
        identification_marks: personal.identification_marks || null,
        blood_group: personal.blood_group || null,
        pfp: files.pfp,
        signature: files.signature,
      };

      const res = await fetch('/api/clerk/admission/students', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to add student');
      toast.success('Student added successfully', { id: toastId });
      setSavedRollLocked(true);
      setShowAddForm(false);
      smoothScrollToTop({ behavior: 'smooth' });
      setBasic({ admission_no:'', roll_no:'', name:'', date_of_birth:'', gender:'Male', email:''});
      setPersonal({ 
        father_name:'', mother_name:'', nationality:'', religion:'', category:'OC', sub_caste:'', area_status:'Local', 
        mother_tongue:'', place_of_birth:'', father_occupation:'', annual_income:'', aadhaar_no:'', 
        curr_house_no: '', curr_street: '', curr_apartment: '', curr_city: '', curr_state: '', curr_pincode: '', curr_country: 'India',
        perm_house_no: '', perm_street: '', perm_apartment: '', perm_city: '', perm_state: '', perm_pincode: '', perm_country: 'India',
        is_current_same_as_permanent: false,
        seat_allotted_category:'', identification_marks:'', blood_group: '', guardian_mobile: '' 
      });
      // reset fee_reimbursement
      setBasic(prev => ({ ...prev, fee_reimbursement: undefined }));
      setAnnualIncomeDisplay('');
      setAcademic({ qualifying_exam:'TG EAPCET', previous_college_details:'', medium_of_instruction:'English', ranks:'', ssc_marks:'', inter_marks:'' });
      setFiles({ pfp: null, signature: null });
      setSavedRollLocked(false);
      setTimeout(()=>{ setShowAddForm(true); }, 1500);
    }catch(err){
      console.error(err);
      toast.error(err.message || 'Save failed', { id: toastId });
    }finally{ setAddLoading(false); }
  };
  
  const genders = COLLEGE_CONFIG.genders;
  const categories = COLLEGE_CONFIG.categories;

  const feeReimbursementOptions = ['NO', 'YES', 'GOV'];

  return (
    showAddForm ? (
      <form onSubmit={handleAddStudent} className="space-y-6">
        <div>
          <h3 className="font-bold">Section A: Basic Details</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mt-2">
            <input placeholder="Admission Number*" value={basic.admission_no} onChange={e=>setBasic({...basic, admission_no:e.target.value})} className="p-2 border rounded" />
            <div className="relative">
              <input placeholder="Roll Number*" value={basic.roll_no} onChange={(e)=>{
                const v = String(e.target.value || '').toUpperCase().slice(0, 10);
                setBasic({...basic, roll_no: v});
              }} disabled={savedRollLocked} className="p-2 border rounded w-full" maxLength={MAX_ROLL} />
              {rollNoError && basic.roll_no.length !== 0 && <div className="text-xs text-red-600 mt-1">{rollNoError}</div>}
              {savedRollLocked && (<span className="absolute right-2 top-2 text-sm">🔒</span>)}
            </div>
            <input placeholder="Student Name*" value={basic.name} onChange={e=>setBasic({...basic, name:e.target.value})} className="p-2 border rounded" />
            <DatePicker
              selected={parseDate(basic.date_of_birth)}
              onChange={(date) => setBasic({ ...basic, date_of_birth: formatDate(date) })}
              dateFormat="dd-MM-yyyy"
              placeholderText="DD-MM-YYYY"
              className="p-2 border rounded w-full"
              showYearDropdown
              dropdownMode="select"
              customInput={<DatePickerInput className="p-2 border rounded w-full" />}
            />
            <select value={basic.gender} onChange={e=>setBasic({...basic, gender:e.target.value})} className="p-2 border rounded">
              {genders.map(g=> <option key={g} value={g}>{g}</option>)}
            </select>
            <select value={basic.fee_reimbursement || 'NO'} onChange={e=>setBasic({...basic, fee_reimbursement: e.target.value})} className="p-2 border rounded">
              {feeReimbursementOptions.map(o => (
                <option key={o} value={o}>
                  {o === 'YES'
                    ? 'Fee Reimbursement: YES'
                    : o === 'NO'
                      ? 'Fee Reimbursement: NO'
                      : 'Fee Reimbursement: GOV'}
                </option>
              ))}
            </select>
            <input placeholder="Course" value={getBranchFromRoll(basic.roll_no) || ''} disabled className="p-2 border rounded bg-gray-100" />
            <input placeholder="Admission Type" value={getAdmissionTypeFromRoll(basic.roll_no) || ''} disabled className="p-2 border rounded bg-gray-100" />
            <div className="flex items-center">
              <span className="px-3 py-2 border border-r-0 bg-gray-100">+91</span>
              <input
                placeholder="Mobile*"
                value={basic.mobile}
                onChange={(e) => {
                  const digits = String(e.target.value || '').replace(/\D/g, '').slice(0, MAX_MOBILE_LEN);
                  setBasic({...basic, mobile: digits});
                  if (digits.length !== MAX_MOBILE_LEN) setMobileError('Mobile must be 10 digits'); else setMobileError('');
                }}
                onPaste={(e) => { const pasted = (e.clipboardData || window.clipboardData).getData('text'); const digits = pasted.replace(/\D/g,'').slice(0, MAX_MOBILE_LEN); setBasic(prev=>({...prev, mobile: digits})); e.preventDefault(); }}
                className="p-2 border rounded w-full"
                inputMode="numeric"
                maxLength={MAX_MOBILE_LEN}
              />
            </div>
            {mobileError && <div className="text-xs text-red-600 mt-1">{mobileError}</div>}
            <input type="email" placeholder="Email*" value={basic.email} onChange={e=>setBasic({...basic, email:e.target.value})} className="p-2 border rounded" />
          </div>
        </div>

        <div>
          <h3 className="font-bold">Section B: Personal Details</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mt-2">
            <input placeholder="Father Name" value={personal.father_name} onChange={e=>setPersonal({...personal, father_name:e.target.value})} className="p-2 border rounded" />
            <input placeholder="Mother Name" value={personal.mother_name} onChange={e=>setPersonal({...personal, mother_name:e.target.value})} className="p-2 border rounded" />
            <input placeholder="Nationality" value={personal.nationality} onChange={e=>setPersonal({...personal, nationality:e.target.value})} className="p-2 border rounded" />
            <select value={personal.religion || ''} onChange={e=>setPersonal({...personal, religion:e.target.value})} className="p-2 border rounded">
                <option value="">Select Religion</option>
                {COLLEGE_CONFIG.religions.map(r => (
                    <option key={r} value={r.toUpperCase()}>{r.toUpperCase()}</option>
                ))}
            </select>
            <select value={personal.category} onChange={e=>setPersonal({...personal, category:e.target.value})} className="p-2 border rounded">{categories.map(c=> <option key={c} value={c}>{c}</option>)}</select>
            <input placeholder="Sub Caste" value={personal.sub_caste} onChange={e=>setPersonal({...personal, sub_caste:e.target.value})} className="p-2 border rounded" />
            <select value={personal.area_status} onChange={e=>setPersonal({...personal, area_status:e.target.value})} className="p-2 border rounded"><option>Local</option><option>Non-Local</option></select>
            <input placeholder="Mother Tongue" value={personal.mother_tongue} onChange={e=>setPersonal({...personal, mother_tongue:e.target.value})} className="p-2 border rounded" />
            <input placeholder="Place of Birth" value={personal.place_of_birth} onChange={e=>setPersonal({...personal, place_of_birth:e.target.value})} className="p-2 border rounded" />
            <input placeholder="Father Occupation" value={personal.father_occupation} onChange={e=>setPersonal({...personal, father_occupation:e.target.value})} className="p-2 border rounded" />
            <input 
              placeholder="Annual Income"
              value={personal.annual_income} 
              onChange={e => {
                const raw = e.target.value.replace(/\D/g, '');
                if (raw && parseInt(raw) > 2000000) return;
                setPersonal({...personal, annual_income: formatIndianNumber(raw)});
              }} 
              className="p-2 border rounded"
            />
            <div className="flex items-center">
              <span className="px-3 py-2 border border-r-0 bg-gray-100 text-sm text-gray-500 font-medium">+91</span>
              <input
                placeholder="Guardian Mobile"
                value={personal.guardian_mobile}
                onChange={(e) => {
                  const digits = String(e.target.value || '').replace(/\D/g, '').slice(0, 10);
                  setPersonal({...personal, guardian_mobile: digits});
                }}
                className="p-2 border rounded rounded-l-none w-full"
                inputMode="numeric"
                maxLength={10}
              />
            </div>
            {incomeError && <div className="text-xs text-red-600 mt-1">{incomeError}</div>}
            <input placeholder="Aadhaar Number" value={personal.aadhaar_no} onChange={e=>setPersonal({...personal, aadhaar_no: formatAadhaar(e.target.value)})} className="p-2 border rounded" maxLength={14} />
            <select value={personal.blood_group || ''} onChange={e=>setPersonal({...personal, blood_group: e.target.value})} className="p-2 border rounded">
              <option value="">Blood Group (optional)</option>
              {COLLEGE_CONFIG.bloodGroups.map(bg => (
                <option key={bg} value={bg}>{bg}</option>
              ))}
            </select>

            {/* Current Address */}
            <div className="md:col-span-3 border-t border-gray-100 pt-4 mt-2">
              <h4 className="text-sm font-bold text-indigo-900 mb-2 uppercase tracking-wider">Current Address</h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <input placeholder="House No*" value={personal.curr_house_no} onChange={e => handleAddressChange('curr_house_no', e.target.value)} className="p-2 border rounded" />
                <input placeholder="Apartment / Landmark" value={personal.curr_apartment} onChange={e => handleAddressChange('curr_apartment', e.target.value)} className="p-2 border rounded" />
                <input placeholder="Street*" value={personal.curr_street} onChange={e => handleAddressChange('curr_street', e.target.value)} className="p-2 border rounded" />
                <input placeholder="City*" value={personal.curr_city} onChange={e => handleAddressChange('curr_city', e.target.value)} className="p-2 border rounded" />
                <input placeholder="State*" value={personal.curr_state} onChange={e => handleAddressChange('curr_state', e.target.value)} className="p-2 border rounded" />
                <input placeholder="PIN Code*" value={personal.curr_pincode} onChange={e => handleAddressChange('curr_pincode', e.target.value.replace(/\D/g, ''))} maxLength={6} className="p-2 border rounded" />
                <input placeholder="Country*" value={personal.curr_country} onChange={e => handleAddressChange('curr_country', e.target.value)} className="p-2 border rounded md:col-span-3" />
              </div>
            </div>

            {/* Sync Checkbox */}
            <div className="md:col-span-3 flex items-center gap-2 py-2">
              <input 
                type="checkbox" 
                id="add_is_current_same_as_permanent" 
                checked={personal.is_current_same_as_permanent} 
                onChange={e => handleCheckboxChange(e.target.checked)} 
                className="h-4 w-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500 cursor-pointer" 
              />
              <label htmlFor="add_is_current_same_as_permanent" className="text-sm font-bold text-gray-700 select-none cursor-pointer">
                Mark as permanent address
              </label>
            </div>

            {/* Permanent Address */}
            <div className="md:col-span-3 border-t border-gray-100 pt-4">
              <h4 className="text-sm font-bold text-indigo-900 mb-2 uppercase tracking-wider">Permanent Address</h4>
              {!personal.is_current_same_as_permanent ? (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                  <input placeholder="House No*" value={personal.perm_house_no} onChange={e => setPersonal({...personal, perm_house_no: e.target.value})} className="p-2 border rounded" />
                  <input placeholder="Apartment / Landmark" value={personal.perm_apartment} onChange={e => setPersonal({...personal, perm_apartment: e.target.value})} className="p-2 border rounded" />
                  <input placeholder="Street*" value={personal.perm_street} onChange={e => setPersonal({...personal, perm_street: e.target.value})} className="p-2 border rounded" />
                  <input placeholder="City*" value={personal.perm_city} onChange={e => setPersonal({...personal, perm_city: e.target.value})} className="p-2 border rounded" />
                  <input placeholder="State*" value={personal.perm_state} onChange={e => setPersonal({...personal, perm_state: e.target.value})} className="p-2 border rounded" />
                  <input placeholder="PIN Code*" value={personal.perm_pincode} onChange={e => setPersonal({...personal, perm_pincode: e.target.value.replace(/\D/g, '')})} maxLength={6} className="p-2 border rounded" />
                  <input placeholder="Country*" value={personal.perm_country} onChange={e => setPersonal({...personal, perm_country: e.target.value})} className="p-2 border rounded md:col-span-3" />
                </div>
              ) : (
                <div className="text-xs font-semibold text-gray-500 bg-gray-50 border border-gray-100 p-3 rounded uppercase tracking-wide">
                  Permanent address is synchronized with current address.
                </div>
              )}
            </div>

            <textarea placeholder="Identification Marks (optional)" value={personal.identification_marks} onChange={e=>setPersonal({...personal, identification_marks:e.target.value})} className="p-2 border rounded md:col-span-3 h-24 resize-none" style={{overflow: 'hidden'}} />
          </div>
        </div>
        <div>
          <h3 className="font-bold">Section C: Academic & Identification</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mt-2">
            <select
              value={academic.qualifying_exam}
              onChange={e => setAcademic({...academic, qualifying_exam:e.target.value})}
              className="p-2 border rounded"
            >
              <option>TG EAPCET</option>
              <option>TG ECET</option>
              <option>PGECET</option>
            </select>
            <input
              placeholder="SSC (10th) Marks"
              value={academic.ssc_marks}
              onChange={e => setAcademic({...academic, ssc_marks:e.target.value})}
              className="p-2 border rounded"
            />
            <input
              placeholder="Inter / Diploma Marks"
              value={academic.inter_marks}
              onChange={e => setAcademic({...academic, inter_marks:e.target.value})}
              className="p-2 border rounded"
            />
            <textarea placeholder="Previous College Details" value={academic.previous_college_details} onChange={e=>setAcademic({...academic, previous_college_details:e.target.value})} className="p-2 border rounded md:col-span-3 h-24 resize-none" rows={3} style={{overflow:'hidden'}} />
            <select value={academic.medium_of_instruction} onChange={e=>setAcademic({...academic, medium_of_instruction:e.target.value})} className="p-2 border rounded"><option>Telugu</option><option>English</option><option>Other</option></select>
            
            <input
              placeholder="Entrance Rank"
              type="number"
              value={academic.ranks}
              onChange={e => setAcademic({...academic, ranks:e.target.value})}
              className="p-2 border rounded"
            />
          </div>
        </div>

        <div>
          <h3 className="font-bold">Section D: Documents Upload (Max 1MB)</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-2">
            <div className="space-y-1">
              <label className="text-sm font-medium text-gray-700">Student Photo (PFP)</label>
              <input type="file" accept="image/*" onChange={(e) => handleFileChange(e, 'pfp')} className="p-2 border rounded w-full" />
              {files.pfp && <Image src={files.pfp} alt="Preview" className="h-20 w-20 object-cover border rounded mt-1" width={80} height={80} unoptimized />}
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium text-gray-700">Student Signature</label>
              <input type="file" accept="image/*" onChange={(e) => handleFileChange(e, 'signature')} className="p-2 border rounded w-full" />
              {files.signature && <Image src={files.signature} alt="Preview" className="h-12 w-32 object-contain border rounded mt-1" width={128} height={48} unoptimized />}
            </div>
          </div>
        </div>

        <div className="flex justify-end">
          <button type="submit" disabled={!addRequiredFilled() || addLoading} className="px-4 py-2 bg-indigo-600 text-white rounded disabled:opacity-50">{addLoading? 'Saving...':'Save'}</button>
        </div>
      </form>
      ) : (
        <div className="p-4 bg-green-50 text-green-800 rounded">Data added to Database</div>
      )
  );
}

"use client";
import React, { useState } from 'react';
import Image from 'next/image';
import toast from 'react-hot-toast';
import * as XLSX from 'xlsx-js-style';
import { branchCodes, getBatchFromRoll } from '@/lib/rollNumber';
import { getAssetUrl } from '@/lib/assets';

const ExportStudents = () => {
  const [branch, setBranch] = useState('');
  const [year, setYear] = useState('');
  const [loading, setLoading] = useState(false);
  const [previewData, setPreviewData] = useState(null);

  // Generate admission years as Batches (e.g., 2023 - 2027)
  const currentYear = new Date().getFullYear();
  const batches = [];
  for (let y = currentYear; y >= 2020; y--) {
    batches.push({
      label: `BATCH ${y} - ${y + 4}`,
      value: `${y}-${y + 4}`
    });
  }

  const handleFetch = async () => {
    if (!branch || !year) {
      toast.error('Please select both Branch and Batch');
      return;
    }

    setLoading(true);
    setPreviewData(null);
    try {
      const params = new URLSearchParams({
        branch: branch,
        year: year
      });
      const response = await fetch(`/api/clerk/admission/export-students?${params.toString()}`);
      const data = await response.json();

      if (!response.ok) throw new Error(data.error || 'Failed to fetch data');

      if (!data.students || data.students.length === 0) {
        toast.error('No students found for the selected criteria');
        return;
      }

      setPreviewData(data.students);
      toast.success(`Found ${data.students.length} student records.`);
    } catch (error) {
      toast.error('Failed to fetch students');
    } finally {
      setLoading(false);
    }
  };

  const handleExport = () => {
    if (!previewData || previewData.length === 0) {
      toast.error('No data available to export');
      return;
    }
    exportToExcel(previewData, branch, year);
    toast.success(`Successfully exported ${previewData.length} student records.`);
  };

  const maskAadhaar = (value) => {
    if (!value || typeof value !== 'string' || value.length < 4) return 'N/A';
    return `XXXX-XXXX-${value.slice(-4)}`;
  };

  const maskMobile = (value) => {
    if (!value || typeof value !== 'string' || value.length < 5) return 'N/A';
    return `XXXXX${value.slice(-5)}`;
  };

  const isValidImageUrl = (url) => {
    if (!url) return false;
    try {
      const urlObj = new URL(url);
      return urlObj.hostname.includes('cloudinary.com');
    } catch {
      return false;
    }
  };

  const exportToExcel = (students, branchCode, batch) => {
    const branchName = branchCodes[branchCode] || branchCode;
    
    // Flatten and format data for Excel
    const worksheetData = students.map(s => ({
      'Roll Number': s.roll_no,
      'Admission Number': s.admission_no,
      'Batch': getBatchFromRoll(s.roll_no),
      'Full Name': s.name,
      'Gender': s.gender,
      'Date of Birth': s.dob,
      'Email': s.email,
      'Mobile Number': s.mobile,
      'Father Name': s.father_name,
      'Mother Name': s.mother_name,
      'Nationality': s.nationality,
      'Religion': s.religion,
      'Category': s.category,
      'Sub-Caste': s.sub_caste,
      'Area Status': s.area_status,
      'Mother Tongue': s.mother_tongue,
      'Place of Birth': s.place_of_birth,
      'Father Occupation': s.father_occupation,
      'Annual Income': s.annual_income,
      'Aadhaar Number': maskAadhaar(s.aadhaar_no),
      'Guardian Mobile': maskMobile(s.guardian_mobile),
      'Permanent Address': s.permanent_address ? s.permanent_address.split(',')[0] : 'N/A',
      'Identification Marks': s.identification_marks,
      'Seat Allotted Category': s.seat_allotted_category,
      'Blood Group': s.blood_group,
      'Fee Reimbursement': s.fee_reimbursement,
      'Qualifying Exam': s.qualifying_exam,
      'SSC Marks': s.ssc_marks,
      'Inter/Diploma Marks': s.inter_marks,
      'Entrance Exam Rank': s.entrance_exam_rank,
      'Previous College': s.previous_college,
      'Photo URL': s.photo ? getAssetUrl(s.photo) : 'N/A',
      'Signature URL': s.signature ? getAssetUrl(s.signature) : 'N/A'
    }));

    const worksheet = XLSX.utils.json_to_sheet(worksheetData);
    
    // Styling the header
    const headerRange = XLSX.utils.decode_range(worksheet['!ref']);
    for (let col = headerRange.s.c; col <= headerRange.e.c; col++) {
      const address = XLSX.utils.encode_col(col) + '1';
      if (!worksheet[address]) continue;
      worksheet[address].s = {
        font: { bold: true, color: { rgb: "FFFFFF" } },
        fill: { fgColor: { rgb: "4F46E5" } }, // Indigo-600
        alignment: { horizontal: "center" }
      };
    }

    // Setting column widths
    const columnWidths = [
      { wch: 15 }, { wch: 18 }, { wch: 12 }, { wch: 25 }, { wch: 10 }, { wch: 12 }, { wch: 25 }, { wch: 15 },
      { wch: 25 }, { wch: 25 }, { wch: 12 }, { wch: 12 }, { wch: 10 }, { wch: 15 }, { wch: 12 },
      { wch: 15 }, { wch: 12 }, { wch: 20 }, { wch: 15 }, { wch: 18 }, { wch: 15 }, { wch: 40 },
      { wch: 30 }, { wch: 20 }, { wch: 10 }, { wch: 15 }, { wch: 15 }, { wch: 10 }, { wch: 15 },
      { wch: 15 }, { wch: 30 }, { wch: 50 }, { wch: 50 }
    ];
    worksheet['!cols'] = columnWidths;

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Students');
    XLSX.writeFile(workbook, `KUCET_Students_${branchName}_Batch_${batch}.xlsx`);
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* 1. Configuration Section */}
      <div className="bg-white p-8 rounded-sm border border-slate-200 shadow-sm">
        <div className="flex items-center gap-3 mb-6 border-b border-slate-100 pb-4">
          <div className="w-8 h-8 bg-indigo-50 rounded-full flex items-center justify-center text-indigo-600">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
               <path d="M7 3a1 1 0 000 2h6a1 1 0 100-2H7zM4 7a1 1 0 011-1h10a1 1 0 110 2H5a1 1 0 01-1-1zM2 11a2 2 0 012-2h12a2 2 0 012 2v4a2 2 0 01-2 2H4a2 2 0 01-2-2v-4z" />
             </svg>
          </div>
          <div>
            <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight">Student Data Migration</h3>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">Filter records and preview before university integration</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Academic Branch</label>
            <select 
              value={branch}
              onChange={(e) => setBranch(e.target.value)}
              className="w-full h-12 bg-slate-50 border-2 border-slate-100 rounded-sm px-4 text-sm font-bold text-slate-700 focus:outline-none focus:border-indigo-500 transition-all uppercase"
            >
              <option value="">SELECT BRANCH</option>
              {Object.entries(branchCodes).map(([code, name]) => (
                <option key={code} value={code}>{name}</option>
              ))}
            </select>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Admission Batch (4-Year Range)</label>
            <select 
              value={year}
              onChange={(e) => setYear(e.target.value)}
              className="w-full h-12 bg-slate-50 border-2 border-slate-100 rounded-sm px-4 text-sm font-bold text-slate-700 focus:outline-none focus:border-indigo-500 transition-all uppercase"
            >
              <option value="">SELECT BATCH</option>
              {batches.map(b => (
                <option key={b.value} value={b.value}>{b.label}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="flex flex-col md:flex-row items-center justify-end gap-4">
          <button 
            onClick={handleFetch}
            disabled={loading}
            className={`w-full md:w-auto h-12 px-8 bg-slate-800 text-white text-[11px] font-black uppercase tracking-[0.2em] rounded-sm hover:bg-slate-900 transition-all shadow-md disabled:bg-slate-300 disabled:cursor-not-allowed flex items-center justify-center gap-3`}
          >
            {loading ? (
              <>
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                <span>Scanning Registry...</span>
              </>
            ) : (
              <>
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z" clipRule="evenodd" />
                </svg>
                <span>Fetch Records</span>
              </>
            )}
          </button>
        </div>
      </div>

      {/* 2. Preview Section */}
      {previewData && (
        <div className="bg-white rounded-sm border border-slate-200 shadow-sm overflow-hidden animate-slideUp">
          <div className="bg-slate-50 px-8 py-4 border-b border-slate-200 flex flex-col md:flex-row items-center justify-between gap-4">
             <div className="flex items-center gap-4">
                <span className="text-[10px] font-black bg-indigo-600 text-white px-2 py-1 rounded-sm uppercase tracking-widest">{previewData.length} Records</span>
                <p className="text-xs font-bold text-slate-500 uppercase tracking-tight">Previewing {branchCodes[branch]} Registry for Batch {year}</p>
             </div>
             
             <button 
                onClick={handleExport}
                className="h-10 px-6 bg-green-600 text-white text-[10px] font-black uppercase tracking-[0.15em] rounded-sm hover:bg-green-700 transition-all flex items-center gap-2"
             >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
                </svg>
                Download Excel (Migration Ready)
             </button>
          </div>
          
          <div className="overflow-x-auto max-h-[500px]">
            <table className="w-full border-collapse">
              <thead className="sticky top-0 bg-white shadow-sm">
                <tr className="border-b-2 border-slate-100">
                  <th className="px-6 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Roll Number</th>
                  <th className="px-6 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Batch</th>
                  <th className="px-6 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Full Name</th>
                  <th className="px-6 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Aadhaar</th>
                  <th className="px-6 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Mobile</th>
                  <th className="px-6 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Photo</th>
                  <th className="px-6 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-widest">Signature</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {previewData.map((student, index) => (
                  <tr key={`${student.roll_no}-${index}`} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4 text-xs font-black text-slate-700">{student.roll_no}</td>
                    <td className="px-6 py-4 text-[10px] font-bold text-indigo-600 uppercase tracking-tight">{getBatchFromRoll(student.roll_no)}</td>
                    <td className="px-6 py-4 text-xs font-bold text-slate-600">{student.name}</td>
                    <td className="px-6 py-4 text-[11px] font-mono text-slate-500">{maskAadhaar(student.aadhaar_no)}</td>
                    <td className="px-6 py-4 text-[11px] font-mono text-slate-500">{maskMobile(student.mobile)}</td>
                    <td className="px-6 py-4">
                      {isValidImageUrl(getAssetUrl(student.photo)) ? (
                        <div className="w-8 h-8 rounded-full border-2 border-indigo-100 overflow-hidden bg-slate-100">
                           <Image src={getAssetUrl(student.photo)} width={32} height={32} className="w-full h-full object-cover" alt="S" unoptimized onError={() => {}} />
                        </div>
                      ) : (
                        <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-[10px] text-slate-400">NA</div>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      {student.signature ? (
                        <div className="h-6 w-16 bg-slate-50 border border-slate-100 p-1 flex items-center justify-center">
                           <Image src={getAssetUrl(student.signature)} width={64} height={24} className="h-full object-contain" alt="SIG" unoptimized />
                        </div>
                      ) : (
                        <span className="text-[10px] text-slate-400 italic">None</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
      
      {/* 3. Helper Note */}
      <div className="bg-amber-50 border-l-4 border-amber-400 p-4">
         <div className="flex gap-3">
           <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-amber-500 mt-0.5" viewBox="0 0 20 20" fill="currentColor">
             <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
           </svg>
           <div className="space-y-1">
             <p className="text-[10px] font-black text-amber-800 uppercase tracking-widest">Migration Protocol</p>
             <p className="text-[11px] text-amber-700 leading-relaxed font-medium">Use the preview table to verify student identity and asset presence before generating the master migration file. Photos and Signatures are linked via Cloudinary URLs for seamless remote ingestion.</p>
           </div>
         </div>
      </div>
    </div>
  );
};

export default ExportStudents;

"use client";
import React, { useState } from 'react';
import toast from 'react-hot-toast';
import { formatDate } from '@/lib/date';
import { getEntranceExamQualified, getBranchFromRoll, getAdmissionTypeFromRoll, validateRollNo } from '@/lib/rollNumber';

export default function FetchStudent({ setActiveAction, setFetchedStudent, setPersonalFull, setAcademicsList, setFeesList, setFeeDetails, setEditValues, setOriginalEditValues, setOriginalPersonalFull, setOriginalAcademicsList }) {
  const [fetchRoll, setFetchRoll] = useState('');
  const [fetchRollNoError, setFetchRollNoError] = useState('');
  const [fetchAdmission, setFetchAdmission] = useState('');
  const [fetchName, setFetchName] = useState('');
  const [fetchLoading, setFetchLoading] = useState(false);
  const [fetchError, setFetchError] = useState('');
  const [fetchedList, setFetchedList] = useState([]);

  const canFetch = () => {
    return fetchRoll.trim() || fetchAdmission.trim() || fetchName.trim();
  };

  const MAX_ROLL = 10;

  const sanitizeRoll = (input) => {
    if (input == null) return '';
    // Allow only uppercase alphanumeric characters (A-Z, 0-9)
    const s = String(input || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    return s.slice(0, MAX_ROLL);
  };

  const sanitizeDigits = (input, maxLen = 10) => {
    if (input == null) return '';
    const s = String(input).replace(/\D/g, '');
    return s.slice(0, maxLen);
  };

  const loadFullProfileByRoll = async (roll) => {
    setFetchError('');
    setFetchedStudent(null);
    try{
      const res = await fetch(`/api/clerk/students/${roll}`);
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || data.error || 'Student not found');
      const student = {
        ...data.student,
        academics: data.academics,
        fees: data.fees,
        student_fee_details: data.student_fee_details
      };
      setFetchedStudent(student);
      const pd = student.personal_details || {};
      setPersonalFull({
        father_name: pd.father_name || student.father_name || '',
        mother_name: pd.mother_name || '',
        nationality: pd.nationality || '',
        religion: pd.religion || '',
        category: pd.category || student.category || 'OC',
        sub_caste: pd.sub_caste || '',
        area_status: pd.area_status || 'Local',
        mother_tongue: pd.mother_tongue || '',
        place_of_birth: pd.place_of_birth || '',
        father_occupation: pd.father_occupation || '',
        annual_income: pd.annual_income || '',
        guardian_mobile: pd.guardian_mobile || '',
        aadhaar_no: pd.aadhaar_no || '',
        curr_house_no: pd.curr_house_no || '',
        curr_street: pd.curr_street || '',
        curr_apartment: pd.curr_apartment || '',
        curr_city: pd.curr_city || '',
        curr_state: pd.curr_state || '',
        curr_pincode: pd.curr_pincode || '',
        curr_country: pd.curr_country || '',
        perm_house_no: pd.perm_house_no || '',
        perm_street: pd.perm_street || '',
        perm_apartment: pd.perm_apartment || '',
        perm_city: pd.perm_city || '',
        perm_state: pd.perm_state || '',
        perm_pincode: pd.perm_pincode || '',
        perm_country: pd.perm_country || '',
        is_current_same_as_permanent: !!pd.is_current_same_as_permanent,
        seat_allotted_category: pd.seat_allotted_category || '',
        identification_marks: pd.identification_marks || ''
      });

      const initialAcademics = Array.isArray(data.academics) ? data.academics : [];
      let currentQualifyingExam = initialAcademics.length > 0 ? initialAcademics[0].qualifying_exam : '';
      let currentRanks = initialAcademics.length > 0 ? initialAcademics[0].ranks : '';
      let currentSscMarks = initialAcademics.length > 0 ? initialAcademics[0].ssc_marks : '';
      let currentInterMarks = initialAcademics.length > 0 ? initialAcademics[0].inter_marks : '';

      if (!currentQualifyingExam) {
        currentQualifyingExam = getEntranceExamQualified(student.roll_no) || 'TG EAPCET';
      }
      
      if (initialAcademics.length === 0) {
        initialAcademics.push({ qualifying_exam: currentQualifyingExam, ranks: currentRanks, ssc_marks: currentSscMarks, inter_marks: currentInterMarks });
      } else {
        initialAcademics[0] = { ...initialAcademics[0], qualifying_exam: currentQualifyingExam, ranks: currentRanks, ssc_marks: currentSscMarks, inter_marks: currentInterMarks };
      }
      setAcademicsList(initialAcademics);
      setOriginalAcademicsList(JSON.parse(JSON.stringify(initialAcademics)));
      
      const initialFees = Array.isArray(data.fees) ? data.fees : [];
      setFeesList(initialFees);
      setFeeDetails(data.student_fee_details || null);

      const initialEdit = {
        admission_no: student.admission_no || null,
        roll_no: student.roll_no || null,
        name: student.name || null,
        date_of_birth: formatDate(student.date_of_birth) || null,
        gender: student.gender || 'Male',
        admission_type: getAdmissionTypeFromRoll(student.roll_no) || null,
        course: getBranchFromRoll(student.roll_no) || null,
        mobile: sanitizeDigits(student.mobile || '' , 10) || null,
        email: student.email || null,
        curr_house_no: pd.curr_house_no || null,
        curr_street: pd.curr_street || null,
        curr_apartment: pd.curr_apartment || null,
        curr_city: pd.curr_city || null,
        curr_state: pd.curr_state || null,
        curr_pincode: pd.curr_pincode || null,
        curr_country: pd.curr_country || null,
        perm_house_no: pd.perm_house_no || null,
        perm_street: pd.perm_street || null,
        perm_apartment: pd.perm_apartment || null,
        perm_city: pd.perm_city || null,
        perm_state: pd.perm_state || null,
        perm_pincode: pd.perm_pincode || null,
        perm_country: pd.perm_country || null,
        is_current_same_as_permanent: !!pd.is_current_same_as_permanent,
        father_occupation: pd.father_occupation || null,
        annual_income: sanitizeDigits(pd.annual_income || '', 12) || null
      };
      setEditValues(initialEdit);
      setOriginalEditValues(JSON.parse(JSON.stringify(initialEdit)));

      const initialPersonal = {
        father_name: pd.father_name || student.father_name || null,
        mother_name: pd.mother_name || null,
        nationality: pd.nationality || null,
        religion: pd.religion || null,
        category: pd.category || student.category || 'OC',
        sub_caste: pd.sub_caste || null,
        area_status: pd.area_status || 'Local',
        mother_tongue: pd.mother_tongue || null,
        place_of_birth: pd.place_of_birth || null,
        father_occupation: pd.father_occupation || null,
        annual_income: pd.annual_income || null,
        guardian_mobile: pd.guardian_mobile || null,
        aadhaar_no: pd.aadhaar_no || null,
        curr_house_no: pd.curr_house_no || null,
        curr_street: pd.curr_street || null,
        curr_apartment: pd.curr_apartment || null,
        curr_city: pd.curr_city || null,
        curr_state: pd.curr_state || null,
        curr_pincode: pd.curr_pincode || null,
        curr_country: pd.curr_country || null,
        perm_house_no: pd.perm_house_no || null,
        perm_street: pd.perm_street || null,
        perm_apartment: pd.perm_apartment || null,
        perm_city: pd.perm_city || null,
        perm_state: pd.perm_state || null,
        perm_pincode: pd.perm_pincode || null,
        perm_country: pd.perm_country || null,
        is_current_same_as_permanent: !!pd.is_current_same_as_permanent,
        seat_allotted_category: pd.seat_allotted_category || null,
        identification_marks: pd.identification_marks || null
      };
      setOriginalPersonalFull(JSON.parse(JSON.stringify(initialPersonal)));
      setActiveAction('view');
    } catch(err){
      console.error('Load profile error:', err);
      setFetchError(err.message || 'Failed to load profile');
    }
  };

  const handleFetch = async () => {
    setFetchError('');
    setFetchedStudent(null);
    setFetchedList([]);
    if (!canFetch()) { setFetchError('Please enter at least one search field.'); return; }
    setFetchLoading(true);
    try{
      if (fetchRoll.trim()) {
        // Validate roll client-side similar to LoginPanel
        const rn = fetchRoll.trim();
        const { isValid } = validateRollNo(rn);
        if (!isValid) {
          setFetchError('Invalid Roll Number format.');
          setFetchLoading(false);
          return;
        }
        await loadFullProfileByRoll(rn);
        return;
      }
      const params = new URLSearchParams();
      if (fetchAdmission.trim()) params.set('admission_no', fetchAdmission.trim());
      if (fetchName.trim()) params.set('name', fetchName.trim());
      const res = await fetch(`/api/clerk/students/search?${params.toString()}`);
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || data.message || 'Search failed');
      if (!data.students || data.students.length === 0) {
        setFetchError('No students found');
      } else if (data.students.length === 1) {
        await loadFullProfileByRoll(data.students[0].roll_no);
      } else {
        setFetchedList(data.students);
      }
    }catch(err){
      console.error(err);
      setFetchError(err.message || 'Fetch failed');
    }finally{ setFetchLoading(false); }
  };

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        <div>
          <input
            placeholder="Roll Number"
            value={fetchRoll}
            onChange={(e) => {
              const v = sanitizeRoll(e.target.value);
              setFetchRoll(v);
              if (v.length > 0 && v.length === MAX_ROLL) {
                const { isValid } = validateRollNo(v);
                if (!isValid) {
                  setFetchRollNoError('Invalid Roll Number format.');
                } else {
                  setFetchRollNoError('');
                }
              } else if (v.length > 0 && v.length !== MAX_ROLL) {
                setFetchRollNoError(`Roll Number must be ${MAX_ROLL} characters long.`);
              } else {
                setFetchRollNoError('');
              }
            }}  
            className="w-full p-2 border rounded"
            maxLength={MAX_ROLL}
          />
          {fetchRollNoError && <div className="text-red-600 text-sm mt-1">{fetchRollNoError}</div>}
        </div>
        <input placeholder="Admission Number" value={fetchAdmission} onChange={e=>setFetchAdmission(e.target.value)} className="w-full p-2 border rounded" />
        <input placeholder="Student Name" value={fetchName} onChange={e=>setFetchName(e.target.value)} className="w-full p-2 border rounded" />
      </div>
      <div className="flex space-x-2">
        <button
          onClick={handleFetch}
          disabled={!canFetch() || fetchLoading || !!fetchRollNoError}
          className={`px-4 py-2 bg-green-600 text-white rounded ${(!canFetch() || fetchLoading || !!fetchRollNoError) ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer hover:shadow-lg hover:ring-2 hover:ring-green-300 transition duration-150'}`}
        >
          {fetchLoading? 'Fetching...':'Fetch'}
        </button>
        <button onClick={()=>{setFetchRoll(''); setFetchAdmission(''); setFetchName(''); setFetchError(''); setFetchRollNoError('');}} className="px-4 py-2 bg-gray-100 rounded">Clear</button>
      </div>
      {fetchError && <div className="text-red-600">{fetchError}</div>}
      {fetchedList && fetchedList.length > 1 && (
        <div className="mt-3 bg-gray-50 p-3 rounded">
          <div className="text-sm font-medium mb-2">Multiple results — click to open</div>
          <div className="space-y-2">
            {fetchedList.map(s => (
              <div key={s.roll_no} className="flex items-center justify-between p-2 bg-white rounded shadow-sm">
                <div>
                  <div className="font-medium">{s.name}</div>
                  <div className="text-xs text-gray-500">Roll: {s.roll_no} • Adm: {s.admission_no || 'N/A'}</div>
                </div>
                <button onClick={()=>loadFullProfileByRoll(s.roll_no)} className="px-3 py-1 bg-indigo-600 text-white rounded text-sm cursor-pointer hover:shadow-sm transition">Open</button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useMemo, useEffect, useRef } from 'react';

export default function StudentHistoryCard({ currentClerkId }) {
  // State
  const [historyScope, setHistoryScope] = useState('my'); // 'my' | 'all'
  const [showFilters, setShowFilters] = useState(false);
  const [popoverPosition, setPopoverPosition] = useState('bottom'); // 'bottom' | 'top'
  const DEFAULT_FILTERS = { actionTypes: [], dateRange: 'all' };
  const [historyFilters, setHistoryFilters] = useState(DEFAULT_FILTERS); // staged filters
  const [appliedFilters, setAppliedFilters] = useState(DEFAULT_FILTERS); // actually applied to fetch
  const [historyData, setHistoryData] = useState({ records: [], myCount: 0, allCount: 0 });
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const triggerRef = useRef(null);
  const historyCacheRef = useRef(new Map());

  const myCount = historyData.myCount || 0;
  const allCount = historyData.allCount || 0;
  const loading = isLoadingHistory;
  const actionTypesKey = useMemo(() => [...appliedFilters.actionTypes].sort().join(','), [appliedFilters.actionTypes]);
  const requestKey = useMemo(() => `${historyScope}|${appliedFilters.dateRange}|${actionTypesKey}`, [historyScope, appliedFilters.dateRange, actionTypesKey]);

  // Helpers
  const formatDateKey = (iso) => {
    if (!iso) return 'unknown';
    const d = new Date(iso);
    const dd = String(d.getDate()).padStart(2, '0');
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const yyyy = d.getFullYear();
    return `${dd}-${mm}-${yyyy}`;
  };

  // Fetch records from backend when scope or filters change
  useEffect(() => {
    const cachedHistory = historyCacheRef.current.get(requestKey);
    if (cachedHistory) {
      setHistoryData(cachedHistory);
      return;
    }

    const controller = new AbortController();
    let isActive = true;

    const loadHistory = async () => {
      setIsLoadingHistory(true);
      try {
        const params = new URLSearchParams();
        params.set('scope', historyScope);
        params.set('dateRange', appliedFilters.dateRange);
        appliedFilters.actionTypes.forEach((type) => params.append('actionType', type));

        const res = await fetch(`/api/clerk/student-history?${params.toString()}`, { signal: controller.signal });
        if (!res.ok) return;

        const json = await res.json();
        const nextHistory = {
          records: json.records || [],
          myCount: json.myCount || 0,
          allCount: json.allCount || 0
        };

        historyCacheRef.current.set(requestKey, nextHistory);
        if (isActive) {
          setHistoryData(nextHistory);
        }
      } catch (error) {
        if (error?.name !== 'AbortError') {
          console.error('Failed to fetch student history', error);
        }
      } finally {
        if (isActive) {
          setIsLoadingHistory(false);
        }
      }
    };

    loadHistory();

    return () => {
      isActive = false;
      controller.abort();
    };
  }, [requestKey, historyScope, appliedFilters.dateRange, appliedFilters.actionTypes]);

  // Compute popover placement to avoid viewport overflow
  useEffect(() => {
    if (!showFilters) return;
    let mounted = true;
    function compute() {
      const trig = triggerRef.current;
      if (!trig) return;
      const rect = trig.getBoundingClientRect();
      const spaceBelow = window.innerHeight - rect.bottom;
      const spaceAbove = rect.top;
      const estimatedHeight = 260; // safe estimate for popover height
      if (spaceBelow < estimatedHeight && spaceAbove > estimatedHeight) {
        if (mounted) setPopoverPosition('top');
      } else {
        if (mounted) setPopoverPosition('bottom');
      }
    }
    compute();
    const onResize = () => compute();
    window.addEventListener('resize', onResize);
    window.addEventListener('scroll', onResize, true);
    return () => { mounted = false; window.removeEventListener('resize', onResize); window.removeEventListener('scroll', onResize, true); };
  }, [showFilters]);

  // Derived filtered/grouped records from recordsRaw
  const filtered = useMemo(() => {
    const raw = historyData.records || [];
    // Apply client-side actionType filter if backend didn't (defensive)
    const src = raw.filter(r => {
      if (appliedFilters.actionTypes.length > 0 && !appliedFilters.actionTypes.includes(String(r.actionType))) return false;
      return true;
    });

    const groups = {};
    src.forEach((r, idx) => {
      const key = formatDateKey(r.actionTime);
      if (!groups[key]) groups[key] = [];
      groups[key].push({ ...r, _keyId: `${r.actionType}-${r.actionTime}-${r.rollNo || 'imported'}-${idx}` });
    });

    const keys = Object.keys(groups).sort((a, b) => {
      const pa = a.split('-').reverse().join('-');
      const pb = b.split('-').reverse().join('-');
      return pb.localeCompare(pa);
    });

    return { groups, keys };
  }, [historyData.records, appliedFilters.actionTypes]);

  const toggleActionType = (type) => {
    setHistoryFilters(h => {
      const exists = h.actionTypes.includes(type);
      const newFilters = { ...h, actionTypes: exists ? h.actionTypes.filter(x => x !== type) : [...h.actionTypes, type] };
      setAppliedFilters(newFilters);
      return newFilters;
    });
  };
  // removed explicit Clear/Apply buttons — changes apply immediately

  const badgeClass = (type) => {
    if (type === 'ADDED') return 'bg-green-100 text-green-800';
    if (type === 'UPDATED') return 'bg-blue-100 text-blue-800';
    if (type === 'IMPORTED') return 'bg-purple-100 text-purple-800';
    return 'bg-gray-100 text-gray-800';
  };

  return (
    <section className="mt-6">
      <div className="bg-white rounded-lg shadow p-6">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-semibold mb-4">Student History</h2>
            <p className="text-sm text-gray-600">Audit timeline of student-related actions.</p>
          </div>

          <div className="flex items-center gap-2">
            <button type="button" onClick={() => setHistoryScope('my')} className={"px-3 py-1 text-sm rounded-md " + (historyScope === 'my' ? 'bg-indigo-600 text-white' : 'bg-gray-50 text-gray-700')}>My Activity ({myCount})</button>
            <button type="button" onClick={() => setHistoryScope('all')} className={"px-3 py-1 text-sm rounded-md " + (historyScope === 'all' ? 'bg-indigo-600 text-white' : 'bg-gray-50 text-gray-700')}>All Activity ({allCount})</button>

              <div className="relative">
              <button ref={triggerRef} type="button" onClick={() => setShowFilters(s => !s)} className="px-3 py-1 text-sm rounded-md border bg-white">Filters ⌄</button>
              {showFilters && (
                <div className={(popoverPosition === 'bottom' ? 'absolute right-0 mt-2' : 'absolute right-0 bottom-full mb-2') + ' w-72 bg-white rounded-lg shadow-lg p-4 z-20'} style={{ minWidth: 280 }}>
                  <div className="space-y-4">
                    <div>
                      <h4 className="text-sm font-medium mb-3">Action Type</h4>
                      <div className="flex items-center gap-2">
                        {['ADDED','UPDATED','IMPORTED'].map(t => {
                          const active = historyFilters.actionTypes.includes(t);
                          return (
                            <button
                              key={t}
                              type="button"
                              onClick={() => toggleActionType(t)}
                              className={
                                "px-3 py-1 text-sm rounded-full font-medium transition " +
                                (active ? 'bg-indigo-600 text-white shadow-sm' : 'bg-white border border-gray-200 text-gray-700')
                              }
                            >
                              {t.charAt(0) + t.slice(1).toLowerCase()}
                            </button>
                          );
                        })}
                      </div>
                    </div>

                    <div>
                      <h4 className="text-sm font-medium mb-3">Date Range</h4>
                      <div className="inline-flex rounded-md bg-gray-100 p-1">
                        <button
                          type="button"
                          onClick={() => {
                            const nf = { ...historyFilters, dateRange: '7' };
                            setHistoryFilters(nf);
                            setAppliedFilters(nf);
                          }}
                          className={"px-3 py-1 text-sm rounded-md font-medium " + (historyFilters.dateRange === '7' ? 'bg-white text-gray-900 shadow' : 'text-gray-700')}
                        >
                          Last 7 Days
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            const nf = { ...historyFilters, dateRange: '30' };
                            setHistoryFilters(nf);
                            setAppliedFilters(nf);
                          }}
                          className={"px-3 py-1 text-sm rounded-md font-medium " + (historyFilters.dateRange === '30' ? 'bg-white text-gray-900 shadow' : 'text-gray-700')}
                        >
                          Last 30 Days
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            const nf = { ...historyFilters, dateRange: 'all' };
                            setHistoryFilters(nf);
                            setAppliedFilters(nf);
                          }}
                          className={"px-3 py-1 text-sm rounded-md font-medium " + (historyFilters.dateRange === 'all' ? 'bg-white text-gray-900 shadow' : 'text-gray-700')}
                        >
                          All Time
                        </button>
                      </div>
                    </div>

                    {/* footer buttons removed — filters apply immediately on change */}
                  </div>
                </div>
              )}
            </div>

          </div>
        </div>

        <div className="mt-4 space-y-6">
          {loading && (
            <div className="text-sm text-gray-600">Loading activity…</div>
          )}

          {!loading && filtered.keys.length === 0 && (
            <div className="text-sm text-gray-600">No activity to display.</div>
          )}

          {filtered.keys.map(k => (
            <div key={k} className="mt-6">
              <div className="font-semibold text-gray-800 mb-3">{k}</div>
              <div className="border-b border-gray-100 mb-3" />
              <div className="space-y-2">
                {filtered.groups[k].map(act => (
                  <div key={act._keyId} className="px-3 py-2 rounded-md bg-gray-50 flex items-center justify-between hover:bg-gray-100 transition">
                    <div className="flex items-center gap-3">
                      <span className={"inline-flex items-center px-2 py-0.5 text-xs font-medium rounded " + badgeClass(act.actionType)}>{act.actionType}</span>
                      <div className="text-sm text-gray-800">
                        {act.rollNo ? <strong className="mr-2">{act.rollNo}</strong> : null}
                        {act.actionType === 'IMPORTED' ? `Imported ${act.totalRecords ?? ''} students` : (act.actionType === 'ADDED' ? 'Student Created' : 'Student Updated')}
                        {historyScope === 'all' && act.clerkName ? (
                          <div className="text-xs text-gray-500 mt-1">By: {act.clerkName}</div>
                        ) : null}
                      </div>
                    </div>
                    <div className="text-xs text-gray-500">{new Date(act.actionTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

"use client";
import React, { useState, useEffect, forwardRef } from 'react';
import toast from 'react-hot-toast';
import { formatDate, parseDate } from '@/lib/date';
import Image from 'next/image';
import ImagePreviewModal from '@/components/ImagePreviewModal';
import DatePicker from 'react-datepicker';
import "react-datepicker/dist/react-datepicker.css";
import { getBranchFromRoll, getAdmissionTypeFromRoll, getEntranceExamQualified } from '@/lib/rollNumber';
import { COLLEGE_CONFIG } from '@/lib/college-config';
import { formatIndianNumber } from '@/lib/financial-utils';
import { getAssetUrl } from '@/lib/assets';

const DatePickerInput = forwardRef(({ value, onClick, ...props }, ref) => (
    <input
      onClick={onClick}
      ref={ref}
      value={value ?? ''}
      {...props}
    />
  ));
DatePickerInput.displayName = 'DatePickerInput';

export default function ViewEditStudent({ fetchedStudent, setActiveAction }) {
  const MAX_MOBILE_LEN = 10;
  const MAX_ANNUAL_INCOME = 99999999; // match AddNewStudent
  const [editValues, setEditValues] = useState({});
  const [personalFull, setPersonalFull] = useState({});
  const [academicsList, setAcademicsList] = useState([]);
  const [feesList, setFeesList] = useState([]);
  const [feeDetails, setFeeDetails] = useState(null);
  const [saving, setSaving] = useState(false);
  const [originalEditValues, setOriginalEditValues] = useState(null);
  const [originalPersonalFull, setOriginalPersonalFull] = useState(null);
  const [originalAcademicsList, setOriginalAcademicsList] = useState(null);
  const [imagePreviewOpen, setImagePreviewOpen] = useState(false);
  const [imagePreviewSrc, setImagePreviewSrc] = useState(null);
  const [annualIncomeDisplay, setAnnualIncomeDisplay] = useState('');
  const [imageLoading, setImageLoading] = useState(true);

  const sanitizeDigits = (input, maxLen = 10) => {
    if (input == null) return '';
    const s = String(input).replace(/\D/g, '');
    return s.slice(0, maxLen);
  };

  useEffect(() => {
    if (fetchedStudent?.pfp) {
      const id = setTimeout(() => setImageLoading(true), 0);
      return () => clearTimeout(id);
    }
    return undefined;
  }, [fetchedStudent?.pfp]);

  useEffect(() => {
    if (!fetchedStudent) return undefined;

    const pd = fetchedStudent.personal_details || {};
    const initialEdit = {
      admission_no: fetchedStudent.admission_no || null,
      roll_no: fetchedStudent.roll_no || null,
      fee_reimbursement: fetchedStudent.fee_reimbursement || null,
      name: fetchedStudent.name || null,
      date_of_birth: formatDate(fetchedStudent.date_of_birth) || null,
      gender: fetchedStudent.gender || 'Male',
      admission_type: getAdmissionTypeFromRoll(fetchedStudent.roll_no) || null,
      course: getBranchFromRoll(fetchedStudent.roll_no) || null,
      mobile: sanitizeDigits(fetchedStudent.mobile || '' , 10) || null,
      email: fetchedStudent.email || null,
      curr_house_no: pd.curr_house_no || null,
      curr_street: pd.curr_street || null,
      curr_apartment: pd.curr_apartment || null,
      curr_city: pd.curr_city || null,
      curr_state: pd.curr_state || null,
      curr_pincode: pd.curr_pincode || null,
      curr_country: pd.curr_country || null,
      perm_house_no: pd.perm_house_no || null,
      perm_street: pd.perm_street || null,
      perm_apartment: pd.perm_apartment || null,
      perm_city: pd.perm_city || null,
      perm_state: pd.perm_state || null,
      perm_pincode: pd.perm_pincode || null,
      perm_country: pd.perm_country || null,
      is_current_same_as_permanent: !!pd.is_current_same_as_permanent,
      father_occupation: pd.father_occupation || null,
      annual_income: pd.annual_income || null,
      admission_date: formatDate(fetchedStudent.admission_date) || null,
      student_status: fetchedStudent.student_status || 'ACTIVE',
      academic_status: fetchedStudent.academic_status || 'ACTIVE',
      academic_offset_years: fetchedStudent.academic_offset_years || 0
    };

    const initialPersonal = {
      father_name: pd.father_name || fetchedStudent.father_name || null,
      mother_name: pd.mother_name || null,
      nationality: pd.nationality || null,
      religion: pd.religion || null,
      category: pd.category || fetchedStudent.category || 'OC',
      sub_caste: pd.sub_caste || null,
      area_status: pd.area_status || 'Local',
      mother_tongue: pd.mother_tongue || null,
      place_of_birth: pd.place_of_birth || null,
      father_occupation: pd.father_occupation || null,
      annual_income: pd.annual_income || null,
      guardian_mobile: pd.guardian_mobile || null,
      aadhaar_no: pd.aadhaar_no || null,
      blood_group: pd.blood_group || null,
      curr_house_no: pd.curr_house_no || null,
      curr_street: pd.curr_street || null,
      curr_apartment: pd.curr_apartment || null,
      curr_city: pd.curr_city || null,
      curr_state: pd.curr_state || null,
      curr_pincode: pd.curr_pincode || null,
      curr_country: pd.curr_country || null,
      perm_house_no: pd.perm_house_no || null,
      perm_street: pd.perm_street || null,
      perm_apartment: pd.perm_apartment || null,
      perm_city: pd.perm_city || null,
      perm_state: pd.perm_state || null,
      perm_pincode: pd.perm_pincode || null,
      perm_country: pd.perm_country || null,
      is_current_same_as_permanent: !!pd.is_current_same_as_permanent,
      seat_allotted_category: pd.seat_allotted_category || null,
      identification_marks: pd.identification_marks || null
    };

    // Copy arrays so we never mutate props.
    const initialAcademics = Array.isArray(fetchedStudent.academics) ? [...fetchedStudent.academics] : [];
    let currentQualifyingExam = initialAcademics.length > 0 ? initialAcademics[0].qualifying_exam : '';
    let currentRanks = initialAcademics.length > 0 ? initialAcademics[0].ranks : '';
    let currentSscMarks = initialAcademics.length > 0 ? initialAcademics[0].ssc_marks : '';
    let currentInterMarks = initialAcademics.length > 0 ? initialAcademics[0].inter_marks : '';
    let currentMediumOfInstruction = initialAcademics.length > 0 ? initialAcademics[0].medium_of_instruction : 'English';
    let currentPreviousCollege = initialAcademics.length > 0 ? initialAcademics[0].previous_college_details : '';

    if (!currentQualifyingExam) {
      currentQualifyingExam = getEntranceExamQualified(fetchedStudent.roll_no) || 'TG EAPCET';
    }
    if (initialAcademics.length === 0) {
      initialAcademics.push({ 
        qualifying_exam: currentQualifyingExam, 
        ranks: currentRanks, 
        ssc_marks: currentSscMarks, 
        inter_marks: currentInterMarks,
        medium_of_instruction: currentMediumOfInstruction,
        previous_college_details: currentPreviousCollege
      });
    } else {
      initialAcademics[0] = { 
        ...initialAcademics[0], 
        qualifying_exam: currentQualifyingExam, 
        ranks: currentRanks, 
        ssc_marks: currentSscMarks, 
        inter_marks: currentInterMarks,
        medium_of_instruction: currentMediumOfInstruction,
        previous_college_details: currentPreviousCollege
      };
    }

    const feesCopy = Array.isArray(fetchedStudent.fees) ? [...fetchedStudent.fees] : [];
    const feeDet = fetchedStudent.student_fee_details || null;

    const id = setTimeout(() => {
      setEditValues(initialEdit);
      setOriginalEditValues(JSON.parse(JSON.stringify(initialEdit)));

      setPersonalFull(initialPersonal);
      setOriginalPersonalFull(JSON.parse(JSON.stringify(initialPersonal)));

      setAcademicsList(initialAcademics);
      setOriginalAcademicsList(JSON.parse(JSON.stringify(initialAcademics)));

      setFeesList(feesCopy);
      setFeeDetails(feeDet);
    }, 0);

    return () => clearTimeout(id);
  }, [fetchedStudent]);
  
  const formatAadhaar = (val) => {
    if (val == null) return '';
    const digits = String(val).replace(/\D/g, '').slice(0, 12);
    if (!digits) return '';
    return digits.replace(/(\d{4})(?=\d)/g, '$1 ').trim();
  };

  const handleCheckboxChange = (checked) => {
    setPersonalFull(prev => {
      const updated = { ...prev, is_current_same_as_permanent: checked };
      if (checked) {
        updated.perm_house_no = prev.curr_house_no;
        updated.perm_street = prev.curr_street;
        updated.perm_apartment = prev.curr_apartment;
        updated.perm_city = prev.curr_city;
        updated.perm_state = prev.curr_state;
        updated.perm_pincode = prev.curr_pincode;
        updated.perm_country = prev.curr_country;
      }
      return updated;
    });
  };

  const handleAddressChange = (field, value) => {
    setPersonalFull(prev => {
      const updated = { ...prev, [field]: value };
      if (prev.is_current_same_as_permanent && field.startsWith('curr_')) {
        const permField = field.replace('curr_', 'perm_');
        updated[permField] = value;
      }
      return updated;
    });
  };

  const handleSaveEdits = async () => {
    if (!fetchedStudent) return;
    setSaving(true);
    const toastId = toast.loading('Saving changes...');
    try {
      const roll = fetchedStudent.roll_no;
      const updatedData = {
        name: editValues.name,
        admission_no: editValues.admission_no,
        fee_reimbursement: editValues.fee_reimbursement,
        date_of_birth: editValues.date_of_birth,
        gender: editValues.gender,
        mobile: editValues.mobile,
        email: editValues.email,
        father_name: personalFull.father_name,
        mother_name: personalFull.mother_name,
        nationality: personalFull.nationality,
        religion: personalFull.religion,
        category: personalFull.category,
        sub_caste: personalFull.sub_caste,
        area_status: personalFull.area_status,
        mother_tongue: personalFull.mother_tongue,
        place_of_birth: personalFull.place_of_birth,
        father_occupation: personalFull.father_occupation,
        annual_income: personalFull.annual_income ? personalFull.annual_income.toString().replace(/,/g, '') : null,
        admission_date: editValues.admission_date,
        student_status: editValues.student_status,
        academic_status: editValues.academic_status,
        academic_offset_years: editValues.academic_offset_years,
        guardian_mobile: personalFull.guardian_mobile,
        aadhaar_no: personalFull.aadhaar_no,
        curr_house_no: personalFull.curr_house_no,
        curr_street: personalFull.curr_street,
        curr_apartment: personalFull.curr_apartment,
        curr_city: personalFull.curr_city,
        curr_state: personalFull.curr_state,
        curr_pincode: personalFull.curr_pincode,
        curr_country: personalFull.curr_country,
        perm_house_no: personalFull.perm_house_no,
        perm_street: personalFull.perm_street,
        perm_apartment: personalFull.perm_apartment,
        perm_city: personalFull.perm_city,
        perm_state: personalFull.perm_state,
        perm_pincode: personalFull.perm_pincode,
        perm_country: personalFull.perm_country,
        is_current_same_as_permanent: !!personalFull.is_current_same_as_permanent,
        seat_allotted_category: personalFull.seat_allotted_category,
        identification_marks: personalFull.identification_marks,
        blood_group: personalFull.blood_group,
        qualifying_exam: academicsList[0]?.qualifying_exam,
        previous_college_details: academicsList[0]?.previous_college_details,
        medium_of_instruction: academicsList[0]?.medium_of_instruction,
        ranks: academicsList[0]?.ranks,
        ssc_marks: academicsList[0]?.ssc_marks,
        inter_marks: academicsList[0]?.inter_marks,
      };

      const res = await fetch(`/api/clerk/admission/students/${roll}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedData),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || 'Failed to update student details');
      }
      toast.success('Saved changes successfully', { id: toastId });
      // After successful save, you might want to refetch the data or update the state
    } catch (err) {
      console.error(err);
      toast.error(err.message || 'Save failed', { id: toastId });
    } finally {
      setSaving(false);
    }
  };

  const genders = COLLEGE_CONFIG.genders;
  const categories = COLLEGE_CONFIG.categories;

  const hasEdits = () => {
    try {
      if (!originalEditValues && !originalPersonalFull && !originalAcademicsList) return false;
      if (originalEditValues && JSON.stringify(originalEditValues) !== JSON.stringify(editValues)) return true;
      if (originalPersonalFull && JSON.stringify(originalPersonalFull) !== JSON.stringify(personalFull)) return true;
      if (originalAcademicsList && JSON.stringify(originalAcademicsList) !== JSON.stringify(academicsList)) return true;
      return false;
    } catch (e) { return false; }
  };

  return (
    <div>
      {!fetchedStudent && <div className="text-gray-600">No student loaded. Use Fetch to load a student.</div>}
      {fetchedStudent && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="md:col-span-1 bg-gray-50 p-4 rounded">
              <h4 className="font-semibold mb-3 text-indigo-700">Profile Sidebar</h4>
              <div className="space-y-6">
                <div>
                  <div className="text-xs font-bold text-gray-500 mb-2 uppercase">Profile Photo</div>
                  <div className="w-28 h-28 rounded-full bg-gray-100 overflow-hidden mb-3 flex items-center justify-center relative border-2 border-indigo-100">
                    {(() => {
                      const p = fetchedStudent.pfp;
                      const has = p && String(p).trim() !== '';
                      const isData = has && String(p).startsWith('data:');
                      const dataHasBody = !isData || (String(p).includes(',') && String(p).split(',')[1].trim() !== '');
                      if (has && dataHasBody) {
                        return (
                            <>
                                {imageLoading && (
                                    <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-100 z-10 space-y-1">
                                        <div className="animate-spin h-6 w-6 border-2 border-indigo-500 border-t-transparent rounded-full"></div>
                                        <span className="text-[10px] text-gray-500 font-medium">Loading...</span>
                                    </div>
                                )}
                                <Image 
                                    src={getAssetUrl(String(p))} 
                                    alt="Profile" 
                                    width={112} 
                                    height={112} 
                                    unoptimized
                                    onClick={(e) => { e.stopPropagation(); setImagePreviewSrc(getAssetUrl(String(p))); setImagePreviewOpen(true); }} 
                                    className={`w-full h-full object-cover cursor-pointer transition-opacity duration-300 ${imageLoading ? 'opacity-0' : 'opacity-100'}`}
                                    onLoad={() => setImageLoading(false)}
                                />
                            </>
                        );
                      }
                      return <div className="text-gray-400 text-xs">No Photo</div>;
                    })()}
                  </div>
                </div>

                <div>
                  <div className="text-xs font-bold text-gray-500 mb-2 uppercase">Signature</div>
                  <div className="w-32 h-12 bg-white rounded border border-gray-200 overflow-hidden mb-1 flex items-center justify-center">
                    {fetchedStudent.signature ? (
                      <Image
                        src={getAssetUrl(fetchedStudent.signature)}
                        alt="Signature"
                        width={128}
                        height={48}
                        className="max-h-full max-w-full object-contain"
                        onClick={() => { setImagePreviewSrc(getAssetUrl(fetchedStudent.signature)); setImagePreviewOpen(true); }}
                      />
                    ) : (
                      <div className="text-gray-400 text-[10px]">No Signature</div>
                    )}
                  </div>
                </div>
              </div>
              <div className="mt-4 text-xs">
                <div className="font-bold text-gray-800">{fetchedStudent.name}</div>
                <div className="text-gray-600 mt-1">Admission No: {fetchedStudent.admission_no || 'N/A'}</div>
                <div className="text-gray-600">DOB: {formatDate(fetchedStudent.date_of_birth)}</div>
                <div className="text-gray-600">Course: {getBranchFromRoll(fetchedStudent.roll_no) || 'N/A'}</div>
              </div>
            </div>

            <div className="md:col-span-2 bg-white p-4 rounded shadow">
              <h4 className="font-semibold mb-2">Section A: Basic Details</h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-3">
                <input placeholder="Admission Number" value={editValues.admission_no || ''} onChange={e=>setEditValues({...editValues, admission_no:e.target.value})} className="p-2 border rounded" />
                <div className="relative">
                  <input placeholder="Roll Number" value={editValues.roll_no || ''} disabled className="p-2 border rounded w-full bg-gray-100" />
                  <span title="Roll number cannot be edited" className="absolute right-2 top-2 text-sm">🔒</span>
                </div>
                <input placeholder="Student Name" value={editValues.name || ''} onChange={e=>setEditValues({...editValues, name:e.target.value})} className="p-2 border rounded" />
                <DatePicker
                  selected={parseDate(editValues.date_of_birth)}
                  onChange={(date) => setEditValues({ ...editValues, date_of_birth: formatDate(date) })}
                  dateFormat="dd-MM-yyyy"
                  placeholderText="DD-MM-YYYY"
                  className="p-2 border rounded w-full"
                  showYearDropdown
                  dropdownMode="select"
                  customInput={<DatePickerInput className="p-2 border rounded w-full" />}
                />
                <select value={editValues.gender || 'Male'} onChange={e=>setEditValues({...editValues, gender:e.target.value})} className="p-2 border rounded">
                  {genders.map(g=> <option key={g} value={g}>{g}</option>)}
                </select>
                <select value={editValues.fee_reimbursement || 'NO'} onChange={e=>setEditValues({...editValues, fee_reimbursement: e.target.value})} className="p-2 border rounded">
                  <option value="NO">Fee Reimbursement: NO</option>
                  <option value="YES">Fee Reimbursement: YES</option>
                  <option value="GOV">Fee Reimbursement: GOV</option>
                </select>
                <input placeholder="Course" value={getBranchFromRoll(editValues.roll_no) || ''} disabled className="p-2 border rounded bg-gray-100" />
                <div className="relative">
                  <input placeholder="Admission Type" value={editValues.admission_type || ''} disabled className="p-2 border rounded w-full bg-gray-100" />
                  <span title="Admission Type cannot be changed after admission." className="absolute right-2 top-2 text-sm">🔒</span>
                </div>
                <div className="flex items-center">
                  <span className="px-3 py-2 border border-r-0 bg-gray-100">+91</span>
                  <input
                    placeholder="Mobile Number"
                    value={editValues.mobile || ''}
                    onChange={e=>{
                      const digits = String(e.target.value || '').replace(/\D/g, '').slice(0, MAX_MOBILE_LEN);
                      setEditValues({...editValues, mobile: digits});
                    }}
                    className="p-2 border rounded w-full"
                    inputMode="numeric"
                    maxLength={MAX_MOBILE_LEN}
                    onPaste={(e) => { const pasted=(e.clipboardData||window.clipboardData).getData('text'); const digits=pasted.replace(/\D/g,'').slice(0, MAX_MOBILE_LEN); setEditValues(prev=>({...prev, mobile: digits})); e.preventDefault(); }}
                  />
                </div>
                <input type="email" placeholder="Email" value={editValues.email || ''} onChange={e=>setEditValues({...editValues, email:e.target.value})} className="p-2 border rounded" />
                <div>
                <label className="block text-sm font-medium text-gray-700">Academic Status</label>
                <select value={editValues.academic_status || 'ACTIVE'} onChange={e=>setEditValues({...editValues, academic_status:e.target.value})} className="p-2 border rounded">
                  <option value="ACTIVE">ACTIVE</option>
                  <option value="GRADUATED">GRADUATED</option>
                  <option value="DETAINED">DETAINED</option>
                  <option value="SUSPENDED">SUSPENDED</option>
                </select>
              </div>
                <div className="flex items-center">
                  <span className="px-3 py-2 border border-r-0 bg-gray-100 text-xs font-bold text-gray-500">OFFSET</span>
                  <input 
                    type="number" 
                    placeholder="Years" 
                    value={editValues.academic_offset_years || 0} 
                    onChange={e=>setEditValues({...editValues, academic_offset_years: parseInt(e.target.value) || 0})} 
                    className="p-2 border rounded w-full rounded-l-none" 
                  />
                </div>
                <DatePicker
                  selected={parseDate(editValues.admission_date)}
                  onChange={(date) => setEditValues({ ...editValues, admission_date: formatDate(date) })}
                  dateFormat="dd-MM-yyyy"
                  placeholderText="Admission Date"
                  className="p-2 border rounded w-full"
                  showYearDropdown
                  dropdownMode="select"
                  customInput={<DatePickerInput className="p-2 border rounded w-full" />}
                />
                <div className="col-span-1 md:col-span-3 text-sm text-gray-500">Profile Picture is view-only here. Inform Students to Upload their Profile Picture Through Their Student Login.</div>
              </div>
              <h4 className="font-semibold mb-2">Section B: Personal Details</h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-3">
                <input placeholder="Father Name" value={personalFull.father_name || ''} onChange={e=>setPersonalFull({...personalFull, father_name:e.target.value})} className="p-2 border rounded" />
                <input placeholder="Mother Name" value={personalFull.mother_name || ''} onChange={e=>setPersonalFull({...personalFull, mother_name:e.target.value})} className="p-2 border rounded" />
                <input placeholder="Nationality" value={personalFull.nationality || ''} onChange={e=>setPersonalFull({...personalFull, nationality:e.target.value})} className="p-2 border rounded" />
            <select value={personalFull.religion || ''} onChange={e=>setPersonalFull({...personalFull, religion:e.target.value})} className="p-2 border rounded">
                <option value="">Select Religion</option>
                {COLLEGE_CONFIG.religions.map(r => (
                    <option key={r} value={r.toUpperCase()}>{r.toUpperCase()}</option>
                ))}
            </select>
                <select value={personalFull.category || 'OC'} onChange={e=>setPersonalFull({...personalFull, category:e.target.value})} className="p-2 border rounded">{categories.map(c=> <option key={c} value={c}>{c}</option>)}</select>
                <input placeholder="Sub Caste" value={personalFull.sub_caste || ''} onChange={e=>setPersonalFull({...personalFull, sub_caste:e.target.value})} className="p-2 border rounded" />
                <select value={personalFull.area_status || 'Local'} onChange={e=>setPersonalFull({...personalFull, area_status:e.target.value})} className="p-2 border rounded"><option>Local</option><option>Non-Local</option></select>
                <input placeholder="Mother Tongue" value={personalFull.mother_tongue || ''} onChange={e=>setPersonalFull({...personalFull, mother_tongue:e.target.value})} className="p-2 border rounded" />
                <input placeholder="Place of Birth" value={personalFull.place_of_birth || ''} onChange={e=>setPersonalFull({...personalFull, place_of_birth:e.target.value})} className="p-2 border rounded" />
                <input placeholder="Father Occupation" value={personalFull.father_occupation || ''} onChange={e=>setPersonalFull({...personalFull, father_occupation:e.target.value})} className="p-2 border rounded" />
                <input 
                  placeholder="Annual Income"
                  value={personalFull.annual_income || ''} 
                  onChange={e => {
                    const raw = e.target.value.replace(/\D/g, '');
                    if (raw && parseInt(raw) > 2000000) return;
                    setPersonalFull({...personalFull, annual_income: formatIndianNumber(raw)});
                  }} 
                  className="p-2 border rounded"
                />
