import React from 'react';
import { Mail, Lock, Check, X } from 'lucide-react';
import { SecurityAuthentication } from './SecurityAuthentication';

export function StudentActivationUI({
  emailInput, setEmailInput,
  handleSendOtp, emailSending, otpSent, setOtpSent,
  otpInput, setOtpInput, handleVerifyOtp, otpVerifying,
  isEmailVerified, isPasswordSet,
  resendCountdown,
  passwordManagement,
  isEmailValid
}) {
  return (
    <div className="border border-gray-300 rounded-md bg-white overflow-hidden shadow-sm">
      <div className="grid grid-cols-1 md:grid-cols-3 bg-gray-50 border-b border-gray-300">
        <ActivationStep num={1} title="Logged In" status="success" />
        <ActivationStep num={2} title="Verify Email" status={isEmailVerified ? "success" : "active"} />
        <ActivationStep num={3} title="Create Password" status={!isEmailVerified ? "waiting" : (isPasswordSet ? "success" : "active")} />
      </div>

      <div className="p-6 space-y-8">
        <section className="space-y-4">
          <div className="flex items-center gap-2">
            <Mail className="text-gray-400" size={18} />
            <h2 className="text-sm font-semibold text-gray-800">Step 2: Verify Your Institutional Email</h2>
          </div>
          
          <div className="max-w-md space-y-3 pl-0 sm:pl-7">
            {isEmailVerified ? (
              <div className="flex items-center gap-2 text-green-700 bg-green-50 border border-green-200 rounded-md p-3 text-xs">
                <Check size={16} className="text-green-600 font-bold" />
                <span className="font-semibold">Institutional Email Verified: {emailInput}</span>
              </div>
            ) : (
              <>
                <p className="text-xs text-gray-600">Enter your primary email address. We will send a 6-digit verification code to this address.</p>
                <div className="flex flex-col sm:flex-row gap-2">
                  <input 
                    type="email" 
                    value={emailInput}
                    onChange={(e) => setEmailInput(e.target.value)}
                    disabled={otpSent}
                    placeholder="name@example.com"
                    className={`flex-1 border rounded-md px-3 py-2 text-sm focus:ring-1 transition-all outline-none disabled:bg-gray-50 ${
                      emailInput && !isEmailValid ? 'border-red-400 focus:ring-red-400 bg-red-50/10' : 'border-gray-300 focus:ring-[#0b3578]'
                    }`}
                  />
                  {!otpSent && (
                    <button 
                      onClick={handleSendOtp}
                      disabled={emailSending || !isEmailValid || otpSent}
                      className="bg-[#0b3578] hover:bg-[#0a2d66] text-white px-4 py-2 rounded-md text-sm font-medium transition-all disabled:opacity-50"
                    >
                      {emailSending ? 'Sending...' : 'Send OTP'}
                    </button>
                  )}
                </div>

                {otpSent && (
                  <div className="bg-blue-50 p-4 rounded-md border border-blue-200 animate-slideDown">
                    <label className="block text-[10px] font-bold text-[#0b3578] mb-1 uppercase tracking-wider">Enter Verification Code</label>
                    <div className="flex flex-wrap gap-2">
                      <input 
                        type="text"
                        maxLength={6}
                        value={otpInput}
                        onChange={(e) => setOtpInput(e.target.value.replace(/\D/g, ''))}
                        placeholder="000000"
                        className="w-full sm:w-32 border border-blue-200 rounded-md px-3 py-2 text-center text-lg font-mono tracking-widest focus:ring-1 focus:ring-[#0b3578] outline-none"
                      />
                      <button 
                        onClick={handleVerifyOtp}
                        disabled={otpVerifying || otpInput.length !== 6}
                        className="flex-1 sm:flex-none bg-[#0b3578] text-white px-4 py-2 rounded-md text-sm font-medium hover:bg-[#0a2d66] disabled:opacity-50"
                      >
                        {otpVerifying ? 'Verifying...' : 'Verify'}
                      </button>
                      
                      <div className="w-full flex items-center justify-between mt-2">
                        <button 
                          onClick={() => { setOtpSent(false); setOtpInput(''); }}
                          className="text-[#0b3578] text-[10px] font-bold uppercase hover:underline"
                        >
                          Change Email
                        </button>
                        
                        {resendCountdown > 0 ? (
                          <span className="text-gray-400 text-[10px] font-bold uppercase">Resend in {resendCountdown}s</span>
                        ) : (
                          <button 
                            onClick={handleSendOtp}
                            className="text-[#0b3578] text-[10px] font-bold uppercase hover:underline"
                          >
                            Resend OTP
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        </section>

        <section className={`space-y-4 ${!isEmailVerified ? 'opacity-40 pointer-events-none' : ''}`}>
          <SecurityAuthentication
            isPasswordSet={isPasswordSet}
            {...passwordManagement}
            buttonText="Complete Activation"
            title="Step 3: Secure Your Account"
            description="Create a strong password to protect your academic records."
          />
        </section>
      </div>
    </div>
  );
}

function ActivationStep({ num, title, status }) {
  const styles = {
    success: 'bg-green-50 text-green-700',
    active: 'bg-blue-50 text-[#0b3578]',
    waiting: 'bg-gray-50 text-gray-400',
  };
  
  return (
    <div className={`flex items-center justify-center p-4 gap-3 ${styles[status]}`}>
      <div className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold border ${
        status === 'success' ? 'bg-green-600 text-white border-green-600' : 
        status === 'active' ? 'bg-[#0b3578] text-white border-[#0b3578]' : 
        'bg-white border-gray-300 text-gray-400'
      }`}>
        {status === 'success' ? '✓' : num}
      </div>
      <span className="text-xs font-semibold uppercase tracking-wide">{title}</span>
    </div>
  );
}

'use client';
import { useState, useEffect, useCallback } from 'react';
import toast from 'react-hot-toast';

const MarkAttendanceCard = ({ session, onVerified }) => {
  const [pin, setPin] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleVerify = async () => {
    if (pin.length !== 4) {
      toast.error('Enter the 4-digit PIN shown on faculty screen');
      return;
    }

    setSubmitting(true);
    try {
      if (window.location.protocol === 'http:' && window.location.hostname !== 'localhost') {
        toast.error("GPS requires HTTPS on mobile. Please host on Render or use a laptop on 'localhost'.", { duration: 6000 });
        setSubmitting(false);
        return;
      }

      // --- ACTION B: DEVICE FINGERPRINTING ---
      let deviceId = localStorage.getItem('kucet_device_uuid');
      if (!deviceId) {
        deviceId = Math.random().toString(36).substring(2) + Date.now().toString(36);
        localStorage.setItem('kucet_device_uuid', deviceId);
      }

      // --- ACTION C: GPS INTEGRITY ---
      const pos = await new Promise((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, { 
          enableHighAccuracy: true, 
          timeout: 10000 
        });
      });

      const { latitude, longitude, accuracy } = pos.coords;

      // 2. Submit Verification
      const res = await fetch('/api/student/attendance/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          assignment_id: session.assignment_id,
          pin: pin,
          latitude,
          longitude,
          accuracy,
          device_id: deviceId
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Verification failed');

      toast.success(json.message);
      onVerified(); 
    } catch (err) {
      let msg = err.message;
      if (err.code === 1) msg = "Location access denied. Please enable GPS.";
      if (err.code === 3) msg = "Location request timed out. Please retry.";
      toast.error(msg);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="bg-indigo-600 rounded-xl p-4 text-white shadow-lg flex flex-col md:flex-row items-center justify-between gap-4 animate-pulse">
      <div className="flex items-center gap-4">
        <div className="bg-white/20 p-3 rounded-full">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 11c0 3.517-1.009 6.799-2.753 9.571m-3.44-2.04l.054-.09A10.003 10.003 0 0012 3c4.183 0 7.66 2.567 9.106 6H22.25m-9.448 10a10.003 10.003 0 01-1.106-2.04m0 0l.054-.09A10.003 10.003 0 0122.5 12"></path></svg>
        </div>
        <div>
          <h4 className="font-bold text-lg leading-tight">Secure Attendance Active</h4>
          <p className="text-indigo-100 text-xs">{session.subject_name} ({session.subject_code})</p>
        </div>
      </div>

      <div className="flex items-center gap-2 bg-white/10 p-2 rounded-lg border border-white/20">
        <input 
          type="text" 
          maxLength="4" 
          placeholder="PIN" 
          value={pin}
          onChange={(e) => setPin(e.target.value.replace(/\D/g, ''))}
          className="w-20 bg-white text-gray-900 text-center font-bold text-xl py-2 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-400 placeholder:text-gray-300"
        />
        <button
          onClick={handleVerify}
          disabled={submitting || pin.length !== 4}
          className="bg-white text-indigo-600 px-4 py-2 rounded-md font-black uppercase text-sm hover:bg-indigo-50 disabled:opacity-50 transition-all whitespace-nowrap"
        >
          {submitting ? 'Verifying...' : 'Mark Present'}
        </button>
      </div>
    </div>
  );
};

export default function AcademicTab() {
  const [data, setData] = useState([]);
  const [activeSessions, setActiveSessions] = useState([]);
  const [verifiedMessages, setVerifiedMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [historySubject, setHistorySubject] = useState(null);
  const [historyData, setHistoryData] = useState([]);
  const [loadingHistory, setLoadingHistory] = useState(false);

  // fetchActiveSessions logic is inlined into fetchAcademicInfo to keep dependencies stable

  const onVerificationSuccess = (assignmentId, subjectName, attendanceDate) => {
    // Add confirmation message
    const today = attendanceDate || new Date().toLocaleDateString('en-IN', { day: '2-digit', month: '2-digit', year: 'numeric' });
    setVerifiedMessages(prev => {
      // Prevent duplicate messages if already present
      if (prev.find(m => m.id === assignmentId)) return prev;
      return [...prev, { 
        id: assignmentId, 
        text: `Your attendance for ${subjectName} has been successfully taken on ${today}.` 
      }];
    });

    // Remove the verified session from the active list immediately
    setActiveSessions(prev => prev.filter(s => s.assignment_id !== assignmentId));
    // Refresh the academic data to show the new attendance count
    fetchAcademicInfo();
  };

  const fetchAcademicInfo = useCallback(async () => {
    try {
      const res = await fetch('/api/student/academic-info');
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to fetch academic info');
      const subjects = json.data || [];
      setData(subjects);
      // fetch active sessions for these subjects
      if (subjects.length) {
        try {
          const assignmentIds = subjects.map(s => s.assignment_id).join(',');
          const ar = await fetch(`/api/student/attendance/active-sessions?ids=${assignmentIds}`);
          if (ar.status === 401 || ar.status === 403) return;
          const jr = await ar.json();
          if (ar.ok) setActiveSessions(jr.data || []);
        } catch (e) {
          // Silent
        }
      } else {
        setActiveSessions([]);
      }
    } catch (error) {
      toast.error(error.message);
    } finally {
      setLoading(false);
    }
  }, []);

  const fetchHistory = async (subject) => {
    setHistorySubject(subject);
    setLoadingHistory(true);
    try {
      const res = await fetch(`/api/student/attendance/history?assignment_id=${subject.assignment_id}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to fetch attendance history');
      setHistoryData(json.data || []);
    } catch (error) {
      toast.error(error.message);
    } finally {
      setLoadingHistory(false);
    }
  };

  useEffect(() => {
    fetchAcademicInfo();
  }, [fetchAcademicInfo]);

  const getPercentageColor = (pct) => {
    if (pct <= 50) return 'text-red-600 bg-red-50 border-red-200';
    if (pct <= 75) return 'text-orange-600 bg-orange-50 border-orange-200';
    return 'text-green-600 bg-green-50 border-green-200';
  };

  if (loading) return <div className="text-center py-8">Loading academic details...</div>;

  return (
    <div className="space-y-6">
      {/* Active Attendance Sessions (Self-Verification) */}
      {(activeSessions.length > 0 || verifiedMessages.length > 0) && (
        <div className="space-y-3">
          {/* Confirmation Messages */}
          {verifiedMessages.map((m, idx) => (
            <div key={`msg-${idx}`} className="bg-green-50 border border-green-200 p-4 rounded-xl flex items-center gap-3 animate-fadeIn">
              <div className="bg-green-100 p-2 rounded-full text-green-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
              </div>
              <p className="text-sm font-bold text-green-800">{m.text}</p>
            </div>
          ))}

          {/* Active Session Cards */}
          {activeSessions.map((session) => (
            <MarkAttendanceCard 
              key={session.assignment_id} 
              session={session} 
              onVerified={() => {
                // Parse the SQL date (YYYY-MM-DD) to Display format (DD-MM-YYYY)
                let displayDate = session.attendance_date;
                if (displayDate && displayDate.includes('-')) {
                  const [y, m, d] = displayDate.split('-');
                  displayDate = `${d}-${m}-${y}`;
                }
                onVerificationSuccess(session.assignment_id, session.subject_name, displayDate);
              }} 
            />
          ))}
        </div>
      )}

      {/* Attendance History Modal */}
      {historySubject && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full max-h-[80vh] flex flex-col animate-scaleUp">
            <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
              <div>
                <h3 className="text-lg font-bold text-gray-900">Attendance History</h3>
