            <thead className="bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left font-bold text-gray-600">Subject</th>
                <th className="px-4 py-3 text-center font-bold text-gray-600">Attendance</th>
                <th className="px-4 py-3 text-center font-bold text-gray-600">Mid-I / Execution</th>
                <th className="px-4 py-3 text-center font-bold text-gray-600">Mid-II / Writing</th>
                <th className="px-4 py-3 text-center font-bold text-gray-600">Assign. / Record</th>
                <th className="px-4 py-3 text-center font-bold text-indigo-600 bg-indigo-50">Total Marks</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-100">
              {data.map((sub) => {
                const pct = sub.total_classes > 0 ? (sub.attended_classes / sub.total_classes) * 100 : 100;
                const isLab = sub.subject_type === 'lab';
                
                // Max Mark Calculation
                const m1m = isLab ? 10 : (sub.mid_max || 20);
                const m2m = isLab ? 10 : (sub.mid_max || 20);
                const am = isLab ? 5 : (sub.mid_max === 25 ? 5 : 10);
                const totalMax = isLab ? 25 : 30;
                
                // Mark labels
                const l1 = isLab ? 'Execution' : 'Mid-I';
                const l2 = isLab ? 'Writing' : 'Mid-II';
                const l3 = isLab ? 'Record' : 'Assign.';

                // Calculate Internal Total
                const m1 = sub.mid1_marks !== null ? parseFloat(sub.mid1_marks) : null;
                const m2 = sub.mid2_marks !== null ? parseFloat(sub.mid2_marks) : null;
                const assgn = sub.assignment_marks !== null ? parseFloat(sub.assignment_marks) : 0;
                
                let internalTotal = null;
                if (isLab) {
                  // Lab: sum of everything
                  internalTotal = (m1 ?? 0) + (m2 ?? 0) + (assgn ?? 0);
                } else {
                  // Theory: Best of mid + assignment
                  if (m1 !== null || m2 !== null) {
                    const bestMid = Math.max(m1 ?? 0, m2 ?? 0);
                    internalTotal = bestMid + assgn;
                  }
                }

                return (
                  <tr key={sub.assignment_id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-4 py-4">
                      <div className="flex items-center gap-2">
                        <div className="font-bold text-gray-900">{sub.subject_name}</div>
                        {isLab && <span className="text-[8px] bg-amber-50 text-amber-600 border border-amber-100 px-1 rounded font-black uppercase">Lab</span>}
                      </div>
                      <div className="text-[10px] text-gray-400 font-mono">{sub.subject_code} • {sub.faculty_name}</div>
                    </td>
                    <td className="px-4 py-4 text-center">
                      <button 
                        onClick={() => fetchHistory(sub)}
                        className={`inline-flex flex-col items-center px-3 py-1 rounded-lg border transition-all hover:shadow-md active:scale-95 ${getPercentageColor(pct)}`}
                      >
                        <span className="text-sm font-black">{pct.toFixed(1)}%</span>
                        <span className="text-[9px] opacity-70 font-bold uppercase">{sub.attended_classes}/{sub.total_classes}</span>
                      </button>
                    </td>
                    <td className="px-4 py-4 text-center">
                      <div className="flex flex-col items-center">
                        <span className={`font-mono font-bold ${sub.mid1_marks === null ? 'text-gray-300' : 'text-gray-700'}`}>
                          {sub.mid1_marks ?? '--'}
                        </span>
                        <span className="text-[8px] text-gray-400 font-bold uppercase">{l1} Max: {m1m}</span>
                      </div>
                    </td>
                    <td className="px-4 py-4 text-center">
                      <div className="flex flex-col items-center">
                        <span className={`font-mono font-bold ${sub.mid2_marks === null ? 'text-gray-300' : 'text-gray-700'}`}>
                          {sub.mid2_marks ?? '--'}
                        </span>
                        <span className="text-[8px] text-gray-400 font-bold uppercase">{l2} Max: {m2m}</span>
                      </div>
                    </td>
                    <td className="px-4 py-4 text-center">
                      <div className="flex flex-col items-center">
                        <span className={`font-mono font-bold ${sub.assignment_marks === null ? 'text-gray-300' : 'text-gray-700'}`}>
                          {sub.assignment_marks ?? '--'}
                        </span>
                        <span className="text-[8px] text-gray-400 font-bold uppercase">{l3} Max: {am}</span>
                      </div>
                    </td>
                    <td className="px-4 py-4 text-center bg-indigo-50/30">
                      <div className="flex flex-col items-center">
                        <span className={`font-mono font-black text-lg ${internalTotal === null ? 'text-gray-300' : 'text-indigo-700'}`}>
                          {internalTotal !== null ? internalTotal.toFixed(1) : '--'}
                        </span>
                        <span className="text-[9px] text-indigo-400 font-bold uppercase">Out of {totalMax}</span>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      ) : (
        <div className="py-12 bg-gray-50 rounded-xl border-2 border-dashed border-gray-200 text-center">
          <p className="text-gray-500 font-medium">No subjects found for the current semester.</p>
          <p className="text-xs text-gray-400 mt-1">Assignments will appear once faculty members are assigned to your class.</p>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import toast from 'react-hot-toast';

export default function AttendanceVerificationActivity({ sessions, onSessionVerified }) {
  const [pinByAssignment, setPinByAssignment] = useState({});
  const [submittingId, setSubmittingId] = useState(null);
  const [statusByAssignment, setStatusByAssignment] = useState({});
  const [deviceId, setDeviceId] = useState(null);

  useEffect(() => {
    const id = setTimeout(() => {
      try {
        const existing = localStorage.getItem('kucet_device_uuid');
        if (existing) {
          setDeviceId(existing);
          return;
        }

        if (typeof crypto === 'undefined' || typeof crypto.getRandomValues !== 'function') {
          // Extremely old browser fallback; keeps app functional even without a strong ID.
          const fallback = 'kucet_device_no_crypto';
          localStorage.setItem('kucet_device_uuid', fallback);
          setDeviceId(fallback);
          return;
        }

        const bytes = new Uint8Array(16);
        crypto.getRandomValues(bytes);
        const created = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
        localStorage.setItem('kucet_device_uuid', created);
        setDeviceId(created);
      } catch (error) {
        // ignore (localStorage can throw in some private modes)
      }
    }, 0);

    return () => clearTimeout(id);
  }, []);

  if (!sessions || sessions.length === 0) return null;

  const handleChangePin = (assignmentId, value) => {
    const numeric = value.replace(/\D/g, '').slice(0, 4);
    setPinByAssignment(prev => ({ ...prev, [assignmentId]: numeric }));
    setStatusByAssignment(prev => {
      if (!prev[assignmentId]) return prev;
      const { [assignmentId]: _discard, ...rest } = prev;
      return rest;
    });
  };

  const handleVerify = async (session) => {
    const assignmentId = session.assignment_id;
    const pin = pinByAssignment[assignmentId] || '';

    if (pin.length !== 4) {
      toast.error('Enter the 4-digit PIN shown on faculty screen');
      return;
    }

    setSubmittingId(assignmentId);
    setStatusByAssignment((prev) => {
      const { [assignmentId]: _discard, ...rest } = prev;
      return rest;
    });
    try {
      if (window.location.protocol === 'http:' && window.location.hostname !== 'localhost') {
        toast.error("GPS requires HTTPS on mobile. Please host on Render or use a laptop on 'localhost'.", { duration: 6000 });
        setSubmittingId(null);
        return;
      }

      const resolvedDeviceId = deviceId || localStorage.getItem('kucet_device_uuid');
      if (!resolvedDeviceId) {
        toast.error('Device ID not ready. Please retry.');
        setSubmittingId(null);
        return;
      }

      const pos = await new Promise((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, {
          enableHighAccuracy: true,
          timeout: 10000,
        });
      });

      const { latitude, longitude, accuracy } = pos.coords;

      // GPS Accuracy Enforcement (Edge Case Governance)
      if (accuracy > 100) {
        toast.error(`Location accuracy is too low (${Math.round(accuracy)}m). Please move near a window or outdoors for better GPS reception.`);
        setSubmittingId(null);
        return;
      }

      const res = await fetch('/api/student/attendance/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          assignment_id: assignmentId,
          session_id: session.session_id,
          pin,
          latitude,
          longitude,
          accuracy,
          device_id: resolvedDeviceId,
        }),
      });

      const json = await res.json();
      if (!res.ok) {
        throw new Error(json.error || 'Verification failed');
      }

      toast.success(json.message || 'Attendance successfully marked.');
      if (typeof onSessionVerified === 'function') {
        onSessionVerified(assignmentId, session);
      }
    } catch (err) {
      let msg = err.message || 'Verification failed';
      if (err.code === 1) msg = 'Location access denied. Please enable GPS.';
      if (err.code === 3) msg = 'Location request timed out. Please retry.';
      toast.error(msg);
      setStatusByAssignment((prev) => ({
        ...prev,
        [assignmentId]: {
          tone: 'error',
          message: msg
        }
      }));
    } finally {
      setSubmittingId(null);
    }
  };

  const formatDate = (value) => {
    if (!value) return null;

    let d = String(value).trim();
    if (!d) return null;

    // Handle ISO timestamps like "2026-04-20T00:00:00.000Z" by extracting the date portion.
    if (d.includes('T')) {
      d = d.split('T')[0];
    }

    // If already in YYYY-MM-DD, format to DD-MM-YYYY.
    if (/^\d{4}-\d{2}-\d{2}$/.test(d)) {
      const [y, m, day] = d.split('-');
      return `${day}-${m}-${y}`;
    }

    // If already in DD-MM-YYYY, keep it.
    if (/^\d{2}-\d{2}-\d{4}$/.test(d)) {
      return d;
    }

    // Fallback: try Date parsing.
    const parsed = new Date(value);
    if (!Number.isNaN(parsed.getTime())) {
      const day = String(parsed.getDate()).padStart(2, '0');
      const month = String(parsed.getMonth() + 1).padStart(2, '0');
      const year = parsed.getFullYear();
      return `${day}-${month}-${year}`;
    }

    return String(value);
  };

  return (
    <div className="space-y-3">
      {sessions.map((session) => {
        const assignmentId = session.assignment_id;
        const pin = pinByAssignment[assignmentId] || '';
        const sessionDate = formatDate(session.attendance_date);
        const status = statusByAssignment[assignmentId];

        const subjectName = session.subject_name || 'Attendance Session';
        const subjectCode = session.subject_code ? String(session.subject_code) : null;
        const facultyName = session.faculty_name || 'Faculty';

        return (
          <div
            key={assignmentId}
            className="rounded-xl border border-blue-200/70 bg-blue-50/70 text-slate-800 shadow-sm"
          >
            <div className="p-4 sm:p-5">
              <div className="flex items-start justify-between gap-4">
                <div className="min-w-0">
                  <div className="flex items-center gap-2">
                    <div className="h-2 w-2 rounded-full bg-[#0b3578]" aria-hidden="true" />
                    <h3 className="text-sm font-bold tracking-tight text-slate-800">
                      Attendance Verification Required
                    </h3>
                  </div>
                  <p className="mt-1 text-xs text-slate-600">
                    Enter the 4-digit PIN displayed by faculty
                  </p>
                </div>

                <div className="hidden sm:flex items-center gap-2 rounded-lg border border-blue-200 bg-white/60 px-2.5 py-1 text-[10px] font-bold uppercase tracking-widest text-[#0b3578]">
                  Secure Session
                </div>
              </div>

              <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-12 md:items-start">
                <div className="md:col-span-7">
                  <div className="rounded-lg border border-blue-200/70 bg-white/60 px-3.5 py-3">
                    <div className="grid grid-cols-1 gap-2">
                      <div className="flex items-start justify-between gap-3">
                        <div className="min-w-0">
                          <div className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Subject</div>
                          <div className="mt-0.5 text-sm font-semibold text-slate-700 truncate">
                            {subjectName}{subjectCode ? <span className="text-slate-400 font-bold"> ({subjectCode})</span> : null}
                          </div>
                        </div>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                        <div>
                          <div className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Faculty</div>
                          <div className="mt-0.5 text-xs font-semibold text-slate-700 truncate">{facultyName}</div>
                        </div>
                        <div>
                          <div className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Session Date</div>
                          <div className="mt-0.5 text-xs font-semibold text-slate-700">{sessionDate || 'N/A'}</div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>

                <div className="md:col-span-5">
                  <div className="rounded-lg border border-blue-200/70 bg-white/60 px-3.5 py-3">
                    <div className="flex flex-col sm:flex-row sm:items-end gap-3">
                      <div className="flex-1">
                        <div className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">PIN</div>
                        <input
                          type="text"
                          inputMode="numeric"
                          autoComplete="one-time-code"
                          maxLength={4}
                          placeholder="••••"
                          value={pin}
                          onChange={(e) => handleChangePin(assignmentId, e.target.value)}
                          className="mt-1 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-center text-sm font-bold tracking-[0.35em] text-slate-800 placeholder:text-slate-300 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#0b3578]/20 focus:border-[#0b3578]/30"
                        />
                      </div>

                      <button
                        type="button"
                        onClick={() => handleVerify(session)}
                        disabled={submittingId === assignmentId || pin.length !== 4}
                        className="w-full sm:w-auto px-5 py-2.5 bg-[#0b3578] text-white text-[10px] font-black uppercase tracking-widest rounded-md shadow-lg shadow-[#0b3578]/20 hover:scale-[1.02] transition disabled:opacity-60 disabled:hover:scale-100"
                      >
                        {submittingId === assignmentId ? 'Verifying…' : 'Mark Present'}
                      </button>
                    </div>

                    {status?.tone === 'error' && status?.message && (
                      <div className="mt-3 rounded-lg border border-rose-200 bg-rose-50 px-3 py-2">
                        <div className="text-[10px] font-bold uppercase tracking-[0.2em] text-rose-700">Status</div>
                        <div className="mt-0.5 text-xs font-semibold text-rose-800 leading-relaxed">{status.message}</div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// src/components/student/ClassTimetable.js
'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import RealtimeListener from '@/components/RealtimeListener';

const INSTITUTIONAL_ACTIVITIES = [
  { code: 'SPORTS', name: 'Sports & Athletics' },
  { code: 'MINI_PROJECT', name: 'Mini Projects' },
  { code: 'EXTRA_CURRICULAR', name: 'Extra Curricular Activities' },
  { code: 'SEMINAR', name: 'Seminars / Workshops' },
  { code: 'LIB', name: 'Library Period' }
];

export default function ClassTimetable() {
  const [schedule, setSchedule] = useState([]);
  const [meta, setMeta] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isMobile, setIsMobile] = useState(false);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [dayColWidth, setDayColWidth] = useState(0);

  const scrollContainerRef = useRef(null);
  const dayHeaderRef = useRef(null);

  const fetchTimetable = useCallback(async () => {
    try {
      const res = await fetch('/api/student/timetable');
      const data = await res.json();
      if (res.ok) {
        setSchedule(data.data || []);
        setMeta(data.meta);
      } else {
        setError(data.error || 'Failed to load timetable');
      }
    } catch (e) {
      setError('Network error - could not sync timetable');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    const id = setTimeout(() => {
      fetchTimetable();
    }, 0);
    return () => clearTimeout(id);
  }, [fetchTimetable]);

  useEffect(() => {
    const updateIsMobile = () => {
      if (typeof window !== 'undefined') {
        setIsMobile(window.innerWidth < 768);
      }
    };
    updateIsMobile();
    window.addEventListener('resize', updateIsMobile);
    return () => window.removeEventListener('resize', updateIsMobile);
  }, []);

  useEffect(() => {
    if (dayHeaderRef.current) {
      setDayColWidth(dayHeaderRef.current.offsetWidth || 0);
    }
  }, [loading]);

  const handleScroll = (event) => {
    setScrollLeft(event.target.scrollLeft || 0);
  };

  const handleRealtimeUpdate = (data) => {
    if (data.type === 'TIMETABLE_CHANGED') {
      fetchTimetable();
    }
  };

  const days = ['MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
  const dayShortMap = { 'MON': 'M', 'TUE': 'T', 'WED': 'W', 'THU': 'T', 'FRI': 'F', 'SAT': 'S' };
  const periods = [1, 2, 3, 4, 5, 6, 7];
  const getSlot = (day, p) => schedule.find(s => s.day_of_week === day && s.period_number === p);

  if (loading) return (
    <div className="bg-white border border-slate-300 p-12 text-center shadow-sm">
       <p className="text-slate-500 font-bold uppercase tracking-widest text-xs animate-pulse">Requesting Institutional Schedule Data...</p>
    </div>
  );

  if (error) return (
    <div className="bg-white border border-rose-200 p-12 text-center shadow-sm">
       <h3 className="text-lg font-bold text-rose-800 uppercase tracking-tight">System Access Error</h3>
       <p className="text-sm text-slate-600 mt-2">{error}</p>
       <button onClick={fetchTimetable} className="mt-6 px-6 py-2 bg-[#0b3578] text-white font-bold hover:bg-blue-900 transition-all uppercase tracking-widest text-xs">Re-authenticate & Retry</button>
    </div>
  );

  return (
    <>
      <RealtimeListener onUpdate={handleRealtimeUpdate} />
      
      {/* Unified Institutional Matrix Card */}
      <div className="bg-white border border-slate-300 shadow-md rounded-sm overflow-hidden w-full max-w-full">
        
        {/* Formal Header */}
        <div className="bg-[#0b3578] px-4 md:px-6 py-3 border-b border-blue-900 flex flex-col md:flex-row md:items-center md:justify-between gap-3">
          <div>
            <h2 className="text-base md:text-xl font-bold text-white uppercase tracking-tight">Departmental Class Matrix</h2>
            <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-0.5">
              <span className="text-blue-300 text-[9px] md:text-[10px] font-bold uppercase tracking-widest">
                {meta?.branch || 'General'} — Sem {meta?.semester || 'N/A'}
              </span>
            </div>
          </div>
          <div className="bg-blue-900/50 px-3 py-1 border border-blue-700/50 rounded-sm self-start md:self-auto">
             <span className="text-[9px] md:text-[11px] font-bold text-white uppercase tracking-widest">Active Session</span>
          </div>
        </div>

        {/* High-Density Matrix Table Wrapper */}
        <div className="relative w-full overflow-hidden">
          <div 
            ref={scrollContainerRef}
            className="overflow-x-auto overflow-y-hidden w-full scrollbar-none"
            style={{ WebkitOverflowScrolling: 'touch' }}
          >
            <table className="w-full border-collapse text-left">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-200">
                  <th 
                    className="sticky left-0 z-30 bg-slate-100 border-r border-slate-300 text-slate-500 text-[9px] md:text-[10px] font-black uppercase tracking-widest text-center w-[35px] md:w-20 shadow-[4px_0_8px_-2px_rgba(0,0,0,0.1)]"
                  >
                    <div className="py-3 px-1">Day</div>
                  </th>
                  {periods.map(p => (
                    <th key={p} className="p-2 md:p-4 border-r border-slate-200 min-w-[95px] md:min-w-[150px]">
                      <div className="text-slate-800 font-bold text-[9px] md:text-[11px] uppercase">P{p}</div>
                      <div className="text-[8px] md:text-[10px] font-medium text-slate-400 mt-0.5 whitespace-nowrap">
                        {p === 1 && '09:30-10:20'}
                        {p === 2 && '10:20-11:10'}
                        {p === 3 && '11:20-12:10'}
                        {p === 4 && '12:10-01:00'}
                        {p === 5 && '02:00-02:50'}
                        {p === 6 && '02:50-03:40'}
                        {p === 7 && '03:40-04:30'}
                      </div>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {days.map(day => (
                  <tr key={day} className="border-b border-slate-100 hover:bg-slate-50 transition-colors group">
                    <td className="sticky left-0 z-20 bg-white border-r border-slate-300 font-black text-[#0b3578] text-center text-[11px] md:text-sm shadow-[4px_0_8px_-2px_rgba(0,0,0,0.1)] group-hover:bg-slate-50">
                      <span className="hidden md:inline">{day}</span>
                      <span className="md:hidden">{dayShortMap[day]}</span>
                    </td>
                    {periods.map(p => {
                      const slot = getSlot(day, p);
                      const activity = slot ? INSTITUTIONAL_ACTIVITIES.find(a => a.code === slot.subject_code) : null;
                      const isInstitutional = !!activity;
                      
                      return (
                        <td key={`${day}-${p}`} className={`p-2 md:p-4 border-r border-slate-100 align-top h-24 md:h-32 ${slot ? (isInstitutional ? 'bg-amber-50/20' : 'bg-white') : 'bg-slate-50/30'}`}>
                          {slot ? (
                            <div className="flex flex-col gap-1 h-full max-w-[85px] md:max-w-none">
                              <div className={`font-bold text-[9px] md:text-[12px] leading-tight uppercase tracking-tight line-clamp-3 ${isInstitutional ? 'text-amber-800' : 'text-slate-900'}`}>
                                {activity ? activity.name : (slot.display_name || slot.subject_code)}
                              </div>
                              <div className="mt-auto pt-1.5 space-y-0.5">
                                 {slot.faculty_name && (
                                   <div className="text-[7px] md:text-[10px] font-medium text-slate-400 uppercase truncate">
                                     {slot.faculty_name}
                                   </div>
                                 )}
                                 {slot.room_no && (
                                   <div className="text-[7px] md:text-[9px] font-bold text-blue-700 uppercase bg-blue-50/50 px-1 py-0.5 inline-block border border-blue-100/50">
                                     {slot.room_no}
                                   </div>
                                 )}
                              </div>
                            </div>
                          ) : (
                            <div className="h-full flex items-center justify-center opacity-10">
                              <span className="text-[10px] font-bold text-slate-300">—</span>
                            </div>
                          )}
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Institutional Breaks Notice */}
        <div className="px-4 py-3 bg-slate-50 border-t border-slate-200 flex flex-row gap-4 md:gap-12 justify-center items-center">
           <div className="flex items-center gap-2">
              <span className="text-[12px] opacity-40">⏱</span>
              <div>
                 <div className="text-[7px] md:text-[8px] font-black text-slate-400 uppercase tracking-tighter leading-none">Short Break</div>
                 <div className="text-[8px] md:text-[11px] font-bold text-slate-700 uppercase mt-0.5">11:10 - 11:20 AM</div>
              </div>
           </div>
           <div className="flex items-center gap-2">
              <span className="text-[12px] opacity-40">🍱</span>
              <div>
                 <div className="text-[7px] md:text-[8px] font-black text-slate-400 uppercase tracking-tighter leading-none">Lunch Break</div>
                 <div className="text-[8px] md:text-[11px] font-bold text-slate-700 uppercase mt-0.5">01:00 - 02:00 PM</div>
              </div>
           </div>
        </div>
      </div>
      <style jsx global>{`
        .scrollbar-none::-webkit-scrollbar {
          display: none;
        }
        .scrollbar-none {
          -ms-overflow-style: none;
          scrollbar-width: none;
        }
      `}</style>
    </>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import useProfileActivity from '@/hooks/student/useProfileActivity';
import useActivityDismissal from '@/hooks/student/useActivityDismissal';
import { useStudent } from '@/context/StudentContext';

export default function DashboardActionCenter({ student }) {
  const activity = useProfileActivity();
  const { academicPerformance } = useStudent();
  const {
    scholarshipThumbUpdate,
    scholarshipHardcopyPending,
    scholarshipApplicationReceived,
    scholarshipApplicationsOpen
  } = activity;

  const [attendanceSessions, setAttendanceSessions] = useState([]);

  const fetchAttendanceSessions = useCallback(async () => {
    try {
      const assignmentIds = (academicPerformance || []).map((s) => s.assignment_id).filter(Boolean);
      if (!assignmentIds.length) {
        setAttendanceSessions([]);
        return;
      }

      const res = await fetch(`/api/student/attendance/active-sessions?ids=${assignmentIds.join(',')}`);
      if (res.status === 401 || res.status === 403) return;
      
      const json = await res.json();
      if (res.ok) {
        setAttendanceSessions(json.data || []);
      }
    } catch (e) {
      // Silent
    }
  }, [academicPerformance]);

  useEffect(() => {
    const timer = setTimeout(() => {
      fetchAttendanceSessions();
    }, 0);
    return () => clearTimeout(timer);
  }, [fetchAttendanceSessions]);

  useEffect(() => {
    const channel = new BroadcastChannel('kucet_sse_sync');
    channel.onmessage = (event) => {
      const data = event.data;
      if (data && (data.type === 'SESSION_STARTED' || data.type === 'SESSION_ENDED')) {
        fetchAttendanceSessions();
      }
    };
    return () => channel.close();
  }, [fetchAttendanceSessions]);

  const handleSessionVerified = (assignmentId) => {
    setAttendanceSessions((prev) => prev.filter((s) => s.assignment_id !== assignmentId));
  };

  const hasAttendanceSessions = attendanceSessions.length > 0;

  const scholarshipReceivedDismissal = useActivityDismissal('scholarship_received');

  const isScholarshipEligible = student?.fee_reimbursement === 'YES' || student?.fee_reimbursement === 'GOV';
  const showScholarshipThumb = isScholarshipEligible && !!scholarshipThumbUpdate?.active;
  const showScholarshipHardcopy = isScholarshipEligible && !!scholarshipHardcopyPending?.active;
  const showScholarshipApplicationReceived = isScholarshipEligible && !!scholarshipApplicationReceived?.active;
  const showScholarshipApplicationsOpen = isScholarshipEligible && !!scholarshipApplicationsOpen?.active;

  const showSecurityWarning = !!student && (!student.email || !student.is_email_verified || !student.password_hash);

  const formatDateDDMMYYYY = (dateStr) => {
    if (!dateStr) return 'N/A';
    const d = new Date(dateStr);
    if (!Number.isNaN(d.getTime())) {
      const day = String(d.getDate()).padStart(2, '0');
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const year = d.getFullYear();
      return `${day}-${month}-${year}`;
    }
    return String(dateStr);
  };

  if (
    !showSecurityWarning &&
    !showScholarshipThumb &&
    !showScholarshipHardcopy &&
    !(showScholarshipApplicationReceived && !scholarshipReceivedDismissal.dismissed) &&
    !showScholarshipApplicationsOpen
  ) {
    return null;
  }

  return (
    <section className="rounded-sm border border-[#0b3578] lg:border-slate-200 bg-white overflow-hidden">
      <div className="bg-[#0b3578]/5 lg:bg-slate-50 px-5 py-3 border-b border-[#0b3578] lg:border-slate-200 flex items-center justify-between">
        <div>
          <h2 className="text-[10px] font-bold text-[#0b3578] lg:text-slate-500 uppercase tracking-[0.22em]">Priority Actions</h2>
          <p className="text-[11px] text-slate-500 mt-0.5">Updates that need your attention.</p>
        </div>
      </div>

      <div className="p-4 space-y-3">
        {/* 1. Scholarship Hard Copies */}
        {showScholarshipHardcopy && (
          <div className="border border-indigo-100 bg-white rounded-sm overflow-hidden">
            <div className="border-l-4 border-indigo-400 p-4">
              <div className="flex items-start gap-3">
                <div className="w-10 h-10 rounded-sm bg-indigo-50 text-indigo-700 ring-1 ring-indigo-100 flex items-center justify-center">
                  <span className="text-sm" aria-hidden="true">📄</span>
                </div>
                <div className="min-w-0">
                  <div className="text-sm font-bold text-slate-900">Submit Scholarship Hard Copies</div>
                  <div className="text-xs mt-1 text-slate-600">
                    Application No: <span className="font-bold">{scholarshipHardcopyPending.application_no || 'N/A'}</span>
                    {scholarshipHardcopyPending.academic_year && ` — Session: ${scholarshipHardcopyPending.academic_year}`}
                  </div>
                  <div className="mt-2 text-[10px] font-bold text-indigo-700 uppercase tracking-widest">
                    Submit documents at scholarship office.
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* 2. Thumb Verification */}
        {showScholarshipThumb && (
          <div className="border border-purple-100 bg-white rounded-sm overflow-hidden">
            <div className="border-l-4 border-purple-400 p-4">
              <div className="flex items-start gap-3">
                <div className="w-10 h-10 rounded-sm bg-purple-50 text-purple-700 ring-1 ring-purple-100 flex items-center justify-center">
                  <span className="text-sm" aria-hidden="true">🔔</span>
                </div>
                <div className="min-w-0">
                  <div className="text-sm font-bold text-slate-900">Scholarship Thumb Verification Required</div>
                  <div className="text-xs mt-1 text-slate-600">
                    Biometric verification required for App No: <span className="font-bold">{scholarshipThumbUpdate.application_no || 'N/A'}</span>
                  </div>
                  <div className="mt-2 text-[10px] font-bold text-purple-700 uppercase tracking-widest">
                    Visit a Mee-Seva center to complete verification.
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* 3. Scholarship Application Received */}
        {showScholarshipApplicationReceived && !scholarshipReceivedDismissal.dismissed && (
          <div
            className={
              'overflow-hidden transition-[max-height,opacity] duration-200 ease-out ' +
              (scholarshipReceivedDismissal.closing ? 'mt-0! max-h-0 opacity-0' : 'max-h-64 opacity-100')
            }
          >
            <div className="border border-emerald-100 bg-white rounded-sm overflow-hidden">
              <div className="border-l-4 border-emerald-400 p-4">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex items-start gap-3">
                    <div className="w-10 h-10 rounded-sm bg-emerald-50 text-emerald-700 ring-1 ring-emerald-100 flex items-center justify-center">
                      <span className="text-sm" aria-hidden="true">✅</span>
                    </div>
                    <div className="min-w-0">
                      <div className="text-sm font-bold text-slate-900">Scholarship Application Received</div>
                      <div className="text-xs mt-1 text-slate-600">
                        Documents submitted successfully. Awaiting verification updates.
                      </div>
                    </div>
                  </div>

                  <button
                    type="button"
                    aria-label="Dismiss"
                    onClick={scholarshipReceivedDismissal.dismiss}
                    className="shrink-0 -mt-1 -mr-1 rounded-sm p-2 text-slate-400 hover:text-slate-700 hover:bg-slate-100 focus:outline-none focus-visible:ring-2 focus-visible:ring-emerald-400"
                  >
                    <svg viewBox="0 0 24 24" className="h-4 w-4" fill="none" aria-hidden="true">
                      <path
                        d="M6 6l12 12M18 6L6 18"
                        stroke="currentColor"
                        strokeWidth="2"
                        strokeLinecap="round"
                      />
                    </svg>
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* 4. Scholarship Applications Open */}
        {showScholarshipApplicationsOpen && (
          <div className="border border-blue-100 bg-white rounded-sm overflow-hidden">
            <div className="border-l-0 sm:border-l-4 border-blue-400 p-4">
              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 rounded-sm bg-blue-50 text-blue-700 ring-1 ring-blue-100 flex items-center justify-center">
                    <span className="text-sm" aria-hidden="true">📅</span>
                  </div>
                  <div className="min-w-0">
                    <div className="text-sm font-bold text-slate-900">Scholarship Applications Open</div>
                    <div className="text-xs mt-1 text-slate-600">
                      Window: <span className="font-bold">{formatDateDDMMYYYY(scholarshipApplicationsOpen.startDate)}</span> — <span className="font-bold">{formatDateDDMMYYYY(scholarshipApplicationsOpen.endDate)}</span>
                    </div>
                  </div>
                </div>
                <Link
                  href="https://telanganaepass.cgg.gov.in/"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="px-5 py-2 bg-[#2563EB] text-white text-[10px] font-bold uppercase tracking-[0.22em] rounded-sm hover:bg-blue-700 hover:-translate-y-0.5 active:translate-y-0 transition-all text-center"
                >
                  Apply Now
                </Link>
              </div>
            </div>
          </div>
        )}

        {/* 5. Security Warning */}
        {showSecurityWarning && (
          <div className="border border-amber-100 bg-white rounded-sm overflow-hidden">
            <div className="border-l-4 border-amber-400 p-4">
              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 rounded-sm bg-amber-50 text-amber-700 ring-1 ring-amber-100 flex items-center justify-center">
                    <span className="text-sm" aria-hidden="true">⚠️</span>
                  </div>
                  <div className="min-w-0">
                    <div className="text-sm font-bold text-slate-900">Account Security Required</div>
                    <div className="text-xs mt-1 text-slate-600">
                      {!student.email ? 'Email not added.' : !student.is_email_verified ? 'Email verification pending.' : 'Password not set.'} Complete setup to access all portal features.
                    </div>
                  </div>
                </div>
                <Link
                  href="/student/settings/security"
                  className="px-5 py-2 bg-amber-500 text-white text-[10px] font-bold uppercase tracking-[0.22em] rounded-sm hover:bg-amber-600 hover:-translate-y-0.5 active:translate-y-0 transition-all text-center"
                >
                  Secure Account
                </Link>
              </div>
            </div>
          </div>
        )}
      </div>
    </section>
  );
}

'use client';
import React, { useEffect, useState, useCallback } from 'react';
import Link from 'next/link';
import toast from 'react-hot-toast';
import AttendanceVerificationActivity from './AttendanceVerificationActivity';
import useActivityDismissal from '@/hooks/student/useActivityDismissal';

export default function ProfileActivityBar({ activity, student }) {
  const {
    latestRequest,
    dismissCount,
    incrementVisit,
    dismiss,
    reset,
    scholarshipThumbUpdate,
    scholarshipHardcopyPending,
    scholarshipApplicationReceived,
    scholarshipApplicationsOpen,
  } = activity || {};
  const [visible, setVisible] = useState(true);
  const processedRef = React.useRef(null);
  const isProd = typeof process !== 'undefined' ? process.env.NODE_ENV === 'production' : true;

  const [attendanceSessions, setAttendanceSessions] = useState([]);

  const reqId = latestRequest?.request_id;
  const reqStatus = latestRequest?.status;

  // Handle visibility reset and increment logic for certificate requests
  useEffect(() => {
    if (!reqId) return;

    if (processedRef.current !== reqId) {
      const timer = setTimeout(() => setVisible(true), 0);

      const canIncrement = isProd ? dismissCount < 4 : true;
      if (canIncrement && typeof incrementVisit === 'function') {
        incrementVisit();
      }

      processedRef.current = reqId;
      return () => clearTimeout(timer);
    }
  }, [reqId, reqStatus, dismissCount, incrementVisit, isProd]);

  const fetchSessions = useCallback(async () => {
    if (!student) return;
    try {
      const res = await fetch('/api/student/academic-info');
      if (res.status === 401 || res.status === 403) return;
      
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to fetch academic info');
      const subjects = json.data || [];
      const assignmentIds = subjects.map((s) => s.assignment_id).filter(Boolean);
      if (!assignmentIds.length) return;

      const res2 = await fetch(`/api/student/attendance/active-sessions?ids=${assignmentIds.join(',')}`);
      if (res2.status === 401 || res2.status === 403) return;
      
      const json2 = await res2.json();
      if (!res2.ok) throw new Error(json2.error || 'Failed to fetch active attendance sessions');

      setAttendanceSessions(json2.data || []);
    } catch (error) {
      // Silent
    }
  }, [student]);

  useEffect(() => {
    const timer = setTimeout(() => {
      fetchSessions();
    }, 0);
    return () => clearTimeout(timer);
  }, [fetchSessions]);

  useEffect(() => {
    const channel = new BroadcastChannel('kucet_sse_sync');
    channel.onmessage = (event) => {
      const data = event.data;
      if (data && (data.type === 'SESSION_STARTED' || data.type === 'SESSION_ENDED')) {
        fetchSessions();
      }
    };
    return () => channel.close();
  }, [fetchSessions]);

  const hasAttendanceSessions = attendanceSessions.length > 0;

  const status = (latestRequest?.status || '').toUpperCase();
  const type = latestRequest?.certificate_type || latestRequest?.type || 'certificate';
  const id = latestRequest?.request_id || latestRequest?.requestId || latestRequest?.id;

  const handleDismiss = () => {
    setVisible(false);
    if (typeof dismiss === 'function') dismiss();
  };

  const handleReset = () => {
    if (typeof reset === 'function') reset();
  };

  const handleDownload = async () => {
    if (!id) return;
    try {
      const res = await fetch(`/api/student/requests/download/${id}`, { method: 'GET', credentials: 'same-origin' });
      if (!res.ok) return;
      const blob = await res.blob();
      
      const filename = `${type}-${id}.pdf`;

      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      window.URL.revokeObjectURL(url);
    } catch (e) {
      console.error('Download error:', e);
    }
  };

  const handleSessionVerified = (assignmentId) => {
    setAttendanceSessions((prev) => prev.filter((s) => s.assignment_id !== assignmentId));
  };

  const formatDateDDMMYYYY = (dateStr) => {
    if (!dateStr) return 'N/A';
    const d = new Date(dateStr);
    if (!Number.isNaN(d.getTime())) {
      const day = String(d.getDate()).padStart(2, '0');
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const year = d.getFullYear();
      return `${day}-${month}-${year}`;
    }
    const parts = String(dateStr).split('-');
    if (parts.length === 3) {
      return `${parts[2]}-${parts[1]}-${parts[0]}`;
    }
    return String(dateStr);
  };

  const isScholarshipEligible = student?.fee_reimbursement === 'YES' || student?.fee_reimbursement === 'GOV';

  const showRequestBar =
    !!latestRequest &&
    visible &&
    !(latestRequest && dismissCount >= 4 && isProd);

  const showLegacyWarning = !latestRequest && !!student && (!student.email || !student.is_email_verified || !student.password_hash);

  const showScholarshipThumb = isScholarshipEligible && !!scholarshipThumbUpdate?.active;
  const showScholarshipHardcopy = isScholarshipEligible && !!scholarshipHardcopyPending?.active;
  const showScholarshipApplicationReceived = isScholarshipEligible && !!scholarshipApplicationReceived?.active;
  const showScholarshipApplicationsOpen = isScholarshipEligible && !!scholarshipApplicationsOpen?.active;

  const scholarshipReceivedDismissal = useActivityDismissal('scholarship_received');

  if (
    !hasAttendanceSessions &&
    !showLegacyWarning &&
    !showRequestBar &&
    !showScholarshipThumb &&
    !showScholarshipHardcopy &&
    !(showScholarshipApplicationReceived && !scholarshipReceivedDismissal.dismissed) &&
    !showScholarshipApplicationsOpen
  ) {
    return null;
  }

  return (
    <div className="w-full flex justify-center">
      <div className="w-full max-w-6xl space-y-3">
        {/* 1️⃣ Submit Hard Copies */}
        {showScholarshipHardcopy && (
          <div className="border border-indigo-200 bg-indigo-50 text-indigo-800 rounded-md p-3">
            <div className="flex items-center justify-between gap-4">
              <div className="text-sm">
                <div className="font-semibold">📄 Submit Scholarship Hard Copies</div>
                <div className="text-sm mt-1">
                  You have applied for scholarship.
                  <div className="mt-1">
                    Application No: <span className="font-medium">{scholarshipHardcopyPending.application_no || 'N/A'}</span>
                    {scholarshipHardcopyPending.academic_year ? (
                      <span> — Academic Year: <span className="font-medium">{scholarshipHardcopyPending.academic_year}</span></span>
                    ) : null}
                  </div>
                  <div className="mt-1 text-xs text-indigo-700">
                    Please submit your required documents in the scholarship office.
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* 2️⃣ Thumb Verification Required */}
        {scholarshipThumbUpdate?.active && (
          <div className="border border-purple-200 bg-purple-50 text-purple-800 rounded-md p-3">
            <div className="flex items-center justify-between gap-4">
              <div className="text-sm">
                <div className="font-semibold">🔔 Scholarship Thumb Verification Required</div>
                <div className="text-sm mt-1">
                  Your scholarship requires biometric verification. Application No: <span className="font-medium">{scholarshipThumbUpdate.application_no || 'N/A'}</span>
                  {scholarshipThumbUpdate.academic_year ? (
                    <span> — Academic Year: <span className="font-medium">{scholarshipThumbUpdate.academic_year}</span></span>
                  ) : null}
                  <div className="mt-1 text-xs text-purple-700">
                    Please visit the nearest Mee-Seva center to complete thumb verification.
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2">
                {/* <Link href="/student/profile" className="text-sm text-purple-700 hover:underline">
                  View Details
                </Link> */}
              </div>
            </div>
          </div>
        )}

        {/* 3️⃣ Scholarship Application Received */}
        {showScholarshipApplicationReceived && !scholarshipReceivedDismissal.dismissed && (
          <div
            className={
              'overflow-hidden transition-[max-height,opacity] duration-200 ease-out ' +
              (scholarshipReceivedDismissal.closing ? 'mt-0! max-h-0 opacity-0' : 'max-h-64 opacity-100')
            }
          >
            <div className="border border-green-200 bg-green-50 text-green-800 rounded-md p-3">
              <div className="flex items-start justify-between gap-4">
                <div className="text-sm">
                  <div className="font-semibold">✅ Scholarship Application Received</div>
                  <div className="text-sm mt-1">
                    Your scholarship application documents have been submitted successfully.
                    <div className="mt-1 text-xs text-green-900">Please wait for government verification updates.</div>
                  </div>
                </div>

                <button
                  type="button"
                  aria-label="Dismiss"
                  onClick={scholarshipReceivedDismissal.dismiss}
                  className="shrink-0 -mt-1 -mr-1 rounded-md p-1 text-green-700/70 hover:text-green-900 hover:bg-green-100 focus:outline-none focus-visible:ring-2 focus-visible:ring-green-400"
                >
                  <svg viewBox="0 0 24 24" className="h-4 w-4" fill="none" aria-hidden="true">
                    <path
                      d="M6 6l12 12M18 6L6 18"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                    />
                  </svg>
                </button>
              </div>
            </div>
          </div>
        )}

        {/* 4️⃣ Scholarship Applications Open */}
        {showScholarshipApplicationsOpen && (
          <div className="border border-blue-200 bg-blue-50 text-blue-800 rounded-md p-3">
            <div className="flex items-center justify-between gap-4">
              <div className="text-sm">
                <div className="font-semibold">📅 Scholarship Applications Open</div>
                <div className="text-sm mt-1">
                  <div className="mt-1">
                    Apply online and submit your documents in the scholarship office.
                  </div>
                  <div className="mt-2 text-xs text-blue-900">
                    Submission Window: <span className="font-medium">{formatDateDDMMYYYY(scholarshipApplicationsOpen.startDate)}</span> — <span className="font-medium">{formatDateDDMMYYYY(scholarshipApplicationsOpen.endDate)}</span>
                  </div>
                </div>
              </div>
              <div className="flex items-center">
                <Link
                  href="https://telanganaepass.cgg.gov.in//epassonlinelinks.do"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-sm font-semibold text-blue-700 hover:underline"
                >
                  Apply Now
                </Link>
              </div>
            </div>
          </div>
        )}

        {showLegacyWarning && (
          <div className="border border-yellow-300 bg-yellow-50 text-yellow-800 rounded-md p-3">
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
              <div className="text-sm">
                {!student.email && (
                  <span>⚠️ Email not added. Please set your email and password to use portal features.</span>
                )}
                {student.email && !student.is_email_verified && (
                  <span>⚠️ Email verification required. Please verify your email to use portal features.</span>
                )}
                {!student.password_hash && student.email && student.is_email_verified && (
                  <span>⚠️ Password not set. Please set a password to continue.</span>
                )}
              </div>
              <Link
                href="/student/settings/security"
                className="inline-flex items-center text-sm font-semibold text-blue-700 hover:underline"
              >
                Go to Security &amp; Privacy
              </Link>
            </div>
          </div>
        )}

        {/* 5️⃣ Certificate Notifications */}
        {showRequestBar && (
          <div
            className={
              status === 'APPROVED'
                ? 'border border-green-200 bg-green-50 text-green-800 rounded-md p-3'
                : status === 'REJECTED'
                ? 'border border-red-200 bg-red-50 text-red-800 rounded-md p-3'
                : 'border border-blue-200 bg-blue-50 text-blue-800 rounded-md p-3'
            }
          >
            <div className="flex items-center justify-between gap-4">
              <div className="text-sm">
                {status === 'APPROVED' && (
                  <>
                    Your {type} request is <span className="font-semibold">approved</span>.
                  </>
                )}
                {status === 'REJECTED' && (
                  <>
                    Your {type} request was <span className="font-semibold">rejected</span>. You may view details or
                    re-apply.
                  </>
                )}
                {status !== 'APPROVED' && status !== 'REJECTED' && (
                  <>
                    Your {type} request is <span className="font-semibold">pending</span>. We&apos;ll notify you when
                    it&apos;s processed.
                  </>
                )}
              </div>
              <div className="flex items-center gap-2">
                <Link
                  href={`/student/requests/certificates?request_id=${encodeURIComponent(
                    id || ''
                  )}&scroll=history`}
                  className="text-sm text-blue-700 hover:underline"
                >
                  View Details
                </Link>
                <button onClick={handleDismiss} className="ml-2 text-sm text-gray-600">
                  ✕
                </button>
              </div>
            </div>
          </div>
        )}

        {/* 6️⃣ Attendance Warnings */}
        {hasAttendanceSessions && (
          <AttendanceVerificationActivity
            sessions={attendanceSessions}
            onSessionVerified={handleSessionVerified}
          />
        )}
      </div>
    </div>
  );
}

'use client';
import React from 'react';

import CommonProfileStatusBar from '@/components/profile/ProfileStatusBar';

export default function ProfileStatusBar({ courseLabel, yearOfStudy, semesterLabel, currentAcademicYearLabel, batchString }) {
