'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { usePathname } from 'next/navigation';
import RealtimeListener from '@/components/RealtimeListener';
import { useStudent } from '@/context/StudentContext';
import AttendanceVerificationActivity from './AttendanceVerificationActivity';

export default function StudentActivityBar() {
  const pathname = usePathname();
  const { studentData, academicPerformance, loading: studentLoading } = useStudent();
  const [activeActivity, setActiveActivity] = useState(null);
  const [attendanceSessions, setAttendanceSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const lastFetchedPeriodRef = useRef(null);
  const isUnmountedRef = useRef(false);

  const fetchActivity = useCallback(async () => {
    if (isUnmountedRef.current || studentLoading || !studentData) return;
    try {
      const res = await fetch('/api/student/current-activity');
      if (res.status === 401 || res.status === 403) return;
      
      const data = await res.json();
      if (isUnmountedRef.current) return;

      if (res.ok && data.active) {
        setActiveActivity(data);
        lastFetchedPeriodRef.current = data.period;
      } else {
        setActiveActivity(null);
        lastFetchedPeriodRef.current = null;
      }
    } catch (e) {
      // Silent in production or if it's a transient network error during reload
    } finally {
      if (!isUnmountedRef.current) setLoading(false);
    }
  }, [studentLoading, studentData]);

  const fetchAttendanceSessions = useCallback(async () => {
    if (isUnmountedRef.current || studentLoading || !studentData || !academicPerformance?.length) return;
    
    try {
      const assignmentIds = academicPerformance.map(s => s.assignment_id).filter(Boolean);
      if (!assignmentIds.length) return;

      const res = await fetch(`/api/student/attendance/active-sessions?ids=${assignmentIds.join(',')}`);
      if (res.status === 401 || res.status === 403) return;

      const json = await res.json();
      
      if (res.ok && !isUnmountedRef.current) {
        setAttendanceSessions(json.data || []);
      }
    } catch (e) {
      // Silent
    }
  }, [academicPerformance, studentLoading, studentData]);

  useEffect(() => {
    isUnmountedRef.current = false;
    const id = setTimeout(() => {
      fetchActivity();
      fetchAttendanceSessions();
    }, 0);
    
    // Check for period transitions every 30 seconds
    const interval = setInterval(() => {
      const now = new Date();
      const time = now.getHours() * 100 + now.getMinutes();
      const transitionTimes = [930, 1020, 1110, 1120, 1210, 1300, 1400, 1450, 1540, 1630];
      
      const isTransitionWindow = transitionTimes.some(t => {
        const diff = time - t;
        return diff >= 0 && diff <= 1;
      });

      if (isTransitionWindow) {
        fetchActivity();
      }
    }, 30000); 

    const backupInterval = setInterval(() => {
        fetchActivity();
        fetchAttendanceSessions();
    }, 5 * 60 * 1000); // More frequent refresh for sessions
    
    return () => {
      isUnmountedRef.current = true;
      clearTimeout(id);
      clearInterval(interval);
      clearInterval(backupInterval);
    };
  }, [fetchActivity, fetchAttendanceSessions]);

  const handleRealtimeUpdate = useCallback((data) => {
    if (data.type === 'TIMETABLE_CHANGED') {
      fetchActivity();
    } else if (data.type === 'SESSION_STARTED' || data.type === 'SESSION_ENDED') {
      fetchAttendanceSessions();
    }
  }, [fetchActivity, fetchAttendanceSessions]);

  useEffect(() => {
    const channel = new BroadcastChannel('kucet_sse_sync');
    channel.onmessage = (event) => {
      if (event.data) handleRealtimeUpdate(event.data);
    };
    return () => channel.close();
  }, [handleRealtimeUpdate]);

  const handleSessionVerified = (assignmentId) => {
    setAttendanceSessions(prev => prev.filter(s => s.assignment_id !== assignmentId));
  };

  const hasAttendance = attendanceSessions.length > 0;
  const isProfilePage = pathname === '/student/profile';
  const showBar = activeActivity || (hasAttendance && !isProfilePage);

  const activity = activeActivity?.activity;
  const period = activeActivity?.period;

  return (
    <div className="space-y-0 animate-in slide-in-from-top duration-500 shadow-md">
      <RealtimeListener onUpdate={handleRealtimeUpdate} />
      
      {/* 1. Main Activity Bar (Ongoing Lecture) */}
      {activeActivity && (
        <div className="bg-[#0b3578] border-b border-white/10 relative overflow-hidden">
          <div className="absolute inset-0 bg-blue-500/5 animate-pulse"></div>
          
          <div className="max-w-7xl mx-auto px-4 py-2 flex flex-col md:flex-row justify-between items-center gap-3 relative z-10">
            <div className="flex items-center gap-3">
              <div className="flex items-center justify-center w-8 h-8 bg-white/10 rounded-full border border-white/20">
                 <span className="relative flex h-2 w-2">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-2 w-2 bg-blue-400"></span>
                 </span>
              </div>
              <div>
                <div className="flex items-center gap-2">
                   <span className="text-[9px] font-bold text-blue-200 uppercase tracking-wider">Ongoing Lecture</span>
                   <span className="text-[9px] font-medium text-white/40 uppercase">Period {period}</span>
                </div>
                <h3 className="text-white font-bold tracking-tight leading-none uppercase text-sm">
                  {activity.subject_name}
                </h3>
              </div>
            </div>

            <div className="flex items-center gap-5">
               <div className="text-right border-r border-white/10 pr-5">
                  <p className="text-[9px] font-bold text-blue-200 uppercase tracking-wider">Location</p>
                  <p className="text-white font-bold text-xs uppercase">{activity.room_no || 'TBD'}</p>
               </div>
               <div className="text-right">
                  <p className="text-[9px] font-bold text-blue-200 uppercase tracking-wider">Faculty</p>
                  <p className="text-white font-bold text-[11px] uppercase truncate max-w-[120px]">{activity.faculty_name || 'Unassigned'}</p>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* 2. Secure Attendance Extension (Hidden on Profile Page to avoid duplication) */}
      {hasAttendance && !isProfilePage && (
        <div className="bg-white border-b border-gray-200 p-4">
          <div className="max-w-7xl mx-auto">
             <AttendanceVerificationActivity 
               sessions={attendanceSessions} 
               onSessionVerified={handleSessionVerified} 
             />
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { useStudent } from '@/context/StudentContext';
import useProfileActivity from '@/hooks/student/useProfileActivity';
import Image from 'next/image';
import Link from 'next/link';
import { useAssets } from '@/context/AssetContext';
import { usePathname, useRouter } from 'next/navigation';
import { logoutByRole } from '@/lib/logout';
import { getPortalTitle } from '@/lib/path-utils';

export default function StudentTopBar({ onMenuClick }) {
  const { studentData } = useStudent();
  const student = studentData?.student;
  const { getAsset } = useAssets();
  const router = useRouter();
  const pathname = usePathname();
  
  const activity = useProfileActivity();
  const { latestRequest, dismissCount, dismiss } = activity;
  const isProd = typeof process !== 'undefined' ? process.env.NODE_ENV === 'production' : true;
  
  // Local state to hide notification immediately on click
  const [localVisible, setLocalVisible] = useState(true);
  const showRequestNotif = !!latestRequest && localVisible && !(latestRequest && dismissCount >= 4 && isProd);

  const [notifOpen, setNotifOpen] = useState(false);
  const desktopDropdownRef = useRef(null);

  // Close dropdown on click outside
  useEffect(() => {
    function handleClickOutside(event) {
      if (desktopDropdownRef.current && desktopDropdownRef.current.contains(event.target)) return;
      setNotifOpen(false);
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const notifications = [];
  if (showRequestNotif) {
    const status = (latestRequest?.status || '').toUpperCase();
    const type = latestRequest?.certificate_type || latestRequest?.type || 'Certificate';
    notifications.push({
      id: latestRequest.request_id || latestRequest.id,
      title: `${type} Request ${status.charAt(0) + status.slice(1).toLowerCase()}`,
      desc: status === 'APPROVED' ? 'Your request has been processed and is ready.' : 
            status === 'REJECTED' ? 'Your request was declined.' : 
            'Your request is currently under review.',
      time: 'Update',
      link: `/student/requests/certificates?request_id=${latestRequest.request_id || ''}&scroll=history`,
      type: status === 'APPROVED' ? 'success' : status === 'REJECTED' ? 'error' : 'info'
    });
  }

  const hasUnread = notifications.length > 0;

  const handleDismiss = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setLocalVisible(false); // Hide immediately in UI
    if (typeof dismiss === 'function') dismiss(); // Persistence logic
  };

  return (
    <header className="h-14 lg:h-20 flex items-center px-4 lg:px-8 bg-transparent relative">
      {/* Left: Mobile Menu Toggle */}
      <div className="flex-1 flex items-center justify-start">
        <button 
          onClick={onMenuClick}
          className="lg:hidden p-2 text-white/70 hover:text-white rounded-lg transition-colors"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
      </div>

      {/* Right Side: Notifications & Portal Title */}
      <div className="flex-1 flex items-center justify-end gap-3 lg:gap-5">
        
        {/* Desktop Bell - Hidden on Mobile */}
        <div className="relative hidden lg:block" ref={desktopDropdownRef}>
          <button 
            onClick={() => setNotifOpen(!notifOpen)}
            className={`p-2 transition-colors rounded-lg relative ${notifOpen ? 'text-[#0b3578] bg-blue-50' : 'text-slate-400 hover:text-[#0b3578] hover:bg-slate-50'}`}
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" />
            </svg>
            {hasUnread && (
              <span className="absolute top-2 right-2.5 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
            )}
          </button>

          {/* Desktop Dropdown remains unchanged for desktop layout consistency */}
          {notifOpen && (
            <div className="absolute right-0 mt-3 w-80 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden z-[70] animate-fadeIn">
              <div className="px-5 py-4 border-b border-slate-50 flex items-center justify-between">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Inbox</span>
                <span className="text-[9px] font-bold text-[#0b3578] bg-blue-50 px-2 py-0.5 rounded-full">{notifications.length} New</span>
              </div>
              
              <div className="max-h-[400px] overflow-y-auto custom-scrollbar">
                {notifications.length > 0 ? (
                  notifications.map((n) => (
                    <div 
                      key={n.id} 
                      className="block p-5 hover:bg-slate-50 transition-colors border-b border-slate-50 last:border-0 relative group"
                    >
                      <div className="flex gap-4">
                        <div className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 text-xs ${
                          n.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 
                          n.type === 'error' ? 'bg-rose-50 text-rose-600' : 'bg-blue-50 text-[#0b3578]'
                        }`}>
                          {n.type === 'success' ? '✓' : n.type === 'error' ? '!' : 'i'}
                        </div>
                        <div className="flex-1 pr-4 text-left">
                          <h4 className="text-sm font-bold text-slate-800">{n.title}</h4>
                          <p className="text-[11px] text-slate-500 mt-1 leading-relaxed">{n.desc}</p>
                          <div className="mt-2">
                            <Link 
                              href={n.link} 
                              onClick={() => setNotifOpen(false)}
                              className="text-[10px] font-bold text-[#0b3578] uppercase tracking-wider hover:underline"
                            >
                              View details →
                            </Link>
                          </div>
                        </div>
                      </div>
                      
                      <button 
                        onClick={handleDismiss}
                        className="absolute top-4 right-4 text-slate-300 hover:text-slate-600 transition-colors p-1"
                        title="Dismiss"
                      >
                        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                        </svg>
                      </button>
                    </div>
                  ))
                ) : (
                  <div className="py-12 text-center">
                    <div className="text-3xl mb-3 opacity-20">📭</div>
                    <p className="text-xs font-bold text-slate-300 uppercase tracking-widest">No new notifications</p>
                  </div>
                )}
              </div>
              
              <Link 
                href="/student/settings/security" 
                onClick={() => setNotifOpen(false)}
                className="block py-3 text-center bg-slate-50 text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:bg-slate-100 transition-colors"
              >
                Notification Settings
              </Link>
            </div>
          )}
        </div>

        {/* Portal Title for Mobile */}
        <div className="lg:hidden pr-2">
          <span className="text-[11px] font-bold text-white/90 tracking-widest uppercase">
            {getPortalTitle(pathname)}
          </span>
        </div>
      </div>
    </header>
  );
}

"use client";

import { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { Info, X } from 'lucide-react';

