import React, { createContext, useContext, useEffect, useState } from 'react';

const AcademicsContext = createContext(null);

export function AcademicsProvider({ children, roll }) {
  const [cache, setCache] = useState(null);

  useEffect(() => {
    if (!roll) return;
    try {
      const key = `academics_cache_${roll}`;
      const raw = sessionStorage.getItem(key) || localStorage.getItem(key);
      if (raw) {
        // Defer setState to avoid synchronous setState inside effect
        const parsed = JSON.parse(raw);
        setTimeout(() => setCache(parsed), 0);
      }
    } catch (e) {
      // ignore parse errors
      setTimeout(() => setCache(null), 0);
    }
  }, [roll]);

  const saveCache = React.useCallback((payload) => {
    if (!roll) return;
    try {
      const key = `academics_cache_${roll}`;
      const data = { payload, ts: Date.now() };
      sessionStorage.setItem(key, JSON.stringify(data));
      setCache(data);
    } catch (e) {
      // ignore storage errors
    }
  }, [roll]);

  const clearCache = React.useCallback(() => {
    if (!roll) return;
    try { sessionStorage.removeItem(`academics_cache_${roll}`); } catch { /* empty */ }
    setCache(null);
  }, [roll]);

  // Detect full page reloads (when available) so callers can decide to refetch
  const isReload = (() => {
    try {
      const nav = performance.getEntriesByType('navigation')?.[0];
      return nav ? nav.type === 'reload' : false;
    } catch (e) { return false; }
  })();

  return (
    <AcademicsContext.Provider value={{ cache, saveCache, clearCache, isReload }}>
      {children}
    </AcademicsContext.Provider>
  );
}

export function useAcademicsCache() {
  return useContext(AcademicsContext);
}

export default AcademicsContext;

'use client';

import { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react';

export const AdminContext = createContext();

export function AdminProvider({ children }) {
  const lastFetchTimeRef = useRef(0);
  const activePromiseRef = useRef(null);
  const isInitializingRef = useRef(false);

  const [adminData, setAdminData] = useState(null);
  const [collegeInfo, setCollegeInfo] = useState(null);
  const [clerks, setClerks] = useState([]);
  const [studentStats, setStudentStats] = useState(null);
  const [facultyInterests, setFacultyInterests] = useState([]);
  const [isLoadingFaculty, setIsLoadingFaculty] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchCollegeInfo = useCallback(async () => {
    try {
      const res = await fetch('/api/public/college-info');
      if (res.ok) {
        const data = await res.json();
        setCollegeInfo(data.collegeInfo);
      }
    } catch (e) {
      console.error('Failed to fetch college info', e);
    }
  }, []);

  const fetchClerks = useCallback(async () => {
    try {
      const res = await fetch('/api/admin/clerks');
      if (res.ok) {
        const json = await res.json();
        const payload = json?.data ?? json ?? [];
        setClerks(payload);
        return payload;
      }
    } catch (e) {
      console.error('Failed to fetch clerks', e);
    }
    return [];
  }, []);

  const fetchStudentStats = useCallback(async () => {
    try {
      const res = await fetch('/api/admin/student-stats');
      if (res.ok) {
        const json = await res.json();
        const payload = json?.data ?? json ?? null;
        setStudentStats(payload);
        return payload;
      }
    } catch (e) {
      console.error('Failed to fetch student stats', e);
    }
    return null;
  }, []);

  const fetchAdminMe = useCallback(async () => {
    try {
      const res = await fetch('/api/admin/verify'); // Assuming verify endpoint gives admin info
      if (res.ok) {
        const json = await res.json();
        const payload = json?.admin ?? json ?? null;
        setAdminData(payload);
        return payload;
      }
    } catch (e) {
      console.error('Failed to verify admin', e);
    }
    return null;
  }, []);

  const fetchFacultyInterests = useCallback(async () => {
    setIsLoadingFaculty(true);
    try {
      const res = await fetch('/api/admin/faculty/interests');
      if (res.ok) {
        const json = await res.json();
        setFacultyInterests(json.data || []);
        return json.data;
      }
    } catch (e) {
      console.error('Failed to fetch faculty interests', e);
    } finally {
      setIsLoadingFaculty(false);
    }
    return [];
  }, []);

  const refreshAll = useCallback(async () => {
    if (activePromiseRef.current) {
      return activePromiseRef.current;
    }

    const promise = (async () => {
      try {
        if (!adminData) setLoading(true);
        await Promise.all([
          fetchAdminMe(),
          fetchClerks(),
          fetchStudentStats(),
          fetchCollegeInfo(),
          fetchFacultyInterests()
        ]);
        lastFetchTimeRef.current = Date.now();
      } catch (e) {
        console.error('Failed to refresh admin data', e);
      } finally {
        setLoading(false);
        activePromiseRef.current = null;
      }
    })();

    activePromiseRef.current = promise;
    return promise;
  }, [fetchAdminMe, fetchClerks, fetchStudentStats, fetchCollegeInfo, fetchFacultyInterests, adminData]);

  const handleResume = useCallback(async (event) => {
    const now = Date.now();
    const isBfcacheRestore = event?.type === 'pageshow' && event.persisted;
    const isStuck = loading && !adminData;

    // Check if we should revalidate
    const shouldReinit = isBfcacheRestore || isStuck;
    const throttleTime = 5000; // 5 seconds throttle
    const isThrottled = now - lastFetchTimeRef.current < throttleTime;

    if (!shouldReinit && isThrottled) {
      return;
    }

    if (activePromiseRef.current) {
      if (shouldReinit) {
        setLoading(true);
      }
      try {
        await activePromiseRef.current;
      } finally {
        setLoading(false);
      }
      return;
    }

    isInitializingRef.current = true;
    if (shouldReinit) {
      setLoading(true);
    }

    try {
      await refreshAll();
    } catch (e) {
      console.error('Failed to revalidate admin data on resume', e);
    } finally {
      setLoading(false);
      isInitializingRef.current = false;
    }
  }, [loading, adminData, refreshAll]);

  useEffect(() => {
    if (adminData || isInitializingRef.current) return;

    let cancelled = false;
    isInitializingRef.current = true;

    const init = async () => {
      if (!adminData) setLoading(true);
      try {
        await refreshAll();
      } finally {
        if (!cancelled) {
          setLoading(false);
          isInitializingRef.current = false;
        }
      }
    };
    init();

    return () => {
      cancelled = true;
      isInitializingRef.current = false;
    };
  }, [refreshAll, adminData]);

  useEffect(() => {
    const onResume = (e) => {
      if (e && e.type === 'visibilitychange' && document.visibilityState !== 'visible') {
        return;
      }
      handleResume(e);
    };

    window.addEventListener('pageshow', onResume);
    document.addEventListener('visibilitychange', onResume);
    window.addEventListener('focus', onResume);

    if (loading && !adminData && !isInitializingRef.current) {
      handleResume();
    }

    return () => {
      window.removeEventListener('pageshow', onResume);
      document.removeEventListener('visibilitychange', onResume);
      window.removeEventListener('focus', onResume);
    };
  }, [handleResume, loading, adminData]);

  return (
    <AdminContext.Provider value={{ 
      adminData, 
      collegeInfo,
      clerks, 
      studentStats, 
      loading, 
      error, 
      refreshAll,
      refreshClerks: fetchClerks,
      refreshStudentStats: fetchStudentStats,
      facultyInterests,
      isLoadingFaculty,
      refreshFaculty: fetchFacultyInterests
    }}>
      {children}
    </AdminContext.Provider>
  );
}

export function useAdmin() {
  const context = useContext(AdminContext);
  if (context === undefined) {
    throw new Error('useAdmin must be used within an AdminProvider');
  }
  return context;
}

'use client';
import { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react';
import RealtimeListener from '@/components/RealtimeListener';

export const ClerkContext = createContext();

export function ClerkProvider({ children }) {
  // ... rest of state
  const lastFetchTimeRef = useRef(0);
  const activePromiseRef = useRef(null);
  const isInitializingRef = useRef(false);

  const [clerkData, setClerkData] = useState(null);
  const [collegeInfo, setCollegeInfo] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [facultyAssignments, setFacultyAssignments] = useState([]);
  const [facultyInterests, setFacultyInterests] = useState([]);
  const [isLoadingFaculty, setIsLoadingFaculty] = useState(false);
  const [pendingProfileRequests, setPendingProfileRequests] = useState([]);
  const [pendingCertificateRequests, setPendingCertificateRequests] = useState([]);
  const [admissionDrafts, setAdmissionDrafts] = useState([]);
  const [isLoadingRequests, setIsLoadingRequests] = useState(false);
  const [areRequestsBootstrapping, setAreRequestsBootstrapping] = useState(true);
  const [hodBranchData, setHodBranchData] = useState(null);
  const [isLoadingHOD, setIsLoadingHOD] = useState(false);
  const [studentHistory, setStudentHistory] = useState({ records: [], myCount: 0, allCount: 0 });
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);

  const fetchCollegeInfo = useCallback(async () => {
    try {
      const res = await fetch('/api/public/college-info');
      if (res.ok) {
        const data = await res.json();
        setCollegeInfo(data.collegeInfo);
      }
    } catch (e) {
      console.error('Failed to fetch college info', e);
    }
  }, []);

  const fetchClerk = useCallback(async () => {
    try {
      const res = await fetch('/api/clerk/me');
      if (res.ok) {
        const data = await res.json();
        setClerkData(data.data);
        return data.data;
      } else {
        try {
          const data = await res.json();
          setError(data.error || 'Failed to fetch clerk data');
        } catch {
          setError('Failed to fetch clerk data');
        }
      }
    } catch (e) {
      setError('Network error');
    }
    return null;
  }, []);

  const fetchFacultyData = useCallback(async () => {
    setIsLoadingFaculty(true);
    try {
      const [asgnRes, intRes] = await Promise.all([
        fetch('/api/clerk/faculty/assignments'),
        fetch('/api/clerk/faculty/interests')
      ]);

      if (asgnRes.ok) {
        const asgnJson = await asgnRes.json();
        setFacultyAssignments(asgnJson.data || []);
      }
      if (intRes.ok) {
        const intJson = await intRes.json();
        setFacultyInterests(intJson.data || []);
      }
    } catch (e) {
      console.error('Failed to fetch faculty data', e);
    } finally {
      setIsLoadingFaculty(false);
    }
  }, []);

  const fetchHODData = useCallback(async () => {
    setIsLoadingHOD(true);
    try {
      const [configRes, facultyRes, ttRes, subjectsRes, assignmentsRes] = await Promise.all([
        fetch('/api/clerk/hod/branch-config'),
        fetch('/api/clerk/hod/faculty-load'),
        fetch('/api/clerk/hod/timetable'),
        fetch('/api/clerk/hod/branch-subjects'),
        fetch('/api/clerk/hod/subject-assignments')
      ]);

      if (configRes.ok && facultyRes.ok && ttRes.ok && subjectsRes.ok && assignmentsRes.ok) {
        const configJson = await configRes.json();
        const facultyJson = await facultyRes.json();
        const ttJson = await ttRes.json();
        const subjectsJson = await subjectsRes.json();
        const assignmentsJson = await assignmentsRes.json();

        setHodBranchData({
          config: configJson.data,
          faculty: facultyJson.data,
          timetable: ttJson.data,
          allSubjects: subjectsJson.data,
          officialAssignments: assignmentsJson.data
        });
      }
    } catch (e) {
      console.error('Failed to fetch HOD data', e);
    } finally {
      setIsLoadingHOD(false);
    }
  }, []);

  const fetchPendingProfileRequests = useCallback(async () => {
    setIsLoadingRequests(true);
    try {
      const res = await fetch('/api/clerk/admission/student-requests');
      if (res.ok) {
        const json = await res.json();
        setPendingProfileRequests(json.data || []);
      }
    } catch (e) {
      console.error('Failed to fetch pending profile requests', e);
    } finally {
      setIsLoadingRequests(false);
    }
  }, []);

  const fetchPendingCertificateRequests = useCallback(async (role) => {
    if (!role) return;
    setIsLoadingRequests(true);
    try {
      const res = await fetch(`/api/clerk/requests?clerkType=${role}`);
      if (res.ok) {
        const json = await res.json();
        setPendingCertificateRequests(json.records || []);
      }
    } catch (e) {
      console.error('Failed to fetch pending certificate requests', e);
    } finally {
      setIsLoadingRequests(false);
    }
  }, []);

  const fetchAdmissionDrafts = useCallback(async () => {
    setIsLoadingRequests(true);
    try {
      const res = await fetch('/api/clerk/admission/drafts?status=DRAFT');
      const data = await res.json();
      if (res.ok) {
        setAdmissionDrafts(data.data || []);
      }
    } catch (e) {
      console.error('Failed to fetch admission drafts', e);
    } finally {
      setIsLoadingRequests(false);
    }
  }, []);

  const fetchStudentHistory = useCallback(async (scope = 'my') => {
    setIsLoadingHistory(true);
    try {
      const res = await fetch(`/api/clerk/student-history?scope=${scope}`);
      if (res.ok) {
        const json = await res.json();
        setStudentHistory({
          records: json.records || [],
          myCount: json.myCount || 0,
          allCount: json.allCount || 0
        });
      }
    } catch (e) {
      console.error('Failed to fetch student history', e);
    } finally {
      setIsLoadingHistory(false);
    }
  }, []);

  const refreshAllRequests = useCallback(async (role) => {
    const promises = [];
    if (role === 'admission') {
      promises.push(fetchPendingProfileRequests());
      promises.push(fetchPendingCertificateRequests('admission'));
      promises.push(fetchAdmissionDrafts());
      promises.push(fetchStudentHistory('my'));
    } else if (role === 'scholarship') {
      promises.push(fetchPendingCertificateRequests('scholarship'));
    }
    await Promise.all(promises);
  }, [fetchPendingProfileRequests, fetchPendingCertificateRequests, fetchAdmissionDrafts, fetchStudentHistory]);

  const refreshAllData = useCallback(async () => {
    if (activePromiseRef.current) {
      return activePromiseRef.current;
    }

    const promise = (async () => {
      try {
        const clerk = await fetchClerk();
        const promises = [fetchCollegeInfo()];
        if (clerk?.role === 'faculty') {
          promises.push(fetchFacultyData());
          if (clerk?.is_hod) {
            promises.push(fetchHODData());
          }
        }
        if (clerk?.role === 'admission') {
          promises.push(fetchPendingProfileRequests());
          promises.push(fetchPendingCertificateRequests('admission'));
          promises.push(fetchAdmissionDrafts());
          promises.push(fetchStudentHistory('my'));
        }
        if (clerk?.role === 'scholarship') {
          promises.push(fetchPendingCertificateRequests('scholarship'));
        }
        await Promise.all(promises);
        lastFetchTimeRef.current = Date.now();
      } catch (e) {
        console.error('Failed to refresh clerk data', e);
      } finally {
        activePromiseRef.current = null;
      }
    })();

    activePromiseRef.current = promise;
    return promise;
  }, [fetchClerk, fetchCollegeInfo, fetchFacultyData, fetchPendingProfileRequests, fetchPendingCertificateRequests, fetchAdmissionDrafts, fetchHODData, fetchStudentHistory]);

  const handleResume = useCallback(async (event) => {
    const now = Date.now();
    const isBfcacheRestore = event?.type === 'pageshow' && event.persisted;
    const isStuck = loading && !clerkData;

    // Check if we should revalidate
    const shouldReinit = isBfcacheRestore || isStuck;
    const throttleTime = 5000; // 5 seconds throttle
    const isThrottled = now - lastFetchTimeRef.current < throttleTime;

    if (!shouldReinit && isThrottled) {
      return;
    }

    if (activePromiseRef.current) {
      if (shouldReinit) {
        setLoading(true);
        setAreRequestsBootstrapping(true);
      }
      try {
        await activePromiseRef.current;
      } finally {
        setLoading(false);
        setAreRequestsBootstrapping(false);
      }
      return;
    }

    isInitializingRef.current = true;
    if (shouldReinit) {
      setLoading(true);
      setAreRequestsBootstrapping(true);
    }

    try {
      await refreshAllData();
    } catch (e) {
      console.error('Failed to revalidate clerk data on resume', e);
    } finally {
      setLoading(false);
      setAreRequestsBootstrapping(false);
      isInitializingRef.current = false;
    }
  }, [loading, clerkData, refreshAllData]);

  useEffect(() => {
    if (clerkData || isInitializingRef.current) return;

    let cancelled = false;
    isInitializingRef.current = true;

    const id = setTimeout(() => {
      const init = async () => {
        if (!clerkData) setLoading(true);
        setAreRequestsBootstrapping(true);
        try {
          await refreshAllData();
        } finally {
          if (!cancelled) {
            setLoading(false);
            setAreRequestsBootstrapping(false);
            isInitializingRef.current = false;
          }
        }
      };
      init();
    }, 0);

    return () => {
      cancelled = true;
      isInitializingRef.current = false;
      clearTimeout(id);
    };
  }, [refreshAllData, clerkData]);

  useEffect(() => {
    const onResume = (e) => {
      if (e && e.type === 'visibilitychange' && document.visibilityState !== 'visible') {
        return;
      }
      handleResume(e);
    };

    window.addEventListener('pageshow', onResume);
    document.addEventListener('visibilitychange', onResume);
    window.addEventListener('focus', onResume);

    if (loading && !clerkData && !isInitializingRef.current) {
      handleResume();
    }

    return () => {
      window.removeEventListener('pageshow', onResume);
      document.removeEventListener('visibilitychange', onResume);
      window.removeEventListener('focus', onResume);
    };
  }, [handleResume, loading, clerkData]);

  const handleRealtimeUpdate = useCallback((data) => {
    if (clerkData?.is_hod && data.payload.branch === clerkData.branch) {
      if (['TIMETABLE_CHANGED', 'ATTENDANCE_SAVED', 'SESSION_STARTED', 'SESSION_ENDED'].includes(data.type)) {
        console.log(`[HODSync] ${data.type} detected, refreshing...`);
        fetchHODData();
      }
    }
  }, [clerkData, fetchHODData]);

  return (
    <ClerkContext.Provider value={{
      clerkData,
      collegeInfo,
      setClerkData,
      loading,
      error,
      refreshClerkData: fetchClerk,
      facultyAssignments,
      facultyInterests,
      isLoadingFaculty,
      refreshFaculty: fetchFacultyData,
      pendingProfileRequests,
      pendingCertificateRequests,
      admissionDrafts,
      isLoadingRequests,
      areRequestsBootstrapping,
      refreshProfileRequests: fetchPendingProfileRequests,
      refreshCertificateRequests: fetchPendingCertificateRequests,
      refreshAdmissionDrafts: fetchAdmissionDrafts,
      refreshAllRequests,
      hodBranchData,
      isLoadingHOD,
      refreshHOD: fetchHODData,
      studentHistory,
      isLoadingHistory,
      refreshStudentHistory: fetchStudentHistory
    }}>
      <RealtimeListener onUpdate={handleRealtimeUpdate} enableNotifications />
      {children}
    </ClerkContext.Provider>
  );
}

export function useClerk() {
  const context = useContext(ClerkContext);
  if (context === undefined) {
    throw new Error('useClerk must be used within a ClerkProvider');
  }
  return context;
}

'use client';
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import toast from 'react-hot-toast';
import RealtimeListener from '@/components/RealtimeListener';
import { getPendingAttendance, savePendingAttendance, deletePendingAttendance } from '@/lib/idb-attendance';

const FacultyAttendanceContext = createContext(null);

export function FacultyAttendanceProvider({ assignment, children }) {
  const [selectedDate, setSelectedDate] = useState(null);
  const [selectedSession, setSelectedSession] = useState(1);
  const [baseStudents, setBaseStudents] = useState([]);
  const [attendanceStatusMap, setAttendanceStatusMap] = useState({});
  const [absentCountMap, setAbsentCountMap] = useState({});
  const [existingSessionsForSelectedDate, setExistingSessionsForSelectedDate] = useState([]);
  const [dayInfo, setDayInfo] = useState(null);
  const [dateValidation, setDateValidation] = useState({
    isValid: false,
    message: 'Select a WORKING day from the academic calendar.',
  });
  const [loading, setLoading] = useState(true);
  const [statusLoading, setStatusLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [attendanceCache, setAttendanceCache] = useState({});
  const [activeSession, setActiveSession] = useState(null);
  const [verifiedStudentIds, setVerifiedStudentIds] = useState(new Set());
  const [pendingSyncs, setPendingSyncs] = useState([]);

  // --- ACTIONS (useCallback) ---

  const fetchBaseStudents = useCallback(async () => {
    if (!assignment?.id) {
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const url = `/api/clerk/faculty/students?assignment_id=${assignment.id}&base=1`;
      const res = await fetch(url);
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to fetch students');

      const base = (data.data || []).map((s) => ({
        id: s.id,
        roll_no: s.roll_no,
        name: s.name,
      }));
      setBaseStudents(base);
      setAttendanceStatusMap({});
    } catch (error) {
      toast.error(error.message);
    } finally {
      setLoading(false);
    }
  }, [assignment]);

  const fetchActiveSession = useCallback(async () => {
    if (!assignment?.id) return;
    try {
      const res = await fetch(`/api/clerk/faculty/attendance/session?assignment_id=${assignment.id}`);
      const json = await res.json();
      if (res.ok && json.active) {
        setActiveSession(json.session);
      } else {
        setActiveSession(null);
      }
    } catch (e) {
      console.error('Failed to fetch active session:', e);
    }
  }, [assignment]);

  const fetchAttendanceStatus = useCallback(async (forcedDate, forcedSession, bypassCache = false) => {
    if (!assignment?.id) return;

    const dateToUse = forcedDate || selectedDate;
    const sessionToUse = forcedSession || selectedSession;

    if (!dateToUse && !activeSession) return;

    const cacheKey = `${dateToUse}-${sessionToUse}`;
    if (!bypassCache && !activeSession && dateToUse && attendanceCache[cacheKey]) {
      setAttendanceStatusMap(attendanceCache[cacheKey].statusMap || {});
      setExistingSessionsForSelectedDate(attendanceCache[cacheKey].sessions || []);
      return;
    }

    if (dateToUse) setStatusLoading(true);
    try {
      let url = `/api/clerk/faculty/attendance/status?assignment_id=${assignment.id}`;
      if (dateToUse) url += `&date=${encodeURIComponent(dateToUse)}&session=${encodeURIComponent(sessionToUse)}`;
      
      const res = await fetch(url);
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to fetch attendance status');

      const verifiedIds = new Set(data.verified_ids || []);
      setVerifiedStudentIds(verifiedIds);

      if (dateToUse) {
        const statusMap = (data.data || []).reduce((acc, r) => {
          acc[r.student_id] = r.status;
          return acc;
        }, {});

        verifiedIds.forEach(id => {
          if (!statusMap[id]) statusMap[id] = 'PRESENT';
        });

        const sessions = data.sessions || [];
        setAttendanceStatusMap(statusMap);
        setExistingSessionsForSelectedDate(sessions);

        if (!activeSession) {
          setAttendanceCache((prev) => ({
            ...prev,
            [cacheKey]: { statusMap, sessions },
          }));
        }
      }
    } catch (error) {
      if (dateToUse) toast.error(error.message);
    } finally {
      setStatusLoading(false);
    }
  }, [assignment, selectedDate, selectedSession, attendanceCache, activeSession]);

  const refreshPendingSyncs = useCallback(async () => {
    try {
      const pending = await getPendingAttendance();
      setPendingSyncs(pending || []);
    } catch (e) {
      console.error('Failed to fetch pending syncs:', e);
    }
  }, []);

  const syncOfflineAttendance = useCallback(async (idToSync = null) => {
    try {
      const allPending = await getPendingAttendance();
      const toSync = idToSync ? allPending.filter((p) => p.id === idToSync) : allPending;

      if (toSync.length === 0) return;

      setSubmitting(true);
      let successCount = 0;

      for (const item of toSync) {
        try {
          const res = await fetch('/api/clerk/faculty/attendance', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              assignment_id: item.assignment_id,
              date: item.date,
              session: item.session,
              attendance_data: item.attendance_data,
            }),
          });

          if (res.ok) {
            await deletePendingAttendance(item.id);
            successCount++;
          } else {
            const data = await res.json();
            throw new Error(data.error || 'Failed to sync record');
          }
        } catch (e) {
          toast.error(`Sync failed for ${item.date} Session ${item.session}: ${e.message}`);
        }
      }

      if (successCount > 0) {
        toast.success(`Successfully synced ${successCount} attendance records.`);
        await refreshPendingSyncs();
        fetchAttendanceStatus(null, null, true);
      }
    } catch (err) {
      console.error('Global Sync Error:', err);
    } finally {
      setSubmitting(false);
    }
  }, [refreshPendingSyncs, fetchAttendanceStatus]);

  const startSession = async () => {
    if (!assignment?.id) return;

    let latitude = null;
    let longitude = null;
    let accuracy = null;

    try {
      setSubmitting(true);

      if (navigator.geolocation) {
        toast.loading('Requesting location access...', { id: 'geo-loading' });
        try {
          const pos = await new Promise((resolve, reject) => {
            navigator.geolocation.getCurrentPosition(resolve, reject, { 
              enableHighAccuracy: true,
              timeout: 8000,
              maximumAge: 0
            });
          });
          latitude = pos.coords.latitude;
          longitude = pos.coords.longitude;
          accuracy = pos.coords.accuracy;
          toast.dismiss('geo-loading');
        } catch (geoErr) {
          toast.dismiss('geo-loading');
          console.warn('Geolocation failed, falling back to PIN-only:', geoErr);
          const proceed = window.confirm('GPS is blocked or unavailable (requires HTTPS on mobile). Start session with PIN-only security?');
          if (!proceed) throw new Error('Session cancelled by user.');
        }
      } else {
        const proceed = window.confirm('Your browser doesn\'t support GPS. Start session with PIN-only security?');
        if (!proceed) return;
      }

      toast.loading('Creating secure session...', { id: 'session-loading' });

      const res = await fetch('/api/clerk/faculty/attendance/session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          assignment_id: assignment.id,
          latitude,
          longitude,
          attendance_date: selectedDate,
          session_number: selectedSession
        }),
      });
      
      const json = await res.json();
      toast.dismiss('session-loading');

      if (!res.ok) throw new Error(json.error || 'Failed to start session');
      
      setActiveSession(json.session);
      toast.success('Attendance session started!');
    } catch (error) {
      toast.dismiss('geo-loading');
      toast.dismiss('session-loading');
      console.error('Start Session Error:', error);
      
      let msg = error.message;
      if (error.code === 1) msg = 'Location permission denied. Please enable location in your browser settings.';
      if (error.code === 2) msg = 'Location unavailable.';
      if (error.code === 3) msg = 'Location request timed out. Please try again.';
      
      toast.error(msg || 'Geolocation is required to start a session.');
    } finally {
      setSubmitting(false);
    }
  };

  const endSession = useCallback(async () => {
    if (!assignment?.id) return;
    try {
      setSubmitting(true);
      const res = await fetch(`/api/clerk/faculty/attendance/session?assignment_id=${assignment.id}`, {
        method: 'DELETE',
      });
      if (res.ok) {
        setActiveSession(null);
        toast.success('Session ended.');
      }
    } catch (error) {
      toast.error('Failed to end session');
    } finally {
      setSubmitting(false);
    }
  }, [assignment]);

  const handleManualRefresh = useCallback(() => {
    fetchAttendanceStatus(null, null, true);
  }, [fetchAttendanceStatus]);

  const setAttendanceStatus = useCallback((studentId, status) => {
    setAttendanceStatusMap((prev) => ({ ...prev, [studentId]: status }));
  }, []);

  const toggleAttendanceStatus = useCallback((studentId) => {
    setAbsentCountMap((prevStages) => {
      const currentStage = prevStages[studentId] || 0;
      let nextStage = currentStage + 1;
      
      if (nextStage > 7) nextStage = 4;

      const stageToStatus = {
        0: null,
        1: 'PRESENT',
        2: 'ABSENT',
        3: 'PRESENT',
        4: 'ABSENT',
        5: 'NCC',
        6: 'MEDICAL',
        7: 'PRESENT'
      };

      const nextStatus = stageToStatus[nextStage];

      setAttendanceStatusMap(prevStatus => ({
        ...prevStatus,
        [studentId]: nextStatus
      }));

      return { ...prevStages, [studentId]: nextStage };
    });
  }, []);

  const setAllAttendanceStatus = useCallback((status) => {
    setAttendanceStatusMap((prev) => {
      const next = { ...prev };
      const nextStages = { ...absentCountMap };
      
      baseStudents.forEach((s) => {
        next[s.id] = status;
        if (status === 'ABSENT') {
          nextStages[s.id] = 2;
        } else if (status === 'PRESENT') {
          nextStages[s.id] = 1;
        } else {
          nextStages[s.id] = 0;
        }
      });
      
      setAbsentCountMap(nextStages);
      return next;
    });
  }, [baseStudents, absentCountMap]);

  const handleSaveAttendance = useCallback(async () => {
    if (!assignment?.id) return;
    
    const previousStatusMap = { ...attendanceStatusMap };
    const previousCache = { ...attendanceCache };
    const previousActiveSession = activeSession;

    setSubmitting(true);
    try {
      if (!selectedDate || !dateValidation.isValid) {
        throw new Error('Select a valid WORKING day from the calendar.');
      }

      const attendanceData = baseStudents.map((s) => ({
        student_id: s.id,
        status: attendanceStatusMap[s.id] ?? null,
      }));

      const missing = attendanceData.filter(a => a.status === null);
      if (missing.length > 0) {
        throw new Error(`Please set attendance status for all students. (${missing.length} remaining)`);
      }

      toast.success('Attendance saved (Optimistic)', { id: 'attendance-save' });
      
      if (activeSession) {
        setActiveSession(null);
      }

      const cacheKey = `${selectedDate}-${selectedSession}`;
      setAttendanceCache((prev) => {
        const next = { ...prev };
        delete next[cacheKey];
        return next;
      });

      const res = await fetch('/api/clerk/faculty/attendance', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          assignment_id: assignment.id,
          date: selectedDate,
          session: selectedSession,
          attendance_data: attendanceData,
        }),
      }).catch(async (err) => {
        if (!navigator.onLine || err.message.includes('Failed to fetch')) {
          const payload = {
            assignment_id: assignment.id,
            subject_name: assignment.subject_name,
            date: selectedDate,
            session: selectedSession,
            attendance_data: attendanceData,
          };
          await savePendingAttendance(payload);
          await refreshPendingSyncs();
          throw new Error('OFFLINE_SAVED');
        }
        throw err;
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to save attendance');

      toast.success('Attendance synced with server', { id: 'attendance-save' });

      if (previousActiveSession && !activeSession) {
         // Session already handled
      } else if (activeSession) {
         await endSession();
      }

      await fetchAttendanceStatus(selectedDate, selectedSession, true);
    } catch (error) {
      if (error.message === 'OFFLINE_SAVED') {
        toast.success('Offline: Attendance saved to device. It will sync automatically when you are back online.', { duration: 5000 });
        setActiveSession(null);
        setSubmitting(false);
        return;
      }

      console.error('[AttendanceSaveRollback]', error);
      setAttendanceStatusMap(previousStatusMap);
      setAttendanceCache(previousCache);
      setActiveSession(previousActiveSession);
      
      toast.error(error.message, { id: 'attendance-save' });
    } finally {
      setSubmitting(false);
    }
  }, [assignment, baseStudents, attendanceStatusMap, dateValidation.isValid, fetchAttendanceStatus, selectedDate, selectedSession, activeSession, endSession, attendanceCache, refreshPendingSyncs]);

  const handleDeleteAttendance = useCallback(async () => {
    if (!assignment?.id) return;
    if (!selectedDate) {
      toast.error('No date selected');
      return;
    }

    if (!window.confirm(`Are you sure you want to delete attendance for Session ${selectedSession} on ${selectedDate}?`)) {
      return;
    }

    setSubmitting(true);
    try {
      const res = await fetch(
        `/api/clerk/faculty/attendance?assignment_id=${assignment.id}&date=${selectedDate}&session=${selectedSession}`,
        {
          method: 'DELETE',
        },
      );
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to delete attendance');

      toast.success('Attendance deleted successfully');

      const cacheKey = `${selectedDate}-${selectedSession}`;
      setAttendanceCache((prev) => {
        const next = { ...prev };
        delete next[cacheKey];
        return next;
      });

      await fetchAttendanceStatus();
      setSelectedSession(1);
    } catch (error) {
      toast.error(error.message);
    } finally {
      setSubmitting(false);
    }
  }, [assignment, fetchAttendanceStatus, selectedDate, selectedSession]);

  const handleCalendarSelect = useCallback((dateStr, info) => {
    setSelectedDate(dateStr);
    if (info) {
      setDayInfo(info);
      if (info.day_type === 'WORKING') {
        setDateValidation({ isValid: true, message: null });
      } else {
        setDateValidation({
          isValid: false,
          message: `Attendance cannot be marked. Reason: ${info.day_type}`,
        });
      }
    } else {
      setDayInfo(null);
      setDateValidation({
        isValid: false,
        message: 'Select a WORKING day from the academic calendar.',
      });
    }
  }, []);

  const handleRealtimeUpdate = useCallback((data) => {
    if (data.type === 'STUDENT_VERIFIED' && data.payload.assignment_id === assignment.id) {
      console.log('[AttendanceSync] Student verified, refreshing...');
      fetchAttendanceStatus();
    } else if (data.type === 'PROXY_ATTEMPTED' && data.payload.assignment_id === assignment.id) {
      const { attempting_roll_no, original_roll_no, original_student_id } = data.payload;
      
      toast.error(
        (t) => (
          <div className="flex flex-col gap-1 border-l-4 border-red-600 pl-2">
            <span className="font-black text-xs uppercase tracking-widest text-red-800">Security Breach Detected</span>
            <div className="text-[11px] font-bold text-gray-700 leading-tight">
              Student <span className="text-red-600">{original_roll_no}</span> attempted proxy for <span className="text-blue-700">{attempting_roll_no}</span>.
            </div>
            <div className="text-[9px] font-bold text-gray-500 uppercase mt-1">
              Action: {original_roll_no} marked as ABSENT.
            </div>
          </div>
        ),
        { 
          duration: 10000, 
          id: `proxy-${original_roll_no}`,
          style: {
            borderRadius: '0px',
            border: '1px solid #fee2e2',
            background: '#fff',
            boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)',
            padding: '12px'
          }
        }
      );

      setVerifiedStudentIds(prev => {
        const next = new Set(prev);
        next.delete(original_student_id);
        return next;
      });

      setAttendanceStatusMap(prev => ({
        ...prev,
        [original_student_id]: 'ABSENT'
      }));

      setAbsentCountMap(prev => ({
        ...prev,
        [original_student_id]: 2
      }));
    }
  }, [assignment.id, fetchAttendanceStatus]);

  // --- SYNCS (useEffect) ---

  useEffect(() => {
    const initSync = async () => {
      await refreshPendingSyncs();
    };
    initSync();

    const handleOnline = () => {
      toast.success('Back online! Checking for pending attendance...', { icon: '🔄' });
      syncOfflineAttendance();
    };

    window.addEventListener('online', handleOnline);
    return () => window.removeEventListener('online', handleOnline);
  }, [refreshPendingSyncs, syncOfflineAttendance]);

  useEffect(() => {
    const init = async () => {
      setSelectedDate(null);
      setSelectedSession(1);
      setAttendanceStatusMap({});
      setAbsentCountMap({});
      setExistingSessionsForSelectedDate([]);
      setDayInfo(null);
      setDateValidation({
        isValid: false,
        message: 'Select a WORKING day from the academic calendar.',
      });
      setAttendanceCache({});
      setActiveSession(null);

      await fetchBaseStudents();
      await fetchActiveSession();
    };
    init();
  }, [assignment, fetchBaseStudents, fetchActiveSession]);

  useEffect(() => {
    const fetchStatus = async () => {
      if (selectedDate) {
        await fetchAttendanceStatus();
      } else {
        setAttendanceStatusMap({});
        setAbsentCountMap({});
        setExistingSessionsForSelectedDate([]);
      }
    };
    fetchStatus();
  }, [selectedDate, selectedSession, fetchAttendanceStatus]);

  // --- DERIVED STATE (useMemo) ---

  const students = useMemo(
    () => baseStudents.map((s) => ({ ...s, status: attendanceStatusMap[s.id] ?? null })),
    [baseStudents, attendanceStatusMap],
  );

  const value = {
    assignment,
    selectedDate,
    setSelectedDate,
    selectedSession,
    setSelectedSession,
    baseStudents,
    attendanceStatusMap,
    setAttendanceStatus,
    toggleAttendanceStatus,
    setAllAttendanceStatus,
    existingSessionsForSelectedDate,
    dayInfo,
    dateValidation,
    loading,
    statusLoading,
    submitting,
    students,
    handleManualRefresh,
    handleSaveAttendance,
    handleDeleteAttendance,
    handleCalendarSelect,
    activeSession,
    startSession,
    endSession,
    verifiedStudentIds,
    fetchAttendanceStatus,
    pendingSyncs,
    syncOfflineAttendance
  };

  return (
    <FacultyAttendanceContext.Provider value={value}>
      <RealtimeListener onUpdate={handleRealtimeUpdate} />
      {children}
    </FacultyAttendanceContext.Provider>
  );
}

export function useFacultyAttendance() {
  const context = useContext(FacultyAttendanceContext);
  if (!context) {
    throw new Error('useFacultyAttendance must be used within a FacultyAttendanceProvider');
  }
  return context;
}

'use client';

import { createContext, useContext, useEffect, useState } from 'react';
import { useStudent } from '@/context/StudentContext';

const STORAGE_COUNT_KEY = 'profileStatusBarCount';
const STORAGE_SEEN_ID_KEY = 'profileStatusBarSeenRequestId';
const STORAGE_SEEN_STATUS_KEY = 'profileStatusBarSeenStatus';

export const ProfileActivityContext = createContext(null);

export function ProfileActivityProvider({ children }) {
  const { studentData } = useStudent();
  const rollno = studentData?.student?.roll_no;

  const [latestRequest, setLatestRequest] = useState(null);
  const [scholarshipThumbUpdate, setScholarshipThumbUpdate] = useState({ active: false });
  const [scholarshipHardcopyPending, setScholarshipHardcopyPending] = useState({ active: false });
  const [scholarshipApplicationReceived, setScholarshipApplicationReceived] = useState({ active: false });
  const [scholarshipApplicationsOpen, setScholarshipApplicationsOpen] = useState({ active: false });
  const [dismissCount, setDismissCount] = useState(0);
  const [seenRequestId, setSeenRequestId] = useState(null);
  const [seenStatus, setSeenStatus] = useState(null);

  useEffect(() => {
    const id = setTimeout(() => {
      try {
        setDismissCount(Number(localStorage.getItem(STORAGE_COUNT_KEY) || '0'));
        setSeenRequestId(localStorage.getItem(STORAGE_SEEN_ID_KEY) || null);
        setSeenStatus(localStorage.getItem(STORAGE_SEEN_STATUS_KEY) || null);
      } catch (error) {
        console.error('Profile activity storage hydrate error:', error);
      }
    }, 0);

    return () => clearTimeout(id);
  }, []);

  // Latest certificate request (fetch once per rollno)
  useEffect(() => {
    let mounted = true;

    if (!rollno) {
      const id = setTimeout(() => {
        setLatestRequest(null);
      }, 0);
      return () => {
        mounted = false;
        clearTimeout(id);
      };
    }

    const fetchData = async () => {
      try {
        const res = await fetch(`/api/student/latest-request?rollno=${encodeURIComponent(rollno)}`);
        if (!mounted) return;

        if (res.ok) {
          const data = await res.json();
          const req = data?.latestRequest || null;

          if (mounted) {
            setLatestRequest(req);

            const incomingId = req?.request_id ? String(req.request_id) : null;
            const incomingStatus = req?.status ? String(req.status) : null;

            if ((incomingId && incomingId !== seenRequestId) || (incomingStatus && incomingStatus !== seenStatus)) {
              setDismissCount(0);
              setSeenRequestId(incomingId);
              setSeenStatus(incomingStatus);

              try {
                localStorage.setItem(STORAGE_COUNT_KEY, '0');
                if (incomingId) localStorage.setItem(STORAGE_SEEN_ID_KEY, incomingId);
                if (incomingStatus) localStorage.setItem(STORAGE_SEEN_STATUS_KEY, incomingStatus);
              } catch (e) {
                console.error('Storage error:', e);
              }
            }
          }
        } else {
          if (mounted) setLatestRequest(null);
        }
      } catch (e) {
        if (mounted) setLatestRequest(null);
      }
    };

    fetchData();

    return () => {
      mounted = false;
    };
    // We intentionally depend only on rollno so this fetch runs once per student session.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rollno]);

  // Student activity (scholarship thumb + hardcopy notifications)
  useEffect(() => {
    let mounted = true;
    if (!rollno) return () => {
      mounted = false;
    };

    const fetchActivity = async () => {
      try {
        const res = await fetch('/api/student/activity');
        if (!mounted) return;
        if (!res.ok) {
          setScholarshipThumbUpdate({ active: false });
          setScholarshipHardcopyPending({ active: false });
          setScholarshipApplicationReceived({ active: false });
          setScholarshipApplicationsOpen({ active: false });
          return;
        }
        const data = await res.json();
        if (!mounted) return;
        setScholarshipThumbUpdate(data?.scholarshipThumbUpdate || { active: false });
        setScholarshipHardcopyPending(data?.scholarshipHardcopyPending || { active: false });
        setScholarshipApplicationReceived(data?.scholarshipApplicationReceived || { active: false });
        setScholarshipApplicationsOpen(data?.scholarshipApplicationsOpen || { active: false });
      } catch (e) {
        if (mounted) {
          setScholarshipThumbUpdate({ active: false });
          setScholarshipHardcopyPending({ active: false });
          setScholarshipApplicationReceived({ active: false });
          setScholarshipApplicationsOpen({ active: false });
        }
      }
    };

    fetchActivity();
    return () => {
      mounted = false;
    };
  }, [rollno]);

  const incrementVisit = () => {
    try {
      const next = Number(localStorage.getItem(STORAGE_COUNT_KEY) || '0') + 1;
      localStorage.setItem(STORAGE_COUNT_KEY, String(next));
      setDismissCount(next);
    } catch (e) { /* empty */ }
  };

  const dismiss = () => {
    try {
      const next = Number(localStorage.getItem(STORAGE_COUNT_KEY) || '0') + 1;
      localStorage.setItem(STORAGE_COUNT_KEY, String(next));
      setDismissCount(next);
    } catch (e) { /* empty */ }
  };

  const reset = () => {
    try {
      localStorage.removeItem(STORAGE_COUNT_KEY);
      localStorage.removeItem(STORAGE_SEEN_ID_KEY);
      localStorage.removeItem(STORAGE_SEEN_STATUS_KEY);
    } catch (e) { /* empty */ }
    setDismissCount(0);
    setSeenRequestId(null);
    setSeenStatus(null);
  };

  const value = {
    latestRequest,
    dismissCount,
    incrementVisit,
    dismiss,
    reset,
    scholarshipThumbUpdate,
    scholarshipHardcopyPending,
    scholarshipApplicationReceived,
    scholarshipApplicationsOpen,
  };

  return (
    <ProfileActivityContext.Provider value={value}>
      {children}
    </ProfileActivityContext.Provider>
  );
}

