      WHERE qualifying_exam = 'EAMCET' OR qualifying_exam = 'TS EAMCET'
    `);
    console.log(`- Updated ${res3.affectedRows} rows for EAMCET/TS EAMCET.`);

    const [res4] = await connection.execute(`
      UPDATE student_academic_background 
      SET qualifying_exam = 'TG ECET' 
      WHERE qualifying_exam = 'ECET' OR qualifying_exam = 'TS ECET'
    `);
    console.log(`- Updated ${res4.affectedRows} rows for ECET/TS ECET.`);

    // 3. Update college_info JSON keys
    console.log('Updating college_info entrance_codes...');
    const [rows] = await connection.execute('SELECT id, entrance_codes FROM college_info');
    for (const row of rows) {
      if (row.entrance_codes) {
        let codes;
        try {
            codes = typeof row.entrance_codes === 'string' ? JSON.parse(row.entrance_codes) : row.entrance_codes;
        } catch (e) {
            console.error(`Failed to parse entrance_codes for ID ${row.id}:`, row.entrance_codes);
            continue;
        }

        if (!codes) continue;

        const newCodes = {};
        // Preserve existing values but use new keys if old ones exist
        if (codes.pgecet) newCodes.tgpgecet = codes.pgecet;
        else if (codes.tgpgecet) newCodes.tgpgecet = codes.tgpgecet;

        if (codes.eapcet) newCodes.tgeapcet = codes.eapcet;
        else if (codes.tgeapcet) newCodes.tgeapcet = codes.tgeapcet;

        if (codes.ecet) newCodes.tgecet = codes.ecet;
        else if (codes.tgecet) newCodes.tgecet = codes.tgecet;
        
        // Also check for any other keys just in case
        Object.keys(codes).forEach(key => {
            if (!['pgecet', 'eapcet', 'ecet', 'tgpgecet', 'tgeapcet', 'tgecet'].includes(key)) {
                newCodes[key] = codes[key];
            }
        });

        if (Object.keys(newCodes).length > 0) {
           await connection.execute('UPDATE college_info SET entrance_codes = ? WHERE id = ?', [JSON.stringify(newCodes), row.id]);
           console.log(`- Updated entrance_codes for college_info ID ${row.id}.`);
        }
      }
    }

    console.log('✅ Database update completed successfully!');
  } catch (error) {
    console.error('❌ Database update failed:', error);
    process.exit(1);
  } finally {
    await connection.end();
  }
}

renameExams();

import crypto from 'crypto';
import { db } from './index.js';
import { students as studentsTable, studentPersonalDetails } from './schema.js';
import { eq, isNotNull } from 'drizzle-orm';
import logger from '../lib/logger.js';

/**
 * PRODUCTION HARDENING: Encryption Key Rotation Utility
 * 
 * Usage:
 * 1. Set OLD_ENCRYPTION_KEY in your .env
 * 2. Set new ENCRYPTION_KEY in your .env
 * 3. Run: npm run db:rotate-keys
 */

const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 12;

function decryptOld(text, key) {
  if (!text) return null;
  try {
    const parts = text.split(':');
    const iv = Buffer.from(parts.shift(), 'hex');
    const authTag = Buffer.from(parts.shift(), 'hex');
    const encryptedText = Buffer.from(parts.join(':'), 'hex');
    const decipher = crypto.createDecipheriv(ALGORITHM, Buffer.from(key, 'hex'), iv);
    decipher.setAuthTag(authTag);
    let decrypted = decipher.update(encryptedText, 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    return decrypted;
  } catch (err) {
    return null; // Failed to decrypt with old key
  }
}

function encryptNew(text, key) {
  if (!text) return null;
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv(ALGORITHM, Buffer.from(key, 'hex'), iv);
  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag().toString('hex');
  return `${iv.toString('hex')}:${authTag}:${encrypted}`;
}

async function rotateKeys() {
  const oldKey = process.env.OLD_ENCRYPTION_KEY;
  const newKey = process.env.ENCRYPTION_KEY;

  if (!oldKey || !newKey || oldKey === newKey) {
    console.error('❌ Error: Both OLD_ENCRYPTION_KEY and ENCRYPTION_KEY must be set and different.');
    process.exit(1);
  }

  console.log('--- STARTING ENCRYPTION KEY ROTATION ---');

  try {
    await db.transaction(async (tx) => {
      // 1. Rotate Student Mobile Numbers
      const students = await tx.select({ id: studentsTable.id, mobile: studentsTable.mobile })
        .from(studentsTable)
        .where(isNotNull(studentsTable.mobile));

      console.log(`📡 Processing ${students.length} student mobile numbers...`);
      for (const s of students) {
        const decrypted = decryptOld(s.mobile, oldKey);
        if (decrypted) {
          const reEncrypted = encryptNew(decrypted, newKey);
          await tx.update(studentsTable)
            .set({ mobile: reEncrypted })
            .where(eq(studentsTable.id, s.id));
        }
      }

      // 2. Rotate Personal Details (Aadhaar, Guardian Mobile)
      const details = await tx.select({ 
        id: studentPersonalDetails.id, 
        aadhaar_no: studentPersonalDetails.aadhaar_no,
        guardian_mobile: studentPersonalDetails.guardian_mobile
      })
      .from(studentPersonalDetails);

      console.log(`📡 Processing ${details.length} personal detail records...`);
      for (const d of details) {
        const updateObj = {};
        
        if (d.aadhaar_no) {
          const decryptedAadhaar = decryptOld(d.aadhaar_no, oldKey);
          if (decryptedAadhaar) updateObj.aadhaar_no = encryptNew(decryptedAadhaar, newKey);
        }

        if (d.guardian_mobile) {
          const decryptedGuardian = decryptOld(d.guardian_mobile, oldKey);
          if (decryptedGuardian) updateObj.guardian_mobile = encryptNew(decryptedGuardian, newKey);
        }

        if (Object.keys(updateObj).length > 0) {
          await tx.update(studentPersonalDetails)
            .set(updateObj)
            .where(eq(studentPersonalDetails.id, d.id));
        }
      }
    });

    console.log('✅ KEY ROTATION SUCCESSFUL');
    console.log('⚠️ Remember to remove OLD_ENCRYPTION_KEY from your environment variables.');
  } catch (error) {
    logger.error('[KEY_ROTATION_ERROR] Operation failed:', error.message);
    console.error('❌ Key rotation failed. Transaction rolled back.');
    process.exit(1);
  }
}

rotateKeys()
  .then(() => process.exit(0))
  .catch((err) => {
    console.error(err);
    process.exit(1);
  });

'use client';
import { useState } from 'react';
import toast from 'react-hot-toast';

export default function useEmailVerification({ rollno, newEmail, setEmail, originalEmail, isPasswordSet, openSetPasswordModal, refreshData }) {
  const [otp, setOtp] = useState('');
  const [isOtpSent, setIsOtpSent] = useState(false);
  const [isOtpVerified, setIsOtpVerified] = useState(false);
  const [isVerifying, setIsVerifying] = useState(false);

  const handleSendOtp = async () => {
    const isEmailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(newEmail || '');
    if (!isEmailValid) {
      toast.error('Please enter a valid email address.');
      return;
    }

    if (newEmail && newEmail !== originalEmail) {
      // client-side uniqueness check
      try {
        const uniquenessRes = await fetch(`/api/student/check-email-uniqueness?email=${encodeURIComponent(newEmail)}&currentRollno=${rollno}`);
        const uniquenessData = await uniquenessRes.json();
        if (!uniquenessData.isUnique) {
          toast.error(uniquenessData.error || uniquenessData.message || 'This email is already in use.');
          return;
        }
      } catch (e) {
        // ignore, server will validate
      }
    }

    setIsVerifying(true);
    try {
      const res = await fetch('/api/student/send-update-email-otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rollno, email: newEmail }),
      });
      const data = await res.json();
      if (res.ok) {
        toast.success(data.message);
        setIsOtpSent(true);
      } else {
        toast.error(data.error || data.message || 'Please try again after 15 minutes.');
      }
    } catch (error) {
      toast.error('Network error. Please try again.');
    } finally {
      setIsVerifying(false);
    }
  };

  const handleVerifyOtp = async () => {
    setIsVerifying(true);
    try {
      const res = await fetch('/api/student/verify-update-email-otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rollno, otp, email: newEmail }),
      });
      const data = await res.json();
      if (res.ok) {
        toast.success(data.message);
        if (!isPasswordSet && openSetPasswordModal) {
          openSetPasswordModal(true);
        } else {
          setIsOtpVerified(true);
          setEmail(newEmail);
          refreshData && refreshData();
        }
      } else {
        toast.error(data.error || data.message || 'OTP verification failed.');
      }
    } catch (error) {
      toast.error('Network error. Please try again.');
    } finally {
      setIsVerifying(false);
    }
  };

  return {
    otp,
    setOtp,
    isOtpSent,
    isOtpVerified,
    isVerifying,
    handleSendOtp,
    handleVerifyOtp,
  };
}

'use client';
import { useState, useEffect, useCallback } from 'react';
import toast from 'react-hot-toast';

export default function usePasswordSetup(rollno) {
  const [isPasswordSet, setIsPasswordSet] = useState(true);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordSaving, setPasswordSaving] = useState(false);
  const [showSetPasswordModal, setShowSetPasswordModal] = useState(false);

  const checkPasswordStatus = useCallback(async () => {
    try {
      const passRes = await fetch(`/api/student/set-password?rollno=${rollno}`);
      if (passRes.ok) {
        const passData = await passRes.json();
        setIsPasswordSet(passData.isPasswordSet);
      }
    } catch (e) {
      console.error('Error checking password status', e);
    }
  }, [rollno]);

  useEffect(() => { 
    const id = setTimeout(() => {
      if (rollno) {
        checkPasswordStatus();
      }
    }, 0);
    return () => clearTimeout(id);
  }, [rollno, checkPasswordStatus]);

  const handlePasswordSave = async () => {
    if (newPassword !== confirmPassword) {
      toast.error('Passwords do not match');
      return false;
    }
    if (newPassword.length < 6) {
      toast.error('Password must be at least 6 characters long');
      return false;
    }
    setPasswordSaving(true);
    try {
      const res = await fetch('/api/student/set-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rollno, password: newPassword }),
      });
      const data = await res.json();
      if (res.ok) {
        toast.success('Password set successfully! Please use this for future logins.');
        setIsPasswordSet(true);
        setNewPassword('');
        setConfirmPassword('');
        setShowSetPasswordModal(false);
        return true;
      } else {
        toast.error(data.error || 'Failed to set password');
        return false;
      }
    } catch (e) {
      toast.error('Network error');
      return false;
    } finally {
      setPasswordSaving(false);
    }
  };

  return {
    isPasswordSet,
    newPassword,
    setNewPassword,
    confirmPassword,
    setConfirmPassword,
    passwordSaving,
    showSetPasswordModal,
    setShowSetPasswordModal,
    handlePasswordSave,
    checkPasswordStatus,
  };
}

'use client';
import { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import useProfileImage from './useProfileImage';

export default function useProfileEdit(studentData = null, refreshData = () => {}) {
  const [isEditing, setIsEditing] = useState(false);
  const [mobile, setMobile] = useState('');
  const [email, setEmail] = useState('');
  const [contactAddress, setContactAddress] = useState('');
  const [permanentAddress, setPermanentAddress] = useState('');
  const [originalMobile, setOriginalMobile] = useState('');
  const [originalEmail, setOriginalEmail] = useState('');
  const [originalContactAddress, setOriginalContactAddress] = useState('');
  const [originalPermanentAddress, setOriginalPermanentAddress] = useState('');
  const [photoChanged, setPhotoChanged] = useState(false);
  const [photoProcessing, setPhotoProcessing] = useState(false);

  const profileImage = useProfileImage(studentData?.student?.pfp || null);

  useEffect(() => {
    const id = setTimeout(() => {
      if (studentData) {
        setMobile(studentData.student.mobile || '');
        setEmail(studentData.student.email || '');
        setContactAddress(studentData.student.personal_details?.contact_address || '');
        setPermanentAddress(studentData.student.personal_details?.permanent_address || '');
        setOriginalMobile(studentData.student.mobile || '');
        setOriginalEmail(studentData.student.email || '');
        setOriginalContactAddress(studentData.student.personal_details?.contact_address || '');
        setOriginalPermanentAddress(studentData.student.personal_details?.permanent_address || '');
      }
    }, 0);

    return () => clearTimeout(id);
  }, [studentData]);

  const sanitizeDigits = (val, maxLen = 12) => {
    if (val == null) return '';
    return String(val).replace(/\D/g, '').slice(0, maxLen);
  };

  const handleSave = async (rollno) => {
    if (profileImage.previewPhoto && !photoChanged) setPhotoChanged(true);
    if (profileImage.previewPhoto && photoChanged) {
      setPhotoProcessing(true);
      try {
        const response = await fetch('/api/student/upload-photo', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ roll_no: rollno, pfp: profileImage.previewPhoto }),
        });
        const result = await response.json();
        if (!response.ok) {
          toast.error(result.message || 'Photo update failed. Try again.');
          setPhotoProcessing(false);
          return false;
        }
        profileImage.setPreviewPhoto(null);
        setPhotoChanged(false);
      } catch (e) {
        toast.error('Network error. Please try again.');
        setPhotoProcessing(false);
        return false;
      } finally {
        setPhotoProcessing(false);
      }
    }

    try {
      const response = await fetch('/api/student/update-profile', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          rollno, 
          phone: sanitizeDigits(mobile, 12), 
          contact_address: contactAddress, 
          permanent_address: permanentAddress 
        }),
      });
      const result = await response.json();
      if (response.ok) {
        toast.success('Profile updated successfully!');
        setIsEditing(false);
        setOriginalMobile(sanitizeDigits(mobile, 12));
        setOriginalContactAddress(contactAddress);
        setOriginalPermanentAddress(permanentAddress);
        setOriginalEmail(email);
        setPhotoChanged(false);
        refreshData();
        return true;
      } else {
        toast.error(result.error || 'Failed to update profile.');
        return false;
      }
    } catch (error) {
      toast.error('Network error. Please try again.');
      return false;
    }
  };

  return {
    isEditing,
    setIsEditing,
    mobile,
    setMobile,
    email,
    setEmail,
    contactAddress,
    setContactAddress,
    permanentAddress,
    setPermanentAddress,
    originalMobile,
    originalEmail,
    originalContactAddress,
    originalPermanentAddress,
    sanitizeDigits,
    handleSave,
    photoChanged,
    setPhotoChanged,
    photoProcessing,
    profileImage,
  };
}

'use client';
import { useState, useRef } from 'react';
import toast from 'react-hot-toast';

export default function useProfileImage(initialSrc = null) {
  const [imageLoading, setImageLoading] = useState(true);
  const [previewPhoto, setPreviewPhoto] = useState(null);
  const [imagePreviewOpen, setImagePreviewOpen] = useState(false);
  const [imagePreviewSrc, setImagePreviewSrc] = useState(null);
  const fileInputRef = useRef(null);

  const handlePhotoChange = (e) => {
    const file = e?.target?.files?.[0];
    if (file) {
      if (!['image/jpeg', 'image/png', 'image/jpg'].includes(file.type)) {
        toast.error('Only JPG, JPEG, and PNG files are allowed.');
        return;
      }
      if (file.size > 1 * 1024 * 1024) {
        toast.error('File size must be less than 1MB.');
        return;
      }

      const reader = new FileReader();
      reader.onload = () => {
        setPreviewPhoto(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  return {
    imageLoading,
    setImageLoading,
    previewPhoto,
    setPreviewPhoto,
    imagePreviewOpen,
    setImagePreviewOpen,
    imagePreviewSrc,
    setImagePreviewSrc,
    fileInputRef,
    handlePhotoChange,
  };
}

import { NextResponse } from 'next/server';
import { cookies, headers } from 'next/headers';
import { verifyJwt } from './auth';
import { db } from '@/db';
import { auditLogs } from '@/db/schema';
import logger from './logger';
import { z } from 'zod';
import { getNow } from './clock';

/**
 * Standard API response helper
 */
export function apiResponse(data, status = 200) {
  return NextResponse.json(data, { status });
}

/**
 * Standard API error response helper
 */
export function apiError(message, status = 500, details = null) {
  const response = { error: message };
  if (details) response.details = details;
  return NextResponse.json(response, { status });
}

/**
 * Audit log helper
 * @param {Request} req The incoming request object
 * @param {Object} data Audit data (userId, userType, action, targetId, targetType, before, after)
 */
export async function logAudit(req, { userId, userType, action, targetId, targetType, before, after }) {
  try {
    const ip = req.headers.get('x-forwarded-for')?.split(',')[0] || '127.0.0.1';
    const userAgent = req.headers.get('user-agent') || 'Unknown Device';

    await db.insert(auditLogs).values({
      user_id: userId || null,
      user_type: userType || 'system',
      action: action,
      target_id: targetId ? String(targetId) : null,
      target_type: targetType || null,
      payload_before: before || null,
      payload_after: after || null,
      ip_address: ip,
      user_agent: userAgent,
    });
  } catch (error) {
    // We log the error but don't fail the main request if audit fails
    logger.error(error, '[AUDIT_LOG_ERROR]');
  }
}

/**
 * Unified API Handler Wrapper
 * Handles: Auth, Validation, Errors, and Telemetry
 * @param {Object} options 
 * @param {Function} options.handler - The core business logic (req, { data, user }) => Promise
 * @param {z.ZodSchema} [options.schema] - Optional Zod schema for request body validation
 * @param {string|string[]} [options.auth] - Optional role(s) required (e.g., 'student', ['admin', 'clerk'])
 * @param {Object} [options.audit] - Optional audit logging configuration
 */
export function wrapHandler({ handler, schema, auth, audit }) {
  return async (req, context) => {
    const start = Date.now();
    const traceId = crypto.randomUUID();
    const ip = req.headers.get('x-forwarded-for')?.split(',')[0] || '127.0.0.1';
    const userAgent = req.headers.get('user-agent') || 'Unknown';
    const method = req.method;
    const url = req.nextUrl.pathname;

    return logger.runWithContext({ traceId }, async () => {
      try {
        let user = null;
        let validatedData = {};

        // 1. Authentication Check
        if (auth) {
          const roles = Array.isArray(auth) ? auth : [auth];
          // Try each allowed role until one succeeds
          for (const role of roles) {
            user = await getAuthUser(role);
            if (user) break;
          }
          
          if (!user) {
            return apiError('Unauthorized', 401);
          }
        }

        // 2. Input Validation (Body only for now, can extend to query params)
        if (schema && ['POST', 'PUT', 'PATCH'].includes(method)) {
          try {
            const body = await req.json();
            validatedData = schema.parse(body);
          } catch (err) {
            if (err instanceof z.ZodError) {
              return apiError(err.errors?.[0]?.message || 'Invalid input data', 400);
            }
            if (err instanceof SyntaxError) {
              return apiError('Malformed JSON body', 400);
            }
            throw err;
          }
        }

        // 3. Execute Handler
        const result = await handler(req, { data: validatedData, user, context, ip, userAgent });

        // 4. Handle Response
        const response = result instanceof NextResponse ? result : apiResponse(result);

        // 5. Inject Trace ID into headers for debugging
        response.headers.set('x-trace-id', traceId);

        // 6. Audit Logging (If successful and configured)
        if (audit && response.status >= 200 && response.status < 300) {
          // Normalize role for enum compliance
          const rawRole = user?.role || 'student';
          let normalizedType = 'student';
          if (rawRole === 'admin') normalizedType = 'admin';
          else if (rawRole.toLowerCase().includes('clerk') || ['faculty', 'hod', 'principal'].includes(rawRole)) normalizedType = 'clerk';

          // Run audit in background to not block response
          logAudit(req, {
            userId: user?.id || user?.student_id || user?.clerkId,
            userType: normalizedType,
            action: audit.action,
            targetId: audit.getTargetId ? audit.getTargetId(validatedData, result) : null,
            before: audit.getBefore ? await audit.getBefore(validatedData) : null,
            after: audit.getAfter ? await audit.getAfter(validatedData, result) : null
          }).catch(err => logger.error(err, '[AUDIT_FAILED]'));
        }

        // 6. Success Telemetry & Performance Profiling
        const duration = Date.now() - start;
        const logData = { method, url, status: response.status, duration, ip };
        
        if (duration > 500) {
          logger.warn(logData, '[API_SLOW_PERFORMANCE]');
        } else {
          logger.info(logData, '[API_SUCCESS]');
        }

        return response;

      } catch (error) {
        const duration = Date.now() - start;
        
        // Handle known service errors
        if (error.status && error.message) {
          logger.warn({ method, url, status: error.status, duration, ip, msg: error.message }, '[API_EXPECTED_ERROR]');
          return apiError(error.message, error.status);
        }

        // Handle Database errors (Drizzle/MySQL)
        if (error.code === 'ER_DUP_ENTRY') {
          return apiError('Duplicate entry detected', 409);
        }

        // Final fallback
        logger.error({ method, url, duration, ip, err: error.message, stack: error.stack }, '[API_CRASH]');
        return apiError('An internal server error occurred', 500, process.env.NODE_ENV === 'development' ? error.message : null);
      }
    });
  };
}

/**
 * Authentication helper to get user from session cookies or middleware-injected headers
 */
export async function getAuthUser(role = null) {
  try {
    const cookieStore = await cookies();
    const reqHeaders = await headers();
    let token = null;
    let expectedRole = role;

    // Prioritize middleware-injected headers for silent refresh compatibility
    if (role === 'admin') {
      token = reqHeaders.get('x-admin-auth') || cookieStore.get('admin_auth')?.value;
    } else if (role === 'clerk') {
      token = reqHeaders.get('x-clerk-auth') || cookieStore.get('clerk_auth')?.value;
    } else if (role === 'student') {
      token = reqHeaders.get('x-student-auth') || cookieStore.get('student_auth')?.value;
    } else {
      // Try to detect role from available sources
      token = reqHeaders.get('x-admin-auth') || reqHeaders.get('x-clerk-auth') || reqHeaders.get('x-student-auth') ||
              cookieStore.get('admin_auth')?.value || cookieStore.get('clerk_auth')?.value || cookieStore.get('student_auth')?.value;
    }

    if (!token) return null;

    const payload = await verifyJwt(token, process.env.JWT_SECRET);
    
    // NOTE: Redundant silent refresh logic removed. 
    // The middleware (proxy.js) now authoritatively handles silent refresh 
    // and injects the new token into the request headers.

    if (!payload) return null;

    // Optional role validation
    if (expectedRole) {
      const actualRole = payload.role;
      const isStudent = actualRole === 'student' || !!payload.roll_no;
      const isClerk = ['admission', 'scholarship', 'faculty', 'clerk'].includes(actualRole);

      if (expectedRole === 'student') {
        if (!isStudent) return null;
      } else if (expectedRole === 'clerk') {
        if (!isClerk) return null;
      } else {
        if (actualRole !== expectedRole) return null;
      }
    }

    return payload;
  } catch (error) {
    console.error('Auth check failed:', error);
    return null;
  }
}

/**
 * Middleware-like check for API routes
 */
export async function withAuth(role, handler) {
  const user = await getAuthUser(role);
  if (!user) {
    return apiError('Unauthorized', 401);
  }
  return handler(user);
}

import { SignJWT, jwtVerify } from 'jose';
import crypto from 'crypto';
import { db } from '@/db';
