let pool;

export function getDb() {
  if (!pool) {
    const poolConfig = {
      host: process.env.DB_HOST,
      user: process.env.DB_USER,
      password: process.env.DB_PASSWORD,
      database: process.env.DB_DATABASE,
      port: process.env.DB_PORT || 3306,
      dateStrings: true, // Prevent timezone conversion issues
      waitForConnections: true,
      connectionLimit: 3, // Increased to 3 to support concurrent queries in hot paths
      queueLimit: 0,
      // PRODUCTION HARDENING (Serverless Optimized):
      enableKeepAlive: true,
      keepAliveInitialDelay: 10000,
      idleTimeout: 30000, // Reduced to 30s to release connections faster in serverless
      maxIdle: 0,
    };

    // TiDB Cloud and many production databases require SSL
    if (process.env.DB_SSL === 'true' || (process.env.DB_HOST && process.env.DB_HOST.includes('tidbcloud.com'))) {
      poolConfig.ssl = {
        minVersion: 'TLSv1.2',
        rejectUnauthorized: true,
      };
      console.log('[DB] SSL/TLS Encryption enabled for database connection.');
    }

    pool = mysql.createPool(poolConfig);
  }
  return pool;
}

/**
 * Executes a SQL query with automatic retry logic for connection resets (ECONNRESET)
 */
export async function query(sql, params, retries = 2) {
  const db = getDb();
  
  // PERMANENT FIX: Ensure no 'undefined' values are passed as bind parameters.
  // mysql2 throws an error if a parameter is undefined; we convert them to null.
  const sanitizedParams = params ? params.map(p => p === undefined ? null : p) : params;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const [rows] = await db.execute(sql, sanitizedParams);
      return rows;
    } catch (error) {
      const isConnectionError = error.code === 'ECONNRESET' || error.code === 'PROTOCOL_CONNECTION_LOST';
      
      if (isConnectionError && attempt < retries) {
        console.warn(`[DB] Connection reset detected. Retrying attempt ${attempt + 1}/${retries}...`);
        // Add a tiny delay before retrying
        await new Promise(resolve => setTimeout(resolve, 500 * (attempt + 1)));
        continue;
      }
      
      // If it's not a connection reset or we're out of retries, throw the error
      console.error(`[DB_ERROR] Query failed after ${attempt + 1} attempts:`, error.message);
      throw error;
    }
  }
}

import crypto from 'crypto';

const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 12; // Recommended for GCM

/**
 * Encrypts plain text using AES-256-GCM.
 */
export function encrypt(text) {
  if (!text) return null;
  
  const encryptionKey = process.env.ENCRYPTION_KEY;
  if (!encryptionKey || encryptionKey.length !== 64) {
    throw new Error('ENCRYPTION_KEY must be a 64-character hex string (32 bytes).');
  }

  const key = Buffer.from(encryptionKey, 'hex');
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
  
  let encrypted = cipher.update(String(text), 'utf8', 'hex');
  encrypted += cipher.final('hex');
  
  const tag = cipher.getAuthTag();
  
  // Format: iv:tag:encrypted
  return `${iv.toString('hex')}:${tag.toString('hex')}:${encrypted}`;
}

/**
 * Decrypts a string encrypted by the encrypt function above.
 */
export function decrypt(encryptedText) {
  if (!encryptedText) return null;
  
  const parts = String(encryptedText).split(':');
  if (parts.length !== 3) return encryptedText;

  try {
    const encryptionKey = process.env.ENCRYPTION_KEY;
    if (!encryptionKey) throw new Error('ENCRYPTION_KEY missing');

    const [ivHex, tagHex, contentHex] = parts;
    const key = Buffer.from(encryptionKey, 'hex');
    const iv = Buffer.from(ivHex, 'hex');
    const tag = Buffer.from(tagHex, 'hex');
    
    const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
    decipher.setAuthTag(tag);
    
    let decrypted = decipher.update(contentHex, 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    
    return decrypted;
  } catch (error) {
    return encryptedText;
  }
}

/**
 * Generates a one-way deterministic hash for indexing/searching encrypted data.
 * Uses a separate key (or same key with salt) to prevent correlation.
 */
export function hashForIndex(text) {
  if (!text) return null;
  
  const encryptionKey = process.env.ENCRYPTION_KEY;
  if (!encryptionKey) throw new Error('ENCRYPTION_KEY missing');

  // Use HMAC with the encryption key as the secret to ensure the hash is unforgeable 
  // and deterministic for the same input.
  return crypto
    .createHmac('sha256', encryptionKey)
    .update(String(text).trim())
    .digest('hex');
}

/**
 * Calculates the distance between two points on Earth using the Haversine formula.
 * @param {number} lat1 Latitude of point 1
 * @param {number} lon1 Longitude of point 1
 * @param {number} lat2 Latitude of point 2
 * @param {number} lon2 Longitude of point 2
 * @returns {number} Distance in meters
 */
export function getHaversineDistance(lat1, lon1, lat2, lon2) {
  const R = 6371e3; // Earth's radius in meters
  const p1 = (lat1 * Math.PI) / 180;
  const p2 = (lat2 * Math.PI) / 180;
  const deltaP = ((lat2 - lat1) * Math.PI) / 180;
  const deltaL = ((lon2 - lon1) * Math.PI) / 180;

  const a =
    Math.sin(deltaP / 2) * Math.sin(deltaP / 2) +
    Math.cos(p1) * Math.cos(p2) * Math.sin(deltaL / 2) * Math.sin(deltaL / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  return R * c;
}

/**
 * Validates if a student is within the allowed radius of the faculty.
 * @param {number} facLat Faculty Latitude
 * @param {number} facLon Faculty Longitude
 * @param {number} studLat Student Latitude
 * @param {number} studLon Student Longitude
 * @param {number} radius Allowed radius in meters (default 50m)
 * @returns {boolean}
 */
export function isWithinRange(facLat, facLon, studLat, studLon, radius = 50) {
  const distance = getHaversineDistance(facLat, facLon, studLat, studLon);
  const ok = distance <= radius;
  if (!ok) {
    console.log(`[Geo] Out of range: ${distance.toFixed(2)}m (Max: ${radius}m). Faculty: ${facLat},${facLon}. Student: ${studLat},${studLon}`);
  }
  return ok;
}

import EmailProvider from './EmailProvider';
import { getBreaker } from '@/lib/utils/CircuitBreaker';

export default class BrevoEmailProvider extends EmailProvider {
  constructor(apiKey, senderEmail) {
    super();
    this.apiKey = apiKey;
    this.senderEmail = senderEmail;
    this.breaker = getBreaker('BrevoEmail');
  }

  async send({ to, subject, html, text }) {
    return await this.breaker.execute(async () => {
      if (!this.apiKey || !this.senderEmail) {
        console.error('[EMAIL_ERROR] Brevo API key or Sender Email missing.');
        return { success: false, message: 'Email service not configured.' };
      }

      try {
        const payload = {
          sender: { email: this.senderEmail, name: 'KUCET College Portal' },
          to: [{ email: to }],
          subject,
          htmlContent: html,
          textContent: text || undefined
        };

        const response = await fetch('https://api.brevo.com/v3/smtp/email', {
          method: 'POST',
          headers: {
            accept: 'application/json',
            'api-key': this.apiKey,
            'content-type': 'application/json'
          },
          body: JSON.stringify(payload)
        });

        const data = await response.json();

        if (response.ok) {
          console.log('[EMAIL_SUCCESS] Message sent via Brevo API.');
          return { success: true, message: 'Email sent successfully.' };
        } else {
          console.error('[EMAIL_FAILURE] Brevo API error:', data);
          return { success: false, message: data.message || 'Failed to send email via Brevo.' };
        }
      } catch (error) {
        console.error('[EMAIL_EXCEPTION] Error calling Brevo API:', error);
        return { success: false, message: 'Internal error connecting to email service.' };
      }
    });
  }
}

